def free_slots(calendars, window):
    lo, hi = window
    if lo >= hi:
        return []
    busy = []
    for cal in calendars:
        for block in cal:
            s, e = block
            s = max(s, lo)
            e = min(e, hi)
            if s < e:
                busy.append((s, e))
    busy.sort()
    out = []
    cur = lo
    for s, e in busy:
        if s > cur:
            out.append([cur, s])
        if e > cur:
            cur = e
    if cur < hi:
        out.append([cur, hi])
    return out
```

