def split_shell_args(s):
    out, cur, i, n, inword = [], [], 0, len(s), False
    while i < n:
        c = s[i]
        if c in " \t":
            if inword:
                out.append("".join(cur))
                cur, inword = [], False
            i += 1
            continue
        if c == "'":
            inword = True
            i += 1
            j = s.find("'", i)
            if j < 0:
                raise ValueError("unterminated single quote")
            cur.append(s[i:j])
            i = j + 1
            continue
        if c == '"':
            inword = True
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                if s[i] == '"':
                    i += 1
                    break
                if s[i] == "\\" and i + 1 < n and s[i + 1] in '"\\$`':
                    cur.append(s[i + 1])
                    i += 2
                else:
                    cur.append(s[i])
                    i += 1
            continue
        if c == "\\":
            inword = True
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            cur.append(s[i + 1])
            i += 2
            continue
        inword = True
        cur.append(c)
        i += 1
    if inword:
        out.append("".join(cur))
    return out
