def parse_csv(text, delimiter=","):
    rows, row, field, inq, i, n = [], [], [], False, 0, len(text)
    while i < n:
        c = text[i]
        if inq:
            if c == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                else:
                    inq = False
                    i += 1
            else:
                field.append(c)
                i += 1
            continue
        if c == '"':
            inq = True
            i += 1
        elif c == delimiter:
            row.append("".join(field))
            field = []
            i += 1
        elif c == "\r" and i + 1 < n and text[i + 1] == "\n":
            row.append("".join(field))
            rows.append(row)
            row, field = [], []
            i += 2
        elif c == "\n":
            row.append("".join(field))
            rows.append(row)
            row, field = [], []
            i += 1
        else:
            field.append(c)
            i += 1
    if field or row:
        row.append("".join(field))
        rows.append(row)
    return rows
