function chunkBySize(items, maxBytes, sizeOf) {
  const out = [];
  let cur = [];
  let curSize = 0;
  for (const item of items) {
    const s = sizeOf(item);
    if (cur.length > 0 && curSize + s > maxBytes) {
      out.push(cur);
      cur = [];
      curSize = 0;
    }
    cur.push(item);
    curSize += s;
  }
  if (cur.length > 0) out.push(cur);
  return out;
}
