function dedupeByKey(records, keyFn) {
  const seen = new Set();
  const kept = [];
  let dropped = 0;
  for (const rec of records) {
    const k = keyFn(rec);
    if (seen.has(k)) {
      dropped += 1;
      continue;
    }
    seen.add(k);
    kept.push(rec);
  }
  return { kept, dropped };
}
```

