def bounded_knapsack(items, capacity):
    if capacity <= 0:
        return 0
    dp = [0] * (capacity + 1)
    for weight, value, count in items:
        if weight <= 0 or value <= 0 or count <= 0:
            continue
        chunk = 1
        remaining = count
        while remaining > 0:
            take = min(chunk, remaining)
            w = weight * take
            v = value * take
            if w <= capacity:
                for cap in range(capacity, w - 1, -1):
                    candidate = dp[cap - w] + v
                    if candidate > dp[cap]:
                        dp[cap] = candidate
            remaining -= take
            chunk *= 2
    return dp[capacity]
```

