def palindrome_cuts(s):
    n = len(s)
    if n <= 1:
        return 0
    is_pal = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if s[i] == s[j] and (j - i < 2 or is_pal[i + 1][j - 1]):
                is_pal[i][j] = True
    cuts = [0] * n
    for end in range(n):
        if is_pal[0][end]:
            cuts[end] = 0
            continue
        best = end
        for start in range(end, 0, -1):
            if is_pal[start][end]:
                best = min(best, cuts[start - 1] + 1)
        cuts[end] = best
    return cuts[-1]
```

