def safe_int(text, default=None):
    if not isinstance(text, str):
        return default
    body = text.strip()
    if not body:
        return default
    sign = ""
    if body[0] == "+" or body[0] == "-":
        sign = body[0]
        body = body[1:]
    if not body:
        return default
    for ch in body:
        if not ("0" <= ch <= "9"):
            return default
    return int(sign + body)
