def dedupe_adjacent(items, max_repeats=1):
    if max_repeats < 1:
        raise ValueError("max_repeats must be at least 1")
    out = []
    run = 0
    previous = object()
    for item in items:
        if run and item == previous:
            run += 1
        else:
            run = 1
        previous = item
        if run <= max_repeats:
            out.append(item)
    return out
