"""Greedy word wrapping."""


def wrap(text, width):
    """Break `text` into lines of at most `width` characters."""
    if width <= 0:
        raise ValueError("width must be positive")
    words = text.split()
    lines = []
    current = ""
    for word in words:
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""
            lines.append(word)
            continue
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current = current + " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines

