class Trie:
    def __init__(self):
        self.root = {}

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = node.get("$", 0) + 1

    def _walk(self, prefix):
        node = self.root
        for ch in prefix:
            node = node.get(ch)
            if node is None:
                return None
        return node

    def search(self, word):
        node = self._walk(word)
        return bool(node) and node.get("$", 0) > 0

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

    def count_prefix(self, prefix):
        node = self._walk(prefix)
        if node is None:
            return 0
        total = 0
        stack = [node]
        while stack:
            current = stack.pop()
            total += current.get("$", 0)
            for key, child in current.items():
                if key != "$":
                    stack.append(child)
        return total
```

