  if (n === 1) return matrix[0][0];
  let total = 0;
  for (let col = 0; col < n; col++) {
    const minor = [];
    for (let r = 1; r < n; r++) {
      const row = [];
      for (let c = 0; c < n; c++) {
        if (c !== col) row.push(matrix[r][c]);
      }
      minor.push(row);
