```typescript
class Stack<T> {
  private items: T[] = [];
  private count = 0;

  push(value: T): void {
    this.items[this.count] = value;
    this.count += 1;
  }

  pop(): T {
    if (this.count === 0) throw new RangeError('empty stack');
    this.count -= 1;
    const value = this.items[this.count];
    this.items.length = this.count;
    return value;
  }

  peek(): T {
    if (this.count === 0) throw new RangeError('empty stack');
    return this.items[this.count - 1];
  }

  size(): number {
    return this.count;
  }

  isEmpty(): boolean {
    return this.count === 0;
  }
}
