class StackQueue:
    def __init__(self):
        self.inbox = []
        self.outbox = []

    def enqueue(self, value):
        self.inbox.append(value)

    def _shift(self):
        if not self.outbox:
            while self.inbox:
                self.outbox.append(self.inbox.pop())

    def dequeue(self):
        self._shift()
        if not self.outbox:
            raise ValueError("empty queue")
        return self.outbox.pop()

    def peek(self):
        self._shift()
        if not self.outbox:
            raise ValueError("empty queue")
        return self.outbox[-1]

    def __len__(self):
        return len(self.inbox) + len(self.outbox)
