class Counter {
  constructor(start = 0) {
    this.current = start;
    this.past = [start];
  }

  increment(by = 1) {
    this.current += by;
    if (by !== 0) this.past.push(this.current);
    return this.current;
  }

  value() {
    return this.current;
  }

  history() {
    return [...this.past];
  }

  undo() {
    if (this.past.length <= 1) return false;
    this.past.pop();
    this.current = this.past[this.past.length - 1];
    return true;
  }
}
```

