#include <string>
#include <vector>

bool brackets_balanced(const std::string& text) {
    std::vector<char> stack;
    for (char ch : text) {
        if (ch == '(' || ch == '[' || ch == '{') {
            stack.push_back(ch);
            continue;
        }
        char expected = 0;
        if (ch == ')') expected = '(';
        else if (ch == ']') expected = '[';
        else if (ch == '}') expected = '{';
        else continue;
        if (stack.empty() || stack.back() != expected) return false;
        stack.pop_back();
    }
    return stack.empty();
}
