```python
class MinStack:
    def __init__(self):
        self.items = []
        self.mins = []

    def push(self, value):
        self.items.append(value)
        if not self.mins or value <= self.mins[-1]:
            self.mins.append(value)

    def pop(self):
        if not self.items:
            raise ValueError("empty stack")
        value = self.items.pop()
        if self.mins and self.mins[-1] == value:
            self.mins.pop()
        return value

    def top(self):
        if not self.items:
            raise ValueError("empty stack")
        return self.items[-1]

    def minimum(self):
        if not self.mins:
            raise ValueError("empty stack")
        return self.mins[-1]
```

