```cpp
int longest_zero_run(int value) {
    if (value < 0) return 0;
    int digits = 1;
    int probe = value;
    while (probe > 1) {
        probe >>= 1;
        ++digits;
    }
    int best = 0;
    int current = 0;
    for (int bit = 0; bit < digits; ++bit) {
        if (((value >> bit) & 1) == 0) {
            ++current;
            if (current > best) best = current;
        } else {
            current = 0;
        }
    }
    return best;
}
```

