def schedule_retries(max_attempts, first_ms, num, den, cap_ms, budget_ms):
    if not isinstance(max_attempts, int) or max_attempts < 1:
        raise ValueError("max_attempts must be a positive integer")
    if num <= 0 or den <= 0:
        raise ValueError("num and den must be positive")
    if first_ms < 0 or cap_ms < 0 or budget_ms < 0:
        raise ValueError("delays and budget must be non-negative")
    delays = []
    spent = 0
    delay = min(cap_ms, first_ms)
    for _ in range(max_attempts - 1):
        if spent + delay > budget_ms:
            break
        delays.append(delay)
        spent += delay
        delay = min(cap_ms, delay * num // den)
    return delays
