def _build(words):
    root = {}
    for word in words:
        node = root
        node["#"] = node.get("#", 0) + 1
        for ch in word:
            node = node.setdefault(ch, {})
            node["#"] = node.get("#", 0) + 1
        node["$"] = node.get("$", 0) + 1
    return root


def _closure(mask, pattern):
    width = len(pattern)
    pending = True
    while pending:
        pending = False
        rest = mask
        while rest:
            low = rest & -rest
            rest ^= low
            index = low.bit_length() - 1
            if index < width and pattern[index] == "*" and not (mask >> (index + 1)) & 1:
                mask |= 1 << (index + 1)
                pending = True
    return mask


def _step(mask, pattern, ch):
    width = len(pattern)
    nxt = 0
    rest = mask
    while rest:
        low = rest & -rest
        rest ^= low
        index = low.bit_length() - 1
        if index >= width:
            continue
        piece = pattern[index]
        if piece == "*":
            nxt |= 1 << index
        elif piece == "?" or piece == ch:
            nxt |= 1 << (index + 1)
    if not nxt:
        return 0
    return _closure(nxt, pattern)


def _walk(node, mask, pattern):
    total = node.get("$", 0) if (mask >> len(pattern)) & 1 else 0
    for name, child in node.items():
        if name == "#" or name == "$":
            continue
        nxt = _step(mask, pattern, name)
        if nxt:
            total += _walk(child, nxt, pattern)
    return total


def count_matching(words, patterns):
    root = _build(words)
    answers = []
    for pattern in patterns:
        start = _closure(1, pattern)
        answers.append(_walk(root, start, pattern))
    return answers
