def _tail(chunks, count):
    parts = []
    need = count
    for piece in reversed(chunks):
        if need <= 0:
            break
        if len(piece) <= need:
            parts.append(piece)
            need -= len(piece)
        else:
            parts.append(piece[len(piece) - need:])
            need = 0
    return "".join(reversed(parts))


def decode_pack(text):
    chunks = []
    size = 0
    index = 0
    while index < len(text):
        ch = text[index]
        if ch == "\\":
            if index + 1 >= len(text):
                raise ValueError("dangling escape")
            chunks.append(text[index + 1])
            size += 1
            index += 2
            continue
        if "0" <= ch <= "9":
            start = index
            while index < len(text) and "0" <= text[index] <= "9":
                index += 1
            if index >= len(text):
                raise ValueError("run without a character")
            count = int(text[start:index])
            if count > 1000000:
                raise ValueError("run too long")
            piece = text[index] * count
            chunks.append(piece)
            size += count
            index += 1
            continue
        if ch == "(":
            close = text.find(")", index + 1)
            if close == -1:
                raise ValueError("unterminated reference")
            body = text[index + 1:close]
            if not body or not body.isdigit() or not body.isascii():
                raise ValueError("bad reference")
            count = int(body)
            if count < 1 or count > 65535 or count > size:
                raise ValueError("reference out of range")
            piece = _tail(chunks, count)
            chunks.append(piece)
            size += count
            index = close + 1
            continue
        chunks.append(ch)
        size += 1
        index += 1
    return "".join(chunks)
