std::string decode_instruction(uint32_t word) {
    unsigned opcode = word & 0x3Fu;
    if (opcode != 0x33u && opcode != 0x13u && opcode != 0x03u) {
        throw std::invalid_argument("bad opcode");
    }
    unsigned rd = (word >> 6) & 0x1Fu;
    unsigned rs1 = (word >> 11) & 0x1Fu;
    unsigned rs2 = (word >> 16) & 0x1Fu;
    unsigned funct3 = (word >> 21) & 0x7u;
    if (funct3 != 0u && funct3 != 1u && funct3 != 2u && funct3 != 4u && funct3 != 6u) {
        throw std::invalid_argument("bad funct3");
    }
    unsigned raw = (word >> 24) & 0xFFu;
    long long immediate = (raw & 0x80u) ? (long long)raw - 256 : (long long)raw;
    return "op=" + std::to_string(opcode) + " rd=" + std::to_string(rd) +
           " rs1=" + std::to_string(rs1) + " rs2=" + std::to_string(rs2) +
           " f3=" + std::to_string(funct3) + " imm=" + std::to_string(immediate);
}
