struct ExprParser {
    const std::string& text;
    size_t pos = 0;

    explicit ExprParser(const std::string& source) : text(source) {}

    void skip() {
        while (pos < text.size() && (text[pos] == ' ' || text[pos] == '\t')) ++pos;
    }

    long long expr() {
        long long value = term();
        while (true) {
            skip();
            if (pos < text.size() && (text[pos] == '+' || text[pos] == '-')) {
                char op = text[pos++];
                long long rhs = term();
                value = (op == '+') ? value + rhs : value - rhs;
            } else {
                return value;
            }
        }
    }

    long long term() {
        long long value = unary();
        while (true) {
            skip();
            if (pos < text.size() && (text[pos] == '*' || text[pos] == '/')) {
                char op = text[pos++];
                long long rhs = unary();
                if (op == '*') {
                    value *= rhs;
                } else {
                    if (rhs == 0) throw std::invalid_argument("division by zero");
                    value /= rhs;
                }
            } else {
                return value;
            }
        }
    }

    long long unary() {
        skip();
        if (pos < text.size() && text[pos] == '-') {
            ++pos;
            return -unary();
        }
        if (pos < text.size() && text[pos] == '+') {
            ++pos;
            return unary();
        }
        return atom();
    }

    long long atom() {
        skip();
        if (pos < text.size() && text[pos] == '(') {
            ++pos;
            long long value = expr();
            skip();
            if (pos >= text.size() || text[pos] != ')') throw std::invalid_argument("unclosed");
            ++pos;
            return value;
        }
        if (pos >= text.size() || !std::isdigit((unsigned char)text[pos])) {
            throw std::invalid_argument("operand expected");
        }
        long long value = 0;
        while (pos < text.size() && std::isdigit((unsigned char)text[pos])) {
            value = value * 10 + (text[pos] - '0');
            ++pos;
        }
        return value;
    }
};

long long eval_expr(const std::string& text) {
    ExprParser parser(text);
    long long value = parser.expr();
    parser.skip();
    if (parser.pos != text.size()) throw std::invalid_argument("trailing garbage");
    return value;
}
