static std::string expand_body(const std::string& text, size_t& pos) {
    std::string out;
    while (pos < text.size() && text[pos] != ']') {
        if (std::isdigit((unsigned char)text[pos])) {
            long long count = 0;
            while (pos < text.size() && std::isdigit((unsigned char)text[pos])) {
                count = count * 10 + (text[pos] - '0');
                if (count > 1000) throw std::invalid_argument("count too large");
                ++pos;
