            if (pos >= text.size() || text[pos] != '[') throw std::invalid_argument("marker needs a bracket");
            ++pos;
            std::string body = expand_body(text, pos);
            if (pos >= text.size() || text[pos] != ']') throw std::invalid_argument("unclosed repeat");
            ++pos;
            for (long long round = 0; round < count; ++round) out += body;
        } else {
            out += text[pos];
            ++pos;
        }
    }
    return out;
}

std::string expand(const std::string& text) {
    size_t pos = 0;
    std::string out = expand_body(text, pos);
    if (pos != text.size()) throw std::invalid_argument("unbalanced brackets");
    return out;
