#include <cassert>
#include <queue>
#include <stdexcept>
#include <vector>

std::vector<int> topo_order(int n, std::vector<std::pair<int, int>> edges) {
    if (n < 0) throw std::invalid_argument("negative node count");
    std::vector<std::vector<int>> next((size_t)n);
    std::vector<int> indegree((size_t)n, 0);
    std::set<std::pair<int, int>> seen;
    for (const auto& edge : edges) {
        int from = edge.first;
        int to = edge.second;
        if (from < 0 || from >= n || to < 0 || to >= n) throw std::invalid_argument("bad node");
        if (!seen.insert({from, to}).second) continue;
        next[(size_t)from].push_back(to);
        indegree[(size_t)to] += 1;
    }
    std::priority_queue<int, std::vector<int>, std::greater<int>> ready;
    for (int node = 0; node < n; ++node) {
        if (indegree[(size_t)node] == 0) ready.push(node);
    }
    std::vector<int> order;
    while (!ready.empty()) {
        int node = ready.top();
        ready.pop();
        order.push_back(node);
        for (int target : next[(size_t)node]) {
            indegree[(size_t)target] -= 1;
            if (indegree[(size_t)target] == 0) ready.push(target);
        }
    }
    if ((int)order.size() != n) return {};
    return order;
}
