std::vector<int> bucket_results(int capacity, int refill_per_second, std::vector<int> times_ms) {
    if (capacity <= 0) throw std::invalid_argument("capacity must be positive");
    if (refill_per_second < 0) throw std::invalid_argument("refill must be non-negative");
    std::vector<int> results;
    long long tokens = capacity;
    long long spare = 0;
    long long last = 0;
    bool started = false;
    for (int stamp : times_ms) {
        if (stamp < 0) throw std::invalid_argument("negative time");
        if (started && stamp < last) throw std::invalid_argument("times must not decrease");
        if (started) {
            long long elapsed = (long long)stamp - last;
            long long gained = elapsed * (long long)refill_per_second + spare;
            tokens += gained / 1000;
            spare = gained % 1000;
            if (tokens > capacity) tokens = capacity;
        }
        started = true;
        last = (long long)stamp;
        if (tokens > 0) {
            tokens -= 1;
            results.push_back(1);
        } else {
            results.push_back(0);
        }
    }
    return results;
}
