#include <cassert>
#include <deque>
#include <stdexcept>
#include <vector>

std::vector<long long> queue_stats(std::vector<int> arrivals, std::vector<int> services, int capacity) {
    if (arrivals.size() != services.size()) throw std::invalid_argument("size mismatch");
    if (capacity < 0) throw std::invalid_argument("negative capacity");
    for (size_t index = 0; index < arrivals.size(); ++index) {
        if (arrivals[index] < 0) throw std::invalid_argument("negative arrival");
        if (services[index] <= 0) throw std::invalid_argument("service must be positive");
        if (index > 0 && arrivals[index] < arrivals[index - 1]) throw std::invalid_argument("arrivals must not decrease");
    }
    std::deque<int> waiting;
    long long served = 0;
    long long dropped = 0;
    long long total_wait = 0;
    long long busy_until = 0;
    long long peak = 0;
    for (size_t index = 0; index < arrivals.size(); ++index) {
        long long now = arrivals[index];
        while (!waiting.empty() && busy_until <= now) {
            long long start = busy_until;
            long long wait = start - (long long)arrivals[(size_t)waiting.front()];
            total_wait += wait;
            busy_until = start + (long long)services[(size_t)waiting.front()];
            waiting.pop_front();
            served += 1;
        }
        if ((long long)waiting.size() >= (long long)capacity) {
            dropped += 1;
            continue;
        }
        waiting.push_back((int)index);
        if ((long long)waiting.size() > peak) peak = (long long)waiting.size();
    }
    while (!waiting.empty()) {
        long long start = busy_until;
        long long wait = start - (long long)arrivals[(size_t)waiting.front()];
        if (wait < 0) wait = 0;
        total_wait += wait;
        busy_until = start + (long long)services[(size_t)waiting.front()];
        waiting.pop_front();
        served += 1;
    }
    return {served, dropped, total_wait, peak};
}
