long long largest_gap(std::vector<std::pair<long long, long long>> ranges, long long lo, long long hi) {
    if (hi <= lo) return 0;
    std::sort(ranges.begin(), ranges.end());
    long long best = 0;
    long long cursor = lo;
    for (const auto& range : ranges) {
        long long start = std::max(range.first, lo);
        long long stop = std::min(range.second, hi);
        if (stop <= start) continue;
        if (start > cursor) best = std::max(best, start - cursor);
        if (stop > cursor) cursor = stop;
    }
    if (cursor < hi) best = std::max(best, hi - cursor);
    return best;
}
