#include <cassert>
#include <stdexcept>
#include <vector>

long long count_sharing_pairs(std::vector<int> values) {
    int limit = 0;
    for (int value : values) {
        if (value <= 0) throw std::invalid_argument("values must be positive");
        if (value > limit) limit = value;
    }
    if (limit < 2) return 0;
    std::vector<long long> multiples((size_t)limit + 1, 0);
    for (int value : values) {
        for (int divisor = 1; divisor * divisor <= value; ++divisor) {
            if (value % divisor != 0) continue;
            multiples[(size_t)divisor] += 1;
            int other = value / divisor;
            if (other != divisor) multiples[(size_t)other] += 1;
        }
    }
    std::vector<long long> exact((size_t)limit + 1, 0);
    long long shared = 0;
    for (int divisor = limit; divisor >= 2; --divisor) {
        long long count = multiples[(size_t)divisor];
        long long pairs = count * (count - 1) / 2;
        for (long long step = (long long)divisor * 2; step <= limit; step += divisor) {
            pairs -= exact[(size_t)step];
        }
        exact[(size_t)divisor] = pairs;
        shared += pairs;
    }
    return shared;
}
