from .core import page_slice


def total_pages(total, size):
    """How many pages the collection needs."""
    if total == 0:
        return 0
    return -(-total // size)


def envelope(items, page, size):
    """A paged envelope for the items."""
    total = len(items)
    pages = total_pages(total, size)
    start, stop = page_slice(total, page, size)
    return {
        "items": items[start:stop],
        "page": page,
        "pages": pages,
        "has_next": page < pages,
        "has_prev": page > 1 and pages > 0,
