def in_range(version, low, high):
    """Whether low <= version < high, comparing numerically."""
    parts = _pad(parse(version))
    low_parts = _pad(parse(low))
    high_parts = _pad(parse(high))
    return tuple(low_parts) <= tuple(parts) < tuple(high_parts)

