type Listener = { fn: (value: any) => void; once: boolean };

class EventEmitter {
  private handlers: Map<string, Listener[]> = new Map();

  private list(name: string): Listener[] {
    const existing = this.handlers.get(name);
    if (existing) return existing;
    const created: Listener[] = [];
    this.handlers.set(name, created);
    return created;
  }

  on(name: string, fn: (value: any) => void): void {
    this.list(name).push({ fn, once: false });
  }

  once(name: string, fn: (value: any) => void): void {
    this.list(name).push({ fn, once: true });
  }

  off(name: string, fn: (value: any) => void): void {
    const listeners = this.list(name);
    for (let index = listeners.length - 1; index >= 0; index -= 1) {
      if (listeners[index].fn === fn) {
        listeners.splice(index, 1);
        return;
      }
    }
  }

  emit(name: string, value: any): number {
    const snapshot = [...this.list(name)];
    let ran = 0;
    for (const listener of snapshot) {
      if (listener.once) this.off(name, listener.fn);
      listener.fn(value);
      ran += 1;
    }
    return ran;
  }

  count(name: string): number {
    return this.list(name).length;
  }
}
