function isPlainObject(value: any): boolean {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function cloneValue(value: any): any {
  if (Array.isArray(value)) return value.map((item) => cloneValue(item));
  if (isPlainObject(value)) {
    const result: Record<string, any> = {};
    for (const key of Object.keys(value)) result[key] = cloneValue(value[key]);
    return result;
  }
  return value;
}

function deepMerge(left: any, right: any): any {
  if (Array.isArray(left) && Array.isArray(right)) {
    return [...cloneValue(left), ...cloneValue(right)];
  }
  if (isPlainObject(left) && isPlainObject(right)) {
    const result: Record<string, any> = cloneValue(left);
    for (const key of Object.keys(right)) {
      result[key] = Object.prototype.hasOwnProperty.call(left, key)
        ? deepMerge(left[key], right[key])
        : cloneValue(right[key]);
    }
    return result;
  }
  return cloneValue(right);
}
