function diffSequences(left: string[], right: string[]): string[][] {
  const rows = left.length;
  const cols = right.length;
  const table: number[][] = [];
  for (let row = 0; row <= rows; row += 1) {
    table.push(new Array(cols + 1).fill(0));
  }
  for (let row = rows - 1; row >= 0; row -= 1) {
    for (let col = cols - 1; col >= 0; col -= 1) {
      table[row][col] = left[row] === right[col]
        ? table[row + 1][col + 1] + 1
        : Math.max(table[row + 1][col], table[row][col + 1]);
    }
  }
  const script: string[][] = [];
  let row = 0;
  let col = 0;
  while (row < rows && col < cols) {
    if (left[row] === right[col]) {
      script.push(['keep', left[row]]);
      row += 1;
      col += 1;
    } else if (table[row + 1][col] >= table[row][col + 1]) {
      script.push(['del', left[row]]);
      row += 1;
    } else {
      script.push(['ins', right[col]]);
      col += 1;
    }
  }
  while (row < rows) {
    script.push(['del', left[row]]);
    row += 1;
  }
  while (col < cols) {
    script.push(['ins', right[col]]);
    col += 1;
  }
  return script;
}
