function globMatch(pattern: string, path: string): boolean {
  const patternLength = pattern.length;
  const pathLength = path.length;
  const memo = new Map<string, boolean>();

  function walk(patternIndex: number, pathIndex: number): boolean {
    const key = patternIndex + ':' + pathIndex;
    const cached = memo.get(key);
    if (cached !== undefined) return cached;
    let answer: boolean;
    if (patternIndex === patternLength) {
      answer = pathIndex === pathLength;
    } else if (pattern[patternIndex] === '*') {
      const double = pattern[patternIndex + 1] === '*';
      const nextIndex = double ? patternIndex + 2 : patternIndex + 1;
      if (double && pattern[nextIndex] === '/') {
        answer = walk(nextIndex + 1, pathIndex) || (pathIndex < pathLength && walk(patternIndex, pathIndex + 1));
      } else if (double) {
        answer = walk(nextIndex, pathIndex) || (pathIndex < pathLength && walk(patternIndex, pathIndex + 1));
      } else {
        answer = walk(nextIndex, pathIndex);
        let cursor = pathIndex;
        while (!answer && cursor < pathLength && path[cursor] !== '/') {
          cursor += 1;
          answer = walk(nextIndex, cursor);
        }
      }
    } else if (pathIndex < pathLength) {
      const expected = pattern[patternIndex];
      const actual = path[pathIndex];
      const literal = expected === '?' ? actual !== '/' : expected === actual;
      answer = literal && walk(patternIndex + 1, pathIndex + 1);
    } else {
      answer = false;
    }
    memo.set(key, answer);
    return answer;
  }

  return walk(0, 0);
}
