function dayNumber(iso: string): number {
  const parts = iso.split('-').map(Number);
  return Math.floor(Date.UTC(parts[0], parts[1] - 1, parts[2]) / 86400000);
}

function isoOf(number: number): string {
  return new Date(number * 86400000).toISOString().slice(0, 10);
}

function weekdayOf(number: number): number {
  return (((number + 4) % 7) + 7) % 7;
}

function addBusinessDays(start: string, count: number, holidays: string[] = []): string {
  if (count === 0) return start;
  const blocked = new Set(holidays);
  const step = count < 0 ? -1 : 1;
  let remaining = Math.abs(count);
  let current = dayNumber(start);
  while (remaining > 0) {
    current += step;
    const weekday = weekdayOf(current);
    if (weekday === 0 || weekday === 6) continue;
    if (blocked.has(isoOf(current))) continue;
    remaining -= 1;
  }
  return isoOf(current);
}
