class Editor {
  private past: string[] = [];
  private future: string[] = [];
  private state: string;

  constructor(start: string = '') {
    this.state = start;
  }

  apply(next: string): void {
    this.past.push(this.state);
    this.state = next;
    this.future = [];
  }

  undo(): string {
    if (this.past.length === 0) return this.state;
    this.future.push(this.state);
    this.state = this.past.pop() as string;
    return this.state;
  }

  redo(): string {
    if (this.future.length === 0) return this.state;
    this.past.push(this.state);
    this.state = this.future.pop() as string;
    return this.state;
  }

  text(): string {
    return this.state;
  }

  history(): string[] {
    return [...this.past];
  }
}
