function encodeCursor(id: number, createdAt: number): string {
  return Buffer.from(id + ':' + createdAt, 'utf8').toString('base64');
}

function decodeCursor(cursor: string): { id: number; createdAt: number } | null {
  let text: string;
  try {
    text = Buffer.from(cursor, 'base64').toString('utf8');
  } catch (error) {
    return null;
  }
  const parts = text.split(':');
  if (parts.length !== 2) return null;
  if (!/^\d+$/.test(parts[0]) || !/^\d+$/.test(parts[1])) return null;
  return { id: Number(parts[0]), createdAt: Number(parts[1]) };
}

function pageAfter(
  rows: Array<{ id: number; createdAt: number }>,
  cursor: string | null,
  size: number,
): Array<{ id: number; createdAt: number }> {
  if (!Number.isInteger(size) || size < 1) throw new Error('size must be a positive integer');
  const position = cursor === null ? null : decodeCursor(cursor);
  if (cursor !== null && position === null) throw new Error('invalid cursor');
  const sorted = [...rows].sort((a, b) => a.createdAt - b.createdAt || a.id - b.id);
  const remaining = position === null
    ? sorted
    : sorted.filter((row) => row.createdAt > position.createdAt || (row.createdAt === position.createdAt && row.id > position.id));
  return remaining.slice(0, size);
}
