function runsOf(text: string): string[] {
  const runs: string[] = [];
  let index = 0;
  while (index < text.length) {
    const digit = text[index] >= '0' && text[index] <= '9';
    let cursor = index;
    while (cursor < text.length) {
      const same = (text[cursor] >= '0' && text[cursor] <= '9') === digit;
      if (!same) break;
      cursor += 1;
    }
    runs.push(text.slice(index, cursor));
    index = cursor;
  }
  return runs;
}

function compareRuns(left: string, right: string): number {
  const leftDigit = left[0] >= '0' && left[0] <= '9';
  const rightDigit = right[0] >= '0' && right[0] <= '9';
  if (leftDigit && rightDigit) {
    const a = left.replace(/^0+(?=\d)/, '');
    const b = right.replace(/^0+(?=\d)/, '');
    if (a.length !== b.length) return a.length < b.length ? -1 : 1;
    if (a !== b) return a < b ? -1 : 1;
    return 0;
  }
  if (leftDigit) return -1;
  if (rightDigit) return 1;
  const a = left.toLowerCase();
  const b = right.toLowerCase();
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

function compareLabels(left: string, right: string): number {
  const a = runsOf(left);
  const b = runsOf(right);
  const width = Math.min(a.length, b.length);
  for (let index = 0; index < width; index += 1) {
    const order = compareRuns(a[index], b[index]);
    if (order !== 0) return order;
  }
  if (a.length === b.length) return 0;
  return a.length < b.length ? -1 : 1;
}

function naturalSort(items: string[]): string[] {
  return items
    .map((item, index) => ({ item, index }))
    .sort((a, b) => compareLabels(a.item, b.item) || a.index - b.index)
    .map((entry) => entry.item);
}
