class Node {
  children: Map<string, Node> = new Map();
  words: Map<string, number> = new Map();
}

function insert(root: Node, word: string): void {
  let node = root;
  const current = node.words.get(word) ?? 0;
  node.words.set(word, current + 1);
  for (const ch of word) {
    const next = node.children.get(ch);
    if (next) {
      node = next;
    } else {
      const created = new Node();
      node.children.set(ch, created);
      node = created;
    }
    const seen = node.words.get(word) ?? 0;
    node.words.set(word, seen + 1);
  }
}

function suggest(words: string[], prefix: string, limit: number): string[] {
  if (!Number.isInteger(limit) || limit < 1) return [];
  const root = new Node();
  for (const word of words) insert(root, word);
  let node = root;
  for (const ch of prefix) {
    const next = node.children.get(ch);
    if (!next) return [];
    node = next;
  }
  const ranked = [...node.words.entries()].sort((a, b) => {
    if (a[1] !== b[1]) return b[1] - a[1];
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0;
  });
  return ranked.slice(0, limit).map((entry) => entry[0]);
}
