class StableHeap {
  constructor() {
    this.items = [];
    this.sequence = 0;
  }

  before(left, right) {
    if (left.priority !== right.priority) return left.priority < right.priority;
    return left.sequence < right.sequence;
  }

  push(priority, label) {
    this.items.push({ priority, label, sequence: this.sequence++ });
    let index = this.items.length - 1;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (!this.before(this.items[index], this.items[parent])) break;
      [this.items[index], this.items[parent]] = [this.items[parent], this.items[index]];
      index = parent;
    }
  }

  pop() {
    if (this.items.length === 0) return null;
    const top = this.items[0];
    const last = this.items.pop();
    if (this.items.length > 0) {
      this.items[0] = last;
      let index = 0;
      while (true) {
        const left = index * 2 + 1;
        const right = left + 1;
        let best = index;
        if (left < this.items.length && this.before(this.items[left], this.items[best])) best = left;
        if (right < this.items.length && this.before(this.items[right], this.items[best])) best = right;
        if (best === index) break;
        [this.items[index], this.items[best]] = [this.items[best], this.items[index]];
        index = best;
      }
    }
    return top.label;
  }

  peek() {
    return this.items.length === 0 ? null : this.items[0].label;
  }

  size() {
    return this.items.length;
  }

  drain() {
    const out = [];
    while (this.items.length > 0) out.push(this.pop());
    return out;
  }
}
