function bestSchedule(jobs) {
  const items = jobs
    .filter((job) => job[2] > 0)
    .map((job) => [job[0], job[1], job[2]])
    .sort((a, b) => a[1] - b[1] || a[0] - b[0]);
  const count = items.length;
  if (count === 0) return 0;
  const ends = items.map((job) => job[1]);
  const best = new Array(count).fill(0);

  function latestBefore(start) {
    let low = 0;
    let high = count - 1;
    let answer = -1;
    while (low <= high) {
      const middle = (low + high) >> 1;
      if (ends[middle] <= start) {
        answer = middle;
        low = middle + 1;
      } else {
        high = middle - 1;
      }
    }
    return answer;
  }

  for (let index = 0; index < count; index += 1) {
    const previous = latestBefore(items[index][0]);
    const withJob = items[index][2] + (previous >= 0 ? best[previous] : 0);
    const withoutJob = index > 0 ? best[index - 1] : 0;
    best[index] = Math.max(withJob, withoutJob);
  }
  return best[count - 1];
}
