function cheapestPath(grid) {
  const rows = grid.length;
  if (rows === 0) return -1;
  const cols = grid[0].length;
  if (cols === 0) return -1;
  const best = grid.map((row) => row.map(() => Infinity));
  const queue = [];
  let head = 0;
  best[0][0] = 0;
  queue.push([0, 0]);
  while (head < queue.length) {
    const [row, col] = queue[head++];
    const cost = best[row][col];
    const moves = [[row - 1, col], [row + 1, col], [row, col - 1], [row, col + 1]];
    for (const [nextRow, nextCol] of moves) {
      if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) continue;
      const step = grid[nextRow][nextCol];
      if (cost + step < best[nextRow][nextCol]) {
        best[nextRow][nextCol] = cost + step;
        if (step === 0) {
          queue.splice(head, 0, [nextRow, nextCol]);
        } else {
          queue.push([nextRow, nextCol]);
        }
      }
    }
  }
  return best[rows - 1][cols - 1] === Infinity ? -1 : best[rows - 1][cols - 1];
}
