function runRobot(width, height, obstacles, commands) {
  const blocked = new Set(obstacles);
  const steps = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  let facing = 0;
  let x = 0;
  let y = 0;
  const seen = new Set(['0,0']);
  let index = 0;
  while (index < commands.length) {
    let repeats = 1;
    if (commands[index] >= '1' && commands[index] <= '9') {
      repeats = Number(commands[index]);
      index += 1;
    }
    const command = commands[index];
    index += 1;
    if (command === undefined) throw new Error('dangling repeat count');
    for (let round = 0; round < repeats; round += 1) {
      if (command === 'L') {
        facing = (facing + 3) % 4;
      } else if (command === 'R') {
        facing = (facing + 1) % 4;
      } else if (command === 'M') {
        const nextX = x + steps[facing][0];
        const nextY = y + steps[facing][1];
        if (nextX < 0 || nextX >= width || nextY < 0 || nextY >= height) continue;
        if (blocked.has(nextX + ',' + nextY)) continue;
        x = nextX;
        y = nextY;
        seen.add(x + ',' + y);
      } else {
        throw new Error('unknown command: ' + command);
      }
    }
  }
  return { x, y, visited: seen.size };
}
