const UNITS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
  'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
const TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];

function underHundred(value) {
  if (value < 20) return UNITS[value];
  const tens = Math.floor(value / 10);
  const rest = value % 10;
  return rest === 0 ? TENS[tens] : TENS[tens] + '-' + UNITS[rest];
}

function underThousand(value) {
  if (value < 100) return underHundred(value);
  const hundreds = Math.floor(value / 100);
  const rest = value % 100;
  return rest === 0 ? UNITS[hundreds] + ' hundred' : UNITS[hundreds] + ' hundred ' + underHundred(rest);
}

function numberToWords(value) {
  if (!Number.isInteger(value)) throw new Error('value must be an integer');
  if (Math.abs(value) >= 1000000000) throw new Error('value is out of range');
  if (value === 0) return 'zero';
  const negative = value < 0;
  let rest = Math.abs(value);
  const parts = [];
  const groups = [[1000000, 'million'], [1000, 'thousand'], [1, '']];
  for (const [size, name] of groups) {
    const chunk = Math.floor(rest / size);
    rest -= chunk * size;
    if (chunk === 0) continue;
    parts.push(underThousand(chunk) + (name === '' ? '' : ' ' + name));
  }
  const text = parts.join(' ');
  return negative ? 'minus ' + text : text;
}
