def serialize_tree(tree):
    parts = []

    def visit(node):
        if node is None:
            parts.append("#")
            return
        if not isinstance(node, list) or len(node) != 3:
            raise ValueError("node must be [value, left, right]")
        parts.append(str(node[0]))
        visit(node[1])
        visit(node[2])

    visit(tree)
