def deserialize_tree(text):
    if not isinstance(text, str) or text == "":
        raise ValueError("text must not be empty")
    tokens = text.split(",")
    position = 0

    def build():
        nonlocal position
        if position >= len(tokens):
            raise ValueError("unexpected end of text")
        token = tokens[position]
        position += 1
        if token == "#":
            return None
        try:
            value = int(token)
        except ValueError:
            raise ValueError("bad token %r" % (token,))
        left = build()
        right = build()
        return [value, left, right]

    tree = build()
    if position != len(tokens):
        raise ValueError("trailing tokens")
    return tree
