import heapq


def merge_streams(streams, limit):
    if limit < 0:
        raise ValueError("limit must be non-negative")
    heap = []
    for index, stream in enumerate(streams):
        for position in range(1, len(stream)):
            if stream[position] < stream[position - 1]:
                raise ValueError("stream %d is not sorted" % (index,))
        if stream:
            heap.append((stream[0], index, 0))
    heapq.heapify(heap)
    merged = []
    previous = None
    while heap and len(merged) < limit:
        value, index, position = heapq.heappop(heap)
        if not merged or value != previous:
            merged.append(value)
            previous = value
        position += 1
        if position < len(streams[index]):
            heapq.heappush(heap, (streams[index][position], index, position))
    return merged
