def normalize_url(url):
    if not isinstance(url, str) or "://" not in url:
        raise ValueError("url must be absolute")
    scheme, _, rest = url.partition("://")
    scheme = scheme.lower()
    if scheme not in ("http", "https"):
        raise ValueError("unsupported scheme: %r" % (scheme,))
    rest = rest.split("#", 1)[0]
    authority, _, tail = rest.partition("/")
    path, _, query = tail.partition("?")
    host, _, port_text = authority.partition(":")
    host = host.lower()
    if not host:
        raise ValueError("host is required")
    if port_text:
        if not port_text.isdigit():
            raise ValueError("bad port: %r" % (port_text,))
        number = int(port_text)
        if number == (80 if scheme == "http" else 443):
            port = ""
        else:
            port = ":" + str(number)
    else:
        port = ""
    kept = []
    for piece in path.split("/"):
        if piece == "" or piece == ".":
            continue
        if piece == "..":
            if kept:
                kept.pop()
            continue
        kept.append(piece)
    trailing = path.endswith("/") and bool(kept)
    cleaned = "/" + "/".join(kept) + ("/" if trailing else "")
    params = []
    for item in query.split("&"):
        if not item:
            continue
        name, _, value = item.partition("=")
        params.append((name, value))
    params.sort()
    text = scheme + "://" + host + port + cleaned
    if params:
        text += "?" + "&".join(name + "=" + value for name, value in params)
    return text
