def trapped_water(widths, heights):
    if len(widths) != len(heights):
        raise ValueError("widths and heights must have the same length")
    if any(width <= 0 for width in widths):
        raise ValueError("widths must be positive")
    if any(height < 0 for height in heights):
        raise ValueError("heights must be non-negative")
    count = len(heights)
    left = [0] * count
    right = [0] * count
    best = 0
    for index in range(count):
        best = max(best, heights[index])
        left[index] = best
    best = 0
    for index in range(count - 1, -1, -1):
        best = max(best, heights[index])
        right[index] = best
    volume = 0
    for index in range(count):
        level = min(left[index], right[index])
        if level > heights[index]:
            volume += (level - heights[index]) * widths[index]
    return volume
