def reconcile(book, bank, tolerance):
    if tolerance < 0:
        raise ValueError("tolerance must be non-negative")
    candidates = []
    for book_index, (reference, amount) in enumerate(book):
        for bank_index, other in enumerate(bank):
            difference = abs(amount - other)
            if difference <= tolerance:
                candidates.append((difference, reference, bank_index, book_index))
    candidates.sort()
    used_book = set()
    used_bank = set()
    for _difference, _reference, bank_index, book_index in candidates:
        if book_index in used_book or bank_index in used_bank:
            continue
        used_book.add(book_index)
        used_bank.add(bank_index)
    unmatched_book = sorted(
        book[index][0] for index in range(len(book)) if index not in used_book
    )
    unmatched_bank = sorted(index for index in range(len(bank)) if index not in used_bank)
    return unmatched_book, unmatched_bank
