from collections import deque


def escape_steps(grid):
    if not grid:
        raise ValueError("grid must not be empty")
    widths = {len(row) for row in grid}
    if len(widths) != 1:
        raise ValueError("rows must have equal length")
    rows = len(grid)
    cols = len(grid[0])
    start = None
    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == "S":
                start = (row, col)
    if start is None:
        raise ValueError("grid needs an S cell")
    if not any("E" in row for row in grid):
        raise ValueError("grid needs an E cell")
    seen = {(start[0], start[1], 0)}
    queue = deque([(start[0], start[1], 0, 0)])
    while queue:
        row, col, mask, steps = queue.popleft()
        for delta_row, delta_col in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            next_row = row + delta_row
            next_col = col + delta_col
            if next_row < 0 or next_row >= rows or next_col < 0 or next_col >= cols:
                continue
            cell = grid[next_row][next_col]
            if cell == "#":
                continue
            if cell == "E":
                return steps + 1
            if "A" <= cell <= "Z" and not mask & (1 << (ord(cell) - ord("A"))):
                continue
            next_mask = mask
            if "a" <= cell <= "z":
                next_mask = mask | (1 << (ord(cell) - ord("a")))
            state = (next_row, next_col, next_mask)
            if state in seen:
                continue
            seen.add(state)
            queue.append((next_row, next_col, next_mask, steps + 1))
    return -1
