def evaluate_with_vars(expression, variables):
    if not isinstance(expression, str) or not expression.strip():
        raise ValueError("expression must not be empty")
    position = 0
    width = len(expression)

    def skip():
        nonlocal position
        while position < width and expression[position] == " ":
            position += 1

    def parse_expression():
        nonlocal position
        value = parse_term()
        while True:
            skip()
            if position < width and expression[position] in "+-":
                operator = expression[position]
                position += 1
                right = parse_term()
                value = value + right if operator == "+" else value - right
            else:
                return value

    def parse_term():
        nonlocal position
        value = parse_unary()
        while True:
            skip()
            if position < width and expression[position] == "*":
                position += 1
                value *= parse_unary()
            else:
                return value

    def parse_unary():
        nonlocal position
        skip()
        if position < width and expression[position] == "-":
            position += 1
            return -parse_unary()
        return parse_atom()

    def parse_atom():
        nonlocal position
        skip()
        if position >= width:
            raise ValueError("operand expected")
        character = expression[position]
        if character == "(":
            position += 1
            value = parse_expression()
            skip()
            if position >= width or expression[position] != ")":
                raise ValueError("unclosed parenthesis")
            position += 1
            return value
        if character.isdigit():
            start = position
            while position < width and expression[position].isdigit():
                position += 1
            return int(expression[start:position])
        if character.isalpha() or character == "_":
            start = position
            while position < width and (expression[position].isalnum() or expression[position] == "_"):
                position += 1
            name = expression[start:position]
            if name not in variables:
                raise ValueError("unknown variable: %r" % (name,))
            return variables[name]
        raise ValueError("unexpected character %r" % (character,))

    result = parse_expression()
    skip()
    if position != width:
        raise ValueError("leftover input")
    return result
