def free_slots(busy, work_start, work_end):
    if work_end <= work_start:
        return []
    clipped = []
    for start, end in busy:
        if end < start:
            raise ValueError("block end must not be before its start")
        left = max(start, work_start)
        right = min(end, work_end)
        if right > left:
            clipped.append((left, right))
    clipped.sort()
    merged = []
    for left, right in clipped:
        if merged and left <= merged[-1][1]:
            if right > merged[-1][1]:
                merged[-1] = (merged[-1][0], right)
        else:
            merged.append((left, right))
    slots = []
    cursor = work_start
    for left, right in merged:
        if left > cursor:
            slots.append((cursor, left))
        cursor = max(cursor, right)
    if cursor < work_end:
        slots.append((cursor, work_end))
    return slots
