def palindromic_subsequences(text):
    modulo = 1000000007
    width = len(text)
    if width == 0:
        return 0
    table = [[0] * width for _ in range(width)]
    for index in range(width):
        table[index][index] = 1
    for length in range(2, width + 1):
        for start in range(0, width - length + 1):
            end = start + length - 1
            if text[start] == text[end]:
                table[start][end] = table[start + 1][end] + table[start][end - 1] + 1
            else:
                table[start][end] = table[start + 1][end] + table[start][end - 1] - table[start + 1][end - 1]
            table[start][end] %= modulo
    return table[0][width - 1] % modulo
