def periods(text):
    width = len(text)
    if width == 0:
        return []
    table = [0] * width
    length = 0
    for index in range(1, width):
        while length > 0 and text[index] != text[length]:
            length = table[length - 1]
        if text[index] == text[length]:
            length += 1
        table[index] = length
    result = []
    candidate = width - table[width - 1]
    if width % candidate == 0:
        result.append(candidate)
    for value in range(1, width + 1):
        if value != candidate and width % value == 0 and all(text[index] == text[index - value] for index in range(value, width)):
            result.append(value)
    result.sort()
    return result
```

