def tax_report(amounts, rate_bp, mode):
    if mode not in ("half_up", "half_even"):
        raise ValueError("unknown rounding mode: %r" % (mode,))

    def rounded(numerator):
        sign = -1 if numerator < 0 else 1
        quotient, remainder = divmod(abs(numerator), 10000)
        doubled = remainder * 2
        if doubled > 10000:
            quotient += 1
        elif doubled == 10000:
            if mode == "half_up":
                quotient += 1
            elif quotient % 2 == 1:
                quotient += 1
        return sign * quotient

    lines = [rounded(amount * rate_bp) for amount in amounts]
    total = rounded(sum(amounts) * rate_bp)
    return {
        "lines": lines,
        "sum_of_lines": sum(lines),
        "on_total": total,
        "difference": sum(lines) - total,
    }
```

