#include <cassert>
#include <stdexcept>
#include <vector>

struct MaxTree {
    int size = 0;
    std::vector<long long> best;
    std::vector<long long> lazy;

    void build(int node, int left, int right, const std::vector<long long>& values) {
        if (left == right) {
            best[(size_t)node] = values[(size_t)left];
            return;
        }
        int middle = (left + right) / 2;
        build(node * 2, left, middle, values);
        build(node * 2 + 1, middle + 1, right, values);
        best[(size_t)node] = std::max(best[(size_t)node * 2], best[(size_t)node * 2 + 1]);
    }

    void push(int node) {
        if (lazy[(size_t)node] == 0) return;
        for (int child = node * 2; child <= node * 2 + 1; ++child) {
            best[(size_t)child] += lazy[(size_t)node];
            lazy[(size_t)child] += lazy[(size_t)node];
        }
        lazy[(size_t)node] = 0;
    }

    void add(int node, int left, int right, int start, int stop, long long delta) {
        if (start <= left && right <= stop) {
            best[(size_t)node] += delta;
            lazy[(size_t)node] += delta;
            return;
        }
        push(node);
        int middle = (left + right) / 2;
        if (start <= middle) add(node * 2, left, middle, start, stop, delta);
        if (stop > middle) add(node * 2 + 1, middle + 1, right, start, stop, delta);
        best[(size_t)node] = std::max(best[(size_t)node * 2], best[(size_t)node * 2 + 1]);
    }

    long long query(int node, int left, int right, int start, int stop) {
        if (start <= left && right <= stop) return best[(size_t)node];
        push(node);
        int middle = (left + right) / 2;
        long long answer = LLONG_MIN;
        if (start <= middle) answer = std::max(answer, query(node * 2, left, middle, start, stop));
        if (stop > middle) answer = std::max(answer, query(node * 2 + 1, middle + 1, right, start, stop));
        return answer;
    }
};

std::vector<long long> range_ops(int n, std::vector<long long> values, std::vector<std::vector<long long>> ops) {
    if (n <= 0 || (int)values.size() != n) throw std::invalid_argument("values must match n");
    MaxTree tree;
    tree.size = n;
    tree.best.assign((size_t)n * 4, 0);
    tree.lazy.assign((size_t)n * 4, 0);
    tree.build(1, 0, n - 1, values);
    std::vector<long long> answers;
    for (const auto& op : ops) {
        if (op.size() < 3) throw std::invalid_argument("operation is incomplete");
        int left = (int)op[1];
        int right = (int)op[2];
        if (left < 0 || right >= n || left > right) throw std::invalid_argument("bad range");
        if (op[0] == 1) {
            if (op.size() != 4) throw std::invalid_argument("add needs a delta");
            tree.add(1, 0, n - 1, left, right, op[3]);
        } else if (op[0] == 2) {
            answers.push_back(tree.query(1, 0, n - 1, left, right));
        } else {
            throw std::invalid_argument("unknown operation");
        }
    }
    return answers;
}
