long long fuel_cost(int n, std::vector<std::tuple<int, int, int>> roads, int start, int target, int capacity, std::vector<int> price) {
    if (capacity <= 0) throw std::invalid_argument("capacity must be positive");
    if (n <= 0 || (int)price.size() != n) throw std::invalid_argument("price must match n");
    if (start < 0 || start >= n || target < 0 || target >= n) throw std::invalid_argument("bad endpoint");
    for (int value : price) {
        if (value < 0) throw std::invalid_argument("negative price");
    }
    std::vector<std::vector<std::pair<int, int>>> graph((size_t)n);
    for (const auto& road : roads) {
        int from = std::get<0>(road);
        int to = std::get<1>(road);
        int distance = std::get<2>(road);
        if (from < 0 || from >= n || to < 0 || to >= n) throw std::invalid_argument("bad road");
        if (distance > capacity) throw std::invalid_argument("road longer than the tank");
        graph[(size_t)from].push_back({to, distance});
        graph[(size_t)to].push_back({from, distance});
    }
    const long long INF = (long long)4e18;
    std::vector<std::vector<long long>> best((size_t)n, std::vector<long long>((size_t)capacity + 1, INF));
    using State = std::tuple<long long, int, int>;
    std::priority_queue<State, std::vector<State>, std::greater<State>> queue;
    best[(size_t)start][0] = 0;
    queue.push({0, start, 0});
    while (!queue.empty()) {
        auto [cost, city, fuel] = queue.top();
        queue.pop();
        if (cost > best[(size_t)city][(size_t)fuel]) continue;
        if (city == target) return cost;
        if (fuel < capacity && cost + price[(size_t)city] < best[(size_t)city][(size_t)fuel + 1]) {
            best[(size_t)city][(size_t)fuel + 1] = cost + price[(size_t)city];
            queue.push({best[(size_t)city][(size_t)fuel + 1], city, fuel + 1});
        }
        for (const auto& [next, distance] : graph[(size_t)city]) {
            if (distance > fuel) continue;
            if (cost < best[(size_t)next][(size_t)(fuel - distance)]) {
                best[(size_t)next][(size_t)(fuel - distance)] = cost;
                queue.push({cost, next, fuel - distance});
            }
        }
    }
    return -1;
}
