static bool on_segment(std::pair<long long, long long> a, std::pair<long long, long long> b, long long x, long long y) {
    long long cross = (b.first - a.first) * (y - a.second) - (b.second - a.second) * (x - a.first);
    if (cross != 0) return false;
    return std::min(a.first, b.first) <= x && x <= std::max(a.first, b.first) &&
           std::min(a.second, b.second) <= y && y <= std::max(a.second, b.second);
}

bool inside(std::vector<std::pair<long long, long long>> polygon, long long x, long long y) {
    if (polygon.size() < 3) throw std::invalid_argument("polygon needs three vertices");
    size_t count = polygon.size();
    for (size_t index = 0; index < count; ++index) {
        if (on_segment(polygon[index], polygon[(index + 1) % count], x, y)) return true;
    }
    bool inside_flag = false;
    for (size_t index = 0; index < count; ++index) {
        auto a = polygon[index];
        auto b = polygon[(index + 1) % count];
        if ((a.second > y) != (b.second > y)) {
            long long cross = (b.first - a.first) * (y - a.second) - (b.second - a.second) * (x - a.first);
            if ((cross > 0) == (b.second > a.second)) inside_flag = !inside_flag;
        }
    }
    return inside_flag;
}
