long long count_digit_sum(long long limit, int target) {
    if (limit < 0) throw std::invalid_argument("limit must be non-negative");
    if (target < 0) throw std::invalid_argument("target must be non-negative");
    std::string digits = std::to_string(limit);
    int width = (int)digits.size();
    std::vector<std::vector<long long>> memo((size_t)width + 1, std::vector<long long>((size_t)target + 1, -1));
    std::vector<std::vector<long long>> loose((size_t)width + 1, std::vector<long long>((size_t)target + 1, 0));
    for (int rest = 0; rest <= target; ++rest) {
        loose[(size_t)width][(size_t)rest] = (rest == 0) ? 1 : 0;
    }
    for (int position = width - 1; position >= 0; --position) {
        for (int rest = 0; rest <= target; ++rest) {
            long long total = 0;
            for (int digit = 0; digit <= 9; ++digit) {
                if (digit > rest) break;
                total += loose[(size_t)position + 1][(size_t)(rest - digit)];
            }
            loose[(size_t)position][(size_t)rest] = total;
        }
    }
    long long answer = 0;
    int rest = target;
    for (int position = 0; position < width; ++position) {
        int current = digits[(size_t)position] - '0';
        for (int digit = 0; digit < current; ++digit) {
            if (digit > rest) break;
            answer += loose[(size_t)position + 1][(size_t)(rest - digit)];
        }
        rest -= current;
        if (rest < 0) break;
    }
    if (rest == 0) answer += 1;
    return answer;
}
