long long count_xor_subsets(std::vector<int> values, int target) {
    const long long modulo = 1000000007LL;
    const int states = 1024;
    if (target < 0 || target >= states) return 0;
    std::vector<long long> ways((size_t)states, 0);
    ways[0] = 1;
    for (int value : values) {
        std::vector<long long> next = ways;
        for (int state = 0; state < states; ++state) {
            next[(size_t)(state ^ value)] = (next[(size_t)(state ^ value)] + ways[(size_t)state]) % modulo;
        }
        ways = next;
    }
    return ways[(size_t)target] % modulo;
}
