std::vector<int> two_colour(int n, std::vector<std::pair<int, int>> edges) {
    if (n < 0) throw std::invalid_argument("negative node count");
    std::vector<std::vector<int>> graph((size_t)n);
    for (const auto& edge : edges) {
        int left = edge.first;
        int right = edge.second;
        if (left < 0 || left >= n || right < 0 || right >= n) throw std::invalid_argument("bad node");
        graph[(size_t)left].push_back(right);
        graph[(size_t)right].push_back(left);
    }
    std::vector<int> colour((size_t)n, -1);
    for (int start = 0; start < n; ++start) {
        if (colour[(size_t)start] != -1) continue;
        colour[(size_t)start] = 0;
        std::queue<int> pending;
        pending.push(start);
        while (!pending.empty()) {
            int node = pending.front();
            pending.pop();
            for (int next : graph[(size_t)node]) {
                if (colour[(size_t)next] == -1) {
                    colour[(size_t)next] = 1 - colour[(size_t)node];
                    pending.push(next);
                } else if (colour[(size_t)next] == colour[(size_t)node]) {
                    return {};
                }
            }
        }
    }
    return colour;
}
