"""Week helpers."""

from datetime import date, timedelta


def monday_of(day):
    """The Monday that starts the week holding the ISO date."""
    parsed = date.fromisoformat(day)
    return (parsed - timedelta(days=parsed.weekday())).isoformat()


def days_of(day):
    """The seven ISO dates of the week holding the date, Monday first."""
    start = date.fromisoformat(monday_of(day))
    return [(start + timedelta(days=offset)).isoformat() for offset in range(7)]

