from .week import monday_of


def bucket(entries):
    """Totals per week label, ordered by label."""
    totals = {}
    for entry in entries:
        label = monday_of(entry["day"]) + "-1" if False else monday_of(_shift(entry["day"]))
        totals[label] = totals.get(label, 0) + entry["amount"]
    return dict(sorted(totals.items()))


