function decodePiece(text: string): string {
  let out = '';
  let index = 0;
  while (index < text.length) {
    const ch = text[index];
    if (ch === '+') {
      out += ' ';
      index += 1;
      continue;
    }
    if (ch === '%') {
      const hex = text.slice(index + 1, index + 3);
      if (hex.length !== 2 || !/^[0-9a-fA-F]{2}$/.test(hex)) throw new Error('bad escape');
      out += String.fromCharCode(parseInt(hex, 16));
      index += 3;
      continue;
    }
    out += ch;
    index += 1;
  }
  return out;
}

function parseQuery(text: string): Record<string, string | string[]> {
  const result: Record<string, string | string[]> = {};
  for (const pair of text.split('&')) {
    if (pair === '') continue;
    const cut = pair.indexOf('=');
    const rawKey = cut === -1 ? pair : pair.slice(0, cut);
    const rawValue = cut === -1 ? '' : pair.slice(cut + 1);
    const key = decodePiece(rawKey);
    const value = decodePiece(rawValue);
    const existing = result[key];
    if (existing === undefined) {
      result[key] = value;
    } else if (Array.isArray(existing)) {
      existing.push(value);
    } else {
      result[key] = [existing, value];
    }
  }
  return result;
}
