class TodoStore {
  private items: Array<{ id: number; title: string; done: boolean; tags: string[] }> = [];
  private nextId = 1;

  add(title: string, tags: string[]): number {
    if (typeof title !== 'string' || title.trim() === '') throw new Error('title is required');
    const unique = [...new Set(tags)];
    const id = this.nextId;
    this.nextId += 1;
    this.items.push({ id, title, done: false, tags: unique });
    return id;
  }

  toggle(id: number): boolean {
    const item = this.items.find((entry) => entry.id === id);
    if (!item) throw new Error('unknown id: ' + id);
    item.done = !item.done;
    return item.done;
  }

  list(tag?: string) {
    const chosen = this.items.filter((item) => tag === undefined || item.tags.includes(tag));
    return chosen
      .slice()
      .sort((a, b) => {
        if (a.done !== b.done) return a.done ? 1 : -1;
        return a.title < b.title ? -1 : a.title > b.title ? 1 : 0;
      })
      .map((item) => ({ id: item.id, title: item.title, done: item.done, tags: [...item.tags] }));
  }

  stats() {
    const done = this.items.filter((item) => item.done).length;
    return { open: this.items.length - done, done };
  }

  tags(): string[] {
    const gathered = new Set<string>();
    for (const item of this.items) for (const tag of item.tags) gathered.add(tag);
    return [...gathered].sort();
  }
}
