function formatTable(headers: string[], rows: Array<Array<string | number>>, numeric: boolean[]): string[] {
  if (headers.length === 0) throw new Error('headers are required');
  const widths = headers.map((header) => String(header).length);
  for (const row of rows) {
    if (row.length !== headers.length) throw new Error('row length mismatch');
    row.forEach((cell, index) => {
      const width = String(cell).length;
      if (width > widths[index]) widths[index] = width;
    });
  }
  const build = (cells: Array<string | number>): string => {
    const parts = cells.map((cell, index) => {
      const text = String(cell);
      const padding = ' '.repeat(widths[index] - text.length);
      return numeric[index] ? padding + text : text + padding;
    });
    return parts.join(' | ');
  };
  return [build(headers), ...rows.map((row) => build(row))];
}
