function applyPatch(lines: string[], patch: Array<[string, string?]>): string[] {
  const out: string[] = [];
  let cursor = 0;
  for (const operation of patch) {
    const kind = operation[0];
    if (kind === 'keep' || kind === 'del') {
      if (cursor >= lines.length) throw new Error('cursor past the end: ' + kind);
      if (kind === 'keep') out.push(lines[cursor]);
      cursor += 1;
      continue;
    }
    if (kind === 'ins') {
      if (cursor > lines.length) throw new Error('cursor past the end: ins');
      if (operation[1] === undefined) throw new Error('ins needs text');
      out.push(operation[1]);
      continue;
    }
    throw new Error('unknown operation: ' + kind);
  }
  return out;
}
