const UNIT_SECONDS: Record<string, number> = { d: 86400, h: 3600, m: 60, s: 1 };
const UNIT_ORDER = ['d', 'h', 'm', 's'];

function parseDuration(text: string): number {
  if (typeof text !== 'string' || text.length === 0) throw new Error('text is required');
  let index = 0;
  let lastRank = -1;
  let total = 0;
  while (index < text.length) {
    const start = index;
    while (index < text.length && text[index] >= '0' && text[index] <= '9') index += 1;
    const digits = text.slice(start, index);
    if (digits.length === 0) throw new Error('number expected at ' + start);
    if (digits.length > 1 && digits[0] === '0') throw new Error('leading zero at ' + start);
    if (index >= text.length) throw new Error('unit expected at ' + index);
    const unit = text[index];
    index += 1;
    if (!(unit in UNIT_SECONDS)) throw new Error('unknown unit: ' + unit);
    const rank = UNIT_ORDER.indexOf(unit);
    if (rank <= lastRank) throw new Error('unit out of order: ' + unit);
    lastRank = rank;
    total += Number(digits) * UNIT_SECONDS[unit];
  }
  return total;
}
