class BitSet {
  private members: Set<number> = new Set();

  private check(value: number): void {
    if (!Number.isInteger(value) || value < 0) throw new Error('values must be non-negative integers');
  }

  add(value: number): void {
    this.check(value);
    this.members.add(value);
  }

  has(value: number): boolean {
    this.check(value);
    return this.members.has(value);
  }

  delete(value: number): void {
    this.check(value);
    this.members.delete(value);
  }

  count(): number {
    return this.members.size;
  }

  values(): number[] {
    return [...this.members].sort((a, b) => a - b);
  }

  union(other: BitSet): BitSet {
    const result = new BitSet();
    for (const value of this.values()) result.add(value);
    for (const value of other.values()) result.add(value);
    return result;
  }

  intersect(other: BitSet): BitSet {
    const result = new BitSet();
    for (const value of this.values()) {
      if (other.has(value)) result.add(value);
    }
    return result;
  }
}
