```typescript
const BASE = 131;
const MOD = 1000000007;

function buildHashes(text: string) {
  const prefix: number[] = [0];
  const power: number[] = [1];
  for (let index = 0; index < text.length; index += 1) {
    prefix.push((prefix[index] * BASE + text.charCodeAt(index)) % MOD);
    power.push((power[index] * BASE) % MOD);
  }
  return { text, prefix, power };
}

function rangeHash(state: { text: string; prefix: number[]; power: number[] }, left: number, right: number): number {
  if (!Number.isInteger(left) || !Number.isInteger(right)) throw new Error('bounds must be integers');
  if (left < 0 || right > state.text.length || left > right) throw new Error('bounds out of range');
  const head = (state.prefix[right] - (state.prefix[left] * state.power[right - left]) % MOD) % MOD;
  return (head + MOD) % MOD;
}

function sameRange(state: { text: string; prefix: number[]; power: number[] }, leftA: number, rightA: number, leftB: number, rightB: number): boolean {
  if (rightA - leftA !== rightB - leftB) throw new Error('ranges must have the same length');
  return rangeHash(state, leftA, rightA) === rangeHash(state, leftB, rightB);
}
