function runElevator(capacity: number, requests: Array<[number, number]>) {
  if (!Number.isInteger(capacity) || capacity < 1) throw new Error('capacity must be a positive integer');
  let floor = 0;
  let distance = 0;
  let served = 0;
  let skipped = 0;
  let aboard = 0;
  for (const request of requests) {
    const from = request[0];
    const to = request[1];
    if (!Number.isInteger(from) || !Number.isInteger(to)) throw new Error('floors must be integers');
    if (from < 0 || to < 0) throw new Error('floors must be non-negative');
    if (from === to) throw new Error('floors must differ');
    if (aboard >= capacity) {
      skipped += 1;
      continue;
    }
    distance += Math.abs(floor - from) + Math.abs(to - from);
    floor = to;
    served += 1;
    aboard = aboard + 1;
  }
  return { floor, distance, served, skipped };
}
