function validateSchema(value: any, schema: any): string[] {
  const errors: string[] = [];

  function walk(current: any, node: any, path: string): void {
    if (!node || typeof node !== 'object') {
      errors.push(path);
      return;
    }
    if (node.type === 'string' || node.type === 'boolean') {
      if (typeof current !== node.type) errors.push(path);
      return;
    }
    if (node.type === 'number') {
      if (typeof current !== 'number' || !Number.isFinite(current)) errors.push(path);
      return;
    }
    if (node.type === 'array') {
      if (!Array.isArray(current)) {
        errors.push(path);
        return;
      }
      current.forEach((item, index) => walk(item, node.items, path + '[' + index + ']'));
      return;
    }
    if (node.type === 'object') {
      if (typeof current !== 'object' || current === null || Array.isArray(current)) {
        errors.push(path);
        return;
      }
      const fields = node.fields || {};
      for (const key of Object.keys(fields)) {
        if (!(key in current)) {
          if ((node.required || []).includes(key)) errors.push(joinPath(path, key));
          continue;
        }
        walk(current[key], fields[key], joinPath(path, key));
      }
      for (const key of node.required || []) {
        if (!(key in current) && !(key in fields)) errors.push(joinPath(path, key));
      }
      return;
    }
    errors.push(path);
  }

  walk(value, schema, '$');
  return errors;
}
