```typescript
class TimeSeries {
  private times: number[] = [];
  private values: Map<number, number> = new Map();

  add(time: number, value: number): void {
    if (!Number.isInteger(time)) throw new Error('time must be an integer');
    if (this.values.has(time)) throw new Error('duplicate time: ' + time);
    this.values.set(time, value);
    this.times.push(time);
    this.times.sort((a, b) => a - b);
  }

  private window(from: number, to: number): number[] {
    return this.times.filter((time) => time >= from && time < to);
  }

  mean(from: number, to: number): number | null {
    const chosen = this.window(from, to);
    if (chosen.length === 0) return null;
    let total = 0;
    for (const time of chosen) total += this.values.get(time) as number;
    return total / chosen.length;
  }

  max(from: number, to: number): number | null {
    const chosen = this.window(from, to);
    if (chosen.length === 0) return null;
    let best = this.values.get(chosen[0]) as number;
    for (const time of chosen) {
      const value = this.values.get(time) as number;
      if (value > best) best = value;
    }
    return best;
  }

  samples(): number[] {
    return [...this.times];
  }
}
