const FILTERS = {
  upper: (text) => text.toUpperCase(),
  lower: (text) => text.toLowerCase(),
  trim: (text) => text.trim(),
};

function render(template, values) {
  let out = '';
  let index = 0;
  while (index < template.length) {
    const start = template.indexOf('{{', index);
    if (start === -1) {
      out += template.slice(index);
      break;
    }
    out += template.slice(index, start);
    const stop = template.indexOf('}}', start + 2);
    if (stop === -1) throw new Error('unclosed placeholder');
    const body = template.slice(start + 2, stop);
    const parts = body.split('|').map((part) => part.trim());
    const name = parts[0];
    if (name === '') throw new Error('empty placeholder');
    if (!(name in values)) throw new Error('missing value: ' + name);
    let text = String(values[name]);
    for (const filter of parts.slice(1)) {
      if (!(filter in FILTERS)) throw new Error('unknown filter: ' + filter);
      text = FILTERS[filter](text);
    }
    out += text;
    index = stop + 2;
  }
  return out;
}
