function memoizeLimit(fn, size) {
  if (!Number.isInteger(size) || size < 1) throw new Error('size must be a positive integer');
  const cache = new Map();
  let hits = 0;
  let misses = 0;

  function wrapper(...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) {
      const value = cache.get(key);
      cache.delete(key);
      cache.set(key, value);
      hits += 1;
      return value;
    }
    const value = fn(...args);
    misses += 1;
    cache.set(key, value);
    if (cache.size > size) {
      const oldest = cache.keys().next().value;
      cache.delete(oldest);
    }
    return value;
  }

  wrapper.stats = () => ({ hits, misses, size: cache.size });
  return wrapper;
}
