function parseMoney(text) {
  if (typeof text !== 'string') throw new Error('text must be a string');
  let body = text.trim();
  if (body.startsWith('$')) body = body.slice(1);
  else if (body.startsWith('EUR ')) body = body.slice(4);
  let sign = 1;
  if (body.startsWith('-')) {
    sign = -1;
    body = body.slice(1);
  } else if (body.startsWith('+')) {
    body = body.slice(1);
  }
  const parts = body.split('.');
  if (parts.length > 2) throw new Error('too many decimal points');
  const whole = parts[0];
  const fraction = parts.length === 2 ? parts[1] : '00';
  if (parts.length === 2 && !/^\d{2}$/.test(fraction)) throw new Error('bad fraction');
  if (!/^\d{1,3}(,\d{3})*$|^\d+$/.test(whole)) throw new Error('bad integer part');
  const digits = whole.split(',').join('');
  return sign * (Number(digits) * 100 + Number(fraction));
}
