```javascript
function runSnake(width, height, food, moves) {
  const remaining = food.map((item) => [item[0], item[1]]);
  const body = [[0, 0]];
  let eaten = 0;
  let steps = 0;
  const deltas = { U: [0, 1], D: [0, -1], L: [-1, 0], R: [1, 0] };
  for (const move of moves) {
    steps += 1;
    const delta = deltas[move];
    if (!delta) throw new Error('unknown move: ' + move);
    const head = body[0];
    const next = [head[0] + delta[0], head[1] + delta[1]];
    const outside = next[0] < 0 || next[0] >= width || next[1] < 0 || next[1] >= height;
    const willEat = remaining.findIndex((item) => item[0] === next[0] && item[1] === next[1]) !== -1;
    const bodyToCheck = willEat ? body : body.slice(0, body.length - 1);
    const hitSelf = bodyToCheck.some((segment) => segment[0] === next[0] && segment[1] === next[1]);
    if (outside || hitSelf) return { alive: false, length: body.length, eaten, steps };
    body.unshift(next);
    if (willEat) {
      remaining.splice(remaining.findIndex((item) => item[0] === next[0] && item[1] === next[1]), 1);
      eaten += 1;
    } else {
      body.pop();
    }
  }
  return { alive: true, length: body.length, eaten, steps };
}
