```javascript
class RingBuffer {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new Error('capacity must be a positive integer');
    this.capacity = capacity;
    this.store = [];
  }

  push(value) {
    this.store.push(value);
    if (this.store.length > this.capacity) this.store.shift();
    return this;
  }

  pushAll(values) {
    for (const value of values) this.push(value);
    return this;
  }

  toArray() {
    return [...this.store];
  }

  size() {
    return this.store.length;
  }

  isFull() {
    return this.store.length === this.capacity;
  }

  shift() {
    return this.store.length === 0 ? null : this.store.shift();
  }

  sum() {
    return this.store.reduce((total, value) => total + value, 0);
  }
}
```

