function spiral(matrix) {
  if (!Array.isArray(matrix)) throw new Error('matrix must be an array');
  if (matrix.length === 0) return [];
  const width = matrix[0].length;
  for (const row of matrix) {
    if (!Array.isArray(row) || row.length !== width) throw new Error('rows must have equal length');
  }
  const out = [];
  let top = 0;
  let bottom = matrix.length - 1;
  let left = 0;
  let right = width - 1;
  while (top <= bottom && left <= right) {
    for (let col = left; col <= right; col += 1) out.push(matrix[top][col]);
    top += 1;
    for (let row = top; row <= bottom; row += 1) out.push(matrix[row][right]);
    right -= 1;
    if (top <= bottom) {
      for (let col = right; col >= left; col -= 1) out.push(matrix[bottom][col]);
      bottom -= 1;
    }
    if (left <= right) {
      for (let row = bottom; row >= top; row -= 1) out.push(matrix[row][left]);
      left += 1;
    }
  }
  return out;
}
