import heapq


def mst_cost(n, edges):
    if n < 0:
        raise ValueError("node count must be non-negative")
    graph = [[] for _ in range(n)]
    for start, stop, weight in edges:
        if start < 0 or start >= n or stop < 0 or stop >= n:
            raise ValueError("bad endpoint: %r" % ((start, stop),))
        graph[start].append((stop, weight))
        graph[stop].append((start, weight))
    if n == 0:
        return 0
    seen = [False] * n
    heap = [(0, 0)]
    total = 0
    used = 0
    while heap and used < n:
        weight, node = heapq.heappop(heap)
        if seen[node]:
            continue
        seen[node] = True
        total += weight
        used += 1
        for neighbour, cost in graph[node]:
            if not seen[neighbour]:
                heapq.heappush(heap, (cost, neighbour))
    return total if used == n else None
```

