def normalise_ipv4(text):
    if not isinstance(text, str) or text == "":
        raise ValueError("address must not be empty")
    parts = text.split(".")
    if len(parts) != 4:
        raise ValueError("an address needs four parts")
    cleaned = []
    for part in parts:
        if not part or not part.isdigit() or not part.isascii():
            raise ValueError("bad part: %r" % (part,))
        if len(part) > 3:
            raise ValueError("part too long: %r" % (part,))
        value = int(part)
        if value > 255:
            raise ValueError("part out of range: %r" % (part,))
        cleaned.append(str(value))
    return ".".join(cleaned)
