def zigzag_levels(tree):
    if tree is None:
        return []
    levels = []
    current = [tree]
    left_to_right = True
    while current:
        values = []
        following = []
        for node in current:
            if not isinstance(node, list) or len(node) != 3:
                raise ValueError("node must be [value, left, right]")
            values.append(node[0])
            for child in (node[1], node[2]):
                if child is not None:
                    following.append(child)
        levels.append(values if left_to_right else list(reversed(values)))
        left_to_right = not left_to_right
        current = following
    return levels
