ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
REVERSE = {character: index for index, character in enumerate(ALPHABET)}


def b64_encode(data):
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes")
    raw = bytes(data)
    out = []
    for index in range(0, len(raw), 3):
        block = raw[index:index + 3]
        padded = block + bytes(3 - len(block))
        number = (padded[0] << 16) | (padded[1] << 8) | padded[2]
        digits = [(number >> 18) & 63, (number >> 12) & 63, (number >> 6) & 63, number & 63]
        letters = [ALPHABET[digit] for digit in digits]
        if len(block) == 1:
            letters[2] = "="
            letters[3] = "="
        elif len(block) == 2:
            letters[3] = "="
        out.extend(letters)
    return "".join(out)


def b64_decode(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if len(text) % 4 != 0:
        raise ValueError("length must be a multiple of four")
    stripped = text.rstrip("=")
    pad = len(text) - len(stripped)
    if pad > 2:
        raise ValueError("too much padding")
    if "=" in stripped:
        raise ValueError("padding in the middle")
    values = []
    for character in stripped:
        if character not in REVERSE:
            raise ValueError("bad character: %r" % (character,))
        values.append(REVERSE[character])
    out = bytearray()
    for index in range(0, len(values), 4):
        chunk = values[index:index + 4]
        chunk += [0] * (4 - len(chunk))
        number = (chunk[0] << 18) | (chunk[1] << 12) | (chunk[2] << 6) | chunk[3]
        out.extend([(number >> 16) & 255, (number >> 8) & 255, number & 255])
    if len(values) % 4 == 2:
        out = out[:-2]
    elif len(values) % 4 == 3:
        out = out[:-1]
    return bytes(out)
