def sparse_matmul(left, right, left_shape, right_shape):
    rows, inner = left_shape
    right_inner, cols = right_shape
    if inner != right_inner:
        raise ValueError("shapes do not line up")
    for (row, col), value in left.items():
        if row < 0 or row >= rows or col < 0 or col >= inner:
            raise ValueError("left key out of range: %r" % ((row, col),))
        if value == 0:
            raise ValueError("zero entries must not be stored")
    for (row, col), value in right.items():
        if row < 0 or row >= right_inner or col < 0 or col >= cols:
            raise ValueError("right key out of range: %r" % ((row, col),))
        if value == 0:
            raise ValueError("zero entries must not be stored")
    by_row = {}
    for (row, col), value in right.items():
        by_row.setdefault(row, []).append((col, value))
    product = {}
    for (row, col), value in left.items():
        for other_col, other_value in by_row.get(col, []):
            key = (row, other_col)
            product[key] = product.get(key, 0) + value * other_value
    return {key: total for key, total in product.items() if total != 0}
