from collections import deque


def topo_batches(n, edges):
    if n < 0:
        raise ValueError("node count must be negative-free")
    following = [set() for _ in range(n)]
    indegree = [0] * n
    for start, stop in edges:
        if start < 0 or start >= n or stop < 0 or stop >= n:
            raise ValueError("bad edge: %r" % ((start, stop),))
        if stop in following[start]:
            continue
        following[start].add(stop)
        indegree[stop] += 1
    ready = deque(node for node in range(n) if indegree[node] == 0)
    batches = []
    placed = 0
    while ready:
        batch = sorted(ready)
        ready.clear()
        batches.append(batch)
        placed += len(batch)
        for node in batch:
            for target in following[node]:
                indegree[target] -= 1
                if indegree[target] == 0:
                    ready.append(target)
    if placed != n:
        return []
    return batches
