def run_session(machine, events):
    states = machine.get("states")
    if not isinstance(states, list) or not states:
        raise ValueError("machine needs a non-empty states list")
    known = set(states)
    start = machine.get("start")
    if start not in known:
        raise ValueError("start must be a declared state")
    accepting = set(machine.get("final", []))
    if not accepting <= known:
        raise ValueError("final states must be declared states")
    rules = []
    for rule in machine.get("transitions", []):
        if "on" not in rule or "to" not in rule:
            raise ValueError("a transition needs on and to")
        source = rule.get("from", "*")
        if source != "*" and source not in known:
            raise ValueError("unknown source state: %r" % (source,))
        if rule["to"] not in known:
            raise ValueError("unknown target state: %r" % (rule["to"],))
        rules.append((rule["on"], source, rule["to"],
                      frozenset(rule.get("need", ())), frozenset(rule.get("deny", ())),
                      list(rule.get("gain", ())), list(rule.get("drop", ())),
                      rule.get("emit")))
    state = start
    facts = set()
    emitted = []
    rejected = []
    for index, event in enumerate(events):
        chosen = None
        for on, source, target, need, deny, gain, drop, emit in rules:
            if on != event:
                continue
            if source != "*" and source != state:
                continue
            if not need <= facts:
                continue
            if deny & facts:
                continue
            chosen = (target, gain, drop, emit)
            break
        if chosen is None:
            rejected.append(index)
            continue
        target, gain, drop, emit = chosen
        facts.difference_update(drop)
        facts.update(gain)
        state = target
        if emit is not None:
            emitted.append(emit)
    return {"state": state, "facts": sorted(facts), "emitted": emitted,
            "rejected": rejected, "accepted": state in accepting}
