static int __rootOf(std::vector<int>& parent, int node) {
    while (parent[(size_t)node] != node) {
        parent[(size_t)node] = parent[(size_t)parent[(size_t)node]];
        node = parent[(size_t)node];
    }
    return node;
}

std::vector<long long> connectivity(int n, std::vector<std::vector<long long>> ops) {
    if (n < 1) throw std::invalid_argument("node count must be positive");
    std::vector<int> parent((size_t)n);
    std::vector<int> members((size_t)n, 1);
    std::iota(parent.begin(), parent.end(), 0);
    std::vector<long long> answers;
    for (const auto& op : ops) {
        if (op.empty()) throw std::invalid_argument("empty operation");
        long long code = op[0];
        if (code < 1 || code > 4) throw std::invalid_argument("unknown operation");
        bool needs_two = code != 3 && code != 4;
        size_t want = needs_two ? 3u : 2u;
        if (op.size() != want) throw std::invalid_argument("wrong operand count");
        long long a = op[1];
        if (a < 0 || a >= n) throw std::invalid_argument("index out of range");
        long long b = needs_two ? op[2] : 0;
        if (needs_two && (b < 0 || b >= n)) throw std::invalid_argument("index out of range");
        if (code == 1) {
            int ra = __rootOf(parent, (int)a);
            int rb = __rootOf(parent, (int)b);
            if (ra == rb) continue;
            if (members[(size_t)ra] < members[(size_t)rb]) std::swap(ra, rb);
            else if (members[(size_t)ra] == members[(size_t)rb] && rb < ra) std::swap(ra, rb);
            parent[(size_t)rb] = ra;
            members[(size_t)ra] += members[(size_t)rb];
        } else if (code == 2) {
            answers.push_back(__rootOf(parent, (int)a) == __rootOf(parent, (int)b) ? 1 : 0);
        } else if (code == 3) {
            answers.push_back(members[(size_t)__rootOf(parent, (int)a)]);
        } else {
            answers.push_back(__rootOf(parent, (int)a));
        }
    }
    return answers;
}
