#include <cassert>
#include <functional>
#include <queue>
#include <stdexcept>
#include <utility>
#include <vector>

std::vector<int> huffman_lengths(std::vector<long long> weights) {
    int n = (int)weights.size();
    for (long long weight : weights) {
        if (weight <= 0) throw std::invalid_argument("weights must be positive");
    }
    if (n == 0) return {};
    if (n == 1) return {0};
    std::vector<int> parent((size_t)(2 * n - 1), -1);
    std::priority_queue<std::pair<long long, int>, std::vector<std::pair<long long, int>>,
                        std::greater<std::pair<long long, int>>> pending;
    for (int i = 0; i < n; ++i) pending.push({weights[(size_t)i], i});
    int fresh = n;
    while (pending.size() > 1) {
        auto first = pending.top();
        pending.pop();
        auto second = pending.top();
        pending.pop();
        parent[(size_t)first.second] = fresh;
        parent[(size_t)second.second] = fresh;
        pending.push({first.first + second.first, fresh});
        ++fresh;
    }
    std::vector<int> lengths((size_t)n, 0);
    for (int leaf = 0; leaf < n; ++leaf) {
        int depth = 0;
        for (int node = leaf; parent[(size_t)node] != -1; node = parent[(size_t)node]) ++depth;
        lengths[(size_t)leaf] = depth;
    }
    return lengths;
}
