#include <algorithm>
#include <cassert>
#include <stdexcept>
#include <vector>

struct __Plan {
    long long value = 0;
    long long count = 0;
};

static __Plan __better(const __Plan& left, const __Plan& right) {
    if (left.value != right.value) return left.value > right.value ? left : right;
    return left.count >= right.count ? left : right;
}

std::vector<long long> best_job_plan(std::vector<std::vector<long long>> jobs) {
    for (const auto& job : jobs) {
        if (job.size() != 3) throw std::invalid_argument("a job needs start, end and value");
        if (job[1] <= job[0]) throw std::invalid_argument("a job must end after it starts");
        if (job[2] < 0) throw std::invalid_argument("values must not be negative");
    }
    if (jobs.empty()) return {0, 0};
    std::sort(jobs.begin(), jobs.end(), [](const std::vector<long long>& a, const std::vector<long long>& b) {
        if (a[1] != b[1]) return a[1] < b[1];
        if (a[0] != b[0]) return a[0] < b[0];
        return a[2] > b[2];
    });
    std::vector<long long> ends((size_t)jobs.size());
    for (size_t i = 0; i < jobs.size(); ++i) ends[i] = jobs[i][1];
    std::vector<__Plan> best(jobs.size() + 1);
    for (size_t i = 1; i <= jobs.size(); ++i) {
        const auto& job = jobs[i - 1];
        size_t free = (size_t)(std::upper_bound(ends.begin(), ends.end(), job[0]) - ends.begin());
        __Plan take{best[free].value + job[2], best[free].count + 1};
        best[i] = __better(best[i - 1], take);
    }
    return {best.back().value, best.back().count};
}
