std::vector<std::string> life_steps(std::vector<std::string> board, int steps) {
    if (steps < 0) throw std::invalid_argument("steps must not be negative");
    if (board.empty()) return board;
    size_t width = board[0].size();
    for (const std::string& row : board) {
        if (row.size() != width) throw std::invalid_argument("rows must share one width");
        for (char cell : row) {
            if (cell != '#' && cell != '.') throw std::invalid_argument("bad cell");
        }
    }
    std::vector<std::string> current = board;
    int height = (int)board.size();
    for (int step = 0; step < steps; ++step) {
        std::vector<std::string> following = current;
        for (int row = 0; row < height; ++row) {
            for (size_t col = 0; col < width; ++col) {
                int alive = 0;
                for (int dr = -1; dr <= 1; ++dr) {
                    for (int dc = -1; dc <= 1; ++dc) {
                        if (dr == 0 && dc == 0) continue;
                        int rr = row + dr;
                        int cc = (int)col + dc;
                        if (rr < 0 || rr >= height || cc < 0 || cc >= (int)width) continue;
                        if (current[(size_t)rr][(size_t)cc] == '#') ++alive;
                    }
                }
                bool live = current[(size_t)row][col] == '#';
                following[(size_t)row][col] = ((live && (alive == 2 || alive == 3)) || (!live && alive == 3)) ? '#' : '.';
            }
        }
        current = following;
    }
    return current;
}
