    for (long long length : logs) {
        long long pieces = (length + limit - 1) / limit;
        spent += pieces - 1;
        if (spent > cuts) return false;
    }
    return spent <= cuts;
}

long long min_max_piece(std::vector<long long> logs, long long cuts) {
    if (cuts < 0) throw std::invalid_argument("cuts must not be negative");
    if (logs.empty()) return 0;
    long long longest = 0;
    for (long long length : logs) {
        if (length <= 0) throw std::invalid_argument("logs must be positive");
        if (length > longest) longest = length;
    }
    long long low = 1;
    long long high = longest;
    while (low < high) {
        long long middle = low + (high - low) / 2;
        if (__fits(logs, middle, cuts)) high = middle;
        else low = middle + 1;
    }
    return low;
}
