struct __TrieNode {
    std::array<int, 26> next{};
    int through = 0;
};

static long long __pairs(long long count) { return count * (count - 1) / 2; }

long long count_prefix_pairs(std::vector<std::string> words, int k) {
    if (k < 0) throw std::invalid_argument("k must not be negative");
    std::vector<__TrieNode> nodes(1);
    for (const std::string& word : words) {
        int node = 0;
        nodes[0].through += 1;
        for (char letter : word) {
            if (letter < 'a' || letter > 'z') throw std::invalid_argument("lower case only");
            int slot = letter - 'a';
            if (nodes[(size_t)node].next[(size_t)slot] == 0) {
                nodes.push_back(__TrieNode{});
                nodes[(size_t)node].next[(size_t)slot] = (int)nodes.size() - 1;
            }
            node = nodes[(size_t)node].next[(size_t)slot];
            nodes[(size_t)node].through += 1;
        }
    }
    long long at_k = 0;
    long long at_next = 0;
    std::vector<std::pair<int, int>> pending;
    pending.push_back({0, 0});
    while (!pending.empty()) {
        int node = pending.back().first;
        int depth = pending.back().second;
        pending.pop_back();
        long long through = nodes[(size_t)node].through;
        if (depth == k) at_k += __pairs(through);
        else if (depth == k + 1) at_next += __pairs(through);
        for (int slot = 0; slot < 26; ++slot) {
            int child = nodes[(size_t)node].next[(size_t)slot];
            if (child != 0) pending.push_back({child, depth + 1});
        }
    }
    return at_k - at_next;
}
