bool wildcard_match(std::string text, std::string pattern) {
    size_t text_at = 0;
    size_t pattern_at = 0;
    size_t star_at = std::string::npos;
    size_t star_text = 0;
    while (text_at < text.size()) {
        if (pattern_at < pattern.size() && (pattern[pattern_at] == '?' || pattern[pattern_at] == text[text_at])) {
            ++text_at;
            ++pattern_at;
        } else if (pattern_at < pattern.size() && pattern[pattern_at] == '*') {
            star_at = pattern_at;
            star_text = text_at;
            ++pattern_at;
        } else if (star_at != std::string::npos) {
            pattern_at = star_at + 1;
            ++star_text;
            text_at = star_text;
        } else {
            return false;
        }
    }
    while (pattern_at < pattern.size() && pattern[pattern_at] == '*') ++pattern_at;
    return pattern_at == pattern.size();
