std::vector<long long> winning_takes(std::vector<int> moves, int pile) {
    if (pile < 0) throw std::invalid_argument("pile must not be negative");
    if (moves.empty()) throw std::invalid_argument("at least one move is needed");
    std::vector<char> seen((size_t)pile + 1, 0);
    for (int move : moves) {
        if (move <= 0) throw std::invalid_argument("moves must be positive");
        if (move <= pile) {
            if (seen[(size_t)move]) throw std::invalid_argument("moves must be distinct");
            seen[(size_t)move] = 1;
        }
    }
    std::vector<char> winning((size_t)pile + 1, 0);
    for (int stones = 1; stones <= pile; ++stones) {
        for (int move : moves) {
            if (move <= stones && !winning[(size_t)(stones - move)]) {
                winning[(size_t)stones] = 1;
                break;
            }
        }
    }
    std::vector<long long> answers;
    for (int move : moves) {
        bool good = move <= pile && !winning[(size_t)(pile - move)];
        answers.push_back(good ? 1 : 0);
    }
    return answers;
}
