static long long __cross(const std::pair<int, int>& origin, const std::pair<int, int>& a,
                         const std::pair<int, int>& b) {
    return (long long)(a.first - origin.first) * (long long)(b.second - origin.second) -
           (long long)(a.second - origin.second) * (long long)(b.first - origin.first);
}

long long hull_double_area(std::vector<std::pair<int, int>> points) {
    for (const auto& point : points) {
        if (point.first < -1000000 || point.first > 1000000 || point.second < -1000000 ||
            point.second > 1000000) {
            throw std::invalid_argument("coordinate out of range");
        }
    }
    std::sort(points.begin(), points.end());
    points.erase(std::unique(points.begin(), points.end()), points.end());
    if (points.size() < 3) return 0;
    std::vector<std::pair<int, int>> chain(2 * points.size());
    size_t size = 0;
    for (size_t i = 0; i < points.size(); ++i) {
        while (size >= 2 && __cross(chain[size - 2], chain[size - 1], points[i]) <= 0) --size;
        chain[size++] = points[i];
    }
    size_t lower = size + 1;
    for (size_t i = points.size() - 1; i-- > 0;) {
        while (size >= lower && __cross(chain[size - 2], chain[size - 1], points[i]) <= 0) --size;
        chain[size++] = points[i];
    }
    chain.resize(size - 1);
    if (chain.size() < 3) return 0;
    long long twice = 0;
    for (size_t i = 0; i < chain.size(); ++i) {
        const auto& a = chain[i];
        const auto& b = chain[(i + 1) % chain.size()];
        twice += (long long)a.first * b.second - (long long)b.first * a.second;
    }
    return twice < 0 ? -twice : twice;
}
