long long count_close_pairs(std::vector<unsigned long long> masks) {
    std::unordered_map<unsigned long long, long long> count;
    count.reserve(masks.size() * 2 + 1);
    for (unsigned long long mask : masks) count[mask] += 1;
    long long directed = 0;
    for (const auto& entry : count) {
        unsigned long long mask = entry.first;
        long long repeats = entry.second;
        directed += repeats * (repeats - 1) / 2 * 2;
        for (int bit = 0; bit < 64; ++bit) {
            auto found = count.find(mask ^ (1ULL << bit));
            if (found != count.end()) directed += repeats * found->second;
        }
    }
    return directed / 2;
}
