    if (quota <= 0) throw std::invalid_argument("quota must be positive");
    std::map<long long, std::deque<long long>> recent;
    std::vector<int> accepted;
    bool started = false;
    long long previous = 0;
    for (const auto& event : events) {
        if (event.size() != 2) throw std::invalid_argument("an event is {timestamp, client}");
        long long stamp = event[0];
        if (started && stamp < previous) throw std::invalid_argument("timestamps must not decrease");
        started = true;
        previous = stamp;
        std::deque<long long>& log = recent[event[1]];
        while (!log.empty() && log.front() <= stamp - window) log.pop_front();
        if ((long long)log.size() < quota) {
            log.push_back(stamp);
            accepted.push_back(1);
