#include <algorithm>
#include <cassert>
#include <stdexcept>
#include <vector>

long long min_square_split(std::vector<long long> values, int parts, int max_len) {
    if (parts < 1) throw std::invalid_argument("parts must be positive");
    if (max_len < 1) throw std::invalid_argument("max_len must be positive");
    for (long long value : values) {
        if (value < 0) throw std::invalid_argument("values must not be negative");
    }
    int n = (int)values.size();
    if (n == 0) return -1;
    const long long unreachable = 4000000000000000000LL;
    std::vector<long long> prefix((size_t)n + 1, 0);
    for (int i = 0; i < n; ++i) prefix[(size_t)i + 1] = prefix[(size_t)i] + values[(size_t)i];
    std::vector<std::vector<long long>> best((size_t)parts + 1,
                                             std::vector<long long>((size_t)n + 1, unreachable));
    best[0][0] = 0;
    for (int part = 1; part <= parts; ++part) {
        for (int end = 1; end <= n; ++end) {
            for (int len = 1; len <= max_len && len <= end; ++len) {
                int start = end - len;
                if (best[(size_t)part - 1][(size_t)start] == unreachable) continue;
                long long sum = prefix[(size_t)end] - prefix[(size_t)start];
                long long cost = best[(size_t)part - 1][(size_t)start] + sum * sum;
                if (cost < best[(size_t)part][(size_t)end]) best[(size_t)part][(size_t)end] = cost;
            }
        }
    }
    long long answer = best[(size_t)parts][(size_t)n];
    return answer == unreachable ? -1 : answer;
}
