int lock_moves(std::string start, std::string target, std::vector<std::string> blocked) {
    __checkCode(start);
    __checkCode(target);
    if (start.size() != target.size()) throw std::invalid_argument("codes must match in length");
    std::set<std::string> banned;
    for (const std::string& code : blocked) {
        __checkCode(code);
        if (code.size() != start.size()) throw std::invalid_argument("blocked code length differs");
        banned.insert(code);
    }
    if (banned.count(start) || banned.count(target)) return -1;
    std::unordered_map<std::string, int> seen;
    std::queue<std::string> pending;
    seen[start] = 0;
    pending.push(start);
    while (!pending.empty()) {
        std::string here = pending.front();
        pending.pop();
        int steps = seen[here];
        if (here == target) return steps;
        for (size_t index = 0; index < here.size(); ++index) {
            for (int delta = -1; delta <= 1; delta += 2) {
                std::string next = here;
                int digit = (next[index] - '0' + delta + 10) % 10;
                next[index] = (char)('0' + digit);
                if (banned.count(next) || seen.count(next)) continue;
                seen[next] = steps + 1;
                pending.push(next);
            }
        }
    }
    return -1;
}
