std::vector<long long> assign_workers(int workers, std::vector<std::vector<long long>> tasks) {
    if (workers < 1) throw std::invalid_argument("at least one worker is needed");
    std::priority_queue<std::pair<long long, int>, std::vector<std::pair<long long, int>>,
                        std::greater<std::pair<long long, int>>> free_at;
    for (int worker = 0; worker < workers; ++worker) free_at.push({0, worker});
    std::vector<long long> finishes;
    bool started = false;
    long long previous = 0;
    for (const auto& task : tasks) {
        if (task.size() != 2) throw std::invalid_argument("a task is {arrival, duration}");
        if (task[1] <= 0) throw std::invalid_argument("durations must be positive");
        if (started && task[0] < previous) throw std::invalid_argument("arrivals must not decrease");
        started = true;
        previous = task[0];
        auto slot = free_at.top();
        free_at.pop();
        long long start = slot.first > task[0] ? slot.first : task[0];
        long long finish = start + task[1];
        free_at.push({finish, slot.second});
        finishes.push_back(finish);
    }
    return finishes;
}
