            while (at < line.size()) {
                if (line[at] != '"') {
                    current.push_back(line[at]);
                    ++at;
                    continue;
                }
                if (at + 1 < line.size() && line[at + 1] == '"') {
                    current.push_back('"');
                    at += 2;
                    continue;
                }
                ++at;
                closed = true;
                break;
            }
            if (!closed) throw std::invalid_argument("unterminated quoted field");
            if (at < line.size() && line[at] != ',') {
                throw std::invalid_argument("text after the closing quote");
            }
        } else {
            while (at < line.size() && line[at] != ',') {
                if (line[at] == '"') throw std::invalid_argument("quote inside an unquoted field");
                current.push_back(line[at]);
                ++at;
            }
        }
        if (at < line.size() && line[at] == ',') {
            fields.push_back(current);
            current.clear();
            ++at;
            continue;
        }
        break;
    }
    fields.push_back(current);
    return fields;
}
