long long pow_text(long long base, std::string exponent, long long modulus) {
    if (modulus < 1) throw std::invalid_argument("modulus must be positive");
    if (exponent.empty()) throw std::invalid_argument("exponent must not be empty");
    long long result = 1 % modulus;
    for (char digit : exponent) {
        if (digit < '0' || digit > '9') throw std::invalid_argument("exponent must be decimal");
        result = __powMod(result, 10, modulus);
        result = (long long)((__int128)result * __powMod(base, digit - '0', modulus) % modulus);
