#include <cassert>
#include <string>

std::string smallest_rotation(std::string text) {
    int n = (int)text.size();
    if (n <= 1) return text;
    std::string doubled = text + text;
    int left = 0;
    int right = 1;
    int shift = 0;
    while (left < n && right < n && shift < n) {
        char a = doubled[(size_t)(left + shift)];
        char b = doubled[(size_t)(right + shift)];
        if (a == b) {
            ++shift;
            continue;
        }
        if (a > b) {
            left = left + shift + 1;
            if (left == right) ++left;
        } else {
            right = right + shift + 1;
            if (left == right) ++right;
        }
        shift = 0;
    }
    int start = std::min(left, right);
    return doubled.substr((size_t)start, (size_t)n);
}
