std::vector<unsigned long long> decode_varints(std::vector<unsigned char> data) {
    std::vector<unsigned long long> values;
    unsigned long long current = 0;
    int shift = 0;
    bool open = false;
    for (unsigned char byte : data) {
        unsigned long long payload = byte & 0x7fu;
        if (shift > 63) {
            if (payload != 0) throw std::invalid_argument("value overflows 64 bits");
        } else if (shift == 63 && payload > 1) {
            throw std::invalid_argument("value overflows 64 bits");
