        open = true;
        if ((byte & 0x80u) != 0) {
            shift += 7;
            continue;
        }
        if (shift > 0 && payload == 0) throw std::invalid_argument("non-minimal encoding");
        values.push_back(current);
        current = 0;
        shift = 0;
        open = false;
    }
    if (open) throw std::invalid_argument("truncated value");
    return values;
