#include <tuple>
#include <vector>

struct __LfuEntry {
    long long value = 0;
    long long uses = 0;
    long long stamp = 0;
};

std::vector<long long> lfu_run(int capacity, std::vector<std::vector<long long>> ops) {
    if (capacity < 1) throw std::invalid_argument("capacity must be positive");
    std::map<long long, __LfuEntry> entries;
    std::set<std::tuple<long long, long long, long long>> order;
    std::vector<long long> answers;
    long long clock = 0;
    for (const auto& op : ops) {
        if (op.empty()) throw std::invalid_argument("empty operation");
        long long code = op[0];
        if (code == 1) {
            if (op.size() != 3) throw std::invalid_argument("put needs a key and a value");
            if (op[1] < 0 || op[2] < 0) throw std::invalid_argument("values must not be negative");
            ++clock;
            auto found = entries.find(op[1]);
            if (found != entries.end()) {
                order.erase({found->second.uses, found->second.stamp, op[1]});
                found->second.value = op[2];
                found->second.uses += 1;
                found->second.stamp = clock;
                order.insert({found->second.uses, clock, op[1]});
                continue;
            }
            if ((int)entries.size() == capacity) {
                long long victim = std::get<2>(*order.begin());
                order.erase(order.begin());
                entries.erase(victim);
            }
            entries[op[1]] = __LfuEntry{op[2], 1, clock};
            order.insert({1, clock, op[1]});
        } else if (code == 2) {
            if (op.size() != 2) throw std::invalid_argument("get needs a key");
            ++clock;
            auto found = entries.find(op[1]);
            if (found == entries.end()) {
                answers.push_back(-1);
                continue;
            }
            order.erase({found->second.uses, found->second.stamp, op[1]});
            found->second.uses += 1;
            found->second.stamp = clock;
            order.insert({found->second.uses, clock, op[1]});
            answers.push_back(found->second.value);
        } else if (code == 3) {
            if (op.size() != 1) throw std::invalid_argument("size takes no operand");
            answers.push_back((long long)entries.size());
        } else {
            throw std::invalid_argument("unknown operation");
        }
    }
    return answers;
}
