            return true;
        }
    }
    return false;
}

int max_matching(int left, int right, std::vector<std::pair<int, int>> edges) {
    if (left < 0 || right < 0) throw std::invalid_argument("sides must not be negative");
    std::vector<std::vector<int>> links((size_t)left);
    std::vector<std::unordered_set<int>> dedupe((size_t)left);
    for (const auto& edge : edges) {
        if (edge.first < 0 || edge.first >= left || edge.second < 0 || edge.second >= right) {
            throw std::invalid_argument("endpoint out of range");
        }
        if (!dedupe[(size_t)edge.first].insert(edge.second).second) continue;
        links[(size_t)edge.first].push_back(edge.second);
    }
    std::vector<int> owner((size_t)right, -1);
    std::vector<int> visited((size_t)right, -1);
    int matched = 0;
    for (int node = 0; node < left; ++node) {
        if (__augment(node, links, owner, visited, node)) ++matched;
    }
    return matched;
}
