#include <string>
#include <vector>

long long boolean_ways(std::string symbols, std::string operators) {
    if (symbols.empty()) throw std::invalid_argument("at least one symbol is needed");
    if (operators.size() + 1 != symbols.size()) {
        throw std::invalid_argument("symbols and operators do not line up");
    }
    for (char symbol : symbols) {
        if (symbol != 'T' && symbol != 'F') throw std::invalid_argument("symbols are T or F");
    }
    for (char op : operators) {
        if (op != '&' && op != '|' && op != '^') throw std::invalid_argument("bad operator");
    }
    const long long mod = 1000000007LL;
    int n = (int)symbols.size();
    std::vector<std::vector<long long>> truth((size_t)n, std::vector<long long>((size_t)n, 0));
    std::vector<std::vector<long long>> lies((size_t)n, std::vector<long long>((size_t)n, 0));
    for (int i = 0; i < n; ++i) {
        truth[(size_t)i][(size_t)i] = symbols[(size_t)i] == 'T' ? 1 : 0;
        lies[(size_t)i][(size_t)i] = symbols[(size_t)i] == 'T' ? 0 : 1;
    }
    for (int span = 2; span <= n; ++span) {
        for (int start = 0; start + span - 1 < n; ++start) {
            int stop = start + span - 1;
            long long yes = 0;
            long long no = 0;
            for (int cut = start; cut < stop; ++cut) {
                long long lt = truth[(size_t)start][(size_t)cut];
                long long lf = lies[(size_t)start][(size_t)cut];
                long long rt = truth[(size_t)cut + 1][(size_t)stop];
                long long rf = lies[(size_t)cut + 1][(size_t)stop];
                char op = operators[(size_t)cut];
                if (op == '&') {
                    yes += lt * rt % mod;
                    no += (lf * rf + lf * rt + lt * rf) % mod;
                } else if (op == '|') {
                    yes += (lt * rt + lt * rf + lf * rt) % mod;
                    no += lf * rf % mod;
                } else {
                    yes += (lt * rf + lf * rt) % mod;
                    no += (lt * rt + lf * rf) % mod;
                }
                yes %= mod;
                no %= mod;
            }
            truth[(size_t)start][(size_t)stop] = yes;
            lies[(size_t)start][(size_t)stop] = no;
        }
    }
    return truth[0][(size_t)n - 1];
}
