std::vector<std::pair<int, int>> skyline(std::vector<std::vector<long long>> buildings) {
    std::vector<std::pair<long long, long long>> events;
    for (const auto& building : buildings) {
        if (building.size() != 3) throw std::invalid_argument("a building is {left, right, height}");
        if (building[1] <= building[0]) throw std::invalid_argument("right must exceed left");
        if (building[2] <= 0) throw std::invalid_argument("heights must be positive");
        events.push_back({building[0], -building[2]});
        events.push_back({building[1], building[2]});
    }
    if (events.empty()) return {};
    std::sort(events.begin(), events.end());
    std::map<long long, int> live;
    std::vector<std::pair<int, int>> outline;
    size_t index = 0;
    long long previous = 0;
    while (index < events.size()) {
        long long position = events[index].first;
        while (index < events.size() && events[index].first == position) {
            long long signed_height = events[index].second;
            if (signed_height < 0) {
                live[-signed_height] += 1;
            } else {
                auto found = live.find(signed_height);
                if (found != live.end()) {
                    if (--found->second == 0) live.erase(found);
                }
            }
            ++index;
        }
        long long top = live.empty() ? 0 : live.rbegin()->first;
        if (top != previous) {
            outline.push_back({(int)position, (int)top});
            previous = top;
        }
    }
    if (outline.empty() || outline.back().second != 0) outline.push_back({(int)events.back().first, 0});
    return outline;
}
