std::vector<long long> median_stream(std::vector<std::vector<long long>> ops) {
    std::multiset<long long> low;
    std::multiset<long long> high;
    std::vector<long long> medians;
    for (const auto& op : ops) {
        if (op.empty()) throw std::invalid_argument("empty operation");
        long long code = op[0];
        if (code == 1) {
            if (op.size() != 2) throw std::invalid_argument("insert needs one value");
            long long value = op[1];
            if (low.empty() || value <= *low.rbegin()) low.insert(value);
            else high.insert(value);
        } else if (code == 2) {
            if (op.size() != 2) throw std::invalid_argument("erase needs one value");
            long long value = op[1];
            auto in_low = low.find(value);
            if (in_low != low.end()) low.erase(in_low);
            else {
                auto in_high = high.find(value);
                if (in_high == high.end()) throw std::invalid_argument("value not present");
                high.erase(in_high);
            }
        } else if (code == 3) {
            if (op.size() != 1) throw std::invalid_argument("median takes no operand");
            medians.push_back(low.empty() ? -1 : *low.rbegin());
            continue;
        } else {
            throw std::invalid_argument("unknown operation");
        }
        while (low.size() > high.size() + 1) {
            auto it = std::prev(low.end());
            high.insert(*it);
            low.erase(it);
        }
        while (low.size() < high.size()) {
            low.insert(*high.begin());
            high.erase(high.begin());
        }
    }
    return medians;
}
