    }
    long long year = std::stoll(text.substr(0, 4));
    int month = std::stoi(text.substr(5, 2));
    int day = std::stoi(text.substr(8, 2));
    if (month < 1 || month > 12) throw std::invalid_argument("month out of range");
    if (day < 1 || day > __monthLength(year, month)) throw std::invalid_argument("day out of range");
    if (year < 1900 || year > 2100) throw std::invalid_argument("year out of range");
    // days since 1970-01-01, after Howard Hinnant's civil_from_days
    long long shifted = year - (month <= 2 ? 1 : 0);
    long long era = (shifted >= 0 ? shifted : shifted - 399) / 400;
    long long yearOfEra = shifted - era * 400;
    long long dayOfYear = (153 * (month + (month > 2 ? -3 : 9)) + 2) / 5 + day - 1;
    long long dayOfEra = yearOfEra * 365 + yearOfEra / 4 - yearOfEra / 100 + dayOfYear;
    return era * 146097 + dayOfEra - 719468;
}

long long business_days(std::string from, std::string to, std::vector<std::string> holidays) {
    long long first = __dayNumber(from);
    long long last = __dayNumber(to);
    std::unordered_set<long long> off;
    for (const std::string& holiday : holidays) off.insert(__dayNumber(holiday));
    long long busy = 0;
    for (long long day = first; day < last; ++day) {
        long long weekday = ((day % 7) + 7 + 4) % 7;  // 0 = Sunday, 1970-01-01 was a Thursday
        if (weekday == 0 || weekday == 6) continue;
        if (off.count(day)) continue;
        ++busy;
    }
    return busy;
}
