std::vector<long long> split_amount(long long total, std::vector<long long> weights) {
    if (total < 0) throw std::invalid_argument("total must not be negative");
    if (weights.empty()) throw std::invalid_argument("at least one weight is needed");
    __int128 whole = 0;
    for (long long weight : weights) {
        if (weight < 0) throw std::invalid_argument("weights must not be negative");
        whole += weight;
    }
    if (whole == 0) throw std::invalid_argument("weights must not all be zero");
    std::vector<long long> shares(weights.size(), 0);
    std::vector<std::pair<long long, size_t>> remainders;
    long long given = 0;
    for (size_t i = 0; i < weights.size(); ++i) {
        __int128 exact = (__int128)total * weights[i];
        long long base = (long long)(exact / whole);
        long long rest = (long long)(exact % whole);
        shares[i] = base;
        given += base;
        if (rest > 0) remainders.push_back({-rest, i});
    }
    std::sort(remainders.begin(), remainders.end());
    long long left = total - given;
    for (long long step = 0; step < left; ++step) shares[remainders[(size_t)step].second] += 1;
    return shares;
}
