#include <cassert>
#include <stdexcept>
#include <string>
#include <vector>

static size_t __classEnd(const std::string& pattern, size_t open) {
    size_t index = open + 1;
    if (index < pattern.size() && (pattern[index] == '!' || pattern[index] == '^')) ++index;
    bool any = false;
    while (index < pattern.size() && pattern[index] != ']') {
        if (index + 2 < pattern.size() && pattern[index + 1] == '-' && pattern[index + 2] != ']') {
            if (pattern[index + 2] < pattern[index]) throw std::invalid_argument("backwards range");
            index += 3;
        } else {
            ++index;
        }
        any = true;
    }
    if (index >= pattern.size()) throw std::invalid_argument("unclosed class");
    if (!any) throw std::invalid_argument("empty class");
    return index;
}

static bool __classHolds(const std::string& pattern, size_t open, size_t close, char letter) {
    size_t index = open + 1;
    bool negated = false;
    if (index < close && (pattern[index] == '!' || pattern[index] == '^')) {
        negated = true;
        ++index;
    }
    bool found = false;
    while (index < close) {
        if (index + 2 < close && pattern[index + 1] == '-') {
            char low = pattern[index];
            char high = pattern[index + 2];
            if (letter >= low && letter <= high) found = true;
            index += 3;
        } else {
            if (letter == pattern[index]) found = true;
            ++index;
        }
    }
    return negated ? !found : found;
}

bool glob_match(std::string pattern, std::string text) {
    size_t m = pattern.size();
    size_t n = text.size();
    std::vector<char> previous(n + 1, 0);
    std::vector<char> current(n + 1, 0);
    previous[0] = 1;
    for (size_t i = 0; i < m; ++i) {
        char token = pattern[i];
        if (token == '[') {
            size_t close = __classEnd(pattern, i);
            std::fill(current.begin(), current.end(), 0);
            for (size_t j = 1; j <= n; ++j) {
                if (!previous[j - 1]) continue;
                if (__classHolds(pattern, i, close, text[j - 1])) current[j] = 1;
            }
            i = close;
        } else if (token == '*') {
            current[0] = previous[0];
            for (size_t j = 1; j <= n; ++j) current[j] = (char)(previous[j] || current[j - 1]);
        } else {
            std::fill(current.begin(), current.end(), 0);
            for (size_t j = 1; j <= n; ++j) {
                if (!previous[j - 1]) continue;
                if (token == '?' || token == text[j - 1]) current[j] = 1;
            }
        }
        previous.swap(current);
    }
    return previous[n] != 0;
}
