#include <cassert>
#include <queue>
#include <stdexcept>
#include <vector>

std::vector<std::vector<long long>> project_times(std::vector<long long> durations,
                                                 std::vector<std::vector<long long>> deps) {
    int n = (int)durations.size();
    for (long long length : durations) {
        if (length < 0) throw std::invalid_argument("durations must not be negative");
    }
    std::vector<std::vector<int>> following((size_t)n);
    std::vector<std::vector<int>> previous((size_t)n);
    std::vector<int> indegree((size_t)n, 0);
    for (const auto& dep : deps) {
        if (dep.size() != 2) throw std::invalid_argument("a dependency is {before, after}");
        long long before = dep[0];
        long long after = dep[1];
        if (before < 0 || before >= n || after < 0 || after >= n) {
            throw std::invalid_argument("endpoint out of range");
        }
        following[(size_t)before].push_back((int)after);
        previous[(size_t)after].push_back((int)before);
        indegree[(size_t)after] += 1;
    }
    std::vector<long long> earliest((size_t)n, 0);
    std::vector<int> order;
    std::queue<int> ready;
    for (int task = 0; task < n; ++task) {
        if (indegree[(size_t)task] == 0) ready.push(task);
    }
    while (!ready.empty()) {
        int task = ready.front();
        ready.pop();
        order.push_back(task);
        for (int next : following[(size_t)task]) {
            long long start = earliest[(size_t)task] + durations[(size_t)task];
            if (start > earliest[(size_t)next]) earliest[(size_t)next] = start;
            if (--indegree[(size_t)next] == 0) ready.push(next);
        }
    }
    if ((int)order.size() != n) return {};
    long long project = 0;
    for (int task = 0; task < n; ++task) {
        long long finish = earliest[(size_t)task] + durations[(size_t)task];
        if (finish > project) project = finish;
    }
    std::vector<long long> tail((size_t)n, 0);
    for (auto it = order.rbegin(); it != order.rend(); ++it) {
        int task = *it;
        long long longest = 0;
        for (int next : following[(size_t)task]) {
            if (tail[(size_t)next] > longest) longest = tail[(size_t)next];
        }
        tail[(size_t)task] = durations[(size_t)task] + longest;
    }
    std::vector<std::vector<long long>> result;
    for (int task = 0; task < n; ++task) {
        result.push_back({earliest[(size_t)task], project - tail[(size_t)task]});
    }
    return result;
}
