#include <algorithm>
#include <cassert>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

static std::string __trim(const std::string& text) {
    size_t first = text.find_first_not_of(" \t\r\n");
    if (first == std::string::npos) return std::string();
    size_t last = text.find_last_not_of(" \t\r\n");
    return text.substr(first, last - first + 1);
}

std::vector<std::string> parse_ini(std::vector<std::string> lines) {
    std::map<std::string, std::string> stored;
    std::string section;
    for (const std::string& raw : lines) {
        std::string line = __trim(raw);
        if (line.empty() || line[0] == '#' || line[0] == ';') continue;
        if (line[0] == '[') {
            if (line.back() != ']') throw std::invalid_argument("bad section header");
            std::string name = __trim(line.substr(1, line.size() - 2));
            if (name.empty()) throw std::invalid_argument("empty section name");
            if (name.find(']') != std::string::npos) {
                throw std::invalid_argument("text after the section header");
            }
            section = name;
            continue;
        }
        size_t equals = line.find('=');
        if (equals == std::string::npos) throw std::invalid_argument("a setting needs an equals sign");
        std::string key = __trim(line.substr(0, equals));
        std::string value = __trim(line.substr(equals + 1));
        if (key.empty()) throw std::invalid_argument("empty key");
        if (key.find('[') != std::string::npos || key.find(']') != std::string::npos) {
            throw std::invalid_argument("a key must not hold brackets");
        }
        stored[section.empty() ? key : section + "." + key] = value;
    }
    std::vector<std::string> result;
    for (const auto& entry : stored) result.push_back(entry.first + "=" + entry.second);
    return result;
}
