#include <stdexcept>
#include <string>
#include <vector>

long long distinct_subsequences(std::string text, long long modulus) {
    if (modulus < 1) throw std::invalid_argument("modulus must be positive");
    std::vector<long long> last(256, 0);
    long long total = 1 % modulus;  // the empty subsequence
    for (unsigned char letter : text) {
        long long grown = total * 2 % modulus;
        long long removed = last[letter];
        long long updated = (grown - removed) % modulus;
        if (updated < 0) updated += modulus;
        last[letter] = total;
        total = updated;
    }
    long long answer = (total - 1) % modulus;
    if (answer < 0) answer += modulus;
    return answer;
}
