#include <algorithm>
#include <cassert>
#include <stdexcept>
#include <utility>
#include <vector>

std::vector<int> component_sizes(int n, std::vector<std::pair<int, int>> edges) {
    if (n < 0) throw std::invalid_argument("node count must not be negative");
    std::vector<std::vector<int>> forward((size_t)n);
    std::vector<std::vector<int>> backward((size_t)n);
    for (const auto& edge : edges) {
        if (edge.first < 0 || edge.first >= n || edge.second < 0 || edge.second >= n) {
            throw std::invalid_argument("endpoint out of range");
        }
        forward[(size_t)edge.first].push_back(edge.second);
        backward[(size_t)edge.second].push_back(edge.first);
    }
    std::vector<char> seen((size_t)n, 0);
    std::vector<int> order;
    order.reserve((size_t)n);
    for (int start = 0; start < n; ++start) {
        if (seen[(size_t)start]) continue;
        seen[(size_t)start] = 1;
        std::vector<std::pair<int, size_t>> stack;
        stack.push_back({start, 0});
        while (!stack.empty()) {
            int node = stack.back().first;
            size_t& cursor = stack.back().second;
            if (cursor < forward[(size_t)node].size()) {
                int next = forward[(size_t)node][cursor++];
                if (!seen[(size_t)next]) {
                    seen[(size_t)next] = 1;
                    stack.push_back({next, 0});
                }
                continue;
            }
            order.push_back(node);
            stack.pop_back();
        }
    }
    std::fill(seen.begin(), seen.end(), 0);
    std::vector<int> sizes;
    for (auto it = order.rbegin(); it != order.rend(); ++it) {
        int start = *it;
        if (seen[(size_t)start]) continue;
        int members = 0;
        std::vector<int> stack{start};
        seen[(size_t)start] = 1;
        while (!stack.empty()) {
            int here = stack.back();
            stack.pop_back();
            ++members;
            for (int previous : backward[(size_t)here]) {
                if (seen[(size_t)previous]) continue;
                seen[(size_t)previous] = 1;
                stack.push_back(previous);
            }
        }
        sizes.push_back(members);
    }
    std::sort(sizes.begin(), sizes.end());
    return sizes;
}
