std::vector<std::string> directory_sizes(std::vector<std::pair<std::string, long long>> files) {
    std::map<std::string, long long> totals;
    for (const auto& file : files) {
        const std::string& path = file.first;
        if (file.second < 0) throw std::invalid_argument("sizes must not be negative");
        if (path.empty() || path.front() == '/' || path.back() == '/') {
            throw std::invalid_argument("paths are relative and non-empty");
        }
        std::vector<std::string> parts;
        size_t at = 0;
        while (true) {
            size_t slash = path.find('/', at);
            std::string part = slash == std::string::npos ? path.substr(at) : path.substr(at, slash - at);
            if (part.empty()) throw std::invalid_argument("empty path part");
            parts.push_back(part);
            if (slash == std::string::npos) break;
            at = slash + 1;
        }
        std::string prefix;
        for (size_t i = 0; i + 1 < parts.size(); ++i) {
            if (i > 0) prefix += "/";
            prefix += parts[i];
            totals[prefix] += file.second;
        }
    }
    std::vector<std::string> result;
    for (const auto& entry : totals) result.push_back(entry.first + " " + std::to_string(entry.second));
    return result;
}
