long long cooldown_time(std::vector<std::string> tasks, int cooldown) {
    if (cooldown < 0) throw std::invalid_argument("cooldown must not be negative");
    std::map<std::string, long long> counts;
    for (const std::string& task : tasks) {
        if (task.size() != 1) throw std::invalid_argument("a task name is one character");
        counts[task] += 1;
    }
    if (counts.empty()) return 0;
    long long busiest = 0;
    long long tied = 0;
    for (const auto& entry : counts) {
        if (entry.second > busiest) {
            busiest = entry.second;
            tied = 1;
        } else if (entry.second == busiest) {
            tied += 1;
        }
    }
    long long spaced = (busiest - 1) * (cooldown + 1) + tied;
    long long total = (long long)tasks.size();
    return std::max(spaced, total);
}
