#include <algorithm>
#include <cassert>
#include <stdexcept>
#include <vector>

long long min_assignment(std::vector<std::vector<long long>> cost) {
    int n = (int)cost.size();
    for (const auto& row : cost) {
        if ((int)row.size() != n) throw std::invalid_argument("the cost matrix must be square");
    }
    if (n == 0) return 0;
    const long long far = 4000000000000000000LL;
    std::vector<long long> best((size_t)(1 << n), far);
    best[0] = 0;
    for (int mask = 0; mask < (1 << n); ++mask) {
        if (best[(size_t)mask] == far) continue;
        int worker = __builtin_popcount((unsigned)mask);
        if (worker == n) continue;
        for (int job = 0; job < n; ++job) {
            if ((mask >> job) & 1) continue;
            long long candidate = best[(size_t)mask] + cost[(size_t)worker][(size_t)job];
            int next = mask | (1 << job);
            if (candidate < best[(size_t)next]) best[(size_t)next] = candidate;
        }
    }
    return best[(size_t)((1 << n) - 1)];
}
