long long floor_sum(long long count, long long divisor, long long slope, long long offset) {
    if (count < 0) throw std::invalid_argument("count must not be negative");
    if (divisor <= 0) throw std::invalid_argument("divisor must be positive");
    if (slope < 0 || offset < 0) throw std::invalid_argument("slope and offset must not be negative");
    long long total = 0;
    while (true) {
        if (slope >= divisor) {
            total += (count - 1) * count / 2 * (slope / divisor);
            slope %= divisor;
        }
        if (offset >= divisor) {
            total += count * (offset / divisor);
            offset %= divisor;
        }
        long long top = slope * count + offset;
        if (top < divisor) return total;
        count = top / divisor;
        offset = top % divisor;
        long long swapped = divisor;
        divisor = slope;
        slope = swapped;
    }
}
