    ys.erase(std::unique(ys.begin(), ys.end()), ys.end());
    std::vector<__Edge> edges;
    for (const auto& rectangle : rectangles) {
        int low = (int)(std::lower_bound(ys.begin(), ys.end(), rectangle[1]) - ys.begin());
        int high = (int)(std::lower_bound(ys.begin(), ys.end(), rectangle[3]) - ys.begin());
        edges.push_back({rectangle[0], low, high, 1});
        edges.push_back({rectangle[2], low, high, -1});
    }
    std::sort(edges.begin(), edges.end(), [](const __Edge& left, const __Edge& right) {
        return left.x < right.x;
    });
    std::vector<int> cover(ys.size() + 1, 0);
    long long area = 0;
    long long previous = edges[0].x;
    size_t index = 0;
    while (index < edges.size()) {
        long long here = edges[index].x;
        long long covered = 0;
        for (size_t segment = 0; segment + 1 < ys.size(); ++segment) {
            if (cover[segment] > 0) covered += ys[segment + 1] - ys[segment];
        }
        area += covered * (here - previous);
