def edit_cost(source, target, insert, delete, replace):
    if insert < 0 or delete < 0 or replace < 0:
        raise ValueError("costs must not be negative")
    if source == target:
        return 0
    if not source:
        return insert * len(target)
    if not target:
        return delete * len(source)
    previous = [index * insert for index in range(len(target) + 1)]
    for row, source_char in enumerate(source, start=1):
        current = [row * delete]
        for column, target_char in enumerate(target, start=1):
            best = previous[column - 1] if source_char == target_char else previous[column - 1] + replace
            best = min(best, previous[column] + delete, current[column - 1] + insert)
            current.append(best)
        previous = current
    return previous[-1]
