def _month_length(year, month):
    if month == 2:
        leap = (year % 4 == 0 and year % 100 != 0) or year % 400 == 0
        return 29 if leap else 28
    if month in (4, 6, 9, 11):
        return 30
    return 31


def _parse_date(text):
    if not isinstance(text, str) or len(text) != 10 or text[4] != "-" or text[7] != "-":
        raise ValueError("dates are YYYY-MM-DD")
    for index in (0, 1, 2, 3, 5, 6, 8, 9):
        if text[index] < "0" or text[index] > "9":
            raise ValueError("dates are digits")
    year = int(text[:4])
    month = int(text[5:7])
    day = int(text[8:])
    if month < 1 or month > 12:
        raise ValueError("month out of range")
    if day < 1 or day > _month_length(year, month):
        raise ValueError("day out of range")
    return year, month, day


def monthly_occurrences(start, day_of_month, count):
    year, month, day = _parse_date(start)
    if day_of_month < 1 or day_of_month > 31:
        raise ValueError("day_of_month must be 1..31")
    if count < 0:
        raise ValueError("count must not be negative")
    dates = []
    clamped = min(day_of_month, _month_length(year, month))
    if clamped < day:
        month += 1
        if month == 13:
            month = 1
            year += 1
    while len(dates) < count:
        clamped = min(day_of_month, _month_length(year, month))
        dates.append("%04d-%02d-%02d" % (year, month, clamped))
        month += 1
        if month == 13:
            month = 1
            year += 1
    return dates
