import bisect


def sliding_kth_largest(values, window, kth):
    if window < 1:
        raise ValueError("window must be at least 1")
    if kth < 1 or kth > window:
        raise ValueError("kth must be inside 1..window")
    if len(values) < window:
        raise ValueError("the window does not fit")
    ordered = []
    answers = []
    for index, value in enumerate(values):
        bisect.insort(ordered, value)
        if index >= window:
            stale = values[index - window]
            del ordered[bisect.bisect_left(ordered, stale)]
        if index >= window - 1:
            answers.append(ordered[len(ordered) - kth])
    return answers
