def merge_accounts(accounts):
    owner = {}
    parent = {}

    def find(email):
        while parent[email] != email:
            parent[email] = parent[parent[email]]
            email = parent[email]
        return email

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return
        if left_root < right_root:
            parent[right_root] = left_root
        else:
            parent[left_root] = right_root

    for account in accounts:
        if not account or not account[0]:
            raise ValueError("an account needs a name")
        emails = account[1:]
        if not emails:
            raise ValueError("an account needs an email")
        for email in emails:
            if not isinstance(email, str) or "@" not in email or email.startswith("@"):
                raise ValueError("bad email: %r" % (email,))
            if email in owner and owner[email] != account[0]:
                raise ValueError("email %r belongs to two names" % (email,))
            owner[email] = account[0]
            parent.setdefault(email, email)
        for email in emails[1:]:
            union(emails[0], email)
    groups = {}
    for email in parent:
        groups.setdefault(find(email), []).append(email)
    merged = []
    for emails in groups.values():
        merged.append([owner[find(emails[0])], sorted(emails)])
    merged.sort()
    return merged
