def weighted_percentile(pairs, percent):
    if not pairs:
        raise ValueError("at least one pair is needed")
    if percent < 1 or percent > 100:
        raise ValueError("percent must be 1..100")
    weights = {}
    total = 0
    for pair in pairs:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError("a pair is (value, weight)")
        value, weight = pair
        if weight <= 0:
            raise ValueError("weights must be positive")
        weights[value] = weights.get(value, 0) + weight
        total += weight
    running = 0
    for value in sorted(weights):
        running += weights[value]
        if running * 100 >= percent * total:
            return value
    return sorted(weights)[-1]
