from bisect import bisect_right


def versioned_store(ops):
    history = {}
    clock = 0
    answers = []
    for op in ops:
        if not isinstance(op, tuple) or not op:
            raise ValueError("an operation is a non-empty tuple")
        code = op[0]
        if code == 1:
            if len(op) != 3:
                raise ValueError("a write is (1, key, value)")
            clock += 1
            history.setdefault(op[1], []).append((clock, op[2]))
            continue
        if code != 2:
            raise ValueError("unknown operation: %r" % (code,))
        if len(op) != 3:
            raise ValueError("a read is (2, key, version)")
        version = op[2]
        if version < 0:
            raise ValueError("versions must not be negative")
        if version > clock:
            raise ValueError("version %r is in the future" % (version,))
        stamps = history.get(op[1])
        if not stamps:
            answers.append(None)
            continue
        position = bisect_right([stamp for stamp, _ in stamps], version) - 1
        answers.append(None if position < 0 else stamps[position][1])
    return answers
