def diff_dicts(old, new):
    if not isinstance(old, dict) or not isinstance(new, dict):
        raise ValueError("both sides must be dicts")
    entries = []

    def walk(left, right, prefix):
        for key in left:
            path = "%s.%s" % (prefix, key) if prefix else str(key)
            if key not in right:
                entries.append(path + ":removed")
                continue
            before = left[key]
            after = right[key]
            if isinstance(before, dict) and isinstance(after, dict):
                walk(before, after, path)
            elif before != after:
                entries.append(path + ":changed")
        for key in right:
            if key in left:
                continue
            path = "%s.%s" % (prefix, key) if prefix else str(key)
            entries.append(path + ":added")

    walk(old, new, "")
    entries.sort()
    return entries
