def dependency_order(tasks, deps):
    for name, duration in tasks.items():
        if duration < 0:
            raise ValueError("durations must not be negative")
    following = {name: [] for name in tasks}
    waiting = {name: 0 for name in tasks}
    for dep in deps:
        if not isinstance(dep, tuple) or len(dep) != 2:
            raise ValueError("a dependency is a (before, after) pair")
        before, after = dep
        if before not in tasks or after not in tasks:
            raise ValueError("unknown task in %r" % (dep,))
        if before == after:
            raise ValueError("a task cannot depend on itself")
        following[before].append(after)
        waiting[after] += 1
    ready = [name for name in tasks if waiting[name] == 0]
    order = []
    while ready:
        ready.sort(key=lambda name: (tasks[name], name))
        name = ready.pop(0)
        order.append(name)
        for neighbour in following[name]:
            waiting[neighbour] -= 1
            if waiting[neighbour] == 0:
                ready.append(neighbour)
    if len(order) != len(tasks):
        raise ValueError("dependency cycle")
    return order
