def _orientation(origin, first, second):
    return ((first[0] - origin[0]) * (second[1] - origin[1])
            - (first[1] - origin[1]) * (second[0] - origin[0]))


def _on_segment(start, end, point):
    return (min(start[0], end[0]) <= point[0] <= max(start[0], end[0])
            and min(start[1], end[1]) <= point[1] <= max(start[1], end[1]))


def _segments_meet(first, second):
    (a1, a2), (b1, b2) = first, second
    d1 = _orientation(b1, b2, a1)
    d2 = _orientation(b1, b2, a2)
    d3 = _orientation(a1, a2, b1)
    d4 = _orientation(a1, a2, b2)
    if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
            ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
        return True
    if d1 == 0 and _on_segment(b1, b2, a1):
        return True
    if d2 == 0 and _on_segment(b1, b2, a2):
        return True
    if d3 == 0 and _on_segment(a1, a2, b1):
        return True
    if d4 == 0 and _on_segment(a1, a2, b2):
        return True
    return False


def count_crossings(segments):
    for segment in segments:
        if not isinstance(segment, tuple) or len(segment) != 2:
            raise ValueError("a segment is a pair of points")
        for point in segment:
            if not isinstance(point, tuple) or len(point) != 2:
                raise ValueError("a point is an (x, y) pair")
    crossings = 0
    for left in range(len(segments)):
        for right in range(left + 1, len(segments)):
            if _segments_meet(segments[left], segments[right]):
                crossings += 1
    return crossings
