def bounded_coins(coins, counts, amount):
    if len(coins) != len(counts):
        raise ValueError("coins and counts must line up")
    if amount < 0:
        raise ValueError("amount must not be negative")
    items = []
    for coin, limit in zip(coins, counts):
        if coin <= 0:
            raise ValueError("coin values must be positive")
        if limit < 0:
            raise ValueError("counts must not be negative")
        take = 1
        remaining = limit
        while remaining > 0:
            bundle = min(take, remaining)
            items.append((coin * bundle, bundle))
            remaining -= bundle
            take *= 2
    unreachable = amount + 1
    best = [unreachable] * (amount + 1)
    best[0] = 0
    for value, used in items:
        for total in range(amount, value - 1, -1):
            if best[total - value] + used < best[total]:
                best[total] = best[total - value] + used
    return -1 if best[amount] == unreachable else best[amount]
```

