def render_template(template, values):
    if not isinstance(template, str):
        raise ValueError("the template must be a string")
    if not isinstance(values, dict):
        raise ValueError("values must be a dict")
    result = []
    index = 0
    length = len(template)
    while index < length:
        char = template[index]
        if char == "\\" and template[index + 1:index + 3] in ("{{", "}}"):
            result.append(template[index + 1:index + 3])
            index += 3
            continue
        if char == "}" and template[index:index + 2] == "}}":
            raise ValueError("closing braces without an opener")
        if template[index:index + 2] != "{{":
            result.append(char)
            index += 1
            continue
        close = template.find("}}", index + 2)
        if close < 0:
            raise ValueError("unclosed placeholder")
        name = template[index + 2:close].strip()
        optional = name.endswith("?")
        if optional:
            name = name[:-1].strip()
        if not name:
            raise ValueError("empty placeholder")
        if not all(letter.isalnum() or letter in "_-" for letter in name):
            raise ValueError("bad placeholder name: %r" % (name,))
        if name in values:
            result.append(str(values[name]))
        elif not optional:
            raise ValueError("missing value for %r" % (name,))
        index = close + 2
    return "".join(result)
```

