def minesweeper_reveal(board, click):
    if not isinstance(board, list) or not board:
        raise ValueError("the board must be a non-empty list of rows")
    width = len(board[0])
    for row in board:
        if len(row) != width:
            raise ValueError("rows must share one width")
        for cell in row:
            if cell not in "*.":
                raise ValueError("cells are '*' or '.'")
    height = len(board)
    row_of_click, column_of_click = click
    if not (0 <= row_of_click < height and 0 <= column_of_click < width):
        raise ValueError("click is outside the board")

    def nearby_mines(row, column):
        total = 0
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                rr, cc = row + dr, column + dc
                if 0 <= rr < height and 0 <= cc < width and board[rr][cc] == "*":
                    total += 1
        return total

    shown = [list(row) for row in board]
    if board[row_of_click][column_of_click] == "*":
        for row in range(height):
            for column in range(width):
                if shown[row][column] != "*":
                    shown[row][column] = str(nearby_mines(row, column))
        return ["".join(row) for row in shown]
    pending = [(row_of_click, column_of_click)]
    while pending:
        row, column = pending.pop()
        if shown[row][column] != ".":
            continue
        count = nearby_mines(row, column)
        shown[row][column] = str(count)
        if count:
            continue
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = row + dr, column + dc
                if 0 <= rr < height and 0 <= cc < width and shown[rr][cc] == ".":
                    pending.append((rr, cc))
    return ["".join(row) for row in shown]
