from math import gcd


def _reduce(numerator, denominator):
    if denominator < 0:
        numerator, denominator = -numerator, -denominator
    divisor = gcd(abs(numerator), denominator) or 1
    return numerator // divisor, denominator // divisor


def fraction_expression(expression):
    if not isinstance(expression, str) or not expression.strip():
        raise ValueError("the expression must not be empty")
    text = "".join(expression.split())
    numerator, denominator = 0, 1
    index = 0
    first = True
    sign = 1
    while index < len(text):
        if text[index] in "+-":
            sign = -1 if text[index] == "-" else 1
            index += 1
            if index >= len(text):
                raise ValueError("a term is missing")
        elif not first:
            raise ValueError("terms must be joined by + or -")
        start = index
        while index < len(text) and text[index].isdigit():
            index += 1
        if start == index:
            raise ValueError("bad term in %r" % (text,))
        term_numerator = int(text[start:index])
        term_denominator = 1
        if index < len(text) and text[index] == "/":
            index += 1
            start = index
            while index < len(text) and text[index].isdigit():
                index += 1
            if start == index:
                raise ValueError("bad denominator in %r" % (text,))
            term_denominator = int(text[start:index])
            if term_denominator == 0:
                raise ValueError("a denominator must not be zero")
        numerator = numerator * term_denominator + sign * term_numerator * denominator
        denominator *= term_denominator
        numerator, denominator = _reduce(numerator, denominator)
        first = False
        sign = 1
    if numerator == 0:
        return "0"
    if denominator == 1:
        return str(numerator)
    return "%d/%d" % (numerator, denominator)
