import re

CELL = re.compile(r"^[A-Z]+[0-9]+$")


def evaluate_cells(raw):
    values = {}

    def resolve(name, trail):
        if name in values:
            return values[name]
        if name not in raw:
            raise ValueError("unknown cell %r" % (name,))
        if name in trail:
            raise ValueError("circular reference at %r" % (name,))
        text = raw[name]
        if not isinstance(text, str) or not text.strip():
            raise ValueError("empty cell %r" % (name,))
        body = text.strip()
        if not body.startswith("="):
            if not body.isdigit():
                raise ValueError("bad cell %r" % (name,))
            return int(body)
        body = body[1:].strip()
        if body.startswith("SUM(") and body.endswith(")"):
            span = body[4:-1].strip()
            if ":" not in span:
                raise ValueError("bad range %r" % (span,))
            start, _, stop = span.partition(":")
            start, stop = start.strip(), stop.strip()
            if not CELL.match(start) or not CELL.match(stop):
                raise ValueError("bad range %r" % (span,))
            letters_start = re.match(r"([A-Z]+)([0-9]+)", start).group(1)
            letters_stop = re.match(r"([A-Z]+)([0-9]+)", stop).group(1)
            low = int(re.match(r"[A-Z]+([0-9]+)", start).group(1))
            high = int(re.match(r"[A-Z]+([0-9]+)", stop).group(1))
            if letters_start != letters_stop or low > high:
                raise ValueError("bad range %r" % (span,))
            return sum(resolve("%s%d" % (letters_start, row), trail | {name})
                       for row in range(low, high + 1))
        total = 0
        for part in body.split("+"):
            piece = part.strip()
            if not piece:
                raise ValueError("bad formula %r" % (text,))
            if CELL.match(piece):
                total += resolve(piece, trail | {name})
            elif piece.isdigit():
                total += int(piece)
            else:
                raise ValueError("bad formula %r" % (text,))
        return total

    for name in raw:
        if not isinstance(name, str) or not CELL.match(name):
            raise ValueError("bad cell name %r" % (name,))
        values[name] = resolve(name, frozenset())
    return dict(sorted(values.items()))
