def bucket_events(events, size, offset):
    if size < 1:
        raise ValueError("the bucket size must be at least 1")
    totals = {}
    for event in events:
        if not isinstance(event, tuple) or len(event) != 2:
            raise ValueError("an event is a (timestamp, value) pair")
        stamp, value = event
        for number in (stamp, value):
            if isinstance(number, bool) or not isinstance(number, int):
                raise ValueError("timestamps and values must be integers")
        start = offset + ((stamp - offset) // size) * size
        count, total = totals.get(start, (0, 0))
        totals[start] = (count + 1, total + value)
    return [(start, count, total) for start, (count, total) in sorted(totals.items())]
