long long grid_cost(std::vector<std::vector<int>> grid, std::vector<std::vector<int>> portals) {
    if (grid.empty()) return -1;
    int rows = (int)grid.size();
    int cols = (int)grid[0].size();
    for (const auto& row : grid) {
        if ((int)row.size() != cols) throw std::invalid_argument("rows must share one width");
        for (int value : row) {
            if (value < 0) throw std::invalid_argument("costs must not be negative");
        }
    }
    std::vector<std::vector<std::pair<int, int>>> pads((size_t)rows * cols);
    for (const auto& portal : portals) {
        if (portal.size() != 4) throw std::invalid_argument("a portal is {r1, c1, r2, c2}");
        for (int index = 0; index < 4; index += 2) {
            if (portal[(size_t)index] < 0 || portal[(size_t)index] >= rows ||
                portal[(size_t)index + 1] < 0 || portal[(size_t)index + 1] >= cols) {
                throw std::invalid_argument("portal cell out of range");
            }
        }
        size_t first = (size_t)portal[0] * cols + portal[1];
        size_t second = (size_t)portal[2] * cols + portal[3];
        pads[first].push_back({portal[2], portal[3]});
        pads[second].push_back({portal[0], portal[1]});
    }
    const long long far = 4000000000000000000LL;
    std::vector<long long> best((size_t)rows * cols, far);
    std::priority_queue<std::pair<long long, int>, std::vector<std::pair<long long, int>>,
                        std::greater<std::pair<long long, int>>> pending;
    best[0] = grid[0][0];
    pending.push({best[0], 0});
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};
    while (!pending.empty()) {
        auto [cost, cell] = pending.top();
        pending.pop();
        if (cost > best[(size_t)cell]) continue;
        int row = cell / cols;
        int col = cell % cols;
        if (row == rows - 1 && col == cols - 1) return cost;
        for (int step = 0; step < 4; ++step) {
            int rr = row + dr[step];
            int cc = col + dc[step];
            if (rr < 0 || rr >= rows || cc < 0 || cc >= cols) continue;
            long long next = cost + grid[(size_t)rr][(size_t)cc];
            size_t slot = (size_t)rr * cols + cc;
            if (next < best[slot]) {
                best[slot] = next;
                pending.push({next, (int)slot});
            }
        }
        for (const auto& jump : pads[(size_t)cell]) {
            size_t slot = (size_t)jump.first * cols + jump.second;
            if (cost < best[slot]) {
                best[slot] = cost;
                pending.push({cost, (int)slot});
            }
        }
    }
    return best.back() == far ? -1 : best.back();
}
