#include <cassert>
#include <stdexcept>
#include <string>

std::string rle_encode(std::string text) {
    std::string code;
    size_t index = 0;
    while (index < text.size()) {
        size_t run = 1;
        while (index + run < text.size() && text[index + run] == text[index]) ++run;
        size_t left = run;
        while (left > 0) {
            size_t take = left > 9 ? 9 : left;
            code += (char)('0' + (int)take);
            code += text[index];
            left -= take;
        }
        index += run;
    }
    return code;
}

std::string rle_decode(std::string code) {
    std::string text;
    size_t index = 0;
    char previous = 0;
    int previousCount = 9;
    while (index < code.size()) {
        char count_char = code[index];
        if (count_char < '1' || count_char > '9') throw std::invalid_argument("bad count");
        if (index + 1 >= code.size()) throw std::invalid_argument("dangling count");
        char letter = code[index + 1];
        if (letter >= '1' && letter <= '9') throw std::invalid_argument("count without a character");
        if (letter == previous && previousCount != 9) {
            throw std::invalid_argument("group could have been merged");
        }
        text.append((size_t)(count_char - '0'), letter);
        previous = letter;
        previousCount = count_char - '0';
        index += 2;
    }
    return text;
}
