std::string reorganize(std::string text) {
    std::vector<int> counts(26, 0);
    for (char letter : text) {
        if (letter < 'a' || letter > 'z') throw std::invalid_argument("lower case letters only");
        counts[(size_t)(letter - 'a')] += 1;
    }
    int total = (int)text.size();
    std::string result;
    result.reserve(text.size());
    char previous = 0;
    while (total > 0) {
        bool placed = false;
        for (int slot = 0; slot < 26; ++slot) {
            if (counts[(size_t)slot] == 0) continue;
            char letter = (char)('a' + slot);
            if (letter == previous) continue;
            counts[(size_t)slot] -= 1;
            int biggest = 0;
            for (int other = 0; other < 26; ++other) biggest = std::max(biggest, counts[(size_t)other]);
            if (2 * biggest <= total) {
                result += letter;
                previous = letter;
                --total;
                placed = true;
                break;
            }
            counts[(size_t)slot] += 1;
        }
        if (!placed) return std::string();
    }
    return result;
}
