    int rightRoot = __find(parent, right);
    if (leftRoot == rightRoot) return;
    if (weight[(size_t)leftRoot] < weight[(size_t)rightRoot]) std::swap(leftRoot, rightRoot);
    parent[(size_t)rightRoot] = leftRoot;
    weight[(size_t)leftRoot] += weight[(size_t)rightRoot];
