int percolation(int rows, int cols, std::vector<std::vector<int>> opened) {
    if (rows <= 0 || cols <= 0) throw std::invalid_argument("the grid needs positive sides");
    int cells = rows * cols;
    int top = cells;
    int bottom = cells + 1;
    std::vector<int> parent((size_t)cells + 2);
    std::iota(parent.begin(), parent.end(), 0);
    std::vector<int> weight((size_t)cells + 2, 1);
    std::vector<char> open((size_t)cells, 0);
    for (size_t step = 0; step < opened.size(); ++step) {
        const auto& cell = opened[step];
        if (cell.size() != 2) throw std::invalid_argument("a cell is {row, col}");
        int row = (int)cell[0];
        int col = (int)cell[1];
        if (row < 0 || row >= rows || col < 0 || col >= cols) {
            throw std::invalid_argument("cell out of range");
        }
        int here = row * cols + col;
        if (open[(size_t)here]) continue;
        open[(size_t)here] = 1;
        if (row == 0) __join(parent, weight, here, top);
        if (row == rows - 1) __join(parent, weight, here, bottom);
        const int dr[4] = {-1, 1, 0, 0};
        const int dc[4] = {0, 0, -1, 1};
        for (int side = 0; side < 4; ++side) {
            int rr = row + dr[side];
            int cc = col + dc[side];
            if (rr < 0 || rr >= rows || cc < 0 || cc >= cols) continue;
            int other = rr * cols + cc;
            if (open[(size_t)other]) __join(parent, weight, here, other);
        }
        if (__find(parent, top) == __find(parent, bottom)) return (int)step + 1;
    }
    return -1;
}
