int lis_one_skip(std::vector<int> values) {
    int n = (int)values.size();
    if (n == 0) return 0;
    std::vector<int> plain((size_t)n, 1);
    std::vector<int> skipped((size_t)n, 1);
    int best = 1;
    for (int index = 0; index < n; ++index) {
        for (int earlier = 0; earlier < index; ++earlier) {
            if (values[(size_t)earlier] < values[(size_t)index]) {
                if (plain[(size_t)earlier] + 1 > plain[(size_t)index]) {
                    plain[(size_t)index] = plain[(size_t)earlier] + 1;
                }
                if (skipped[(size_t)earlier] + 1 > skipped[(size_t)index]) {
                    skipped[(size_t)index] = skipped[(size_t)earlier] + 1;
                }
            } else if (plain[(size_t)earlier] > skipped[(size_t)index]) {
                skipped[(size_t)index] = plain[(size_t)earlier];
            }
        }
        if (plain[(size_t)index] > best) best = plain[(size_t)index];
