#include <cassert>
#include <stdexcept>
#include <string>
#include <vector>

std::vector<std::string> justify(std::vector<std::string> words, int width) {
    if (width < 1) throw std::invalid_argument("width must be positive");
    for (const std::string& word : words) {
        if (word.empty()) throw std::invalid_argument("words must not be empty");
        if ((int)word.size() > width) throw std::invalid_argument("a word is wider than the line");
    }
    std::vector<std::vector<std::string>> lines;
    std::vector<std::string> current;
    size_t used = 0;
    for (const std::string& word : words) {
        size_t extra = current.empty() ? word.size() : used + 1 + word.size();
        if (extra > (size_t)width && !current.empty()) {
            lines.push_back(current);
            current.clear();
            used = word.size();
        } else {
            used = extra;
        }
        current.push_back(word);
    }
    if (!current.empty()) lines.push_back(current);
    std::vector<std::string> result;
    for (size_t index = 0; index < lines.size(); ++index) {
        const auto& line = lines[index];
        std::string text;
        if (index + 1 == lines.size() || line.size() == 1) {
            for (size_t word = 0; word < line.size(); ++word) {
                if (word) text += " ";
                text += line[word];
            }
            if (index + 1 != lines.size()) text.append((size_t)width - text.size(), ' ');
            result.push_back(text);
            continue;
        }
        size_t letters = 0;
        for (const std::string& word : line) letters += word.size();
        size_t gaps = line.size() - 1;
        size_t spaces = (size_t)width - letters;
        size_t base = spaces / gaps;
        size_t remainder = spaces % gaps;
        for (size_t word = 0; word < line.size(); ++word) {
            if (word) text.append(base + (word <= remainder ? 1 : 0), ' ');
            text += line[word];
        }
        result.push_back(text);
    }
    return result;
}
