long long kth_pair_distance(std::vector<int> values, long long kth) {
    long long n = (long long)values.size();
    if (n < 2) throw std::invalid_argument("at least two values are needed");
    long long all = n * (n - 1) / 2;
    if (kth < 1 || kth > all) throw std::invalid_argument("kth is out of range");
    std::vector<int> sorted(values);
    std::sort(sorted.begin(), sorted.end());
    long long low = 0;
    long long high = (long long)sorted.back() - sorted.front();
    while (low < high) {
        long long middle = low + (high - low) / 2;
        if (__pairsAtMost(sorted, middle) >= kth) high = middle;
        else low = middle + 1;
    }
    return low;
}
