def _parse_version(text):
    parts = text.split(".")
    if len(parts) != 3:
        raise ValueError("a version has three parts: %r" % (text,))
    numbers = []
    for part in parts:
        if not part.isdigit() or not part.isascii():
            raise ValueError("bad version part: %r" % (part,))
        numbers.append(int(part))
    return tuple(numbers)


def _compare(left, right):
    return (left > right) - (left < right)


def _wildcard(fixed, version):
    for index, part in enumerate(fixed):
        if version[index] != part:
            return False
    return True


def semver_matches(version, rangespec):
    numbers = _parse_version(version)
    if not isinstance(rangespec, str) or not rangespec.split():
        raise ValueError("an empty range")
    for raw in rangespec.split():
        token = raw.strip()
        if not token:
            raise ValueError("empty comparator")
        if token.startswith("^") or token.startswith("~"):
            base = _parse_version(token[1:])
            if numbers < base:
                return False
            if token[0] == "~":
                upper = (base[0], base[1] + 1, 0)
            elif base[0] != 0:
                upper = (base[0] + 1, 0, 0)
            elif base[1] != 0:
                upper = (0, base[1] + 1, 0)
            else:
                upper = (0, 0, base[2] + 1)
            if numbers >= upper:
                return False
            continue
        operator = "="
        for candidate in (">=", "<=", ">", "<", "="):
            if token.startswith(candidate):
                operator = candidate
                token = token[len(candidate):]
                break
        if "x" in token or "*" in token:
            if operator not in ("=",):
                raise ValueError("wildcards only stand alone: %r" % (raw,))
            parts = token.split(".")
            if len(parts) > 3:
                raise ValueError("bad wildcard: %r" % (raw,))
            for index, part in enumerate(parts):
                if part in ("x", "*"):
                    if index != len(parts) - 1:
                        raise ValueError("wildcard must come last: %r" % (raw,))
                    return _wildcard([int(p) for p in parts[:index]], numbers)
                if not part.isdigit():
                    raise ValueError("bad wildcard part: %r" % (part,))
            raise ValueError("wildcard without x or *: %r" % (raw,))
        other = _parse_version(token)
        order = _compare(numbers, other)
        if operator == ">=" and order < 0:
            return False
        if operator == ">" and order <= 0:
            return False
        if operator == "<=" and order > 0:
            return False
        if operator == "<" and order >= 0:
            return False
        if operator == "=" and order != 0:
            return False
    return True
