def three_way_merge(base, left, right):
    for part in (base, left, right):
        if not isinstance(part, dict):
            raise ValueError("every side must be a dict")
        for value in part.values():
            if not isinstance(value, str):
                raise ValueError("values must be strings")
    merged = {}
    conflicts = []
    for key in set(base) | set(left) | set(right):
        original = base.get(key)
        mine = left.get(key)
        theirs = right.get(key)
        if mine == theirs:
            if mine is not None:
                merged[key] = mine
            continue
        if mine == original:
            if theirs is not None:
                merged[key] = theirs
            continue
        if theirs == original:
            if mine is not None:
                merged[key] = mine
            continue
        conflicts.append(key)
    conflicts.sort()
    return merged, conflicts
