def grid_word_count(grid, word):
    if not isinstance(word, str) or not word:
        raise ValueError("the word must not be empty")
    if not grid:
        return 0
    width = len(grid[0])
    for row in grid:
        if len(row) != width:
            raise ValueError("rows must share one width")
    height = len(grid)
    if len(word) == 1:
        return sum(1 for row in grid for letter in row if letter == word)
    directions = [(dr, dc) for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc]
    hits = 0
    for row in range(height):
        for column in range(width):
            if grid[row][column] != word[0]:
                continue
            for dr, dc in directions:
                end_row = row + dr * (len(word) - 1)
                end_column = column + dc * (len(word) - 1)
                if not (0 <= end_row < height and 0 <= end_column < width):
                    continue
                matched = True
                for step in range(1, len(word)):
                    rr = row + dr * step
                    cc = column + dc * step
                    if grid[rr][cc] != word[step]:
                        matched = False
                        break
                if matched:
                    hits += 1
    return hits
