            raise ValueError("a job is (name, duration, deadline)")
        name, duration, deadline = job
        if not isinstance(name, str) or not name:
            raise ValueError("a job needs a name")
        if name in seen:
            raise ValueError("duplicate job name %r" % (name,))
        seen.add(name)
        if duration < 0 or deadline < 0:
            raise ValueError("durations and deadlines must not be negative")
    order = []
