def islands_after_adds(rows, cols, adds):
    if rows <= 0 or cols <= 0:
        raise ValueError("the grid needs positive sides")
    parent = {}
    size = {}

    def find(cell):
        while parent[cell] != cell:
            parent[cell] = parent[parent[cell]]
            cell = parent[cell]
        return cell

    def join(first, second):
        left = find(first)
        right = find(second)
        if left == right:
            return 0
        if size[left] < size[right]:
            left, right = right, left
        parent[right] = left
        size[left] += size[right]
        return 1

    counts = []
    islands = 0
    for cell in adds:
        if not isinstance(cell, tuple) or len(cell) != 2:
            raise ValueError("a cell is a (row, column) pair")
        row, column = cell
        if not (0 <= row < rows and 0 <= column < cols):
            raise ValueError("cell out of range")
        if cell in parent:
            counts.append(islands)
            continue
        parent[cell] = cell
        size[cell] = 1
        islands += 1
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            neighbour = (row + dr, column + dc)
            if neighbour in parent:
                islands -= join(cell, neighbour)
        counts.append(islands)
    return counts
```

