def palindrome_delete_cost(text, costs):
    for letter in text:
        if letter not in costs:
            raise ValueError("no cost for %r" % (letter,))
        if costs[letter] < 0:
            raise ValueError("costs must not be negative")
    n = len(text)
    if n <= 1:
        return 0
    best = [[0] * n for _ in range(n)]
    for span in range(2, n + 1):
        for start in range(n - span + 1):
            stop = start + span - 1
            if text[start] == text[stop]:
                best[start][stop] = best[start + 1][stop - 1]
            else:
                drop_left = costs[text[start]] + best[start + 1][stop]
                drop_right = costs[text[stop]] + best[start][stop - 1]
                best[start][stop] = min(drop_left, drop_right)
    return best[0][n - 1]
```

