def wildcard_occurrences(text, pattern):
    if not pattern:
        raise ValueError("the pattern must not be empty")
    if len(pattern) > 64:
        raise ValueError("the pattern can hold at most 64 characters")
    masks = {}
    for position, letter in enumerate(pattern):
        masks[letter] = masks.get(letter, 0) | (1 << position)
    wildcard = 0
    for position, letter in enumerate(pattern):
        if letter == "?":
            wildcard |= 1 << position
    for code in set(text) | set(pattern):
        if code != "?":
            masks[code] = masks.get(code, 0) | wildcard
    goal = 1 << (len(pattern) - 1)
    state = 0
    hits = 0
    for letter in text:
        state = ((state << 1) | 1) & masks.get(letter, wildcard)
        if state & goal:
            hits += 1
    return hits
```

