def session_split(events, timeout):
    if timeout < 0:
        raise ValueError("the timeout must not be negative")
    grouped = {}
    for event in events:
        if not isinstance(event, tuple) or len(event) != 2:
            raise ValueError("an event is a (timestamp, user) pair")
        stamp, user = event
        if isinstance(stamp, bool) or not isinstance(stamp, int) or stamp < 0:
            raise ValueError("timestamps must be non-negative integers")
        if not isinstance(user, str) or not user:
            raise ValueError("a user must be a non-empty name")
        grouped.setdefault(user, []).append(stamp)
    result = {}
    for user, stamps in grouped.items():
        stamps.sort()
        sessions = []
        start = stamps[0]
        previous = stamps[0]
        count = 1
        for stamp in stamps[1:]:
            if stamp - previous > timeout:
                sessions.append((start, previous, count))
                start = stamp
                count = 0
            count += 1
            previous = stamp
        sessions.append((start, previous, count))
        result[user] = sessions
    return result
