function quarterRange(label: string): { start: string; end: string } {
  const match = /^(\d{4})-Q([1-4])$/.exec(label);
  if (!match) throw new Error('bad quarter label: ' + label);
  const year = Number(match[1]);
  if (year < 1900 || year > 2100) throw new Error('year out of range');
  const quarter = Number(match[2]);
  const startMonth = (quarter - 1) * 3 + 1;
  const endMonth = quarter * 3 + 1;
  const pad = (value: number) => String(value).padStart(2, '0');
  const start = `${year}-${pad(startMonth)}-01`;
  if (endMonth === 13) return { start, end: `${year + 1}-01-01` };
  return { start, end: `${year}-${pad(endMonth)}-01` };
}
