```typescript
function topoOrder(count: number, edges: Array<[number, number]>): number[] | null {
  if (!Number.isInteger(count) || count < 0) throw new Error('bad count');
  const following: Set<number>[] = [];
  const waiting: number[] = [];
  for (let node = 0; node < count; node += 1) {
    following.push(new Set<number>());
    waiting.push(0);
  }
  for (const edge of edges) {
    const [before, after] = edge;
    if (before < 0 || before >= count || after < 0 || after >= count) throw new Error('bad edge');
    if (following[before].has(after)) continue;
    following[before].add(after);
    waiting[after] += 1;
  }
  const ready: number[] = [];
  for (let node = 0; node < count; node += 1) if (waiting[node] === 0) ready.push(node);
  const order: number[] = [];
  while (ready.length) {
    ready.sort((left, right) => left - right);
    const node = ready.shift() as number;
    order.push(node);
    for (const other of following[node]) {
      waiting[other] -= 1;
      if (waiting[other] === 0) ready.push(other);
    }
  }
  return order.length === count ? order : null;
}
```

```typescript
function lruSim(capacity: number, ops: Array<[number, number, number?]>): number[] {
  if (!Number.isInteger(capacity) || capacity < 1) throw new Error('bad capacity');
  const order: number[] = [];
  const store = new Map<number, number>();
  const answers: number[] = [];
  const touch = (key: number) => {
    const at = order.indexOf(key);
    if (at >= 0) order.splice(at, 1);
    order.push(key);
  };
  for (const op of ops) {
    const code = op[0];
    if (code === 1) {
      const key = op[1];
      const value = op[2] as number;
      if (!store.has(key) && store.size === capacity) {
        const victim = order.shift() as number;
        store.delete(victim);
      }
      store.set(key, value);
      touch(key);
    } else if (code === 2) {
      const key = op[1];
      if (!store.has(key)) {
        answers.push(-1);
        continue;
      }
      touch(key);
      answers.push(store.get(key) as number);
    } else if (code === 3) {
      answers.push(store.size);
    } else {
      throw new Error('unknown operation');
    }
  }
  return answers;
}
```

