function collapseRuns(text: string): string {
  if (/[{}0-9]/.test(text)) throw new Error('reserved character');
  let out = '';
  let index = 0;
  while (index < text.length) {
    let run = 1;
    while (index + run < text.length && text[index + run] === text[index]) run += 1;
    const letter = text[index];
    out += run >= 3 ? `${letter}{${run}}` : letter.repeat(run);
    index += run;
  }
  return out;
}
