function parseMoney(text: string): number {
  if (typeof text !== 'string' || text.length === 0) throw new Error('empty amount');
  let body = text;
  let sign = 1;
  if (body[0] === '-') {
    sign = -1;
    body = body.slice(1);
  }
  const pieces = body.split('.');
  if (pieces.length > 2) throw new Error('too many dots');
  const whole = pieces[0];
  const fraction = pieces.length === 2 ? pieces[1] : '';
  if (fraction.length > 2) throw new Error('at most two decimals');
  if (!/^\d{1,3}(,\d{3})*$/.test(whole) && !/^\d+$/.test(whole)) throw new Error('bad digits');
  const digits = whole.replace(/,/g, '');
  if (digits.length === 0) throw new Error('missing digits');
  const cents = Number(digits) * 100 + Number((fraction + '00').slice(0, 2));
  return sign * cents;
}
