function firstAtLeast(values: number[], target: number): { index: number; found: boolean } {
  for (let index = 1; index < values.length; index += 1) {
    if (values[index] < values[index - 1]) throw new Error('array is not sorted');
  }
  let low = 0;
  let high = values.length;
  while (low < high) {
    const middle = low + ((high - low) >> 1);
    if (values[middle] < target) low = middle + 1;
    else high = middle;
  }
  return { index: low, found: low < values.length && values[low] === target };
}
