function serveOrder(items: Array<[string, number, number]>): string[] {
  const pending: Array<[string, number, number]> = [];
  for (const item of items) {
    if (item[1] < 0 || item[2] < 0) throw new Error('negative arrival or priority');
    pending.push([item[0], item[1], item[2]]);
  }
  pending.sort((left, right) => left[1] - right[1] || left[2] - right[2] || (left[0] < right[0] ? -1 : 1));
  const order: string[] = [];
  let clock = 0;
  let at = 0;
  const waiting: Array<[string, number, number]> = [];
  while (at < pending.length || waiting.length > 0) {
    if (waiting.length === 0 && at < pending.length && pending[at][1] > clock) {
      clock = pending[at][1];
    }
    while (at < pending.length && pending[at][1] <= clock) {
      waiting.push(pending[at]);
      at += 1;
    }
    waiting.sort((left, right) => left[2] - right[2] || left[1] - right[1] || (left[0] < right[0] ? -1 : 1));
    const next = waiting.shift() as [string, number, number];
    order.push(next[0]);
    clock += 1;
  }
  return order;
}
