function decodeBase32(text: string): number[] {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  const clean = text.toUpperCase();
  if (text !== clean && /[^A-Za-z2-7]/.test(text)) throw new Error('illegal symbol');
  if (/[^A-Z2-7]/.test(clean)) throw new Error('illegal symbol');
  const leftover = clean.length % 8;
  if (leftover === 1 || leftover === 3 || leftover === 6) throw new Error('bad length');
  const bytes: number[] = [];
  let buffer = 0;
  let bits = 0;
  for (const symbol of clean) {
    const value = alphabet.indexOf(symbol);
    if (value < 0) throw new Error('illegal symbol: ' + symbol);
    buffer = (buffer << 5) | value;
    bits += 5;
    if (bits >= 8) {
      bits -= 8;
      bytes.push((buffer >> bits) & 0xff);
    }
  }
  return bytes;
}
