function sudokuErrors(grid: number[][]): string[] {
  if (!Array.isArray(grid) || grid.length !== 9) throw new Error('nine rows are needed');
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== 9) throw new Error('nine columns are needed');
    for (const value of row) {
      if (!Number.isInteger(value) || value < 0 || value > 9) throw new Error('bad value');
    }
  }
  const bad = new Set<string>();
  for (let row = 0; row < 9; row += 1) {
    for (let col = 0; col < 9; col += 1) {
      const value = grid[row][col];
      if (value === 0) continue;
      let conflict = false;
      for (let other = 0; other < 9; other += 1) {
        if (other !== col && grid[row][other] === value) conflict = true;
        if (other !== row && grid[other][col] === value) conflict = true;
      }
      const baseRow = Math.floor(row / 3) * 3;
      const baseCol = Math.floor(col / 3) * 3;
      for (let dr = 0; dr < 3; dr += 1) {
        for (let dc = 0; dc < 3; dc += 1) {
          const rr = baseRow + dr;
          const cc = baseCol + dc;
          if ((rr !== row || cc !== col) && grid[rr][cc] === value) conflict = true;
        }
      }
      if (conflict) bad.add(row + ',' + col);
    }
  }
  return Array.from(bad).sort((left, right) => {
    const [rowA, colA] = left.split(',').map(Number);
    const [rowB, colB] = right.split(',').map(Number);
    return rowA - rowB || colA - colB;
  });
}
