function flattenPaths(value: unknown): Array<[string, unknown]> {
  const out: Array<[string, unknown]> = [];
  const walk = (current: unknown, path: string): void => {
    if (Array.isArray(current)) {
      if (current.length === 0) {
        out.push([path, current]);
        return;
      }
      current.forEach((item, index) => walk(item, path + '[' + index + ']'));
      return;
    }
    if (isPlainObject(current)) {
      const keys = Object.keys(current);
      if (keys.length === 0) {
        out.push([path, current]);
        return;
      }
      for (const key of keys) {
        walk(current[key], path === '' ? key : path + '.' + key);
      }
      return;
    }
    out.push([path, current]);
  };
  walk(value, '');
  out.sort((left, right) => (left[0] < right[0] ? -1 : left[0] > right[0] ? 1 : 0));
  return out;
}
