def coin_ways(coins, limits, target):
    if len(coins) != len(limits):
        raise ValueError("coins and limits must line up")
    if target < 0:
        raise ValueError("target must not be negative")
    ways = [0] * (target + 1)
    ways[0] = 1
    for coin, limit in zip(coins, limits):
        if coin <= 0:
            raise ValueError("coin values must be positive")
        if limit < 0:
            raise ValueError("limits must not be negative")
        usable = min(limit, target // coin)
        if usable == 0:
            continue
        fresh = [0] * (target + 1)
        for residue in range(coin):
            running = 0
            for total in range(residue, target + 1, coin):
                running += ways[total]
                stale = total - (usable + 1) * coin
                if stale >= 0:
                    running -= ways[stale]
                fresh[total] = running
        ways = fresh
    return ways[target]
