def odd_cycle(nodes, edges):
    if nodes < 0:
        raise ValueError("node count must not be negative")
    neighbours = [[] for _ in range(nodes)]
    for edge in edges:
        if not isinstance(edge, tuple) or len(edge) != 2:
            raise ValueError("an edge is a (left, right) pair")
        left, right = edge
        if left < 0 or left >= nodes or right < 0 or right >= nodes:
            raise ValueError("endpoint out of range")
        if right not in neighbours[left]:
            neighbours[left].append(right)
        if left not in neighbours[right]:
            neighbours[right].append(left)
    colour = [-1] * nodes
    parent = [-1] * nodes
    for start in range(nodes):
        if colour[start] != -1:
            continue
        colour[start] = 0
        queue = [start]
        head = 0
        while head < len(queue):
            node = queue[head]
            head += 1
            for other in sorted(neighbours[node]):
                if colour[other] == -1:
                    colour[other] = 1 - colour[node]
                    parent[other] = node
                    queue.append(other)
                elif colour[other] == colour[node]:
                    first_path = []
                    second_path = []
                    walker = node
                    while walker != -1:
                        first_path.append(walker)
                        walker = parent[walker]
                    walker = other
                    while walker != -1:
                        second_path.append(walker)
                        walker = parent[walker]
                    shared = set(first_path) & set(second_path)
                    meet = next(item for item in first_path if item in shared)
                    cycle = []
                    for item in first_path:
                        cycle.append(item)
                        if item == meet:
                            break
                    extra = []
                    for item in second_path:
                        if item == meet:
                            break
                        extra.append(item)
                    cycle.extend(reversed(extra))
                    return sorted(set(cycle))
    return []
