from collections import deque


def jump_cost(costs, reach):
    if not costs:
        raise ValueError("at least one position is needed")
    if reach < 1:
        raise ValueError("reach must be positive")
    for cost in costs:
        if cost < 0:
            raise ValueError("costs must not be negative")
