        return 0
    best = [None] * size
    best[0] = 0
    window = deque([0])
    for index in range(1, size):
        while window and window[0] < index - reach:
            window.popleft()
        if not window or best[window[0]] is None:
            best[index] = None
        else:
            best[index] = best[window[0]] + costs[index]
        while window and (best[window[-1]] is None or best[window[-1]] >= best[index]):
            window.pop()
        if best[index] is not None:
            window.append(index)
    return -1 if best[-1] is None else best[-1]
