def palindrome_cuts(text):
    size = len(text)
    if size <= 1:
        return 0
    table = [[False] * size for _ in range(size)]
    for index in range(size):
        table[index][index] = True
    for index in range(size - 1):
        table[index][index + 1] = text[index] == text[index + 1]
    for span in range(3, size + 1):
        for start in range(size - span + 1):
            stop = start + span - 1
            if text[start] == text[stop] and table[start + 1][stop - 1]:
                table[start][stop] = True
    cuts = [0] * size
    for stop in range(size):
        if table[0][stop]:
            cuts[stop] = 0
            continue
        best = stop
        for start in range(1, stop + 1):
            if table[start][stop] and cuts[start - 1] + 1 < best:
                best = cuts[start - 1] + 1
        cuts[stop] = best
    return cuts[size - 1]
