long long sumSubarrayMins(std::vector<int> values) {
    const long long mod = 1000000007LL;
    const int size = static_cast<int>(values.size());
    std::vector<long long> left(size), right(size);
    std::vector<int> stack;
    for (int i = 0; i < size; ++i) {
        while (!stack.empty() && values[stack.back()] > values[i]) stack.pop_back();
        left[i] = stack.empty() ? i + 1 : i - stack.back();
        stack.push_back(i);
    }
    stack.clear();
    for (int i = size - 1; i >= 0; --i) {
        while (!stack.empty() && values[stack.back()] >= values[i]) stack.pop_back();
        right[i] = stack.empty() ? size - i : stack.back() - i;
        stack.push_back(i);
    }
    long long total = 0;
    for (int i = 0; i < size; ++i) {
        total = (total + static_cast<long long>(values[i]) * left[i] % mod * right[i]) % mod;
