int longestPalindromeSubseq(std::string text) {
    const int size = static_cast<int>(text.size());
    if (size == 0) return 0;
    std::vector<std::vector<int>> table(size, std::vector<int>(size, 0));
    for (int start = size - 1; start >= 0; --start) {
        table[start][start] = 1;
        for (int stop = start + 1; stop < size; ++stop) {
            if (text[start] == text[stop]) {
                table[start][stop] = table[start + 1][stop - 1] + 2;
            } else {
                table[start][stop] = std::max(table[start + 1][stop], table[start][stop - 1]);
            }
        }
    }
    return table[0][size - 1];
}
