long long countDigitSum(long long limit, int target) {
    if (limit < 1 || target < 0) return 0;
    const std::string digits = std::to_string(limit);
    const int length = static_cast<int>(digits.size());
    std::vector<long long> tight(target + 1, 0), loose(target + 1, 0);
    tight[0] = 1;
    for (int at = 0; at < length; ++at) {
        std::vector<long long> nextTight(target + 1, 0), nextLoose(target + 1, 0);
        const int ceiling = digits[at] - '0';
        for (int sum = 0; sum <= target; ++sum) {
            if (tight[sum] > 0) {
                for (int digit = 0; digit <= ceiling && sum + digit <= target; ++digit) {
                    if (digit == ceiling) nextTight[sum + digit] += tight[sum];
                    else nextLoose[sum + digit] += tight[sum];
                }
            }
            if (loose[sum] > 0) {
                for (int digit = 0; digit <= 9 && sum + digit <= target; ++digit) {
                    nextLoose[sum + digit] += loose[sum];
                }
            }
        }
        tight = nextTight;
        loose = nextLoose;
    }
    long long total = tight[target] + loose[target];
    if (target == 0) total -= 1;
    return total;
}
