int fifoFaults(std::vector<int> pages, int capacity) {
    if (capacity < 1) throw std::invalid_argument("capacity must be positive");
    std::deque<int> order;
    std::unordered_set<int> inside;
    int faults = 0;
    for (int page : pages) {
        if (inside.count(page) > 0) continue;
        faults += 1;
        if (static_cast<int>(order.size()) == capacity) {
            inside.erase(order.front());
            order.pop_front();
        }
        order.push_back(page);
        inside.insert(page);
    }
    return faults;
}
