int wordLadder(std::string begin, std::string end, std::vector<std::string> words) {
    if (begin.size() != end.size()) throw std::invalid_argument("lengths differ");
    std::unordered_set<std::string> pool(words.begin(), words.end());
    if (pool.count(end) == 0) return 0;
    std::unordered_set<std::string> seen{begin};
    std::vector<std::string> frontier{begin};
    int steps = 1;
    while (!frontier.empty()) {
        for (const auto &word : frontier) {
            if (word == end) return steps;
        }
        std::vector<std::string> next;
        for (const auto &word : frontier) {
            for (std::size_t at = 0; at < word.size(); ++at) {
                std::string probe = word;
                for (char letter = 'a'; letter <= 'z'; ++letter) {
                    probe[at] = letter;
                    if (pool.count(probe) == 0 || seen.count(probe) > 0) continue;
                    seen.insert(probe);
                    next.push_back(probe);
                }
            }
        }
        frontier = next;
        steps += 1;
    }
    return 0;
}
