class Inventory {
  constructor() {
    this.stock = new Map();
    this.reserved = new Map();
  }

  check(count) {
    if (!Number.isInteger(count) || count < 0) throw new Error('bad count');
  }

  add(sku, count) {
    this.check(count);
    this.stock.set(sku, (this.stock.get(sku) || 0) + count);
  }

  remove(sku, count) {
    this.check(count);
    const held = this.stock.get(sku) || 0;
    if (count > held) return false;
    this.stock.set(sku, held - count);
    return true;
  }

  reserve(sku, count) {
    this.check(count);
    const held = this.stock.get(sku) || 0;
    if (count === 0 || count > held) return false;
    this.stock.set(sku, held - count);
    this.reserved.set(sku, (this.reserved.get(sku) || 0) + count);
    return true;
  }

  report() {
    const skus = [];
    let total = 0;
    for (const [sku, count] of this.stock.entries()) {
      if (count > 0) {
        skus.push([sku, count]);
        total += count;
      }
    }
    skus.sort((left, right) => (left[0] < right[0] ? -1 : left[0] > right[0] ? 1 : 0));
    return { total, skus };
  }
}
