function decodePiece(piece) {
  if (/%/.test(piece) && /%(?![0-9A-Fa-f]{2})/.test(piece)) throw new Error('bad escape');
  return piece.replace(/\+/g, ' ').replace(/%([0-9A-Fa-f]{2})/g, (_, hex) =>
    String.fromCharCode(parseInt(hex, 16)));
}

function parseQueryString(text) {
  let body = String(text);
  if (body.startsWith('?')) body = body.slice(1);
  const out = {};
  if (body.length === 0) return out;
  for (const piece of body.split('&')) {
    if (piece.length === 0) continue;
    const cut = piece.indexOf('=');
    const rawKey = cut < 0 ? piece : piece.slice(0, cut);
    const rawValue = cut < 0 ? '' : piece.slice(cut + 1);
    const key = decodePiece(rawKey);
    if (key.length === 0) throw new Error('empty key');
    if (!Object.prototype.hasOwnProperty.call(out, key)) out[key] = [];
    out[key].push(decodePiece(rawValue));
  }
  return out;
}
