function buildTree(pairs) {
  const parentOf = new Map();
  const order = [];
  const seen = new Set();
  const remember = (name) => {
    if (!seen.has(name)) {
      seen.add(name);
      order.push(name);
    }
  };
  for (const [child, parent] of pairs) {
    remember(child);
    if (parent === null) continue;
    remember(parent);
    if (parent === child) throw new Error('self parent');
    if (parentOf.has(child)) throw new Error('two parents for ' + child);
    parentOf.set(child, parent);
  }
  const kids = new Map();
  const roots = [];
  for (const name of order) kids.set(name, []);
  for (const name of order) {
    if (!parentOf.has(name)) roots.push(name);
    else kids.get(parentOf.get(name)).push(name);
  }
  const state = new Map();
  const build = (name) => {
    if (state.get(name) === 1) throw new Error('cycle through ' + name);
    state.set(name, 1);
    const children = kids.get(name).map(build);
    state.set(name, 2);
    return { name, children };
