```javascript
class MinHeap {
  constructor() {
    this.items = [];
  }

  size() {
    return this.items.length;
  }

  peek() {
    return this.items.length ? this.items[0] : undefined;
  }

  push(value) {
    if (!Number.isFinite(value)) throw new Error('not a finite number');
    this.items.push(value);
    this.siftUp(this.items.length - 1);
  }

  siftUp(at) {
    let index = at;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (this.items[parent] <= this.items[index]) return;
      [this.items[parent], this.items[index]] = [this.items[index], this.items[parent]];
      index = parent;
    }
  }

  siftDown(at) {
    let index = at;
    while (true) {
      const left = index * 2 + 1;
      const right = left + 1;
      let smallest = index;
      if (left < this.items.length && this.items[left] < this.items[smallest]) smallest = left;
      if (right < this.items.length && this.items[right] < this.items[smallest]) smallest = right;
      if (smallest === index) return;
      [this.items[smallest], this.items[index]] = [this.items[index], this.items[smallest]];
      index = smallest;
    }
  }

  pop() {
    if (this.items.length === 0) return undefined;
    const top = this.items[0];
    const last = this.items.pop();
    if (this.items.length > 0) {
      this.items[0] = last;
      this.siftDown(0);
    }
    return top;
  }

  static from(values) {
    if (!Array.isArray(values)) throw new Error('an array is needed');
    const heap = new MinHeap();
    for (const value of values) {
      if (!Number.isFinite(value)) throw new Error('not a finite number');
      heap.items.push(value);
    }
    for (let index = (heap.items.length >> 1) - 1; index >= 0; index -= 1) heap.siftDown(index);
    return heap;
  }
}
```

