function foldEvents(events) {
  const summary = { open: 0, closed: 0, reopened: 0, invalid: 0 };
  if (!Array.isArray(events)) throw new Error('events must be an array');
  let isOpen = false;
  for (const event of events) {
    if (!Array.isArray(event) || event.length < 2) {
      summary.invalid += 1;
      continue;
    }
    const [type, id] = event;
    if (typeof id !== 'string' || id.length === 0) {
      summary.invalid += 1;
      continue;
    }
    if (type === 'open' && !isOpen) {
      isOpen = true;
      summary.open += 1;
    } else if (type === 'close' && isOpen) {
      isOpen = false;
      summary.closed += 1;
    } else if (type === 'reopen' && !isOpen) {
      summary.reopened += 1;
    } else {
      summary.invalid += 1;
    }
  }
  return summary;
}
```

