def ship_capacity(weights, days):
    if not weights:
        raise ValueError("at least one parcel is needed")
    for weight in weights:
        if weight <= 0:
            raise ValueError("weights must be positive")
    if days < 1:
        raise ValueError("days must be positive")
    total = sum(weights)
    low, high = max(weights), total
    while low < high:
        middle = (low + high) // 2
        used = 1
        load = 0
        for weight in weights:
            if load + weight > middle:
                used += 1
                load = 0
            load += weight
        if used <= days:
            high = middle
        else:
            low = middle + 1
    return low
