from collections import deque


def zero_one_paths(nodes, edges, start):
    if nodes < 0:
        raise ValueError("node count must not be negative")
    if start < 0 or start >= nodes:
        raise ValueError("start out of range")
    neighbours = [[] for _ in range(nodes)]
    for edge in edges:
        if len(edge) != 3:
            raise ValueError("an edge is (left, right, weight)")
        left, right, weight = edge
        if weight not in (0, 1):
            raise ValueError("weights must be 0 or 1")
        if not (0 <= left < nodes) or not (0 <= right < nodes):
            raise ValueError("endpoint out of range")
        neighbours[left].append((right, weight))
        neighbours[right].append((left, weight))
    best = [None] * nodes
    best[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for other, weight in neighbours[node]:
            candidate = best[node] + weight
            if best[other] is None or candidate < best[other]:
                best[other] = candidate
                if weight == 0:
                    queue.appendleft(other)
                else:
                    queue.append(other)
    return best
