def parse_csv_line(text):
    if not isinstance(text, str):
        raise ValueError("the record must be a string")
    if text.endswith("\r"):
        text = text[:-1]
    fields = []
    current = []
    at = 0
    while True:
        if at < len(text) and text[at] == '"':
            at += 1
            while True:
                if at >= len(text):
                    raise ValueError("the quoted field is not closed")
                if text[at] == '"':
                    if at + 1 < len(text) and text[at + 1] == '"':
                        current.append('"')
                        at += 2
                        continue
                    at += 1
                    break
                current.append(text[at])
                at += 1
            if at < len(text) and text[at] != ',':
                raise ValueError("unexpected character after a quoted field")
        else:
            while at < len(text) and text[at] != ',':
                if text[at] == '"':
                    raise ValueError("a quote inside an unquoted field")
                current.append(text[at])
                at += 1
        fields.append("".join(current))
        current = []
        if at >= len(text):
            break
        at += 1
        if at == len(text):
            fields.append("")
            break
    return fields
