def word_counts(text, stopwords):
    if not isinstance(text, str):
        raise ValueError("the text must be a string")
    blocked = {word.lower() for word in stopwords}
    tally = {}
    cleaned = []
    for character in text:
        if character.isalnum():
            cleaned.append(character.lower())
        else:
            cleaned.append(" ")
    for word in "".join(cleaned).split():
        if len(word) < 2 or word in blocked:
            continue
        tally[word] = tally.get(word, 0) + 1
    pairs = list(tally.items())
    pairs.sort(key=lambda item: (-item[1], item[0]))
    return pairs
