def spiral_order(grid):
    if not grid:
        return []
    if not grid[0]:
        return []
    width = len(grid[0])
    for row in grid:
        if len(row) != width:
            raise ValueError("the grid must be rectangular")
    top, bottom = 0, len(grid) - 1
    left, right = 0, width - 1
    walk = []
    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            walk.append(grid[top][col])
        top += 1
        for row in range(top, bottom + 1):
            walk.append(grid[row][right])
        right -= 1
        if top <= bottom:
            for col in range(right, left - 1, -1):
                walk.append(grid[bottom][col])
            bottom -= 1
        if left <= right:
            for row in range(bottom, top - 1, -1):
                walk.append(grid[row][left])
            left += 1
    return walk
