def run_ledger(opening, fee, entries):
    if opening < 0:
        raise ValueError("the opening balance must not be negative")
    if fee < 0:
        raise ValueError("the fee must not be negative")
    balance = opening
    applied = 0
    rejected = 0
    fees = 0
    for entry in entries:
        if not isinstance(entry, tuple) or len(entry) != 2:
            raise ValueError("an entry is (kind, amount)")
        kind, amount = entry
        if not isinstance(amount, int) or isinstance(amount, bool) or amount <= 0:
            raise ValueError("amounts must be positive integers")
        if kind == "credit":
            balance += amount
            applied += 1
        elif kind == "debit":
            needed = amount + fee
            if balance >= needed:
                balance -= needed
                fees += fee
                applied += 1
            else:
                rejected += 1
        else:
            raise ValueError("unknown entry kind %r" % (kind,))
    return {"balance": balance, "applied": applied, "rejected": rejected, "fees": fees}
```

