std::string kthPermutation(int n, long long k) {
    if (n < 0 || n > 9) throw std::invalid_argument("n out of range");
    if (k < 1) throw std::invalid_argument("k must be positive");
    std::vector<long long> factorial(n + 1, 1);
    for (int at = 1; at <= n; ++at) factorial[at] = factorial[at - 1] * at;
    if (k > factorial[n]) throw std::invalid_argument("k is too large");
    std::vector<int> pool;
    for (int digit = 1; digit <= n; ++digit) pool.push_back(digit);
    long long index = k - 1;
    std::string out;
    for (int left = n; left >= 1; --left) {
        const long long block = factorial[left - 1];
        const int pick = static_cast<int>(index / block);
        index %= block;
        out.push_back(static_cast<char>('0' + pool[pick]));
        pool.erase(pool.begin() + pick);
    }
    return out;
}
