long long countWalks(int nodes, std::vector<std::pair<int,int>> edges, int length) {
    const long long mod = 1000000007LL;
    if (nodes < 0 || length < 0) throw std::invalid_argument("bad input");
    using Matrix = std::vector<std::vector<long long>>;
    auto multiply = [&](const Matrix &first, const Matrix &second) {
        Matrix product(nodes, std::vector<long long>(nodes, 0));
        for (int row = 0; row < nodes; ++row) {
            for (int middle = 0; middle < nodes; ++middle) {
                if (first[row][middle] == 0) continue;
                for (int col = 0; col < nodes; ++col) {
                    product[row][col] = (product[row][col] + first[row][middle] * second[middle][col]) % mod;
                }
            }
        }
        return product;
    };
    Matrix base(nodes, std::vector<long long>(nodes, 0));
    for (const auto &edge : edges) {
        if (edge.first < 0 || edge.first >= nodes || edge.second < 0 || edge.second >= nodes) {
            throw std::invalid_argument("endpoint out of range");
        }
        base[edge.first][edge.second] = (base[edge.first][edge.second] + 1) % mod;
    }
    Matrix result(nodes, std::vector<long long>(nodes, 0));
    for (int node = 0; node < nodes; ++node) result[node][node] = 1;
    Matrix power = base;
    int exponent = length;
    while (exponent > 0) {
        if (exponent & 1) result = multiply(result, power);
        power = multiply(power, power);
        exponent >>= 1;
    }
    long long total = 0;
    for (int row = 0; row < nodes; ++row) {
        for (int col = 0; col < nodes; ++col) total = (total + result[row][col]) % mod;
    }
    return total;
}
