int shortestSuper(std::string left, std::string right) {
    if (left.size() > 5000 || right.size() > 5000) throw std::invalid_argument("input too long");
    const int rows = static_cast<int>(left.size());
    const int cols = static_cast<int>(right.size());
    std::vector<int> previous(cols + 1, 0), current(cols + 1, 0);
    for (int col = 1; col <= cols; ++col) previous[col] = col;
    for (int row = 1; row <= rows; ++row) {
        current[0] = row;
        for (int col = 1; col <= cols; ++col) {
            if (left[row - 1] == right[col - 1]) {
                current[col] = previous[col - 1] + 1;
            } else {
                current[col] = std::min(previous[col], current[col - 1]) + 1;
            }
        }
        previous = current;
    }
    return previous[cols];
}
