long long countSubsets(std::vector<int> values, int target) {
    if (target < 0) throw std::invalid_argument("target must not be negative");
    if (values.size() > 36) throw std::invalid_argument("too many values");
    for (int value : values) {
        if (value <= 0) throw std::invalid_argument("values must be positive");
    }
    const int middle = static_cast<int>(values.size()) / 2;
    auto listSums = [&](int from, int to) {
        std::vector<long long> sums{0};
        for (int at = from; at < to; ++at) {
            const std::size_t size = sums.size();
            for (std::size_t index = 0; index < size; ++index) sums.push_back(sums[index] + values[at]);
        }
        return sums;
    };
    std::vector<long long> first = listSums(0, middle);
    std::vector<long long> second = listSums(middle, static_cast<int>(values.size()));
    std::sort(second.begin(), second.end());
    long long total = 0;
    for (long long sum : first) {
        const long long need = static_cast<long long>(target) - sum;
        total += std::upper_bound(second.begin(), second.end(), need)
               - std::lower_bound(second.begin(), second.end(), need);
    }
    return total;
}
