int twinPrimes(int limit) {
    if (limit < 0 || limit > 10000000) throw std::invalid_argument("limit out of range");
    if (limit < 5) return 0;
    std::vector<bool> prime(limit + 1, true);
    prime[0] = false;
    prime[1] = false;
    for (long long start = 2; start * start <= limit; ++start) {
        if (!prime[start]) continue;
        for (long long multiple = start * start; multiple <= limit; multiple += start) {
            prime[multiple] = false;
        }
    }
    int pairs = 0;
    for (int value = 2; value + 2 <= limit; ++value) {
        if (prime[value] && prime[value + 2]) pairs += 1;
