```cpp
std::vector<int> circularTrace(int capacity, std::vector<int> ops) {
    if (capacity < 1) throw std::invalid_argument("capacity must be positive");
    std::vector<int> slots(capacity, -1);
    int cursor = 0;
    int written = 0;
    for (int op : ops) {
        if (op > 0) {
            slots[cursor] = op;
            cursor = (cursor + 1) % capacity;
            if (written < capacity) written += 1;
        } else if (op < 0) {
            cursor = (cursor + 1) % capacity;
        } else {
            throw std::invalid_argument("a zero value cannot be written");
        }
    }
    const int start = written == capacity ? cursor : 0;
    std::vector<int> out;
    out.reserve(capacity);
    for (int offset = 0; offset < capacity; ++offset) {
        out.push_back(slots[(start + offset) % capacity]);
    }
    return out;
}
