long long countSubarraySum(std::vector<int> values, long long target) {
    std::unordered_map<long long, long long> seen;
    seen.reserve(values.size() * 2 + 1);
    seen[0] = 1;
    long long running = 0;
    long long total = 0;
    for (int value : values) {
        running += value;
        const auto found = seen.find(running - target);
        if (found != seen.end()) total += found->second;
        seen[running] += 1;
    }
    return total;
