std::pair<int,int> treeStats(std::vector<int> levelOrder) {
    if (levelOrder.empty() || levelOrder[0] == -1) return {0, 0};
    struct Node {
        int left = -1;
        int right = -1;
    };
    std::vector<Node> nodes;
    nodes.push_back(Node{});
    std::vector<int> frontier{0};
    std::size_t at = 1;
    while (!frontier.empty() && at < levelOrder.size()) {
        std::vector<int> next;
        for (int index : frontier) {
            if (at >= levelOrder.size()) break;
            if (levelOrder[at] != -1) {
                nodes.push_back(Node{});
                nodes[index].left = static_cast<int>(nodes.size()) - 1;
                next.push_back(nodes[index].left);
            }
            at += 1;
            if (at >= levelOrder.size()) break;
            if (levelOrder[at] != -1) {
                nodes.push_back(Node{});
                nodes[index].right = static_cast<int>(nodes.size()) - 1;
                next.push_back(nodes[index].right);
            }
            at += 1;
        }
        frontier = next;
    }
    int height = 0;
    int width = 0;
    std::vector<int> level{0};
    while (!level.empty()) {
        height += 1;
        width = std::max(width, static_cast<int>(level.size()));
        std::vector<int> next;
        for (int index : level) {
            if (nodes[index].left >= 0) next.push_back(nodes[index].left);
            if (nodes[index].right >= 0) next.push_back(nodes[index].right);
        }
        level = next;
    }
    return {height, width};
}
