def to_number(text):
    digits = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    index = 0
    while index < len(text):
        current = digits[text[index]]
        if index + 1 < len(text) and digits[text[index + 1]] > current:
            total += digits[text[index + 1]] - current
            index += 2
        else:
            total += current
            index += 1
    return total


