"""Offset parsing, minutes east of UTC."""


def parse_offset(text):
    """Turn "+05:30" or "-08:00" into signed minutes."""
    if not isinstance(text, str) or len(text) != 6 or text[3] != ":":
        raise ValueError("offset must look like +HH:MM")
    sign = text[0]
    if sign not in "+-":
        raise ValueError("offset must start with + or -")
    hours = int(text[1:3])
    minutes = int(text[4:6])
    if hours > 14 or minutes > 59:
        raise ValueError("offset out of range")
    return hours * 60 + minutes if sign == "+" else -(hours * 60) + minutes

