from .offset import parse_offset

MINUTES_PER_DAY = 24 * 60


def local_minute(utc_minute, offset_text):
    """Minute of the day in the local zone, wrapped into one day."""
    if not 0 <= utc_minute < MINUTES_PER_DAY:
        raise ValueError("minute of the day out of range")
    shifted = utc_minute + parse_offset(offset_text)
