"""Wait schedule for a retry policy."""

from .policy import attempts


def waits(retries, base):
    """Seconds to wait before every attempt after the first."""
    total = attempts(retries, base)
    schedule = []
    for attempt in range(2, total + 1):
        schedule.append(base * 2 ** (attempt - 2))
    return schedule


