SOURCE_ORDER = ("defaults", "env", "file")


def merge(defaults, file_values, env_values):
    """Combine three mappings, strongest source last."""
    layers = {"defaults": defaults, "file": file_values, "env": env_values}
    result = {}
    for name in SOURCE_ORDER:
        layer = layers[name]
        if not isinstance(layer, dict):
