def min_window(text, wanted):
    if not wanted:
        return ""
    need = {}
    for letter in wanted:
        need[letter] = need.get(letter, 0) + 1
    missing = len(wanted)
    best_start = -1
    best_end = len(text) + 1
    left = 0
    for right, letter in enumerate(text):
        if letter in need:
            need[letter] -= 1
            if need[letter] >= 0:
                missing -= 1
        while missing == 0:
            if right - left + 1 < best_end - best_start:
                best_start = left
                best_end = right + 1
            out = text[left]
            if out in need:
                need[out] += 1
                if need[out] > 0:
                    missing += 1
            left += 1
    if best_start < 0:
        return ""
    return text[best_start:best_end]
