def break_count(text, words):
    if not isinstance(text, str):
        raise ValueError("the text must be a string")
    allowed = set()
    for word in words:
        if not isinstance(word, str) or not word:
            raise ValueError("words must be non-empty strings")
        allowed.add(word)
    longest = max((len(word) for word in allowed), default=0)
    ways = [0] * (len(text) + 1)
    ways[0] = 1
    for stop in range(1, len(text) + 1):
        total = 0
        for start in range(max(0, stop - longest), stop):
            if ways[start] == 0:
                continue
            if text[start:stop] in allowed:
                total += ways[start]
        ways[stop] = total
    return ways[len(text)]
