int longestValid(std::string text) {
    std::vector<int> stack;
    stack.push_back(-1);
    int best = 0;
    for (int at = 0; at < static_cast<int>(text.size()); ++at) {
        const char symbol = text[at];
        if (symbol == '(') {
            stack.push_back(at);
        } else if (symbol == ')') {
            stack.pop_back();
            if (stack.empty()) {
                stack.push_back(at);
            } else {
                best = std::max(best, at - stack.back());
            }
        } else {
            throw std::invalid_argument("only brackets are allowed");
        }
    }
    return best;
}
