int distinctIslands(std::vector<std::vector<int>> grid) {
    const int rows = static_cast<int>(grid.size());
    if (rows == 0) return 0;
    const int cols = static_cast<int>(grid[0].size());
    for (const auto &row : grid) {
        if (static_cast<int>(row.size()) != cols) throw std::invalid_argument("grid must be rectangular");
    }
    std::vector<std::vector<char>> seen(rows, std::vector<char>(cols, 0));
    std::set<std::vector<std::pair<int,int>>> shapes;
    const int steps[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; ++col) {
            if (grid[row][col] != 1 || seen[row][col]) continue;
            std::vector<std::pair<int,int>> cells;
            std::vector<std::pair<int,int>> stack{{row, col}};
            seen[row][col] = 1;
            while (!stack.empty()) {
                const auto cell = stack.back();
                stack.pop_back();
                cells.push_back(cell);
                for (const auto &step : steps) {
                    const int rr = cell.first + step[0];
                    const int cc = cell.second + step[1];
                    if (rr < 0 || rr >= rows || cc < 0 || cc >= cols) continue;
                    if (grid[rr][cc] != 1 || seen[rr][cc]) continue;
                    seen[rr][cc] = 1;
                    stack.push_back({rr, cc});
                }
            }
            int top = cells[0].first;
            int left = cells[0].second;
            for (const auto &cell : cells) {
                top = std::min(top, cell.first);
                left = std::min(left, cell.second);
            }
            for (auto &cell : cells) {
                cell.first -= top;
                cell.second -= left;
            }
            std::sort(cells.begin(), cells.end());
            shapes.insert(cells);
        }
    }
    return static_cast<int>(shapes.size());
}
