long long countPaths(int nodes, std::vector<std::pair<int,int>> edges) {
    const long long mod = 1000000007LL;
    if (nodes < 1) return 0;
    std::vector<std::vector<int>> next(nodes);
    std::vector<int> waiting(nodes, 0);
    for (const auto &edge : edges) {
        if (edge.first < 0 || edge.first >= nodes || edge.second < 0 || edge.second >= nodes) {
            throw std::invalid_argument("endpoint out of range");
        }
        next[edge.first].push_back(edge.second);
        waiting[edge.second] += 1;
    }
    std::vector<long long> ways(nodes, 0);
    ways[0] = 1;
    std::vector<int> queue;
    for (int node = 0; node < nodes; ++node) {
        if (waiting[node] == 0) queue.push_back(node);
    }
    for (std::size_t head = 0; head < queue.size(); ++head) {
        const int node = queue[head];
        for (int other : next[node]) {
            ways[other] = (ways[other] + ways[node]) % mod;
            waiting[other] -= 1;
            if (waiting[other] == 0) queue.push_back(other);
        }
    }
    return ways[nodes - 1];
}
