int partitionDiff(std::vector<int> values) {
    long long total = 0;
    for (int value : values) {
        if (value < 0) throw std::invalid_argument("values must not be negative");
        total += value;
    }
    if (total > 200000) throw std::invalid_argument("total is too large");
    std::vector<char> reachable(total + 1, 0);
    reachable[0] = 1;
    for (int value : values) {
        for (long long sum = total; sum >= value; --sum) {
            if (reachable[sum - value]) reachable[sum] = 1;
        }
    }
    long long best = total;
    for (long long sum = 0; sum <= total; ++sum) {
        if (!reachable[sum]) continue;
        const long long difference = std::llabs(total - 2 * sum);
        if (difference < best) best = difference;
    }
