class EventBus {
  constructor() {
    this.table = new Map();
  }

  check(name, handler) {
    if (typeof name !== 'string' || name.length === 0) throw new Error('bad name');
    if (typeof handler !== 'function') throw new Error('bad handler');
  }

  entries(name) {
    if (!this.table.has(name)) this.table.set(name, []);
    return this.table.get(name);
  }

  on(name, handler) {
    this.check(name, handler);
    this.entries(name).push({ handler, once: false });
  }

  once(name, handler) {
    this.check(name, handler);
    this.entries(name).push({ handler, once: true });
  }

  off(name, handler) {
    this.check(name, handler);
    const list = this.table.get(name) || [];
    const at = list.findIndex((entry) => entry.handler === handler);
    if (at < 0) return false;
    list.splice(at, 1);
    return true;
  }

  listeners(name) {
    const list = this.table.get(name);
    return list ? list.length : 0;
  }

  emit(name, payload) {
    const list = [...(this.table.get(name) || [])];
    let called = 0;
    for (const entry of list) {
      if (entry.once) {
        const live = this.table.get(name) || [];
        const at = live.indexOf(entry);
        if (at >= 0) live.splice(at, 1);
      }
      entry.handler(payload);
      called += 1;
    }
    return called;
  }
}
