function memoize(fn) {
  if (typeof fn !== 'function') throw new Error('memoize needs a function');
  const cache = new Map();
  let hits = 0;
  let misses = 0;
  return {
    run(...args) {
      const key = JSON.stringify(args);
      if (cache.has(key)) {
        hits += 1;
        return cache.get(key);
      }
      misses += 1;
      const value = fn(...args);
      cache.set(key, value);
      return value;
    },
    stats() {
      return { hits, misses, size: cache.size };
    },
  };
}
