class TokenBucket {
  constructor(capacity, refillPerMinute) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new Error('bad capacity');
    if (!Number.isFinite(refillPerMinute) || refillPerMinute < 0) throw new Error('bad refill rate');
    this.capacity = capacity;
    this.rate = refillPerMinute;
    this.tokens = capacity;
  }

  advance(seconds) {
    if (!Number.isFinite(seconds) || seconds < 0) throw new Error('seconds must not be negative');
    this.tokens = Math.min(this.capacity, this.tokens + (this.rate * seconds) / 60);
    return this.tokens;
  }

  take(count) {
    if (!Number.isFinite(count) || count < 0) throw new Error('count must not be negative');
    if (count > this.tokens) return false;
    this.tokens -= count;
    return true;
  }
}
