function groupTotals(rows) {
  const teams = new Map();
  for (const row of rows) {
    if (typeof row !== 'object' || row === null) throw new Error('rows must be objects');
    const { team, region, amount } = row;
    if (typeof team !== 'string' || team.length === 0) throw new Error('a team is needed');
    if (typeof region !== 'string' || region.length === 0) throw new Error('a region is needed');
    if (!Number.isFinite(amount)) throw new Error('the amount must be finite');
    if (!teams.has(team)) teams.set(team, { total: 0, regions: new Map() });
    const entry = teams.get(team);
    entry.total += amount;
    entry.regions.set(region, (entry.regions.get(region) || 0) + amount);
  }
  const out = [];
  for (const [team, entry] of teams.entries()) {
    const regions = Array.from(entry.regions.entries())
      .map(([region, total]) => ({ region, total }))
      .sort((left, right) => (left.region < right.region ? -1 : left.region > right.region ? 1 : 0));
    out.push({ team, total: entry.total, regions });
  }
  out.sort((left, right) => (left.team < right.team ? -1 : left.team > right.team ? 1 : 0));
  return out;
}
