type OrderState = 'new' | 'paid' | 'shipped' | 'cancelled';

interface Order {
  state: OrderState;
  paid: number;
  tracking: string | null;
  log: string[];
}

type OrderEvent =
  | { type: 'pay'; amount: number }
  | { type: 'ship'; tracking: string }
  | { type: 'cancel'; reason: string };

function reduceOrder(order: Order, event: OrderEvent): Order {
  const next: Order = { ...order, log: [...order.log] };
  if (event.type === 'pay') {
    if (order.state !== 'new') throw new Error('cannot pay from ' + order.state);
    if (!Number.isFinite(event.amount) || event.amount <= 0) throw new Error('bad amount');
    next.state = 'paid';
    next.paid = order.paid + event.amount;
    next.log.push('pay:' + event.amount);
    return next;
  }
  if (event.type === 'ship') {
    if (order.state !== 'paid') throw new Error('cannot ship from ' + order.state);
    if (typeof event.tracking !== 'string' || event.tracking.length === 0) {
      throw new Error('a tracking code is needed');
    }
    next.state = 'shipped';
    next.tracking = event.tracking;
    next.log.push('ship:' + event.tracking);
    return next;
  }
  if (event.type === 'cancel') {
    if (order.state !== 'new' && order.state !== 'paid') throw new Error('cannot cancel ' + order.state);
    if (typeof event.reason !== 'string' || event.reason.length === 0) {
      throw new Error('a reason is needed');
    }
    next.state = 'cancelled';
    next.log.push('cancel:' + event.reason);
    return next;
  }
  throw new Error('unknown event');
}
```

