class Stats {
  private total = 0;
  private average = 0;
  private squares = 0;

  size(): number {
    return this.total;
  }

  add(value: number): void {
    if (!Number.isFinite(value)) throw new Error('value must be finite');
    this.total += 1;
    const delta = value - this.average;
    this.average += delta / this.total;
    this.squares += delta * (value - this.average);
  }

  mean(): number {
    if (this.total === 0) return 0;
    return Number(this.average.toFixed(6));
  }

  variance(): number {
    if (this.total === 0) return 0;
    return Number((this.squares / this.total).toFixed(6));
  }

  stddev(): number {
    if (this.total === 0) return 0;
    return Number(Math.sqrt(this.squares / this.total).toFixed(6));
  }

  summary(): { size: number; mean: number; variance: number } {
    return { size: this.total, mean: this.mean(), variance: this.variance() };
  }
}
```

