```typescript
class BitField {
  private readonly bits: number;
  private readonly words: Uint32Array;

  constructor(bits: number) {
    if (!Number.isInteger(bits) || bits < 1 || bits > 4096) throw new Error('bad size');
    this.bits = bits;
    this.words = new Uint32Array(Math.ceil(bits / 32));
  }

  private check(at: number): void {
    if (!Number.isInteger(at) || at < 0 || at >= this.bits) throw new Error('index out of range');
  }

  set(at: number): boolean {
    this.check(at);
    const word = at >>> 5;
    const mask = 1 << (at & 31);
    if ((this.words[word] & mask) !== 0) return false;
    this.words[word] |= mask;
    return true;
  }

  clear(at: number): boolean {
    this.check(at);
    const word = at >>> 5;
    const mask = 1 << (at & 31);
    if ((this.words[word] & mask) === 0) return false;
    this.words[word] &= ~mask;
    return true;
  }

  test(at: number): boolean {
    this.check(at);
    return (this.words[at >>> 5] & (1 << (at & 31))) !== 0;
  }

  count(): number {
    let total = 0;
    for (const word of this.words) {
      let value = word;
      while (value !== 0) {
        value &= value - 1;
        total += 1;
      }
    }
    return total;
  }

  ranges(): Array<[number, number]> {
    const out: Array<[number, number]> = [];
    let start = -1;
    for (let at = 0; at < this.bits; at += 1) {
      if (this.test(at)) {
        if (start < 0) start = at;
      } else if (start >= 0) {
        out.push([start, at - 1]);
        start = -1;
      }
    }
    if (start >= 0) out.push([start, this.bits - 1]);
    return out;
  }
}
```

