function planChunks(total: number, chunkSize: number, done: number): Array<[number, number]> {
  if (!Number.isInteger(total) || total < 1) throw new Error('total must be a positive integer');
  if (!Number.isInteger(chunkSize) || chunkSize < 1 || chunkSize > total) {
    throw new Error('the chunk size is out of range');
  }
  if (!Number.isInteger(done) || done < 0 || done > total) throw new Error('done is out of range');
  const plan: Array<[number, number]> = [];
  let start = 0;
  while (start < total) {
    const end = Math.min(start + chunkSize - 1, total - 1);
    if (end >= done) {
      plan.push([Math.max(start, done), end]);
    }
    start = end + 1;
  }
  return plan;
}
```

