function balancedSplit(weights: number[], parts: number): number[] {
  if (!Number.isInteger(parts) || parts < 1) throw new Error('parts must be a positive integer');
  const loads = new Array(parts).fill(0);
  const items: Array<{ weight: number; index: number }> = [];
  weights.forEach((weight, index) => {
    if (!Number.isFinite(weight) || weight < 0) throw new Error('weights must be non-negative');
    items.push({ weight, index });
  });
  items.sort((left, right) => right.weight - left.weight || left.index - right.index);
  for (const item of items) {
    let target = 0;
    for (let bucket = 1; bucket < parts; bucket += 1) {
      if (loads[bucket] < loads[target]) target = bucket;
    }
    loads[target] += item.weight;
  }
  return loads;
}
