```typescript
interface Order {
  side: 'buy' | 'sell';
  price: number;
  qty: number;
}

function runMatch(orders: Order[]): Array<{ price: number; qty: number }> {
  const buys: Order[] = [];
  const sells: Order[] = [];
  const trades: Array<{ price: number; qty: number }> = [];
  for (const order of orders) {
    if (order.side !== 'buy' && order.side !== 'sell') throw new Error('unknown side');
    if (!Number.isInteger(order.qty) || order.qty <= 0) throw new Error('bad quantity');
    if (!Number.isFinite(order.price) || order.price < 0) throw new Error('bad price');
    let remaining = order.qty;
    if (order.side === 'buy') {
      sells.sort((left, right) => left.price - right.price);
      while (remaining > 0 && sells.length > 0 && sells[0].price <= order.price) {
        const resting = sells[0];
        const take = Math.min(remaining, resting.qty);
        trades.push({ price: resting.price, qty: take });
        remaining -= take;
        resting.qty -= take;
        if (resting.qty === 0) sells.shift();
      }
      if (remaining > 0) buys.push({ side: 'buy', price: order.price, qty: remaining });
    } else {
      buys.sort((left, right) => right.price - left.price);
      while (remaining > 0 && buys.length > 0 && buys[0].price >= order.price) {
        const resting = buys[0];
        const take = Math.min(remaining, resting.qty);
        trades.push({ price: resting.price, qty: take });
        remaining -= take;
        resting.qty -= take;
        if (resting.qty === 0) buys.shift();
      }
      if (remaining > 0) sells.push({ side: 'sell', price: order.price, qty: remaining });
    }
  }
  return trades;
}
```

