def success_rate(ok, total):
    """Fraction of successful calls, between 0 and 1."""
    if not isinstance(ok, int) or not isinstance(total, int):
        raise ValueError("counts must be integers")
    if ok < 0 or total < 0:
        raise ValueError("counts must not be negative")
    if ok > total:
        raise ValueError("successes cannot exceed the total")
    if total == 0:
        return None
    return ok / total

