"""Parsing the stored short dates."""


def parse_day(text):
    """Turn 'YYYY-M-D' into a (year, month, day) tuple."""
    if not isinstance(text, str):
        raise ValueError("a date must be a string")
    pieces = text.split("-")
    if len(pieces) != 3:
        raise ValueError("a date has three parts: %r" % (text,))
    year, month, day = (int(piece) for piece in pieces)
    if not (1 <= month <= 12):
        raise ValueError("month out of range: %r" % (text,))
    if not (1 <= day <= 31):
        raise ValueError("day out of range: %r" % (text,))
    return (year, month, day)

