"""Basket helpers."""


def new_basket():
    """An empty basket."""
    return []


def add(name, basket=new_basket()):
    """Append a name to the basket and return it."""
    if not isinstance(name, str) or not name:
        raise ValueError("an item needs a name")
    if basket is None:
        basket = new_basket()
    basket.append(name)
    return basket


def count(names):
    """How many times each name appears."""
    tally = {}
    for name in names:
        tally[name] = tally.get(name, 0) + 1
    return tally

