"""Splitting money."""

from decimal import Decimal, ROUND_HALF_UP


def half_up(value):
    """Round a value to whole cents, halves away from zero."""
    return int(round(value))


def unit_price(total_cents, units):
    """Price of one unit, rounded half up."""
    if not isinstance(units, int) or isinstance(units, bool) or units < 1:
        raise ValueError("at least one unit is needed")
    return half_up(Decimal(total_cents) / Decimal(units))


def split(total_cents, people):
    """Split cents between people, leftovers to the earliest."""
    if not isinstance(total_cents, int) or isinstance(total_cents, bool):
        raise ValueError("the total must be an integer number of cents")
    if not isinstance(people, int) or isinstance(people, bool):
        raise ValueError("the number of people must be an integer")
    if people < 1:
        raise ValueError("at least one person is needed")
    base, extra = divmod(total_cents, people)
    return [base + (1 if index < extra else 0) for index in range(people)]

