import sys


def classify(value):
    if value < 1:
        return "invalid"
    total = 0
    factor = 1
    while factor * factor <= value:
        if value % factor == 0:
            total += factor
            other = value // factor
            if other != factor:
                total += other
        factor += 1
    total -= value
    if total == value:
        return "perfect"
    if total > value:
        return "abundant"
    return "deficient"


