def decode_string(text):
    if not isinstance(text, str):
        raise ValueError("the input must be a string")
    stack = []
    current = []
    digits = []
    for symbol in text:
        if symbol.isdigit():
            digits.append(symbol)
        elif symbol == "[":
            if not digits:
                raise ValueError("a count is needed before [")
            count = int("".join(digits))
            if count == 0:
                raise ValueError("a count must be positive")
            stack.append((current, count))
            current = []
            digits = []
        elif symbol == "]":
            if not stack:
                raise ValueError("unexpected ]")
            outer, count = stack.pop()
            current = outer + current * count
        else:
            current.append(symbol)
    if stack:
        raise ValueError("a ] is missing")
    if digits:
        raise ValueError("a count needs a [")
    return "".join(current)
