def partition_labels(text):
    if not isinstance(text, str):
        raise ValueError("the text must be a string")
    last = {}
    for index, letter in enumerate(text):
        last[letter] = index
    sizes = []
    start = 0
    reach = 0
    for index, letter in enumerate(text):
        if last[letter] > reach:
            reach = last[letter]
        if index == reach:
            sizes.append(reach - start + 1)
            start = reach + 1
    return sizes
