def network_delay(times, nodes, source):
    if nodes < 1:
        raise ValueError("at least one node is needed")
    if not 1 <= source <= nodes:
        raise ValueError("the source is out of range")
    edges = [[] for _ in range(nodes + 1)]
    for start, stop, seconds in times:
        if seconds <= 0:
            raise ValueError("durations must be positive")
        if not 1 <= start <= nodes or not 1 <= stop <= nodes:
            raise ValueError("endpoint out of range")
        edges[start].append((stop, seconds))
    best = [None] * (nodes + 1)
    best[source] = 0
    queue = [(0, source)]
    while queue:
        distance, node = heapq.heappop(queue)
        if best[node] is not None and distance > best[node]:
            continue
        for other, seconds in edges[node]:
            candidate = distance + seconds
            if best[other] is None or candidate < best[other]:
                best[other] = candidate
                heapq.heappush(queue, (candidate, other))
    if any(best[node] is None for node in range(1, nodes + 1)):
        return -1
    return max(best[1:])


