def zigzag(text, rows):
    if not isinstance(text, str):
        raise ValueError("the text must be a string")
    if not isinstance(rows, int) or isinstance(rows, bool):
        raise ValueError("the row count must be an integer")
    if rows < 1:
        raise ValueError("the row count must be positive")
    if rows == 1 or rows >= len(text):
        return text
    bands = [[] for _ in range(rows)]
    row = 0
    step = 1
    for letter in text:
        bands[row].append(letter)
        if row == 0:
            step = 1
        elif row == rows - 1:
            step = -1
        row += step
    return "".join("".join(band) for band in bands)
