std::vector<std::string> restoreIps(std::string digits) {
    if (digits.size() > 12) throw std::invalid_argument("too many digits");
    for (char symbol : digits) {
        if (symbol < '0' || symbol > '9') throw std::invalid_argument("digits only");
    }
    std::vector<std::string> out;
    const int size = static_cast<int>(digits.size());
    for (int first = 1; first <= 3 && first < size; ++first) {
        for (int second = first + 1; second <= first + 3 && second < size; ++second) {
            for (int third = second + 1; third <= second + 3 && third < size; ++third) {
                std::vector<std::string> pieces;
                pieces.push_back(digits.substr(0, first));
                pieces.push_back(digits.substr(first, second - first));
                pieces.push_back(digits.substr(second, third - second));
                pieces.push_back(digits.substr(third));
                bool good = true;
                for (const auto &piece : pieces) {
                    if (piece.empty() || piece.size() > 3) {
                        good = false;
                        break;
                    }
                    if (piece.size() > 1 && piece[0] == '0') {
                        good = false;
                        break;
                    }
                    if (std::stoi(piece) > 255) {
                        good = false;
                        break;
                    }
                }
                if (!good) continue;
                out.push_back(pieces[0] + "." + pieces[1] + "." + pieces[2] + "." + pieces[3]);
            }
        }
    }
    std::sort(out.begin(), out.end());
    return out;
}
