long long decodeWays(std::string digits) {
    const long long mod = 1000000007LL;
    for (char symbol : digits) {
        if (symbol < '0' || symbol > '9') throw std::invalid_argument("digits only");
    }
    const int size = static_cast<int>(digits.size());
    if (size == 0) return 1;
    long long older = 1;
    long long previous = digits[0] == '0' ? 0 : 1;
    for (int at = 2; at <= size; ++at) {
        long long current = 0;
        if (digits[at - 1] != '0') current = previous;
        const int pair = (digits[at - 2] - '0') * 10 + (digits[at - 1] - '0');
        if (digits[at - 2] != '0' && pair >= 10 && pair <= 26) current = (current + older) % mod;
        older = previous;
        previous = current;
    }
    return previous;
}
