std::vector<int> nextGreaterCircular(std::vector<int> values) {
    const int size = static_cast<int>(values.size());
    if (size > 200000) throw std::invalid_argument("too many values");
    std::vector<int> out(size, -1);
    std::vector<int> stack;
    for (int step = 0; step < 2 * size; ++step) {
        const int index = step % size;
        while (!stack.empty() && values[stack.back()] < values[index]) {
            out[stack.back()] = values[index];
            stack.pop_back();
        }
        if (step < size) stack.push_back(index);
    }
    return out;
}
