bool isInterleave(std::string left, std::string right, std::string whole) {
    if (left.size() > 2000 || right.size() > 2000) throw std::invalid_argument("input too long");
    if (left.size() + right.size() != whole.size()) return false;
    const int width = static_cast<int>(right.size());
    std::vector<char> reachable(width + 1, 0);
    reachable[0] = 1;
    for (int col = 1; col <= width; ++col) {
        reachable[col] = reachable[col - 1] && right[col - 1] == whole[col - 1];
    }
    for (int row = 1; row <= static_cast<int>(left.size()); ++row) {
        reachable[0] = reachable[0] && left[row - 1] == whole[row - 1];
        for (int col = 1; col <= width; ++col) {
            const bool fromLeft = reachable[col] && left[row - 1] == whole[row + col - 1];
            const bool fromRight = reachable[col - 1] && right[col - 1] == whole[row + col - 1];
            reachable[col] = fromLeft || fromRight;
        }
    }
    return reachable[width] != 0;
}
