std::vector<std::vector<int>> rotateMatrix(std::vector<std::vector<int>> grid) {
    const int size = static_cast<int>(grid.size());
    for (const auto &row : grid) {
        if (static_cast<int>(row.size()) != size) throw std::invalid_argument("grid must be square");
    }
    for (int layer = 0; layer < size / 2; ++layer) {
        const int last = size - 1 - layer;
        for (int offset = layer; offset < last; ++offset) {
            const int far = size - 1 - offset;
            const int saved = grid[layer][offset];
            grid[layer][offset] = grid[far][layer];
            grid[far][layer] = grid[last][far];
            grid[last][far] = grid[offset][last];
            grid[offset][last] = saved;
