double medianTwo(std::vector<int> left, std::vector<int> right) {
    for (std::size_t at = 1; at < left.size(); ++at) {
        if (left[at] < left[at - 1]) throw std::invalid_argument("left is not sorted");
    }
    for (std::size_t at = 1; at < right.size(); ++at) {
        if (right[at] < right[at - 1]) throw std::invalid_argument("right is not sorted");
    }
    const int total = static_cast<int>(left.size() + right.size());
    if (total == 0) throw std::invalid_argument("at least one value is needed");
    if (left.size() > right.size()) std::swap(left, right);
    const int n = static_cast<int>(left.size());
    const int m = static_cast<int>(right.size());
    const auto kth = [&](int k) {
        int low = std::max(0, k - m);
        int high = std::min(k, n);
        while (low <= high) {
            const int takeLeft = (low + high) / 2;
            const int takeRight = k - takeLeft;
            const int leftMax = takeLeft == 0 ? INT_MIN : left[takeLeft - 1];
            const int leftMin = takeLeft == n ? INT_MAX : left[takeLeft];
            const int rightMax = takeRight == 0 ? INT_MIN : right[takeRight - 1];
            const int rightMin = takeRight == m ? INT_MAX : right[takeRight];
            if (leftMax <= rightMin && rightMax <= leftMin) return std::max(leftMax, rightMax);
