                high = takeLeft - 1;
            } else {
                low = takeLeft + 1;
            }
        }
        throw std::runtime_error("unreachable");
    };
    if (total % 2 == 1) return static_cast<double>(kth(total / 2 + 1));
    const long long low = kth(total / 2);
    const long long high = kth(total / 2 + 1);
    return static_cast<double>(low + high) / 2.0;
}
