    if (rows == 0 || static_cast<int>(word.size()) > rows * cols) return false;
    std::vector<std::vector<char>> used(rows, std::vector<char>(cols, 0));
    const int steps[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    std::function<bool(int, int, int)> walk = [&](int row, int col, int at) {
        if (at == static_cast<int>(word.size())) return true;
        if (row < 0 || row >= rows || col < 0 || col >= cols) return false;
        if (used[row][col] || grid[row][col] != word[at]) return false;
        used[row][col] = 1;
        bool found = false;
