std::string fractionToDecimal(int numerator, int denominator) {
    if (denominator == 0) throw std::invalid_argument("the denominator must not be zero");
    long long top = numerator;
    long long bottom = denominator;
    std::string out;
    if ((top < 0) != (bottom < 0)) out += "-";
    top = std::llabs(top);
    bottom = std::llabs(bottom);
    out += std::to_string(top / bottom);
    long long rest = top % bottom;
    if (rest == 0) return out;
    out += ".";
    std::unordered_map<long long, int> seen;
    std::string digits;
    while (rest != 0) {
        const auto found = seen.find(rest);
        if (found != seen.end()) {
            digits.insert(static_cast<std::size_t>(found->second), "(");
            digits += ")";
            break;
        }
        seen[rest] = static_cast<int>(digits.size());
        rest *= 10;
        digits += static_cast<char>('0' + rest / bottom);
        rest %= bottom;
    }
    return out + digits;
}
