long long sumRanges(std::vector<int> values) {
    const int size = static_cast<int>(values.size());
    if (size > 200000) throw std::invalid_argument("too many values");
    const auto contribution = [&](bool wantsMax) {
        std::vector<int> stack;
        std::vector<long long> left(size), right(size);
        for (int at = 0; at < size; ++at) {
            while (!stack.empty()) {
                const int other = values[stack.back()];
                const bool drop = wantsMax ? values[at] > other : values[at] < other;
                if (!drop) break;
                stack.pop_back();
            }
            left[at] = stack.empty() ? at + 1 : at - stack.back();
            stack.push_back(at);
        }
        stack.clear();
        for (int at = size - 1; at >= 0; --at) {
            while (!stack.empty()) {
                const int other = values[stack.back()];
                const bool drop = wantsMax ? values[at] >= other : values[at] <= other;
                if (!drop) break;
                stack.pop_back();
            }
            right[at] = stack.empty() ? size - at : stack.back() - at;
            stack.push_back(at);
        }
        long long total = 0;
        for (int at = 0; at < size; ++at) total += static_cast<long long>(values[at]) * left[at] * right[at];
