def suffix_lcp(text):
    if not isinstance(text, str):
        raise ValueError("the text must be a string")
    for letter in text:
        if letter < "a" or letter > "z":
            raise ValueError("only lower case letters are allowed")
    size = len(text)
    order = list(range(size))
    order.sort(key=lambda start: text[start:])
    rank = [0] * size
    for place, start in enumerate(order):
        rank[start] = place
    lcp = [0] * size
    length = 0
    for start in range(size):
        if rank[start] == 0:
            length = 0
            continue
        other = order[rank[start] - 1]
        while start + length < size and other + length < size and text[start + length] == text[other + length]:
            length += 1
        lcp[rank[start]] = length
        if length > 0:
            length -= 1
    return order, lcp
