import heapq


def refuel(stations, target, start):
    if target < 0 or start < 0:
        raise ValueError("distance and fuel must not be negative")
    previous = -1
    for pair in stations:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError("a station is a (distance, fuel) pair")
        distance, fuel = pair
        if distance < 0 or fuel < 0:
            raise ValueError("distance and fuel must not be negative")
        if distance > target:
            raise ValueError("a station lies beyond the target")
        if distance <= previous:
            raise ValueError("stations must be sorted by distance")
        previous = distance
    if start >= target:
        return 0
    available = []
    stops = 0
    position = 0
    fuel = start
    at = 0
    while position + fuel < target:
        reach = position + fuel
        while at < len(stations) and stations[at][0] <= reach:
            heapq.heappush(available, -stations[at][1])
            at += 1
        if not available:
            return -1
        bonus = -heapq.heappop(available)
        if bonus == 0:
            continue
        position = reach
        fuel = bonus
        stops += 1
    return stops
