def evaluate(expr):
    if not isinstance(expr, str):
        raise ValueError("the expression must be a string")
    tokens = []
    for symbol in expr:
        if symbol.isdigit():
            raise ValueError("digits are not part of this language")
        if symbol.isspace():
            continue
        if symbol not in "TF!&|()":
            raise ValueError("unknown character %r" % (symbol,))
        tokens.append(symbol)
    if not tokens:
        raise ValueError("the expression is empty")
    position = [0]

    def peek():
        return tokens[position[0]] if position[0] < len(tokens) else None

    def take():
        symbol = peek()
        if symbol is None:
            raise ValueError("the expression ended too early")
        position[0] += 1
        return symbol

    def parse_or():
        value = parse_and()
        while peek() == "|":
            take()
            value = parse_and() or value
        return value

    def parse_and():
        value = parse_not()
        while peek() == "&":
            take()
            value = parse_not() and value
        return value

    def parse_not():
        if peek() == "!":
            take()
            return not parse_not()
        return parse_atom()

    def parse_atom():
        symbol = take()
        if symbol == "T":
            return True
        if symbol == "F":
            return False
        if symbol == "(":
            value = parse_or()
            if take() != ")":
                raise ValueError("a ) is missing")
            return value
        raise ValueError("unexpected token %r" % (symbol,))

    result = parse_or()
    if position[0] != len(tokens):
        raise ValueError("trailing tokens")
    return result
