from collections import deque


def worst_windows(values, width, limit):
    if not isinstance(values, list):
        raise ValueError("a list of integers is needed")
    if not isinstance(width, int) or isinstance(width, bool) or width < 1:
        raise ValueError("the width must be a positive integer")
    if width > len(values):
        raise ValueError("the width is larger than the list")
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
        raise ValueError("the limit must not be negative")
    for value in values:
        if not isinstance(value, int) or isinstance(value, bool):
            raise ValueError("values must be integers")
    highs = deque()
    lows = deque()
    counted = 0
    for index, value in enumerate(values):
        while highs and values[highs[-1]] <= value:
            highs.pop()
        highs.append(index)
        while lows and values[lows[-1]] >= value:
            lows.pop()
        lows.append(index)
        start = index - width + 1
        if start < 0:
            continue
        while highs[0] < start:
            highs.popleft()
        while lows[0] < start:
            lows.popleft()
        if values[highs[0]] - values[lows[0]] > limit:
            counted += 1
    return counted
