```javascript
function parseHexdump(text) {
  if (typeof text !== 'string') throw new Error('text must be a string');
  const bytes = [];
  const lines = text.split('\n');
  for (const raw of lines) {
    const line = raw.replace(/\s+$/, '');
    if (line.length === 0) continue;
    const bars = line.split('|');
    if (bars.length !== 3) throw new Error('a line needs one ascii column');
    const head = bars[0].trim();
    const ascii = bars[1];
    const tail = bars[2].trim();
    if (tail.length !== 0) throw new Error('unexpected text after the ascii column');
    const pieces = head.split(/\s+/);
    const offset = parseInt(pieces[0], 16);
    if (!/^[0-9A-Fa-f]{8}$/.test(pieces[0])) throw new Error('bad offset: ' + pieces[0]);
    if (offset !== bytes.length) throw new Error('offset ' + offset + ' does not match ' + bytes.length);
    const decoded = [];
    for (const piece of pieces.slice(1)) {
      if (!/^[0-9A-Fa-f]{2}$/.test(piece)) throw new Error('bad byte: ' + piece);
      decoded.push(parseInt(piece, 16));
    }
    const expected = decoded
      .map((value) => (value >= 0x20 && value <= 0x7e ? String.fromCharCode(value) : '.'))
      .join('');
    if (ascii !== expected) throw new Error('ascii column mismatch: ' + ascii + ' != ' + expected);
    bytes.push(...decoded);
  }
  return bytes;
}
```

