class RollingWindow {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new Error('bad capacity');
    this.capacity = capacity;
    this.items = [];
  }

  add(value) {
    if (!Number.isFinite(value)) throw new Error('not a finite number');
    this.items.push(value);
    if (this.items.length > this.capacity) this.items.shift();
  }

  size() {
    return this.items.length;
  }

  values() {
    return this.items.slice().sort((left, right) => left - right);
  }

  quantile(fraction) {
    if (!Number.isFinite(fraction) || fraction < 0 || fraction > 1) throw new Error('bad fraction');
    const sorted = this.values();
    if (sorted.length === 0) throw new Error('the window is empty');
    const rank = Math.min(sorted.length, Math.max(1, Math.ceil(fraction * sorted.length)));
    return sorted[rank - 1];
  }
}
```

