const PAIRS = { ')': '(', ']': '[', '}': '{' };

function scanBrackets(text) {
  if (typeof text !== 'string') throw new Error('text must be a string');
  const stack = [];
  for (let index = 0; index < text.length; index += 1) {
    const symbol = text[index];
    if (symbol === '(' || symbol === '[' || symbol === '{') {
      stack.push({ symbol, index });
      continue;
    }
    if (symbol === ')' || symbol === ']' || symbol === '}') {
      if (stack.length === 0) return { ok: false, kind: 'unexpected-close', index };
      const open = stack.pop();
      if (open.symbol !== PAIRS[symbol]) return { ok: false, kind: 'mismatch', index };
      continue;
    }
    return { ok: false, kind: 'bad-char', index };
  }
  if (stack.length > 0) {
    const open = stack[stack.length - 1];
    return { ok: false, kind: 'unclosed', index: open.index };
  }
  return { ok: true };
}
