function checkMatrix(matrix, label) {
  if (!Array.isArray(matrix)) throw new Error(label + ' must be an array');
  const width = matrix.length === 0 ? 0 : matrix[0].length;
  for (const row of matrix) {
    if (!Array.isArray(row) || row.length !== width) throw new Error(label + ' rows differ in length');
    for (const value of row) {
      if (!Number.isFinite(value)) throw new Error(label + ' holds a non-finite value');
    }
  }
}

function multiply(left, right) {
  checkMatrix(left, 'left');
  checkMatrix(right, 'right');
  if (left.length === 0 || right.length === 0) return [];
  const shared = left[0].length;
  if (shared !== right.length) throw new Error('shapes do not fit');
  const product = left.map(() => new Array(right[0].length).fill(0));
  for (let row = 0; row < left.length; row += 1) {
    for (let middle = 0; middle < shared; middle += 1) {
      const factor = left[row][middle];
      if (factor === 0) continue;
      for (let col = 0; col < right[0].length; col += 1) {
        const other = right[middle][col];
        if (other === 0) continue;
        product[row][col] += factor * other;
      }
    }
  }
  return product;
}
