interface CurrencyRule {
  symbol: string;
  decimals: number;
  before: boolean;
  group: string;
  decimal: string;
}

const RULES: Record<string, CurrencyRule> = {
  USD: { symbol: '$', decimals: 2, before: true, group: ',', decimal: '.' },
  EUR: { symbol: '€', decimals: 2, before: false, group: '.', decimal: ',' },
  JPY: { symbol: '¥', decimals: 0, before: true, group: ',', decimal: '.' },
  KWD: { symbol: 'KD', decimals: 3, before: false, group: ',', decimal: '.' },
};

function groupDigits(digits: string, separator: string): string {
  const parts: string[] = [];
  for (let end = digits.length; end > 0; end -= 3) {
    parts.unshift(digits.slice(Math.max(0, end - 3), end));
  }
  return parts.join(separator);
}

function formatMoney(minor: number, currency: string): string {
  if (!Number.isInteger(minor)) throw new Error('the amount must be an integer');
  const rule = RULES[currency];
  if (rule === undefined) throw new Error('unknown currency: ' + currency);
  const negative = minor < 0;
  const absolute = Math.abs(minor);
  const scale = 10 ** rule.decimals;
  const whole = Math.floor(absolute / scale);
  const fraction = absolute - whole * scale;
  let number = groupDigits(String(whole), rule.group);
  if (rule.decimals > 0) {
    number += rule.decimal + String(fraction).padStart(rule.decimals, '0');
  }
  const sign = negative ? '-' : '';
  return rule.before ? sign + rule.symbol + number : sign + number + ' ' + rule.symbol;
}
