interface CsvOptions {
  delimiter?: string;
  terminator?: string;
  quoteAll?: boolean;
}

function encodeField(field: string, delimiter: string, quoteAll: boolean): string {
  if (typeof field !== 'string') throw new Error('fields must be strings');
  const needsQuotes = quoteAll
    || field.includes(delimiter)
    || field.includes('"')
    || field.includes('\r')
    || field.includes('\n');
  if (!needsQuotes) return field;
  return '"' + field.split('"').join('""') + '"';
}

function toCsv(rows: string[][], options: CsvOptions = {}): string {
  const delimiter = options.delimiter === undefined ? ',' : options.delimiter;
  const terminator = options.terminator === undefined ? '\n' : options.terminator;
  const quoteAll = options.quoteAll === true;
  if (typeof delimiter !== 'string' || delimiter.length !== 1) throw new Error('bad delimiter');
  if (typeof terminator !== 'string' || terminator.length === 0) throw new Error('bad terminator');
  const lines = rows.map((row) => {
    if (!Array.isArray(row)) throw new Error('a row must be an array of fields');
    return row.map((field) => encodeField(field, delimiter, quoteAll)).join(delimiter);
  });
  return lines.join(terminator);
}
