```typescript
class IntervalSet {
  private intervals: Array<[number, number]> = [];

  private static check(start: number, end: number): void {
    if (!Number.isInteger(start) || !Number.isInteger(end)) throw new Error('bounds must be integers');
    if (end <= start) throw new Error('an interval must not be empty');
  }

  add(start: number, end: number): void {
    IntervalSet.check(start, end);
    const all: Array<[number, number]> = [...this.intervals, [start, end]];
    all.sort((left, right) => left[0] - right[0]);
    const merged: Array<[number, number]> = [];
    for (const piece of all) {
      const last = merged[merged.length - 1];
      if (last !== undefined && piece[0] <= last[1]) {
        last[1] = Math.max(last[1], piece[1]);
      } else {
        merged.push([piece[0], piece[1]]);
      }
    }
    this.intervals = merged;
  }

  remove(start: number, end: number): void {
    IntervalSet.check(start, end);
    const kept: Array<[number, number]> = [];
    for (const [low, high] of this.intervals) {
      if (high <= start || low >= end) {
        kept.push([low, high]);
        continue;
      }
      if (low < start) kept.push([low, start]);
      if (high > end) kept.push([end, high]);
    }
    this.intervals = kept;
  }

  measure(): number {
    let total = 0;
    for (const [low, high] of this.intervals) total += high - low;
    return total;
  }

  contains(value: number): boolean {
    return this.intervals.some(([low, high]) => low <= value && value < high);
  }

  ranges(): Array<[number, number]> {
    return this.intervals.map(([low, high]) => [low, high]);
  }
}
