const DATE_UNITS = ['Y', 'M', 'D'];
const TIME_UNITS = ['H', 'M', 'S'];

function parseIsoDuration(text: string): number {
  if (typeof text !== 'string' || !text.startsWith('P')) throw new Error('an iso duration starts with P');
  let seconds = 0;
  let index = 1;
  let inTime = false;
  let dateAt = 0;
  let timeAt = 0;
  while (index < text.length) {
    if (text[index] === 'T') {
      if (inTime) throw new Error('a duration has one T');
      inTime = true;
      index += 1;
      continue;
    }
    const start = index;
    while (index < text.length && text[index] >= '0' && text[index] <= '9') index += 1;
    if (start === index) throw new Error('a number is missing');
    const amount = Number(text.slice(start, index));
    const unit = text[index];
    index += 1;
    if (!inTime) {
      const at = DATE_UNITS.indexOf(unit);
      if (at < 0) throw new Error('unknown date unit: ' + unit);
      if (at < dateAt) throw new Error('date units are out of order');
      dateAt = at + 1;
      if (unit === 'Y') seconds += amount * 365 * 24 * 60 * 60;
      else if (unit === 'M') seconds += amount * 30 * 24 * 60 * 60;
      else seconds += amount * 24 * 60 * 60;
    } else {
      const at = TIME_UNITS.indexOf(unit);
      if (at < 0) throw new Error('unknown time unit: ' + unit);
      if (at < timeAt) throw new Error('time units are out of order');
      timeAt = at + 1;
      if (unit === 'H') seconds += amount * 60 * 60;
      else if (unit === 'M') seconds += amount * 60;
      else seconds += amount;
    }
  }
  return seconds;
}
