interface QueueStats {
  served: number;
  maxWaiting: number;
  totalWait: number;
}

function checkArrivals(arrivals: number[]): void {
  if (!Array.isArray(arrivals)) throw new Error('arrivals must be an array');
  let previous = -1;
  for (const value of arrivals) {
    if (!Number.isInteger(value) || value < 0) throw new Error('arrivals must be non-negative integers');
    if (value < previous) throw new Error('arrivals must be sorted');
    previous = value;
  }
}

function queueStats(arrivals: number[], service: number): QueueStats {
  checkArrivals(arrivals);
  if (!Number.isInteger(service) || service <= 0) throw new Error('the service time must be positive');
  const starts: number[] = [];
  for (let index = 0; index < arrivals.length; index += 1) {
    const freeAt = index === 0 ? 0 : starts[index - 1] + service;
    starts.push(Math.max(arrivals[index], freeAt));
  }
  let totalWait = 0;
  for (let index = 0; index < arrivals.length; index += 1) {
    totalWait += starts[index] - arrivals[index];
  }
  let maxWaiting = 0;
  let started = 0;
  for (let index = 0; index < arrivals.length; index += 1) {
    const now = arrivals[index];
    while (started < arrivals.length && starts[started] <= now) started += 1;
    const waiting = index + 1 - started;
    if (waiting > maxWaiting) maxWaiting = waiting;
  }
  return { served: arrivals.length, maxWaiting, totalWait };
}
