std::vector<int> removalOrder(int count, int step) {
    if (count < 1 || step < 1) throw std::invalid_argument("count and step must be positive");
    std::vector<int> tree(count + 1, 0);
    const auto update = [&](int at, int delta) {
        for (int index = at; index <= count; index += index & -index) tree[index] += delta;
    };
    const auto prefix = [&](int at) {
        int total = 0;
        for (int index = at; index > 0; index -= index & -index) total += tree[index];
        return total;
    };
    const auto kth = [&](int rank) {
        int position = 0;
        int bit = 1;
        while (bit * 2 <= count) bit *= 2;
        for (; bit > 0; bit /= 2) {
            const int next = position + bit;
            if (next <= count && tree[next] < rank) {
                position = next;
                rank -= tree[next];
            }
        }
        return position + 1;
    };
    for (int person = 1; person <= count; ++person) update(person, 1);
    std::vector<int> order;
    order.reserve(count);
    long long cursor = 0;
    for (int left = count; left >= 1; --left) {
        cursor = (cursor + step - 1) % left;
        const int target = kth(static_cast<int>(cursor) + 1);
        order.push_back(target);
        update(target, -1);
    }
    return order;
}
