int minPieces(std::string text, std::vector<std::string> words) {
    std::unordered_set<std::string> allowed;
    int longest = 0;
    for (const auto &word : words) {
        if (word.empty()) throw std::invalid_argument("words must not be empty");
        allowed.insert(word);
        longest = std::max(longest, static_cast<int>(word.size()));
    }
    const int size = static_cast<int>(text.size());
    const int missing = -1;
    std::vector<int> best(size + 1, missing);
    best[0] = 0;
    for (int stop = 1; stop <= size; ++stop) {
        for (int length = 1; length <= longest && length <= stop; ++length) {
            const int start = stop - length;
            if (best[start] == missing) continue;
            if (allowed.count(text.substr(start, length)) == 0) continue;
            const int candidate = best[start] + 1;
            if (best[stop] == missing || candidate < best[stop]) best[stop] = candidate;
        }
    }
    return best[size];
}
