    for (int value : values) {
        if (value < 0) throw std::invalid_argument("values must not be negative");
    }
    std::vector<int> padded;
    padded.push_back(1);
    for (int value : values) padded.push_back(value);
    padded.push_back(1);
    const int size = static_cast<int>(padded.size());
    std::vector<std::vector<int>> best(size, std::vector<int>(size, 0));
    for (int span = 2; span < size; ++span) {
        for (int left = 0; left + span < size; ++left) {
            const int right = left + span;
            int answer = 0;
            for (int middle = left + 1; middle < right; ++middle) {
                const int gain = padded[left] * padded[middle] * padded[right]
                    + best[left][middle] + best[middle][right];
                if (gain > answer) answer = gain;
            }
            best[left][right] = answer;
        }
    }
    return best[0][size - 1];
