int openMaze(std::vector<std::string> grid) {
    const int rows = static_cast<int>(grid.size());
    if (rows == 0) return -1;
    const int cols = static_cast<int>(grid[0].size());
    for (const auto &row : grid) {
        if (static_cast<int>(row.size()) != cols) throw std::invalid_argument("grid must be rectangular");
        for (char cell : row) {
            const bool known = cell == '#' || cell == '.' || cell == '@'
                || (cell >= 'a' && cell <= 'f') || (cell >= 'A' && cell <= 'F');
            if (!known) throw std::invalid_argument("unknown cell");
        }
    }
    int startRow = -1;
    int startCol = -1;
    for (int row = 0; row < rows && startRow < 0; ++row) {
        for (int col = 0; col < cols; ++col) {
            if (grid[row][col] == '@') {
                startRow = row;
                startCol = col;
                break;
            }
        }
    }
    if (startRow < 0) return -1;
    std::vector<std::vector<std::vector<char>>> seen(rows, std::vector<std::vector<char>>(cols, std::vector<char>(64, 0)));
    std::vector<std::array<int, 4>> queue{{startRow, startCol, 0, 0}};
    seen[startRow][startCol][0] = 1;
    const int steps[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    for (std::size_t head = 0; head < queue.size(); ++head) {
        const auto state = queue[head];
        const int row = state[0];
        const int col = state[1];
        const int mask = state[2];
        const int distance = state[3];
        const char cell = grid[row][col];
        if (cell >= 'a' && cell <= 'f') return distance;
        for (const auto &step : steps) {
            const int rr = row + step[0];
            const int cc = col + step[1];
            if (rr < 0 || rr >= rows || cc < 0 || cc >= cols) continue;
            const char target = grid[rr][cc];
            if (target == '#') continue;
            int deeper = mask;
            if (target >= 'a' && target <= 'f') deeper |= 1 << (target - 'a');
            if (target >= 'A' && target <= 'F' && ((mask >> (target - 'A')) & 1) == 0) continue;
            if (seen[rr][cc][deeper]) continue;
            seen[rr][cc][deeper] = 1;
            queue.push_back({rr, cc, deeper, distance + 1});
        }
    }
    return -1;
}
