    std::vector<int> stack;
    long long best = 0;
    for (int at = 0; at <= count; ++at) {
        const int current = at == count ? 0 : heights[at];
        while (!stack.empty() && heights[stack.back()] >= current) {
            const int height = heights[stack.back()];
            stack.pop_back();
            const int left = stack.empty() ? -1 : stack.back();
            const long long width = at - left - 1;
            best = std::max(best, static_cast<long long>(height) * width);
        }
        stack.push_back(at);
    }
    return best;
