long long tripletsBelow(std::vector<int> values, long long limit) {
    for (int value : values) {
        if (value < 0) throw std::invalid_argument("values must not be negative");
    }
    std::sort(values.begin(), values.end());
    const int size = static_cast<int>(values.size());
    long long total = 0;
    for (int first = 0; first + 2 < size; ++first) {
        int left = first + 1;
        int right = size - 1;
        while (left < right) {
            const long long sum = static_cast<long long>(values[first]) + values[left] + values[right];
            if (sum < limit) {
                total += right - left;
                left += 1;
            } else {
                right -= 1;
            }
        }
    }
    return total;
}
