    std::vector<long long> holding(limit + 1, negative);
    std::vector<long long> resting(limit + 1, 0);
    for (int price : prices) {
        for (int used = limit; used >= 1; --used) {
            if (resting[used - 1] != negative) {
                const long long fresh = resting[used - 1] - price;
                if (fresh > holding[used]) holding[used] = fresh;
            }
            if (holding[used] != negative) {
                const long long sold = holding[used] + price;
                if (sold > resting[used]) resting[used] = sold;
            }
        }
    }
    long long best = 0;
    for (int used = 0; used <= limit; ++used) best = std::max(best, resting[used]);
    return best;
