long long mergeStones(std::vector<int> piles) {
    for (int pile : piles) {
        if (pile <= 0) throw std::invalid_argument("piles must be positive");
    }
    const int size = static_cast<int>(piles.size());
    if (size < 2) return 0;
    std::vector<long long> prefix(size + 1, 0);
    for (int at = 0; at < size; ++at) prefix[at + 1] = prefix[at] + piles[at];
    std::vector<std::vector<long long>> best(size, std::vector<long long>(size, 0));
    for (int span = 2; span <= size; ++span) {
        for (int start = 0; start + span - 1 < size; ++start) {
            const int stop = start + span - 1;
            long long answer = LLONG_MAX;
            for (int split = start; split < stop; ++split) {
                const long long cost = best[start][split] + best[split + 1][stop];
                if (cost < answer) answer = cost;
            }
            best[start][stop] = answer + prefix[stop + 1] - prefix[start];
        }
    }
    return best[0][size - 1];
}
