def full_match(text, pattern):
    if not isinstance(text, str) or not isinstance(pattern, str):
        raise ValueError("both arguments must be strings")
    if pattern.startswith("*"):
        raise ValueError("a pattern cannot start with *")
    rows = len(text)
    cols = len(pattern)
    memo = {}

    def walk(at, into):
        key = (at, into)
        if key in memo:
            return memo[key]
        if into == cols:
            answer = at == rows
        else:
            first = at < rows and (pattern[into] == "." or pattern[into] == text[at])
            if into + 1 < cols and pattern[into + 1] == "*":
                answer = walk(at, into + 2) or (first and walk(at + 1, into))
            else:
                answer = first and walk(at + 1, into + 1)
        memo[key] = answer
        return answer

    return walk(0, 0)
```

