def all_sentences(text, words):
    if not isinstance(text, str):
        raise ValueError("the text must be a string")
    allowed = set()
    for word in words:
        if not isinstance(word, str) or not word:
            raise ValueError("words must be non-empty strings")
        allowed.add(word)
    if not text:
        return []
    longest = max((len(word) for word in allowed), default=0)
    memo = {}

    def walk(at):
        if at in memo:
            return memo[at]
        if at == len(text):
            return [""]
        sentences = []
        for length in range(1, longest + 1):
            stop = at + length
            if stop > len(text):
                break
            piece = text[at:stop]
            if piece not in allowed:
                continue
            for tail in walk(stop):
                sentences.append(piece if tail == "" else piece + " " + tail)
        memo[at] = sentences
        return sentences

    return sorted(walk(0))
