def alien_order(words):
    letters = set()
    for word in words:
        if not isinstance(word, str) or not word:
            raise ValueError("words must be non-empty strings")
        for letter in word:
            if letter < "a" or letter > "z":
                raise ValueError("lower case letters only")
            letters.add(letter)
    following = {letter: set() for letter in letters}
    waiting = {letter: 0 for letter in letters}
    for first, second in zip(words, words[1:]):
        limit = min(len(first), len(second))
        shared = 0
        while shared < limit and first[shared] == second[shared]:
            shared += 1
        if shared == limit:
            if len(first) > len(second):
                raise ValueError("a word comes before its own prefix")
            continue
        left, right = first[shared], second[shared]
        if right not in following[left]:
            following[left].add(right)
            waiting[right] += 1
    ready = sorted(letter for letter in letters if waiting[letter] == 0)
    order = []
    while ready:
        letter = ready.pop(0)
        order.append(letter)
        for other in sorted(following[letter]):
            waiting[other] -= 1
            if waiting[other] == 0:
                ready.append(other)
        ready.sort()
    if len(order) != len(letters):
        return ""
    return "".join(order)
