def decode_star(digits):
    if not isinstance(digits, str):
        raise ValueError("the input must be a string")
    for symbol in digits:
        if not (symbol.isdigit() or symbol == "*"):
            raise ValueError("only digits and * are allowed")
    size = len(digits)
    if size == 0:
        return 1
    older = 1
    if digits[0] == "0":
        previous = 0
    elif digits[0] == "*":
        previous = 9
    else:
        previous = 1
    for at in range(2, size + 1):
        current = 0
        last = digits[at - 1]
        if last == "*":
            current += 9 * previous
        elif last != "0":
            current += previous
        pair_first = digits[at - 2]
        pair_last = digits[at - 1]
        if pair_first == "*":
            if pair_last == "*":
                current += 15 * older
            elif "0" <= pair_last <= "6":
                current += 2 * older
            else:
                current += older
        elif pair_last == "*":
            if pair_first == "1":
                current += 9 * older
            elif pair_first == "2":
                current += 6 * older
        elif pair_first != "0" and 10 <= int(pair_first + pair_last) <= 26:
            current += older
        older, previous = previous, current
    return previous
