def longest_rising(matrix):
    if not matrix:
        return 0
    width = len(matrix[0])
    for row in matrix:
        if len(row) != width:
            raise ValueError("the matrix must be rectangular")
    depth = [[0] * width for _ in range(len(matrix))]
    steps = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def walk(row, col):
        if depth[row][col]:
            return depth[row][col]
        best = 1
        for drow, dcol in steps:
            rr = row + drow
            cc = col + dcol
            if 0 <= rr < len(matrix) and 0 <= cc < width and matrix[rr][cc] > matrix[row][col]:
                candidate = 1 + walk(rr, cc)
                if candidate > best:
                    best = candidate
        depth[row][col] = best
        return best

    for row in range(len(matrix)):
        for col in range(width):
            walk(row, col)
    return max(max(line) for line in depth)
```

