def palindrome_parts(text):
    if not isinstance(text, str):
        raise ValueError("the text must be a string")
    if not text:
        return []
    found = []
    current = []

    def is_palindrome(piece):
        return piece == piece[::-1]

    def walk(at):
        if at == len(text):
            found.append(list(current))
            return
        for stop in range(at + 1, len(text) + 1):
            piece = text[at:stop]
            if not is_palindrome(piece):
                continue
            current.append(piece)
            walk(stop)
            current.pop()

    walk(0)
    found.sort()
    return found
