def kth_smallest(matrix, place):
    if not matrix:
        return 0
    width = len(matrix[0])
    for row in matrix:
        if len(row) != width:
            raise ValueError("the matrix must be rectangular")
    total = len(matrix) * width
    if place < 1 or place > total:
        raise ValueError("the place is out of range")
    low = matrix[0][0]
    high = matrix[-1][-1]
    while low < high:
        middle = (low + high) // 2
        counted = 0
        row = len(matrix) - 1
        col = 0
        while row >= 0 and col < width:
            if matrix[row][col] <= middle:
                counted += row + 1
                col += 1
            else:
                row -= 1
        if counted >= place:
            high = middle
        else:
            low = middle + 1
    return low
