"""Whole percentages that add up to 100."""


def percentages(counts):
    """Whole percentages per bucket."""
    if not isinstance(counts, (list, tuple)):
        raise ValueError("a list of counts is needed")
    total = 0
    for count in counts:
        if not isinstance(count, int) or isinstance(count, bool) or count < 0:
            raise ValueError("counts must be non-negative integers")
        total += count
    if not counts:
        return []
    if total == 0:
        raise ValueError("at least one count must be positive")
    floors = []
    remainders = []
    for index, count in enumerate(counts):
        exact = count * 100
        whole = round(count * 100 / total)
        floors.append(whole)
        remainders.append((-(exact % total), index))
    left = 100 - sum(floors)
    remainders.sort()
    for _score, index in remainders[:left]:
        floors[index] += 1
    return floors

