def clone_rows(rows):
    """A deep copy of every row and its cells."""
    if not isinstance(rows, list):
        raise ValueError("a list of rows is needed")
    cloned = []
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("a row must be a dictionary")
        cells = row.get("cells", [])
        if not isinstance(cells, list):
            raise ValueError("cells must be a list")
        fresh = dict(row)
        fresh["cells"] = list(cells)
        cloned.append(fresh)
    return cloned

