def marked_price(base, rate):
    """Base price (an int or float) with the rate applied, as cents."""
    if isinstance(base, bool) or not isinstance(base, (int, float, Decimal)):
        raise ValueError("the base price must be a number")
    if isinstance(rate, bool) or not isinstance(rate, (int, float, Decimal)):
        raise ValueError("the rate must be a number")
