int treeDiameter(int nodes, std::vector<std::pair<int,int>> edges) {
    if (nodes <= 0) return 0;
    std::vector<std::vector<int>> graph(nodes);
    for (const auto &edge : edges) {
        if (edge.first < 0 || edge.first >= nodes || edge.second < 0 || edge.second >= nodes) {
            throw std::invalid_argument("endpoint out of range");
        }
        graph[edge.first].push_back(edge.second);
        graph[edge.second].push_back(edge.first);
    }
    const auto farthest = [&](int start) {
        std::vector<int> distance(nodes, -1);
        distance[start] = 0;
        std::vector<int> queue{start};
        int best = start;
        for (std::size_t head = 0; head < queue.size(); ++head) {
            const int node = queue[head];
            if (distance[node] > distance[best]) best = node;
            for (int other : graph[node]) {
                if (distance[other] >= 0) continue;
                distance[other] = distance[node] + 1;
                queue.push_back(other);
            }
        }
        return std::make_pair(best, distance[best]);
    };
    const auto first = farthest(0);
    return farthest(first.first).second;
}
