std::vector<int> findAll(std::string text, std::string pattern) {
    std::vector<int> hits;
    if (pattern.empty()) {
        for (int at = 0; at <= static_cast<int>(text.size()); ++at) hits.push_back(at);
        return hits;
    }
    if (text.size() < pattern.size()) throw std::invalid_argument("the pattern is longer than the text");
    std::vector<int> table(pattern.size(), 0);
    int length = 0;
    for (std::size_t at = 1; at < pattern.size(); ++at) {
        while (length > 0 && pattern[at] != pattern[length]) length = table[length - 1];
        if (pattern[at] == pattern[length]) length += 1;
        table[at] = length;
    }
    int matched = 0;
    for (std::size_t at = 0; at < text.size(); ++at) {
        while (matched > 0 && text[at] != pattern[matched]) matched = table[matched - 1];
        if (text[at] == pattern[matched]) matched += 1;
        if (matched == static_cast<int>(pattern.size())) {
            hits.push_back(static_cast<int>(at) - matched + 1);
            matched = table[matched - 1];
        }
    }
    return hits;
}
