long long countXor(std::vector<int> values, int target) {
    const int span = 1024;
    if (target < 0 || target >= span) throw std::invalid_argument("target out of range");
    for (int value : values) {
        if (value < 0 || value >= span) throw std::invalid_argument("value out of range");
    }
    std::vector<long long> counts(span, 0);
    counts[0] = 1;
    for (int value : values) {
        std::vector<long long> next(span, 0);
        for (int state = 0; state < span; ++state) {
            if (counts[state] == 0) continue;
            next[state] += counts[state];
            next[state ^ value] += counts[state];
        }
        counts.swap(next);
    }
    return counts[target];
}
