int distinctWindows(std::string text, int width) {
    if (width < 1) return 0;
    for (char letter : text) {
        if (letter < 'a' || letter > 'z') throw std::invalid_argument("lower case letters only");
    }
    const int size = static_cast<int>(text.size());
    if (width > size) return 0;
    const unsigned long long base = 131ULL;
    unsigned long long high = 1;
    for (int at = 0; at < width; ++at) high *= base;
    unsigned long long hash = 0;
    for (int at = 0; at < width; ++at) hash = hash * base + static_cast<unsigned long long>(text[at] - 'a' + 1);
    std::unordered_set<unsigned long long> seen;
    seen.insert(hash);
    for (int at = width; at < size; ++at) {
        hash = hash * base + static_cast<unsigned long long>(text[at] - 'a' + 1);
        hash -= static_cast<unsigned long long>(text[at - width] - 'a' + 1) * high;
        seen.insert(hash);
    }
    return static_cast<int>(seen.size());
}
