std::vector<int> lcaAll(int nodes, std::vector<std::pair<int,int>> edges, std::vector<std::pair<int,int>> queries) {
    if (nodes <= 0) {
        if (edges.empty() && queries.empty()) return {};
        throw std::invalid_argument("no nodes to link");
    }
    std::vector<std::vector<int>> graph(nodes);
    for (const auto &edge : edges) {
        if (edge.first < 0 || edge.first >= nodes || edge.second < 0 || edge.second >= nodes) {
            throw std::invalid_argument("endpoint out of range");
        }
        graph[edge.first].push_back(edge.second);
        graph[edge.second].push_back(edge.first);
    }
    int levels = 1;
    while ((1 << levels) <= nodes) levels += 1;
    std::vector<std::vector<int>> up(levels, std::vector<int>(nodes, 0));
    std::vector<int> depth(nodes, 0);
    std::vector<char> seen(nodes, 0);
    std::vector<int> queue{0};
    seen[0] = 1;
    up[0][0] = 0;
    for (std::size_t head = 0; head < queue.size(); ++head) {
        const int node = queue[head];
        for (int other : graph[node]) {
            if (seen[other]) continue;
            seen[other] = 1;
            depth[other] = depth[node] + 1;
            up[0][other] = node;
            queue.push_back(other);
        }
    }
    for (int level = 1; level < levels; ++level) {
        for (int node = 0; node < nodes; ++node) {
            up[level][node] = up[level - 1][up[level - 1][node]];
        }
    }
    std::vector<int> answers;
    answers.reserve(queries.size());
    for (const auto &query : queries) {
        int left = query.first;
        int right = query.second;
        if (left < 0 || left >= nodes || right < 0 || right >= nodes) {
            throw std::invalid_argument("queried node out of range");
        }
        if (depth[left] < depth[right]) std::swap(left, right);
        int gap = depth[left] - depth[right];
        for (int level = 0; level < levels; ++level) {
            if ((gap >> level) & 1) left = up[level][left];
        }
        if (left == right) {
            answers.push_back(left);
            continue;
        }
        for (int level = levels - 1; level >= 0; --level) {
            if (up[level][left] != up[level][right]) {
                left = up[level][left];
                right = up[level][right];
            }
        }
        answers.push_back(up[0][left]);
    }
    return answers;
}
