int minStairCost(std::vector<int> costs) {
    for (int cost : costs) {
        if (cost < 0) throw std::invalid_argument("costs must not be negative");
    }
    const int size = static_cast<int>(costs.size());
    if (size <= 1) return 0;
    int older = 0;
    int previous = 0;
    for (int at = 2; at <= size; ++at) {
        const int fromOne = previous + costs[at - 1];
        const int fromTwo = older + costs[at - 2];
        const int current = std::min(fromOne, fromTwo);
        older = previous;
        previous = current;
    }
    return previous;
}
