from collections import deque


def snakes_and_ladders(board):
    if not board or any(len(row) != len(board) for row in board):
        raise ValueError("the board must be square")
    size = len(board)
    goal = size * size
    jumps = {}
    for row in range(size):
        for col in range(size):
            value = board[~row][col]
            square = row * size + col + 1
            if value != -1:
                if not 2 <= value <= goal - 1:
                    raise ValueError("an end is out of range")
                jumps[square] = value
    seen = {1: 0}
    queue = deque([1])
    while queue:
        square = queue.popleft()
        if square == goal:
            return seen[square]
        for die in range(1, 7):
            landing = square + die
            if landing > goal:
                continue
            landing = jumps.get(landing, landing)
            if landing not in seen:
                seen[landing] = seen[square] + 1
                queue.append(landing)
    return -1
