def smaller_counts(values):
    if not isinstance(values, list):
        raise ValueError("a list is needed")
    for value in values:
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("all values must be integers")
    if not values:
        return []
    ordered = sorted(set(values))
    rank = {value: index + 1 for index, value in enumerate(ordered)}
    tree = [0] * (len(ordered) + 1)

    def add(at):
        while at < len(tree):
            tree[at] += 1
            at += at & (-at)

    def prefix(at):
        total = 0
        while at > 0:
            total += tree[at]
            at -= at & (-at)
        return total

    counts = [0] * len(values)
    seen = 0
    for index in range(len(values) - 1, -1, -1):
        spot = rank[values[index]]
        counts[index] = prefix(spot - 1)
        add(spot)
        seen += 1
    return counts
