def max_collinear(points):
    if not isinstance(points, list):
        raise ValueError("a list of points is needed")
    cleaned = []
    for point in points:
        if not isinstance(point, (list, tuple)) or len(point) != 2:
            raise ValueError("a point is a pair")
        for value in point:
            if isinstance(value, bool) or not isinstance(value, int):
                raise ValueError("coordinates must be integers")
        cleaned.append(tuple(point))
    if len(cleaned) < 3:
        return len(cleaned)
    best = 2
    for first in range(len(cleaned)):
        for second in range(first + 1, len(cleaned)):
            ax, ay = cleaned[first]
            bx, by = cleaned[second]
            count = 2
            for third in range(len(cleaned)):
                if third in (first, second):
                    continue
                cx, cy = cleaned[third]
                if (bx - ax) * (cy - ay) == (by - ay) * (cx - ax):
                    count += 1
            if count > best:
                best = count
    return best
