def candy_count(ratings):
    if not isinstance(ratings, list):
        raise ValueError("a list of ratings is needed")
    for rating in ratings:
        if isinstance(rating, bool) or not isinstance(rating, int) or rating < 0:
            raise ValueError("ratings must be non-negative integers")
    count = len(ratings)
    if count == 0:
        return 0
    sweets = [1] * count
    for index in range(1, count):
        if ratings[index] > ratings[index - 1]:
            sweets[index] = sweets[index - 1] + 1
    for index in range(count - 2, -1, -1):
        if ratings[index] > ratings[index + 1]:
            sweets[index] = max(sweets[index], sweets[index + 1] + 1)
    return sum(sweets)
