def can_cross(stones):
    if not isinstance(stones, list):
        raise ValueError("a list of stones is needed")
    for index, stone in enumerate(stones):
        if isinstance(stone, bool) or not isinstance(stone, int) or stone < 0:
            raise ValueError("stones must be non-negative integers")
        if index and stone <= stones[index - 1]:
            raise ValueError("stones must be sorted and distinct")
    if len(stones) <= 1:
        return True
    positions = set(stones)
    reachable = {}
    if 1 in positions:
        reachable[1] = {1}
    for stone in stones:
        if stone not in reachable:
            continue
        for step in sorted(reachable[stone]):
            for jump in (step - 1, step, step + 1):
                if jump <= 0 or stone + jump not in positions:
                    continue
                reachable.setdefault(stone + jump, set()).add(jump)
    return stones[-1] in reachable
