def best_rod(price, limits):
    if not isinstance(price, list) or not isinstance(limits, list):
        raise ValueError("two lists are needed")
    if len(price) != len(limits):
        raise ValueError("price and limits must line up")
    for value in list(price) + list(limits):
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError("only non-negative integers are allowed")
    total = len(price)
    if total == 0:
        return 0
    best = [None] * (total + 1)
    best[0] = 0
    for length in range(1, total + 1):
        allowance = limits[length - 1]
        if allowance == 0:
            continue
        carried = best[:]
        for _piece in range(allowance):
            previous = carried[:]
            for size in range(length, total + 1):
                base = previous[size - length]
                if base is None:
                    continue
                candidate = base + price[length - 1]
                if carried[size] is None or candidate > carried[size]:
                    carried[size] = candidate
            best = carried
    return -1 if best[total] is None else best[total]
