import posixpath


def join_path(root, children):
    """Join the children under the root, keeping everything inside it."""
    if not isinstance(root, str) or not root:
        raise ValueError("a non-empty root is needed")
    if isinstance(children, str):
        children = (children,)
    parts = []
    for child in children:
        if not isinstance(child, str):
            raise ValueError("children must be strings")
        clean = child
        if clean:
            parts.append(clean)
    if not parts:
        return root
    return posixpath.join(root, *parts)

