    const equals = line.indexOf("=");
    if (equals < 0) throw new SyntaxError("a line needs a = sign");
    if (current === null) throw new SyntaxError("a key outside a section");
    const key = line.slice(0, equals).trim();
    const value = line.slice(equals + 1).trim();
    if (key === "") throw new SyntaxError("a line needs a key");
    out[current][key] = value;
  }
  return out;
