function convertAmount(
  rates: [string, string, number][],
  from: string,
  to: string,
  amount: number,
): number {
  for (const [, , factor] of rates) {
    if (!(factor > 0)) throw new RangeError("rates must be positive");
  }
  if (from === to) return amount;
  let frontier = new Map<string, number>([[from, amount]]);
  const seen = new Set<string>([from]);
  while (frontier.size > 0) {
    const next = new Map<string, number>();
    for (const [unit, value] of frontier) {
      for (const [source, target, factor] of rates) {
        const pairs: [string, string, number][] = [
          [source, target, factor],
          [target, source, 1 / factor],
        ];
        for (const [start, stop, ratio] of pairs) {
          if (start !== unit) continue;
          const converted = value * ratio;
          if (stop === to) {
            next.set(stop, Math.max(next.get(stop) ?? -Infinity, converted));
            continue;
          }
          if (seen.has(stop)) continue;
          next.set(stop, Math.max(next.get(stop) ?? -Infinity, converted));
        }
      }
    }
    if (next.has(to)) {
      return next.get(to) as number;
    }
    for (const unit of next.keys()) seen.add(unit);
    frontier = next;
  }
  return -1;
