    if (row.length !== right[0].length) throw new RangeError("ragged matrix");
  }
  const out: number[][] = [];
  for (let row = 0; row < left.length; row += 1) {
    const line: number[] = [];
    for (let column = 0; column < (right[0]?.length ?? 0); column += 1) {
      let total = 0;
      for (let inner = 0; inner < width; inner += 1) total += left[row][inner] * right[inner][column];
      line.push(total);
    }
    out.push(line);
  }
  return out;
