function identity(size: number): number[][] {
  const out: number[][] = [];
  for (let row = 0; row < size; row += 1) {
    out.push(Array.from({ length: size }, (_cell, column) => (row === column ? 1 : 0)));
  }
  return out;
}

function powerMatrix(matrix: number[][], exponent: number): number[][] {
  if (!Number.isInteger(exponent) || exponent < 0) throw new RangeError("exponent must be >= 0");
  if (matrix.some((row) => row.length !== matrix.length)) throw new RangeError("a square matrix is needed");
  let result = identity(matrix.length);
  let base = matrix;
  let power = exponent;
  while (power > 0) {
    if (power % 2 === 1) result = multiplyMatrix(result, base);
    base = multiplyMatrix(base, base);
    power = Math.floor(power / 2);
  }
  return result;
}
