long long maxFlow(int nodes, std::vector<std::vector<int>> edges, int source, int sink) {
    if (nodes <= 0) throw std::invalid_argument("no nodes");
    if (source < 0 || source >= nodes || sink < 0 || sink >= nodes) throw std::invalid_argument("bad endpoint");
    int count = 0;
    for (const auto &edge : edges) {
        if (edge[0] < 0 || edge[0] >= nodes || edge[1] < 0 || edge[1] >= nodes) throw std::invalid_argument("bad edge");
        if (edge[2] < 0) throw std::invalid_argument("negative capacity");
        count += 2;
    }
    std::vector<int> head(nodes, -1), next(count, -1), to(count, 0);
    std::vector<long long> cap(count, 0);
    int used = 0;
    for (const auto &edge : edges) {
        to[used] = edge[1]; cap[used] = edge[2]; next[used] = head[edge[0]]; head[edge[0]] = used++;
        to[used] = edge[0]; cap[used] = 0; next[used] = head[edge[1]]; head[edge[1]] = used++;
    }
    long long total = 0;
    while (true) {
        std::vector<int> parentEdge(nodes, -1), queue{source};
        parentEdge[source] = -2;
        for (std::size_t at = 0; at < queue.size() && parentEdge[sink] == -1; ++at) {
            const int node = queue[at];
            for (int edge = head[node]; edge != -1; edge = next[edge]) {
                if (cap[edge] <= 0 || parentEdge[to[edge]] != -1) continue;
                parentEdge[to[edge]] = edge;
                queue.push_back(to[edge]);
            }
        }
        if (parentEdge[sink] == -1) break;
        long long pushed = -1;
        for (int node = sink; node != source;) {
            const int edge = parentEdge[node];
            pushed = (pushed < 0 || cap[edge] < pushed) ? cap[edge] : pushed;
            node = to[edge ^ 1];
        }
        for (int node = sink; node != source;) {
            const int edge = parentEdge[node];
            cap[edge] -= pushed;
            cap[edge ^ 1] += pushed;
            node = to[edge ^ 1];
        }
        total += pushed;
    }
    return total;
}
