long long minAssignment(std::vector<std::vector<int>> cost) {
    const int size = static_cast<int>(cost.size());
    for (const auto &row : cost) {
        if (static_cast<int>(row.size()) != size) throw std::invalid_argument("a square matrix is needed");
        for (int value : row) {
            if (value < 0) throw std::invalid_argument("costs must not be negative");
        }
    }
    if (size == 0) return 0;
    const int full = 1 << size;
    std::vector<long long> best(full, -1);
    best[0] = 0;
    for (int mask = 0; mask < full; ++mask) {
        if (best[mask] < 0) continue;
        int worker = __builtin_popcount(mask);
        if (worker == size) continue;
        for (int task = 0; task < size; ++task) {
            if (mask >> task & 1) continue;
            const int next = mask | (1 << task);
            const long long candidate = best[mask] + cost[worker][task];
            if (best[next] < 0 || candidate < best[next]) best[next] = candidate;
        }
    }
    return best[full - 1];
}
