std::vector<int> zeroOneCost(int nodes, std::vector<std::vector<int>> edges, int source) {
    if (nodes <= 0) throw std::invalid_argument("no nodes");
    if (source < 0 || source >= nodes) throw std::invalid_argument("bad source");
    std::vector<std::vector<std::pair<int,int>>> graph(nodes);
    for (const auto &edge : edges) {
        if (edge.size() != 3) throw std::invalid_argument("an edge needs three numbers");
        if (edge[0] < 0 || edge[0] >= nodes || edge[1] < 0 || edge[1] >= nodes) throw std::invalid_argument("bad endpoint");
        if (edge[2] != 0 && edge[2] != 1) throw std::invalid_argument("costs are 0 or 1");
        graph[edge[0]].push_back({edge[1], edge[2]});
        graph[edge[1]].push_back({edge[0], edge[2]});
    }
    const int far = 1 << 30;
    std::vector<int> best(nodes, far);
    std::deque<int> queue;
    best[source] = 0;
    queue.push_back(source);
    while (!queue.empty()) {
        const int node = queue.front();
        queue.pop_front();
        for (const auto &step : graph[node]) {
            const int candidate = best[node] + step.second;
            if (candidate >= best[step.first]) continue;
            best[step.first] = candidate;
            if (step.second == 0) queue.push_front(step.first);
            else queue.push_back(step.first);
        }
    }
    for (int &value : best) {
        if (value == far) value = -1;
    }
    return best;
}
