    for (std::size_t at = 0; at < order.size(); ++at) order[at] = static_cast<int>(at);
    std::sort(order.begin(), order.end(), [&](int left, int right) {
        return edges[left][2] < edges[right][2];
    });
    std::vector<int> parent(nodes);
    for (int node = 0; node < nodes; ++node) parent[node] = node;
