long long countExactly(std::vector<int> values, int wanted) {
    for (int value : values) {
        if (value < 0) throw std::invalid_argument("values must not be negative");
    }
    if (wanted < 1 || values.empty()) return 0;
    const auto atMost = [&](int limit) {
        std::vector<int> seen(*std::max_element(values.begin(), values.end()) + 1, 0);
        long long total = 0;
        int distinct = 0;
        std::size_t left = 0;
        for (std::size_t right = 0; right < values.size(); ++right) {
            if (seen[values[right]] == 0) ++distinct;
            seen[values[right]] += 1;
            while (distinct > limit) {
                seen[values[left]] -= 1;
                if (seen[values[left]] == 0) --distinct;
                ++left;
            }
            total += static_cast<long long>(right) - static_cast<long long>(left) + 1;
        }
        return total;
    };
    return atMost(wanted) - atMost(wanted - 1);
}
