std::vector<int> slidingMax(std::vector<int> values, int width) {
    for (int value : values) {
        if (value < 0) throw std::invalid_argument("values must not be negative");
    }
    if (width < 1 || width > static_cast<int>(values.size())) return {};
    std::deque<int> queue;
    std::vector<int> out;
    out.reserve(values.size() - width + 1);
    for (int at = 0; at < static_cast<int>(values.size()); ++at) {
        while (!queue.empty() && values[queue.back()] <= values[at]) queue.pop_back();
        queue.push_back(at);
        if (queue.front() <= at - width) queue.pop_front();
        if (at + 1 >= width) out.push_back(values[queue.front()]);
    }
    return out;
}
