std::string smallestWindow(std::string text, std::string pattern) {
    for (char letter : text) {
        if (letter < 'a' || letter > 'z') throw std::invalid_argument("lower case letters only");
    }
    for (char letter : pattern) {
        if (letter < 'a' || letter > 'z') throw std::invalid_argument("lower case letters only");
    }
    if (pattern.empty()) return "";
    std::vector<int> need(26, 0), have(26, 0);
    for (char letter : pattern) need[letter - 'a'] += 1;
    int missing = static_cast<int>(pattern.size());
    std::size_t left = 0;
    std::size_t bestStart = 0;
    std::size_t bestLength = text.size() + 1;
    for (std::size_t right = 0; right < text.size(); ++right) {
        const int index = text[right] - 'a';
        if (have[index] < need[index]) --missing;
        have[index] += 1;
        while (missing == 0 && left <= right) {
            if (right - left + 1 < bestLength) {
                bestLength = right - left + 1;
                bestStart = left;
            }
            const int gone = text[left] - 'a';
            have[gone] -= 1;
            if (have[gone] < need[gone]) ++missing;
            ++left;
        }
    }
    if (bestLength > text.size()) return "";
    return text.substr(bestStart, bestLength);
}
