def evaluate(text):
    if not isinstance(text, str):
        raise ValueError("a string is needed")
    tokens = []
    at = 0
    while at < len(text):
        char = text[at]
        if char == " ":
            at += 1
            continue
        if char.isdigit():
            start = at
            while at < len(text) and text[at].isdigit():
                at += 1
            tokens.append(int(text[start:at]))
            continue
        if char in "+-*/()":
            tokens.append(char)
            at += 1
            continue
        raise ValueError("bad character: " + char)
    if not tokens:
        raise ValueError("the expression is empty")
    position = 0

    def expression():
        nonlocal position
        value = term()
        while position < len(tokens) and tokens[position] in ("+", "-"):
            operator = tokens[position]
            position += 1
            other = term()
            value = value + other if operator == "+" else value - other
        return value

    def term():
        nonlocal position
        value = factor()
        while position < len(tokens) and tokens[position] in ("*", "/"):
            operator = tokens[position]
            position += 1
            other = factor()
            if operator == "*":
                value *= other
            else:
                if other == 0:
                    raise ValueError("division by zero")
                quotient = abs(value) // abs(other)
                value = quotient if (value >= 0) == (other >= 0) else -quotient
        return value

    def factor():
        nonlocal position
        if position >= len(tokens):
            raise ValueError("unexpected end")
        token = tokens[position]
        if token == "(":
            position += 1
            value = expression()
            if position >= len(tokens) or tokens[position] != ")":
                raise ValueError("missing bracket")
            position += 1
            return value
        if isinstance(token, int):
            position += 1
            return token
        raise ValueError("unexpected token")

    result = expression()
    if position != len(tokens):
        raise ValueError("trailing input")
    return result
