def longest_increasing(values):
    if not isinstance(values, list):
        raise ValueError("a list is needed")
    for value in values:
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("values must be integers")
    if not values:
        return []
    best = [1] * len(values)
    parent = [-1] * len(values)
    for index in range(len(values)):
        for back in range(index):
            if values[back] < values[index] and best[back] + 1 > best[index]:
                best[index] = best[back] + 1
                parent[index] = back
    end = 0
    for index in range(len(values)):
        if best[index] > best[end]:
            end = index
    chain = []
    while end >= 0:
        chain.append(values[end])
        end = parent[end]
    chain.reverse()
    return chain
