def search_words(words, pattern):
    if not isinstance(words, list):
        raise ValueError("a list of words is needed")
    for letter in pattern:
        if letter != "." and not ("a" <= letter <= "z"):
            raise ValueError("bad pattern letter: " + letter)
    root = {}
    for word in words:
        if not isinstance(word, str):
            raise ValueError("words must be strings")
        node = root
        for letter in word:
            node = node.setdefault(letter, {})
        node[""] = word
    found = []

    def walk(node, at):
        if at == len(pattern):
            if "" in node:
                found.append(node[""])
            return
        letter = pattern[at]
        if letter == ".":
            for key in node:
                if key != "":
                    walk(node[key], at + 1)
            return
        if letter in node:
            walk(node[letter], at + 1)

    walk(root, 0)
    return found
