from collections import deque


def is_bipartite(nodes, edges):
    if isinstance(nodes, bool) or not isinstance(nodes, int) or nodes < 0:
        raise ValueError("nodes must not be negative")
    graph = [[] for _ in range(nodes)]
    for left, right in edges:
        if not (0 <= left < nodes) or not (0 <= right < nodes):
            raise ValueError("endpoint out of range")
        if left == right:
            return False
        graph[left].append(right)
        graph[right].append(left)
    colour = [-1] * nodes
    for start in range(nodes):
        if colour[start] >= 0:
            continue
        colour[start] = 0
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for other in graph[node]:
                if colour[other] < 0:
                    colour[other] = 1 - colour[node]
                    queue.append(other)
                elif colour[other] == colour[node]:
                    return False
    return True
