import bisect


def skyline(buildings):
    cleaned = []
    for building in buildings:
        if not isinstance(building, (list, tuple)) or len(building) != 3:
            raise ValueError("a building is a triple")
        left, right, height = building
        if left >= right:
            raise ValueError("the left edge must be before the right edge")
        if height <= 0:
            raise ValueError("heights must be positive")
        cleaned.append((left, right, height))
    events = []
    for left, right, height in cleaned:
        events.append((left, -height))
        events.append((right, height))
    events.sort()
    active = []
    out = []
    at = 0
    while at < len(events):
        spot = events[at][0]
        while at < len(events) and events[at][0] == spot:
            height = events[at][1]
            if height < 0:
                bisect.insort(active, -height)
            else:
                active.remove(height)
            at += 1
        current = active[-1] if active else 0
        if not out or out[-1][1] != current:
            out.append((spot, current))
    return out
