def count_paths(grid):
    if not isinstance(grid, list):
        raise ValueError("a grid is needed")
    rows = len(grid)
    if rows == 0:
        return 0
    cols = len(grid[0])
    for row in grid:
        if len(row) != cols:
            raise ValueError("the grid must be rectangular")
        for value in row:
            if value not in (0, 1) or isinstance(value, bool):
                raise ValueError("cells must be 0 or 1")
    if grid[0][0] == 1 or grid[rows - 1][cols - 1] == 1:
        return 0
    best = [0] * cols
    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                best[col] = 0
                continue
            if row == 0 and col == 0:
                best[col] = 1
            elif row == 0:
                best[col] = best[col - 1]
            elif col == 0:
                best[col] = best[col]
            else:
                best[col] = best[col] + best[col - 1]
    return best[cols - 1]
