def min_rotated(values):
    if not isinstance(values, list):
        raise ValueError("a list is needed")
    if not values:
        raise ValueError("the list is empty")
    for value in values:
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("values must be integers")
    size = len(values)
    drops = [index for index in range(size) if values[index] < values[index - 1]]
    if len(drops) > 1:
        raise ValueError("the values are not a rotation of a sorted list")
    low = 0
    high = size - 1
    while low < high:
        middle = (low + high) // 2
        if values[middle] > values[high]:
            low = middle + 1
        elif values[middle] < values[high]:
            high = middle
        else:
            high -= 1
    return low, values[low]
