type Dict = Record<string, unknown>;

function isPlain(value: unknown): value is Dict {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function deepMerge(base: Dict, patch: Dict): Dict {
  if (!isPlain(base) || !isPlain(patch)) throw new TypeError("two objects are required");
  const out: Dict = {};
  for (const key of Object.keys(base)) out[key] = clone(base[key]);
  for (const key of Object.keys(patch)) {
    const next = patch[key];
    if (next === undefined) continue;
    if (Array.isArray(next)) {
      const previous = Array.isArray(out[key]) ? (out[key] as unknown[]) : [];
      out[key] = [...previous.map(clone), ...next.map(clone)];
    } else if (isPlain(next) && isPlain(out[key])) {
