function parseVersion(text: string): [number, number, number] {
  const parts = text.split(".");
  if (parts.length !== 3) throw new RangeError("a version needs three numbers");
  const numbers = parts.map((part) => {
    if (!/^\d+$/.test(part)) throw new RangeError("bad version part: " + part);
    return Number(part);
  });
  return [numbers[0], numbers[1], numbers[2]];
}

function compare(left: [number, number, number], right: [number, number, number]): number {
  for (let at = 0; at < 3; at += 1) {
    if (left[at] !== right[at]) return left[at] < right[at] ? -1 : 1;
  }
  return 0;
}

function satisfiesRange(version: string, range: string): boolean {
  const current = parseVersion(version);
  const comparators = range.trim() === "" ? [] : range.trim().split(/\s+/);
  for (const comparator of comparators) {
    const match = /^(\^|~|>=|>|<=|<|=)?(\d+\.\d+\.\d+)$/.exec(comparator);
    if (!match) throw new RangeError("bad comparator: " + comparator);
    const operator = match[1] ?? "=";
    const target = parseVersion(match[2]);
    if (operator === "^") {
      const upper: [number, number, number] = target[0] > 0 ? [target[0] + 1, 0, 0]
        : target[1] > 0 ? [0, target[1] + 1, 0] : [0, 0, target[2] + 1];
      if (compare(current, target) < 0 || compare(current, upper) >= 0) return false;
      continue;
    }
    if (operator === "~") {
      const upper: [number, number, number] = [target[0], target[1] + 1, 0];
      if (compare(current, target) < 0 || compare(current, upper) >= 0) return false;
      continue;
    }
    const order = compare(current, target);
    if (operator === "=" && order !== 0) return false;
    if (operator === ">=" && order < 0) return false;
    if (operator === ">" && order <= 0) return false;
    if (operator === "<=" && order > 0) return false;
    if (operator === "<" && order >= 0) return false;
  }
  return true;
