function backoffSchedule(attempts: number, base: number, cap: number): number[] {
  if (!Number.isInteger(attempts) || attempts < 0) throw new RangeError("attempts must be a whole number");
  if (!Number.isFinite(base) || base <= 0) throw new RangeError("base must be positive");
  if (!Number.isFinite(cap) || cap < base) throw new RangeError("cap must not be below base");
  const delays: number[] = [];
  let delay = base;
  for (let at = 0; at < attempts; at += 1) {
    delays.push(Math.min(delay, cap));
    delay = Math.min(delay * 2, cap);
  }
  return delays;
