class TrieMap {
  private root: { next: Map<string, any>; count: number; end: boolean } = {
    next: new Map(),
    count: 0,
    end: false,
  };
  private stored = new Set<string>();

  insert(word: string): void {
    if (!/^[a-z]+$/.test(word)) throw new RangeError("lower case words only");
    let node = this.root;
    node.count += 1;
    for (const letter of word) {
      if (!node.next.has(letter)) {
        node.next.set(letter, { next: new Map(), count: 0, end: false });
      }
      node = node.next.get(letter);
      node.count += 1;
    }
    node.end = true;
    this.stored.add(word);
  }

  private walk(prefix: string) {
    let node = this.root;
    for (const letter of prefix) {
      if (!node.next.has(letter)) return null;
      node = node.next.get(letter);
    }
    return node;
  }

  has(word: string): boolean {
    const node = this.walk(word);
    return node !== null && node.end;
  }

  countPrefix(prefix: string): number {
    if (!/^[a-z]*$/.test(prefix)) throw new RangeError("lower case prefixes only");
    const node = this.walk(prefix);
    return node === null ? 0 : node.count;
  }

  words(): string[] {
    return [...this.stored].sort();
  }

  get size(): number {
    return this.stored.size;
  }
}
