    if (other.currency !== this.currency) throw new RangeError("currencies differ");
    return new Money(this.amount + other.amount, this.currency);
  }

  scale(factor: number): Money {
    if (!Number.isFinite(factor) || factor < 0) throw new RangeError("the factor must not be negative");
    return new Money(Math.floor(this.amount * factor + 0.5), this.currency);
