function parseColor(text) {
  if (typeof text !== "string") throw new RangeError("a colour string is required");
  const value = text.trim().toLowerCase();
  const short = /^#([0-9a-f])([0-9a-f])([0-9a-f])$/.exec(value);
  if (short) {
    return {
      r: parseInt(short[1] + short[1], 16),
      g: parseInt(short[2] + short[2], 16),
      b: parseInt(short[3] + short[3], 16),
    };
  }
  const full = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/.exec(value);
  if (full) {
    return { r: parseInt(full[1], 16), g: parseInt(full[2], 16), b: parseInt(full[3], 16) };
  }
  const parts = /^rgba?\((\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\)$/.exec(value);
  if (parts) {
    const channels = [Number(parts[1]), Number(parts[2]), Number(parts[3])];
    if (channels.some((channel) => channel > 255)) throw new RangeError("channel out of range");
    return { r: channels[0], g: channels[1], b: channels[2] };
  }
  throw new RangeError("unknown colour: " + text);
}

function mixColor(first, second, ratio) {
  if (!(ratio >= 0 && ratio <= 1)) throw new RangeError("the ratio must be between 0 and 1");
  const blend = (left, right) => Math.floor(left * (1 - ratio) + right * ratio + 0.5);
  return { r: blend(first.r, second.r), g: blend(first.g, second.g), b: blend(first.b, second.b) };
}

function toHex(colour) {
  const pad = (channel) => channel.toString(16).padStart(2, "0");
  return "#" + pad(colour.r) + pad(colour.g) + pad(colour.b);
}
