std::vector<int> placeItems(int shelves, int capacity, std::vector<int> items) {
    if (shelves < 0) throw std::invalid_argument("shelf count must not be negative");
    if (capacity <= 0) throw std::invalid_argument("capacity must be positive");
    std::vector<int> used(shelves, 0);
    int rejected = 0;
    for (int item : items) {
        if (item <= 0) throw std::invalid_argument("items must be positive");
        if (item > capacity) {
            ++rejected;
            continue;
        }
        int pick = -1;
        int bestLeft = 0;
        for (int index = 0; index < shelves; ++index) {
            const int left = capacity - used[index];
            if (item > left) continue;
            if (pick < 0 || left - item < bestLeft) {
                pick = index;
                bestLeft = left - item;
            }
        }
        if (pick < 0) {
            ++rejected;
            continue;
        }
        used[pick] += item;
    }
    used.push_back(rejected);
    return used;
}
