std::vector<int> mergeMaintenance(std::vector<std::pair<int,int>> windows, int minGap) {
    if (minGap < 0) throw std::invalid_argument("the gap must not be negative");
    for (auto &window : windows) {
        if (window.first > window.second) std::swap(window.first, window.second);
    }
    std::sort(windows.begin(), windows.end());
    std::vector<std::pair<int,int>> slots;
    for (const auto &window : windows) {
        if (!slots.empty() && window.first - slots.back().second <= minGap) {
            if (window.second > slots.back().second) slots.back().second = window.second;
            continue;
        }
        slots.push_back(window);
    }
    int covered = 0;
    for (const auto &slot : slots) covered += slot.second - slot.first;
    return {static_cast<int>(slots.size()), covered};
}
