std::vector<int> sampleIndexes(std::vector<int> values, int stride, int jump) {
    if (stride < 1) throw std::invalid_argument("the stride must be at least 1");
    if (jump < 0) throw std::invalid_argument("the jump must not be negative");
    if (values.empty()) return {};
    std::vector<int> kept{0};
    int last = 0;
    for (int index = 1; index < static_cast<int>(values.size()); ++index) {
        const int change = std::abs(values[index] - values[last]);
        const bool sudden = change > jump;
        const bool due = index - last >= stride;
        if (!sudden && !due) continue;
        kept.push_back(index);
        last = index;
    }
    return kept;
}
