std::vector<std::string> serveOrder(std::vector<std::vector<int>> tickets, int agingMinutes) {
    if (agingMinutes <= 0) throw std::invalid_argument("the aging window must be positive");
    for (const auto &ticket : tickets) {
        if (ticket.size() != 3) throw std::invalid_argument("a ticket needs id, priority and wait");
        if (ticket[2] < 0) throw std::invalid_argument("the wait must not be negative");
    }
    std::vector<std::vector<int>> pool = tickets;
    std::vector<std::string> order;
    while (!pool.empty()) {
        int best = 0;
        for (int at = 1; at < static_cast<int>(pool.size()); ++at) {
            const int boost = std::min(2, pool[at][2] / agingMinutes);
            const int score = pool[at][1] + boost;
            const int bestBoost = std::min(2, pool[best][2] / agingMinutes);
            const int bestScore = pool[best][1] + bestBoost;
            if (score > bestScore || (score == bestScore && pool[at][0] < pool[best][0])) best = at;
        }
        order.push_back(std::to_string(pool[best][0]));
        pool.erase(pool.begin() + best);
    }
    return order;
