def payroll(shifts, base_cents):
    if not isinstance(shifts, list):
        raise ValueError("a list of shifts is needed")
    if isinstance(base_cents, bool) or not isinstance(base_cents, int) or base_cents < 0:
        raise ValueError("the base rate must not be negative")
    per_day = {}
    for shift in shifts:
        day, start, end = shift
        if start < 0 or end < start:
            raise ValueError("a shift must end after it starts")
        blocks = (end - start + 14) // 15
        per_day[day] = per_day.get(day, 0) + blocks * 15
    total = 0
    for day in sorted(per_day):
        quarters = per_day[day] // 15
        plain = min(quarters, 32)
        middle = max(0, min(quarters, 48) - 32)
        extra = max(0, quarters - 48)
        halves = 2 * plain + 3 * middle + 4 * extra
        total += (2 * halves * base_cents + 8) // 16
    return total
