"""Order totals."""


def line_total(quantity, unit_cents):
    """One order line in cents."""
    if quantity < 0 or unit_cents < 0:
        raise ValueError("quantity and price must not be negative")
    return quantity * unit_cents


def subtotal(lines):
    """The whole order before any discount."""
    return sum(line_total(quantity, unit_cents) for quantity, unit_cents in lines)


def order_total(lines, discount_bp):
    """The order after the partner discount, in basis points."""
    if isinstance(discount_bp, bool) or not isinstance(discount_bp, int) or not 0 <= discount_bp <= 10000:
        raise ValueError("the discount must be between 0 and 10000 basis points")
    discount = sum((2 * line_total(quantity, unit_cents) * discount_bp + 10000) // 20000
                   for quantity, unit_cents in lines)
    return subtotal(lines) - discount

