```javascript
function freeSlots(calendars, dayStart, dayEnd, length, buffer) {
  if (dayEnd < dayStart) throw new RangeError("the day must end after it starts");
  if (!Number.isInteger(length) || length < 1) throw new RangeError("the length must be at least 1");
  if (!Number.isInteger(buffer) || buffer < 0) throw new RangeError("the buffer must not be negative");
  const busy = new Array(dayEnd - dayStart).fill(false);
  for (const calendar of calendars) {
    for (const [start, end] of calendar) {
      const low = Math.max(dayStart, Math.min(start, end) - buffer);
      const high = Math.min(dayEnd, Math.max(start, end) + buffer);
      for (let minute = low; minute < high; minute += 1) {
        if (minute >= dayStart) busy[minute - dayStart] = true;
      }
    }
  }
  const slots = [];
  let runStart = -1;
  for (let minute = 0; minute <= busy.length; minute += 1) {
    const taken = minute < busy.length ? busy[minute] : true;
    if (!taken) {
      if (runStart < 0) runStart = minute;
      continue;
    }
    if (runStart >= 0) {
      if (minute - runStart >= length) slots.push([dayStart + runStart, dayStart + minute]);
      runStart = -1;
    }
  }
  return slots;
}
```

