```javascript
function parseEnv(text) {
  if (typeof text !== "string") throw new TypeError("a string is required");
  const out = {};
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === "" || line.startsWith("#")) continue;
    const body = line.startsWith("export ") ? line.slice(7).trim() : line;
    const equals = body.indexOf("=");
    if (equals < 0) throw new RangeError("a line needs an equals sign: " + line);
    const key = body.slice(0, equals).trim();
    if (!/^[A-Z_][A-Z0-9_]*$/.test(key)) throw new RangeError("bad key: " + key);
    let value = body.slice(equals + 1).trim();
    if (value.length > 0 && (value[0] === '"' || value[0] === "'")) {
      const quote = value[0];
      if (value.length < 2 || value[value.length - 1] !== quote) {
        throw new RangeError("unterminated quote in: " + line);
      }
      value = value.slice(1, -1);
      if (quote === '"') value = value.split("\\n").join("\n");
    }
    out[key] = value;
  }
  return out;
}
```

