function parseSearch(query) {
  if (typeof query !== "string") throw new TypeError("a query string is required");
  const terms = [];
  let at = 0;
  while (at < query.length) {
    if (query[at] === " ") {
      at += 1;
      continue;
    }
    let negated = false;
    let required = false;
    if (query[at] === "-" || query[at] === "+") {
      negated = query[at] === "-";
      required = query[at] === "+";
      at += 1;
    }
    let text = "";
    if (query[at] === '"') {
      const close = query.indexOf('"', at + 1);
      if (close < 0) throw new RangeError("unbalanced quote");
      text = query.slice(at + 1, close);
      at = close + 1;
    } else {
      const start = at;
      while (at < query.length && query[at] !== " ") at += 1;
      text = query.slice(start, at);
    }
    if (text === "") continue;
    terms.push({ text, negated, required });
  }
  return terms;
}
