function applyCredits(invoices, creditCents) {
  if (!Number.isFinite(creditCents) || creditCents < 0) throw new RangeError("the credit must not be negative");
  for (const invoice of invoices) {
    if (!Number.isFinite(invoice.cents) || invoice.cents < 0) throw new RangeError("amounts must not be negative");
  }
  const order = [...invoices].sort((left, right) => {
    if (left.due !== right.due) return left.due < right.due ? -1 : 1;
    return left.id < right.id ? -1 : left.id > right.id ? 1 : 0;
  });
  let left = creditCents;
  const paid = [];
  const settled = [];
  for (const invoice of order) {
    if (left <= 0) break;
    const amount = Math.min(left, invoice.cents);
    if (amount <= 0) continue;
    left -= amount;
    paid.push([invoice.id, amount]);
    if (amount === invoice.cents) settled.push(invoice.id);
  }
  settled.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return { paid, remaining: left, settled };
}
```

