class ShiftBoard {
  cap: number;
  shifts: Map<string, Map<number, number>>;

  constructor(cap: number) {
    if (!Number.isInteger(cap) || cap < 1) throw new RangeError("the cap must be at least 1");
    this.cap = cap;
    this.shifts = new Map();
  }

  book(name: string, day: number, hours: number): boolean {
    if (typeof name !== "string" || name === "") throw new RangeError("a name is required");
    if (!Number.isInteger(day) || day < 0) throw new RangeError("a day must be a whole number");
    if (!Number.isInteger(hours) || hours < 0) throw new RangeError("hours must be whole and non-negative");
    const booked = this.shifts.get(name) ?? new Map();
    if (booked.has(day)) return false;
    let total = 0;
    for (const value of booked.values()) total += value;
    if (total + hours > this.cap) return false;
    booked.set(day, hours);
    this.shifts.set(name, booked);
    return true;
  }

  hoursOf(name: string): number {
    const booked = this.shifts.get(name);
    if (booked === undefined) return 0;
    let total = 0;
    for (const value of booked.values()) total += value;
    return total;
  }

  booked(): string[] {
    const out = [];
    for (const [name, days] of this.shifts) {
      for (const day of days.keys()) out.push(name + ":" + day);
    }
    return out.sort();
  }
}
