function energyBill(readings) {
  let day = 0;
  let night = 0;
  const buckets = new Set();
  for (const reading of readings) {
    if (!Number.isInteger(reading.hour) || reading.hour < 0 || reading.hour > 23) {
      throw new RangeError("the hour must be 0..23");
    }
    if (!Number.isFinite(reading.kwh) || reading.kwh < 0) throw new RangeError("kWh must not be negative");
    if (reading.hour >= 7 && reading.hour <= 22) day += reading.kwh;
    else night += reading.kwh;
