function refundFor(order, reason) {
  const { paid, shipping, opened, daysSince } = order;
  for (const value of [paid, shipping, daysSince]) {
    if (!Number.isFinite(value) || value < 0) throw new RangeError("amounts and age must not be negative");
  }
  if (reason !== "defective" && reason !== "changed mind") throw new RangeError("unknown reason");
  const item = paid - shipping;
  if (item < 0) throw new RangeError("shipping cannot exceed the amount paid");
  if (daysSince > 60) return 0;
  const halfUp = (value) => Math.floor(value + 0.5);
  if (reason === "defective") return paid;
  let refundable = item;
  if (daysSince > 30) refundable = halfUp(item / 2);
  const fee = halfUp(refundable * 0.15);
  let total = refundable - fee;
  if (!opened) total += shipping;
  return Math.max(0, total);
}
