```typescript
function matchesPath(path, pattern) {
  if (typeof path !== "string" || path === "") throw new RangeError("a path is required");
  if (typeof pattern !== "string" || pattern === "") throw new RangeError("a pattern is required");
  if (pattern.includes("***")) throw new RangeError("a pattern cannot hold ***");
  let source = "^";
  for (let at = 0; at < pattern.length; at += 1) {
    const letter = pattern[at];
    if (letter === "*") {
      if (pattern[at + 1] === "*") {
        source += ".*";
        at += 1;
      } else {
        source += "[^/]*";
      }
      continue;
    }
    if (letter === "?") {
      source += "[^/]";
      continue;
    }
    source += letter.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }
  source += "$";
  return new RegExp(source).test(path);
}
