"""Choosing a shelf."""

import bisect


def shelf_for(capacities, needed):
    """The index of the first shelf that fits, or -1."""
    if not isinstance(capacities, list):
        raise ValueError("a list of capacities is needed")
    if isinstance(needed, bool) or not isinstance(needed, int) or needed < 0:
        raise ValueError("the needed amount must not be negative")
    spot = bisect.bisect_right(capacities, needed)
    if spot >= len(capacities):
        return -1
    return spot

