int cheapestPlan(std::vector<std::vector<int>> plans, int usage) {
    if (usage < 0) throw std::invalid_argument("the usage must not be negative");
    if (plans.empty()) throw std::invalid_argument("a plan is needed");
    int best = 0;
    long long bestCost = -1;
    for (int index = 0; index < static_cast<int>(plans.size()); ++index) {
        const auto &plan = plans[index];
        if (plan.size() != 3) throw std::invalid_argument("a plan holds base, allowance and rate");
        if (plan[0] < 0 || plan[1] < 0 || plan[2] < 0) throw std::invalid_argument("plan values must not be negative");
        const long long extra = std::max(0, usage - plan[1]);
        const long long cost = plan[0] + extra * plan[2];
        if (bestCost < 0 || cost < bestCost) {
            bestCost = cost;
            best = index;
        }
    }
    return best;
}
