long long libraryFine(std::vector<int> daysLate, int perDay, int graceDays, int capPerItem) {
    if (perDay < 0) throw std::invalid_argument("the daily rate must not be negative");
    if (graceDays < 0) throw std::invalid_argument("the grace period must not be negative");
    if (capPerItem <= 0) throw std::invalid_argument("the cap must be positive");
    long long total = 0;
    for (int late : daysLate) {
        if (late < 0) throw std::invalid_argument("days late must not be negative");
        if (late <= graceDays) continue;
        const long long charge = static_cast<long long>(late - graceDays) * perDay;
        total += charge < capPerItem ? charge : capPerItem;
    }
    return total;
}
