"""Building query strings."""

UNRESERVED = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")


def quote_plus(text):
    """Percent encode one piece, using + for spaces."""
    out = []
    for byte in text.encode("utf-8"):
        letter = chr(byte)
        if letter in UNRESERVED:
            out.append(letter)
        elif letter == " ":
            out.append("+")
        else:
            out.append("%%%02X" % byte)
    return "".join(out)


def build_query(pairs):
    """A query string for the pairs, in order."""
    if not isinstance(pairs, list):
        raise ValueError("a list of pairs is needed")
    parts = []
    for key, value in pairs:
        if not isinstance(key, str) or not isinstance(value, str):
            raise ValueError("keys and values must be strings")
        parts.append(key + "=" + value)
    return "&".join(parts)

