def build_rota(days, workers):
    if isinstance(days, bool) or not isinstance(days, int) or days < 0:
        raise ValueError("the day count must not be negative")
    checked = []
    for worker in workers:
        if not isinstance(worker, tuple) or len(worker) != 2:
            raise ValueError("a worker is a (name, blocked_days) pair")
        checked.append((worker[0], worker[1]))
    streak = {name: 0 for name, _blocked in checked}
    rota = []
    for day in range(days):
        chosen = None
        for name, blocked in checked:
            if day in blocked or streak[name] >= 2:
                continue
            chosen = name
            break
        if chosen is None:
            rota.append(None)
            for name in streak:
                streak[name] = 0
            continue
        rota.append(chosen)
        for name in streak:
            streak[name] = 0 if name != chosen else streak[name] + 1
    return rota
