def reconcile(invoices, payments, tolerance):
    if isinstance(tolerance, bool) or not isinstance(tolerance, int) or tolerance < 0:
        raise ValueError("the tolerance must not be negative")
    pool = list(invoices)
    matches = []
    unmatched = []
    for payment_id, paid in payments:
        best = None
        for invoice_id, due_day, cents in pool:
            gap = abs(paid - cents)
            if gap > tolerance:
                continue
            key = (gap, due_day, invoice_id)
            if best is None or key < best[0]:
                best = (key, (invoice_id, due_day, cents))
        if best is None:
            unmatched.append(payment_id)
            continue
        matches.append((payment_id, best[1][0]))
        pool.remove(best[1])
    return (matches, unmatched)
