from datetime import date, datetime, timedelta


def _last_day(year, month):
    """The last day of a month."""
    if month == 12:
        return 31
    return (date(year, month + 1, 1) - timedelta(days=1)).day


def add_months(moment, months):
    """The moment shifted by whole months, clamped to the month end."""
    if not isinstance(moment, (date, datetime)):
        raise ValueError("a date is needed")
    if isinstance(months, bool) or not isinstance(months, int):
        raise ValueError("the month step must be an integer")
    total = (moment.month - 1) + months
    year = moment.year + total // 12
    month = total % 12 + 1
    day = min(moment.day, 28)
    if isinstance(moment, datetime):
        return moment.replace(year=year, month=month, day=day)
    return date(year, month, day)

