std::vector<std::string> mergeShifts(std::vector<std::pair<int,int>> shifts, int tolerance, int breakAfter, int breakLength) {
    if (tolerance < 0) throw std::invalid_argument("the tolerance must not be negative");
    if (breakAfter < 0) throw std::invalid_argument("the break threshold must not be negative");
    if (breakLength < 0) throw std::invalid_argument("the break length must not be negative");
    std::sort(shifts.begin(), shifts.end());
    for (const auto &shift : shifts) {
        if (shift.second < shift.first) throw std::invalid_argument("a shift cannot end before it starts");
    }
    std::vector<std::pair<int,int>> blocks;
    for (const auto &shift : shifts) {
        if (!blocks.empty() && shift.first - blocks.back().second <= tolerance) {
            if (shift.second > blocks.back().second) blocks.back().second = shift.second;
        } else {
            blocks.push_back(shift);
        }
    }
    std::vector<std::string> out;
    for (const auto &block : blocks) {
        const int minutes = block.second - block.first;
        const int breaks = breakAfter > 0 ? minutes / breakAfter : 0;
        int paid = minutes - breaks * breakLength;
        if (paid < 0) paid = 0;
        out.push_back(std::to_string(block.first) + "-" + std::to_string(block.second) + ":" + std::to_string(paid));
    }
    return out;
}
