std::vector<std::string> dedupeEvents(std::vector<std::string> events, int window) {
    if (window < 0) throw std::invalid_argument("the window must not be negative");
    std::vector<std::pair<int, std::string>> parsed;
    for (const auto &entry : events) {
        const auto space = entry.find(' ');
        if (space == std::string::npos || space == 0 || space + 1 == entry.size())
            throw std::invalid_argument("an event is minute and code");
        for (std::size_t index = 0; index < space; ++index)
            if (!std::isdigit(static_cast<unsigned char>(entry[index])))
                throw std::invalid_argument("the minute must be digits");
        parsed.emplace_back(std::stoi(entry.substr(0, space)), entry.substr(space + 1));
    }
    std::sort(parsed.begin(), parsed.end());
    std::map<std::string, int> lastSeen;
    std::vector<std::string> out;
    int suppressed = 0;
    for (const auto &event : parsed) {
        auto found = lastSeen.find(event.second);
        if (found != lastSeen.end() && event.first - found->second < window) {
            ++suppressed;
            continue;
        }
        lastSeen[event.second] = event.first;
        std::string stamp = std::to_string(event.first);
        while (stamp.size() < 3) stamp = "0" + stamp;
        out.push_back(stamp + " " + event.second);
    }
    out.push_back("suppressed " + std::to_string(suppressed));
    return out;
}
