def quote(start_day, nights, base, uplift_pct, holidays, surcharge, long_stay_days, discount_pct):
    if isinstance(nights, bool) or not isinstance(nights, int) or nights < 0:
        raise ValueError("the night count must not be negative")
    if isinstance(base, bool) or not isinstance(base, int) or base < 0:
        raise ValueError("the base price must not be negative")
    total = 0
    weekend_nights = 0
    holiday_nights = 0
    for step in range(nights):
        day = start_day + step
        price = base
        if day % 7 in (5, 6):
            price += (2 * base * uplift_pct + 100) // 200
            weekend_nights += 1
        if day in holidays:
            price += surcharge
            holiday_nights += 1
        total += price
    if nights >= long_stay_days and discount_pct > 0:
        total -= (2 * total * discount_pct + 100) // 200
    return (total, weekend_nights, holiday_nights)
