def schedule(jobs, setup):
    if isinstance(setup, bool) or not isinstance(setup, int) or setup < 0:
        raise ValueError("the setup time must not be negative")
    for job in jobs:
        if not isinstance(job, tuple) or len(job) != 3:
            raise ValueError("a job is an (id, duration, due) triple")
    ordered = sorted(jobs, key=lambda job: (job[2], job[0]))
    clock = 0
    total = 0
    worst = 0
    order = []
    for index, (job_id, duration, due) in enumerate(ordered):
        if index:
            clock += setup
        clock += duration
        order.append(job_id)
        late = clock - due
        if late < 0:
            late = 0
        total += late
        if late > worst:
            worst = late
    return (order, total, worst)
