function nextState(state: Breaker, event: "ok" | "fail", clock: number, threshold: number, cooldown: number): Breaker {
  if (threshold < 1) throw new Error("threshold must be positive");
  if (cooldown < 0) throw new Error("cooldown must not be negative");
  if (state.kind === "closed") {
