type Field = { name: string; kind: "int" | "text" | "bool" };
type Parsed = { rows: Array<Record<string, string | number | boolean>>; errors: string[] };

function parseRows(csv: string, fields: Field[]): Parsed {
  const errors: string[] = [];
  const rows: Array<Record<string, string | number | boolean>> = [];
  const lines = csv.split("\n").filter((line) => line.trim() !== "");
  if (lines.length === 0) return { rows, errors };
  const header = lines[0].split(",").map((cell) => cell.trim());
  const expected = fields.map((field) => field.name);
  if (header.length !== expected.length || header.some((cell, at) => cell !== expected[at])) {
    errors.push("header");
    return { rows, errors };
  }
  for (let index = 1; index < lines.length; index += 1) {
    const cells = lines[index].split(",").map((cell) => cell.trim());
    if (cells.length !== fields.length) {
      errors.push("row " + index + ": wrong width");
      continue;
    }
    const record: Record<string, string | number | boolean> = {};
    let bad = false;
    for (let at = 0; at < fields.length; at += 1) {
      const field = fields[at];
      const cell = cells[at];
      if (field.kind === "int") {
        if (!/^-?[0-9]+$/.test(cell)) {
          errors.push("row " + index + " " + field.name + ": not an int");
          bad = true;
          break;
        }
        record[field.name] = Number(cell);
      } else if (field.kind === "bool") {
        if (cell !== "y" && cell !== "n") {
          errors.push("row " + index + " " + field.name + ": not a bool");
          bad = true;
          break;
        }
        record[field.name] = cell === "y";
      } else {
        record[field.name] = cell;
      }
    }
    if (!bad) rows.push(record);
  }
  return { rows, errors };
}
