function eachDay(start: string, end: string): string[] {
  const parse = (text: string): number => {
    if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(text)) throw new Error("bad date " + text);
    const stamp = Date.parse(text + "T00:00:00Z");
    if (Number.isNaN(stamp)) throw new Error("bad date " + text);
    const back = new Date(stamp).toISOString().slice(0, 10);
    if (back !== text) throw new Error("bad date " + text);
    return stamp;
  };
  const first = parse(start);
  const last = parse(end);
  const out: string[] = [];
