type Win = { start: number; end: number; tags: string[] };

function mergeWindows(windows: Win[]): Win[] {
  for (const win of windows) {
    if (win.end < win.start) throw new Error("a window cannot end before it starts");
  }
  const ordered = [...windows].sort((left, right) => left.start - right.start || left.end - right.end);
  const out: Win[] = [];
  for (const win of ordered) {
    const last = out[out.length - 1];
    if (last && win.start <= last.end) {
      if (win.end > last.end) last.end = win.end;
      for (const tag of win.tags) {
        if (!last.tags.includes(tag)) last.tags.push(tag);
      }
      last.tags.sort();
      continue;
    }
    out.push({ start: win.start, end: win.end, tags: [...win.tags].sort() });
  }
  return out;
}
