function checkPassword(password, rules) {
  if (typeof password !== "string") throw new Error("a password string is needed");
  const failing = [];
  const any = (pattern) => pattern.test(password);
  for (const rule of rules) {
    let ok = true;
    if (rule.kind === "minLen") {
      ok = password.length >= rule.value;
    } else if (rule.kind === "maxLen") {
      ok = password.length <= rule.value;
    } else if (rule.kind === "hasUpper") {
      ok = any(/[A-Z]/);
    } else if (rule.kind === "hasLower") {
      ok = any(/[a-z]/);
    } else if (rule.kind === "hasDigit") {
      ok = any(/[0-9]/);
    } else if (rule.kind === "hasSymbol") {
      ok = any(/[^A-Za-z0-9]/);
    } else if (rule.kind === "noRepeat") {
      let run = 0;
      let previous = "";
      ok = true;
      for (const letter of password) {
        run = letter === previous ? run + 1 : 1;
        previous = letter;
        if (run > rule.value) ok = false;
      }
    } else if (rule.kind === "noCommon") {
      const lowered = password.toLowerCase();
      ok = !rule.value.some((word) => lowered.includes(word.toLowerCase()));
    } else {
      throw new Error("unknown rule " + rule.kind);
    }
    if (!ok) failing.push(rule.id);
  }
  return failing;
}
