function slugify(title) {
  if (typeof title !== "string") throw new Error("a title string is needed");
  const lowered = title
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  if (lowered === "") return "untitled";
  if (lowered.length <= 60) return lowered;
  const cut = lowered.slice(0, 61);
  const boundary = cut.lastIndexOf("-");
  const trimmed = (boundary > 0 ? cut.slice(0, boundary) : lowered.slice(0, 60)).replace(/-+$/g, "");
  return trimmed === "" ? "untitled" : trimmed;
}
