function histogram(values, edges) {
  if (!Array.isArray(edges) || edges.length < 2) throw new Error("at least two edges are needed");
  for (let at = 1; at < edges.length; at += 1) {
    if (!(edges[at] > edges[at - 1])) throw new Error("edges must increase");
  }
  const bins = [{ bin: "under", count: 0 }];
  for (let at = 1; at < edges.length; at += 1) {
    bins.push({ bin: edges[at - 1] + "-" + edges[at], count: 0 });
  }
  bins.push({ bin: "over", count: 0 });
  for (const value of values) {
    if (value < edges[0]) {
      bins[0].count += 1;
      continue;
    }
    if (value > edges[edges.length - 1]) {
      bins[bins.length - 1].count += 1;
      continue;
    }
    let placed = false;
    for (let at = 1; at < edges.length; at += 1) {
      const last = at === edges.length - 1;
      if (value >= edges[at - 1] && (last ? value <= edges[at] : value < edges[at])) {
        bins[at].count += 1;
        placed = true;
        break;
      }
    }
    if (!placed) bins[bins.length - 1].count += 1;
  }
  return bins;
}
