from datetime import date, timedelta


def is_weekend(moment):
    """True on Saturday and Sunday."""
    if not isinstance(moment, date):
        raise ValueError("a date is needed")
    return moment.isoweekday() >= 5


def surcharge_pct(moment):
    """The delivery surcharge for a day."""
    return 25 if is_weekend(moment) else 0


def next_weekend(start):
    """The first weekend day on or after the start."""
    moment = start
    for _step in range(7):
        if is_weekend(moment):
            return moment
        moment = moment + timedelta(days=1)
    return moment

