std::vector<std::string> coverageGaps(std::vector<std::pair<int,int>> shifts, std::vector<std::pair<int,int>> windows) {
    for (const auto &shift : shifts)
        if (shift.second < shift.first) throw std::invalid_argument("a shift cannot end before it starts");
    for (const auto &window : windows)
        if (window.second < window.first) throw std::invalid_argument("a window cannot end before it starts");
    std::sort(shifts.begin(), shifts.end());
    std::vector<std::pair<int,int>> merged;
    for (const auto &shift : shifts) {
        if (!merged.empty() && shift.first <= merged.back().second) {
            if (shift.second > merged.back().second) merged.back().second = shift.second;
        } else {
            merged.push_back(shift);
        }
    }
    std::vector<std::string> out;
    for (const auto &window : windows) {
        int covered = 0;
        for (const auto &block : merged) {
            const int low = std::max(window.first, block.first);
            const int high = std::min(window.second, block.second);
            if (high > low) covered += high - low;
        }
        out.push_back(std::to_string(window.first) + "-" + std::to_string(window.second) + ":" +
                      std::to_string((window.second - window.first) - covered));
    }
    return out;
}
