def fare_cap(journeys, daily_cap, weekly_cap):
    if isinstance(daily_cap, bool) or not isinstance(daily_cap, int) or daily_cap <= 0:
        raise ValueError("the daily cap must be positive")
    if isinstance(weekly_cap, bool) or not isinstance(weekly_cap, int) or weekly_cap <= 0:
        raise ValueError("the weekly cap must be positive")
    charges = []
    daily = {}
    weekly = {}
    for day, fare in journeys:
        if isinstance(fare, bool) or not isinstance(fare, int) or fare < 0:
            raise ValueError("the fare must not be negative")
        week = day // 7
        room_day = daily_cap - daily.get(day, 0)
        room_week = weekly_cap - weekly.get(week, 0)
        pay = fare
        if room_day < pay:
            pay = room_day
        if room_week < pay:
            pay = room_week
        if pay < 0:
            pay = 0
        daily[day] = daily.get(day, 0) + pay
        weekly[week] = weekly.get(week, 0) + pay
        charges.append(pay)
    return (sum(charges), charges)
