def approve(requests, staff, coverage):
    if isinstance(coverage, bool) or not isinstance(coverage, int) or coverage < 0:
        raise ValueError("the coverage must not be negative")
    approved = []
    rejected = []
    off_days = {}
    seen = set()
    for request in requests:
        who, day = request
        if who not in staff or (who, day) in seen:
            rejected.append(request)
            continue
        off = 0
        for other, other_day in seen:
            if other_day == day:
                off += 1
        if len(staff) - off - 1 < coverage:
            rejected.append(request)
            continue
        seen.add((who, day))
        off_days[day] = off_days.get(day, 0) + 1
        approved.append(request)
    return (approved, rejected)
