def assess(counts, bands):
    checked = []
    for band in bands:
        if not isinstance(band, tuple) or len(band) != 2:
            raise ValueError("a band is a (limit, action) pair")
        checked.append((band[0], band[1]))
    checked.sort()
    out = []
    for sku, book, counted, cost in counts:
        if book < 0 or counted < 0 or cost < 0:
            raise ValueError("counts must not be negative")
        delta = counted - book
        value = delta * cost
        if abs(delta) <= 1:
            action = "accept"
        else:
            action = "escalate"
            for limit, name in checked:
                if abs(value) <= limit:
                    action = name
                    break
        out.append((sku, delta, value, action))
    return out
