def leak_run(readings, night_hours, threshold):
    if isinstance(threshold, bool) or not isinstance(threshold, int) or threshold < 0:
        raise ValueError("the threshold must not be negative")
    best = 0
    best_start = None
    run = 0
    start = None
    previous = None
    for hour, litres in sorted(readings):
        if litres < 0:
            raise ValueError("readings must not be negative")
        if hour in night_hours and litres >= threshold:
            if run and previous is not None and hour == previous + 1:
                run += 1
            else:
                run = 1
                start = hour
            previous = hour
            if run > best:
                best = run
                best_start = start
        else:
