std::vector<std::string> excursions(std::vector<std::pair<int,int>> readings, int low, int high, int graceMinutes) {
    if (low > high) throw std::invalid_argument("low must not exceed high");
    if (graceMinutes < 0) throw std::invalid_argument("the grace must not be negative");
    std::sort(readings.begin(), readings.end());
    std::vector<std::string> out;
    int total = 0;
    bool running = false;
    int start = 0;
    for (std::size_t index = 0; index < readings.size(); ++index) {
        const int minute = readings[index].first;
        const int temp = readings[index].second;
        const bool outside = temp < low || temp > high;
        if (outside && !running) {
            running = true;
            start = minute;
        }
        const bool last = index + 1 == readings.size();
        if (running && (!outside || last)) {
            const int end = outside ? minute + 1 : minute;
            if (end - start >= graceMinutes) {
                out.push_back(std::to_string(start) + "-" + std::to_string(end));
                total += end - start;
            }
            running = false;
        }
    }
    out.push_back("total " + std::to_string(total));
    return out;
}
