std::vector<std::string> padLabels(std::vector<std::string> codes, int width) {
    if (width < 1) throw std::invalid_argument("the width must be positive");
    std::vector<std::string> out;
    for (const auto &code : codes) {
        std::size_t index = 0;
        while (index < code.size() && std::isalpha(static_cast<unsigned char>(code[index]))) ++index;
        const std::string prefix = code.substr(0, index);
        const std::string digits = code.substr(index);
        bool ok = !digits.empty();
        for (char ch : digits) {
            if (!std::isdigit(static_cast<unsigned char>(ch))) {
                ok = false;
                break;
            }
        }
        if (!ok) {
            out.push_back("invalid");
            continue;
        }
        std::string padded = digits;
        while (static_cast<int>(padded.size()) < width) padded = "0" + padded;
        out.push_back(prefix + padded);
    }
    return out;
}
