std::vector<std::string> tolls(std::vector<std::tuple<int,int,int>> trips, int entryFee, int perKm, int cap, int freeKm) {
    if (entryFee < 0 || perKm < 0 || cap < 0 || freeKm < 0)
        throw std::invalid_argument("money and free kilometres must not be negative");
    std::vector<std::string> out;
    for (const auto &trip : trips) {
        const int start = std::get<0>(trip);
        const int end = std::get<1>(trip);
        const int cls = std::get<2>(trip);
        if (end < start) throw std::invalid_argument("a trip cannot end before it starts");
        int multiplier = 0;
        if (cls == 1) multiplier = 100;
        else if (cls == 2) multiplier = 200;
        else if (cls == 3) multiplier = 250;
        else throw std::invalid_argument("unknown class");
        const int distance = end - start;
        const int billed = distance - freeKm > 0 ? distance - freeKm : 0;
        const int base = entryFee + billed * perKm;
        int charge = (2 * base * multiplier + 100) / 200;
        if (charge > cap) charge = cap;
        out.push_back(std::to_string(start) + "-" + std::to_string(end) + ":" + std::to_string(charge));
    }
    return out;
}
