def duty(items, bands, de_minimis, preferred):
    if isinstance(de_minimis, bool) or not isinstance(de_minimis, int) or de_minimis < 0:
        raise ValueError("the de minimis must not be negative")
    checked = []
    for band in bands:
        if not isinstance(band, tuple) or len(band) != 2:
            raise ValueError("a band is a (limit, rate) pair")
        checked.append((band[0], band[1]))
    checked.sort()
    total_value = 0
    for item in items:
        if not isinstance(item, tuple) or len(item) != 4:
            raise ValueError("an item is (name, value, origin, category)")
        if item[1] < 0:
            raise ValueError("values must not be negative")
        total_value += item[1]
    if total_value <= de_minimis:
        return (0, [0] * len(items))
    duties = []
    for _name, value, origin, _category in items:
        percent = 0
        for limit, rate in checked:
            if value <= limit:
                percent = rate
                break
        if origin in preferred:
            percent //= 2
        duties.append((2 * value * percent + 100) // 200)
    return (sum(duties), duties)
