def depreciate(cost, residual, months):
    if isinstance(cost, bool) or not isinstance(cost, int) or cost < 0:
        raise ValueError("the cost must not be negative")
    if isinstance(residual, bool) or not isinstance(residual, int) or residual < 0:
        raise ValueError("the residual must not be negative")
    if residual > cost:
        raise ValueError("the residual cannot exceed the cost")
    if isinstance(months, bool) or not isinstance(months, int) or months < 1:
        raise ValueError("at least one month is needed")
    base = (cost - residual) // months
    schedule = []
    book = cost
    for index in range(months):
        amount = base if index < months - 1 else book - residual
        if amount < 0:
            amount = 0
        if amount > book - residual:
            amount = book - residual
        book -= amount
        schedule.append(amount)
    return schedule
