def payroll(punches, rate, break_minutes, threshold_minutes):
    if isinstance(rate, bool) or not isinstance(rate, int) or rate < 0:
        raise ValueError("the rate must not be negative")
    if isinstance(break_minutes, bool) or not isinstance(break_minutes, int) or break_minutes < 0:
        raise ValueError("the break must not be negative")
    if isinstance(threshold_minutes, bool) or not isinstance(threshold_minutes, int) or threshold_minutes < 0:
        raise ValueError("the threshold must not be negative")
    paid = 0
    for _day, start, end in punches:
        low = (start // 5) * 5
        high = -((-end) // 5) * 5
        minutes = high - low
        if minutes > threshold_minutes:
            minutes -= break_minutes
        if minutes < 0:
            minutes = 0
        paid += minutes
    cents = (2 * paid * rate + 60) // 120
    return (paid, cents)
