def postage(weight_g, zone, table, extra_per_100g=25):
    if isinstance(weight_g, bool) or not isinstance(weight_g, int) or weight_g < 0:
        raise ValueError("the weight must not be negative")
    if zone not in table:
        raise ValueError("unknown zone " + str(zone))
    bands = table[zone]
    if not bands:
        raise ValueError("a zone needs bands")
    covered = 0
    for band_grams, price in bands:
        covered += band_grams
        if weight_g <= covered:
            return price
    last_price = bands[-1][1]
    over = weight_g - covered
    steps = -(-over // 100)
    return last_price + steps * extra_per_100g
