"""Literal search."""


def find_literal(text, needle):
    """The index of the first literal occurrence, or -1."""
    if not isinstance(text, str) or not isinstance(needle, str):
        raise ValueError("two strings are needed")
    if needle == "":
        raise ValueError("the needle must not be empty")
    import re
    found = re.search(needle, text)
    return found.start() if found else -1


def count_literal(text, needle):
    """How many literal occurrences start in the text."""
    if needle == "":
        raise ValueError("the needle must not be empty")
    total = 0
    start = find_literal(text, needle)
    while start != -1:
        total += 1
        start = text.find(needle, start + 1)
    return total


def contains_literal(text, needle):
    """True when the needle occurs."""
    return find_literal(text, needle) != -1

