"""Bucket indexes."""


def bucket(value, width):
    """The bucket a value belongs to."""
    if not isinstance(value, int) or isinstance(value, bool):
        raise ValueError("a value must be a whole number")
    if not isinstance(width, int) or isinstance(width, bool) or width < 1:
        raise ValueError("the width must be positive")
    return int(round(value / width))


def label(value, width):
    """The bucket range a value belongs to."""
    start = bucket(value, width) * width
    return "%d-%d" % (start, start + width - 1)


def counts(values, width, buckets):
    """How many values fall into each of the first n buckets."""
    out = [0] * buckets
    for value in values:
        index = bucket(value, width)
        if 0 <= index < buckets:
            out[index] += 1
    return out

