"""Fixed width fields."""


def field(line, start, width):
    """One field of a fixed width line."""
    if not isinstance(line, str):
        raise ValueError("a line is needed")
    if start < 0 or width < 1:
        raise ValueError("the slice must be positive")
    return line[start:start + width].strip()


def number(line, start, width):
    """A field read as a whole number."""
    text = field(line, start, width).strip()
    if text == "":
        return 0
    body = text[1:] if text[0] in "+-" else text
    if not body.isdigit():
        raise ValueError("not a number: " + repr(text))
    return int(text)


def split(line, widths):
    """Every field of a line."""
    out = []
    cursor = 0
    for width in widths:
        out.append(field(line, cursor, width))
        cursor += width
    return out

