std::vector<std::string> checkEans(std::vector<std::string> codes) {
    std::vector<std::string> out;
    for (const auto &code : codes) {
        if (code.size() != 13) {
            out.push_back("bad_len");
            continue;
        }
        bool badChar = false;
        for (char ch : code) {
            if (ch < '0' || ch > '9') {
                badChar = true;
                break;
            }
        }
        if (badChar) {
            out.push_back("bad_char");
            continue;
        }
        int total = 0;
        for (int index = 0; index < 12; ++index) {
            const int digit = code[index] - '0';
            total += (index % 2 == 0) ? digit : digit * 3;
        }
        const int check = (10 - total % 10) % 10;
        out.push_back(check == (code[12] - '0') ? "ok" : "bad_check");
    }
    return out;
}
