std::vector<std::string> rebalance(std::vector<int> docks, int target) {
    if (target < 0) throw std::invalid_argument("the target must not be negative");
    std::vector<std::pair<int,int>> spare;
    for (int index = 0; index < static_cast<int>(docks.size()); ++index) {
        if (docks[index] > target) spare.emplace_back(index, docks[index] - target);
    }
    std::vector<std::string> out;
    std::size_t slot = 0;
    for (int index = 0; index < static_cast<int>(docks.size()); ++index) {
        int need = target - docks[index];
        while (need > 0 && slot < spare.size()) {
            if (spare[slot].second == 0) {
                ++slot;
                continue;
            }
            const int take = std::min(spare[slot].second, need);
            out.push_back(std::to_string(spare[slot].first) + "-" + std::to_string(index) + ":" + std::to_string(take));
            spare[slot].second -= take;
            need -= take;
            if (spare[slot].second == 0) ++slot;
