function chunk<T>(values: Iterable<T>, size: number): T[][] {
  if (!Number.isInteger(size) || size < 1) throw new Error("the chunk size must be a positive whole number");
  const out: T[][] = [];
  let current: T[] = [];
  for (const value of values) {
    current.push(value);
    if (current.length === size) {
      out.push(current);
      current = [];
    }
  }
  if (current.length) out.push(current);
  return out;
}

function takeWhile<T>(values: Iterable<T>, keep: (value: T) => boolean): T[] {
  const out: T[] = [];
  for (const value of values) {
    if (!keep(value)) break;
    out.push(value);
  }
  return out;
}

function dedupeAdjacent<T>(values: Iterable<T>): T[] {
  const out: T[] = [];
  for (const value of values) {
    if (out.length && out[out.length - 1] === value) continue;
    out.push(value);
  }
  return out;
}
