function formatMoney(cents: number, separator: string = ",", decimals: number = 2): string {
  if (!Number.isInteger(cents)) throw new Error("cents must be a whole number");
  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 2) throw new Error("decimals must be 0, 1 or 2");
  if (separator === "" || /[0-9]/.test(separator)) throw new Error("the separator must not be a digit");
  const negative = cents < 0;
  const value = Math.abs(cents);
  const whole = Math.floor(value / 100);
  const rest = value % 100;
  let text = String(whole);
  let grouped = "";
  for (let index = 0; index < text.length; index += 1) {
    const fromEnd = text.length - index;
    if (index > 0 && fromEnd % 3 === 0) grouped += separator;
    grouped += text[index];
  }
  let digits = "";
  if (decimals > 0) {
    digits = "." + String(rest).padStart(2, "0").slice(0, decimals);
  }
  return (negative ? "-" : "") + grouped + digits;
}
