class BoundedMedian {
  values: number[] = [];
  capacity: number;
  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new Error("the capacity must be a positive whole number");
    this.capacity = capacity;
  }

  add(value: number): void {
    if (!Number.isFinite(value)) throw new Error("a finite number is needed");
    this.values.push(value);
    this.values.sort((left, right) => left - right);
    if (this.values.length > this.capacity) this.values.shift();
  }

  size(): number {
    return this.values.length;
  }

  median(): number | null {
    if (this.values.length === 0) return null;
    return this.values[(this.values.length - 1) >> 1];
  }
}
