function buildInsert(table: string, rows: Array<Record<string, string | number | boolean | null>>): string {
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(table)) throw new Error("bad table name");
  if (rows.length === 0) throw new Error("at least one row is needed");
  const columns = Object.keys(rows[0]);
  if (columns.length === 0) throw new Error("a row needs columns");
  for (const row of rows) {
    for (const column of columns) {
      if (!(column in row)) throw new Error("every row needs the same columns");
    }
  }
  const quote = (value: string): string => "'" + value.split("'").join("''") + "'";
  const cell = (value: string | number | boolean | null): string => {
    if (value === null) return "NULL";
    if (typeof value === "number") {
      if (!Number.isFinite(value)) throw new Error("numbers must be finite");
      return String(value);
    }
    if (typeof value === "boolean") return value ? "1" : "0";
    return quote(value);
  };
  const tuples = rows.map((row) => "(" + columns.map((column) => cell(row[column])).join(", ") + ")");
  return "INSERT INTO " + table + " (" + columns.join(", ") + ") VALUES " + tuples.join(", ");
}
