type Entry = { key: string; value: number; at: number };

function compact(entries: Entry[]): Entry[] {
  const latest = new Map<string, number>();
  for (let index = 0; index < entries.length; index += 1) {
    latest.set(entries[index].key, index);
  }
  const out: Entry[] = [];
  for (let index = 0; index < entries.length; index += 1) {
    if (latest.get(entries[index].key) === index) out.push(entries[index]);
  }
  return out;
}

function versionOf(entries: Entry[], key: string): number | null {
  let found: number | null = null;
  for (const entry of entries) {
    if (entry.key === key) {
      if (found === null || entry.at >= found) found = entry.at;
    }
  }
  return found;
}
