function assignSeats(rows, cols, taken, requests) {
  if (!Number.isInteger(rows) || rows < 1) throw new Error("rows must be positive");
  if (!Number.isInteger(cols) || cols < 1) throw new Error("columns must be positive");
  const used = new Set(taken);
  const out = [];
  for (const count of requests) {
    if (!Number.isInteger(count) || count < 1) throw new Error("a request must be a positive whole number");
    let placed = null;
    for (let row = 1; row <= rows && !placed; row += 1) {
      for (let start = 0; start + count <= cols; start += 1) {
        let free = true;
        for (let step = 0; step < count; step += 1) {
          const letter = String.fromCharCode(65 + start + step);
          if (used.has(row + letter)) {
            free = false;
            break;
          }
        }
        if (free) {
          placed = [];
          for (let step = 0; step < count; step += 1) {
            const seat = row + String.fromCharCode(65 + start + step);
            used.add(seat);
            placed.push(seat);
          }
          break;
        }
      }
    }
    out.push(placed);
  }
  return out;
}
