function splitCsvLine(line) {
  if (typeof line !== "string") throw new Error("a line is needed");
  const fields = [];
  let at = 0;
  if (line === "") return [""];
  while (true) {
    let field = "";
    if (line[at] === '"') {
      at += 1;
      let closed = false;
      while (at < line.length) {
        if (line[at] === '"') {
          if (line[at + 1] === '"') {
            field += '"';
            at += 2;
            continue;
          }
          at += 1;
          closed = true;
          break;
        }
        field += line[at];
        at += 1;
      }
      if (!closed) throw new Error("unterminated quote");
      if (at < line.length && line[at] !== ",") throw new Error("unexpected text after a closing quote");
    } else {
      while (at < line.length && line[at] !== ",") {
        if (line[at] === '"') throw new Error("a quote must start a field");
        field += line[at];
        at += 1;
      }
    }
    fields.push(field);
    if (at >= line.length) break;
    at += 1;
    if (at === line.length) {
      fields.push("");
      break;
    }
  }
  return fields;
}
