    if (seed < 0) throw std::invalid_argument("the seed must not be negative");
    std::vector<int> distinct = ids;
    std::sort(distinct.begin(), distinct.end());
    distinct.erase(std::unique(distinct.begin(), distinct.end()), distinct.end());
    if (k >= static_cast<int>(distinct.size())) return distinct;
    std::vector<std::pair<std::uint32_t, int>> scored;
    scored.reserve(distinct.size());
    for (int value : distinct) {
        scored.emplace_back(mixScore(static_cast<std::uint32_t>(value), static_cast<std::uint32_t>(seed)), value);
    }
    std::sort(scored.begin(), scored.end());
    std::vector<int> out;
    out.reserve(k);
    for (int index = 0; index < k; ++index) out.push_back(scored[index].second);
    std::sort(out.begin(), out.end());
