std::vector<std::string> checkIbans(std::vector<std::string> codes) {
    std::vector<std::string> out;
    for (const auto &code : codes) {
        std::string text;
        for (char ch : code) {
            if (ch == ' ') continue;
            text += static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
        }
        if (text.size() < 15 || text.size() > 34) {
            out.push_back("bad_len");
            continue;
        }
        bool badChar = false;
        for (char ch : text) {
            const bool letter = ch >= 'A' && ch <= 'Z';
            const bool digit = ch >= '0' && ch <= '9';
            if (!letter && !digit) {
                badChar = true;
                break;
            }
        }
        if (badChar) {
            out.push_back("bad_char");
            continue;
        }
        const std::string moved = text.substr(4) + text.substr(0, 4);
        long long remainder = 0;
        for (char ch : moved) {
            if (ch >= '0' && ch <= '9') {
                remainder = (remainder * 10 + (ch - '0')) % 97;
            } else {
                remainder = (remainder * 100 + (ch - 'A' + 10)) % 97;
            }
        }
        out.push_back(remainder == 1 ? "ok" : "bad_check");
    }
    return out;
}
