int maxConcurrent(std::vector<std::pair<int,int>> visits) {
    std::vector<std::pair<int,int>> events;
    for (const auto &visit : visits) {
        if (visit.second < visit.first) throw std::invalid_argument("a visit cannot end before it starts");
        events.emplace_back(visit.first, 1);
        events.emplace_back(visit.second, -1);
    }
    std::sort(events.begin(), events.end());
    int current = 0;
    int best = 0;
    for (const auto &event : events) {
        current += event.second;
        if (current > best) best = current;
    }
    return best;
}
