def price_lease(monthly_cents, start_day, end_day, days_in_month, late_fee_cents, paid_day, grace_days):
    for name, val in [("monthly", monthly_cents), ("late_fee", late_fee_cents), ("grace", grace_days)]:
        if isinstance(val, bool) or not isinstance(val, int) or val < 0:
            raise ValueError(name + " must be non-negative")
    for name, val in [("days_in_month", days_in_month), ("start_day", start_day), ("paid_day", paid_day)]:
        if isinstance(val, bool) or not isinstance(val, int) or val < 1:
            raise ValueError(name + " must be at least 1")
    if isinstance(end_day, bool) or not isinstance(end_day, int) or end_day < start_day or end_day > days_in_month:
        raise ValueError("invalid end_day")
    occupied = end_day - start_day + 1
    rent = (2 * monthly_cents * occupied + days_in_month) // (2 * days_in_month)
    due_by = start_day + grace_days
    fee = late_fee_cents if (rent > 0 and paid_day > due_by) else 0
    return (occupied, rent, fee, rent + fee)
