def evaluate_sla(window_start, window_end, outages, target_ppm, credit_tiers):
    if isinstance(window_start, bool) or not isinstance(window_start, int):
        raise ValueError("bad window_start")
    if isinstance(window_end, bool) or not isinstance(window_end, int) or window_end <= window_start:
        raise ValueError("window_end must exceed window_start")
    if isinstance(target_ppm, bool) or not isinstance(target_ppm, int) or not (0 <= target_ppm <= 1_000_000):
        raise ValueError("bad target_ppm")
    clipped = []
    for s, e in outages:
        if e < s:
            raise ValueError("outage ends before it starts")
        cs = s if s > window_start else window_start
        ce = e if e < window_end else window_end
        if cs < ce:
            clipped.append((cs, ce))
    clipped.sort()
    merged = []
    for s, e in clipped:
        if merged and s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1] = (merged[-1][0], e)
        else:
            merged.append((s, e))
    down = sum(e - s for s, e in merged)
    total = window_end - window_start
    uptime_ppm = ((total - down) * 1_000_000) // total
    credit = 0
    if uptime_ppm < target_ppm:
        for thresh, pct in sorted(credit_tiers):
            if uptime_ppm <= thresh:
                credit = pct
                break
    return (down, uptime_ppm, credit)
