def pack_bins(items, capacity, max_bins):
    if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be >= 1")
    if isinstance(max_bins, bool) or not isinstance(max_bins, int) or max_bins < 1:
        raise ValueError("max_bins must be >= 1")
    rem_list = []
    bins = []
    rejected = []
    for sku, weight in items:
        if isinstance(weight, bool) or not isinstance(weight, int) or weight < 1:
            raise ValueError("weight must be >= 1")
        if weight > capacity:
            rejected.append((sku, "oversize"))
            continue
        best_idx = -1
        best_rem = None
        for idx, rem in enumerate(rem_list):
            if rem >= weight:
                after = rem - weight
                if best_rem is None or after < best_rem:
                    best_rem = after
                    best_idx = idx
                    if after == 0:
                        break
        if best_idx != -1:
            rem_list[best_idx] -= weight
            bins[best_idx].append(sku)
        elif len(bins) < max_bins:
            rem_list.append(capacity - weight)
            bins.append([sku])
        else:
            rejected.append((sku, "full"))
    return ([tuple(b) for b in bins], rejected)
