def retain_snapshots(snapshots, now_day, keep_daily, keep_weekly, max_bytes):
    for name, val in [("now_day", now_day), ("keep_daily", keep_daily), ("keep_weekly", keep_weekly), ("max_bytes", max_bytes)]:
        if isinstance(val, bool) or not isinstance(val, int) or val < 0:
            raise ValueError(name + " must be non-negative")
    for sid, day, size in snapshots:
        if day > now_day or size < 0:
            raise ValueError("invalid snapshot " + str(sid))
    ordered = sorted(snapshots, key=lambda item: (-item[1], item[0]))
    seen_days = set()
    seen_weeks = set()
    kept = []
    used = 0
    for sid, day, size in ordered:
        protect = False
        if day not in seen_days and len(seen_days) < keep_daily:
            seen_days.add(day)
            protect = True
        week = day // 7
        if week not in seen_weeks and len(seen_weeks) < keep_weekly:
            seen_weeks.add(week)
            protect = True
        if protect and used + size <= max_bytes:
            kept.append(sid)
            used += size
    return (sorted(kept), used)
