import sys


def main():
    lines = [l.split() for l in sys.stdin.read().splitlines() if l.strip()]
    if not lines:
        return
    s_cap, m_cap, l_cap = int(lines[0][0]), int(lines[0][1]), int(lines[0][2])
    caps = {"S": s_cap, "M": m_cap, "L": l_cap}
    next_new = {"S": 1, "M": 1, "L": 1}
    freed = {"S": [], "M": [], "L": []}
    order = {"S": ("S", "M", "L"), "M": ("M", "L"), "L": ("L",)}
    placed = {}
    out = []
    for parts in lines[1:]:
        if parts[0] == "IN":
            pid, sz = parts[1], parts[2]
            chosen = None
            for tier in order[sz]:
                if freed[tier]:
                    num = heapq.heappop(freed[tier])
                    chosen = (tier, num)
                    break
                if next_new[tier] <= caps[tier]:
                    num = next_new[tier]
                    next_new[tier] += 1
                    chosen = (tier, num)
                    break
            if chosen is None:
                out.append("FULL " + pid)
            else:
                tier, num = chosen
                placed[pid] = (tier, num)
                out.append("OK %s %s%d" % (pid, tier, num))
        else:
            pid = parts[1]
            if pid not in placed:
                out.append("MISS " + pid)
            else:
                tier, num = placed.pop(pid)
                heapq.heappush(freed[tier], num)
                out.append("OUT %s %s%d" % (pid, tier, num))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


main()
