import heapq
import sys


def main():
    lines = [l.split() for l in sys.stdin.read().splitlines() if l.strip()]
    if not lines:
        return
    heaps = {}
    valid_tot = {}
    expired_pending = {}
    out = []
    for parts in lines[1:]:
        cmd = parts[0]
        if cmd == "ADD":
            sku, qty, exp = parts[1], int(parts[2]), int(parts[3])
            if qty > 0:
                heapq.heappush(heaps.setdefault(sku, []), [exp, qty])
                valid_tot[sku] = valid_tot.get(sku, 0) + qty
        elif cmd == "PURGE":
            day = int(parts[1])
            removed = 0
            for sku, q in expired_pending.items():
                removed += q
            expired_pending.clear()
            for sku, h in heaps.items():
                while h and h[0][0] < day:
                    q = heapq.heappop(h)[1]
                    removed += q
                    valid_tot[sku] -= q
            out.append("PURGED %d" % removed)
        else:
            sku, need, day = parts[1], int(parts[2]), int(parts[3])
            h = heaps.get(sku)
            if not h:
                out.append("SHORT %s 0" % sku)
                continue
            while h and h[0][0] < day:
                q = heapq.heappop(h)[1]
                valid_tot[sku] -= q
                expired_pending[sku] = expired_pending.get(sku, 0) + q
            avail = valid_tot.get(sku, 0)
            if avail < need:
                out.append("SHORT %s %d" % (sku, avail))
            else:
                rem = need
                used_lots = 0
                while rem > 0:
                    top = h[0]
                    take = top[1] if top[1] < rem else rem
                    top[1] -= take
                    valid_tot[sku] -= take
                    rem -= take
                    used_lots += 1
                    if top[1] == 0:
                        heapq.heappop(h)
                out.append("SHIP %s %d" % (sku, used_lots))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


main()
