"""In-memory TTL store (timestamps in milliseconds)."""


class TtlStore:
    def __init__(self):
        self._data = {}

    def put(self, key, value, now_ms, ttl_ms):
        if ttl_ms < 0:
            raise ValueError("ttl_ms must be non-negative")
        self._data[key] = (value, now_ms + ttl_ms)

    def get(self, key, now_ms):
        entry = self._data.get(key)
        if entry is None:
            return None
        value, expires_at = entry
        if now_ms > expires_at:
            del self._data[key]
            return None
        return value

