"""Token gate backed by TtlStore."""

from .store import TtlStore


class Gate:
    def __init__(self, ttl_seconds, limit):
        if ttl_seconds < 0 or limit < 1:
            raise ValueError("invalid gate config")
        self.ttl_ms = ttl_seconds
        self.limit = limit
        self.store = TtlStore()

    def allow(self, client, now_ms):
        count = self.store.get(client, now_ms)
        if count is None:
            self.store.put(client, 1, now_ms, self.ttl_ms)
            return True
        if count >= self.limit:
            return False
        self.store.put(client, count + 1, now_ms, self.ttl_ms)
        return True

