from .lines import half_up, line_taxable


def build_invoice(lines, tax_pct):
    if tax_pct < 0:
        raise ValueError("negative tax")
    gross = sum(q * u for q, u, _d in lines)
    tax = (gross * tax_pct) // 100
    subtotal = sum(line_taxable(q, u, d) for q, u, d in lines)
