std::vector<bool> allowRequests(std::vector<std::tuple<long long, std::string, long long>> events, long long window, long long limit) {
    if (window <= 0) throw std::invalid_argument("window must be positive");
    if (limit < 0) throw std::invalid_argument("limit must not be negative");
    std::unordered_map<std::string, std::deque<std::pair<long long, long long>>> hist;
    std::unordered_map<std::string, long long> sums;
    std::vector<bool> out;
    out.reserve(events.size());
    for (const auto& ev : events) {
        long long ts = std::get<0>(ev);
        const std::string& client = std::get<1>(ev);
        long long cost = std::get<2>(ev);
        if (cost < 0) throw std::invalid_argument("cost must not be negative");
        auto& q = hist[client];
        long long& cur = sums[client];
        long long cutoff = ts - window;
        while (!q.empty() && q.front().first <= cutoff) {
            cur -= q.front().second;
            q.pop_front();
        }
        if (cur + cost <= limit) {
            q.emplace_back(ts, cost);
            cur += cost;
            out.push_back(true);
        } else {
            out.push_back(false);
        }
    }
    return out;
}
