std::vector<int> splitWeighted(long long totalCents, std::vector<int> weights) {
    if (totalCents < 0) throw std::invalid_argument("totalCents must not be negative");
    if (weights.empty()) throw std::invalid_argument("weights must not be empty");
    long long sumW = 0;
    for (int w : weights) {
        if (w < 0) throw std::invalid_argument("weight must not be negative");
        sumW += w;
    }
    if (sumW <= 0) throw std::invalid_argument("sum of weights must be positive");
    int n = static_cast<int>(weights.size());
    std::vector<int> out(n, 0);
    std::vector<std::pair<long long, int>> rems;
    rems.reserve(n);
    long long assigned = 0;
    for (int i = 0; i < n; ++i) {
        long long prod = totalCents * weights[i];
        long long share = prod / sumW;
        out[i] = static_cast<int>(share);
        assigned += share;
        rems.emplace_back(-(prod % sumW), i);
    }
    long long leftover = totalCents - assigned;
    std::sort(rems.begin(), rems.end());
    for (long long k = 0; k < leftover; ++k) {
        out[rems[static_cast<size_t>(k)].second] += 1;
    }
    return out;
}
