long long cheapestFlight(int n, std::vector<std::tuple<int, int, long long>> edges, int start, int target, int maxHops) {
    if (n < 1) throw std::invalid_argument("n must be >= 1");
    if (start < 0 || start >= n || target < 0 || target >= n) throw std::invalid_argument("bad endpoint");
    if (maxHops < 0) throw std::invalid_argument("maxHops must be >= 0");
    for (const auto& e : edges) {
        int u = std::get<0>(e), v = std::get<1>(e);
        long long w = std::get<2>(e);
        if (u < 0 || u >= n || v < 0 || v >= n || w < 0) throw std::invalid_argument("bad edge");
    }
    const long long INF = (1LL << 60);
    std::vector<long long> dp(n, INF);
    dp[start] = 0;
    long long best = dp[target];
    for (int hop = 0; hop < maxHops; ++hop) {
        std::vector<long long> ndp(n, INF);
        for (const auto& e : edges) {
            int u = std::get<0>(e), v = std::get<1>(e);
            long long w = std::get<2>(e);
            if (dp[u] < INF && dp[u] + w < ndp[v]) {
                ndp[v] = dp[u] + w;
            }
        }
        dp.swap(ndp);
        if (dp[target] < best) best = dp[target];
    }
    return best >= INF ? -1 : best;
}
