namespace {
std::vector<bool> parseCronField(const std::string& spec, int lo, int hi) {
    if (spec.empty()) throw std::invalid_argument("empty cron spec");
    std::vector<bool> ok(hi + 1, false);
    size_t start = 0;
    while (start <= spec.size()) {
        size_t comma = spec.find(',', start);
        std::string part = (comma == std::string::npos) ? spec.substr(start) : spec.substr(start, comma - start);
        if (part.empty()) throw std::invalid_argument("empty token");
        if (part == "*") {
            for (int v = lo; v <= hi; ++v) ok[v] = true;
        } else {
            size_t dash = part.find('-');
            auto parseInt = [&](const std::string& s) -> int {
                if (s.empty()) throw std::invalid_argument("empty number");
                for (char ch : s) {
                    if (ch < '0' || ch > '9') throw std::invalid_argument("non-digit");
                }
                int val = std::stoi(s);
                if (val < lo || val > hi) throw std::invalid_argument("out of range");
                return val;
            };
            if (dash == std::string::npos) {
                ok[parseInt(part)] = true;
            } else {
                int a = parseInt(part.substr(0, dash));
                int b = parseInt(part.substr(dash + 1));
                if (a > b) throw std::invalid_argument("reversed range");
                for (int v = a; v <= b; ++v) ok[v] = true;
            }
        }
        if (comma == std::string::npos) break;
        start = comma + 1;
    }
    return ok;
}
}

std::vector<int> matchingMinutes(std::string minuteSpec, std::string hourSpec, std::vector<int> timestamps) {
    auto mOk = parseCronField(minuteSpec, 0, 59);
    auto hOk = parseCronField(hourSpec, 0, 23);
    std::vector<int> out;
    for (int t : timestamps) {
        if (t < 0) throw std::invalid_argument("negative timestamp");
        int hh = (t / 60) % 24;
        int mm = t % 60;
        if (hOk[hh] && mOk[mm]) out.push_back(t);
    }
    return out;
}
