std::vector<int> rollingLowerMedian(std::vector<int> values, int capacity) {
    if (capacity < 1) throw std::invalid_argument("capacity must be >= 1");
    std::multiset<int> low, high;
    auto rebalance = [&]() {
        while (low.size() > high.size() + 1) {
            auto it = std::prev(low.end());
            high.insert(*it);
            low.erase(it);
        }
        while (low.size() < high.size()) {
            auto it = high.begin();
            low.insert(*it);
            high.erase(it);
        }
    };
    std::vector<int> out;
    out.reserve(values.size());
    for (size_t i = 0; i < values.size(); ++i) {
        int v = values[i];
        if (low.empty() || v <= *std::prev(low.end())) low.insert(v);
        else high.insert(v);
        rebalance();
        if (i >= static_cast<size_t>(capacity)) {
            int old = values[i - capacity];
            auto it = low.find(old);
            if (it != low.end()) low.erase(it);
            else high.erase(high.find(old));
            rebalance();
        }
        out.push_back(*std::prev(low.end()));
    }
    return out;
}
