function pickBestVersion(versions, rangeExpr) {
  if (typeof rangeExpr !== "string" || rangeExpr.trim() === "") throw new Error("empty range");
  const parseVer = (raw) => {
    if (typeof raw !== "string") throw new Error("version must be a string");
    const m = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/.exec(raw);
    if (!m) throw new Error("bad semver: " + raw);
    return [Number(m[1]), Number(m[2]), Number(m[3])];
  };
  const cmp = (a, b) => (a[0] - b[0]) || (a[1] - b[1]) || (a[2] - b[2]);
  const checks = [];
  for (const part of rangeExpr.split(",")) {
    const tok = part.trim();
    if (!tok) throw new Error("empty clause");
    if (tok.startsWith("^")) {
      const lo = parseVer(tok.slice(1));
      const hi = lo[0] > 0 ? [lo[0] + 1, 0, 0] : lo[1] > 0 ? [0, lo[1] + 1, 0] : [0, 0, lo[2] + 1];
      checks.push((v) => cmp(v, lo) >= 0 && cmp(v, hi) < 0);
    } else if (tok.startsWith(">=")) {
      const lo = parseVer(tok.slice(2));
      checks.push((v) => cmp(v, lo) >= 0);
    } else if (tok.startsWith("<")) {
      const hi = parseVer(tok.slice(1));
      checks.push((v) => cmp(v, hi) < 0);
    } else {
      const eq = parseVer(tok);
      checks.push((v) => cmp(v, eq) === 0);
    }
  }
  let best = null;
  let bestRaw = null;
  for (const raw of versions) {
    const v = parseVer(raw);
    if (checks.every((fn) => fn(v))) {
      if (!best || cmp(v, best) > 0) {
        best = v;
        bestRaw = raw;
      }
    }
  }
  return bestRaw;
}
