function flattenObject(input, separator = ".") {
  if (typeof separator !== "string" || separator === "") throw new Error("bad separator");
  const isPlain = (val) => val !== null && typeof val === "object" && !Array.isArray(val);
  if (!isPlain(input)) throw new Error("root must be a plain object");
  const out = {};
  const walk = (node, prefix, seen) => {
    if (seen.has(node)) throw new Error("cycle detected");
    seen.add(node);
    const keys = Object.keys(node).sort();
    for (const key of keys) {
      const path = prefix === "" ? key : prefix + separator + key;
      const val = node[key];
      if (isPlain(val)) {
        const subKeys = Object.keys(val);
        if (subKeys.length === 0) {
          out[path] = {};
        } else {
          walk(val, path, seen);
        }
      } else {
        out[path] = val;
      }
    }
    seen.delete(node);
  };
  walk(input, "", new Set());
  return out;
}
