function scheduleRetries(attempts, baseMs, maxMs, jitterOffsets) {
  if (!Number.isInteger(attempts) || attempts < 0) throw new Error("attempts must be >= 0");
  if (!Number.isInteger(baseMs) || baseMs < 0) throw new Error("baseMs must be >= 0");
  if (!Number.isInteger(maxMs) || maxMs < baseMs) throw new Error("maxMs must be >= baseMs");
  if (!Array.isArray(jitterOffsets) || jitterOffsets.length === 0) throw new Error("jitterOffsets required");
  const out = [];
  let elapsed = 0;
  for (let i = 0; i < attempts; i += 1) {
    const shift = Math.min(i, 30);
    const exp = baseMs * Math.pow(2, shift);
    const capped = exp > maxMs ? maxMs : exp;
    const jitter = jitterOffsets[i % jitterOffsets.length];
    if (!Number.isInteger(jitter)) throw new Error("jitter must be integer");
    let wait = capped + jitter;
    if (wait < 0) wait = 0;
    if (wait > maxMs) wait = maxMs;
    elapsed += wait;
    out.push({ attempt: i + 1, waitMs: wait, atMs: elapsed });
  }
  return out;
}
