function applyTransfers(initialBalances, transfers) {
  const balances = new Map();
  for (const [acct, amt] of Object.entries(initialBalances)) {
    if (!Number.isInteger(amt) || amt < 0) throw new Error("bad initial balance");
    balances.set(acct, amt);
  }
  const results = [];
  for (const tx of transfers) {
    const { id, from, to, amount } = tx;
    if (!Number.isInteger(amount) || amount <= 0) throw new Error("amount must be positive integer");
    if (from === to) {
      results.push({ id, status: "rejected", reason: "same_account" });
      continue;
    }
    const fromBal = balances.get(from) ?? 0;
    if (!balances.has(from) || !balances.has(to)) {
      results.push({ id, status: "rejected", reason: "unknown_account" });
      continue;
    }
    if (fromBal < amount) {
      results.push({ id, status: "rejected", reason: "insufficient_funds" });
      continue;
    }
    balances.set(from, fromBal - amount);
    balances.set(to, balances.get(to) + amount);
    results.push({ id, status: "applied", reason: null });
  }
  const finalBalances = {};
  for (const key of Array.from(balances.keys()).sort()) {
    finalBalances[key] = balances.get(key);
  }
  return { balances: finalBalances, results };
}
