function parseQuery(raw) {
  if (typeof raw !== "string") throw new Error("query must be a string");
  const text = raw.startsWith("?") ? raw.slice(1) : raw;
  const out = {};
  if (text === "") return out;
  const decodePart = (part) => {
    const plusFixed = part.replace(/\+/g, " ");
    try {
      return decodeURIComponent(plusFixed);
    } catch {
      throw new Error("malformed percent encoding");
    }
  };
  for (const pair of text.split("&")) {
    if (pair === "") continue;
    const eq = pair.indexOf("=");
    const rawKey = eq === -1 ? pair : pair.slice(0, eq);
    const rawVal = eq === -1 ? "" : pair.slice(eq + 1);
    const key = decodePart(rawKey);
    const val = decodePart(rawVal);
    if (Object.prototype.hasOwnProperty.call(out, key)) {
      if (Array.isArray(out[key])) out[key].push(val);
      else out[key] = [out[key], val];
    } else {
      out[key] = val;
    }
  }
  return out;
}
