function matchGlob(pattern: string, path: string): boolean {
  if (typeof pattern !== "string" || typeof path !== "string") {
    throw new Error("pattern and path must be strings");
  }
  const patSegs = pattern === "" ? [] : pattern.split("/");
  const pathSegs = path === "" ? [] : path.split("/");
  const matchSeg = (p: string, s: string): boolean => {
    let pi = 0;
    let si = 0;
    let starIdx = -1;
    let matchIdx = 0;
    while (si < s.length) {
      if (pi < p.length && (p[pi] === "?" || p[pi] === s[si])) {
        pi += 1;
        si += 1;
      } else if (pi < p.length && p[pi] === "*") {
        starIdx = pi;
        matchIdx = si;
        pi += 1;
      } else if (starIdx !== -1) {
        pi = starIdx + 1;
        matchIdx += 1;
        si = matchIdx;
      } else {
        return false;
      }
    }
    while (pi < p.length && p[pi] === "*") pi += 1;
    return pi === p.length;
  };
  const memo = new Map<string, boolean>();
  const dp = (i: number, j: number): boolean => {
    const key = i + ":" + j;
    const hit = memo.get(key);
    if (hit !== undefined) return hit;
    let res = false;
    if (i === patSegs.length && j === pathSegs.length) {
      res = true;
    } else if (i < patSegs.length && patSegs[i] === "**") {
      res = dp(i + 1, j) || (j < pathSegs.length && dp(i, j + 1));
    } else if (i < patSegs.length && j < pathSegs.length && matchSeg(patSegs[i], pathSegs[j])) {
      res = dp(i + 1, j + 1);
    }
    memo.set(key, res);
    return res;
  };
  return dp(0, 0);
}
