type Span = { start: number; end: number };

function findFreeSlots(dayStart: number, dayEnd: number, busy: Span[], minDuration: number): Span[] {
  if (!Number.isInteger(dayStart) || !Number.isInteger(dayEnd) || dayEnd < dayStart) {
    throw new Error("invalid day bounds");
  }
  if (!Number.isInteger(minDuration) || minDuration < 1) {
    throw new Error("minDuration must be >= 1");
  }
  const clipped: Span[] = [];
  for (const span of busy) {
    if (!Number.isInteger(span.start) || !Number.isInteger(span.end) || span.end < span.start) {
      throw new Error("invalid busy span");
    }
    const s = Math.max(dayStart, span.start);
    const e = Math.min(dayEnd, span.end);
    if (s < e) clipped.push({ start: s, end: e });
  }
  clipped.sort((a, b) => a.start - b.start || a.end - b.end);
  const merged: Span[] = [];
  for (const span of clipped) {
    const last = merged[merged.length - 1];
    if (last && span.start <= last.end) {
      if (span.end > last.end) last.end = span.end;
    } else {
      merged.push({ start: span.start, end: span.end });
    }
  }
  const free: Span[] = [];
  let cursor = dayStart;
  for (const span of merged) {
    if (span.start - cursor >= minDuration) {
      free.push({ start: cursor, end: span.start });
    }
    cursor = span.end;
  }
  if (dayEnd - cursor >= minDuration) {
    free.push({ start: cursor, end: dayEnd });
  }
  return free;
}
