type BucketEvent = { at: number; tokens: number };
type BucketDecision = { allowed: boolean; remaining: number };

function simulateTokenBucket(capacity: number, refillPerSec: number, events: BucketEvent[]): BucketDecision[] {
  if (!Number.isInteger(capacity) || capacity < 0) throw new Error("capacity must be >= 0");
  if (!Number.isInteger(refillPerSec) || refillPerSec < 0) throw new Error("refillPerSec must be >= 0");
  let tokens = capacity;
  let lastAt = 0;
  let initialized = false;
  const out: BucketDecision[] = [];
  for (const ev of events) {
    if (!Number.isInteger(ev.at) || ev.at < 0) throw new Error("timestamp must be >= 0");
    if (!Number.isInteger(ev.tokens) || ev.tokens < 0) throw new Error("tokens must be >= 0");
    if (!initialized) {
      lastAt = ev.at;
      initialized = true;
    } else {
      if (ev.at < lastAt) throw new Error("timestamps must be non-decreasing");
      const elapsed = ev.at - lastAt;
      tokens = Math.min(capacity, tokens + elapsed * refillPerSec);
      lastAt = ev.at;
    }
    if (tokens >= ev.tokens) {
      tokens -= ev.tokens;
      out.push({ allowed: true, remaining: tokens });
    } else {
      out.push({ allowed: false, remaining: tokens });
    }
  }
  return out;
}
