function renderTemplate(template: string, vars: Record<string, string | number | boolean>): string {
  if (typeof template !== "string") throw new Error("template must be a string");
  let out = "";
  let i = 0;
  while (i < template.length) {
    if (template[i] === "{") {
      if (template[i + 1] === "{") {
        out += "{";
        i += 2;
        continue;
      }
      const close = template.indexOf("}", i + 1);
      if (close === -1) throw new Error("unclosed placeholder");
      const expr = template.slice(i + 1, close);
      const colon = expr.indexOf(":");
      const key = colon === -1 ? expr : expr.slice(0, colon);
      const fallback = colon === -1 ? null : expr.slice(colon + 1);
      if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) throw new Error("bad placeholder key: " + key);
      if (Object.prototype.hasOwnProperty.call(vars, key)) {
        out += String(vars[key]);
      } else if (fallback !== null) {
        out += fallback;
      } else {
        throw new Error("missing key: " + key);
      }
      i = close + 1;
    } else if (template[i] === "}") {
      if (template[i + 1] === "}") {
        out += "}";
        i += 2;
      } else {
        throw new Error("stray closing brace");
      }
    } else {
      out += template[i];
      i += 1;
    }
  }
  return out;
}
