function batchWaves(deps: Record<string, string[]>): string[][] {
  const nodes = Object.keys(deps);
  const indeg = new Map<string, number>();
  const adj = new Map<string, string[]>();
  for (const node of nodes) {
    indeg.set(node, 0);
    adj.set(node, []);
  }
  for (const node of nodes) {
    const seenDep = new Set<string>();
    for (const dep of deps[node]) {
      if (!indeg.has(dep)) throw new Error("unknown dependency: " + dep);
      if (seenDep.has(dep)) continue;
      seenDep.add(dep);
      adj.get(dep)!.push(node);
      indeg.set(node, indeg.get(node)! + 1);
    }
  }
  let ready = nodes.filter((n) => indeg.get(n) === 0).sort();
  const waves: string[][] = [];
  let done = 0;
  while (ready.length > 0) {
    waves.push(ready);
    done += ready.length;
    const nextReady: string[] = [];
    for (const cur of ready) {
      for (const nxt of adj.get(cur)!) {
        const d = indeg.get(nxt)! - 1;
        indeg.set(nxt, d);
        if (d === 0) nextReady.push(nxt);
      }
    }
    nextReady.sort();
    ready = nextReady;
  }
  if (done !== nodes.length) throw new Error("cycle detected");
  return waves;
}
