def build_roster(days, workers, blocked, max_streak):
    if isinstance(days, bool) or not isinstance(days, int) or days < 0:
        raise ValueError("days must be >= 0")
    if isinstance(max_streak, bool) or not isinstance(max_streak, int) or max_streak < 1:
        raise ValueError("max_streak must be >= 1")
    counts = {w: 0 for w in workers}
    last_worker = None
    streak = 0
    schedule = []
    for day in range(days):
        ban = set(blocked.get(day, ()))
        best_key = None
        best_worker = None
        for w in workers:
            if w in ban:
                continue
            cur = streak if w == last_worker else 0
            if cur + 1 > max_streak:
                continue
            key = (counts[w], cur, w)
            if best_key is None or key < best_key:
                best_key = key
                best_worker = w
        if best_worker is None:
            raise ValueError("no eligible worker on day " + str(day))
        counts[best_worker] += 1
        streak = (streak + 1) if best_worker == last_worker else 1
        last_worker = best_worker
        schedule.append(best_worker)
    return schedule
