def reconcile_payments(invoices, payments):
    due = {}
    order = []
    for iid, amt, day in invoices:
        if isinstance(amt, bool) or not isinstance(amt, int) or amt < 0:
            raise ValueError("due_cents must be non-negative")
        if iid in due:
            raise ValueError("duplicate invoice: " + str(iid))
        due[iid] = amt
        order.append((day, iid))
    order.sort()
    unapplied = 0
    for _pid, amt, _day, target in payments:
        if isinstance(amt, bool) or not isinstance(amt, int) or amt < 0:
            raise ValueError("payment cents must be non-negative")
        rem = amt
        if target is not None:
            if target not in due:
                unapplied += rem
                continue
            take = rem if rem < due[target] else due[target]
            due[target] -= take
            unapplied += rem - take
        else:
            for _d, iid in order:
                if rem == 0:
                    break
                avail = due[iid]
                if avail > 0:
                    take = rem if rem < avail else avail
                    due[iid] -= take
                    rem -= take
            unapplied += rem
    return (due, unapplied)
