def compute_tax(income_cents, brackets):
    if isinstance(income_cents, bool) or not isinstance(income_cents, int) or income_cents < 0:
        raise ValueError("income must be non-negative")
    if not brackets:
        raise ValueError("brackets must not be empty")
    finite = []
    unbounded = []
    seen = set()
    for limit, rate in brackets:
        if rate < 0:
            raise ValueError("rate must be non-negative")
        if limit is None:
            unbounded.append(rate)
        else:
            if limit < 0 or limit in seen:
                raise ValueError("invalid bracket limit")
            seen.add(limit)
            finite.append((limit, rate))
    if len(unbounded) > 1:
        raise ValueError("at most one unbounded bracket")
    finite.sort()
    prev = 0
    rem = income_cents
    points = 0
    for limit, rate in finite:
        cap = limit - prev
        take = rem if rem < cap else cap
        points += take * rate
        rem -= take
        prev = limit
        if rem == 0:
            break
    if rem > 0:
        if not unbounded:
            raise ValueError("income exceeds highest bracket")
        points += rem * unbounded[0]
    tax = (2 * points + 100) // 200
    bps = 0 if income_cents == 0 else (2 * tax * 10000 + income_cents) // (2 * income_cents)
    return (tax, bps)
