"""Profile store backed by Cache."""

from .cache import Cache


class ProfileService:
    def __init__(self, initial_users, capacity=2):
        self._db = {uid: dict(data) for uid, data in initial_users.items()}
        self._cache = Cache(capacity)
        self.db_reads = 0

    @staticmethod
    def _key(user_id):
        return "user:" + user_id

    def get_profile(self, user_id):
        key = self._key(user_id)
        cached = self._cache.get(key)
        if cached is not None:
            return dict(cached)
        if user_id not in self._db:
            return None
        self.db_reads += 1
        rec = dict(self._db[user_id])
        self._cache.set(key, rec)
        return dict(rec)

    def update_role(self, user_id, new_role):
        if user_id not in self._db:
            raise KeyError(user_id)
        self._db[user_id]["role"] = new_role
        self._cache.delete("role:" + user_id)

