"""Largest-remainder integer allocation."""


def allocate_cents(total_cents, weights):
    """Split total_cents proportionally across weights using Hamilton largest-remainder."""
    if total_cents < 0:
        raise ValueError("total_cents must be >= 0")
    if not weights:
        raise ValueError("weights must not be empty")
    for w in weights:
        if w < 0:
            raise ValueError("weights must be >= 0")
    total_w = sum(weights)
    if total_w <= 0:
        raise ValueError("sum of weights must be > 0")
    shares = []
    rems = []
    for idx, w in enumerate(weights):
        num = total_cents * w
        shares.append(num // total_w)
        rems.append((-(num % total_w), idx))
    leftover = total_cents - sum(shares)
    for i in range(leftover):
        shares[-(i + 1)] += 1
    return shares

