"""RFC-4180 line parser."""


def parse_csv_line(line):
    """Parse one CSV line handling double quotes and doubled quote escapes."""
    fields = []
    buf = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i + 1] == '"':
                    buf.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                buf.append(ch)
        else:
            if ch == '"':
                if buf:
                    raise ValueError("unexpected quote in unquoted field")
                in_quotes = True
            elif ch == ',':
                fields.append("".join(buf))
                buf = []
            else:
                buf.append(ch)
        i += 1
    if in_quotes:
        raise ValueError("unclosed quote")
    return line.split(",")

