"""Three-state circuit breaker."""


class CircuitBreaker:
    def __init__(self, fail_threshold, cooldown):
        if fail_threshold < 1 or cooldown < 0:
            raise ValueError("invalid breaker config")
        self.fail_threshold = fail_threshold
        self.cooldown = cooldown
        self.state = "CLOSED"
        self.failures = 0
        self.opened_at = None

    def allow_request(self, now):
        if self.state == "CLOSED":
            return True
        if self.state == "OPEN":
            if now < self.opened_at + self.cooldown:
                self.state = "HALF_OPEN"
                return True
            return False
        # HALF_OPEN allows probe
        return True

    def record_success(self):
        self.failures = 0
        self.state = "CLOSED"
        self.opened_at = None

    def record_failure(self, now):
        if self.state == "HALF_OPEN":
            self.failures = 0
            return
        self.failures += 1
        if self.failures >= self.fail_threshold:
            self.state = "OPEN"
            self.opened_at = now

