"""RPC call wrapper using CircuitBreaker."""

from .breaker import CircuitBreaker


class RpcClient:
    def __init__(self, fail_threshold, cooldown):
        self.breaker = CircuitBreaker(fail_threshold, cooldown)

    def call(self, now, fn):
        if not self.breaker.allow_request(now):
            return ("BLOCKED", None)
        try:
            res = fn()
        except RuntimeError:
            self.breaker.record_failure(now)
            return ("ERR", None)
        self.breaker.record_success()
        return ("OK", res)

