"""Path pattern matching."""


def match_path(pattern, path):
    """Match slash-separated path where * matches one segment and ** matches 0+ segments."""
    pat_segs = [s for s in pattern.strip("/").split("/") if s]
    path_segs = [s for s in path.strip("/").split("/") if s]
    memo = {}

    def dp(i, j):
        key = (i, j)
        if key in memo:
            return memo[key]
        if i == len(pat_segs) and j == len(path_segs):
            res = True
        elif i < len(pat_segs) and pat_segs[i] == "**" and j < len(path_segs):
            res = dp(i + 1, j + 1)
        elif i < len(pat_segs) and j < len(path_segs) and (pat_segs[i] == "*" or pat_segs[i] == path_segs[j]):
            res = dp(i + 1, j + 1)
        else:
            res = False
        memo[key] = res
        return res

    return dp(0, 0)

