"""Runtime interval clipping and merging."""


def active_minutes(sessions, win_start, win_end):
    """Return total covered minutes within [win_start, win_end)."""
    if win_end < win_start:
        raise ValueError("invalid window")
    clipped = []
    for s, e in sessions:
        if e < s:
            raise ValueError("invalid session")
        if s >= win_start and e <= win_end and s < e:
            clipped.append((s, e))
    clipped.sort()
    merged = []
    for s, e in clipped:
        if merged and s <= merged[-1][1]:
            if e > merged[-1][1]:
                merged[-1] = (merged[-1][0], e)
        else:
            merged.append((s, e))
    return sum(e - s for s, e in merged)

