def audit_breaker(events, fail_threshold, cooldown):
    if fail_threshold < 1 or cooldown < 0:
        raise ValueError("invalid breaker configuration")
    state = "CLOSED"
    fails = 0
    opened_at = None
    last_ts = None
    counts = {"OK": 0, "ERR": 0, "BLOCKED": 0}
    transitions = []
    for ts, outcome in events:
        if last_ts is not None and ts < last_ts:
            raise ValueError("timestamps must be non-decreasing")
        last_ts = ts
        if outcome not in ("OK", "ERR"):
            raise ValueError("invalid outcome: " + str(outcome))
        if state == "OPEN":
            if ts >= opened_at + cooldown:
                state = "HALF_OPEN"
                transitions.append((ts, "HALF_OPEN"))
            else:
                counts["BLOCKED"] += 1
                continue
        if outcome == "OK":
            counts["OK"] += 1
            if state != "CLOSED":
                state = "CLOSED"
                transitions.append((ts, "CLOSED"))
            fails = 0
            opened_at = None
        else:
            counts["ERR"] += 1
            if state == "HALF_OPEN":
                state = "OPEN"
                opened_at = ts
                fails = fail_threshold
                transitions.append((ts, "OPEN"))
            else:
                fails += 1
                if fails >= fail_threshold:
                    state = "OPEN"
                    opened_at = ts
                    transitions.append((ts, "OPEN"))
    return {"state": state, "counts": counts, "transitions": transitions}
