def rebuild_plan(deps, changed):
    import heapq
    for target, reqs in deps.items():
        for req in reqs:
            if req not in deps:
                raise ValueError("unknown dependency: " + str(req))
    for item in changed:
        if item not in deps:
            raise ValueError("unknown changed target: " + str(item))
    state = {}
    for start in deps:
        if state.get(start, 0) != 0:
            continue
        stack = [(start, 0)]
        state[start] = 1
        while stack:
            u, idx = stack[-1]
            reqs = deps[u]
            if idx < len(reqs):
                stack[-1] = (u, idx + 1)
                v = reqs[idx]
                st = state.get(v, 0)
                if st == 1:
                    raise ValueError("dependency cycle detected")
                if st == 0:
                    state[v] = 1
                    stack.append((v, 0))
            else:
                state[u] = 2
                stack.pop()
    rev = {k: [] for k in deps}
    for u, reqs in deps.items():
        for req in set(reqs):
            rev[req].append(u)
    dirty = set(changed)
    queue = list(dirty)
    while queue:
        cur = queue.pop()
        for dep in rev[cur]:
            if dep not in dirty:
                dirty.add(dep)
                queue.append(dep)
    indeg = {u: 0 for u in dirty}
    for u in dirty:
        for req in set(deps[u]):
            if req in dirty:
                indeg[u] += 1
    heap = [u for u, d in indeg.items() if d == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for nxt in rev[u]:
            if nxt in dirty:
                indeg[nxt] -= 1
                if indeg[nxt] == 0:
                    heapq.heappush(heap, nxt)
    return order
