def check_quotas(events, window, limit):
    from collections import deque
    if window <= 0 or limit < 0:
        raise ValueError("invalid window or limit")
    hist = {}
    sums = {}
    last_ts = None
    out = []
    for ts, key, units in events:
        if last_ts is not None and ts < last_ts:
            raise ValueError("timestamps must be non-decreasing")
        last_ts = ts
        if units < 0:
            raise ValueError("units must be non-negative")
        q = hist.get(key)
        if q is None:
            q = deque()
            hist[key] = q
            sums[key] = 0
        cutoff = ts - window
        cur = sums[key]
        while q and q[0][0] <= cutoff:
            cur -= q.popleft()[1]
        if cur + units <= limit:
            q.append((ts, units))
            cur += units
            sums[key] = cur
            out.append((True, limit - cur))
        else:
            sums[key] = cur
            out.append((False, limit - cur))
    return out
