def build_config_tree(entries):
    root = {}
    for key, value in entries:
        if not isinstance(key, str) or key == "":
            raise ValueError("invalid key")
        if isinstance(value, dict):
            raise ValueError("value cannot be a dict")
        parts = key.split(".")
        if any(p == "" for p in parts):
            raise ValueError("empty segment in key: " + key)
        node = root
        for seg in parts[:-1]:
            if seg not in node:
                node[seg] = {}
            elif not isinstance(node[seg], dict):
                raise ValueError("scalar/branch conflict at: " + seg)
            node = node[seg]
        leaf = parts[-1]
        if leaf in node and isinstance(node[leaf], dict):
            raise ValueError("branch/scalar conflict at: " + leaf)
        node[leaf] = value
    return root
