def compact_kv_log(records, now):
    latest = {}
    for rec in records:
        if not isinstance(rec, (tuple, list)) or not rec:
            raise ValueError("invalid record")
        op = rec[0]
        if op == "SET":
            if len(rec) != 5:
                raise ValueError("invalid SET record")
            _op, key, val, ttl, ts = rec
            if ttl is not None and ttl < 0:
                raise ValueError("negative ttl")
            latest[key] = ("SET", val, ttl, ts)
        elif op == "DEL":
            if len(rec) != 3:
                raise ValueError("invalid DEL record")
            _op, key, ts = rec
            latest[key] = ("DEL", None, None, ts)
        else:
            raise ValueError("unknown op: " + str(op))
    out = []
    for key in sorted(latest):
        op, val, ttl, ts = latest[key]
        if op == "SET":
            if ttl is None or ts + ttl > now:
                out.append((key, val))
    return out
