std::vector<std::string> assignLockers(int sCap, int mCap, int lCap,
                                       std::vector<std::tuple<std::string, std::string, std::string>> commands) {
    if (sCap < 0 || mCap < 0 || lCap < 0) throw std::invalid_argument("negative capacity");
    int caps[3] = {sCap, mCap, lCap};
    int nextNew[3] = {1, 1, 1};
    const char* tNames[3] = {"S", "M", "L"};
    std::priority_queue<int, std::vector<int>, std::greater<int>> freed[3];
    std::unordered_map<std::string, std::pair<int, int>> placed;
    std::vector<std::string> out;
    out.reserve(commands.size());
    for (const auto& cmd : commands) {
        const std::string& op = std::get<0>(cmd);
        const std::string& pid = std::get<1>(cmd);
        const std::string& sz = std::get<2>(cmd);
        if (op == "IN") {
            int startTier = -1;
            if (sz == "S") startTier = 0;
            else if (sz == "M") startTier = 1;
            else if (sz == "L") startTier = 2;
            else throw std::invalid_argument("bad size");
            int chosenT = -1, chosenN = -1;
            for (int t = startTier; t < 3; ++t) {
                if (!freed[t].empty()) {
                    chosenT = t;
                    chosenN = freed[t].top();
                    freed[t].pop();
                    break;
                }
                if (nextNew[t] <= caps[t]) {
                    chosenT = t;
                    chosenN = nextNew[t]++;
                    break;
                }
            }
            if (chosenT == -1) {
                out.push_back("FULL " + pid);
            } else {
                placed[pid] = {chosenT, chosenN};
                out.push_back("OK " + pid + " " + tNames[chosenT] + std::to_string(chosenN));
            }
        } else if (op == "OUT") {
            auto it = placed.find(pid);
            if (it == placed.end()) {
                out.push_back("MISS " + pid);
            } else {
                int t = it->second.first;
                int num = it->second.second;
                placed.erase(it);
                freed[t].push(num);
                out.push_back("OUT " + pid + " " + tNames[t] + std::to_string(num));
            }
        } else {
            throw std::invalid_argument("bad op");
        }
    }
    return out;
}
