long long computeUptime(long long winStart, long long winEnd, std::vector<std::pair<long long, long long>> blackouts) {
    if (winEnd < winStart) throw std::invalid_argument("invalid window");
    std::vector<std::pair<long long, long long>> spans;
    spans.reserve(blackouts.size());
    for (const auto& p : blackouts) {
        if (p.second < p.first) throw std::invalid_argument("invalid blackout");
        long long a = std::max(winStart, p.first);
        long long b = std::min(winEnd, p.second);
        if (a < b) spans.emplace_back(a, b);
    }
    std::sort(spans.begin(), spans.end());
    long long down = 0;
    long long curS = 0, curE = -1;
    bool hasCur = false;
    for (const auto& sp : spans) {
        if (!hasCur) {
            curS = sp.first;
            curE = sp.second;
            hasCur = true;
        } else if (sp.first <= curE) {
            if (sp.second > curE) curE = sp.second;
        } else {
            down += curE - curS;
            curS = sp.first;
            curE = sp.second;
        }
    }
    if (hasCur) down += curE - curS;
    return (winEnd - winStart) - down;
}
