std::vector<std::string> buildRoster(int days, std::vector<std::string> workers,
                                     std::vector<std::vector<std::string>> blocked, int maxStreak) {
    if (days < 0 || maxStreak < 1) throw std::invalid_argument("invalid roster params");
    if (days == 0) return {};
    std::unordered_map<std::string, int> counts;
    for (const auto& w : workers) counts[w] = 0;
    std::string lastW;
    bool hasLast = false;
    int streak = 0;
    std::vector<std::string> out;
    out.reserve(days);
    for (int d = 0; d < days; ++d) {
        std::unordered_set<std::string> ban;
        if (d < static_cast<int>(blocked.size())) {
            for (const auto& b : blocked[d]) ban.insert(b);
        }
        bool found = false;
        std::tuple<int, int, std::string> bestKey;
        std::string bestW;
        for (const auto& w : workers) {
            if (ban.count(w)) continue;
            int cur = (hasLast && w == lastW) ? streak : 0;
            if (cur + 1 > maxStreak) continue;
            auto key = std::make_tuple(counts[w], cur, w);
            if (!found || key < bestKey) {
                found = true;
                bestKey = key;
                bestW = w;
            }
        }
        if (!found) return {};
        counts[bestW] += 1;
        streak = (hasLast && bestW == lastW) ? (streak + 1) : 1;
        lastW = bestW;
        hasLast = true;
        out.push_back(bestW);
    }
    return out;
}
