long long maxScheduleValue(std::vector<std::tuple<long long, long long, long long>> jobs, long long gap) {
    if (gap < 0) throw std::invalid_argument("negative gap");
    struct Job { long long e, s, w; };
    std::vector<Job> items;
    items.reserve(jobs.size());
    for (const auto& j : jobs) {
        long long s = std::get<0>(j), e = std::get<1>(j), w = std::get<2>(j);
        if (e <= s || w < 0) throw std::invalid_argument("invalid job");
        items.push_back({e, s, w});
    }
    if (items.empty()) return 0;
    std::sort(items.begin(), items.end(), [](const Job& a, const Job& b) {
        if (a.e != b.e) return a.e < b.e;
        return a.s < b.s;
    });
    size_t n = items.size();
    std::vector<long long> ends(n);
    for (size_t i = 0; i < n; ++i) ends[i] = items[i].e;
    std::vector<long long> dp(n + 1, 0);
    for (size_t i = 1; i <= n; ++i) {
        long long limit = items[i - 1].s - gap;
        auto it = std::upper_bound(ends.begin(), ends.begin() + (i - 1), limit);
        size_t prevIdx = static_cast<size_t>(it - ends.begin());
        long long take = dp[prevIdx] + items[i - 1].w;
        dp[i] = std::max(dp[i - 1], take);
    }
    return dp[n];
}
