std::vector<long long> waterfillAllocate(long long capacity, std::vector<long long> demands) {
    if (capacity < 0) throw std::invalid_argument("negative capacity");
    size_t n = demands.size();
    for (long long d : demands) {
        if (d < 0) throw std::invalid_argument("negative demand");
    }
    std::vector<long long> alloc(n, 0);
    if (n == 0 || capacity == 0) return alloc;
    std::vector<size_t> order(n);
    std::iota(order.begin(), order.end(), 0);
    std::sort(order.begin(), order.end(), [&](size_t a, size_t b) {
        if (demands[a] != demands[b]) return demands[a] < demands[b];
        return a < b;
    });
    long long rem = capacity;
    long long level = 0;
    size_t idx = 0;
    while (idx < n && rem > 0) {
        long long d = demands[order[idx]];
        long long active = static_cast<long long>(n - idx);
        long long delta = d - level;
        if (delta == 0) {
            alloc[order[idx]] = d;
            ++idx;
            continue;
        }
        // Check delta * active <= rem safely without overflow
        if (delta <= rem / active) {
            rem -= delta * active;
            level = d;
            while (idx < n && demands[order[idx]] == d) {
                alloc[order[idx]] = d;
                ++idx;
            }
        } else {
            long long q = rem / active;
            long long r = rem % active;
            long long base = level + q;
            std::vector<size_t> rest(order.begin() + idx, order.end());
            std::sort(rest.begin(), rest.end());
            for (size_t pos = 0; pos < rest.size(); ++pos) {
                alloc[rest[pos]] = base + (static_cast<long long>(pos) < r ? 1 : 0);
            }
            rem = 0;
            break;
        }
    }
    return alloc;
}
