std::vector<int> dirtyTargets(int n, std::vector<std::pair<int, int>> deps, std::vector<int> seeds) {
    if (n < 0) throw std::invalid_argument("negative n");
    std::vector<std::vector<int>> rev(n);
    for (const auto& e : deps) {
        if (e.first < 0 || e.first >= n || e.second < 0 || e.second >= n) {
            throw std::invalid_argument("node out of range");
        }
        rev[e.second].push_back(e.first);
    }
    std::vector<bool> vis(n, false);
    std::queue<int> q;
    for (int s : seeds) {
        if (s < 0 || s >= n) throw std::invalid_argument("seed out of range");
        if (!vis[s]) {
            vis[s] = true;
            q.push(s);
        }
    }
    while (!q.empty()) {
        int cur = q.front();
        q.pop();
        for (int nxt : rev[cur]) {
            if (!vis[nxt]) {
                vis[nxt] = true;
                q.push(nxt);
            }
        }
    }
    std::vector<int> out;
    for (int i = 0; i < n; ++i) {
        if (vis[i]) out.push_back(i);
    }
    return out;
}
