function simulateBreaker(events, failThreshold, cooldown) {
  if (!Number.isInteger(failThreshold) || failThreshold < 1) throw new Error("bad failThreshold");
  if (!Number.isInteger(cooldown) || cooldown < 0) throw new Error("bad cooldown");
  let state = "CLOSED";
  let fails = 0;
  let openedAt = null;
  let lastTs = null;
  const counts = { OK: 0, ERR: 0, BLOCKED: 0 };
  const transitions = [];
  for (const ev of events) {
    const { ts, outcome } = ev;
    if (!Number.isInteger(ts)) throw new Error("ts must be integer");
    if (lastTs !== null && ts < lastTs) throw new Error("non-monotonic ts");
    lastTs = ts;
    if (outcome !== "OK" && outcome !== "ERR") throw new Error("bad outcome");
    if (state === "OPEN") {
      if (ts >= openedAt + cooldown) {
        state = "HALF_OPEN";
        transitions.push({ ts, state: "HALF_OPEN" });
      } else {
        counts.BLOCKED += 1;
        continue;
      }
    }
    if (outcome === "OK") {
      counts.OK += 1;
      if (state !== "CLOSED") {
        state = "CLOSED";
        transitions.push({ ts, state: "CLOSED" });
      }
      fails = 0;
      openedAt = null;
    } else {
      counts.ERR += 1;
      if (state === "HALF_OPEN") {
        state = "OPEN";
        openedAt = ts;
        fails = failThreshold;
        transitions.push({ ts, state: "OPEN" });
      } else {
        fails += 1;
        if (fails >= failThreshold) {
          state = "OPEN";
          openedAt = ts;
          transitions.push({ ts, state: "OPEN" });
        }
      }
    }
  }
  return { state, counts, transitions };
}
