function reconcilePayments(invoices, payments) {
  const due = new Map();
  const order = [];
  for (const inv of invoices) {
    if (!Number.isInteger(inv.dueCents) || inv.dueCents < 0) throw new Error("bad dueCents");
    if (due.has(inv.id)) throw new Error("duplicate invoice");
    due.set(inv.id, inv.dueCents);
    order.push({ id: inv.id, dueDay: inv.dueDay });
  }
  order.sort((a, b) => (a.dueDay - b.dueDay) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  let unappliedCents = 0;
  for (const pay of payments) {
    if (!Number.isInteger(pay.cents) || pay.cents < 0) throw new Error("bad payment cents");
    let rem = pay.cents;
    if (pay.targetId !== null && pay.targetId !== undefined) {
      if (!due.has(pay.targetId)) {
        unappliedCents += rem;
        continue;
      }
      const cur = due.get(pay.targetId);
      const take = rem < cur ? rem : cur;
      due.set(pay.targetId, cur - take);
      unappliedCents += rem - take;
    } else {
      for (const item of order) {
        if (rem === 0) break;
        const cur = due.get(item.id);
        if (cur > 0) {
          const take = rem < cur ? rem : cur;
          due.set(item.id, cur - take);
          rem -= take;
        }
      }
      unappliedCents += rem;
    }
  }
  const remaining = {};
  for (const id of Array.from(due.keys()).sort()) {
    remaining[id] = due.get(id);
  }
  return { remaining, unappliedCents };
}
