function parseCsv(text) {
  if (typeof text !== "string") throw new Error("text must be a string");
  if (text === "") return [];
  const rows = [];
  let row = [];
  let field = "";
  let inQuotes = false;
  let fieldStarted = false;
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === "\"") {
        if (text[i + 1] === "\"") {
          field += "\"";
          i += 1;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
    } else {
      if (ch === "\"") {
        if (fieldStarted) throw new Error("quote in unquoted field");
        inQuotes = true;
        fieldStarted = true;
      } else if (ch === ",") {
        row.push(field);
        field = "";
        fieldStarted = false;
      } else if (ch === "\r" && text[i + 1] === "\n") {
        row.push(field);
        rows.push(row);
        row = [];
        field = "";
        fieldStarted = false;
        i += 1;
      } else if (ch === "\n") {
        row.push(field);
        rows.push(row);
        row = [];
        field = "";
        fieldStarted = false;
      } else {
        field += ch;
        fieldStarted = true;
      }
    }
  }
  if (inQuotes) throw new Error("unclosed quote");
  if (fieldStarted || row.length > 0) {
    row.push(field);
    rows.push(row);
  }
  return rows;
}
