class LruTtlCache {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new Error("bad capacity");
    this.capacity = capacity;
    this.map = new Map();
  }
  _purgeExpired(now) {
    for (const [k, entry] of this.map) {
      if (entry.expiresAt !== null && entry.expiresAt <= now) {
        this.map.delete(k);
      }
    }
  }
  set(key, value, now, ttl = null) {
    if (ttl !== null && (!Number.isInteger(ttl) || ttl < 0)) throw new Error("bad ttl");
    this._purgeExpired(now);
    if (this.map.has(key)) this.map.delete(key);
    else if (this.map.size >= this.capacity) {
      const oldest = this.map.keys().next().value;
      this.map.delete(oldest);
    }
    const expiresAt = ttl === null ? null : now + ttl;
    if (expiresAt !== null && expiresAt <= now) return;
    this.map.set(key, { value, expiresAt });
  }
  get(key, now) {
    this._purgeExpired(now);
    if (!this.map.has(key)) return undefined;
    const entry = this.map.get(key);
    this.map.delete(key);
    this.map.set(key, entry);
    return entry.value;
  }
  keys(now) {
    this._purgeExpired(now);
    return Array.from(this.map.keys());
  }
}

function runCacheOps(capacity, ops) {
  const cache = new LruTtlCache(capacity);
  const out = [];
  for (const op of ops) {
    if (op[0] === "SET") {
      cache.set(op[1], op[2], op[3], op[4] ?? null);
    } else if (op[0] === "GET") {
      const v = cache.get(op[1], op[2]);
      out.push(v === undefined ? null : v);
    } else if (op[0] === "KEYS") {
      out.push(cache.keys(op[1]));
    } else {
      throw new Error("bad op");
    }
  }
  return out;
}
