function splitWeighted(totalCents, participants) {
  if (!Number.isInteger(totalCents) || totalCents < 0) throw new Error("bad totalCents");
  if (!Array.isArray(participants) || participants.length === 0) throw new Error("participants required");
  let sumW = 0;
  const seen = new Set();
  for (const p of participants) {
    if (typeof p.name !== "string" || seen.has(p.name)) throw new Error("bad participant name");
    if (!Number.isInteger(p.weight) || p.weight < 0) throw new Error("bad weight");
    seen.add(p.name);
    sumW += p.weight;
  }
  if (sumW <= 0) throw new Error("sum of weights must be > 0");
  const totalBig = BigInt(totalCents);
  const sumBig = BigInt(sumW);
  const shares = [];
  const rems = [];
  let assigned = 0;
  for (let i = 0; i < participants.length; i += 1) {
    const prod = totalBig * BigInt(participants[i].weight);
    const share = Number(prod / sumBig);
    const rem = prod % sumBig;
    shares.push(share);
    assigned += share;
    rems.push({ rem, idx: i });
  }
  const leftover = totalCents - assigned;
  rems.sort((a, b) => (a.rem > b.rem ? -1 : a.rem < b.rem ? 1 : a.idx - b.idx));
  for (let k = 0; k < leftover; k += 1) {
    shares[rems[k].idx] += 1;
  }
  const out = {};
  for (let i = 0; i < participants.length; i += 1) {
    out[participants[i].name] = shares[i];
  }
  return out;
}
