function resolvePosix(cwd, target) {
  if (typeof cwd !== "string" || typeof target !== "string") throw new Error("paths must be strings");
  if (!cwd.startsWith("/")) throw new Error("cwd must start with /");
  const combined = target.startsWith("/") ? target : cwd.replace(/\/+$/, "") + "/" + target;
  const stack = [];
  for (const seg of combined.split("/")) {
    if (seg === "" || seg === ".") continue;
    if (seg === "..") {
      if (stack.length > 0) stack.pop();
    } else {
      stack.push(seg);
    }
  }
  return "/" + stack.join("/");
}
