function buildRoster(
  days: number,
  workers: string[],
  blocked: Record<number, string[]>,
  maxStreak: number
): string[] {
  if (!Number.isInteger(days) || days < 0) throw new Error("days must be >= 0");
  if (!Number.isInteger(maxStreak) || maxStreak < 1) throw new Error("maxStreak must be >= 1");
  const counts = new Map<string, number>();
  for (const w of workers) counts.set(w, 0);
  let lastWorker: string | null = null;
  let streak = 0;
  const schedule: string[] = [];
  for (let d = 0; d < days; d += 1) {
    const ban = new Set<string>(blocked[d] ?? []);
    let best: { count: number; cur: number; name: string } | null = null;
    for (const w of workers) {
      if (ban.has(w)) continue;
      const cur = w === lastWorker ? streak : 0;
      if (cur + 1 > maxStreak) continue;
      const count = counts.get(w) ?? 0;
      if (
        best === null ||
        count < best.count ||
        (count === best.count && (cur < best.cur || (cur === best.cur && w < best.name)))
      ) {
        best = { count, cur, name: w };
      }
    }
    if (best === null) throw new Error("no eligible worker on day " + d);
    counts.set(best.name, best.count + 1);
    streak = best.name === lastWorker ? streak + 1 : 1;
    lastWorker = best.name;
    schedule.push(best.name);
  }
  return schedule;
}
