  const clone = (v: JsonVal): JsonVal => {
    if (Array.isArray(v)) return v.map(clone);
    if (isPlain(v)) {
      const out: Record<string, JsonVal> = {};
      for (const k of Object.keys(v)) out[k] = clone(v[k]);
      return out;
    }
    return v;
  };
  if (!isPlain(base) || !isPlain(override)) throw new Error("inputs must be plain objects");
  const result = clone(base) as Record<string, JsonVal>;
  for (const key of Object.keys(override)) {
    const ov = override[key];
    const bv = result[key];
    if (isPlain(ov) && isPlain(bv)) {
      result[key] = mergeConfigs(bv, ov);
    } else {
      result[key] = clone(ov);
    }
  }
  return result;
