type QuotaEvent = { ts: number; client: string; cost: number };

function evaluateQuotas(events: QuotaEvent[], window: number, limit: number): Array<{ allowed: boolean; remaining: number }> {
  if (!Number.isInteger(window) || window <= 0) throw new Error("window must be > 0");
  if (!Number.isInteger(limit) || limit < 0) throw new Error("limit must be >= 0");
  const hist = new Map<string, { items: Array<{ ts: number; cost: number }>; head: number; sum: number }>();
  let lastTs: number | null = null;
  const out: Array<{ allowed: boolean; remaining: number }> = [];
  for (const ev of events) {
    if (!Number.isInteger(ev.ts) || !Number.isInteger(ev.cost) || ev.cost < 0) {
      throw new Error("invalid event");
    }
    if (lastTs !== null && ev.ts < lastTs) throw new Error("timestamps must be non-decreasing");
    lastTs = ev.ts;
    let rec = hist.get(ev.client);
    if (!rec) {
      rec = { items: [], head: 0, sum: 0 };
      hist.set(ev.client, rec);
    }
    const cutoff = ev.ts - window;
    while (rec.head < rec.items.length && rec.items[rec.head].ts <= cutoff) {
      rec.sum -= rec.items[rec.head].cost;
      rec.head += 1;
    }
    if (rec.head > 64 && rec.head * 2 >= rec.items.length) {
      rec.items = rec.items.slice(rec.head);
      rec.head = 0;
    }
    if (rec.sum + ev.cost <= limit) {
      rec.items.push({ ts: ev.ts, cost: ev.cost });
      rec.sum += ev.cost;
      out.push({ allowed: true, remaining: limit - rec.sum });
    } else {
      out.push({ allowed: false, remaining: limit - rec.sum });
    }
  }
  return out;
}
