type Bracket = { upTo: number | null; ratePct: number };

function computeProgressiveTax(incomeCents: number, brackets: Bracket[]): { taxCents: number; effectiveBps: number } {
  if (!Number.isInteger(incomeCents) || incomeCents < 0) throw new Error("income must be >= 0");
  if (!Array.isArray(brackets) || brackets.length === 0) throw new Error("brackets required");
  const finite: Array<{ upTo: number; ratePct: number }> = [];
  const unbounded: number[] = [];
  const seen = new Set<number>();
  for (const b of brackets) {
    if (!Number.isInteger(b.ratePct) || b.ratePct < 0) throw new Error("bad ratePct");
    if (b.upTo === null) {
      unbounded.push(b.ratePct);
    } else {
      if (!Number.isInteger(b.upTo) || b.upTo < 0 || seen.has(b.upTo)) throw new Error("bad upTo");
      seen.add(b.upTo);
      finite.push({ upTo: b.upTo, ratePct: b.ratePct });
    }
  }
  if (unbounded.length > 1) throw new Error("at most one unbounded bracket");
  finite.sort((a, b) => a.upTo - b.upTo);
  let prev = 0;
  let rem = incomeCents;
  let points = 0n;
  for (const b of finite) {
    const cap = b.upTo - prev;
    const take = rem < cap ? rem : cap;
    points += BigInt(take) * BigInt(b.ratePct);
    rem -= take;
    prev = b.upTo;
    if (rem === 0) break;
  }
  if (rem > 0) {
    if (unbounded.length === 0) throw new Error("income exceeds brackets");
    points += BigInt(rem) * BigInt(unbounded[0]);
  }
  const taxCents = Number((2n * points + 100n) / 200n);
  const incBig = BigInt(incomeCents);
  const effectiveBps = incomeCents === 0 ? 0 : Number((2n * BigInt(taxCents) * 10000n + incBig) / (2n * incBig));
  return { taxCents, effectiveBps };
}
