function matchCronMinutes(minuteSpec: string, hourSpec: string, timestamps: number[]): number[] {
  const parseField = (spec: string, lo: number, hi: number): Set<number> => {
    if (typeof spec !== "string" || spec === "") throw new Error("empty spec");
    const allowed = new Set<number>();
    for (const part of spec.split(",")) {
      if (part === "") throw new Error("empty cron token");
      if (part === "*") {
        for (let v = lo; v <= hi; v += 1) allowed.add(v);
      } else if (part.includes("-")) {
        const segs = part.split("-");
        if (segs.length !== 2 || !/^\d+$/.test(segs[0]) || !/^\d+$/.test(segs[1])) {
          throw new Error("bad range: " + part);
        }
        const a = Number(segs[0]);
        const b = Number(segs[1]);
        if (a < lo || b > hi || a > b) throw new Error("range out of bounds: " + part);
        for (let v = a; v <= b; v += 1) allowed.add(v);
      } else {
        if (!/^\d+$/.test(part)) throw new Error("bad number: " + part);
        const v = Number(part);
        if (v < lo || v > hi) throw new Error("value out of bounds: " + part);
        allowed.add(v);
      }
    }
    return allowed;
  };
  const mins = parseField(minuteSpec, 0, 59);
  const hrs = parseField(hourSpec, 0, 23);
  const out: number[] = [];
  for (const t of timestamps) {
    if (!Number.isInteger(t) || t < 0) throw new Error("bad timestamp");
    const hh = Math.floor(t / 60) % 24;
    const mm = t % 60;
    if (hrs.has(hh) && mins.has(mm)) out.push(t);
  }
  return out;
}
