type Job = { start: number; end: number; value: number };

function maxScheduleValue(jobs: Job[], gap: number): number {
  if (!Number.isInteger(gap) || gap < 0) throw new Error("gap must be >= 0");
  const items: Job[] = [];
  for (const j of jobs) {
    if (!Number.isInteger(j.start) || !Number.isInteger(j.end) || !Number.isInteger(j.value)) {
      throw new Error("job fields must be integers");
    }
    if (j.end <= j.start || j.value < 0) throw new Error("invalid job");
    items.push({ start: j.start, end: j.end, value: j.value });
  }
  if (items.length === 0) return 0;
  items.sort((a, b) => a.end - b.end || a.start - b.start);
  const n = items.length;
  const dp = new Array<number>(n + 1).fill(0);
  for (let i = 1; i <= n; i += 1) {
    const limit = items[i - 1].start - gap;
    let lo = 0;
    let hi = i - 1;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (items[mid].end <= limit) lo = mid + 1;
      else hi = mid;
    }
    const take = dp[lo] + items[i - 1].value;
    dp[i] = take > dp[i - 1] ? take : dp[i - 1];
  }
  return dp[n];
}
