import sys


def main():
    lines = [l.split() for l in sys.stdin.read().splitlines() if l.strip()]
    if not lines:
        return
    n = int(lines[0][0])
    size = 1
    while size < n:
        size *= 2
    tree = [0] * (2 * size)
    for i in range(n):
        tree[size + i] = 1
    for i in range(size - 1, 0, -1):
        tree[i] = tree[2 * i] + tree[2 * i + 1]

    def update(idx, val):
        pos = size + idx
        tree[pos] = val
        pos //= 2
        while pos:
            tree[pos] = tree[2 * pos] + tree[2 * pos + 1]
            pos //= 2

    def find_first(node, l, r, ql):
        if r < ql or tree[node] == 0:
            return -1
        if l == r:
            return l
        mid = (l + r) // 2
        res = find_first(2 * node, l, mid, ql)
        if res != -1:
            return res
        return find_first(2 * node + 1, mid + 1, r, ql)

    pos_map = {}
    out = []
    for parts in lines[1:]:
        if parts[0] == "ADD":
            bid, pref = parts[1], int(parts[2]) % n
            if tree[1] == 0:
                out.append("FULL " + bid)
            else:
                idx = find_first(1, 0, size - 1, pref)
                if idx == -1:
                    idx = find_first(1, 0, size - 1, 0)
                update(idx, 0)
                pos_map[bid] = idx
                out.append("IN %s %d" % (bid, idx))
        else:
            bid = parts[1]
            if bid not in pos_map:
                out.append("MISS " + bid)
            else:
                idx = pos_map.pop(bid)
                update(idx, 1)
                out.append("OUT %s %d" % (bid, idx))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


main()
