from .window import SlidingWindow


class GatewayLimiter:
    def __init__(self, window_ms, limit):
        if limit < 0:
            raise ValueError("limit must be >= 0")
        self.limit = limit
        self.win = SlidingWindow(window_ms)

    def allow(self, client, now_ms, cost=1):
        if cost < 0:
            raise ValueError("cost must be >= 0")
        used = self.win.prune_and_sum(client, now_ms)
        self.win.record(client, now_ms, cost)
        if used + cost > self.limit:
            return False
        return True

