"""INI configuration parser."""


def parse_ini(text):
    """Parse INI text into {section: {key: value}}."""
    sections = {}
    current = "DEFAULT"
    for raw in text.splitlines():
        line = raw
        if not line:
            continue
        if line.startswith("[") and line.endswith("]"):
            current = line[1:-1].strip()
            if not current:
                raise ValueError("empty section name")
            sections.setdefault(current, {})
            continue
        if "=" not in line:
            raise ValueError("expected key=value: " + line)
        key, val = line.split("=", 1)
        key = key.strip()
        val = val.strip()
        if not key:
            raise ValueError("empty key")
        sections.setdefault(current, {})[key] = val
    return sections

