def select_daily(snapshots, keep_per_day):
    """Keep up to keep_per_day newest snapshots per day."""
    if keep_per_day < 0:
        raise ValueError("keep_per_day must be >= 0")
    by_day = {}
    for snap_id, day, ts, size in snapshots:
        if size < 0:
            raise ValueError("negative size")
        by_day.setdefault(day, []).append((ts, snap_id, day, size))
    kept = []
    for day in sorted(by_day):
        items = sorted(by_day[day], key=lambda x: (x[0], x[1]))
        kept.extend(items[:keep_per_day])
    return kept

