"""Cron field parser supporting *, N, A-B, and /step."""


def parse_field(spec, lo, hi):
    if not spec:
        raise ValueError("empty cron spec")
    allowed = set()
    for part in spec.split(","):
        if not part:
            raise ValueError("empty token")
        base, step = part, 1
        if base == "*":
            a, b = lo, hi
        elif "-" in base:
            a_s, b_s = base.split("-", 1)
            a, b = int(a_s), int(b_s)
            if a < lo or b > hi or a > b:
                raise ValueError("range out of bounds")
        else:
            if "/" in part:
                raise ValueError("step requires * or range")
            v = int(base)
            if v < lo or v > hi:
                raise ValueError("value out of bounds")
            a, b = v, v
        for v in range(a, b + 1, step):
            allowed.add(v)
    return allowed

