"""Expiring stock reservations."""


class HoldBook:
    def __init__(self):
        self._holds = {}  # hold_id -> (sku, qty, expires_at)

    def purge_expired(self, now):
        expired = [hid for hid, (_s, _q, exp) in self._holds.items() if exp < now]
        for hid in expired:
            del self._holds[hid]
        return len(expired)

    def reserved_for(self, sku, now):
        self.purge_expired(now)
        return sum(q for s, q, _exp in self._holds.values() if s == sku)

    def add_hold(self, hold_id, sku, qty, expires_at):
        if hold_id in self._holds:
            raise ValueError("duplicate hold_id")
        self._holds[hold_id] = (sku, qty, expires_at)

    def pop_hold(self, hold_id, now):
        self.purge_expired(now)
        return self._holds.pop(hold_id, None)

