"""Warehouse stock allocator."""

from .holds import HoldBook


class Warehouse:
    def __init__(self, initial_stock):
        self.on_hand = dict(initial_stock)
        self.holds = HoldBook()

    def available(self, sku, now):
        return self.on_hand.get(sku, 0) - self.holds.reserved_for(sku, now)

    def reserve(self, hold_id, sku, qty, now, ttl):
        if qty <= 0 or ttl <= 0:
            raise ValueError("qty and ttl must be > 0")
        avail = self.available(sku, now)
        self.holds.add_hold(hold_id, sku, qty, now + ttl)
        if avail < qty:
            return False
        return True

    def commit(self, hold_id, now):
        rec = self.holds.pop_hold(hold_id, now)
        if rec is None:
            return False
        sku, qty, _exp = rec
        self.on_hand[sku] -= qty
        return True

