    bids = []
    asks = []
    trades = []
    statuses = []
    for seq, (oid, side, tif, price, qty) in enumerate(orders):
        if side not in ("BUY", "SELL") or tif not in ("GTC", "IOC"):
            raise ValueError("invalid side or tif")
        if price < 1 or qty < 1:
            raise ValueError("price and qty must be >= 1")
        filled = 0
        if side == "BUY":
            while qty > 0 and asks and asks[0][0] <= price:
                ap, _aseq, aoid, aref = asks[0]
                take = qty if qty < aref[0] else aref[0]
                qty -= take
                aref[0] -= take
                filled += take
                trades.append((oid, aoid, ap, take))
                if aref[0] == 0:
                    heapq.heappop(asks)
            if qty > 0 and tif == "GTC":
                heapq.heappush(bids, (-price, seq, oid, [qty]))
        else:
