                neg_bp, _bseq, boid, bref = bids[0]
                bp = -neg_bp
                take = qty if qty < bref[0] else bref[0]
                qty -= take
                bref[0] -= take
                filled += take
                trades.append((boid, oid, bp, take))
                if bref[0] == 0:
                    heapq.heappop(bids)
            if qty > 0 and tif == "GTC":
                heapq.heappush(asks, (price, seq, oid, [qty]))
        if qty == 0:
            status = "FILLED"
        elif tif == "IOC":
            status = "CANCELLED"
        elif filled > 0:
            status = "PARTIAL"
        else:
