def run_leases(commands):
    leases = {}
    next_tok = 0
    out = []
    for cmd in commands:
        op = cmd[0]
        if op == "ACQ":
            _, res, holder, now, ttl = cmd
            if ttl < 0:
                raise ValueError("ttl must be >= 0")
            cur = leases.get(res)
            if cur is not None and cur[1] > now:
                out.append(("BUSY", res, cur[0], cur[2]))
            else:
                next_tok += 1
                exp = now + ttl
                leases[res] = (holder, exp, next_tok)
                out.append(("GRANT", res, next_tok, exp))
        elif op == "RENEW":
            _, res, holder, tok, now, ttl = cmd
            if ttl < 0:
                raise ValueError("ttl must be >= 0")
            cur = leases.get(res)
            if cur is None or cur[1] <= now or cur[0] != holder or cur[2] != tok:
                out.append(("DENY", res))
            else:
                exp = now + ttl
                leases[res] = (holder, exp, tok)
                out.append(("OK", res, tok, exp))
        elif op == "REL":
            _, res, holder, tok, now = cmd
            cur = leases.get(res)
            if cur is None or cur[1] <= now or cur[0] != holder or cur[2] != tok:
                out.append(("DENY", res))
            else:
                del leases[res]
                out.append(("FREE", res))
        elif op == "CHECK":
            _, res, tok, now = cmd
            cur = leases.get(res)
            if cur is not None and cur[1] > now and cur[2] == tok:
                out.append(("VALID", res, cur[0]))
            else:
                out.append(("STALE", res))
        else:
            raise ValueError("unknown op: " + str(op))
    return out
