def prune_backups(snapshots, keep_per_day, max_total_bytes):
    if keep_per_day < 0 or max_total_bytes < 0:
        raise ValueError("limits must be >= 0")
    seen = set()
    by_day = {}
    for snap_id, day, ts, size in snapshots:
        if size < 0:
            raise ValueError("size must be >= 0")
        if snap_id in seen:
            raise ValueError("duplicate snap_id: " + str(snap_id))
        seen.add(snap_id)
        by_day.setdefault(day, []).append((ts, snap_id, size))
    daily = []
    for day in by_day:
        items = sorted(by_day[day], key=lambda x: (-x[0], x[1]))
        daily.extend(items[:keep_per_day])
    daily.sort(key=lambda x: (-x[0], x[1]))
    used = 0
    kept = []
    for _ts, snap_id, size in daily:
        if used + size <= max_total_bytes:
            used += size
            kept.append(snap_id)
    return sorted(kept)
