def apply_quota_ops(ops):
    def ancestors(path):
        res = ["/"]
        i = 1
        while True:
            j = path.find("/", i)
            if j == -1:
                break
            res.append(path[:j])
            i = j + 1
        return res

    quotas = {}
    usage = {}
    files = {}
    out = []
    for op in ops:
        kind = op[0]
        if kind == "QUOTA":
            _, dpath, lim = op
            if not dpath.startswith("/") or lim < 0:
                raise ValueError("invalid quota op")
            quotas[dpath] = lim
        elif kind == "WRITE":
            _, fpath, sz = op
            if not fpath.startswith("/") or fpath == "/" or sz < 0:
                raise ValueError("invalid write op")
            old = files.get(fpath, 0)
            delta = sz - old
            ancs = ancestors(fpath)
            ok = True
            if delta > 0:
                for d in ancs:
                    lim = quotas.get(d)
                    if lim is not None and usage.get(d, 0) + delta > lim:
                        ok = False
                        break
            if ok:
                files[fpath] = sz
                if delta != 0:
                    for d in ancs:
                        usage[d] = usage.get(d, 0) + delta
                out.append(("OK", fpath, sz))
            else:
                out.append(("QUOTA", fpath))
        elif kind == "RM":
            _, fpath = op
            if not fpath.startswith("/"):
                raise ValueError("invalid rm path")
            old = files.pop(fpath, 0)
            if old != 0:
                for d in ancestors(fpath):
                    usage[d] -= old
            out.append(("RM", fpath, old))
        else:
            raise ValueError("unknown op: " + str(kind))
    return out
