def schedule_drr(queues, quantum):
    from collections import deque
    if quantum < 1:
        raise ValueError("quantum must be >= 1")
    active = deque()
    for name, weight, pkts in queues:
        if weight < 1:
            raise ValueError("weight must be >= 1")
        q = deque()
        for sz in pkts:
            if sz < 1:
                raise ValueError("packet size must be >= 1")
            q.append(sz)
        if q:
            active.append([name, weight, q, 0])
    out = []
    while active:
        item = active.popleft()
        item[3] += quantum * item[1]
        q = item[2]
        while q and q[0] <= item[3]:
            sz = q.popleft()
            item[3] -= sz
            out.append((item[0], sz))
        if q:
            active.append(item)
    return out
