std::vector<std::string> scheduleDrr(
    std::vector<std::tuple<std::string, int, std::vector<int>>> queues, int quantum) {
    if (quantum < 1) throw std::invalid_argument("quantum must be >= 1");
    struct QState {
        std::string name;
        int weight;
        std::deque<int> pkts;
        long long deficit;
    };
    std::deque<QState> active;
    for (const auto& q : queues) {
        const std::string& name = std::get<0>(q);
        int w = std::get<1>(q);
        if (w < 1) throw std::invalid_argument("weight must be >= 1");
        std::deque<int> dq;
        for (int sz : std::get<2>(q)) {
            if (sz < 1) throw std::invalid_argument("packet size must be >= 1");
            dq.push_back(sz);
        }
        if (!dq.empty()) {
            active.push_back({name, w, std::move(dq), 0});
        }
    }
    std::vector<std::string> out;
    while (!active.empty()) {
        QState cur = std::move(active.front());
        active.pop_front();
        cur.deficit += static_cast<long long>(quantum) * cur.weight;
        while (!cur.pkts.empty() && cur.pkts.front() <= cur.deficit) {
            int sz = cur.pkts.front();
            cur.pkts.pop_front();
            cur.deficit -= sz;
            out.push_back(cur.name + " " + std::to_string(sz));
        }
        if (!cur.pkts.empty()) {
            active.push_back(std::move(cur));
        }
    }
    return out;
}
