std::vector<std::string> runLeases(
    std::vector<std::tuple<std::string, std::string, std::string, long long, long long, long long>> commands) {
    struct Lease { std::string holder; long long exp; long long tok; };
    std::unordered_map<std::string, Lease> leases;
    long long nextTok = 0;
    std::vector<std::string> out;
    out.reserve(commands.size());
    for (const auto& c : commands) {
        const std::string& op = std::get<0>(c);
        const std::string& res = std::get<1>(c);
        const std::string& holder = std::get<2>(c);
        long long tok = std::get<3>(c);
        long long now = std::get<4>(c);
        long long ttl = std::get<5>(c);
        if (op == "ACQ") {
            if (ttl < 0) throw std::invalid_argument("negative ttl");
            auto it = leases.find(res);
            if (it != leases.end() && it->second.exp > now) {
                out.push_back("BUSY " + res + " " + it->second.holder + " " + std::to_string(it->second.tok));
            } else {
                ++nextTok;
                long long exp = now + ttl;
                leases[res] = {holder, exp, nextTok};
                out.push_back("GRANT " + res + " " + std::to_string(nextTok) + " " + std::to_string(exp));
            }
        } else if (op == "RENEW") {
            if (ttl < 0) throw std::invalid_argument("negative ttl");
            auto it = leases.find(res);
            if (it == leases.end() || it->second.exp <= now || it->second.holder != holder || it->second.tok != tok) {
                out.push_back("DENY " + res);
            } else {
                it->second.exp = now + ttl;
                out.push_back("OK " + res + " " + std::to_string(tok) + " " + std::to_string(it->second.exp));
            }
        } else if (op == "REL") {
            auto it = leases.find(res);
            if (it == leases.end() || it->second.exp <= now || it->second.holder != holder || it->second.tok != tok) {
                out.push_back("DENY " + res);
            } else {
                leases.erase(it);
                out.push_back("FREE " + res);
            }
        } else if (op == "CHECK") {
            auto it = leases.find(res);
            if (it != leases.end() && it->second.exp > now && it->second.tok == tok) {
                out.push_back("VALID " + res + " " + it->second.holder);
            } else {
                out.push_back("STALE " + res);
            }
        } else {
            throw std::invalid_argument("bad op");
        }
    }
    return out;
}
