std::vector<std::string> assignRooms(
    int numRooms, long long gap, std::vector<std::tuple<std::string, long long, long long>> requests) {
    if (numRooms < 0 || gap < 0) throw std::invalid_argument("invalid params");
    std::priority_queue<std::pair<long long, int>> avail;
    // max-heap by freeAt, tie-break smallest room id -> store (freeAt, -roomId)
    for (int r = 1; r <= numRooms; ++r) avail.emplace(0LL, -r);
    using BusyItem = std::pair<long long, int>;
    std::priority_queue<BusyItem, std::vector<BusyItem>, std::greater<BusyItem>> busy;
    long long lastS = -1;
    std::vector<std::string> out;
    out.reserve(requests.size());
    for (const auto& req : requests) {
        const std::string& bid = std::get<0>(req);
        long long s = std::get<1>(req);
        long long e = std::get<2>(req);
        if (s < 0 || e < s) throw std::invalid_argument("invalid interval");
        if (lastS != -1 && s < lastS) throw std::invalid_argument("starts must be non-decreasing");
        lastS = s;
        while (!busy.empty() && busy.top().first <= s) {
            auto [fAt, r] = busy.top();
            busy.pop();
            avail.emplace(fAt, -r);
        }
        if (avail.empty()) {
            out.push_back("DENY " + bid);
        } else {
            int r = -avail.top().second;
            avail.pop();
            busy.emplace(e + gap, r);
            out.push_back("ROOM " + bid + " " + std::to_string(r));
        }
    }
    return out;
}
