std::vector<std::string> assignCircularSlots(int n, std::vector<std::tuple<std::string, std::string, int>> ops) {
    if (n < 1) throw std::invalid_argument("n must be >= 1");
    std::set<int> freeSlots;
    for (int i = 0; i < n; ++i) freeSlots.insert(i);
    std::unordered_map<std::string, int> pos;
    std::vector<std::string> out;
    out.reserve(ops.size());
    for (const auto& item : ops) {
        const std::string& op = std::get<0>(item);
        const std::string& bid = std::get<1>(item);
        int pref = std::get<2>(item);
        if (op == "ADD") {
            if (freeSlots.empty()) {
                out.push_back("FULL " + bid);
                continue;
            }
            int p = ((pref % n) + n) % n;
            auto it = freeSlots.lower_bound(p);
            if (it == freeSlots.end()) it = freeSlots.begin();
            int slot = *it;
            freeSlots.erase(it);
            pos[bid] = slot;
            out.push_back("IN " + bid + " " + std::to_string(slot));
        } else if (op == "REM") {
            auto it = pos.find(bid);
            if (it == pos.end()) {
                out.push_back("MISS " + bid);
            } else {
                int slot = it->second;
                pos.erase(it);
                freeSlots.insert(slot);
                out.push_back("OUT " + bid + " " + std::to_string(slot));
            }
        } else {
            throw std::invalid_argument("bad op");
        }
    }
    return out;
}
