long long computeProgressiveTax(long long incomeCents, std::vector<std::pair<long long, int>> brackets) {
    if (incomeCents < 0) throw std::invalid_argument("negative income");
    if (brackets.empty()) throw std::invalid_argument("empty brackets");
    std::vector<std::pair<long long, int>> finite;
    std::vector<int> unbounded;
    std::set<long long> seen;
    for (const auto& b : brackets) {
        if (b.second < 0) throw std::invalid_argument("negative rate");
        if (b.first == -1) {
            unbounded.push_back(b.second);
        } else {
            if (b.first < 0 || !seen.insert(b.first).second) throw std::invalid_argument("invalid bracket limit");
            finite.push_back(b);
        }
    }
    if (unbounded.size() > 1) throw std::invalid_argument("multiple unbounded brackets");
    std::sort(finite.begin(), finite.end());
    long long prev = 0;
    long long rem = incomeCents;
    long long points = 0;
    for (const auto& b : finite) {
        long long cap = b.first - prev;
        long long take = std::min(rem, cap);
        points += take * b.second;
        rem -= take;
        prev = b.first;
        if (rem == 0) break;
    }
    if (rem > 0) {
        if (unbounded.empty()) throw std::invalid_argument("income exceeds brackets");
        points += rem * unbounded[0];
    }
    return (2 * points + 100) / 200;
}
