std::vector<std::string> filterLogs(
    long long window, int burst, std::vector<std::tuple<long long, std::string, std::string>> events) {
    if (window < 1 || burst < 0) throw std::invalid_argument("invalid config");
    std::map<std::pair<std::string, std::string>, long long> lastMsg;
    std::unordered_map<std::string, std::deque<long long>> svcQ;
    long long lastTs = -1;
    std::vector<std::string> out;
    out.reserve(events.size());
    for (const auto& ev : events) {
        long long ts = std::get<0>(ev);
        const std::string& svc = std::get<1>(ev);
        const std::string& msg = std::get<2>(ev);
        if (lastTs != -1 && ts < lastTs) throw std::invalid_argument("non-monotonic ts");
        lastTs = ts;
        auto key = std::make_pair(svc, msg);
        auto it = lastMsg.find(key);
        if (it != lastMsg.end() && ts - it->second < window) {
            out.push_back("DUP");
            continue;
        }
        auto& q = svcQ[svc];
        long long cutoff = ts - window;
        while (!q.empty() && q.front() <= cutoff) q.pop_front();
        if (static_cast<int>(q.size()) >= burst) {
            out.push_back("THROTTLE");
            continue;
        }
        lastMsg[key] = ts;
        q.push_back(ts);
        out.push_back("KEEP");
    }
    return out;
}
