function simulateTokenBuckets(events, capacity, refillPerSec) {
  if (!Number.isInteger(capacity) || capacity < 1) throw new Error("bad capacity");
  if (typeof refillPerSec !== "number" || !Number.isFinite(refillPerSec) || refillPerSec < 0) {
    throw new Error("bad refillPerSec");
  }
  const state = new Map();
  let lastTs = null;
  const results = [];
  for (const ev of events) {
    const { key, ts, cost } = ev;
    if (typeof key !== "string" || key.length === 0) throw new Error("bad key");
    if (typeof ts !== "number" || !Number.isFinite(ts)) throw new Error("bad ts");
    if (lastTs !== null && ts < lastTs) throw new Error("decreasing ts");
    lastTs = ts;
    if (!Number.isInteger(cost) || cost < 0) throw new Error("bad cost");
    let bucket = state.get(key);
    if (!bucket) {
      bucket = { tokens: capacity, lastTs: ts };
      state.set(key, bucket);
    } else {
      const elapsed = ts - bucket.lastTs;
      bucket.tokens = Math.min(capacity, bucket.tokens + elapsed * refillPerSec);
      bucket.lastTs = ts;
    }
    if (cost <= bucket.tokens + 1e-9) {
      bucket.tokens = Math.max(0, bucket.tokens - cost);
      results.push({ allowed: true, remaining: Math.round(bucket.tokens * 1000) / 1000 });
    } else {
      results.push({ allowed: false, remaining: Math.round(bucket.tokens * 1000) / 1000 });
    }
  }
  return results;
}
