function nextCronMatches(pattern, startMinute, count) {
  if (!Number.isInteger(startMinute) || startMinute < 0) throw new Error("bad startMinute");
  if (!Number.isInteger(count) || count < 0) throw new Error("bad count");
  const fields = pattern.trim().split(/\s+/);
  if (fields.length !== 3) throw new Error("expected 3 fields: min hour dom");
  const parseField = (expr, lo, hi) => {
    const allowed = new Set();
    for (const part of expr.split(",")) {
      if (!part) throw new Error("empty part");
      const slash = part.split("/");
      if (slash.length > 2) throw new Error("bad step");
      const step = slash.length === 2 ? Number(slash[1]) : 1;
      if (!Number.isInteger(step) || step <= 0) throw new Error("bad step value");
      let a = lo, b = hi;
      if (slash[0] !== "*") {
        const dash = slash[0].split("-");
        if (dash.length === 1) {
          a = b = Number(dash[0]);
          if (slash.length === 2) b = hi;
        } else if (dash.length === 2) {
          a = Number(dash[0]);
          b = Number(dash[1]);
        } else {
          throw new Error("bad range");
        }
        if (!Number.isInteger(a) || !Number.isInteger(b) || a < lo || b > hi || a > b) {
          throw new Error("out of range");
        }
      }
      for (let v = a; v <= b; v += step) allowed.add(v);
    }
    return allowed;
  };
  const mins = parseField(fields[0], 0, 59);
  const hours = parseField(fields[1], 0, 23);
  const doms = parseField(fields[2], 1, 30);
  if (count === 0) return [];
  const out = [];
  const limit = startMinute + 30 * 1440 * 2;
  for (let t = startMinute; t < limit && out.length < count; t += 1) {
    const m = t % 60;
    const h = Math.floor(t / 60) % 24;
    const d = (Math.floor(t / 1440) % 30) + 1;
    if (mins.has(m) && hours.has(h) && doms.has(d)) out.push(t);
  }
  if (out.length < count) throw new Error("no matches found");
  return out;
}
