function runLeaseCommands(commands) {
  const leases = new Map();
  let nextToken = 0;
  const out = [];
  for (const cmd of commands) {
    const [op] = cmd;
    if (op === "ACQ") {
      const [, res, holder, now, ttl] = cmd;
      if (!Number.isInteger(now) || !Number.isInteger(ttl) || ttl <= 0) throw new Error("bad ACQ");
      const cur = leases.get(res);
      if (cur && cur.exp > now) {
        out.push(`BUSY ${res} ${cur.holder} ${cur.token}`);
      } else {
        nextToken += 1;
        leases.set(res, { holder, exp: now + ttl, token: nextToken });
        out.push(`GRANT ${res} ${nextToken} ${now + ttl}`);
      }
    } else if (op === "RENEW") {
      const [, res, holder, tok, now, ttl] = cmd;
      if (!Number.isInteger(now) || !Number.isInteger(ttl) || ttl <= 0) throw new Error("bad RENEW");
      const cur = leases.get(res);
      if (!cur || cur.exp <= now || cur.holder !== holder || cur.token !== tok) {
        out.push(`DENY ${res}`);
      } else {
        cur.exp = now + ttl;
        out.push(`OK ${res} ${tok} ${cur.exp}`);
      }
    } else if (op === "REL") {
      const [, res, holder, tok, now] = cmd;
      const cur = leases.get(res);
      if (!cur || cur.exp <= now || cur.holder !== holder || cur.token !== tok) {
        out.push(`DENY ${res}`);
      } else {
        leases.delete(res);
        out.push(`FREE ${res}`);
      }
    } else if (op === "CHECK") {
      const [, res, tok, now] = cmd;
      const cur = leases.get(res);
      if (cur && cur.exp > now && cur.token === tok) {
        out.push(`VALID ${res} ${cur.holder}`);
      } else {
        out.push(`STALE ${res}`);
      }
    } else {
      throw new Error("unknown op: " + op);
    }
  }
  return out;
}
