function scheduleDrr(queues, quantum) {
  if (!Number.isInteger(quantum) || quantum <= 0) throw new Error("bad quantum");
  const active = [];
  for (const q of queues) {
    if (!Number.isInteger(q.weight) || q.weight <= 0) throw new Error("bad weight");
    if (q.packets.some((p) => !Number.isInteger(p) || p <= 0)) throw new Error("bad packet");
    if (q.packets.length > 0) {
      active.push({ name: q.name, weight: q.weight, packets: [...q.packets], idx: 0, deficit: 0 });
    }
  }
  const out = [];
  let cur = active;
  while (cur.length > 0) {
    const next = [];
    for (const q of cur) {
      q.deficit += quantum * q.weight;
      while (q.idx < q.packets.length && q.packets[q.idx] <= q.deficit) {
        const sz = q.packets[q.idx++];
        q.deficit -= sz;
        out.push(`${q.name}:${sz}`);
      }
      if (q.idx < q.packets.length) next.push(q);
    }
    cur = next;
  }
  return out;
}
