function computeSlaDowntime(outages, maintenance) {
  const merge = (ivs) => {
    const valid = [];
    for (const [s, e] of ivs) {
      if (!Number.isInteger(s) || !Number.isInteger(e) || s > e) throw new Error("bad interval");
      if (s < e) valid.push([s, e]);
    }
    valid.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    const res = [];
    for (const [s, e] of valid) {
      if (res.length === 0 || s > res[res.length - 1][1]) res.push([s, e]);
      else res[res.length - 1][1] = Math.max(res[res.length - 1][1], e);
    }
    return res;
  };
  const outs = merge(outages);
  const maints = merge(maintenance);
  let total = 0;
  let j = 0;
  const uncovered = [];
  for (const [os, oe] of outs) {
    let cur = os;
    while (j < maints.length && maints[j][1] <= cur) j += 1;
    let k = j;
    while (k < maints.length && maints[k][0] < oe) {
      const [ms, me] = maints[k];
      if (ms > cur) {
        uncovered.push([cur, ms]);
        total += ms - cur;
      }
      if (me > cur) cur = me;
      if (cur >= oe) break;
      k += 1;
    }
    if (cur < oe) {
      uncovered.push([cur, oe]);
      total += oe - cur;
    }
  }
  return { totalDowntime: total, intervals: uncovered };
}
