function scheduleDepWaves(tasks, deps) {
  const nodes = new Set(tasks);
  if (nodes.size !== tasks.length) throw new Error("duplicate task");
  const adj = new Map();
  const indeg = new Map();
  for (const t of tasks) {
    adj.set(t, []);
    indeg.set(t, 0);
  }
  for (const [before, after] of deps) {
    if (!nodes.has(before) || !nodes.has(after)) throw new Error("unknown task in dep");
    adj.get(before).push(after);
    indeg.set(after, indeg.get(after) + 1);
  }
  let ready = [];
  for (const [t, d] of indeg.entries()) {
    if (d === 0) ready.push(t);
  }
  const waves = [];
  let done = 0;
  while (ready.length > 0) {
    ready.sort();
    waves.push(ready);
    done += ready.length;
    const next = [];
    for (const u of ready) {
      for (const v of adj.get(u)) {
        const nd = indeg.get(v) - 1;
        indeg.set(v, nd);
        if (nd === 0) next.push(v);
      }
    }
    ready = next;
  }
  if (done !== tasks.length) throw new Error("cycle detected");
  return waves;
}
