function rollingMedians(values, k) {
  if (!Number.isInteger(k) || k < 1) throw new Error("bad k");
  const win = [];
  const insertSorted = (arr, x) => {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (arr[mid] < x) lo = mid + 1;
      else hi = mid;
    }
    arr.splice(lo, 0, x);
  };
  const removeSorted = (arr, x) => {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (arr[mid] < x) lo = mid + 1;
      else hi = mid;
    }
    arr.splice(lo, 1);
  };
  const out = [];
  for (let i = 0; i < values.length; i += 1) {
    const v = values[i];
    if (typeof v !== "number" || !Number.isFinite(v)) throw new Error("bad value");
    insertSorted(win, v);
    if (win.length > k) removeSorted(win, values[i - k]);
    if (win.length === k) {
      out.push(win[(k - 1) >> 1]);
    }
  }
  return out;
}
