interface OrderInput {
  id: string;
  side: "BUY" | "SELL";
  tif: "GTC" | "IOC";
  price: number;
  qty: number;
}
interface Trade {
  buyId: string;
  sellId: string;
  price: number;
  qty: number;
}
interface OrderSummary {
  id: string;
  filled: number;
  remaining: number;
  status: "FILLED" | "PARTIAL" | "OPEN" | "CANCELLED";
}
interface BookOrder {
  id: string;
  price: number;
  qty: number;
  seq: number;
}

function matchOrderBook(orders: OrderInput[]): { trades: Trade[]; summaries: OrderSummary[] } {
  const bids: BookOrder[] = [];
  const asks: BookOrder[] = [];
  const trades: Trade[] = [];
  const summaries: OrderSummary[] = [];
  let seq = 0;

  for (const ord of orders) {
    if (!Number.isInteger(ord.price) || ord.price <= 0) throw new Error("bad price");
    if (!Number.isInteger(ord.qty) || ord.qty <= 0) throw new Error("bad qty");
    if (ord.side !== "BUY" && ord.side !== "SELL") throw new Error("bad side");
    if (ord.tif !== "GTC" && ord.tif !== "IOC") throw new Error("bad tif");
    seq += 1;
    let rem = ord.qty;
    let filled = 0;

    if (ord.side === "BUY") {
      while (rem > 0) {
        let bestIdx = -1;
        for (let i = 0; i < asks.length; i += 1) {
          const a = asks[i];
          if (a.price <= ord.price) {
            if (
              bestIdx === -1 ||
              a.price < asks[bestIdx].price ||
              (a.price === asks[bestIdx].price && a.seq < asks[bestIdx].seq)
            ) {
              bestIdx = i;
            }
          }
        }
        if (bestIdx === -1) break;
        const best = asks[bestIdx];
        const take = Math.min(rem, best.qty);
        rem -= take;
        best.qty -= take;
        filled += take;
        trades.push({ buyId: ord.id, sellId: best.id, price: best.price, qty: take });
        if (best.qty === 0) asks.splice(bestIdx, 1);
      }
      if (rem > 0 && ord.tif === "GTC") {
        bids.push({ id: ord.id, price: ord.price, qty: rem, seq });
      }
    } else {
      while (rem > 0) {
        let bestIdx = -1;
        for (let i = 0; i < bids.length; i += 1) {
          const b = bids[i];
          if (b.price >= ord.price) {
            if (
              bestIdx === -1 ||
              b.price > bids[bestIdx].price ||
              (b.price === bids[bestIdx].price && b.seq < bids[bestIdx].seq)
            ) {
              bestIdx = i;
            }
          }
        }
        if (bestIdx === -1) break;
        const best = bids[bestIdx];
        const take = Math.min(rem, best.qty);
        rem -= take;
        best.qty -= take;
        filled += take;
        trades.push({ buyId: best.id, sellId: ord.id, price: best.price, qty: take });
        if (best.qty === 0) bids.splice(bestIdx, 1);
      }
      if (rem > 0 && ord.tif === "GTC") {
        asks.push({ id: ord.id, price: ord.price, qty: rem, seq });
      }
    }

    const status: OrderSummary["status"] =
      rem === 0 ? "FILLED" : ord.tif === "IOC" ? "CANCELLED" : filled > 0 ? "PARTIAL" : "OPEN";
    summaries.push({ id: ord.id, filled, remaining: rem, status });
  }
  return { trades, summaries };
}
