function allocateCarousels(numSlots: number, flights: FlightArrival[]): CarouselAssignment[] {
  if (!Number.isInteger(numSlots) || numSlots < 1) throw new Error("bad numSlots");
  const sorted = [...flights].sort((a, b) => a.start - b.start || a.flight.localeCompare(b.flight));
