    for (let i = 0; i < numSlots; i += 1) {
      const occ = slotOcc[i];
      if (occ !== null && occ.end <= f.start) slotOcc[i] = null;
    }
    let chosen = -1;
    for (let i = 0; i < numSlots; i += 1) {
      if (slotOcc[i] === null) {
        chosen = i;
        break;
      }
    }
    const evicted: string[] = [];
    if (chosen === -1 && f.priority) {
      let bestEnd = Infinity;
      for (let i = 0; i < numSlots; i += 1) {
        const occ = slotOcc[i]!;
        if (!occ.priority && occ.end < bestEnd) {
          bestEnd = occ.end;
          chosen = i;
        }
      }
      if (chosen !== -1) {
        evicted.push(slotOcc[chosen]!.flight);
        slotOcc[chosen] = null;
      }
