    if (chosen === -1) {
      out.push({ flight: f.flight, slot: -1, evicted });
    } else {
      slotOcc[chosen] = { flight: f.flight, end: f.end, priority: f.priority };
      out.push({ flight: f.flight, slot: chosen, evicted });
    }
