interface TierShare {
  id: string;
  weight: number;
}

function prorateWithResidue(
  totalCents: number,
  usedDays: number,
  totalDays: number,
  shares: TierShare[]
): Record<string, number> {
  if (!Number.isInteger(totalCents) || totalCents < 0) throw new Error("bad totalCents");
  if (!Number.isInteger(usedDays) || !Number.isInteger(totalDays) || usedDays < 0 || totalDays <= 0 || usedDays > totalDays) {
    throw new Error("bad days");
  }
  if (shares.length === 0) throw new Error("empty shares");
  let weightSum = 0;
  const seen = new Set<string>();
  for (const s of shares) {
    if (!s.id || seen.has(s.id)) throw new Error("bad/duplicate id");
    if (!Number.isInteger(s.weight) || s.weight < 0) throw new Error("bad weight");
    seen.add(s.id);
    weightSum += s.weight;
  }
  if (weightSum <= 0) throw new Error("weightSum must be > 0");

  const prorated = Math.floor((2 * totalCents * usedDays + totalDays) / (2 * totalDays));
  const items = shares.map((s) => {
    const exactNum = prorated * s.weight;
    const base = Math.floor(exactNum / weightSum);
    const rem = exactNum % weightSum;
    return { id: s.id, base, rem };
  });
  let leftover = prorated - items.reduce((acc, it) => acc + it.base, 0);
  const ranked = [...items].sort((a, b) => b.rem - a.rem || a.id.localeCompare(b.id));
  const bonus = new Map<string, number>();
  for (let i = 0; i < leftover; i += 1) {
    const id = ranked[i].id;
    bonus.set(id, (bonus.get(id) ?? 0) + 1);
  }
  const out: Record<string, number> = {};
  for (const it of items) {
    out[it.id] = it.base + (bonus.get(it.id) ?? 0);
  }
  return out;
}
