function detectSpikes(
  values: number[],
  window: number,
  multNum: number,
  multDen: number,
  minDelta: number
): number[] {
  if (!Number.isInteger(window) || window < 1) throw new Error("bad window");
  if (!Number.isInteger(multNum) || !Number.isInteger(multDen) || multNum <= 0 || multDen <= 0) {
    throw new Error("bad multiplier");
  }
  if (!Number.isInteger(minDelta) || minDelta < 0) throw new Error("bad minDelta");
  const sortedWin: number[] = [];
  const insertVal = (x: number) => {
    let lo = 0, hi = sortedWin.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (sortedWin[mid] < x) lo = mid + 1;
      else hi = mid;
    }
    sortedWin.splice(lo, 0, x);
  };
  const removeVal = (x: number) => {
    let lo = 0, hi = sortedWin.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (sortedWin[mid] < x) lo = mid + 1;
      else hi = mid;
    }
    sortedWin.splice(lo, 1);
  };
  const spikes: number[] = [];
  for (let i = 0; i < values.length; i += 1) {
    const v = values[i];
    if (!Number.isInteger(v)) throw new Error("values must be integers");
    if (i >= window) {
      const med = sortedWin[(window - 1) >> 1];
      if (v * multDen >= med * multNum && v - med >= minDelta) {
        spikes.push(i);
      }
      removeVal(values[i - window]);
    }
    insertVal(v);
  }
  return spikes;
}
