function assignRooms(numRooms: number, bookings: Booking[]): Record<string, number> {
  if (!Number.isInteger(numRooms) || numRooms < 0) throw new Error("bad numRooms");
  const sorted = [...bookings].sort((a, b) => a.start - b.start || a.end - b.end || a.id.localeCompare(b.id));
  const freeAt = Array<number>(numRooms).fill(-Infinity);
  const res: Record<string, number> = {};
  for (const b of sorted) {
    if (!Number.isInteger(b.start) || !Number.isInteger(b.end) || b.start >= b.end) {
      throw new Error("bad interval");
    }
    if (b.id in res) throw new Error("duplicate id");
    let chosen = -1;
    for (let r = 0; r < numRooms; r += 1) {
      if (freeAt[r] <= b.start) {
        chosen = r;
        break;
      }
    }
    if (chosen !== -1) {
      freeAt[chosen] = b.end;
    }
    res[b.id] = chosen;
  }
  return res;
}
