interface CallEvent {
  ts: number;
  ok: boolean;
}
interface BreakerReport {
  state: "CLOSED" | "OPEN" | "HALF_OPEN";
  ok: number;
  err: number;
  blocked: number;
  transitions: Array<{ ts: number; state: "CLOSED" | "OPEN" | "HALF_OPEN" }>;
}

function runBreakerBudget(
  events: CallEvent[],
  failThreshold: number,
  cooldown: number,
  halfOpenSuccessNeeded: number
): BreakerReport {
  if (!Number.isInteger(failThreshold) || failThreshold < 1) throw new Error("bad failThreshold");
  if (!Number.isInteger(cooldown) || cooldown < 0) throw new Error("bad cooldown");
  if (!Number.isInteger(halfOpenSuccessNeeded) || halfOpenSuccessNeeded < 1) {
    throw new Error("bad halfOpenSuccessNeeded");
  }
  let state: "CLOSED" | "OPEN" | "HALF_OPEN" = "CLOSED";
  let fails = 0;
  let halfOk = 0;
  let openedAt = 0;
  let lastTs: number | null = null;
  let ok = 0;
  let err = 0;
  let blocked = 0;
  const transitions: Array<{ ts: number; state: "CLOSED" | "OPEN" | "HALF_OPEN" }> = [];

  for (const ev of events) {
    if (!Number.isInteger(ev.ts)) throw new Error("bad ts");
    if (lastTs !== null && ev.ts < lastTs) throw new Error("decreasing ts");
    lastTs = ev.ts;
    if (state === "OPEN") {
      if (ev.ts >= openedAt + cooldown) {
        state = "HALF_OPEN";
        halfOk = 0;
        transitions.push({ ts: ev.ts, state: "HALF_OPEN" });
      } else {
        blocked += 1;
        continue;
      }
    }
    if (ev.ok) {
      ok += 1;
      if (state === "HALF_OPEN") {
        halfOk += 1;
        if (halfOk >= halfOpenSuccessNeeded) {
          state = "CLOSED";
          fails = 0;
          transitions.push({ ts: ev.ts, state: "CLOSED" });
        }
      } else {
        fails = 0;
      }
    } else {
      err += 1;
      if (state === "HALF_OPEN") {
        state = "OPEN";
        openedAt = ev.ts;
        halfOk = 0;
        transitions.push({ ts: ev.ts, state: "OPEN" });
      } else {
        fails += 1;
        if (fails >= failThreshold) {
          state = "OPEN";
          openedAt = ev.ts;
          transitions.push({ ts: ev.ts, state: "OPEN" });
        }
      }
    }
  }
  return { state, ok, err, blocked, transitions };
}
