type ColType = "int" | "bool" | "str";

function parseTypedCsv(text: string, schema: Record<string, ColType>): Array<Record<string, number | boolean | string>> {
  const splitCsvLine = (line: string): string[] => {
    const cells: string[] = [];
    let cur = "";
    let inQuotes = false;
    for (let i = 0; i < line.length; i += 1) {
      const ch = line[i];
      if (inQuotes) {
        if (ch === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            cur += '"';
            i += 1;
          } else {
            inQuotes = false;
          }
        } else {
          cur += ch;
        }
      } else if (ch === '"') {
        if (cur.length !== 0) throw new Error("unexpected quote");
        inQuotes = true;
      } else if (ch === ",") {
        cells.push(cur);
        cur = "";
      } else {
        cur += ch;
      }
    }
    if (inQuotes) throw new Error("unclosed quote");
    cells.push(cur);
    return cells;
  };

  const lines = text.split(/\r?\n/).filter((l) => l.length > 0);
  if (lines.length === 0) throw new Error("missing header");
  const headers = splitCsvLine(lines[0]);
  if (new Set(headers).size !== headers.length) throw new Error("duplicate header");
  for (const h of headers) {
    if (!(h in schema)) throw new Error("unknown column: " + h);
  }
  const rows: Array<Record<string, number | boolean | string>> = [];
  for (let r = 1; r < lines.length; r += 1) {
    const cells = splitCsvLine(lines[r]);
    if (cells.length !== headers.length) throw new Error("column count mismatch");
    const obj: Record<string, number | boolean | string> = {};
    for (let c = 0; c < headers.length; c += 1) {
      const col = headers[c];
      const raw = cells[c];
      const typ = schema[col];
      if (typ === "str") {
        obj[col] = raw;
      } else if (typ === "int") {
        if (!/^-?\d+$/.test(raw)) throw new Error("bad int: " + raw);
        obj[col] = Number(raw);
      } else if (typ === "bool") {
        if (raw === "true") obj[col] = true;
        else if (raw === "false") obj[col] = false;
        else throw new Error("bad bool: " + raw);
      }
    }
    rows.push(obj);
  }
  return rows;
}
