```typescript
class BoundedLru<V> {
  private cap: number;
  private map: Map<string, V>;
  public hits: number;
  public misses: number;
  public evictions: number;

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new Error("bad capacity");
    this.cap = capacity;
    this.map = new Map<string, V>();
    this.hits = 0;
    this.misses = 0;
    this.evictions = 0;
  }

  get(key: string): V | null {
    if (!this.map.has(key)) {
      this.misses += 1;
      return null;
    }
    const val = this.map.get(key)!;
    this.map.delete(key);
    this.map.set(key, val);
    this.hits += 1;
    return val;
  }

  set(key: string, value: V): string | null {
    if (this.map.has(key)) {
      this.map.delete(key);
      this.map.set(key, value);
      return null;
    }
    let evicted: string | null = null;
    if (this.map.size >= this.cap) {
      evicted = this.map.keys().next().value!;
      this.map.delete(evicted);
      this.evictions += 1;
    }
    this.map.set(key, value);
    return evicted;
  }

  delete(key: string): boolean {
    return this.map.delete(key);
  }

  keys(): string[] {
    return [...this.map.keys()];
  }
}

function runLruOps(
  capacity: number,
  ops: Array<["GET", string] | ["SET", string, number] | ["DEL", string]>
): { results: Array<number | string | boolean | null>; hits: number; misses: number; evictions: number; keys: string[] } {
  const cache = new BoundedLru<number>(capacity);
  const results: Array<number | string | boolean | null> = [];
  for (const op of ops) {
    if (op[0] === "GET") results.push(cache.get(op[1]));
    else if (op[0] === "SET") results.push(cache.set(op[1], op[2]));
    else if (op[0] === "DEL") results.push(cache.delete(op[1]));
    else throw new Error("unknown op");
  }
  return { results, hits: cache.hits, misses: cache.misses, evictions: cache.evictions, keys: cache.keys() };
}
