def schedule_drr(queues, quantum):
    if not isinstance(quantum, int) or isinstance(quantum, bool) or quantum <= 0:
        raise ValueError("bad quantum")
    active = deque()
    for name, weight, packets in queues:
        if not isinstance(weight, int) or isinstance(weight, bool) or weight <= 0:
            raise ValueError("bad weight")
        q = deque()
        for sz in packets:
            if not isinstance(sz, int) or isinstance(sz, bool) or sz <= 0:
                raise ValueError("bad packet")
            q.append(sz)
        if q:
            active.append([name, weight, q, 0])
    out = []
    while active:
        for _ in range(len(active)):
            item = active.popleft()
            item[3] += quantum * item[1]
            q = item[2]
            while q and q[0] <= item[3]:
                sz = q.popleft()
                item[3] -= sz
                out.append((item[0], sz))
            if q:
                active.append(item)
    return out
