            _, path, sz = op
            if not isinstance(sz, int) or isinstance(sz, bool) or sz < 0:
                raise ValueError("bad size")
            ds = ancestors(path)
            delta = sz - sizes.get(path, 0)
            if delta > 0 and any(d in limits and used.get(d, 0) + delta > limits[d] for d in ds):
                out.append("QUOTA_EXCEEDED")
            else:
                sizes[path] = sz
                for d in ds:
                    used[d] = used.get(d, 0) + delta
                out.append("OK")
        elif kind == "DEL":
            _, path = op
            ds = ancestors(path)
            if path not in sizes:
                out.append("NOT_FOUND")
            else:
                old = sizes.pop(path)
                for d in ds:
                    used[d] -= old
                out.append("DELETED")
        elif kind == "USAGE":
            _, d = op
            out.append(used.get(d, 0))
        else:
            raise ValueError("unknown op")
    return out
