def run_breaker_budget(events, fail_threshold, cooldown, half_open_needed):
    if fail_threshold < 1 or cooldown < 0 or half_open_needed < 1:
        raise ValueError("bad config")
    state = "CLOSED"
    fails = 0
    half_ok = 0
    opened_at = 0
    last_t = None
    ok = err = blocked = 0
    transitions = []
    for t, is_ok in events:
        if not isinstance(t, int) or isinstance(t, bool) or not isinstance(is_ok, bool):
            raise ValueError("bad event")
        if last_t is not None and t < last_t:
            raise ValueError("decreasing ts")
        last_t = t
        if state == "OPEN":
            if t >= opened_at + cooldown:
                state = "HALF_OPEN"
                half_ok = 0
                transitions.append((t, "HALF_OPEN"))
            else:
                blocked += 1
                continue
        if is_ok:
            ok += 1
            if state == "HALF_OPEN":
                half_ok += 1
                if half_ok >= half_open_needed:
                    state = "CLOSED"
                    fails = 0
                    transitions.append((t, "CLOSED"))
            else:
                fails = 0
        else:
            err += 1
            if state == "HALF_OPEN":
                state = "OPEN"
                opened_at = t
                half_ok = 0
                transitions.append((t, "OPEN"))
            else:
                fails += 1
                if fails >= fail_threshold:
                    state = "OPEN"
                    opened_at = t
                    transitions.append((t, "OPEN"))
    return (state, ok, err, blocked, transitions)
