def compute_sla_downtime(outages, maintenance):
    def merge(ivs):
        valid = []
        for s, e in ivs:
            if not isinstance(s, int) or not isinstance(e, int) or isinstance(s, bool) or isinstance(e, bool) or s > e:
                raise ValueError("bad interval")
            if s < e:
                valid.append((s, e))
        valid.sort()
        res = []
        for s, e in valid:
            if not res or s > res[-1][1]:
                res.append([s, e])
            elif e > res[-1][1]:
                res[-1][1] = e
        return res

    outs = merge(outages)
    ms = merge(maintenance)
    uncovered = []
    total = 0
    j = 0
    for os_, oe in outs:
        cur = os_
        while j < len(ms) and ms[j][1] <= cur:
            j += 1
        k = j
        while k < len(ms) and ms[k][0] < oe:
            ms_, me = ms[k]
            if ms_ > cur:
                uncovered.append((cur, ms_))
                total += ms_ - cur
            if me > cur:
                cur = me
            if cur >= oe:
                break
            k += 1
        if cur < oe:
            uncovered.append((cur, oe))
            total += oe - cur
    return (total, uncovered)
