def prorate_with_residue(total_cents, used_days, total_days, shares):
    if total_cents < 0 or used_days < 0 or total_days <= 0 or used_days > total_days:
        raise ValueError("bad proration params")
    if not shares:
        raise ValueError("empty shares")
    seen = set()
    wsum = 0
    for k, w in shares:
        if not k or k in seen or not isinstance(w, int) or isinstance(w, bool) or w < 0:
            raise ValueError("bad share")
        seen.add(k)
        wsum += w
    if wsum <= 0:
        raise ValueError("weight sum must be > 0")
    prorated = (2 * total_cents * used_days + total_days) // (2 * total_days)
    items = []
    for k, w in shares:
        num = prorated * w
        items.append((k, num // wsum, num % wsum))
    rem = prorated - sum(b for _, b, _ in items)
    ranked = sorted(items, key=lambda x: (-x[2], x[0]))
    bonus = {k: 1 for k, _, _ in ranked[:rem]}
    return {k: b + bonus.get(k, 0) for k, b, _ in items}
