from bisect import bisect_left, insort


def detect_spikes(values, window, mult_num, mult_den, min_delta):
    if window < 1 or mult_num <= 0 or mult_den <= 0 or min_delta < 0:
        raise ValueError("bad params")
    sorted_win = []
    spikes = []
    for i, v in enumerate(values):
        if not isinstance(v, int) or isinstance(v, bool):
            raise ValueError("values must be ints")
        if i >= window:
            med = sorted_win[(window - 1) // 2]
            if v * mult_den >= med * mult_num and v - med >= min_delta:
                spikes.append(i)
            pos = bisect_left(sorted_win, values[i - window])
            sorted_win.pop(pos)
        insort(sorted_win, v)
    return spikes
