def schedule_dep_waves(tasks, deps):
    nodes = set(tasks)
    if len(nodes) != len(tasks):
        raise ValueError("duplicate task")
    adj = {t: [] for t in tasks}
    indeg = {t: 0 for t in tasks}
    for before, after in deps:
        if before not in nodes or after not in nodes:
            raise ValueError("unknown task")
        adj[before].append(after)
        indeg[after] += 1
    ready = sorted(t for t, d in indeg.items() if d == 0)
    waves = []
    done = 0
    while ready:
        waves.append(ready)
        done += len(ready)
        nxt = []
        for u in ready:
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    nxt.append(v)
        ready = sorted(nxt)
    if done != len(tasks):
        raise ValueError("cycle detected")
    return waves
