std::vector<std::string> allocateCarousels(
    int numSlots,
    const std::vector<std::tuple<std::string, int, int, bool>>& flights
) {
    auto sorted = flights;
    std::sort(sorted.begin(), sorted.end(), [](const auto& a, const auto& b) {
        if (std::get<1>(a) != std::get<1>(b)) return std::get<1>(a) < std::get<1>(b);
        return std::get<0>(a) < std::get<0>(b);
    });
    struct SlotOcc { bool used = false; std::string id; int end = 0; bool prio = false; };
    std::vector<SlotOcc> slots(numSlots);
    std::vector<std::string> out;
    for (const auto& f : sorted) {
        const auto& fid = std::get<0>(f);
        int s = std::get<1>(f), e = std::get<2>(f);
        bool prio = std::get<3>(f);
        for (int i = 0; i < numSlots; ++i) {
            if (slots[i].used && slots[i].end <= s) slots[i].used = false;
        }
        int chosen = -1;
        for (int i = 0; i < numSlots; ++i) {
            if (!slots[i].used) { chosen = i; break; }
        }
        std::string evicted = "-";
        if (chosen == -1 && prio) {
            int bestEnd = 0;
            for (int i = 0; i < numSlots; ++i) {
                if (!slots[i].prio && (chosen == -1 || slots[i].end < bestEnd)) {
                    bestEnd = slots[i].end;
                    chosen = i;
                }
            }
            if (chosen != -1) {
                evicted = slots[chosen].id;
                slots[chosen].used = false;
            }
        }
        if (chosen != -1) slots[chosen] = {true, fid, e, prio};
        out.push_back(fid + " " + std::to_string(chosen) + " " + evicted);
    }
    return out;
}
