#include <string>
#include <tuple>
#include <unordered_map>
#include <utility>
#include <vector>

std::vector<std::string> evaluateQuotas(
    const std::vector<std::pair<std::string, long long>>& limits,
    const std::vector<std::tuple<std::string, std::string, long long>>& ops
) {
    std::unordered_map<std::string, long long> limMap, used, sizes;
    for (const auto& [d, lim] : limits) limMap[d] = lim;
    auto ancestors = [](const std::string& path) {
        std::vector<std::string> ds = {"/"};
        for (size_t i = 1; i < path.size(); ++i) {
            if (path[i] == '/') ds.push_back(path.substr(0, i));
        }
        return ds;
    };
    std::vector<std::string> out;
    for (const auto& op : ops) {
        const auto& kind = std::get<0>(op);
        const auto& p = std::get<1>(op);
        long long sz = std::get<2>(op);
        if (kind == "PUT") {
            auto ds = ancestors(p);
            long long prev = sizes.count(p) ? sizes[p] : 0LL;
            long long delta = sz - prev;
            bool ok = true;
            if (delta > 0) {
                for (const auto& d : ds) {
                    auto it = limMap.find(d);
                    if (it != limMap.end() && used[d] + delta > it->second) {
                        ok = false;
                        break;
                    }
                }
            }
            if (!ok) {
                out.push_back("QUOTA_EXCEEDED");
            } else {
                sizes[p] = sz;
                for (const auto& d : ds) used[d] += delta;
                out.push_back("OK");
            }
        } else if (kind == "DEL") {
            auto it = sizes.find(p);
            if (it == sizes.end()) {
                out.push_back("NOT_FOUND");
            } else {
                long long old = it->second;
                sizes.erase(it);
                for (const auto& d : ancestors(p)) used[d] -= old;
                out.push_back("DELETED");
            }
        } else {
            out.push_back(std::to_string(used[p]));
        }
    }
    return out;
}
