#include <queue>
#include <string>
#include <tuple>
#include <vector>

std::vector<std::string> matchOrders(
    const std::vector<std::tuple<std::string, std::string, std::string, long long, long long>>& orders
) {
    struct Entry { long long price; int seq; long long qty; };
    struct BidCmp {
        bool operator()(const Entry& a, const Entry& b) const {
            if (a.price != b.price) return a.price < b.price;
            return a.seq > b.seq;
        }
    };
    struct AskCmp {
        bool operator()(const Entry& a, const Entry& b) const {
            if (a.price != b.price) return a.price > b.price;
            return a.seq > b.seq;
        }
    };
    std::priority_queue<Entry, std::vector<Entry>, BidCmp> bids;
    std::priority_queue<Entry, std::vector<Entry>, AskCmp> asks;
    std::vector<std::string> out;
    int seq = 0;
    for (const auto& ord : orders) {
        const auto& oid = std::get<0>(ord);
        const auto& side = std::get<1>(ord);
        const auto& tif = std::get<2>(ord);
        long long price = std::get<3>(ord), rem = std::get<4>(ord);
        ++seq;
        long long filled = 0;
        if (side == "BUY") {
            while (rem > 0 && !asks.empty() && asks.top().price <= price) {
                Entry top = asks.top();
                asks.pop();
                long long take = std::min(rem, top.qty);
                rem -= take;
                top.qty -= take;
                filled += take;
                if (top.qty > 0) asks.push(top);
            }
            if (rem > 0 && tif == "GTC") bids.push({price, seq, rem});
        } else {
            while (rem > 0 && !bids.empty() && bids.top().price >= price) {
                Entry top = bids.top();
                bids.pop();
                long long take = std::min(rem, top.qty);
                rem -= take;
                top.qty -= take;
                filled += take;
                if (top.qty > 0) bids.push(top);
            }
            if (rem > 0 && tif == "GTC") asks.push({price, seq, rem});
        }
        std::string st = rem == 0 ? "FILLED" : (tif == "IOC" ? "CANCELLED" : (filled > 0 ? "PARTIAL" : "OPEN"));
        out.push_back(oid + " " + std::to_string(filled) + " " + std::to_string(rem) + " " + st);
    }
    return out;
}
