#include <set>
#include <vector>

std::vector<int> detectSpikes(
    const std::vector<long long>& values,
    int window,
    long long multNum,
    long long multDen,
    long long minDelta
) {
    std::multiset<long long> lo, hi;
    int targetLo = (window + 1) / 2;
    auto rebalance = [&]() {
        while ((int)lo.size() > targetLo) {
            auto it = std::prev(lo.end());
            hi.insert(*it);
            lo.erase(it);
        }
        while ((int)lo.size() < targetLo && !hi.empty()) {
            auto it = hi.begin();
            lo.insert(*it);
            hi.erase(it);
        }
    };
    auto add = [&](long long x) {
        if (lo.empty() || x <= *std::prev(lo.end())) lo.insert(x);
        else hi.insert(x);
        rebalance();
    };
    auto removeOne = [&](long long x) {
        auto it = lo.find(x);
        if (it != lo.end()) lo.erase(it);
        else hi.erase(hi.find(x));
        rebalance();
    };
    std::vector<int> spikes;
    for (int i = 0; i < (int)values.size(); ++i) {
        long long v = values[i];
        if (i >= window) {
            long long med = *std::prev(lo.end());
            if ((__int128)v * multDen >= (__int128)med * multNum && v - med >= minDelta) {
                spikes.push_back(i);
            }
            removeOne(values[i - window]);
        }
        add(v);
    }
    return spikes;
}
