std::string runBreakerBudget(
    const std::vector<std::pair<long long, bool>>& events,
    int failThreshold,
    long long cooldown,
    int halfOpenSuccessNeeded
) {
    std::string state = "CLOSED";
    int fails = 0, halfOk = 0;
    long long openedAt = 0, ok = 0, err = 0, blocked = 0;
    for (const auto& [t, isOk] : events) {
