            ++ok;
            if (state == "HALF_OPEN") {
                if (++halfOk >= halfOpenSuccessNeeded) {
                    state = "CLOSED";
                    fails = 0;
                }
            } else {
                fails = 0;
            }
        } else {
            ++err;
            if (state == "HALF_OPEN") {
                state = "OPEN";
                openedAt = t;
                halfOk = 0;
            } else if (++fails >= failThreshold) {
                state = "OPEN";
                openedAt = t;
            }
        }
    }
    return state + " " + std::to_string(ok) + " " + std::to_string(err) + " " + std::to_string(blocked);
