        int ui = idOf[u], vi = idOf[v];
        adj[ui].push_back(vi);
        ++indeg[vi];
    }
    std::vector<int> ready;
    for (int i = 0; i < n; ++i) if (indeg[i] == 0) ready.push_back(i);
    std::vector<std::string> waves;
    int done = 0;
    while (!ready.empty()) {
        std::sort(ready.begin(), ready.end(), [&](int a, int b) { return tasks[a] < tasks[b]; });
        std::string line;
        std::vector<int> next;
        for (int i = 0; i < (int)ready.size(); ++i) {
            if (i) line += ",";
            line += tasks[ready[i]];
            ++done;
            for (int v : adj[ready[i]]) {
                if (--indeg[v] == 0) next.push_back(v);
            }
        }
        waves.push_back(line);
        ready = std::move(next);
    }
    if (done != n) return {"CYCLE"};
    return waves;
