std::vector<long long> nextCronMatches(const std::string& pattern, long long startMinute, int count) {
    auto parseField = [](const std::string& expr, int lo, int hi) {
        std::set<int> allowed;
        std::stringstream ss(expr);
        std::string part;
        while (std::getline(ss, part, ',')) {
            int step = 1;
            auto slash = part.find('/');
            std::string rng = part;
            if (slash != std::string::npos) {
                step = std::stoi(part.substr(slash + 1));
                rng = part.substr(0, slash);
            }
            int a = lo, b = hi;
            if (rng != "*") {
                auto dash = rng.find('-');
                if (dash == std::string::npos) {
                    a = std::stoi(rng);
                    b = (slash != std::string::npos) ? hi : a;
                } else {
                    a = std::stoi(rng.substr(0, dash));
                    b = std::stoi(rng.substr(dash + 1));
                }
            }
            for (int v = a; v <= b; v += step) allowed.insert(v);
        }
        return allowed;
    };
    std::stringstream pss(pattern);
    std::string f0, f1, f2;
    pss >> f0 >> f1 >> f2;
    auto mins = parseField(f0, 0, 59);
    auto hours = parseField(f1, 0, 23);
    auto doms = parseField(f2, 1, 30);
    std::vector<long long> out;
    for (long long t = startMinute; (int)out.size() < count; ++t) {
        int m = (int)(t % 60);
        int h = (int)((t / 60) % 24);
        int d = (int)((t / 1440) % 30) + 1;
        if (mins.count(m) && hours.count(h) && doms.count(d)) out.push_back(t);
    }
    return out;
}
