    start_m, cnt = int(parts[3]), int(parts[4])

    def parse(expr, lo, hi):
        s = set()
        for p in expr.split(","):
            if "/" in p:
                rng, step_s = p.split("/")
                step = int(step_s)
            else:
                rng, step = p, 1
            if rng == "*":
                a, b = lo, hi
            elif "-" in rng:
                a, b = map(int, rng.split("-"))
            else:
                a = int(rng)
                b = hi if "/" in p else a
            for v in range(a, b + 1, step):
                s.add(v)
        return sorted(s)

    ms = sorted(parse(f0, 0, 59))
    hs = sorted(parse(f1, 0, 23))
    ds = sorted(parse(f2, 1, 30))
    ms_set, hs_set, ds_set = set(ms), set(hs), set(ds)
    if not ms or not hs or not ds:
        return
    out = []
    # Jump directly using sorted ticks within the 30-day cycle (43200 minutes)
    cycle_ticks = [((d - 1) * 1440 + h * 60 + m) for d in ds for h in hs for m in ms]
    base_cycle = (start_m // 43200) * 43200
    idx = 0
    rem_start = start_m - base_cycle
