from .paths import ancestors


class QuotaTracker:
    def __init__(self, limits):
        self.limits = dict(limits)
        self.files = {}
        self.used = {}

    def put_file(self, path, size):
        if size < 0:
            raise ValueError("size must be >= 0")
        dirs = ancestors(path)
        delta = size - self.files.get(path, 0)
        for d in dirs:
            self.used[d] = self.used.get(d, 0) + delta
            lim = self.limits.get(d)
            if lim is not None and self.used[d] > lim:
                return False
        self.files[path] = size
        return True

