"""Dependency graph builder."""


def build_graph(tasks, deps):
    nodes = set(tasks)
    adj = {t: [] for t in tasks}
    indeg = {t: 0 for t in tasks}
    for before, after in deps:
        if before not in nodes or after not in nodes:
            raise ValueError("unknown task")
        adj[after].append(before)
        indeg[before] += 1
    return adj, indeg

files.dag/waves.py:
"""Parallel execution wave planner."""

from .graph import build_graph


def plan_waves(tasks, deps):
    adj, indeg = build_graph(tasks, deps)
    ready = sorted((t for t, d in indeg.items() if d == 0), reverse=True)
    waves = []
    while ready:
        waves.append(ready)
        nxt = []
        for u in ready:
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    nxt.append(v)
        ready = sorted(nxt, reverse=True)
    return waves

