"""Half-open interval normalisation."""


def merge_intervals(ivs):
    valid = sorted((s, e) for s, e in ivs if s < e)
    out = []
    for s, e in valid:
        if not out or s >= out[-1][1]:
            out.append([s, e])
        elif e > out[-1][1]:
            out[-1][1] = e
    return [(s, e) for s, e in out]

