"""SLA downtime excluding maintenance."""

from .intervals import merge_intervals


def billable_downtime(outages, maintenance):
    outs = merge_intervals(outages)
    maints = merge_intervals(maintenance)
    segs = []
    total = 0
    for os_, oe in outs:
        cur = os_
        for ms, me in maints:
            if me <= cur:
                continue
            if ms >= oe:
                break
            if ms > cur:
                segs.append((cur, ms))
                total += ms - cur
                cur = me
            if cur >= oe:
                break
        if cur < oe:
            segs.append((cur, oe))
            total += oe - cur
    return total, segs

