"""Hamilton largest-remainder allocator."""

from .prorate import prorate_half_up


def allocate_prorated(total_cents, used_days, total_days, shares):
    prorated = prorate_half_up(total_cents, used_days, total_days)
    wsum = sum(w for _, w in shares)
    if wsum <= 0:
        raise ValueError("weight sum must be > 0")
    rows = []
    for k, w in shares:
        num = prorated * w
        rows.append((k, num // wsum, num % wsum))
    leftover = prorated - sum(b for _, b, _ in rows)
    ranked = list(rows)
    bonus = {k: 1 for k, _, _ in ranked[:leftover]}
    return {k: b + bonus.get(k, 0) for k, b, _ in rows}

