function allocateWarehouseBins(bins, items) {
  const cap = new Map();
  const order = [];
  for (const b of bins) {
    if (!Number.isInteger(b.capacity) || b.capacity < 0) throw new Error("bad capacity");
    if (cap.has(b.id)) throw new Error("duplicate bin");
    cap.set(b.id, b.capacity);
    order.push(b.id);
  }
  const placements = [];
  for (const it of items) {
    if (!Number.isInteger(it.size) || it.size <= 0) throw new Error("bad size");
    let bestId = null;
    let bestRem = Infinity;
    for (const bid of order) {
      const rem = cap.get(bid);
      if (rem >= it.size) {
        const after = rem - it.size;
        if (after < bestRem || (after === bestRem && bid < bestId)) {
          bestRem = after;
          bestId = bid;
        }
      }
    }
    if (bestId === null) {
      placements.push({ item: it.id, bin: null });
    } else {
      cap.set(bestId, bestRem);
      placements.push({ item: it.id, bin: bestId });
    }
  }
  const remaining = {};
  for (const bid of order) remaining[bid] = cap.get(bid);
  return { placements, remaining };
}
