```javascript
function filterLogBurst(records, windowMs, maxPerWindow) {
  if (!Number.isInteger(windowMs) || windowMs <= 0) throw new Error("bad windowMs");
  if (!Number.isInteger(maxPerWindow) || maxPerWindow < 1) throw new Error("bad maxPerWindow");
  const queues = new Map();
  let lastTs = null;
  const out = [];
  for (const rec of records) {
    const { ts, sig } = rec;
    if (!Number.isInteger(ts)) throw new Error("bad ts");
    if (lastTs !== null && ts < lastTs) throw new Error("decreasing ts");
    lastTs = ts;
    if (typeof sig !== "string" || sig.length === 0) throw new Error("bad sig");
    let q = queues.get(sig);
    if (!q) {
      q = [];
      queues.set(sig, q);
    }
    const cutoff = ts - windowMs;
    while (q.length > 0 && q[0] <= cutoff) q.shift();
    if (q.length < maxPerWindow) {
      q.push(ts);
      out.push({ ts, sig, kept: true });
    } else {
      out.push({ ts, sig, kept: false });
    }
  }
  return out;
}
