function buildUserSessions(events, idleGap, maxDuration) {
  if (!Number.isInteger(idleGap) || idleGap < 0) throw new Error("bad idleGap");
  if (!Number.isInteger(maxDuration) || maxDuration < 1) throw new Error("bad maxDuration");
  const byUser = new Map();
  for (const ev of events) {
    if (!Number.isInteger(ev.ts)) throw new Error("bad ts");
    if (!byUser.has(ev.user)) byUser.set(ev.user, []);
    byUser.get(ev.user).push(ev.ts);
  }
  const sessions = [];
  for (const [user, tsList] of byUser.entries()) {
    tsList.sort((a, b) => a - b);
    let start = tsList[0];
    let last = tsList[0];
    let count = 1;
    for (let i = 1; i < tsList.length; i += 1) {
      const t = tsList[i];
      if (t - last > idleGap || t - start >= maxDuration) {
        sessions.push({ user, start, end: last, count });
        start = t;
        last = t;
        count = 1;
      } else {
        last = t;
        count += 1;
      }
    }
    sessions.push({ user, start, end: last, count });
  }
  sessions.sort((a, b) => a.start - b.start || a.user.localeCompare(b.user));
  return sessions;
}
