function processWaitlist(capacity, commands) {
  if (!Number.isInteger(capacity) || capacity < 0) throw new Error("bad capacity");
  const enrolled = new Set();
  const queue = [];
  const inWait = new Set();
  const out = [];
  const promote = () => {
    while (enrolled.size < capacity && queue.length > 0) {
      const nxt = queue.shift();
      inWait.delete(nxt);
      enrolled.add(nxt);
      out.push(`PROMOTE ${nxt}`);
    }
  };
  for (const cmd of commands) {
    const [op, user] = cmd;
    if (op === "JOIN") {
      if (enrolled.has(user) || inWait.has(user)) {
        out.push(`DUP ${user}`);
      } else if (enrolled.size < capacity) {
        enrolled.add(user);
        out.push(`ENROLLED ${user}`);
      } else {
        queue.push(user);
        inWait.add(user);
        out.push(`WAIT ${user}`);
      }
    } else if (op === "LEAVE") {
      if (enrolled.delete(user)) {
        out.push(`LEFT ${user}`);
        promote();
      } else if (inWait.delete(user)) {
        const idx = queue.indexOf(user);
        if (idx !== -1) queue.splice(idx, 1);
        out.push(`UNWAIT ${user}`);
      } else {
        out.push(`MISSING ${user}`);
      }
    } else if (op === "CAP") {
      const newCap = cmd[1];
      if (!Number.isInteger(newCap) || newCap < 0) throw new Error("bad cap");
      capacity = newCap;
      out.push(`CAP ${capacity}`);
      promote();
    } else {
      throw new Error("bad op");
    }
  }
  return { events: out, enrolled: [...enrolled].sort(), waitlist: [...queue] };
}
