function computeTieredWaterBill(prevReading, currReading, tiers) {
  if (!Number.isInteger(prevReading) || !Number.isInteger(currReading) || prevReading < 0 || currReading < prevReading) {
    throw new Error("bad readings");
  }
  if (!Array.isArray(tiers) || tiers.length === 0) throw new Error("bad tiers");
  let prevTop = 0;
  let rem = currReading - prevReading;
  let total = 0;
  const breakdown = [];
  for (let i = 0; i < tiers.length; i += 1) {
    const { upTo, rateCents } = tiers[i];
    if (!Number.isInteger(rateCents) || rateCents < 0) throw new Error("bad rate");
    if (upTo === null) {
      if (i !== tiers.length - 1) throw new Error("unbounded tier must be last");
      const units = rem;
      const charge = units * rateCents;
      total += charge;
      if (units > 0) breakdown.push({ tier: i, units, charge });
      rem = 0;
    } else {
      if (!Number.isInteger(upTo) || upTo <= prevTop) throw new Error("non-increasing upTo");
      const cap = upTo - prevTop;
      const units = Math.min(rem, cap);
      const charge = units * rateCents;
      total += charge;
      if (units > 0) breakdown.push({ tier: i, units, charge });
      rem -= units;
      prevTop = upTo;
    }
  }
  if (rem > 0) throw new Error("usage exceeds tier coverage");
  return { usage: currReading - prevReading, totalCents: total, breakdown };
}
