function ageReceivables(invoices, asOfDay) {
  if (!Number.isInteger(asOfDay)) throw new Error("bad asOfDay");
  const buckets = { current: 0, d1_30: 0, d31_60: 0, d61_90: 0, d91_plus: 0 };
  const byCustomer = new Map();
  for (const inv of invoices) {
    if (!Number.isInteger(inv.dueDay) || !Number.isInteger(inv.amount) || !Number.isInteger(inv.paid)) {
      throw new Error("bad invoice");
    }
    if (inv.amount < 0 || inv.paid < 0 || inv.paid > inv.amount) throw new Error("bad paid/amount");
    const open = inv.amount - inv.paid;
    if (open === 0) continue;
    const overdue = asOfDay - inv.dueDay;
    const key =
      overdue <= 0 ? "current" :
      overdue <= 30 ? "d1_30" :
      overdue <= 60 ? "d31_60" :
      overdue <= 90 ? "d61_90" : "d91_plus";
    buckets[key] += open;
    if (!byCustomer.has(inv.customer)) {
      byCustomer.set(inv.customer, { current: 0, d1_30: 0, d31_60: 0, d61_90: 0, d91_plus: 0, total: 0 });
    }
    const c = byCustomer.get(inv.customer);
    c[key] += open;
    c.total += open;
