interface BinSpec {
  id: string;
  capacity: number;
}
interface ItemSpec {
  id: string;
  size: number;
}
interface BinResult {
  placements: Array<{ item: string; bin: string | null }>;
  remaining: Record<string, number>;
}

function packWarehouseBins(bins: BinSpec[], items: ItemSpec[]): BinResult {
  const cap = new Map<string, number>();
  const order: string[] = [];
  for (const b of bins) {
    if (!Number.isInteger(b.capacity) || b.capacity < 0) throw new Error("bad capacity");
    if (cap.has(b.id)) throw new Error("duplicate bin");
    cap.set(b.id, b.capacity);
    order.push(b.id);
  }
  const placements: Array<{ item: string; bin: string | null }> = [];
  for (const it of items) {
    if (!Number.isInteger(it.size) || it.size <= 0) throw new Error("bad size");
    let bestId: string | null = null;
    let bestRem = Infinity;
    for (const bid of order) {
      const rem = cap.get(bid)!;
      if (rem >= it.size) {
        const after = rem - it.size;
        if (after < bestRem || (after === bestRem && (bestId === null || bid < bestId))) {
          bestRem = after;
          bestId = bid;
        }
      }
    }
    if (bestId === null) {
      placements.push({ item: it.id, bin: null });
    } else {
      cap.set(bestId, bestRem);
      placements.push({ item: it.id, bin: bestId });
    }
  }
  const remaining: Record<string, number> = {};
  for (const bid of order) remaining[bid] = cap.get(bid)!;
  return { placements, remaining };
}
