type QuotaOp =
  | { type: "PUT"; path: string; size: number }
  | { type: "DEL"; path: string }
  | { type: "USAGE"; dir: string };

function runQuotaOps(limits: Record<string, number>, ops: QuotaOp[]): Array<string | number> {
  const sizes = new Map<string, number>();
  const used = new Map<string, number>();
  const limitMap = new Map<string, number>();
  for (const [d, lim] of Object.entries(limits)) {
    if (!Number.isInteger(lim) || lim < 0) throw new Error("bad limit");
    limitMap.set(d, lim);
  }
  const ancestors = (path: string): string[] => {
    if (!path.startsWith("/") || path === "/" || path.endsWith("/")) throw new Error("bad path");
    const parts = path.split("/").slice(1);
    if (parts.some((p) => p.length === 0)) throw new Error("empty segment");
    const dirs = ["/"];
    let cur = "";
    for (let i = 0; i < parts.length - 1; i += 1) {
      cur += "/" + parts[i];
      dirs.push(cur);
    }
    return dirs;
  };
  const out: Array<string | number> = [];
  for (const op of ops) {
    if (op.type === "PUT") {
      if (!Number.isInteger(op.size) || op.size < 0) throw new Error("bad size");
      const dirs = ancestors(op.path);
      const prev = sizes.get(op.path) ?? 0;
      const delta = op.size - prev;
      let ok = true;
      if (delta > 0) {
        for (const d of dirs) {
          const lim = limitMap.get(d);
          if (lim !== undefined && (used.get(d) ?? 0) + delta > lim) {
            ok = false;
            break;
          }
        }
      }
      if (!ok) {
        out.push("QUOTA_EXCEEDED");
      } else {
        sizes.set(op.path, op.size);
        for (const d of dirs) used.set(d, (used.get(d) ?? 0) + delta);
        out.push("OK");
      }
    } else if (op.type === "DEL") {
      const dirs = ancestors(op.path);
      const prev = sizes.get(op.path);
      if (prev === undefined) {
        out.push("NOT_FOUND");
      } else {
        sizes.delete(op.path);
        for (const d of dirs) used.set(d, (used.get(d) ?? 0) - prev);
        out.push("DELETED");
      }
    } else if (op.type === "USAGE") {
      out.push(used.get(op.dir) ?? 0);
    } else {
      throw new Error("bad op");
    }
  }
  return out;
}
