interface OpenInvoice {
  customer: string;
  dueDay: number;
  amount: number;
  paid: number;
}
interface AgeingTotals {
  current: number;
  d1_30: number;
  d31_60: number;
  d61_90: number;
  d91_plus: number;
}

function computeAgeing(
  invoices: OpenInvoice[],
  asOfDay: number
): { totals: AgeingTotals; customers: Array<AgeingTotals & { customer: string; total: number }> } {
  if (!Number.isInteger(asOfDay)) throw new Error("bad asOfDay");
  const totals: AgeingTotals = { current: 0, d1_30: 0, d31_60: 0, d61_90: 0, d91_plus: 0 };
  const byCust = new Map<string, AgeingTotals & { total: number }>();
  for (const inv of invoices) {
    if (!Number.isInteger(inv.dueDay) || !Number.isInteger(inv.amount) || !Number.isInteger(inv.paid)) {
      throw new Error("bad invoice");
    }
    if (inv.amount < 0 || inv.paid < 0 || inv.paid > inv.amount) throw new Error("bad amounts");
    const open = inv.amount - inv.paid;
    if (open === 0) continue;
    const od = asOfDay - inv.dueDay;
    const key: keyof AgeingTotals =
      od <= 0 ? "current" : od <= 30 ? "d1_30" : od <= 60 ? "d31_60" : od <= 90 ? "d61_90" : "d91_plus";
    totals[key] += open;
    if (!byCust.has(inv.customer)) {
      byCust.set(inv.customer, { current: 0, d1_30: 0, d31_60: 0, d61_90: 0, d91_plus: 0, total: 0 });
    }
    const c = byCust.get(inv.customer)!;
    c[key] += open;
    c.total += open;
  }
  const customers = [...byCust.entries()]
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([customer, stats]) => ({ customer, ...stats }));
  return { totals, customers };
}
