interface WaterTier {
  upTo: number | null;
  rateCents: number;
}
interface WaterBill {
  usage: number;
  totalCents: number;
  breakdown: Array<{ tier: number; units: number; charge: number }>;
}

function calcWaterBill(prevReading: number, currReading: number, tiers: WaterTier[]): WaterBill {
  if (!Number.isInteger(prevReading) || !Number.isInteger(currReading) || prevReading < 0 || currReading < prevReading) {
    throw new Error("bad readings");
  }
  if (tiers.length === 0) throw new Error("empty tiers");
  let prevTop = 0;
  let rem = currReading - prevReading;
  let total = 0;
  const breakdown: Array<{ tier: number; units: number; charge: number }> = [];
  for (let i = 0; i < tiers.length; i += 1) {
    const { upTo, rateCents } = tiers[i];
    if (!Number.isInteger(rateCents) || rateCents < 0) throw new Error("bad rate");
    if (upTo === null) {
      if (i !== tiers.length - 1) throw new Error("null must be last");
      const units = rem;
      const charge = units * rateCents;
      total += charge;
      if (units > 0) breakdown.push({ tier: i, units, charge });
      rem = 0;
    } else {
      if (!Number.isInteger(upTo) || upTo <= prevTop) throw new Error("bad upTo");
      const units = Math.min(rem, upTo - prevTop);
      const charge = units * rateCents;
      total += charge;
      if (units > 0) breakdown.push({ tier: i, units, charge });
      rem -= units;
      prevTop = upTo;
    }
  }
  if (rem > 0) throw new Error("usage exceeds finite tiers");
  return { usage: currReading - prevReading, totalCents: total, breakdown };
}
