type WaitCmd = ["JOIN", string] | ["LEAVE", string] | ["CAP", number];

function runWaitlist(
  capacity: number,
  commands: WaitCmd[]
): { events: string[]; enrolled: string[]; waitlist: string[] } {
  if (!Number.isInteger(capacity) || capacity < 0) throw new Error("bad capacity");
  const enrolled = new Set<string>();
  const queue: string[] = [];
  const inWait = new Set<string>();
  const events: string[] = [];
  const promote = () => {
    while (enrolled.size < capacity && queue.length > 0) {
      const nxt = queue.shift()!;
      inWait.delete(nxt);
      enrolled.add(nxt);
      events.push(`PROMOTE ${nxt}`);
    }
  };
  for (const cmd of commands) {
    if (cmd[0] === "JOIN") {
      const user = cmd[1];
      if (enrolled.has(user) || inWait.has(user)) {
        events.push(`DUP ${user}`);
      } else if (enrolled.size < capacity) {
        enrolled.add(user);
        events.push(`ENROLLED ${user}`);
      } else {
        queue.push(user);
        inWait.add(user);
        events.push(`WAIT ${user}`);
      }
    } else if (cmd[0] === "LEAVE") {
      const user = cmd[1];
      if (enrolled.delete(user)) {
        events.push(`LEFT ${user}`);
        promote();
      } else if (inWait.delete(user)) {
        const idx = queue.indexOf(user);
        if (idx !== -1) queue.splice(idx, 1);
        events.push(`UNWAIT ${user}`);
      } else {
        events.push(`MISSING ${user}`);
      }
    } else if (cmd[0] === "CAP") {
      const newCap = cmd[1];
      if (!Number.isInteger(newCap) || newCap < 0) throw new Error("bad cap");
      capacity = newCap;
      events.push(`CAP ${capacity}`);
      promote();
    } else {
      throw new Error("bad op");
    }
  }
  return { events, enrolled: [...enrolled].sort(), waitlist: [...queue] };
}
