```typescript
type ParcelStatus =
  | "CREATED"
  | "PICKED_UP"
  | "IN_TRANSIT"
  | "OUT_FOR_DELIVERY"
  | "DELIVERED"
  | "RETURNED"
  | "CANCELLED";

interface ParcelEvent {
  ts: number;
  status: ParcelStatus;
  hub?: string;
}

function validateParcelTrace(events: ParcelEvent[]): { state: ParcelStatus; hops: number; lastHub: string | null } {
  const allowed: Record<ParcelStatus, Set<ParcelStatus>> = {
    CREATED: new Set(["PICKED_UP", "CANCELLED"]),
    PICKED_UP: new Set(["IN_TRANSIT", "CANCELLED"]),
    IN_TRANSIT: new Set(["IN_TRANSIT", "OUT_FOR_DELIVERY", "RETURNED"]),
    OUT_FOR_DELIVERY: new Set(["DELIVERED", "IN_TRANSIT", "RETURNED"]),
    DELIVERED: new Set(),
    RETURNED: new Set(),
    CANCELLED: new Set(),
  };
  let state: ParcelStatus = "CREATED";
  let lastTs: number | null = null;
  let hops = 0;
  let lastHub: string | null = null;
  for (const ev of events) {
    if (!Number.isInteger(ev.ts)) throw new Error("bad ts");
    if (lastTs !== null && ev.ts < lastTs) throw new Error("decreasing ts");
    lastTs = ev.ts;
    if (!(ev.status in allowed)) throw new Error("unknown status");
    if (!allowed[state].has(ev.status)) throw new Error("invalid transition");
    state = ev.status;
    if (ev.hub) lastHub = ev.hub;
    if (ev.status === "IN_TRANSIT") hops += 1;
  }
  return { state, hops, lastHub };
}
