def allocate_warehouse_bins(bins, items):
    cap = {}
    order = []
    for bid, c in bins:
        if not isinstance(c, int) or isinstance(c, bool) or c < 0:
            raise ValueError("bad capacity")
        if bid in cap:
            raise ValueError("duplicate bin")
        cap[bid] = c
        order.append(bid)
    placements = []
    for iid, sz in items:
        if not isinstance(sz, int) or isinstance(sz, bool) or sz <= 0:
            raise ValueError("bad size")
        best_id = None
        best_rem = None
        for bid in order:
            rem = cap[bid]
            if rem >= sz:
                after = rem - sz
                if best_rem is None or after < best_rem or (after == best_rem and bid < best_id):
                    best_rem = after
                    best_id = bid
        if best_id is None:
            placements.append((iid, None))
        else:
            cap[best_id] = best_rem
            placements.append((iid, best_id))
    return (placements, {bid: cap[bid] for bid in order})
