def build_user_sessions(events, idle_gap, max_duration):
    if not isinstance(idle_gap, int) or isinstance(idle_gap, bool) or idle_gap < 0:
        raise ValueError("bad idle_gap")
    if not isinstance(max_duration, int) or isinstance(max_duration, bool) or max_duration < 1:
        raise ValueError("bad max_duration")
    by_user = {}
    for user, ts in events:
        if not isinstance(ts, int) or isinstance(ts, bool):
            raise ValueError("bad ts")
        by_user.setdefault(user, []).append(ts)
    sessions = []
    for user, ts_list in by_user.items():
        ts_list.sort()
        start = last = ts_list[0]
        count = 1
        for t in ts_list[1:]:
            if t - last > idle_gap or t - start >= max_duration:
                sessions.append((user, start, last, count))
                start = last = t
                count = 1
            else:
                last = t
                count += 1
        sessions.append((user, start, last, count))
    sessions.sort(key=lambda s: (s[1], s[0]))
    return sessions
