def age_receivables(invoices, as_of_day):
    if not isinstance(as_of_day, int) or isinstance(as_of_day, bool):
        raise ValueError("bad as_of_day")
    totals = [0, 0, 0, 0, 0]
    by_cust = {}
    for cust, due, amt, paid in invoices:
        if any(not isinstance(x, int) or isinstance(x, bool) for x in (due, amt, paid)):
            raise ValueError("bad invoice")
        if amt < 0 or paid < 0 or paid > amt:
            raise ValueError("bad amounts")
        rem = amt - paid
        if rem == 0:
            continue
        od = as_of_day - due
        if od <= 0:
            idx = 0
        elif od <= 30:
            idx = 1
        elif od <= 60:
            idx = 2
        elif od <= 90:
            idx = 3
        else:
            idx = 4
        totals[idx] += rem
        row = by_cust.setdefault(cust, [0, 0, 0, 0, 0])
        row[idx] += rem
    customers = [(c, *by_cust[c], sum(by_cust[c])) for c in sorted(by_cust)]
    return (tuple(totals), customers)
