def compute_water_bill(prev_reading, curr_reading, tiers):
    if any(not isinstance(x, int) or isinstance(x, bool) for x in (prev_reading, curr_reading)):
        raise ValueError("bad reading type")
    if prev_reading < 0 or curr_reading < prev_reading:
        raise ValueError("bad readings")
    if not tiers:
        raise ValueError("empty tiers")
    prev_top = 0
    rem = curr_reading - prev_reading
    total = 0
    breakdown = []
    for i, (upto, rate) in enumerate(tiers):
        if not isinstance(rate, int) or isinstance(rate, bool) or rate < 0:
            raise ValueError("bad rate")
        if upto is None:
            if i != len(tiers) - 1:
                raise ValueError("unbounded tier must be last")
            units = rem
            rem = 0
        else:
            if not isinstance(upto, int) or isinstance(upto, bool) or upto <= prev_top:
                raise ValueError("bad up_to")
            units = min(rem, upto - prev_top)
            rem -= units
            prev_top = upto
        charge = units * rate
        total += charge
        if units > 0:
            breakdown.append((i, units, charge))
    if rem > 0:
        raise ValueError("usage exceeds finite tiers")
    return (curr_reading - prev_reading, total, breakdown)
