from collections import deque


def process_waitlist(capacity, commands):
    if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 0:
        raise ValueError("bad capacity")
    enrolled = set()
    in_wait = set()
    queue = deque()
    events = []

    def promote():
        while len(enrolled) < capacity and queue:
            nxt = queue.popleft()
            if nxt in in_wait:
                in_wait.remove(nxt)
                enrolled.add(nxt)
                events.append(("PROMOTE", nxt))

    for cmd in commands:
        op = cmd[0]
        if op == "JOIN":
            user = cmd[1]
            if user in enrolled or user in in_wait:
                events.append(("DUP", user))
            elif len(enrolled) < capacity:
                enrolled.add(user)
                events.append(("ENROLLED", user))
            else:
                in_wait.add(user)
                queue.append(user)
                events.append(("WAIT", user))
        elif op == "LEAVE":
            user = cmd[1]
            if user in enrolled:
                enrolled.remove(user)
                events.append(("LEFT", user))
                promote()
            elif user in in_wait:
                in_wait.remove(user)
                events.append(("UNWAIT", user))
            else:
                events.append(("MISSING", user))
        elif op == "CAP":
            new_cap = cmd[1]
            if not isinstance(new_cap, int) or isinstance(new_cap, bool) or new_cap < 0:
                raise ValueError("bad cap")
            capacity = new_cap
            events.append(("CAP", capacity))
            promote()
        else:
            raise ValueError("unknown op")
    return (events, sorted(enrolled), [u for u in queue if u in in_wait])
