from collections import deque


def filter_log_burst(records, window_ms, max_per_window):
    if not isinstance(window_ms, int) or isinstance(window_ms, bool) or window_ms <= 0:
        raise ValueError("bad window_ms")
    if not isinstance(max_per_window, int) or isinstance(max_per_window, bool) or max_per_window < 1:
        raise ValueError("bad max_per_window")
    queues = {}
    last_ts = None
    out = []
    for ts, sig in records:
        if not isinstance(ts, int) or isinstance(ts, bool) or not isinstance(sig, str) or not sig:
            raise ValueError("bad record")
        if last_ts is not None and ts < last_ts:
            raise ValueError("decreasing ts")
        last_ts = ts
        q = queues.setdefault(sig, deque())
        cutoff = ts - window_ms
        while q and q[0] <= cutoff:
            q.popleft()
        if len(q) < max_per_window:
            q.append(ts)
            out.append((ts, sig, True))
        else:
            out.append((ts, sig, False))
    return out
