#include <string>
#include <utility>
#include <vector>

std::vector<std::string> packWarehouseBins(
    const std::vector<std::pair<std::string, int>>& bins,
    const std::vector<std::pair<std::string, int>>& items
) {
    auto rem = bins;
    std::vector<std::string> out;
    for (const auto& [iid, sz] : items) {
        int bestIdx = -1;
        int bestRem = 0;
        for (int i = 0; i < (int)rem.size(); ++i) {
            if (rem[i].second >= sz) {
                int after = rem[i].second - sz;
                if (bestIdx == -1 || after < bestRem || (after == bestRem && rem[i].first < rem[bestIdx].first)) {
                    bestRem = after;
                    bestIdx = i;
                }
            }
        }
        if (bestIdx == -1) {
            out.push_back(iid + ":NONE");
        } else {
            rem[bestIdx].second = bestRem;
            out.push_back(iid + ":" + rem[bestIdx].first);
        }
    }
    return out;
}
