#include <algorithm>
#include <map>
#include <string>
#include <tuple>
#include <utility>
#include <vector>

std::vector<std::string> summarizeSessions(
    const std::vector<std::pair<std::string, long long>>& events,
    long long idleGap,
    long long maxDuration
) {
    std::map<std::string, std::vector<long long>> byUser;
    for (const auto& [u, t] : events) byUser[u].push_back(t);
    std::vector<std::tuple<long long, std::string, long long, int>> sess;
    for (auto& [u, ts] : byUser) {
        std::sort(ts.begin(), ts.end());
        long long s = ts[0], l = ts[0];
        int cnt = 1;
        for (size_t i = 1; i < ts.size(); ++i) {
            long long t = ts[i];
            if (t - l > idleGap || t - s >= maxDuration) {
                sess.emplace_back(s, u, l, cnt);
                s = l = t;
                cnt = 1;
            } else {
                l = t;
                ++cnt;
            }
        }
        sess.emplace_back(s, u, l, cnt);
    }
    std::sort(sess.begin(), sess.end());
    std::vector<std::string> out;
    for (const auto& [s, u, l, cnt] : sess) {
        out.push_back(u + " " + std::to_string(s) + " " + std::to_string(l) + " " + std::to_string(cnt));
    }
    return out;
}
