    long long currReading,
    const std::vector<std::pair<long long, long long>>& tiers
) {
    long long rem = currReading - prevReading;
    long long prevTop = 0;
    long long total = 0;
    for (const auto& [upto, rate] : tiers) {
        long long units = 0;
        if (upto < 0) {
            units = rem;
            rem = 0;
        } else {
            units = std::min(rem, upto - prevTop);
            rem -= units;
            prevTop = upto;
        }
        total += units * rate;
    }
    return total;
}
