#include <vector>

std::vector<std::string> runWaitlist(
    int capacity,
    const std::vector<std::pair<std::string, std::string>>& commands
) {
    std::set<std::string> enrolled, inWait;
    std::deque<std::string> q;
    std::vector<std::string> out;
    auto promote = [&]() {
        while ((int)enrolled.size() < capacity && !q.empty()) {
            std::string nxt = q.front();
            q.pop_front();
            if (inWait.erase(nxt)) {
                enrolled.insert(nxt);
                out.push_back("PROMOTE " + nxt);
            }
        }
    };
    for (const auto& [op, arg] : commands) {
        if (op == "JOIN") {
            if (enrolled.count(arg) || inWait.count(arg)) {
                out.push_back("DUP " + arg);
            } else if ((int)enrolled.size() < capacity) {
                enrolled.insert(arg);
                out.push_back("ENROLLED " + arg);
            } else {
                inWait.insert(arg);
                q.push_back(arg);
                out.push_back("WAIT " + arg);
            }
        } else if (op == "LEAVE") {
            if (enrolled.erase(arg)) {
                out.push_back("LEFT " + arg);
                promote();
            } else if (inWait.erase(arg)) {
                out.push_back("UNWAIT " + arg);
            } else {
                out.push_back("MISSING " + arg);
            }
        } else {
            capacity = std::stoi(arg);
            out.push_back("CAP " + std::to_string(capacity));
            promote();
        }
    }
    return out;
}
