#include <algorithm>
#include <unordered_map>
#include <vector>

std::vector<long long> simulateStockReorder(
    long long initialStock,
    long long reorderPoint,
    long long targetStock,
    int leadDays,
    const std::vector<long long>& dailyDemand
) {
    long long stock = initialStock, onOrder = 0, stockouts = 0, orders = 0;
    std::unordered_map<int, long long> arrivals;
    for (int d = 0; d < (int)dailyDemand.size(); ++d) {
        auto it = arrivals.find(d);
        if (it != arrivals.end()) {
            stock += it->second;
            onOrder -= it->second;
        }
        long long dem = dailyDemand[d];
        long long sold = std::min(stock, dem);
        stockouts += dem - sold;
        stock -= sold;
        if (stock + onOrder <= reorderPoint) {
            long long q = targetStock - (stock + onOrder);
            onOrder += q;
            ++orders;
            arrivals[d + leadDays] += q;
        }
    }
    return {stock, stockouts, orders};
}
