std::vector<bool> filterLogBurst(
    const std::vector<std::pair<long long, std::string>>& records,
    long long windowMs,
    int maxPerWindow
) {
    std::unordered_map<std::string, std::deque<long long>> qs;
    std::vector<bool> out;
    out.reserve(records.size());
    for (const auto& [ts, sig] : records) {
        auto& q = qs[sig];
        long long cutoff = ts - windowMs;
        while (!q.empty() && q.front() <= cutoff) q.pop_front();
        if ((int)q.size() < maxPerWindow) {
            q.push_back(ts);
            out.push_back(true);
        } else {
            out.push_back(false);
        }
    }
    return out;
}
