#include <algorithm>
#include <utility>
#include <vector>

long long computeSlaDowntime(
    const std::vector<std::pair<long long, long long>>& outages,
    const std::vector<std::pair<long long, long long>>& maintenance
) {
    auto merge = [](const std::vector<std::pair<long long, long long>>& ivs) {
        std::vector<std::pair<long long, long long>> v;
        for (auto [s, e] : ivs) if (s < e) v.emplace_back(s, e);
        std::sort(v.begin(), v.end());
        std::vector<std::pair<long long, long long>> res;
        for (auto [s, e] : v) {
            if (res.empty() || s > res.back().second) res.emplace_back(s, e);
            else res.back().second = std::max(res.back().second, e);
        }
        return res;
    };
    auto outs = merge(outages);
    auto ms = merge(maintenance);
    long long total = 0;
    size_t j = 0;
    for (auto [os, oe] : outs) {
        long long cur = os;
        while (j < ms.size() && ms[j].second <= cur) ++j;
        size_t k = j;
        while (k < ms.size() && ms[k].first < oe) {
            auto [ms_, me] = ms[k];
            if (ms_ > cur) total += ms_ - cur;
            if (me > cur) cur = me;
            if (cur >= oe) break;
            ++k;
        }
        if (cur < oe) total += oe - cur;
    }
    return total;
}
