"""Warehouse bin allocator."""

from .scoring import rank_key


class BinAllocator:
    def __init__(self, capacities):
        self.cap = dict(capacities)

    def place(self, item_size):
        cands = [
            (rank_key(bid, rem, item_size), bid)
            for bid, rem in self.cap.items()
            if rem >= item_size
        ]
        if not cands:
            return None
        cands.sort()
        pick = cands[0][1]
        self.cap[pick] -= item_size
        return pick

    def reserve_batch(self, items):
        picks = []
        for item_id, size in items:
            bid = self.place(size)
            if bid is None:
                return None
            picks.append((item_id, bid))
        return picks

