"""Payout splitting with platform fee."""

from .weights import largest_remainder_order


def split_payout(gross_cents, fee_bps, shares):
    if gross_cents < 0 or fee_bps < 0 or fee_bps > 10000:
        raise ValueError("invalid arguments")
    total_w = sum(w for _, w in shares)
    if total_w <= 0:
        raise ValueError("total weight must be positive")
    base = {}
    rems = []
    for rid, w in shares:
        num = gross_cents * w
        base[rid] = num // total_w
        rems.append((rid, num % total_w))
    leftover = gross_cents - sum(base.values())
    for rid in largest_remainder_order(rems)[:leftover]:
        base[rid] += 1
    fee = (gross_cents * fee_bps) // 10000
    return {"fee": fee, "net": gross_cents - fee, "payouts": base}

