"""FIFO wait queue with membership tracking."""

from collections import deque


class WaitQueue:
    def __init__(self):
        self._q = deque()
        self._members = set()

    def add(self, user):
        if user in self._members:
            return False
        self._members.add(user)
        self._q.appendleft(user)
        return True

    def remove(self, user):
        if user not in self._members:
            return False
        self._members.remove(user)
        return True

    def pop_next(self):
        while self._q:
            u = self._q.popleft()
            if u in self._members:
                self._members.remove(u)
                return u
        return None

    def __contains__(self, user):
        return user in self._members

