"""Course enrollment and waitlist promotion."""

from .queue import WaitQueue


class CourseRoster:
    def __init__(self, capacity):
        self.capacity = capacity
        self.enrolled = set()
        self.wait = WaitQueue()

    def _promote(self):
        promoted = []
        while len(self.enrolled) < self.capacity:
            nxt = self.wait.pop_next()
            if nxt is None:
                break
            self.enrolled.add(nxt)
            promoted.append(nxt)
        return promoted

    def join(self, user):
        if user in self.enrolled or user in self.wait:
            return ("DUP", [])
        if len(self.enrolled) < self.capacity:
            self.enrolled.add(user)
            return ("ENROLLED", [])
        self.wait.add(user)
        return ("WAIT", [])

    def leave(self, user):
        if user in self.enrolled:
            self.enrolled.remove(user)
            return ("LEFT", self._promote())
        if self.wait.remove(user):
            return ("UNWAIT", [])
        return ("MISSING", [])

    def set_capacity(self, new_cap):
        self.capacity = new_cap
        while len(self.enrolled) > self.capacity:
            self.enrolled.pop()
        return self._promote()

