```typescript
interface TruckSpec {
  id: string;
  arrival: number;
  duration: number;
}
interface DockAssignment {
  id: string;
  dock: number;
  start: number;
  end: number;
}

function scheduleFreightDocks(numDocks: number, trucks: TruckSpec[]): DockAssignment[] {
  if (!Number.isInteger(numDocks) || numDocks <= 0) throw new Error("bad numDocks");
  const sorted = trucks.map((t) => {
    if (!Number.isInteger(t.arrival) || t.arrival < 0 || !Number.isInteger(t.duration) || t.duration <= 0) {
      throw new Error("bad truck");
    }
    return { ...t };
  });
  sorted.sort((a, b) => (a.arrival !== b.arrival ? a.arrival - b.arrival : a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  const free = new Array<number>(numDocks).fill(0);
  const out: DockAssignment[] = [];
  for (const t of sorted) {
    let bestDock = 0;
    for (let d = 1; d < numDocks; d += 1) {
      if (free[d] < free[bestDock]) bestDock = d;
    }
    const start = Math.max(t.arrival, free[bestDock]);
    const end = start + t.duration;
    free[bestDock] = end;
    out.push({ id: t.id, dock: bestDock, start, end });
  }
  out.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return out;
}
