interface LineWeight {
  id: string;
  weight: number;
}

function prorateCents(totalCents: number, items: LineWeight[]): Record<string, number> {
  if (!Number.isInteger(totalCents) || totalCents < 0) throw new Error("bad total");
  const seen = new Set<string>();
  let totalW = 0;
  for (const it of items) {
    if (seen.has(it.id)) throw new Error("duplicate id");
    seen.add(it.id);
    if (!Number.isInteger(it.weight) || it.weight < 0) throw new Error("bad weight");
    totalW += it.weight;
  }
  const out: Record<string, number> = {};
  if (totalW === 0) {
    for (const it of items) out[it.id] = 0;
    return out;
  }
  const rems: Array<{ id: string; rem: number }> = [];
  let assigned = 0;
  for (const it of items) {
    const prod = totalCents * it.weight;
    const base = Math.floor(prod / totalW);
    out[it.id] = base;
    assigned += base;
    rems.push({ id: it.id, rem: prod % totalW });
  }
  rems.sort((a, b) => (b.rem !== a.rem ? b.rem - a.rem : a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  const leftover = totalCents - assigned;
  for (let i = 0; i < leftover; i += 1) {
    out[rems[i].id] += 1;
  }
  return out;
}
