interface Snapshot {
  id: string;
  ts: number;
  size: number;
}
interface RetentionPlan {
  kept: string[];
  used: number;
  dropped: string[];
}

function planRetention(snapshots: Snapshot[], budget: number): RetentionPlan {
  if (!Number.isInteger(budget) || budget < 0) throw new Error("bad budget");
  const seen = new Set<string>();
  const items = snapshots.map((s) => {
    if (seen.has(s.id)) throw new Error("duplicate id");
    seen.add(s.id);
    if (!Number.isInteger(s.ts) || !Number.isInteger(s.size) || s.size <= 0) throw new Error("bad snapshot");
    return { ...s };
  });
  items.sort((a, b) => (b.ts !== a.ts ? b.ts - a.ts : a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  let used = 0;
  const keptItems: Snapshot[] = [];
  const droppedItems: Snapshot[] = [];
  for (const it of items) {
    if (used + it.size <= budget) {
      used += it.size;
      keptItems.push(it);
    } else {
      droppedItems.push(it);
    }
  }
  const byChron = (a: Snapshot, b: Snapshot) => (a.ts !== b.ts ? a.ts - b.ts : a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
  keptItems.sort(byChron);
  droppedItems.sort(byChron);
  return {
    kept: keptItems.map((x) => x.id),
    used,
    dropped: droppedItems.map((x) => x.id),
  };
}
