function planDeployWaves(tasks: string[], edges: Array<[string, string]>): string[][] {
  const adj = new Map<string, string[]>();
  const indeg = new Map<string, number>();
  for (const t of tasks) {
    if (adj.has(t)) throw new Error("duplicate task");
    adj.set(t, []);
    indeg.set(t, 0);
  }
  for (const [dep, target] of edges) {
    if (!adj.has(dep) || !adj.has(target)) throw new Error("unknown task");
    adj.get(dep)!.push(target);
    indeg.set(target, indeg.get(target)! + 1);
  }
  let ready: string[] = [];
  for (const [t, d] of indeg.entries()) {
    if (d === 0) ready.push(t);
  }
  ready.sort();
  const waves: string[][] = [];
  let done = 0;
  while (ready.length > 0) {
    waves.push(ready);
    done += ready.length;
    const nxt: string[] = [];
    for (const u of ready) {
      for (const v of adj.get(u)!) {
        const d = indeg.get(v)! - 1;
        indeg.set(v, d);
        if (d === 0) nxt.push(v);
      }
    }
    nxt.sort();
    ready = nxt;
  }
  if (done !== tasks.length) throw new Error("cycle detected");
  return waves;
}
