interface AlertEvent {
  ts: number;
  key: string;
}
interface EmittedAlert {
  ts: number;
  key: string;
  suppressed: number;
}

function deduplicateAlerts(events: AlertEvent[], cooldown: number): EmittedAlert[] {
  if (!Number.isInteger(cooldown) || cooldown <= 0) throw new Error("bad cooldown");
  const lastEmit = new Map<string, number>();
  const sup = new Map<string, number>();
  const out: EmittedAlert[] = [];
  let prevTs: number | null = null;
  for (const ev of events) {
    if (!Number.isInteger(ev.ts)) throw new Error("bad ts");
    if (prevTs !== null && ev.ts < prevTs) throw new Error("decreasing ts");
    prevTs = ev.ts;
    const prev = lastEmit.get(ev.key);
    if (prev === undefined || ev.ts >= prev + cooldown) {
      out.push({ ts: ev.ts, key: ev.key, suppressed: sup.get(ev.key) ?? 0 });
      lastEmit.set(ev.key, ev.ts);
      sup.set(ev.key, 0);
    } else {
      sup.set(ev.key, (sup.get(ev.key) ?? 0) + 1);
    }
  }
  return out;
}
