interface InvoiceSpec {
  customer: string;
  dueDay: number;
  amount: number;
  paid: number;
}
interface AgeingSummary {
  totals: [number, number, number, number, number];
  byCustomer: Record<string, [number, number, number, number, number]>;
}

function summarizeReceivables(invoices: InvoiceSpec[], asOfDay: number): AgeingSummary {
  const totals: [number, number, number, number, number] = [0, 0, 0, 0, 0];
  const byCustomer: Record<string, [number, number, number, number, number]> = {};
  for (const inv of invoices) {
    if (!Number.isInteger(inv.amount) || !Number.isInteger(inv.paid) || inv.paid < 0 || inv.paid > inv.amount) {
      throw new Error("bad invoice");
    }
    const open = inv.amount - inv.paid;
    if (open === 0) continue;
    const od = asOfDay - inv.dueDay;
    const b = od <= 0 ? 0 : od <= 30 ? 1 : od <= 60 ? 2 : od <= 90 ? 3 : 4;
    totals[b] += open;
    if (!byCustomer[inv.customer]) byCustomer[inv.customer] = [0, 0, 0, 0, 0];
    byCustomer[inv.customer][b] += open;
  }
  return { totals, byCustomer };
}
