```typescript
interface WaterTier {
  upTo: number | null;
  rateCents: number;
}
interface WaterBill {
  usage: number;
  totalCents: number;
  breakdown: Array<{ tierIndex: number; units: number; costCents: number }>;
}

function calculateWaterBill(prevReading: number, currReading: number, tiers: WaterTier[]): WaterBill {
  if (!Number.isInteger(prevReading) || !Number.isInteger(currReading) || currReading < prevReading) {
    throw new Error("bad reading");
  }
  let rem = currReading - prevReading;
  let prevTop = 0;
  let totalCents = 0;
  const breakdown: Array<{ tierIndex: number; units: number; costCents: number }> = [];
  for (let i = 0; i < tiers.length; i += 1) {
    const t = tiers[i];
    if (!Number.isInteger(t.rateCents) || t.rateCents < 0) throw new Error("bad rate");
    let units = 0;
    if (t.upTo === null) {
      units = rem;
      rem = 0;
    } else {
      if (!Number.isInteger(t.upTo) || t.upTo <= prevTop) throw new Error("bad upTo");
      units = Math.min(rem, t.upTo - prevTop);
      rem -= units;
      prevTop = t.upTo;
    }
    const costCents = units * t.rateCents;
    totalCents += costCents;
    if (units > 0) breakdown.push({ tierIndex: i, units, costCents });
  }
  if (rem > 0) throw new Error("usage exceeds bounded tiers");
  return { usage: currReading - prevReading, totalCents, breakdown };
}
```

