type Interval = [number, number];

function computeSlaDowntime(outages: Interval[], maintenance: Interval[]): number {
  const merge = (ivs: Interval[]): Interval[] => {
    const clean = ivs.filter(([s, e]) => s < e).sort((a, b) => (a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]));
    const res: Interval[] = [];
    for (const [s, e] of clean) {
      if (res.length === 0 || s > res[res.length - 1][1]) {
        res.push([s, e]);
      } else if (e > res[res.length - 1][1]) {
        res[res.length - 1][1] = e;
      }
    }
    return res;
  };
  const outs = merge(outages);
  const ms = merge(maintenance);
  let total = 0;
  let j = 0;
  for (const [os, oe] of outs) {
    let cur = os;
    while (j < ms.length && ms[j][1] <= cur) j += 1;
    let k = j;
    while (k < ms.length && ms[k][0] < oe) {
      const [ms0, me0] = ms[k];
      if (ms0 > cur) total += ms0 - cur;
      if (me0 > cur) cur = me0;
      if (cur >= oe) break;
      k += 1;
    }
    if (cur < oe) total += oe - cur;
  }
  return total;
}
```

