function simulateBreaker(events, failThreshold, cooldown, halfOpenNeeded) {
  if (!Number.isInteger(failThreshold) || failThreshold < 1) throw new Error("bad failThreshold");
  if (!Number.isInteger(cooldown) || cooldown < 0) throw new Error("bad cooldown");
  if (!Number.isInteger(halfOpenNeeded) || halfOpenNeeded < 1) throw new Error("bad halfOpenNeeded");
  let state = "CLOSED";
  let fails = 0;
  let halfOk = 0;
  let openedAt = 0;
  let prevTs = null;
  let ok = 0, err = 0, blocked = 0;
  for (const ev of events) {
    if (!Number.isInteger(ev.ts)) throw new Error("bad ts");
    if (prevTs !== null && ev.ts < prevTs) throw new Error("decreasing ts");
    prevTs = ev.ts;
    if (state === "OPEN") {
      if (ev.ts >= openedAt + cooldown) {
        state = "HALF_OPEN";
        halfOk = 0;
      } else {
        blocked += 1;
        continue;
      }
    }
    if (ev.ok) {
      ok += 1;
      if (state === "HALF_OPEN") {
        halfOk += 1;
        if (halfOk >= halfOpenNeeded) {
          state = "CLOSED";
          fails = 0;
        }
      } else {
        fails = 0;
      }
    } else {
      err += 1;
      if (state === "HALF_OPEN") {
        state = "OPEN";
        openedAt = ev.ts;
        halfOk = 0;
      } else {
        fails += 1;
        if (fails >= failThreshold) {
          state = "OPEN";
          openedAt = ev.ts;
        }
      }
    }
  }
  return { state, ok, err, blocked };
}
