        const step = Number(stepStr);
        if (!Number.isInteger(step) || step <= 0) throw new Error("bad step");
        let a, b;
        if (rng === "*") { a = lo; b = hi; }
        else if (rng.includes("-")) { [a, b] = rng.split("-").map(Number); }
        else { a = Number(rng); b = hi; }
        if (!Number.isInteger(a) || !Number.isInteger(b) || a < lo || b > hi || a > b) throw new Error("bad range");
        for (let v = a; v <= b; v += step) s.add(v);
      } else if (part === "*") {
        for (let v = lo; v <= hi; v += 1) s.add(v);
      } else if (part.includes("-")) {
        const [a, b] = part.split("-").map(Number);
        if (!Number.isInteger(a) || !Number.isInteger(b) || a < lo || b > hi || a > b) throw new Error("bad range");
