        cycleTicks.push(dayOff + h * 60 + m);
      }
    }
  }
  if (cycleTicks.length === 0) throw new Error("no matching ticks");
  const CYCLE = 30 * 1440;
  let k = Math.floor((startMinute + 1) / CYCLE);
  const rem = (startMinute + 1) % CYCLE;
  let lo = 0, hi = cycleTicks.length;
