function applyQuotaCommands(limits, ops) {
  const limitMap = new Map(Object.entries(limits));
  const files = new Map();
  const used = new Map();
  const ancestors = (path) => {
    if (!path.startsWith("/") || path === "/" || path.endsWith("/")) throw new Error("bad path");
    const parts = path.split("/").slice(1);
    if (parts.some((p) => p.length === 0)) throw new Error("empty segment");
    const dirs = ["/"];
    let cur = "";
    for (let i = 0; i < parts.length - 1; i += 1) {
      cur += "/" + parts[i];
      dirs.push(cur);
    }
    return dirs;
  };
  const out = [];
  for (const op of ops) {
    if (op.type === "PUT") {
      if (!Number.isInteger(op.size) || op.size < 0) throw new Error("bad size");
      const dirs = ancestors(op.path);
      const prev = files.get(op.path) ?? 0;
      const delta = op.size - prev;
      let ok = true;
      if (delta > 0) {
        for (const d of dirs) {
          const lim = limitMap.get(d);
          if (lim !== undefined && (used.get(d) ?? 0) + delta > lim) {
            ok = false;
            break;
          }
        }
      }
      if (ok) {
        files.set(op.path, op.size);
        for (const d of dirs) used.set(d, (used.get(d) ?? 0) + delta);
        out.push("OK");
      } else {
        out.push("ERR");
      }
    } else if (op.type === "DEL") {
      const prev = files.get(op.path);
      if (prev === undefined) {
        out.push("MISSING");
      } else {
        files.delete(op.path);
        for (const d of ancestors(op.path)) used.set(d, (used.get(d) ?? 0) - prev);
        out.push("DELETED");
      }
    } else {
      out.push(used.get(op.dir) ?? 0);
    }
  }
  return out;
}
