from bisect import bisect_left

def schedule_backfill(capacity: int, jobs: list[tuple[str, int, int, int]]) -> list[tuple[str, int, int]]:
    if capacity <= 0:
        raise ValueError("capacity must be positive")
    points = [0, 10**18]
    usage = [0]
    out = []
    for jid, arr, dur, cores in jobs:
        if arr < 0 or dur <= 0 or cores <= 0 or cores > capacity:
            raise ValueError("invalid job")
        idx = bisect_left(points, arr)
        if idx == len(points) or points[idx] > arr:
            idx -= 1
        t = arr
        j = idx
        while True:
            if usage[j] + cores > capacity:
                t = points[j + 1]
                j += 1
            else:
                if points[j + 1] >= t + dur:
                    break
                j += 1
        start = t
        end = t + dur
        si = bisect_left(points, start)
        if points[si] != start:
            points.insert(si, start)
            usage.insert(si, usage[si - 1])
        ei = bisect_left(points, end)
        if points[ei] != end:
            points.insert(ei, end)
            usage.insert(ei, usage[ei - 1])
        for k in range(si, ei):
            usage[k] += cores
        out.append((jid, start, end))
    return out
