def simulate_parking(num_spots: int, events: list[tuple[str, int, str, str]]) -> tuple[int, list[tuple[str, object]]]:
    if num_spots < 0:
        raise ValueError("num_spots must be >= 0")
    free_min = list(range(num_spots))
    free_max = [-i for i in range(num_spots)]
    heapq.heapify(free_min)
    heapq.heapify(free_max)
    is_free = [True] * num_spots
    occ = {}
    total = 0
    log = []
    prev_ts = None
    for kind, ts, vid, cat in events:
        if prev_ts is not None and ts < prev_ts:
            raise ValueError("decreasing timestamp")
        prev_ts = ts
        if kind not in ("IN", "OUT") or cat not in ("EV", "STD"):
            raise ValueError("invalid event")
        if kind == "IN":
            if vid in occ:
                log.append((vid, "DENY"))
                continue
            pick = None
            if cat == "EV":
                while free_min:
                    cand = heapq.heappop(free_min)
                    if is_free[cand]:
                        pick = cand
                        break
            else:
                while free_max:
                    cand = -heapq.heappop(free_max)
                    if is_free[cand]:
                        pick = cand
                        break
            if pick is None:
                log.append((vid, "DENY"))
            else:
                is_free[pick] = False
                occ[vid] = (pick, ts, cat)
                log.append((vid, pick))
        else:
            if vid not in occ:
                log.append((vid, -1))
            else:
                s, t0, c0 = occ.pop(vid)
                is_free[s] = True
                heapq.heappush(free_min, s)
                heapq.heappush(free_max, -s)
                dur = ts - t0
                rate = 3 if c0 == "EV" else 5
                fee = 0 if dur <= 15 else ((dur - 15 + 59) // 60) * rate
                total += fee
                log.append((vid, fee))
    return (total, log)
