import heapq

def route_baggage(
    belt_count: int,
    bags: list[tuple[str, int, int, bool]],
) -> tuple[list[tuple[str, int]], list[int]]:
    if belt_count <= 0:
        raise ValueError("belt_count must be positive")
    for _, _, w, _ in bags:
        if w <= 0:
            raise ValueError("weight must be positive")
    ordered = sorted(bags, key=lambda b: (b[1], 0 if b[3] else 1, b[0]))
    heap = [(0, 0, i) for i in range(belt_count)]
    heapq.heapify(heap)
    loads = [0] * belt_count
    assign = []
    for bid, _, w, _ in ordered:
        lw, cnt, i = heapq.heappop(heap)
        loads[i] = lw + w
        heapq.heappush(heap, (lw + w, cnt + 1, i))
        assign.append((bid, i))
    return (assign, loads)
