                        placed = [(names[r_idx], k + 1) for k in range(s0, c_idx + 1)]
                        break
                if placed is not None:
                    break
        else:
            avail = []
            for r_idx, row in enumerate(free):
                for c_idx, ok in enumerate(row):
                    if ok:
                        avail.append((r_idx, c_idx))
                        if len(avail) == sz:
