def bill_calls(
    plans: dict[str, tuple[int, int, int]],
    calls: list[tuple[str, str, int]],
) -> dict[str, int]:
    for pid, (inc, rate, blk) in plans.items():
        if inc < 0 or rate < 0 or blk <= 0:
            raise ValueError("invalid plan")
    used = {}
    bill = {}
    for uid, pid, dur in calls:
        if pid not in plans or dur < 0:
            raise ValueError("invalid call")
        inc, rate, blk = plans[pid]
        prev = used.get(uid, 0)
        used[uid] = prev + dur
        b0 = max(0, prev - inc)
        b1 = max(0, prev + dur - inc)
        delta = b1 - b0
        if delta > 0:
            blocks = (delta + blk - 1) // blk
            bill[uid] = bill.get(uid, 0) + blocks * rate
        else:
            bill.setdefault(uid, 0)
    return bill
