std::vector<std::string> assignFreightDocks(
    int numDocks,
    const std::vector<std::tuple<std::string, long long, long long>>& trucks
) {
    std::vector<std::tuple<long long, std::string, long long>> ord;
    ord.reserve(trucks.size());
    for (const auto& [tid, arr, dur] : trucks) ord.emplace_back(arr, tid, dur);
    std::sort(ord.begin(), ord.end());
    using P = std::pair<long long, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;
    for (int d = 0; d < numDocks; ++d) pq.emplace(0LL, d);
    std::vector<std::tuple<std::string, int, long long, long long>> res;
    for (const auto& [arr, tid, dur] : ord) {
        auto [f, d] = pq.top();
        pq.pop();
        long long st = std::max(arr, f);
        long long en = st + dur;
        pq.emplace(en, d);
        res.emplace_back(tid, d, st, en);
    }
    std::sort(res.begin(), res.end());
    std::vector<std::string> out;
    for (const auto& [tid, d, st, en] : res) {
        out.push_back(tid + " " + std::to_string(d) + " " + std::to_string(st) + " " + std::to_string(en));
