#include <algorithm>
#include <string>
#include <utility>
#include <vector>

std::vector<long long> prorateInvoice(
    long long totalCents,
    const std::vector<std::pair<std::string, long long>>& items
) {
    __int128 wsum = 0;
    for (const auto& [id, w] : items) wsum += w;
    std::vector<long long> alloc(items.size(), 0);
    if (wsum == 0) return alloc;
    struct Rem { __int128 r; std::string id; size_t idx; };
    std::vector<Rem> rems;
    rems.reserve(items.size());
    long long baseSum = 0;
    for (size_t i = 0; i < items.size(); ++i) {
        __int128 prod = (__int128)totalCents * items[i].second;
        long long b = (long long)(prod / wsum);
        alloc[i] = b;
        baseSum += b;
        rems.push_back({prod % wsum, items[i].first, i});
    }
    std::sort(rems.begin(), rems.end(), [](const Rem& a, const Rem& b) {
        if (a.r != b.r) return a.r > b.r;
        return a.id < b.id;
    });
    long long leftover = totalCents - baseSum;
    for (long long i = 0; i < leftover; ++i) alloc[rems[i].idx] += 1;
    return alloc;
}
