long long simulateParkingRevenue(
    int numSpots,
    const std::vector<std::tuple<std::string, long long, std::string, std::string>>& events
) {
    std::set<int> freeSpots;
    for (int i = 0; i < numSpots; ++i) freeSpots.insert(i);
    struct Entry { int spot; long long t0; std::string cat; };
    std::unordered_map<std::string, Entry> occ;
    long long total = 0;
    for (const auto& [kind, ts, vid, cat] : events) {
        if (kind == "IN") {
            if (occ.count(vid) || freeSpots.empty()) continue;
            int s = (cat == "EV") ? *freeSpots.begin() : *freeSpots.rbegin();
            freeSpots.erase(s);
            occ[vid] = {s, ts, cat};
        } else {
            auto it = occ.find(vid);
            if (it == occ.end()) continue;
            Entry e = it->second;
            occ.erase(it);
            freeSpots.insert(e.spot);
            long long dur = ts - e.t0;
            if (dur > 15) {
                long long rate = (e.cat == "EV") ? 3LL : 5LL;
                total += ((dur - 15 + 59) / 60) * rate;
            }
        }
    }
    return total;
}
