                            total_free -= sz
                            picked = f"{rows[ri]}:{s0 + 1}-{ci + 1}"
                            break
                    if picked is not None:
                        break
            out.append(f"{gid} {picked if picked is not None else 'NONE'}")
        else:
            if total_free < sz:
                out.append(f"{gid} NONE")
            else:
                chosen = []
                for ri, row in enumerate(free):
                    for ci, ok in enumerate(row):
                        if ok:
                            row[ci] = False
                            chosen.append(f"{rows[ri]}{ci + 1}")
                            if len(chosen) == sz:
                                break
                    if len(chosen) == sz:
                        break
                total_free -= sz
                out.append(f"{gid} " + ",".join(chosen))
    sys.stdout.write("\n".join(out) + "\n")

