import sys

def parse_field(expr, lo, hi):
    s = set()
    for part in expr.split(","):
        if "/" in part:
            rng, st_s = part.split("/", 1)
            st = int(st_s)
            if rng == "*":
                a, b = lo, hi
            elif "-" in rng:
                a_s, b_s = rng.split("-", 1)
                a, b = int(a_s), int(b_s)
            else:
                a, b = int(rng), hi
            s.update(range(a, b + 1, st))
        elif part == "*":
            s.update(range(lo, hi + 1))
        elif "-" in part:
            a_s, b_s = part.split("-", 1)
            s.update(range(int(a_s), int(b_s) + 1))
        else:
            s.add(int(part))
    return sorted(s)

def prefix_in_day(r, mins, hours):
    if r < 0:
        return 0
    rh, rm = divmod(r, 60)
    cnt = 0
    for h in hours:
        if h < rh:
            cnt += len(mins)
        elif h == rh:
            for m in mins:
                if m <= rm:
                    cnt += 1
    return cnt

def main():
    parts = sys.stdin.read().split()
    if not parts:
        return
    m_expr, h_expr, lo_s, hi_s = parts[0], parts[1], parts[2], parts[3]
    lo, hi = int(lo_s), int(hi_s)
    mins = parse_field(m_expr, 0, 59)
    hours = parse_field(h_expr, 0, 23)
    per_day = len(mins) * len(hours)
    d0, r0 = divmod(lo, 1440)
    d1, r1 = divmod(hi, 1440)
    if d0 == d1:
        ans = prefix_in_day(r1, mins, hours) - prefix_in_day(r0 - 1, mins, hours)
    else:
        c0 = per_day - prefix_in_day(r0 - 1, mins, hours)
        c1 = prefix_in_day(r1, mins, hours)
        ans = c0 + (d1 - d0 - 1) * per_day + c1
    print(ans)

if __name__ == "__main__":
    main()
