"""Parking spot assignment."""

from .pricing import compute_fee


class ParkingLot:
    def __init__(self, num_spots):
        self.free = set(range(num_spots))
        self.occ = {}
        self.revenue = 0

    def enter(self, minute, vid, category):
        if vid in self.occ or not self.free:
            return None
        spot = min(self.free)
        self.free.remove(spot)
        self.occ[vid] = (spot, minute, category)
        return spot

    def exit(self, minute, vid):
        if vid not in self.occ:
            return -1
        spot, t0, cat = self.occ.pop(vid)
        self.free.add(spot)
        fee = compute_fee(minute - t0, cat)
        self.revenue += fee
        return fee

