"""Customer record merging."""

from .dsu import LexDSU


def merge_records(records):
    dsu = LexDSU()
    by_email = {}
    by_phone = {}
    for _, rid, em, ph, _ in records:
        dsu.add(rid)
        if em:
            if em in by_email:
                dsu.union(rid, by_email[em])
            else:
                by_email[em] = rid
        if ph:
            if ph in by_phone:
                dsu.union(rid, by_phone[ph])
            else:
                by_phone[ph] = rid
    groups = {}
    for rec in records:
        groups.setdefault(dsu.find(rec[1]), []).append(rec)
    out = []
    for root in sorted(groups):
        items = sorted(groups[root], key=lambda r: (r[0], r[1]))
        name = email = phone = ""
        for _, _, em, ph, nm in items:
            name = nm
            email = em
            phone = ph
        out.append((root, name, email, phone, len(items)))
    return out

