"""Theater group seat allocator."""

from .row import find_contiguous


class Theater:
    def __init__(self, rows_spec):
        self.names = [nm for nm, _ in rows_spec]
        self.free = [[True] * cnt for _, cnt in rows_spec]

    def book(self, size, contiguous=True):
        if contiguous:
            for r_idx, row in enumerate(self.free):
                start = find_contiguous(row, size)
                if start is not None:
                    for k in range(start, start + size):
                        row[k] = False
                    return [(self.names[r_idx], k + 1) for k in range(start, start + size)]
            return None
        max_c = max((len(r) for r in self.free), default=0)
        avail = [
            (r_idx, c_idx)
            for c_idx in range(max_c)
            for r_idx, row in enumerate(self.free)
            if c_idx < len(row) and row[c_idx]
        ]
        if len(avail) < size:
            return None
        chosen = avail[:size]
        for r_idx, c_idx in chosen:
            self.free[r_idx][c_idx] = False
        return [(self.names[r_idx], c_idx + 1) for r_idx, c_idx in chosen]

