interface BidSpec {
  ts: number;
  bidder: string;
  amount: number;
}
interface AuctionSummary {
  leader: string | null;
  high: number;
  accepted: number;
}

function runAuction(reserve: number, minInc: number, bids: BidSpec[]): AuctionSummary {
  if (!Number.isInteger(reserve) || reserve <= 0) throw new Error("bad reserve");
  if (!Number.isInteger(minInc) || minInc <= 0) throw new Error("bad minInc");
  let leader: string | null = null;
  let high = 0;
  let accepted = 0;
  let prevTs: number | null = null;
  for (const b of bids) {
    if (!Number.isInteger(b.ts) || !Number.isInteger(b.amount) || b.amount <= 0) throw new Error("bad bid");
    if (prevTs !== null && b.ts < prevTs) throw new Error("decreasing ts");
    prevTs = b.ts;
    const needed = leader === null ? reserve : high + minInc;
    if (b.amount >= needed) {
      high = b.amount;
      leader = b.bidder;
      accepted += 1;
    }
  }
  return { leader, high, accepted };
}
