interface BagSpec {
  id: string;
  arrival: number;
  weight: number;
  priority: boolean;
}

function routeBaggage(beltCount: number, bags: BagSpec[]): Array<{ id: string; belt: number }> {
  if (!Number.isInteger(beltCount) || beltCount <= 0) throw new Error("bad beltCount");
  const ord = bags.map((b) => {
    if (!Number.isInteger(b.arrival) || !Number.isInteger(b.weight) || b.weight <= 0) throw new Error("bad bag");
    return { ...b };
  });
  ord.sort((a, b) => {
    if (a.arrival !== b.arrival) return a.arrival - b.arrival;
    if (a.priority !== b.priority) return a.priority ? -1 : 1;
    return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
  });
  const loads = new Array<number>(beltCount).fill(0);
  const counts = new Array<number>(beltCount).fill(0);
  const out: Array<{ id: string; belt: number }> = [];
  for (const b of ord) {
    let best = 0;
    for (let i = 1; i < beltCount; i += 1) {
      if (loads[i] < loads[best] || (loads[i] === loads[best] && counts[i] < counts[best])) {
        best = i;
      }
    }
    loads[best] += b.weight;
    counts[best] += 1;
    out.push({ id: b.id, belt: best });
  }
  return out;
}
