  includedSec: number;
  rateCents: number;
  blockSec: number;
}
interface CallRecord {
  user: string;
  plan: string;
  durationSec: number;
}

function computeCallBills(plans: Record<string, TariffPlan>, calls: CallRecord[]): Record<string, number> {
  for (const p of Object.values(plans)) {
    if (!Number.isInteger(p.includedSec) || p.includedSec < 0 || !Number.isInteger(p.rateCents) || p.rateCents < 0 || !Number.isInteger(p.blockSec) || p.blockSec <= 0) {
      throw new Error("bad plan");
    }
  }
  const used = new Map<string, number>();
  const bills: Record<string, number> = {};
  for (const c of calls) {
    const p = plans[c.plan];
    if (!p) throw new Error("unknown plan");
    if (!Number.isInteger(c.durationSec) || c.durationSec < 0) throw new Error("bad duration");
    const prev = used.get(c.user) ?? 0;
    used.set(c.user, prev + c.durationSec);
    const b0 = Math.max(0, prev - p.includedSec);
    const b1 = Math.max(0, prev + c.durationSec - p.includedSec);
    const delta = b1 - b0;
    if (delta > 0) {
      const blocks = Math.ceil(delta / p.blockSec);
      bills[c.user] = (bills[c.user] ?? 0) + blocks * p.rateCents;
    } else if (bills[c.user] === undefined) {
      bills[c.user] = 0;
    }
  }
  return bills;
}
