interface RowSpec {
  name: string;
  seats: number;
}
interface SeatRequest {
  groupId: string;
  size: number;
  contiguous: boolean;
}
interface SeatLocation {
  row: string;
  seat: number;
}

function allocateTheaterSeats(rows: RowSpec[], requests: SeatRequest[]): Record<string, SeatLocation[] | null> {
  const seen = new Set<string>();
  const free: boolean[][] = [];
  const names: string[] = [];
  for (const r of rows) {
    if (seen.has(r.name) || !Number.isInteger(r.seats) || r.seats < 0) throw new Error("bad row");
    seen.add(r.name);
    names.push(r.name);
    free.push(new Array<boolean>(r.seats).fill(true));
  }
  const out: Record<string, SeatLocation[] | null> = {};
  for (const req of requests) {
    if (!Number.isInteger(req.size) || req.size <= 0) throw new Error("bad size");
    let placed: SeatLocation[] | null = null;
    if (req.contiguous) {
      for (let ri = 0; ri < free.length; ri += 1) {
        let run = 0;
        for (let ci = 0; ci < free[ri].length; ci += 1) {
          run = free[ri][ci] ? run + 1 : 0;
          if (run === req.size) {
            const s0 = ci - req.size + 1;
            placed = [];
            for (let k = s0; k <= ci; k += 1) {
              free[ri][k] = false;
              placed.push({ row: names[ri], seat: k + 1 });
            }
            break;
          }
        }
        if (placed !== null) break;
      }
    } else {
      const avail: Array<[number, number]> = [];
      for (let ri = 0; ri < free.length && avail.length < req.size; ri += 1) {
        for (let ci = 0; ci < free[ri].length && avail.length < req.size; ci += 1) {
          if (free[ri][ci]) avail.push([ri, ci]);
        }
      }
      if (avail.length === req.size) {
        placed = avail.map(([ri, ci]) => {
          free[ri][ci] = false;
          return { row: names[ri], seat: ci + 1 };
        });
      }
    }
    out[req.groupId] = placed;
  }
  return out;
}
