  name: string;
  email: string;
  phone: string;
  count: number;
}

function mergeCustomerIdentities(rows: CustomerRow[]): MergedCustomer[] {
  const parent = new Map<string, string>();
  const find = (x: string): string => {
    let cur = x;
    while (parent.get(cur) !== cur) {
      const p = parent.get(cur)!;
      parent.set(cur, parent.get(p)!);
      cur = p;
    }
    return cur;
  };
  const union = (a: string, b: string) => {
    const ra = find(a);
    const rb = find(b);
    if (ra !== rb) {
      if (ra < rb) parent.set(rb, ra);
      else parent.set(ra, rb);
    }
  };
  const byEmail = new Map<string, string>();
  const byPhone = new Map<string, string>();
  for (const r of rows) {
    if (parent.has(r.id)) throw new Error("duplicate id");
    parent.set(r.id, r.id);
    if (r.email) {
      const prev = byEmail.get(r.email);
      if (prev !== undefined) union(r.id, prev);
      else byEmail.set(r.email, r.id);
    }
    if (r.phone) {
      const prev = byPhone.get(r.phone);
      if (prev !== undefined) union(r.id, prev);
      else byPhone.set(r.phone, r.id);
    }
  }
  const groups = new Map<string, CustomerRow[]>();
  for (const r of rows) {
    const root = find(r.id);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root)!.push(r);
  }
  const out: MergedCustomer[] = [];
  for (const [cid, items] of groups.entries()) {
    items.sort((a, b) => (a.ts !== b.ts ? a.ts - b.ts : a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
    let name = "", email = "", phone = "";
    for (const it of items) {
      if (it.name) name = it.name;
      if (it.email) email = it.email;
      if (it.phone) phone = it.phone;
    }
    out.push({ canonicalId: cid, name, email, phone, count: items.length });
  }
  out.sort((a, b) => (a.canonicalId < b.canonicalId ? -1 : a.canonicalId > b.canonicalId ? 1 : 0));
  return out;
}
