function manageParkingLot(numSpots, events) {
  if (!Number.isInteger(numSpots) || numSpots < 0) throw new Error("bad numSpots");
  const free = new Set();
  for (let i = 0; i < numSpots; i += 1) free.add(i);
  const occ = new Map();
  let revenue = 0;
  let prevTs = null;
  const out = [];
  for (const ev of events) {
    if (!Number.isInteger(ev.ts)) throw new Error("bad ts");
    if (prevTs !== null && ev.ts < prevTs) throw new Error("decreasing ts");
    prevTs = ev.ts;
    if (ev.kind === "IN") {
      if (occ.has(ev.vid) || free.size === 0) {
        out.push({ vid: ev.vid, value: "DENY" });
      } else {
        const spot = ev.category === "EV" ? Math.min(...free) : Math.max(...free);
        free.delete(spot);
        occ.set(ev.vid, { spot, t0: ev.ts, cat: ev.category });
        out.push({ vid: ev.vid, value: spot });
      }
    } else {
      const rec = occ.get(ev.vid);
      if (!rec) {
        out.push({ vid: ev.vid, value: -1 });
      } else {
        occ.delete(ev.vid);
        free.add(rec.spot);
        const dur = ev.ts - rec.t0;
        const rate = rec.cat === "EV" ? 3 : 5;
        const fee = dur <= 15 ? 0 : Math.ceil((dur - 15) / 60) * rate;
        revenue += fee;
        out.push({ vid: ev.vid, value: fee });
      }
    }
  }
  return { revenue, events: out };
}
