function checkFirewallPackets(rules, packets) {
  const parseIp = (s) => {
    const parts = s.split(".");
    if (parts.length !== 4) throw new Error("bad ip");
    let v = 0;
    for (const p of parts) {
      const n = Number(p);
      if (!Number.isInteger(n) || n < 0 || n > 255) throw new Error("bad octet");
      v = ((v << 8) | n) >>> 0;
    }
    return v;
  };
  const compiled = rules.map((r) => {
    const [ipStr, prefStr] = r.cidr.split("/");
    const pref = Number(prefStr);
    if (!Number.isInteger(pref) || pref < 0 || pref > 32) throw new Error("bad prefix");
    const mask = pref === 0 ? 0 : ((0xffffffff << (32 - pref)) >>> 0);
    const net = (parseIp(ipStr) & mask) >>> 0;
    return { action: r.action, proto: r.proto, net, mask, minPort: r.minPort, maxPort: r.maxPort };
  });
  return packets.map((pkt) => {
    const ip = parseIp(pkt.ip);
    for (const r of compiled) {
      if ((r.proto === "ANY" || r.proto === pkt.proto) && ((ip & r.mask) >>> 0) === r.net && pkt.port >= r.minPort && pkt.port <= r.maxPort) {
        return r.action;
      }
    }
    return "DENY";
  });
}
