function billTelecomCalls(plans, calls) {
  for (const p of Object.values(plans)) {
    if (!Number.isInteger(p.includedSec) || p.includedSec < 0 || !Number.isInteger(p.rateCents) || p.rateCents < 0 || !Number.isInteger(p.blockSec) || p.blockSec <= 0) {
      throw new Error("bad plan");
    }
