  const bills = {};
  for (const c of calls) {
    const p = plans[c.plan];
    if (!p) throw new Error("unknown plan");
    if (!Number.isInteger(c.durationSec) || c.durationSec < 0) throw new Error("bad duration");
    const prev = used.get(c.user) ?? 0;
    used.set(c.user, prev + c.durationSec);
    const b0 = Math.max(0, prev - p.includedSec);
    const b1 = Math.max(0, prev + c.durationSec - p.includedSec);
    const delta = b1 - b0;
    if (delta > 0) {
      const blocks = Math.ceil(delta / p.blockSec);
