function settleSharedExpenses(members, expenses) {
  const bal = {};
  for (const m of members) {
    if (m in bal) throw new Error("duplicate member");
    bal[m] = 0;
  }
  for (const exp of expenses) {
    if (!(exp.payer in bal) || !Number.isInteger(exp.amountCents) || exp.amountCents < 0 || exp.shares.length === 0) {
      throw new Error("bad expense");
    }
    const seen = new Set();
    let tw = 0;
    for (const s of exp.shares) {
      if (!(s.member in bal) || seen.has(s.member) || !Number.isInteger(s.weight) || s.weight < 0) {
        throw new Error("bad share");
      }
      seen.add(s.member);
      tw += s.weight;
    }
    if (tw <= 0) throw new Error("zero total weight");
    bal[exp.payer] += exp.amountCents;
    const rems = [];
    let baseSum = 0;
    for (const s of exp.shares) {
      const prod = exp.amountCents * s.weight;
      const b = Math.floor(prod / tw);
      bal[s.member] -= b;
      baseSum += b;
      rems.push({ member: s.member, rem: prod % tw });
    }
    rems.sort((a, b) => (b.rem !== a.rem ? b.rem - a.rem : a.member < b.member ? -1 : a.member > b.member ? 1 : 0));
    const left = exp.amountCents - baseSum;
    for (let i = 0; i < left; i += 1) bal[rems[i].member] -= 1;
  }
  return bal;
}
