def evaluate_auction(
    reserve: int,
    min_inc: int,
    bids: list[tuple[int, str, int]],
) -> tuple[str | None, int, int]:
    if reserve <= 0 or min_inc <= 0:
        raise ValueError("reserve and min_inc must be positive")
    leader = None
    high = 0
    accepted = 0
    prev_ts = None
    for ts, bidder, amt in bids:
        if prev_ts is not None and ts < prev_ts:
            raise ValueError("decreasing timestamp")
        prev_ts = ts
        if amt <= 0:
            raise ValueError("bid amount must be positive")
        need = reserve if leader is None else high + min_inc
        if amt >= need:
            high = amt
            leader = bidder
            accepted += 1
    return (leader, high, accepted)
