def _parse_ip(addr: str) -> int:
    parts = addr.split(".")
    if len(parts) != 4:
        raise ValueError("invalid ip")
    val = 0
    for p in parts:
        n = int(p)
        if n < 0 or n > 255:
            raise ValueError("invalid octet")
        val = (val << 8) | n
    return val

def evaluate_firewall(
    rules: list[tuple[str, str, str, int, int]],
    packets: list[tuple[str, str, int]],
) -> list[str]:
    comp = []
    for act, proto, cidr, p0, p1 in rules:
        if act not in ("ALLOW", "DENY") or proto not in ("TCP", "UDP", "ANY") or p0 > p1:
            raise ValueError("invalid rule")
        ip_s, pref_s = cidr.split("/")
        pref = int(pref_s)
        if pref < 0 or pref > 32:
            raise ValueError("invalid prefix")
        mask = (0xFFFFFFFF << (32 - pref)) & 0xFFFFFFFF if pref > 0 else 0
        comp.append((act, proto, _parse_ip(ip_s) & mask, mask, p0, p1))
    out = []
    for proto, ip_s, port in packets:
        ip = _parse_ip(ip_s)
        decision = "DENY"
        for act, rproto, net, mask, p0, p1 in comp:
            if (rproto == "ANY" or rproto == proto) and (ip & mask) == net and p0 <= port <= p1:
                decision = act
                break
        out.append(decision)
    return out
