def validate_shift_swaps(
    max_hours: dict[str, int],
    initial_shifts: list[tuple[str, str, int, int]],
    swaps: list[tuple[str, str]],
) -> list[str]:
    shifts = {}
    emp_days = {e: set() for e in max_hours}
    emp_hrs = {e: 0 for e in max_hours}
    for sid, emp, day, hrs in initial_shifts:
        if sid in shifts:
            raise ValueError("duplicate shift_id")
        shifts[sid] = [emp, day, hrs]
        emp_days.setdefault(emp, set()).add(day)
        emp_hrs[emp] = emp_hrs.get(emp, 0) + hrs
    out = []
    for sid, new_emp in swaps:
        if sid not in shifts:
            raise ValueError("unknown shift_id")
        old_emp, day, hrs = shifts[sid]
        if new_emp == old_emp:
            out.append("NOOP")
            continue
        if new_emp not in max_hours:
            out.append("REJECT")
            continue
        ds = emp_days[new_emp]
        if day in ds or emp_hrs[new_emp] + hrs > max_hours[new_emp]:
            out.append("REJECT")
            continue
        test_ds = ds | {day}
        if any(x in test_ds and (x + 1) in test_ds and (x + 2) in test_ds for x in (day - 2, day - 1, day)):
            out.append("REJECT")
            continue
        emp_days[old_emp].remove(day)
        emp_hrs[old_emp] -= hrs
        ds.add(day)
        emp_hrs[new_emp] += hrs
        shifts[sid][0] = new_emp
        out.append("OK")
    return out
