import heapq

def match_orders(
    orders: list[tuple[str, str, int, int]],
) -> list[tuple[str, str, int, int]]:
    seen = set()
    bids = []  # (-price, seq, oid)
    asks = []  # (price, seq, oid)
    qty_map = {}
    fills = []
    for seq, (side, oid, price, qty) in enumerate(orders):
        if side not in ("BUY", "SELL") or price <= 0 or qty <= 0 or oid in seen:
            raise ValueError("invalid order")
        seen.add(oid)
        rem = qty
        if side == "BUY":
            while rem > 0 and asks and asks[0][0] <= price:
                ap, _, aid = asks[0]
                aq = qty_map[aid]
                tr = rem if rem < aq else aq
                fills.append((oid, aid, ap, tr))
                rem -= tr
                if tr == aq:
                    heapq.heappop(asks)
                    del qty_map[aid]
                else:
                    qty_map[aid] = aq - tr
            if rem > 0:
                qty_map[oid] = rem
                heapq.heappush(bids, (-price, seq, oid))
        else:
            while rem > 0 and bids and -bids[0][0] >= price:
                nbp, _, bid = bids[0]
                bq = qty_map[bid]
                tr = rem if rem < bq else bq
                fills.append((bid, oid, -nbp, tr))
                rem -= tr
                if tr == bq:
                    heapq.heappop(bids)
                    del qty_map[bid]
                else:
                    qty_map[bid] = bq - tr
            if rem > 0:
                qty_map[oid] = rem
                heapq.heappush(asks, (price, seq, oid))
    return fills
