def _parse_ver(s: str) -> tuple[int, int, int]:
    parts = s.split(".")
    if len(parts) != 3:
        raise ValueError("invalid version")
    nums = tuple(int(p) for p in parts)
    if any(n < 0 for n in nums):
        raise ValueError("negative version part")
    return nums

def _matches_clause(v: tuple[int, int, int], cl: str) -> bool:
    for op in (">=", "<=", ">", "<", "=", "^", "~"):
        if cl.startswith(op):
            tgt = _parse_ver(cl[len(op):])
            if op == ">=":
                return v >= tgt
            if op == "<=":
                return v <= tgt
            if op == ">":
                return v > tgt
            if op == "<":
                return v < tgt
            if op == "=":
                return v == tgt
            if op == "~":
                return tgt <= v < (tgt[0], tgt[1] + 1, 0)
            a, b, c = tgt
            hi = (a + 1, 0, 0) if a > 0 else ((0, b + 1, 0) if b > 0 else (0, 0, c + 1))
            return tgt <= v < hi
    return v == _parse_ver(cl)

def resolve_semver(available: list[str], constraints: list[str]) -> str | None:
    parsed = [(_parse_ver(s), s) for s in available]
    clauses = []
    for expr in constraints:
        for cl in expr.split():
            clauses.append(cl)
    best = None
    for v, orig in parsed:
        if all(_matches_clause(v, cl) for cl in clauses):
            if best is None or v > best[0]:
                best = (v, orig)
    return best[1] if best is not None else None
