def simulate_webhooks(
    base_delay: int,
    max_delay: int,
    max_attempts: int,
    events: list[tuple[str, int, bool]],
) -> list[tuple[str, str]]:
    if base_delay <= 0 or max_delay < base_delay or max_attempts < 1:
        raise ValueError("invalid retry policy")
    state = {}
    out = []
    prev_ts = None
    for eid, ts, ok in events:
        if prev_ts is not None and ts < prev_ts:
            raise ValueError("decreasing timestamp")
        prev_ts = ts
        if eid not in state:
            state[eid] = [0, 0, "PENDING"]
        nxt, att, st = state[eid]
        if st != "PENDING":
            out.append((eid, st))
            continue
        if ts < nxt:
            out.append((eid, "DEFERRED"))
            continue
        att += 1
        if ok:
            state[eid] = [ts, att, "DELIVERED"]
            out.append((eid, "DELIVERED"))
        elif att >= max_attempts:
            state[eid] = [ts, att, "DEAD"]
            out.append((eid, "DEAD"))
        else:
            delay = min(max_delay, base_delay * (1 << (att - 1)))
            nxt_ts = ts + delay
            state[eid] = [nxt_ts, att, "PENDING"]
            out.append((eid, f"RETRY@{nxt_ts}"))
    return out
