from collections import OrderedDict, defaultdict

def run_lfu_cache(capacity: int, ops: list[tuple]) -> list[int | None]:
    if capacity < 0:
        raise ValueError("capacity must be >= 0")
    vals = {}
    freqs = {}
    buckets = defaultdict(OrderedDict)
    min_freq = 0
    out = []

    def touch(k: str) -> None:
        nonlocal min_freq
        f = freqs[k]
        del buckets[f][k]
        if not buckets[f] and f == min_freq:
            min_freq += 1
        nf = f + 1
        freqs[k] = nf
        buckets[nf][k] = None

    for op in ops:
        kind = op[0]
        if kind == "PUT":
            _, k, v = op
            if capacity == 0:
                continue
            if k in vals:
                vals[k] = v
                touch(k)
            else:
                if len(vals) >= capacity:
                    ev, _ = buckets[min_freq].popitem(last=False)
                    del vals[ev]
                    del freqs[ev]
                vals[k] = v
                freqs[k] = 1
                buckets[1][k] = None
                min_freq = 1
        elif kind == "GET":
            _, k = op
            if k not in vals:
                out.append(None)
            else:
                touch(k)
                out.append(vals[k])
        else:
            raise ValueError("unknown op")
    return out
