#include <algorithm>
#include <utility>
#include <vector>

static std::vector<std::pair<long long, long long>> mergeIntervals(
    long long pStart, long long pEnd,
    const std::vector<std::pair<long long, long long>>& raw
) {
    std::vector<std::pair<long long, long long>> clamped;
    for (const auto& [s, e] : raw) {
        long long a = std::max(pStart, s);
        long long b = std::min(pEnd, e);
        if (a < b) clamped.emplace_back(a, b);
    }
    std::sort(clamped.begin(), clamped.end());
    std::vector<std::pair<long long, long long>> merged;
    for (const auto& [a, b] : clamped) {
        if (merged.empty() || a > merged.back().second) {
            merged.emplace_back(a, b);
        } else {
            merged.back().second = std::max(merged.back().second, b);
        }
    }
    return merged;
}

std::vector<long long> computeSlaCredit(
    long long periodStart,
    long long periodEnd,
    const std::vector<std::pair<long long, long long>>& maintenance,
    const std::vector<std::pair<long long, long long>>& outages,
    const std::vector<std::pair<long long, long long>>& tiers
) {
    auto mnt = mergeIntervals(periodStart, periodEnd, maintenance);
    auto out = mergeIntervals(periodStart, periodEnd, outages);
    long long down = 0;
    size_t j = 0;
    for (auto [os, oe] : out) {
        long long cur = os;
        while (j < mnt.size() && mnt[j].second <= cur) ++j;
        size_t k = j;
        while (k < mnt.size() && mnt[k].first < oe) {
            if (mnt[k].first > cur) down += mnt[k].first - cur;
            cur = std::max(cur, mnt[k].second);
            if (cur >= oe) break;
            ++k;
        }
        if (cur < oe) down += oe - cur;
    }
    long long bps = 0;
    for (const auto& [thr, cr] : tiers) {
        if (down >= thr && cr > bps) bps = cr;
    }
    return {down, bps};
}
