#include <string>
#include <tuple>
#include <unordered_map>
#include <unordered_set>
#include <vector>

std::vector<std::string> resolveDnsQueries(
    const std::vector<std::tuple<std::string, std::string, std::string, std::string, long long, long long>>& ops
) {
    struct Rec { std::string rtype; std::string val; long long exp; };
    std::unordered_map<std::string, Rec> cache;
    std::vector<std::string> out;
    for (const auto& [op, name, rtype, val, ttl, ts] : ops) {
        if (op == "SET") {
            cache[name] = {rtype, val, ts + ttl};
        } else {
            std::string cur = name;
            std::unordered_set<std::string> seen;
            std::string ans = "LOOP";
            for (int hop = 0; hop <= 8; ++hop) {
                if (!seen.insert(cur).second) {
                    ans = "LOOP";
                    break;
                }
                auto it = cache.find(cur);
                if (it == cache.end() || ts >= it->second.exp) {
                    ans = "NXDOMAIN";
                    break;
                }
                if (it->second.rtype == "A") {
                    ans = it->second.val;
                    break;
                }
                cur = it->second.val;
            }
            out.push_back(ans);
        }
    }
    return out;
}
