#include <vector>

std::vector<std::string> processWarehousePick(
    const std::vector<std::tuple<std::string, std::string, std::string, long long, long long>>& ops
) {
    struct Lot { long long exp; int seq; std::string id; long long rem; };
    std::unordered_map<std::string, std::vector<Lot>> inv;
    std::vector<std::string> out;
    int seq = 0;
    for (const auto& [op, oid, sku, qty, day] : ops) {
        if (op == "STOCK") {
            inv[sku].push_back({day, ++seq, oid, qty});
        } else {
            auto& vec = inv[sku];
            std::vector<size_t> idx;
            long long avail = 0;
            for (size_t i = 0; i < vec.size(); ++i) {
                if (vec[i].rem > 0 && vec[i].exp >= day) {
                    avail += vec[i].rem;
                    idx.push_back(i);
                }
            }
            if (avail < qty) {
                out.push_back(oid + ":SHORT");
                continue;
            }
            std::sort(idx.begin(), idx.end(), [&](size_t a, size_t b) {
                if (vec[a].exp != vec[b].exp) return vec[a].exp < vec[b].exp;
                return vec[a].seq < vec[b].seq;
            });
            long long need = qty;
            std::string line = oid + ":";
            bool first = true;
            for (size_t i : idx) {
                if (need == 0) break;
                long long take = std::min(need, vec[i].rem);
                vec[i].rem -= take;
                need -= take;
                if (!first) line += ",";
                first = false;
                line += vec[i].id + "=" + std::to_string(take);
            }
            out.push_back(line);
        }
    }
    return out;
}
