#include <list>
#include <string>
#include <tuple>
#include <unordered_map>
#include <vector>

std::vector<std::string> runBuildCache(
    long long capacityBytes,
    const std::vector<std::tuple<std::string, std::string, long long, int>>& ops
) {
    struct Entry { std::string key; long long sz; int pin; };
    std::list<Entry> lru;
    std::unordered_map<std::string, std::list<Entry>::iterator> pos;
    long long used = 0;
    std::vector<std::string> out;

    for (const auto& [op, key, sz, pin] : ops) {
        if (op == "GET") {
            auto it = pos.find(key);
            if (it == pos.end()) {
                out.push_back("MISS");
            } else {
                lru.splice(lru.begin(), lru, it->second);
                out.push_back("HIT");
            }
        } else if (op == "UNPIN") {
            auto it = pos.find(key);
            if (it == pos.end()) {
                out.push_back("MISS");
            } else {
                it->second->pin = 0;
                out.push_back("OK");
            }
        } else {
            if (sz > capacityBytes) {
                out.push_back("SKIP");
                continue;
            }
            auto existing = pos.find(key);
            long long oldSz = (existing != pos.end()) ? existing->second->sz : 0;
            long long availUnpinned = 0;
            for (auto it = lru.rbegin(); it != lru.rend(); ++it) {
                if (it->key != key && it->pin == 0) availUnpinned += it->sz;
            }
            long long baseUsed = used - oldSz;
            if (baseUsed + sz - availUnpinned > capacityBytes) {
                out.push_back("SKIP");
                continue;
            }
            auto it = lru.end();
            while (baseUsed + sz > capacityBytes) {
                --it;
                if (it->key != key && it->pin == 0) {
                    baseUsed -= it->sz;
                    pos.erase(it->key);
                    it = lru.erase(it);
                }
            }
            used = baseUsed + sz;
            if (existing != pos.end()) {
                existing->second->sz = sz;
                existing->second->pin = pin;
                lru.splice(lru.begin(), lru, existing->second);
            } else {
                lru.push_front({key, sz, pin});
                pos[key] = lru.begin();
            }
            out.push_back("OK");
        }
    }
    return out;
}
