#include <string>
#include <utility>
#include <vector>

std::vector<std::string> simulateCircuitBreaker(
    int failThreshold,
    long long cooldown,
    int halfOpenTarget,
    const std::vector<std::pair<long long, bool>>& calls
) {
    std::string state = "CLOSED";
    int fails = 0;
    long long openUntil = 0;
    int halfOk = 0;
    std::vector<std::string> out;
    out.reserve(calls.size() + 1);
    for (const auto& [ts, ok] : calls) {
        if (state == "OPEN") {
            if (ts < openUntil) {
                out.push_back("REJECT");
                continue;
            }
            state = "HALF_OPEN";
            halfOk = 0;
        }
        if (state == "CLOSED") {
            if (ok) {
                fails = 0;
                out.push_back("ALLOW");
            } else {
                ++fails;
                if (fails >= failThreshold) {
                    state = "OPEN";
                    openUntil = ts + cooldown;
                }
                out.push_back("FAIL");
            }
        } else {
            if (ok) {
                ++halfOk;
                if (halfOk >= halfOpenTarget) {
                    state = "CLOSED";
                    fails = 0;
                }
                out.push_back("ALLOW");
            } else {
                state = "OPEN";
                openUntil = ts + cooldown;
                out.push_back("FAIL");
            }
        }
    }
    out.push_back(state);
    return out;
}
