#include <algorithm>
#include <string>
#include <tuple>
#include <vector>

static int tierRank(const std::string& t) {
    if (t == "PLAT") return 0;
    if (t == "GOLD") return 1;
    if (t == "SILVER") return 2;
    return 3;
}

std::vector<std::string> assignCabinUpgrades(
    int firstOpen,
    int bizOpen,
    int econOpen,
    const std::vector<std::tuple<std::string, std::string, std::string, std::string, int>>& passengers
) {
    struct Pax { int tr; int seq; std::string id; };
    std::vector<Pax> b2f, e2b, sb;
    for (const auto& [pid, booked, tier, req, seq] : passengers) {
        int tr = tierRank(tier);
        if (booked == "B" && req == "F") b2f.push_back({tr, seq, pid});
        else if (booked == "E" && req == "B") e2b.push_back({tr, seq, pid});
        else if (booked == "NONE") sb.push_back({tr, seq, pid});
    }
    auto cmp = [](const Pax& a, const Pax& b) {
        if (a.tr != b.tr) return a.tr < b.tr;
        return a.seq < b.seq;
    };
    std::sort(b2f.begin(), b2f.end(), cmp);
    std::sort(e2b.begin(), e2b.end(), cmp);
    std::sort(sb.begin(), sb.end(), cmp);

    std::vector<std::pair<std::string, std::string>> res;
    for (const auto& p : b2f) {
        if (firstOpen <= 0) break;
        --firstOpen;
        ++bizOpen;
        res.emplace_back(p.id, "F");
    }
    for (const auto& p : e2b) {
        if (bizOpen <= 0) break;
        --bizOpen;
        ++econOpen;
        res.emplace_back(p.id, "B");
    }
    for (const auto& p : sb) {
        if (firstOpen > 0) { --firstOpen; res.emplace_back(p.id, "F"); }
        else if (bizOpen > 0) { --bizOpen; res.emplace_back(p.id, "B"); }
        else if (econOpen > 0) { --econOpen; res.emplace_back(p.id, "E"); }
    }
    std::sort(res.begin(), res.end());
    std::vector<std::string> out;
    out.reserve(res.size());
    for (const auto& [id, cab] : res) out.push_back(id + ":" + cab);
    return out;
}
