#include <algorithm>
#include <map>
#include <string>
#include <tuple>
#include <unordered_map>
#include <vector>

std::vector<std::string> summarizeTraceSpans(
    const std::vector<std::tuple<std::string, std::string, long long, long long>>& spans
) {
    struct Span { long long s, e; };
    std::map<std::string, Span> byId;
    std::unordered_map<std::string, std::vector<Span>> kids;
    for (const auto& [sid, par, s, e] : spans) {
        byId[sid] = {s, e};
        if (!par.empty()) kids[par].push_back({s, e});
    }
    std::vector<std::string> out;
    out.reserve(byId.size());
    for (const auto& [sid, sp] : byId) {
        std::vector<std::pair<long long, long long>> segs;
        auto it = kids.find(sid);
        if (it != kids.end()) {
            for (const auto& c : it->second) {
                long long a = std::max(sp.s, c.s);
                long long b = std::min(sp.e, c.e);
                if (a < b) segs.emplace_back(a, b);
            }
        }
        std::sort(segs.begin(), segs.end());
        long long childCov = 0;
        long long cs = 0, ce = 0;
        bool has = false;
        for (const auto& [a, b] : segs) {
            if (!has) {
                cs = a; ce = b; has = true;
            } else if (a <= ce) {
                ce = std::max(ce, b);
            } else {
                childCov += ce - cs;
                cs = a; ce = b;
            }
        }
        if (has) childCov += ce - cs;
        long long tot = sp.e - sp.s;
        out.push_back(sid + " " + std::to_string(tot) + " " + std::to_string(tot - childCov));
    }
    return out;
}
