#include <map>
#include <set>
#include <string>
#include <tuple>
#include <unordered_map>
#include <vector>

std::vector<std::string> runParcelLockers(
    const std::vector<std::pair<int, int>>& lockers,
    const std::vector<std::tuple<long long, std::string, std::string, int, long long>>& events
) {
    std::set<std::pair<int, int>> freeLockers;
    for (const auto& [lid, sz] : lockers) freeLockers.emplace(sz, lid);
    struct Parcel { int sz; int lid; long long exp; };
    std::unordered_map<std::string, Parcel> occ;
    std::vector<std::string> out;

    for (const auto& [ts, op, pid, sz, ttl] : events) {
        if (op == "DROP") {
            auto it = freeLockers.lower_bound({sz, -2147483648});
            if (it == freeLockers.end()) {
                out.push_back("FULL");
            } else {
                auto [lsz, lid] = *it;
                freeLockers.erase(it);
                occ[pid] = {lsz, lid, ts + ttl};
                out.push_back("LOCKER:" + std::to_string(lid));
            }
        } else if (op == "PICK") {
            auto it = occ.find(pid);
            if (it == occ.end()) {
                out.push_back("MISSING");
            } else {
                Parcel p = it->second;
                occ.erase(it);
                freeLockers.emplace(p.sz, p.lid);
                if (ts <= p.exp) out.push_back("OK:0");
                else out.push_back("LATE:" + std::to_string((ts - p.exp) * 50));
            }
        } else {
            int cnt = 0;
            for (auto it = occ.begin(); it != occ.end(); ) {
                if (it->second.exp < ts) {
                    freeLockers.emplace(it->second.sz, it->second.lid);
                    it = occ.erase(it);
                    ++cnt;
                } else {
                    ++it;
                }
            }
            out.push_back("PURGED:" + std::to_string(cnt));
        }
    }
    return out;
}
