import heapq
import sys

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    nl, ne = map(int, lines[0].split())
    by_sz = {1: [], 2: [], 3: []}
    for line in lines[1:1 + nl]:
        lid, sz = map(int, line.split())
        heapq.heappush(by_sz[sz], lid)
    occ = {}
    exp_heap = []
    out = []
    for line in lines[1 + nl:1 + nl + ne]:
        p = line.split()
        ts = int(p[0])
        op = p[1]
        if op == "DROP":
            pid, req_sz, ttl = p[2], int(p[3]), int(p[4])
            chosen = None
            for sz in range(req_sz, 4):
                if by_sz[sz]:
                    lid = heapq.heappop(by_sz[sz])
                    chosen = (sz, lid)
                    break
            if chosen is None:
                out.append("FULL")
            else:
                lsz, lid = chosen
                exp = ts + ttl
                occ[pid] = (lsz, lid, exp)
                heapq.heappush(exp_heap, (exp, pid))
                out.append(f"LOCKER:{lid}")
        elif op == "PICK":
            pid = p[2]
            rec = occ.pop(pid, None)
            if rec is None:
                out.append("MISSING")
            else:
                lsz, lid, exp = rec
                heapq.heappush(by_sz[lsz], lid)
                if ts <= exp:
                    out.append("OK:0")
                else:
                    out.append(f"LATE:{(ts - exp) * 50}")
        else:
            cnt = 0
            while exp_heap and exp_heap[0][0] < ts:
                exp, pid = heapq.heappop(exp_heap)
                rec = occ.get(pid)
                if rec is not None and rec[2] == exp:
                    lsz, lid, _ = occ.pop(pid)
                    heapq.heappush(by_sz[lsz], lid)
                    cnt += 1
            out.append(f"PURGED:{cnt}")
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))

if __name__ == "__main__":
    main()
