            e2b.append(item)
        elif booked == "NONE":
            sb.append(item)
    b2f.sort()
    e2b.sort()
    sb.sort()
    res = []
    for _, _, pid in b2f:
        if f_o <= 0:
            break
        f_o -= 1
        b_o += 1
        res.append((pid, "F"))
    for _, _, pid in e2b:
        if b_o <= 0:
            break
        b_o -= 1
        e_o += 1
        res.append((pid, "B"))
    for _, _, pid in sb:
