from .lots import eligible_lots


class Warehouse:
    def __init__(self):
        self.inv = {}
        self.seq = 0

    def stock(self, lot_id, sku, qty, exp):
        self.seq += 1
        self.inv.setdefault(sku, []).append({"id": lot_id, "qty": qty, "exp": exp, "seq": self.seq})

    def pick(self, sku, req_qty, today):
        avail = eligible_lots(self.inv.get(sku, []), today)
        if not avail:
            return None
        need = req_qty
        picks = []
        for lot in avail:
            if need == 0:
                break
            take = min(need, lot["qty"])
            lot["qty"] -= take
            need -= take
            picks.append((lot["id"], take))
        return picks

