"""Webhook delivery state machine."""

from .backoff import compute_delay


class WebhookDispatcher:
    def __init__(self, base_delay, max_delay, max_attempts):
        self.base_delay = base_delay
        self.max_delay = max_delay
        self.max_attempts = max_attempts
        self.state = {}

    def handle(self, event_id, ts, succeeded):
        nxt, att, st = self.state.get(event_id, (0, 0, "PENDING"))
        if st != "PENDING":
            return st
        att += 1
        if ts < nxt:
            self.state[event_id] = (nxt, att, st)
            return "DEFERRED"
        if succeeded:
            self.state[event_id] = (ts, att, "DELIVERED")
            return "DELIVERED"
        if att >= self.max_attempts:
            self.state[event_id] = (ts, att, "DEAD")
            return "DEAD"
        nxt_ts = ts + compute_delay(self.base_delay, self.max_delay, att)
        self.state[event_id] = (nxt_ts, att, "PENDING")
        return f"RETRY@{nxt_ts}"

