def plan_evictions(lru_keys, meta, exclude_key, bytes_needed):
    if bytes_needed <= 0:
        return []
    freed = 0
    chosen = []
    for k in reversed(lru_keys):
        if k == exclude_key:
            continue
        chosen.append(k)
        freed += meta[k]["size"]
        if freed >= bytes_needed:
            return chosen
    return None

