class BuildCache:
    def __init__(self, capacity_bytes):
        self.cap = capacity_bytes
        self.used = 0
        self.order = []
        self.meta = {}

    def get(self, key):
        if key not in self.meta:
            return False
        self.order.remove(key)
        self.order.insert(0, key)
        return True

    def unpin(self, key):
        if key not in self.meta:
            return False
        self.meta[key]["pinned"] = False
        return True

    def put(self, key, size_bytes, pinned=False):
        if size_bytes > self.cap:
            return False
        old_sz = self.meta[key]["size"] if key in self.meta else 0
        needed = (self.used - old_sz + size_bytes) - self.cap
        for v in list(reversed(self.order)):
            if self.used - old_sz + size_bytes <= self.cap:
                break
            if v != key and not self.meta[v]["pinned"]:
                self.used -= self.meta.pop(v)["size"]
                self.order.remove(v)
        if self.used - old_sz + size_bytes > self.cap:
            return False
        if key in self.meta:
            self.order.remove(key)
        self.order.insert(0, key)
        self.meta[key] = {"size": size_bytes, "pinned": pinned}
        self.used = self.used - old_sz + size_bytes
        return True

