            if rem > 0:
                self.qty[oid] = rem
                heapq.heappush(self.bids, (-price, self.seq, oid))
        else:
            while rem > 0 and self.bids and -self.bids[0][0] >= price:
                nbp, _, bid = self.bids[0]
                bq = self.qty[bid]
                tr = min(rem, bq)
