interface WindowInterval {
  start: number;
  end: number;
}
interface CreditTier {
  minDowntime: number;
  creditBps: number;
}
interface SlaReport {
  effectiveDowntime: number;
  creditBps: number;
}

function mergeClampedWindows(pStart: number, pEnd: number, raw: WindowInterval[]): Array<[number, number]> {
  const clamped: Array<[number, number]> = [];
  for (const w of raw) {
    const a = Math.max(pStart, w.start);
    const b = Math.min(pEnd, w.end);
    if (a < b) clamped.push([a, b]);
  }
  clamped.sort((x, y) => (x[0] !== y[0] ? x[0] - y[0] : x[1] - y[1]));
  const merged: Array<[number, number]> = [];
  for (const [a, b] of clamped) {
    if (merged.length === 0 || a > merged[merged.length - 1][1]) {
      merged.push([a, b]);
    } else {
      merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], b);
    }
  }
  return merged;
}

function calculateSlaCredits(
  periodStart: number,
  periodEnd: number,
  maintenance: WindowInterval[],
  outages: WindowInterval[],
  tiers: CreditTier[],
): SlaReport {
  if (periodEnd < periodStart) throw new Error("bad period");
  const mnt = mergeClampedWindows(periodStart, periodEnd, maintenance);
  const outs = mergeClampedWindows(periodStart, periodEnd, outages);
  let effectiveDowntime = 0;
  let j = 0;
  for (const [os, oe] of outs) {
    let cur = os;
    while (j < mnt.length && mnt[j][1] <= cur) j += 1;
    let k = j;
    while (k < mnt.length && mnt[k][0] < oe) {
      if (mnt[k][0] > cur) effectiveDowntime += mnt[k][0] - cur;
      cur = Math.max(cur, mnt[k][1]);
      if (cur >= oe) break;
      k += 1;
    }
    if (cur < oe) effectiveDowntime += oe - cur;
  }
  let creditBps = 0;
  for (const t of tiers) {
    if (effectiveDowntime >= t.minDowntime && t.creditBps > creditBps) {
      creditBps = t.creditBps;
    }
  }
  return { effectiveDowntime, creditBps };
}
