type DnsOp =
  | { op: "SET"; name: string; rtype: "A" | "CNAME"; value: string; ttl: number; ts: number }
  | { op: "QUERY"; name: string; ts: number };

function evaluateDnsOps(ops: DnsOp[]): string[] {
  const cache = new Map<string, { rtype: "A" | "CNAME"; value: string; exp: number }>();
  const out: string[] = [];
  let prevTs: number | null = null;
  for (const item of ops) {
    if (prevTs !== null && item.ts < prevTs) throw new Error("decreasing ts");
    prevTs = item.ts;
    if (item.op === "SET") {
      if (item.ttl <= 0) throw new Error("bad ttl");
      cache.set(item.name, { rtype: item.rtype, value: item.value, exp: item.ts + item.ttl });
    } else {
      let cur = item.name;
      const seen = new Set<string>();
      let ans = "LOOP";
      for (let hop = 0; hop <= 8; hop += 1) {
        if (seen.has(cur)) {
          ans = "LOOP";
          break;
        }
        seen.add(cur);
        const rec = cache.get(cur);
        if (!rec || item.ts >= rec.exp) {
          ans = "NXDOMAIN";
          break;
        }
