type WarehouseOp =
  | { op: "STOCK"; lotId: string; sku: string; qty: number; expiryDay: number }
  | { op: "PICK"; orderId: string; sku: string; reqQty: number; today: number };

interface PickOutcome {
  orderId: string;
  status: "FILLED" | "SHORT";
  allocations: Array<{ lotId: string; qty: number }>;
}

function runFefoWarehouse(ops: WarehouseOp[]): PickOutcome[] {
  const inv = new Map<string, Array<{ seq: number; lotId: string; rem: number; exp: number }>>();
  let seq = 0;
  const out: PickOutcome[] = [];
  for (const item of ops) {
    if (item.op === "STOCK") {
      if (item.qty <= 0) throw new Error("bad qty");
      seq += 1;
      const list = inv.get(item.sku) ?? [];
      list.push({ seq, lotId: item.lotId, rem: item.qty, exp: item.expiryDay });
      inv.set(item.sku, list);
    } else {
      if (item.reqQty <= 0) throw new Error("bad reqQty");
      const list = (inv.get(item.sku) ?? []).filter((l) => l.rem > 0 && l.exp >= item.today);
      list.sort((a, b) => (a.exp !== b.exp ? a.exp - b.exp : a.seq - b.seq));
      const total = list.reduce((s, l) => s + l.rem, 0);
      if (total < item.reqQty) {
        out.push({ orderId: item.orderId, status: "SHORT", allocations: [] });
        continue;
      }
      let need = item.reqQty;
      const allocations: Array<{ lotId: string; qty: number }> = [];
      for (const lot of list) {
        if (need === 0) break;
        const take = Math.min(need, lot.rem);
        lot.rem -= take;
        need -= take;
        allocations.push({ lotId: lot.lotId, qty: take });
      }
      out.push({ orderId: item.orderId, status: "FILLED", allocations });
    }
  }
  return out;
}
