interface BreakerCall {
  ts: number;
  succeeded: boolean;
}
interface BreakerReport {
  outcomes: Array<"ALLOW" | "FAIL" | "REJECT">;
  finalState: "CLOSED" | "OPEN" | "HALF_OPEN";
}

function runCircuitBreaker(
  failThreshold: number,
  cooldown: number,
  halfOpenTarget: number,
  calls: BreakerCall[],
): BreakerReport {
  if (failThreshold <= 0 || cooldown < 0 || halfOpenTarget <= 0) throw new Error("bad config");
  let state: "CLOSED" | "OPEN" | "HALF_OPEN" = "CLOSED";
  let fails = 0;
  let openUntil = 0;
  let halfOk = 0;
  let prevTs: number | null = null;
  const outcomes: Array<"ALLOW" | "FAIL" | "REJECT"> = [];
  for (const c of calls) {
    if (prevTs !== null && c.ts < prevTs) throw new Error("decreasing ts");
    prevTs = c.ts;
    if (state === "OPEN") {
      if (c.ts < openUntil) {
        outcomes.push("REJECT");
        continue;
      }
      state = "HALF_OPEN";
      halfOk = 0;
    }
    if (state === "CLOSED") {
      if (c.succeeded) {
        fails = 0;
        outcomes.push("ALLOW");
      } else {
        fails += 1;
        if (fails >= failThreshold) {
          state = "OPEN";
          openUntil = c.ts + cooldown;
        }
        outcomes.push("FAIL");
      }
    } else {
      if (c.succeeded) {
        halfOk += 1;
        if (halfOk >= halfOpenTarget) {
          state = "CLOSED";
          fails = 0;
        }
        outcomes.push("ALLOW");
      } else {
        state = "OPEN";
        openUntil = c.ts + cooldown;
        outcomes.push("FAIL");
      }
    }
  }
  return { outcomes, finalState: state };
}
