interface WebhookEvent {
  eventId: string;
  ts: number;
  succeeded: boolean;
}

function processWebhooks(
  baseDelay: number,
  maxDelay: number,
  maxAttempts: number,
  events: WebhookEvent[],
): Array<{ eventId: string; status: string }> {
  if (baseDelay <= 0 || maxDelay < baseDelay || maxAttempts < 1) throw new Error("bad policy");
  const state = new Map<string, { nxt: number; att: number; st: string }>();
  const out: Array<{ eventId: string; status: string }> = [];
  let prevTs: number | null = null;
  for (const ev of events) {
    if (prevTs !== null && ev.ts < prevTs) throw new Error("decreasing ts");
    prevTs = ev.ts;
    let cur = state.get(ev.eventId);
    if (!cur) {
      cur = { nxt: 0, att: 0, st: "PENDING" };
      state.set(ev.eventId, cur);
    }
    if (cur.st !== "PENDING") {
      out.push({ eventId: ev.eventId, status: cur.st });
      continue;
    }
    if (ev.ts < cur.nxt) {
      out.push({ eventId: ev.eventId, status: "DEFERRED" });
      continue;
    }
    cur.att += 1;
    if (ev.succeeded) {
      cur.st = "DELIVERED";
      out.push({ eventId: ev.eventId, status: "DELIVERED" });
    } else if (cur.att >= maxAttempts) {
      cur.st = "DEAD";
      out.push({ eventId: ev.eventId, status: "DEAD" });
    } else {
      const delay = Math.min(maxDelay, baseDelay * (2 ** (cur.att - 1)));
      cur.nxt = ev.ts + delay;
      out.push({ eventId: ev.eventId, status: `RETRY@${cur.nxt}` });
    }
  }
  return out;
}
