interface SpanInput {
  spanId: string;
  parentId: string | null;
  startTs: number;
  endTs: number;
}
interface SpanSummary {
  spanId: string;
  totalTime: number;
  selfTime: number;
}

function summarizeTraceSpans(spans: SpanInput[]): SpanSummary[] {
  const byId = new Map<string, SpanInput>();
  const kids = new Map<string, SpanInput[]>();
  for (const s of spans) {
    if (byId.has(s.spanId) || s.endTs < s.startTs) throw new Error("bad span");
    byId.set(s.spanId, s);
    if (s.parentId !== null) {
      const list = kids.get(s.parentId) ?? [];
      list.push(s);
      kids.set(s.parentId, list);
    }
  }
  const out: SpanSummary[] = [];
  const ids = Array.from(byId.keys()).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  for (const sid of ids) {
    const sp = byId.get(sid)!;
    const segs: Array<[number, number]> = [];
    for (const c of kids.get(sid) ?? []) {
      const a = Math.max(sp.startTs, c.startTs);
      const b = Math.min(sp.endTs, c.endTs);
      if (a < b) segs.push([a, b]);
    }
    segs.sort((x, y) => (x[0] !== y[0] ? x[0] - y[0] : x[1] - y[1]));
    let cov = 0;
    let cs = 0;
    let ce = 0;
    let has = false;
    for (const [a, b] of segs) {
      if (!has) {
        cs = a; ce = b; has = true;
      } else if (a <= ce) {
        ce = Math.max(ce, b);
      } else {
        cov += ce - cs;
        cs = a; ce = b;
      }
    }
    if (has) cov += ce - cs;
    const totalTime = sp.endTs - sp.startTs;
    out.push({ spanId: sid, totalTime, selfTime: totalTime - cov });
  }
  return out;
}
