interface LockerSpec {
  id: number;
  size: 1 | 2 | 3;
}
type LockerEvent =
  | { ts: number; kind: "DROP"; parcelId: string; size: 1 | 2 | 3; ttl: number }
  | { ts: number; kind: "PICK"; parcelId: string }
  | { ts: number; kind: "EXPIRE" };

function simulateParcelLockers(lockers: LockerSpec[], events: LockerEvent[]): string[] {
  const free = new Map<number, 1 | 2 | 3>();
  for (const l of lockers) {
    if (free.has(l.id)) throw new Error("duplicate locker");
    free.set(l.id, l.size);
  }
  const occ = new Map<string, { lid: number; lsz: 1 | 2 | 3; exp: number }>();
  const out: string[] = [];
  let prevTs: number | null = null;
  for (const ev of events) {
    if (prevTs !== null && ev.ts < prevTs) throw new Error("decreasing ts");
    prevTs = ev.ts;
    if (ev.kind === "DROP") {
      let bestId: number | null = null;
      let bestSz = 99;
      for (const [lid, lsz] of free.entries()) {
        if (lsz >= ev.size && (lsz < bestSz || (lsz === bestSz && (bestId === null || lid < bestId)))) {
          bestSz = lsz;
          bestId = lid;
        }
      }
      if (bestId === null) {
        out.push("FULL");
      } else {
        free.delete(bestId);
        occ.set(ev.parcelId, { lid: bestId, lsz: bestSz as 1 | 2 | 3, exp: ev.ts + ev.ttl });
        out.push(`LOCKER:${bestId}`);
      }
    } else if (ev.kind === "PICK") {
      const rec = occ.get(ev.parcelId);
      if (!rec) {
        out.push("MISSING");
      } else {
        occ.delete(ev.parcelId);
        free.set(rec.lid, rec.lsz);
        out.push(ev.ts <= rec.exp ? "OK:0" : `LATE:${(ev.ts - rec.exp) * 50}`);
      }
    } else {
      let cnt = 0;
      for (const [pid, rec] of Array.from(occ.entries())) {
        if (rec.exp < ev.ts) {
          occ.delete(pid);
          free.set(rec.lid, rec.lsz);
          cnt += 1;
        }
      }
      out.push(`PURGED:${cnt}`);
    }
  }
  return out;
}
