  for (const s of initialShifts) {
    if (shifts.has(s.shiftId)) throw new Error("duplicate shiftId");
    shifts.set(s.shiftId, { emp: s.emp, day: s.day, hours: s.hours });
    if (!empDays.has(s.emp)) empDays.set(s.emp, new Set());
    empDays.get(s.emp)!.add(s.day);
    empHrs.set(s.emp, (empHrs.get(s.emp) ?? 0) + s.hours);
  }
  const out: Array<"NOOP" | "OK" | "REJECT"> = [];
  for (const sw of swaps) {
    const cur = shifts.get(sw.shiftId);
    if (!cur) throw new Error("unknown shiftId");
    if (sw.newEmp === cur.emp) {
      out.push("NOOP");
      continue;
    }
    if (!(sw.newEmp in maxHours)) {
      out.push("REJECT");
      continue;
    }
    const ds = empDays.get(sw.newEmp)!;
    const hrs = empHrs.get(sw.newEmp)!;
