function meterApiRequests(policies, requests) {
  const buckets = new Map();
  for (const [tenant, cfg] of Object.entries(policies)) {
    if (cfg.capacity <= 0 || cfg.refillPerSec < 0 || cfg.burstCredit < 0) throw new Error("bad policy");
    buckets.set(tenant, {
      tokens: cfg.capacity,
      credit: cfg.burstCredit,
      lastTs: 0,
      cap: cfg.capacity,
      rate: cfg.refillPerSec,
    });
  }
  let prevTs = -Infinity;
  const out = [];
  for (const req of requests) {
    if (req.ts < prevTs || req.cost <= 0) throw new Error("bad request");
    prevTs = req.ts;
    const b = buckets.get(req.tenant);
    if (!b) {
      out.push("UNKNOWN");
      continue;
    }
    const dt = req.ts - b.lastTs;
    b.tokens = Math.min(b.cap, b.tokens + dt * b.rate);
    b.lastTs = req.ts;
    if (b.tokens >= req.cost) {
      b.tokens -= req.cost;
      out.push("PASS");
    } else if (b.tokens + b.credit >= req.cost) {
      const rem = req.cost - b.tokens;
      b.tokens = 0;
      b.credit -= rem;
      out.push("BURST");
    } else {
      out.push("DROP");
    }
  }
  return out;
}
