function evaluateFeatureFlags(flags, context) {
  const hashUser = (seed, uid) => {
    let h = 2166136261;
    const s = `${seed}:${uid}`;
    for (let i = 0; i < s.length; i += 1) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 16777619) >>> 0;
    }
    return h % 100;
  };
  const matchCond = (c) => {
    const val = context[c.attr];
    if (c.op === "EQ") return val === c.value;
    if (c.op === "IN") return Array.isArray(c.value) && c.value.includes(val);
    if (c.op === "GTE") return typeof val === "number" && val >= c.value;
    throw new Error("unknown op");
  };
  const out = {};
  for (const flag of flags) {
    if (!flag.enabled) {
      out[flag.key] = flag.fallback;
      continue;
    }
    let decided = null;
    for (const rule of flag.rules) {
      if (rule.when.every(matchCond)) {
        const pct = rule.rolloutPct ?? 100;
        if (pct === 100 || hashUser(flag.key, String(context.userId ?? "")) < pct) {
          decided = rule.variant;
        }
        break;
      }
    }
    out[flag.key] = decided !== null ? decided : flag.fallback;
  }
  return out;
}
