function formatMarkdownTable(headers, alignments, rows) {
  if (headers.length === 0 || headers.length !== alignments.length) throw new Error("header/align mismatch");
  const esc = (s) => String(s).replace(/\|/g, "\\|").replace(/\n/g, " ");
  const cols = headers.length;
  const normHeaders = headers.map(esc);
  const normRows = rows.map((r) => {
    if (r.length !== cols) throw new Error("row width mismatch");
    return r.map(esc);
  });
  const widths = normHeaders.map((h, i) => {
    let w = Math.max(3, h.length);
    for (const r of normRows) w = Math.max(w, r[i].length);
    return w;
  });
  const pad = (text, w, align) => {
    const gap = w - text.length;
    if (align === "right") return " ".repeat(gap) + text;
    if (align === "center") {
      const left = Math.floor(gap / 2);
      return " ".repeat(left) + text + " ".repeat(gap - left);
    }
    return text + " ".repeat(gap);
  };
  const sep = (w, align) => {
    if (align === "left") return ":" + "-".repeat(w - 1);
    if (align === "right") return "-".repeat(w - 1) + ":";
    if (align === "center") return ":" + "-".repeat(w - 2) + ":";
    throw new Error("bad alignment");
  };
  const line = (cells) => "| " + cells.map((c, i) => pad(c, widths[i], alignments[i])).join(" | ") + " |";
  const out = [line(normHeaders), "| " + widths.map((w, i) => sep(w, alignments[i])).join(" | ") + " |"];
  for (const r of normRows) out.push(line(r));
  return out.join("\n");
}
