function propagateDirtyNodes(nodes, edges, updates) {
  const indeg = new Map();
  const adj = new Map();
  for (const id of nodes) {
    if (indeg.has(id)) throw new Error("duplicate node");
    indeg.set(id, 0);
    adj.set(id, []);
  }
  for (const [src, dst] of edges) {
    if (!indeg.has(src) || !indeg.has(dst)) throw new Error("unknown node");
    adj.get(src).push(dst);
    indeg.set(dst, indeg.get(dst) + 1);
  }
  const q = [];
  for (const [id, d] of indeg.entries()) {
    if (d === 0) q.push(id);
  }
  const topo = [];
  for (let i = 0; i < q.length; i += 1) {
    const u = q[i];
    topo.push(u);
    for (const v of adj.get(u)) {
      const nd = indeg.get(v) - 1;
      indeg.set(v, nd);
      if (nd === 0) q.push(v);
    }
  }
  if (topo.length !== nodes.length) throw new Error("cycle");
  const dirty = new Set();
  for (const u of updates) {
    if (!indeg.has(u)) throw new Error("unknown update");
    dirty.add(u);
  }
  const order = [];
  for (const u of topo) {
    if (!dirty.has(u)) continue;
    order.push(u);
    for (const v of adj.get(u)) dirty.add(v);
  }
  return order;
}
