function canonicalizeQuery(rawQuery, dropKeys, arrayMode) {
  const trimmed = rawQuery.startsWith("?") ? rawQuery.slice(1) : rawQuery;
  if (!trimmed) return "";
  const drop = new Set(dropKeys);
  const grouped = new Map();
  for (const part of trimmed.split("&")) {
    if (!part) continue;
    const eq = part.indexOf("=");
    const rawK = eq === -1 ? part : part.slice(0, eq);
    const rawV = eq === -1 ? "" : part.slice(eq + 1);
    const k = decodeURIComponent(rawK.replace(/\+/g, " "));
    const v = decodeURIComponent(rawV.replace(/\+/g, " "));
    if (drop.has(k)) continue;
    if (!grouped.has(k)) grouped.set(k, []);
    grouped.get(k).push(v);
  }
  const keys = Array.from(grouped.keys()).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const pairs = [];
  for (const k of keys) {
    const vals = grouped.get(k);
    if (arrayMode === "last") {
      pairs.push(`${encodeURIComponent(k)}=${encodeURIComponent(vals[vals.length - 1])}`);
    } else if (arrayMode === "repeat") {
      for (const v of vals) pairs.push(`${encodeURIComponent(k)}=${encodeURIComponent(v)}`);
    } else if (arrayMode === "csv") {
      pairs.push(`${encodeURIComponent(k)}=${vals.map((v) => encodeURIComponent(v)).join(",")}`);
    } else {
      throw new Error("bad arrayMode");
    }
  }
  return pairs.join("&");
}
