async function runTaskPool(concurrency, factories) {
  if (!Number.isInteger(concurrency) || concurrency <= 0) throw new Error("bad concurrency");
  const results = new Array(factories.length);
  let nextIdx = 0;
  let activePeak = 0;
  let active = 0;
  const worker = async () => {
    while (nextIdx < factories.length) {
      const idx = nextIdx;
      nextIdx += 1;
      active += 1;
      if (active > activePeak) activePeak = active;
      try {
        const value = await factories[idx]();
        results[idx] = { status: "fulfilled", value };
      } catch (err) {
        results[idx] = { status: "rejected", reason: err instanceof Error ? err.message : String(err) };
      } finally {
        active -= 1;
      }
    }
  };
  const workers = [];
  const n = Math.min(concurrency, factories.length);
  for (let i = 0; i < n; i += 1) workers.push(worker());
  await Promise.all(workers);
  return { peak: activePeak, results };
}
