function resolveCssCascade(rules) {
  const specificity = (sel) => {
    let ids = 0;
    let cls = 0;
    let tags = 0;
    for (const part of sel.trim().split(/\s+/)) {
      if (!part || part === ">") continue;
      let cur = part;
      const idMatches = cur.match(/#[A-Za-z0-9_-]+/g) || [];
      ids += idMatches.length;
      cur = cur.replace(/#[A-Za-z0-9_-]+/g, "");
      const clsMatches = cur.match(/(\.[A-Za-z0-9_-]+|\[[^\]]+\]|:[A-Za-z0-9_-]+)/g) || [];
      cls += clsMatches.length;
      cur = cur.replace(/(\.[A-Za-z0-9_-]+|\[[^\]]+\]|:[A-Za-z0-9_-]+)/g, "");
      if (cur && cur !== "*") tags += 1;
    }
    return [ids, cls, tags];
  };
  const winners = new Map();
  rules.forEach((rule, order) => {
    const [a, b, c] = specificity(rule.selector);
    for (const decl of rule.declarations) {
      const imp = decl.important ? 1 : 0;
      const cand = [imp, a, b, c, order, decl.value];
      const prev = winners.get(decl.prop);
      if (!prev) {
        winners.set(decl.prop, cand);
      } else {
        let better = false;
        for (let i = 0; i < 5; i += 1) {
          if (cand[i] !== prev[i]) {
            better = cand[i] > prev[i];
            break;
          }
        }
        if (better) winners.set(decl.prop, cand);
      }
    }
  });
  const out = {};
  for (const prop of Array.from(winners.keys()).sort()) {
    out[prop] = winners.get(prop)[5];
  }
  return out;
}
