def _merge_clamped(p_start: int, p_end: int, raw: list[tuple[int, int]]) -> list[tuple[int, int]]:
    clamped = []
    for s, e in raw:
        a = p_start if p_start > s else s
        b = p_end if p_end < e else e
        if a < b:
            clamped.append((a, b))
    clamped.sort()
    merged = []
    for a, b in clamped:
        if not merged or a > merged[-1][1]:
            merged.append([a, b])
        elif b > merged[-1][1]:
            merged[-1][1] = b
    return [(a, b) for a, b in merged]

def compute_sla_credit(
    period_start: int,
    period_end: int,
    maintenance: list[tuple[int, int]],
    outages: list[tuple[int, int]],
    tiers: list[tuple[int, int]],
) -> tuple[int, int]:
    if period_end < period_start:
        raise ValueError("invalid period")
    mnt = _merge_clamped(period_start, period_end, maintenance)
    outs = _merge_clamped(period_start, period_end, outages)
    down = 0
    j = 0
    for os_, oe in outs:
        cur = os_
        while j < len(mnt) and mnt[j][1] <= cur:
            j += 1
        k = j
        while k < len(mnt) and mnt[k][0] < oe:
            ms, me = mnt[k]
            if ms > cur:
                down += ms - cur
            if me > cur:
                cur = me
            if cur >= oe:
                break
            k += 1
        if cur < oe:
            down += oe - cur
    bps = 0
    for thr, cr in tiers:
        if down >= thr and cr > bps:
            bps = cr
    return (down, bps)
