def resolve_dns(ops: list[tuple]) -> list[str]:
    cache = {}
    out = []
    prev_ts = None
    for item in ops:
        op = item[0]
        if op == "SET":
            _, name, rtype, val, ttl, ts = item
            if prev_ts is not None and ts < prev_ts:
                raise ValueError("decreasing ts")
            prev_ts = ts
            if ttl <= 0 or rtype not in ("A", "CNAME"):
                raise ValueError("invalid record")
            cache[name] = (rtype, val, ts + ttl)
        elif op == "QUERY":
            _, name, ts = item
            if prev_ts is not None and ts < prev_ts:
                raise ValueError("decreasing ts")
            prev_ts = ts
            cur = name
            seen = set()
            ans = "LOOP"
            for _ in range(9):
                if cur in seen:
                    ans = "LOOP"
                    break
                seen.add(cur)
                rec = cache.get(cur)
                if rec is None or ts >= rec[2]:
                    ans = "NXDOMAIN"
                    break
                if rec[0] == "A":
                    ans = rec[1]
                    break
                cur = rec[1]
            out.append(ans)
        else:
            raise ValueError("unknown op")
    return out
