def run_circuit_breaker(
    fail_threshold: int,
    cooldown: int,
    half_open_target: int,
    calls: list[tuple[int, bool]],
) -> tuple[list[str], str]:
    if fail_threshold <= 0 or cooldown < 0 or half_open_target <= 0:
        raise ValueError("invalid policy")
    state = "CLOSED"
    fails = 0
    open_until = 0
    half_ok = 0
    prev_ts = None
    out = []
    for ts, ok in calls:
        if prev_ts is not None and ts < prev_ts:
            raise ValueError("decreasing ts")
        prev_ts = ts
        if state == "OPEN":
            if ts < open_until:
                out.append("REJECT")
                continue
            state = "HALF_OPEN"
            half_ok = 0
        if state == "CLOSED":
            if ok:
                fails = 0
                out.append("ALLOW")
            else:
                fails += 1
                if fails >= fail_threshold:
                    state = "OPEN"
                    open_until = ts + cooldown
                out.append("FAIL")
        else:
            if ok:
                half_ok += 1
                if half_ok >= half_open_target:
                    state = "CLOSED"
                    fails = 0
                out.append("ALLOW")
            else:
                state = "OPEN"
                open_until = ts + cooldown
                out.append("FAIL")
    return (out, state)
