from collections import defaultdict

def summarize_trace_spans(
    spans: list[tuple[str, str | None, int, int]],
) -> list[tuple[str, int, int]]:
    by_id = {}
    kids = defaultdict(list)
    for sid, par, s, e in spans:
        if sid in by_id or e < s:
            raise ValueError("invalid span")
        by_id[sid] = (s, e)
        if par is not None:
            kids[par].append((s, e))
    out = []
    for sid in sorted(by_id):
        ps, pe = by_id[sid]
        segs = []
        for cs, ce in kids[sid]:
            a = ps if ps > cs else cs
            b = pe if pe < ce else ce
            if a < b:
                segs.append((a, b))
        segs.sort()
        cov = 0
        cs = ce = None
        for a, b in segs:
            if cs is None:
                cs, ce = a, b
            elif a <= ce:
                if b > ce:
                    ce = b
            else:
                cov += ce - cs
                cs, ce = a, b
        if cs is not None:
            cov += ce - cs
        tot = pe - ps
        out.append((sid, tot, tot - cov))
    return out
