import heapq

def simulate_parcel_lockers(
    lockers: list[tuple[int, int]],
    events: list[tuple],
) -> list[str]:
    seen_lockers = set()
    by_sz = {1: [], 2: [], 3: []}
    for lid, sz in lockers:
        if lid in seen_lockers or sz not in (1, 2, 3):
            raise ValueError("invalid locker")
        seen_lockers.add(lid)
        heapq.heappush(by_sz[sz], lid)
    occ = {}
    exp_heap = []
    prev_ts = None
    out = []
    for ev in events:
        ts, kind = ev[0], ev[1]
        if prev_ts is not None and ts < prev_ts:
            raise ValueError("decreasing ts")
        prev_ts = ts
        if kind == "DROP":
            _, _, pid, req_sz, ttl = ev
            chosen = None
            for sz in range(req_sz, 4):
                if by_sz[sz]:
                    chosen = (sz, heapq.heappop(by_sz[sz]))
                    break
            if chosen is None:
                out.append("FULL")
            else:
                lsz, lid = chosen
                exp = ts + ttl
                occ[pid] = (lsz, lid, exp)
                heapq.heappush(exp_heap, (exp, pid))
                out.append(f"LOCKER:{lid}")
        elif kind == "PICK":
            _, _, pid = ev
            rec = occ.pop(pid, None)
            if rec is None:
                out.append("MISSING")
            else:
                lsz, lid, exp = rec
                heapq.heappush(by_sz[lsz], lid)
                out.append("OK:0" if ts <= exp else f"LATE:{(ts - exp) * 50}")
        elif kind == "EXPIRE":
            cnt = 0
            while exp_heap and exp_heap[0][0] < ts:
                exp, pid = heapq.heappop(exp_heap)
                rec = occ.get(pid)
                if rec is not None and rec[2] == exp:
                    lsz, lid, _ = occ.pop(pid)
                    heapq.heappush(by_sz[lsz], lid)
                    cnt += 1
            out.append(f"PURGED:{cnt}")
        else:
            raise ValueError("unknown event")
    return out
