    econ_open: int,
    passengers: list[tuple[str, str, str, str, int]],
) -> list[tuple[str, str]]:
    if first_open < 0 or biz_open < 0 or econ_open < 0:
        raise ValueError("open seats cannot be negative")
    b2f, e2b, sb = [], [], []
    for pid, booked, tier, req, seq in passengers:
