        elif booked == "E" and req == "B":
            e2b.append(item)
        elif booked == "NONE":
            sb.append(item)
    b2f.sort()
    e2b.sort()
    sb.sort()
    res = []
    for _, _, pid in b2f:
        if first_open <= 0:
            break
        first_open -= 1
        biz_open += 1
        res.append((pid, "F"))
    for _, _, pid in e2b:
        if biz_open <= 0:
            break
        biz_open -= 1
        econ_open += 1
        res.append((pid, "B"))
    for _, _, pid in sb:
        if first_open > 0:
            first_open -= 1
            res.append((pid, "F"))
        elif biz_open > 0:
            biz_open -= 1
            res.append((pid, "B"))
