def meter_api_requests(
    policies: dict[str, tuple[int, int, int]],
    requests: list[tuple[int, str, int]],
) -> list[str]:
    buckets = {}
    for t, (cap, rate, cr) in policies.items():
        if cap <= 0 or rate < 0 or cr < 0:
            raise ValueError("invalid policy")
        buckets[t] = [cap, cr, 0, cap, rate]
    prev_ts = None
    out = []
    for ts, t, cost in requests:
        if prev_ts is not None and ts < prev_ts:
            raise ValueError("decreasing ts")
        prev_ts = ts
        if cost <= 0:
            raise ValueError("cost must be positive")
        b = buckets.get(t)
        if b is None:
            out.append("UNKNOWN")
            continue
        tok, cr, last, cap, rate = b
        tok = cap if tok + (ts - last) * rate > cap else tok + (ts - last) * rate
        b[2] = ts
        if tok >= cost:
            b[0] = tok - cost
            out.append("PASS")
        elif tok + cr >= cost:
            b[1] = cr - (cost - tok)
            b[0] = 0
            out.append("BURST")
        else:
            b[0] = tok
            out.append("DROP")
    return out
