#include <algorithm>
#include <string>
#include <tuple>
#include <unordered_map>
#include <vector>

std::vector<std::string> meterGatewayRequests(
    const std::vector<std::tuple<std::string, long long, long long, long long>>& policies,
    const std::vector<std::tuple<long long, std::string, long long>>& requests
) {
    struct Bucket { long long tok, cr, last, cap, rate; };
    std::unordered_map<std::string, Bucket> m;
    for (const auto& [t, cap, rate, cr] : policies) {
        m[t] = {cap, cr, 0, cap, rate};
    }
    std::vector<std::string> out;
    out.reserve(requests.size());
    for (const auto& [ts, t, cost] : requests) {
        auto it = m.find(t);
        if (it == m.end()) {
            out.push_back("UNKNOWN");
            continue;
        }
        Bucket& b = it->second;
        b.tok = std::min(b.cap, b.tok + (ts - b.last) * b.rate);
        b.last = ts;
        if (b.tok >= cost) {
            b.tok -= cost;
            out.push_back("PASS");
        } else if (b.tok + b.cr >= cost) {
            b.cr -= (cost - b.tok);
            b.tok = 0;
            out.push_back("BURST");
        } else {
            out.push_back("DROP");
        }
    }
    return out;
}
