std::vector<std::string> propagateDirty(
    const std::vector<std::string>& nodes,
    const std::vector<std::pair<std::string, std::string>>& edges,
    const std::vector<std::string>& updates
) {
    std::unordered_map<std::string, int> indeg;
    std::unordered_map<std::string, std::vector<std::string>> adj;
    for (const auto& u : nodes) {
        indeg[u] = 0;
        adj[u];
    }
    for (const auto& [u, v] : edges) {
        adj[u].push_back(v);
        indeg[v] += 1;
    }
    std::priority_queue<std::string, std::vector<std::string>, std::greater<std::string>> pq;
    for (const auto& [u, d] : indeg) {
        if (d == 0) pq.push(u);
    }
    std::vector<std::string> topo;
    while (!pq.empty()) {
        std::string u = pq.top();
        pq.pop();
        topo.push_back(u);
        for (const auto& v : adj[u]) {
            if (--indeg[v] == 0) pq.push(v);
        }
    }
    if (topo.size() != indeg.size()) return {"CYCLE"};
    std::unordered_set<std::string> dirty(updates.begin(), updates.end());
    std::vector<std::string> out;
    for (const auto& u : topo) {
        if (!dirty.count(u)) continue;
        out.push_back(u);
        for (const auto& v : adj[u]) dirty.insert(v);
    }
    return out;
}
