std::vector<std::string> processLeaseOps(
    const std::vector<std::tuple<std::string, std::string, std::string, long long, long long>>& ops
) {
    struct Lease { std::string owner; long long fence; long long exp; };
    std::unordered_map<std::string, Lease> m;
    long long fence = 0;
    std::vector<std::string> out;
    out.reserve(ops.size());
    for (const auto& [op, key, owner, ttl, ts] : ops) {
        if (op == "ACQUIRE") {
            auto it = m.find(key);
            if (it == m.end() || ts >= it->second.exp) {
                ++fence;
                m[key] = {owner, fence, ts + ttl};
                out.push_back("OK:" + std::to_string(fence));
            } else {
                out.push_back("BUSY");
            }
        } else if (op == "RENEW") {
            auto it = m.find(key);
            if (it != m.end() && it->second.owner == owner && ts < it->second.exp) {
                it->second.exp = ts + ttl;
                out.push_back("OK:" + std::to_string(it->second.fence));
            } else {
                out.push_back("STALE");
            }
        } else {
            auto it = m.find(key);
            if (it != m.end() && it->second.owner == owner && ts < it->second.exp) {
                out.push_back("WRITE:" + std::to_string(it->second.fence));
            } else {
                out.push_back("DENIED");
            }
        }
    }
    return out;
}
