        if (r == tr && c == tc) return steps;
        if (bat == 0) continue;
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C || grid[nr][nc] == '#') continue;
            int nbat = (grid[nr][nc] == 'C') ? maxBattery : (bat - 1);
            if (nbat > best[nr][nc]) {
                best[nr][nc] = nbat;
                q.emplace(nr, nc, nbat, steps + 1);
            }
        }
    }
    return -1;
}
