#include <algorithm>
#include <deque>
#include <vector>

int minInvoiceBatches(
    const std::vector<long long>& amounts,
    int maxCount,
    long long maxAmount
) {
    int n = (int)amounts.size();
    if (n == 0) return 0;
    if (maxCount <= 0) return -1;
    for (long long a : amounts) {
        if (a > maxAmount) return -1;
    }
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + amounts[i];
    std::vector<int> dp(n + 1, n + 5);
    dp[0] = 0;
    int left = 0;
    for (int i = 1; i <= n; ++i) {
        while (left < i - maxCount || pref[i] - pref[left] > maxAmount) ++left;
        dp[i] = dp[left] + 1;
    }
    return dp[n];
}
