#include <algorithm>
#include <utility>
#include <vector>

long long findEarliestSlot(
    const std::vector<std::pair<long long, long long>>& busy,
    long long workStart,
    long long workEnd,
    long long duration,
    long long step
) {
    if (workStart + duration > workEnd) return -1;
    std::vector<std::pair<long long, long long>> ivs;
    for (const auto& [s, e] : busy) {
        if (s < e) ivs.emplace_back(s, e);
    }
    std::sort(ivs.begin(), ivs.end());
    std::vector<std::pair<long long, long long>> merged;
    for (const auto& [s, e] : ivs) {
        if (merged.empty() || s > merged.back().second) merged.emplace_back(s, e);
        else merged.back().second = std::max(merged.back().second, e);
    }
    long long t = workStart;
    for (const auto& [s, e] : merged) {
        if (e <= t) continue;
        if (t + duration <= s) break;
        long long k = (e - workStart + step - 1) / step;
        t = std::max(t, workStart + k * step);
        if (t + duration > workEnd) return -1;
    }
    return (t + duration <= workEnd) ? t : -1;
}
