#include <string>
#include <tuple>
#include <vector>

std::vector<std::string> runCraneYard(
    std::vector<std::vector<std::string>> stacks,
    const std::vector<std::tuple<std::string, std::string, int>>& ops
) {
    long long moves = 0;
    std::vector<std::string> out;
    for (const auto& [op, arg, dst] : ops) {
        if (op == "MOVE") {
            int src = std::stoi(arg);
            if (!stacks[src].empty()) {
                stacks[dst].push_back(std::move(stacks[src].back()));
                stacks[src].pop_back();
                ++moves;
            }
        } else {
            int found = -1, pos = -1;
            for (int i = 0; i < (int)stacks.size(); ++i) {
                for (int j = 0; j < (int)stacks[i].size(); ++j) {
                    if (stacks[i][j] == arg) { found = i; pos = j; break; }
                }
                if (found != -1) break;
            }
            if (found == -1) {
                out.push_back("MISSING");
            } else {
                while ((int)stacks[found].size() - 1 > pos) {
                    stacks[dst].push_back(std::move(stacks[found].back()));
                    stacks[found].pop_back();
                    ++moves;
                }
                stacks[found].pop_back();
                ++moves;
                out.push_back("FETCHED:" + std::to_string(moves));
            }
        }
    }
    out.push_back("TOTAL:" + std::to_string(moves));
    return out;
}
