static long long evalRange(const std::vector<long long>& leaves, int l, int r) {
    constexpr long long MOD = 1000000007LL;
    if (l == r) return ((leaves[l] % MOD) + MOD) % MOD;
    int mid = (l + r) / 2;
    long long lv = evalRange(leaves, l, mid);
    long long rv = evalRange(leaves, mid + 1, r);
    return (lv * 1315423911LL + rv * 2654435761LL + 1LL) % MOD;
}

std::vector<long long> queryMerkleRanges(
    std::vector<long long> leaves,
    const std::vector<std::tuple<std::string, int, long long>>& ops
) {
    std::vector<long long> out;
    for (const auto& [op, a, b] : ops) {
        if (op == "SET") {
            leaves[a] = b;
        } else {
            out.push_back(evalRange(leaves, a, (int)b));
        }
    }
    return out;
}
