    pq = [u for u, d in indeg.items() if d == 0]
    heapq.heapify(pq)
    topo = []
    while pq:
        u = heapq.heappop(pq)
        topo.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(pq, v)
    if len(topo) != len(nodes):
        print("CYCLE")
        return
    dirty = set(updates)
    out = []
    for u in topo:
        if u in dirty:
            out.append(u)
            for v in adj[u]:
                dirty.add(v)
    if out:
        sys.stdout.write("\n".join(out) + "\n")

