from collections import OrderedDict
import sys

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    cap, n = map(int, lines[0].split())
    lru = OrderedDict()
    used = 0
    out = []
    for line in lines[1:1 + n]:
        p = line.split()
        op, key = p[0], p[1]
        if op == "GET":
            if key in lru:
                lru.move_to_end(key, last=False)
                out.append("HIT")
            else:
                out.append("MISS")
        elif op == "UNPIN":
            if key in lru:
                lru[key][1] = 0
                out.append("OK")
            else:
                out.append("MISS")
        else:
            sz, pin = int(p[2]), int(p[3])
            if sz > cap:
                out.append("SKIP")
                continue
            old_sz = lru[key][0] if key in lru else 0
            base = used - old_sz
            needed = base + sz - cap
            victims = []
            freed = 0
            if needed > 0:
                for k in reversed(lru):
                    if k == key or lru[k][1] == 1:
                        continue
                    victims.append(k)
                    freed += lru[k][0]
                    if freed >= needed:
                        break
            if needed > 0 and freed < needed:
                out.append("SKIP")
                continue
            for v in victims:
                used -= lru.pop(v)[0]
            if key in lru:
                used -= lru[key][0]
                lru[key] = [sz, pin]
                lru.move_to_end(key, last=False)
            else:
                lru[key] = [sz, pin]
                lru.move_to_end(key, last=False)
            used += sz
            out.append("OK")
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))

if __name__ == "__main__":
    main()
