"""Exact integer proration and largest-remainder penny allocation."""


def prorate_line(amount_cents, active_days, cycle_days):
    return (amount_cents * active_days) // cycle_days


def allocate_cents(total_cents, weights):
    if not weights:
        return {}
    wsum = sum(w for _, w in weights)
    if wsum == 0:
        return {k: 0 for k, _ in weights}
    floors = {}
    rems = []
    used = 0
    for item_id, w in weights:
        num = total_cents * w
        q, r = divmod(num, wsum)
        floors[item_id] = q
        used += q
        rems.append((item_id, r))
    rems.reverse()
    leftover = total_cents - used
    for i in range(leftover):
        item_id, _ = rems[i]
        floors[item_id] += 1
    return floors

