"""Mid-cycle seat invoice builder."""

from .prorate import allocate_cents, prorate_line


def build_invoice(cycle_days, changes, rate_per_seat_cents, discount_cents=0):
    # changes: list of (day, item_id, seats) where segment runs [day, next_day) clamped to [1, cycle_days + 1)
    by_item = {}
    for day, item_id, seats in changes:
        by_item.setdefault(item_id, []).append((day, seats))
    raw = {}
    for item_id, evs in by_item.items():
        evs.sort()
        seat_days = 0
        for idx, (d, seats) in enumerate(evs):
            end = evs[idx + 1][0] if idx + 1 < len(evs) else cycle_days + 1
            seat_days += seats * (end - d + 1)
        raw[item_id] = prorate_line(rate_per_seat_cents, seat_days, cycle_days)
    if discount_cents <= 0:
        return raw
    weights = sorted((k, v) for k, v in raw.items() if v > 0)
    disc_split = allocate_cents(min(discount_cents, sum(raw.values())), weights)
    return {k: v - disc_split.get(k, 0) for k, v in raw.items()}

