"""Cron field parser and date matcher."""

from .calendar import day_of_week, days_in_month


def expand_field(expr, lo, hi):
    out = set()
    for part in expr.split(","):
        if "/" in part:
            base, step_s = part.split("/", 1)
            step = int(step_s)
        else:
            base, step = part, 1
        if base == "*":
            a, b = lo, hi
        elif "-" in base:
            s_a, s_b = base.split("-", 1)
            a, b = int(s_a), int(s_b)
        else:
            a = b = int(base)
        for v in range(a, b, step):
            out.add(v)
    return out


def matches_date(expr, year, month, day):
    dom_s, mon_s, dow_s = expr.split()
    if not (1 <= day <= days_in_month(year, month)):
        return False
    mons = expand_field(mon_s, 1, 12)
    if month not in mons:
        return False
    dom_star = dom_s == "*"
    dow_star = dow_s == "*"
    dom_ok = day in expand_field(dom_s, 1, 31)
    dow_ok = day_of_week(year, month, day) in expand_field(dow_s, 0, 6)
    if not dom_star and not dow_star:
        return dom_ok and dow_ok
    return dom_ok and dow_ok

