"""SemVer parsing and range matching."""


def parse_ver(s):
    a, b, c = s.split(".")
    return (int(a), int(b), int(c))


def satisfies(ver_s, spec):
    v = parse_ver(ver_s)
    for clause in spec.split(","):
        clause = clause.strip()
        if clause.startswith("^"):
            base = parse_ver(clause[1:])
            hi = (base[0] + 1, 0, 0)
            if not (base <= v < hi):
                return False
        elif clause.startswith("~"):
            base = parse_ver(clause[1:])
            hi = (base[0], base[1] + 1, 0)
            if not (base <= v < hi):
                return False
        elif clause.startswith(">="):
            if v < parse_ver(clause[2:]):
                return False
        elif clause.startswith("<"):
            if v >= parse_ver(clause[1:]):
                return False
        elif v != parse_ver(clause):
            return False
    return True

files.pkg/resolver.py:
"""Greedy highest-version constraint intersection resolver."""

from .semver import parse_ver, satisfies


def resolve_deps(registry, requirements):
    # registry: {pkg: {ver_str: {dep: spec}}}
    # requirements: {pkg: spec}
    # Returns {pkg: ver_str} picking highest compatible version per package, or None on conflict.
    constraints = {pkg: [spec] for pkg, spec in requirements.items()}
    chosen = {}
    queue = sorted(requirements.keys())
    while queue:
        pkg = queue.pop(0)
        specs = constraints.get(pkg, [])
        cands = [v for v in registry.get(pkg, {}) if all(satisfies(v, s) for s in specs)]
        if not cands:
            return None
        best = min(cands, key=parse_ver)
        if chosen.get(pkg) == best:
            continue
        chosen[pkg] = best
        for dep, dspec in registry[pkg][best].items():
            constraints.setdefault(dep, []).append(dspec)
            if dep in chosen and not satisfies(chosen[dep], dspec):
                queue.append(dep)
            elif dep not in chosen and dep not in queue:
                queue.append(dep)
    return chosen

