"""Segment-aware glob matching (*, ?, **)."""


def _seg_match(pat, text):
    m, n = len(pat), len(text)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for i in range(1, m + 1):
        if pat[i - 1] == "*":
            dp[i][0] = dp[i - 1][0]
        for j in range(1, n + 1):
            if pat[i - 1] == "*":
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            elif pat[i - 1] == "?" or pat[i - 1] == text[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
    return dp[m][n]


def glob_match(pattern, path):
    return _seg_match(pattern.strip("/"), path.strip("/"))

