"""Elevator dispatch travel-cost calculation."""


def dispatch_cost(car_floor, car_dir, car_target, call_floor, call_dir):
    if car_dir == "IDLE":
        return abs(car_floor - call_floor)
    if car_dir == call_dir:
        if car_dir == "UP" and car_floor <= call_floor:
            return call_floor - car_floor
        if car_dir == "DOWN" and car_floor >= call_floor:
            return car_floor - call_floor
    return abs(car_floor - call_floor)

