"""Multi-car elevator dispatcher."""

from .cost import dispatch_cost


class ElevatorBank:
    def __init__(self, floors_list):
        self.cars = [{"id": i, "floor": f, "dir": "IDLE", "target": f} for i, f in enumerate(floors_list)]

    def request(self, call_floor, call_dir):
        best = min(
            self.cars,
            key=lambda c: (dispatch_cost(c["floor"], c["dir"], c["target"], call_floor, call_dir), -c["id"]),
        )
        if best["dir"] == "IDLE":
            if call_floor > best["floor"]:
                best["dir"] = "UP"
            elif call_floor < best["floor"]:
                best["dir"] = "DOWN"
            else:
                best["dir"] = call_dir
            best["target"] = call_floor
        else:
            pass
        return best["id"]

