"""Point-in-time ASOF feature lookup."""

from bisect import bisect_left
from .ttl import is_fresh


def build_index(writes):
    # writes: list of (entity, ts, val)
    by_ent = {}
    for ent, ts, val in writes:
        by_ent.setdefault(ent, []).append((ts, val))
    index = {}
    for ent, items in by_ent.items():
        items.sort(key=lambda x: x[0])
        index[ent] = ([t for t, _ in items], [v for _, v in items])
    return index


def as_of_join(writes, queries, max_age, default=None):
    index = build_index(writes)
    out = []
    for ent, ets in queries:
        pair = index.get(ent)
        if not pair:
            out.append(default)
            continue
        ts_list, vals = pair
        pos = bisect_left(ts_list, ets) - 1
        if pos < 0 or not is_fresh(ts_list[pos], ets, max_age):
            out.append(default)
        else:
            out.append(vals[pos])
    return out

