function buildProratedInvoice(cycleDays, changes, ratePerSeatCents, discountCents = 0) {
  if (!Number.isInteger(cycleDays) || cycleDays <= 0 || ratePerSeatCents < 0 || discountCents < 0) {
    throw new Error("bad invoice params");
  }
  const byTeam = new Map();
  for (const ch of changes) {
    if (ch.seats < 0) throw new Error("negative seats");
    const list = byTeam.get(ch.teamId) ?? [];
    list.push({ day: ch.day, seats: ch.seats });
    byTeam.set(ch.teamId, list);
  }
  const raw = new Map();
  for (const [teamId, evs] of byTeam.entries()) {
    evs.sort((a, b) => a.day - b.day);
    let seatDays = 0;
    for (let i = 0; i < evs.length; i += 1) {
      const start = Math.max(1, evs[i].day);
      const nextDay = i + 1 < evs.length ? evs[i + 1].day : cycleDays + 1;
      const end = Math.min(cycleDays + 1, nextDay);
      if (end > start) seatDays += evs[i].seats * (end - start);
    }
    raw.set(teamId, Math.floor((ratePerSeatCents * seatDays) / cycleDays));
  }
  let subtotal = 0;
  for (const v of raw.values()) subtotal += v;
  const effDisc = Math.min(discountCents, subtotal);
  if (effDisc > 0 && subtotal > 0) {
    const items = Array.from(raw.entries())
      .filter(([, w]) => w > 0)
      .map(([id, w]) => {
        const num = effDisc * w;
        return { id, floor: Math.floor(num / subtotal), rem: num % subtotal };
      });
    let used = 0;
    for (const it of items) used += it.floor;
    items.sort((a, b) => (b.rem !== a.rem ? b.rem - a.rem : a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
    const extra = effDisc - used;
    for (let i = 0; i < items.length; i += 1) {
      const add = i < extra ? 1 : 0;
      raw.set(items[i].id, raw.get(items[i].id) - (items[i].floor + add));
    }
  }
  const out = {};
  for (const id of Array.from(raw.keys()).sort()) out[id] = raw.get(id);
  return out;
}
