function matchCronDates(expr, dates) {
  const isLeap = (y) => y % 400 === 0 || (y % 4 === 0 && y % 100 !== 0);
  const daysInMonth = (y, m) => {
    if ([1, 3, 5, 7, 8, 10, 12].includes(m)) return 31;
    if ([4, 6, 9, 11].includes(m)) return 30;
    return isLeap(y) ? 29 : 28;
  };
  const dayOfWeek = (y, m, d) => {
    const t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
    const yy = y - (m < 3 ? 1 : 0);
    return (yy + Math.floor(yy / 4) - Math.floor(yy / 100) + Math.floor(yy / 400) + t[m - 1] + d) % 7;
  };
  const expand = (field, lo, hi) => {
    const set = new Set();
    for (const part of field.split(",")) {
      const [base, stepStr] = part.includes("/") ? part.split("/") : [part, "1"];
      const step = Number(stepStr);
      if (!Number.isInteger(step) || step <= 0) throw new Error("bad step");
      let a = lo, b = hi;
      if (base !== "*") {
        if (base.includes("-")) {
          const [sa, sb] = base.split("-");
          a = Number(sa); b = Number(sb);
        } else {
          a = Number(base); b = a;
        }
      }
      if (!Number.isInteger(a) || !Number.isInteger(b) || a < lo || b > hi || a > b) {
        throw new Error("out of bounds");
      }
      for (let v = a; v <= b; v += step) set.add(v);
    }
    return set;
  };
  const parts = expr.trim().split(/\s+/);
  if (parts.length !== 3) throw new Error("bad cron");
  const [domF, monF, dowF] = parts;
  const domSet = expand(domF, 1, 31);
  const monSet = expand(monF, 1, 12);
  const dowSet = expand(dowF, 0, 6);
  const bothRestricted = domF !== "*" && dowF !== "*";
  return dates.map(({ year, month, day }) => {
    if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) return false;
    if (!monSet.has(month)) return false;
    const domOk = domSet.has(day);
    const dowOk = dowSet.has(dayOfWeek(year, month, day));
    return bothRestricted ? (domOk || dowOk) : (domOk && dowOk);
  });
}
