function resolveSemverPackages(registry, requirements) {
  const parse = (s) => s.split(".").map(Number);
  const cmp = (a, b) => {
    const pa = parse(a), pb = parse(b);
    for (let i = 0; i < 3; i += 1) {
      if (pa[i] !== pb[i]) return pa[i] - pb[i];
    }
    return 0;
  };
  const satisfies = (vStr, spec) => {
    const [va, vb, vc] = parse(vStr);
    const ge = (x, y) => x[0] !== y[0] ? x[0] > y[0] : x[1] !== y[1] ? x[1] > y[1] : x[2] >= y[2];
    const lt = (x, y) => !ge(x, y);
    for (const raw of spec.split(",")) {
      const c = raw.trim();
      if (c.startsWith("^")) {
        const b = parse(c.slice(1));
        const hi = b[0] > 0 ? [b[0] + 1, 0, 0] : b[1] > 0 ? [0, b[1] + 1, 0] : [0, 0, b[2] + 1];
        if (!ge([va, vb, vc], b) || !lt([va, vb, vc], hi)) return false;
      } else if (c.startsWith("~")) {
        const b = parse(c.slice(1));
        if (!ge([va, vb, vc], b) || !lt([va, vb, vc], [b[0], b[1] + 1, 0])) return false;
      } else if (c.startsWith(">=")) {
        if (!ge([va, vb, vc], parse(c.slice(2)))) return false;
      } else if (c.startsWith("<")) {
        if (!lt([va, vb, vc], parse(c.slice(1)))) return false;
      } else if (cmp(vStr, c) !== 0) {
        return false;
      }
    }
    return true;
  };
  const constraints = new Map();
  const queue = [];
  for (const [pkg, spec] of Object.entries(requirements)) {
    constraints.set(pkg, [spec]);
    queue.push(pkg);
  }
  queue.sort();
  const chosen = {};
  while (queue.length > 0) {
    const pkg = queue.shift();
    const vers = Object.keys(registry[pkg] ?? {});
    const specs = constraints.get(pkg) ?? [];
    const cands = vers.filter((v) => specs.every((s) => satisfies(v, s))).sort((a, b) => cmp(b, a));
    if (cands.length === 0) return null;
    const best = cands[0];
    if (chosen[pkg] === best) continue;
    chosen[pkg] = best;
    for (const [dep, dspec] of Object.entries(registry[pkg][best])) {
      if (!constraints.has(dep)) constraints.set(dep, []);
      constraints.get(dep).push(dspec);
      if ((chosen[dep] && !satisfies(chosen[dep], dspec)) || (!chosen[dep] && !queue.includes(dep))) {
        queue.push(dep);
      }
    }
