function compactLogSegments(segments, maxBytes, minKeepPerDay) {
  if (maxBytes < 0 || minKeepPerDay < 0) throw new Error("bad limits");
  const byDay = new Map();
  let total = 0;
  for (const seg of segments) {
    if (seg.bytes < 0) throw new Error("negative bytes");
    total += seg.bytes;
    const list = byDay.get(seg.day) ?? [];
    list.push(seg);
    byDay.set(seg.day, list);
  }
  const evictable = [];
  for (const list of byDay.values()) {
    list.sort((a, b) => (a.seq !== b.seq ? a.seq - b.seq : a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
    const cut = Math.max(0, list.length - minKeepPerDay);
    for (let i = 0; i < cut; i += 1) evictable.push(list[i]);
  }
  evictable.sort((a, b) =>
    a.day !== b.day ? a.day - b.day : a.seq !== b.seq ? a.seq - b.seq : a.id < b.id ? -1 : a.id > b.id ? 1 : 0
  );
  const dropped = new Set();
  for (const seg of evictable) {
    if (total <= maxBytes) break;
    total -= seg.bytes;
    dropped.add(seg.id);
  }
  const kept = segments
    .filter((s) => !dropped.has(s.id))
    .sort((a, b) => (a.day !== b.day ? a.day - b.day : a.seq !== b.seq ? a.seq - b.seq : a.id < b.id ? -1 : 1))
    .map((s) => s.id);
