function dispatchElevators(initialCars, requests) {
  if (initialCars.length === 0) throw new Error("no cars");
  const cars = initialCars.map((c, idx) => ({
    id: c.id ?? idx,
    floor: c.floor,
    dir: c.dir ?? "IDLE",
    target: c.target ?? c.floor,
  }));
  const costOf = (car, floor, dir) => {
    if (car.dir === "IDLE") return Math.abs(car.floor - floor);
    if (car.dir === dir) {
      if (dir === "UP" && car.floor <= floor) return floor - car.floor;
      if (dir === "DOWN" && car.floor >= floor) return car.floor - floor;
    }
    return Math.abs(car.floor - car.target) + Math.abs(car.target - floor);
  };
  return requests.map((req) => {
    let best = cars[0];
    let bestCost = costOf(best, req.floor, req.dir);
    for (let i = 1; i < cars.length; i += 1) {
      const c = cars[i];
      const cst = costOf(c, req.floor, req.dir);
      if (cst < bestCost || (cst === bestCost && c.id < best.id)) {
        best = c;
        bestCost = cst;
      }
    }
    if (best.dir === "IDLE") {
      best.dir = req.floor > best.floor ? "UP" : req.floor < best.floor ? "DOWN" : req.dir;
      best.target = req.floor;
    } else if (best.dir === "UP") {
      best.target = Math.max(best.target, req.floor);
    } else {
      best.target = Math.min(best.target, req.floor);
    }
    return best.id;
  });
}
