function asOfFeatureJoin(writes, queries, maxAge, fallback = null) {
  if (maxAge < 0) throw new Error("negative maxAge");
  const idx = new Map();
  for (const w of writes) {
    const list = idx.get(w.entity) ?? [];
    list.push({ ts: w.ts, val: w.value });
    idx.set(w.entity, list);
  }
  for (const list of idx.values()) {
    list.sort((a, b) => a.ts - b.ts);
  }
  return queries.map((q) => {
    const list = idx.get(q.entity);
    if (!list || list.length === 0) return fallback;
    let lo = 0, hi = list.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (list[mid].ts <= q.ts) lo = mid + 1;
      else hi = mid;
    }
    const pos = lo - 1;
    if (pos < 0 || q.ts - list[pos].ts > maxAge) return fallback;
    return list[pos].val;
  });
}
