interface TenantPolicy {
  capacity: number;
  refillPerSec: number;
  burstCredit: number;
}
interface ApiRequest {
  ts: number;
  tenant: string;
  cost: number;
}
type Decision = "PASS" | "BURST" | "DROP" | "UNKNOWN";

function evaluateApiGateway(
  policies: Record<string, TenantPolicy>,
  requests: ApiRequest[],
): Decision[] {
  const state = new Map<string, { tok: number; cr: number; last: number; cap: number; rate: number }>();
  for (const [k, p] of Object.entries(policies)) {
    if (p.capacity <= 0 || p.refillPerSec < 0 || p.burstCredit < 0) throw new Error("bad policy");
    state.set(k, { tok: p.capacity, cr: p.burstCredit, last: 0, cap: p.capacity, rate: p.refillPerSec });
  }
  let prevTs = -Infinity;
  const out: Decision[] = [];
  for (const r of requests) {
    if (r.ts < prevTs || r.cost <= 0) throw new Error("bad request");
    prevTs = r.ts;
    const b = state.get(r.tenant);
    if (!b) {
      out.push("UNKNOWN");
      continue;
    }
    b.tok = Math.min(b.cap, b.tok + (r.ts - b.last) * b.rate);
    b.last = r.ts;
    if (b.tok >= r.cost) {
      b.tok -= r.cost;
      out.push("PASS");
    } else if (b.tok + b.cr >= r.cost) {
      b.cr -= r.cost - b.tok;
      b.tok = 0;
      out.push("BURST");
    } else {
      out.push("DROP");
    }
  }
  return out;
}
