function orderDirtyNodes(
  nodes: string[],
  edges: Array<[string, string]>,
  updates: string[],
): string[] {
  const indeg = new Map<string, number>();
  const adj = new Map<string, string[]>();
  for (const u of nodes) {
    if (indeg.has(u)) throw new Error("duplicate node");
    indeg.set(u, 0);
    adj.set(u, []);
  }
  for (const [src, dst] of edges) {
    if (!indeg.has(src) || !indeg.has(dst)) throw new Error("unknown node");
    adj.get(src)!.push(dst);
    indeg.set(dst, indeg.get(dst)! + 1);
  }
  const ready: string[] = [];
  for (const [u, d] of indeg.entries()) {
    if (d === 0) ready.push(u);
  }
  ready.sort();
  const topo: string[] = [];
  while (ready.length > 0) {
    const u = ready.shift()!;
    topo.push(u);
    for (const v of adj.get(u)!) {
      const nd = indeg.get(v)! - 1;
      indeg.set(v, nd);
      if (nd === 0) {
        ready.push(v);
        ready.sort();
      }
    }
  }
  if (topo.length !== nodes.length) throw new Error("cycle");
  const dirty = new Set<string>();
  for (const u of updates) {
    if (!indeg.has(u)) throw new Error("unknown update");
    dirty.add(u);
  }
  const out: string[] = [];
  for (const u of topo) {
    if (!dirty.has(u)) continue;
    out.push(u);
    for (const v of adj.get(u)!) dirty.add(v);
  }
  return out;
}
