type LeaseOp =
  | { op: "ACQUIRE"; key: string; owner: string; ttl: number; ts: number }
  | { op: "RENEW"; key: string; owner: string; ttl: number; ts: number }
  | { op: "RELEASE"; key: string; owner: string; ts: number }
  | { op: "WRITE"; key: string; token: number; ts: number };

function simulateFencedLeases(ops: LeaseOp[]): string[] {
  const leases = new Map<string, { owner: string; fence: number; exp: number }>();
  const highFence = new Map<string, number>();
  let nextFence = 0;
  let prevTs = -Infinity;
  const out: string[] = [];
  for (const item of ops) {
    if (item.ts < prevTs) throw new Error("decreasing ts");
    prevTs = item.ts;
    const cur = leases.get(item.key);
    if (item.op === "ACQUIRE") {
      if (item.ttl <= 0) throw new Error("bad ttl");
      if (!cur || item.ts >= cur.exp) {
        nextFence += 1;
        leases.set(item.key, { owner: item.owner, fence: nextFence, exp: item.ts + item.ttl });
        highFence.set(item.key, nextFence);
        out.push(`OK:${nextFence}`);
      } else {
        out.push("BUSY");
      }
    } else if (item.op === "RENEW") {
      if (item.ttl <= 0) throw new Error("bad ttl");
      if (cur && cur.owner === item.owner && item.ts < cur.exp) {
        cur.exp = item.ts + item.ttl;
        out.push(`OK:${cur.fence}`);
      } else {
        out.push("STALE");
      }
    } else if (item.op === "RELEASE") {
      if (cur && cur.owner === item.owner && item.ts < cur.exp) {
        leases.delete(item.key);
        out.push("RELEASED");
      } else {
        out.push("STALE");
      }
    } else {
      const hf = highFence.get(item.key) ?? 0;
      if (cur && item.ts < cur.exp && item.token === cur.fence && item.token >= hf) {
        out.push("WRITTEN");
      } else {
        out.push("FENCED");
      }
    }
  }
  return out;
}
