      if (pos.has(item.id) || stacks[item.stack].length >= cap) throw new Error("cannot arrive");
      stacks[item.stack].push(item.id);
      pos.set(item.id, item.stack);
    } else {
      const s = pos.get(item.id);
      if (s === undefined) throw new Error("missing container");
      const st = stacks[s];
      while (st[st.length - 1] !== item.id) {
        const mover = st.pop()!;
        let target = -1;
        let minH = Infinity;
        for (let k = 0; k < numStacks; k += 1) {
          if (k === s || stacks[k].length >= cap) continue;
          if (stacks[k].length < minH) {
            minH = stacks[k].length;
            target = k;
          }
        }
        if (target === -1) throw new Error("yard blocked");
        stacks[target].push(mover);
        pos.set(mover, target);
        rehandles += 1;
      }
      st.pop();
      pos.delete(item.id);
    }
  }
  const unretrieved = Array.from(pos.keys()).sort();
  return { rehandles, unretrieved };
}
