interface MinuteSample {
  minute: number;
  total: number;
  errors: number;
}
interface BurnRule {
  windowMinutes: number;
  maxErrorRatio: number;
}

function detectBurnAlerts(samples: MinuteSample[], rules: BurnRule[]): number[] {
  if (samples.length === 0 || rules.length === 0) return [];
  const sorted = [...samples].sort((a, b) => a.minute - b.minute);
  const alerts: number[] = [];
  for (let i = 0; i < sorted.length; i += 1) {
    const curMin = sorted[i].minute;
    let triggered = true;
    for (const rule of rules) {
      const startMin = curMin - rule.windowMinutes + 1;
      let tot = 0;
      let err = 0;
      for (let j = i; j >= 0 && sorted[j].minute >= startMin; j -= 1) {
        tot += sorted[j].total;
        err += sorted[j].errors;
      }
      if (tot === 0 || err / tot <= rule.maxErrorRatio) {
        triggered = false;
        break;
      }
    }
    if (triggered) alerts.push(curMin);
  }
  return alerts;
}
