```typescript
type CacheOp =
  | { op: "PUT"; key: string; bytes: number; pinned: boolean }
  | { op: "GET"; key: string }
  | { op: "UNPIN"; key: string };

function runPinnedBuildCache(capacityBytes: number, ops: CacheOp[]): Array<boolean | string> {
  if (capacityBytes <= 0) throw new Error("bad capacity");
  const meta = new Map<string, { bytes: number; pinned: boolean }>();
  const lru: string[] = []; // front = LRU, back = MRU
  let used = 0;
  const touch = (k: string) => {
    const idx = lru.indexOf(k);
    if (idx !== -1) lru.splice(idx, 1);
    lru.push(k);
  };
  const out: Array<boolean | string> = [];
  for (const item of ops) {
    if (item.op === "GET") {
      if (!meta.has(item.key)) {
        out.push(false);
      } else {
        touch(item.key);
        out.push(true);
      }
    } else if (item.op === "UNPIN") {
      const m = meta.get(item.key);
      if (!m) {
        out.push(false);
      } else {
        m.pinned = false;
        out.push(true);
      }
    } else {
      if (item.bytes < 0) throw new Error("negative bytes");
      if (item.bytes > capacityBytes) {
        out.push("SKIP");
        continue;
      }
      const prev = meta.get(item.key);
      const oldSz = prev ? prev.bytes : 0;
      const needed = used - oldSz + item.bytes - capacityBytes;
      const victims: string[] = [];
      let freed = 0;
      if (needed > 0) {
        for (const k of lru) {
          if (k === item.key || meta.get(k)!.pinned) continue;
          victims.push(k);
          freed += meta.get(k)!.bytes;
          if (freed >= needed) break;
        }
      }
      if (needed > 0 && freed < needed) {
        out.push("SKIP");
        continue;
      }
      for (const v of victims) {
        used -= meta.get(v)!.bytes;
        meta.delete(v);
        const idx = lru.indexOf(v);
        if (idx !== -1) lru.splice(idx, 1);
      }
      meta.set(item.key, { bytes: item.bytes, pinned: item.pinned });
      touch(item.key);
      used = used - oldSz + item.bytes;
      out.push("OK");
    }
  }
  return out;
}
