std::vector<std::string> scheduleRunways(
    int numRunways,
    const std::vector<std::vector<int>>& wakeSep,
    long long maxDelay,
    const std::vector<std::tuple<std::string, long long, int>>& flights) {
    std::vector<bool> used(numRunways, false);
    std::vector<long long> lastT(numRunways, 0);
    std::vector<int> lastC(numRunways, 0);
    std::vector<std::string> out;
    out.reserve(flights.size());
    for (const auto& [fid, reqTs, wcls] : flights) {
        int bestR = -1;
        long long bestT = 0;
        for (int r = 0; r < numRunways; ++r) {
            long long t = used[r] ? std::max(reqTs, lastT[r] + (long long)wakeSep[lastC[r]][wcls]) : reqTs;
            if (bestR == -1 || t < bestT) {
                bestR = r;
                bestT = t;
            }
        }
        if (bestR == -1 || bestT - reqTs > maxDelay) {
            out.push_back(fid + ":DIVERT");
        } else {
            used[bestR] = true;
            lastT[bestR] = bestT;
            lastC[bestR] = wcls;
            out.push_back(fid + ":R" + std::to_string(bestR) + "@" + std::to_string(bestT));
        }
    }
    return out;
}
