std::vector<std::string> routePacketsLpm(
    const std::vector<std::tuple<std::string, int, std::string, std::string>>& routes,
    const std::vector<std::pair<std::string, std::string>>& events) {
    auto parseIp = [](const std::string& s) -> uint32_t {
        uint32_t res = 0;
        size_t pos = 0;
        for (int i = 0; i < 4; ++i) {
            size_t dot = s.find('.', pos);
            uint32_t part = (uint32_t)std::stoul(s.substr(pos, dot == std::string::npos ? std::string::npos : dot - pos));
            res = (res << 8) | part;
            if (dot != std::string::npos) pos = dot + 1;
        }
        return res;
    };
    struct Route {
        uint32_t net;
        uint32_t mask;
        int plen;
        int metric;
        std::string nh;
        std::string iface;
    };
    std::vector<Route> table;
    std::unordered_set<std::string> upIfaces;
    for (const auto& [cidr, metric, nh, iface] : routes) {
        size_t slash = cidr.find('/');
        uint32_t ip = parseIp(cidr.substr(0, slash));
        int plen = std::stoi(cidr.substr(slash + 1));
        uint32_t mask = (plen == 0) ? 0U : (~0U << (32 - plen));
        table.push_back({ip & mask, mask, plen, metric, nh, iface});
        upIfaces.insert(iface);
    }
    std::vector<std::string> out;
    for (const auto& [kind, arg] : events) {
        if (kind == "DOWN") {
            upIfaces.erase(arg);
        } else if (kind == "UP") {
            upIfaces.insert(arg);
        } else {
            uint32_t ip = parseIp(arg);
            int bestIdx = -1;
            for (int i = 0; i < (int)table.size(); ++i) {
                const auto& r = table[i];
                if (!upIfaces.count(r.iface)) continue;
                if ((ip & r.mask) == r.net) {
                    if (bestIdx == -1) {
                        bestIdx = i;
                    } else {
                        const auto& b = table[bestIdx];
                        if (r.plen > b.plen ||
                            (r.plen == b.plen && (r.metric < b.metric || (r.metric == b.metric && r.nh < b.nh)))) {
                            bestIdx = i;
                        }
                    }
                }
            }
            out.push_back(bestIdx == -1 ? "DROP" : table[bestIdx].nh);
        }
    }
    return out;
}
