std::vector<std::string> placeRingReplicas(
    const std::vector<std::tuple<std::string, std::string, std::vector<long long>>>& nodes,
    const std::vector<std::tuple<std::string, std::string, int>>& ops) {
    std::vector<std::pair<long long, std::string>> ring;
    std::unordered_map<std::string, std::string> rackOf;
    std::unordered_set<std::string> up;
    for (const auto& [nid, rid, vns] : nodes) {
        rackOf[nid] = rid;
        up.insert(nid);
        for (long long h : vns) ring.push_back({h, nid});
    }
    std::sort(ring.begin(), ring.end());
    std::vector<std::string> out;
    for (const auto& [op, arg, rf] : ops) {
        if (op == "DOWN") {
            up.erase(arg);
        } else if (op == "UP") {
            up.insert(arg);
        } else {
            long long kh = std::stoll(arg);
            auto it = std::lower_bound(ring.begin(), ring.end(), std::make_pair(kh, std::string("")));
            size_t start = (size_t)(it - ring.begin());
            size_t n = ring.size();
            std::vector<std::string> chosen;
            std::unordered_set<std::string> usedN, usedR;
            for (size_t step = 0; step < n && (int)chosen.size() < rf; ++step) {
                const std::string& nid = ring[(start + step) % n].second;
                if (!up.count(nid) || usedN.count(nid)) continue;
                const std::string& rid = rackOf[nid];
                if (!usedR.count(rid)) {
                    chosen.push_back(nid);
                    usedN.insert(nid);
                    usedR.insert(rid);
                }
            }
            for (size_t step = 0; step < n && (int)chosen.size() < rf; ++step) {
                const std::string& nid = ring[(start + step) % n].second;
                if (!up.count(nid) || usedN.count(nid)) continue;
                chosen.push_back(nid);
                usedN.insert(nid);
            }
            if (chosen.empty()) {
                out.push_back("NONE");
            } else {
                std::string s;
                for (size_t i = 0; i < chosen.size(); ++i) {
                    if (i) s += ",";
                    s += chosen[i];
                }
                out.push_back(s);
            }
        }
    }
    return out;
}
