std::vector<std::string> runDarkPool(
    const std::vector<std::tuple<std::string, std::string, std::string, int, int, int>>& orders) {
    struct Entry {
        int seq;
        std::string oid;
        std::string trader;
        std::string side;
        int rem;
        int price;
    };
    std::vector<Entry> book;
    std::vector<std::string> out;
    int seq = 0;
    for (const auto& [oid, trader, side, qty, minQty, price] : orders) {
        ++seq;
        std::vector<int> cands;
        for (int i = 0; i < (int)book.size(); ++i) {
            if (book[i].rem <= 0 || book[i].side == side || book[i].trader == trader) continue;
            if ((side == "BUY" && book[i].price <= price) || (side == "SELL" && book[i].price >= price)) {
                cands.push_back(i);
            }
        }
        std::sort(cands.begin(), cands.end(), [&](int a, int b) {
            if (book[a].price != book[b].price) {
                return side == "BUY" ? (book[a].price < book[b].price) : (book[a].price > book[b].price);
            }
            return book[a].seq < book[b].seq;
        });
        long long avail = 0;
        for (int idx : cands) avail += book[idx].rem;
        if (avail < minQty) {
            book.push_back({seq, oid, trader, side, qty, price});
            out.push_back(oid + ":REST:" + std::to_string(qty));
            continue;
        }
        int need = qty;
        int filled = 0;
        for (int idx : cands) {
            if (need == 0) break;
            int take = std::min(need, book[idx].rem);
            book[idx].rem -= take;
            need -= take;
            filled += take;
        }
        if (need > 0) book.push_back({seq, oid, trader, side, need, price});
        out.push_back(oid + ":FILL:" + std::to_string(filled) + ":REM:" + std::to_string(need));
    }
    return out;
}
