std::vector<std::string> runSlabAllocator(
    int memSize,
    const std::vector<std::tuple<std::string, std::string, int>>& ops) {
    struct Block {
        int start;
        int len;
        std::string owner; // empty = free
    };
    std::vector<Block> blocks;
    if (memSize > 0) blocks.push_back({0, memSize, ""});
    std::vector<std::string> out;
    for (const auto& [op, bid, sz] : ops) {
        if (op == "MALLOC") {
            int asz = ((sz + 7) / 8) * 8;
            int placed = -1;
            for (size_t i = 0; i < blocks.size(); ++i) {
                if (blocks[i].owner.empty() && blocks[i].len >= asz) {
                    placed = blocks[i].start;
                    if (blocks[i].len == asz) {
                        blocks[i].owner = bid;
                    } else {
                        int remStart = blocks[i].start + asz;
                        int remLen = blocks[i].len - asz;
                        blocks[i].len = asz;
                        blocks[i].owner = bid;
                        blocks.insert(blocks.begin() + (ptrdiff_t)i + 1, {remStart, remLen, ""});
                    }
                    break;
                }
            }
            out.push_back(placed == -1 ? "OOM" : ("@" + std::to_string(placed)));
        } else if (op == "FREE") {
            bool found = false;
            for (auto& b : blocks) {
                if (b.owner == bid) {
                    b.owner.clear();
                    found = true;
                    break;
                }
            }
            if (!found) {
                out.push_back("ERR");
            } else {
                std::vector<Block> merged;
                for (const auto& b : blocks) {
                    if (!merged.empty() && merged.back().owner.empty() && b.owner.empty()) {
                        merged.back().len += b.len;
                    } else {
                        merged.push_back(b);
                    }
                }
                blocks = std::move(merged);
                out.push_back("OK");
            }
        } else {
            int mx = 0;
            for (const auto& b : blocks) {
                if (b.owner.empty()) mx = std::max(mx, b.len);
            }
            out.push_back(std::to_string(mx));
        }
    }
    return out;
}
