std::vector<std::string> evaluateSheetQueries(
    const std::vector<std::pair<std::string, std::string>>& cells,
    const std::vector<std::string>& queries) {
    std::unordered_map<std::string, std::string> raw;
    for (const auto& [k, v] : cells) raw[k] = v;
    std::unordered_map<std::string, int> state; // 1=visiting, 2=done
    std::unordered_map<std::string, std::pair<bool, long long>> numMemo;
    std::unordered_map<std::string, std::string> errMemo;

    auto parseCoord = [](const std::string& s) -> std::pair<int, int> {
        return {s[0] - 'A', std::stoi(s.substr(1))};
    };

    std::function<std::pair<bool, std::string>(const std::string&, long long&)> eval =
        [&](const std::string& k, long long& outVal) -> std::pair<bool, std::string> {
        auto it = raw.find(k);
        if (it == raw.end()) {
            outVal = 0;
            return {true, ""};
        }
        int st = state[k];
        if (st == 1) return {false, "#CYCLE"};
        if (st == 2) {
            if (errMemo.count(k)) return {false, errMemo[k]};
            outVal = numMemo[k].second;
            return {true, ""};
        }
        state[k] = 1;
        const std::string& expr = it->second;
        bool ok = true;
        std::string err;
        long long val = 0;
        if (expr[0] != '=') {
            val = std::stoll(expr);
        } else if (expr.rfind("=SUM(", 0) == 0) {
            size_t colon = expr.find(':');
            auto [c1, r1] = parseCoord(expr.substr(5, colon - 5));
            auto [c2, r2] = parseCoord(expr.substr(colon + 1, expr.size() - colon - 2));
            for (int c = std::min(c1, c2); c <= std::max(c1, c2) && ok; ++c) {
                for (int r = std::min(r1, r2); r <= std::max(r1, r2) && ok; ++r) {
                    std::string nm = std::string(1, (char)('A' + c)) + std::to_string(r);
                    long long sub = 0;
                    auto [sok, serr] = eval(nm, sub);
                    if (!sok) { ok = false; err = serr; }
                    else val += sub;
                }
            }
        } else {
            std::string op = expr.substr(1, 3);
            size_t comma = expr.find(',');
            std::string a = expr.substr(5, comma - 5);
            std::string b = expr.substr(comma + 1, expr.size() - comma - 2);
            long long v1 = 0, v2 = 0;
            auto [ok1, e1] = eval(a, v1);
            if (!ok1) { ok = false; err = e1; }
            else {
                auto [ok2, e2] = eval(b, v2);
                if (!ok2) { ok = false; err = e2; }
                else if (op == "ADD") val = v1 + v2;
                else if (op == "SUB") val = v1 - v2;
                else if (op == "DIV") {
                    if (v2 == 0) { ok = false; err = "#DIV0"; }
                    else val = v1 / v2;
                }
            }
        }
        state[k] = 2;
        if (ok) {
            numMemo[k] = {true, val};
            outVal = val;
            return {true, ""};
        } else {
            errMemo[k] = err;
            return {false, err};
        }
    };

    std::vector<std::string> out;
    for (const auto& q : queries) {
        long long v = 0;
        auto [ok, err] = eval(q, v);
        out.push_back(ok ? std::to_string(v) : err);
    }
    return out;
}
