std::vector<std::string> threeWayLineMerge(
    const std::vector<std::string>& base,
    const std::vector<std::string>& ours,
    const std::vector<std::string>& theirs) {
    auto alignSide = [&](const std::vector<std::string>& side,
                         std::vector<std::vector<std::string>>& ins,
                         std::vector<bool>& kept) {
        int m = (int)base.size(), n = (int)side.size();
        std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));
        for (int i = m - 1; i >= 0; --i) {
            for (int j = n - 1; j >= 0; --j) {
                if (base[i] == side[j]) dp[i][j] = 1 + dp[i + 1][j + 1];
                else dp[i][j] = std::max(dp[i + 1][j], dp[i][j + 1]);
            }
        }
        ins.assign(m + 1, {});
        kept.assign(m, false);
        int i = 0, j = 0, bi = 0, si = 0;
        while (i < m && j < n) {
            if (base[i] == side[j]) {
                for (int p = si; p < j; ++p) ins[bi].push_back(side[p]);
                kept[i] = true;
                bi = i + 1;
                si = j + 1;
                ++i; ++j;
            } else if (dp[i + 1][j] >= dp[i][j + 1]) {
                ++i;
            } else {
                ++j;
            }
        }
        for (int p = si; p < n; ++p) ins[bi].push_back(side[p]);
    };

    std::vector<std::vector<std::string>> oIns, tIns;
    std::vector<bool> oKept, tKept;
    alignSide(ours, oIns, oKept);
    alignSide(theirs, tIns, tKept);

    std::vector<std::string> out;
    for (int k = 0; k <= (int)base.size(); ++k) {
        const auto& oi = oIns[k];
        const auto& ti = tIns[k];
        if (oi == ti) {
            out.insert(out.end(), oi.begin(), oi.end());
        } else if (oi.empty()) {
            out.insert(out.end(), ti.begin(), ti.end());
        } else if (ti.empty()) {
            out.insert(out.end(), oi.begin(), oi.end());
        } else {
            out.push_back("<<<<<<< OURS");
            out.insert(out.end(), oi.begin(), oi.end());
            out.push_back("=======");
            out.insert(out.end(), ti.begin(), ti.end());
            out.push_back(">>>>>>> THEIRS");
        }
        if (k < (int)base.size() && oKept[k] && tKept[k]) {
            out.push_back(base[k]);
        }
    }
    return out;
}
