std::vector<std::string> simulateErTriage(
    int icuBeds,
    int wardBeds,
    const std::vector<std::tuple<std::string, long long, int, long long, bool>>& arrivals) {
    struct Patient {
        int acuity;
        long long arrTs;
        int seq;
        std::string pid;
        long long stay;
        bool needIcu;
    };
    std::vector<Patient> arrs;
    for (int i = 0; i < (int)arrivals.size(); ++i) {
        const auto& [pid, ats, ac, stay, ni] = arrivals[i];
        arrs.push_back({ac, ats, i, pid, stay, ni});
    }
    std::sort(arrs.begin(), arrs.end(), [](const Patient& a, const Patient& b) {
        return std::tie(a.arrTs, a.seq) < std::tie(b.arrTs, b.seq);
    });
    using BusyItem = std::pair<long long, int>; // (freeTs, 0=ICU / 1=WARD)
    std::priority_queue<BusyItem, std::vector<BusyItem>, std::greater<BusyItem>> busy;
    std::vector<Patient> waiting;
    std::vector<std::string> out;
    int icuFree = icuBeds, wardFree = wardBeds;
    size_t ai = 0;
    while (ai < arrs.size() || !busy.empty()) {
        long long nextArr = ai < arrs.size() ? arrs[ai].arrTs : (long long)4e18;
        long long nextFree = !busy.empty() ? busy.top().first : (long long)4e18;
        long long now = std::min(nextArr, nextFree);
        while (!busy.empty() && busy.top().first == now) {
            if (busy.top().second == 0) ++icuFree;
            else ++wardFree;
            busy.pop();
        }
        while (ai < arrs.size() && arrs[ai].arrTs == now) {
            waiting.push_back(arrs[ai++]);
        }
        std::sort(waiting.begin(), waiting.end(), [](const Patient& a, const Patient& b) {
            return std::tie(a.acuity, a.arrTs, a.seq) < std::tie(b.acuity, b.arrTs, b.seq);
        });
        std::vector<Patient> rem;
        for (const auto& p : waiting) {
            if (p.needIcu) {
                if (icuFree > 0) {
                    --icuFree;
                    busy.push({now + p.stay, 0});
                    out.push_back(p.pid + ":ICU@" + std::to_string(now));
                } else {
                    rem.push_back(p);
                }
            } else {
                if (wardFree > 0) {
                    --wardFree;
                    busy.push({now + p.stay, 1});
                    out.push_back(p.pid + ":WARD@" + std::to_string(now));
                } else if (p.acuity <= 2 && icuFree > 0) {
                    --icuFree;
                    busy.push({now + p.stay, 0});
                    out.push_back(p.pid + ":ICU@" + std::to_string(now));
                } else {
                    rem.push_back(p);
                }
            }
        }
        waiting = std::move(rem);
    }
    return out;
}
