def schedule_runways(num_runways, wake_sep, max_delay, flights):
    if num_runways < 0 or max_delay < 0:
        raise ValueError("invalid config")
    last_ts = [None] * num_runways
    last_cls = [0] * num_runways
    out = []
    for fid, req_ts, wcls in flights:
        if wcls < 0 or wcls >= len(wake_sep):
            raise ValueError("bad weight class")
        best_r = -1
        best_t = None
        for r in range(num_runways):
            t = req_ts if last_ts[r] is None else max(req_ts, last_ts[r] + wake_sep[last_cls[r]][wcls])
            if best_t is None or t < best_t:
                best_t = t
                best_r = r
        if best_r == -1 or best_t - req_ts > max_delay:
            out.append(f"{fid}:DIVERT")
        else:
            last_ts[best_r] = best_t
            last_cls[best_r] = wcls
            out.append(f"{fid}:R{best_r}@{best_t}")
    return out
