def route_packets_lpm(routes, events):
    def parse_ip(s):
        parts = s.split(".")
        if len(parts) != 4:
            raise ValueError("bad ip")
        val = 0
        for p in parts:
            n = int(p)
            if not (0 <= n <= 255):
                raise ValueError("bad octet")
            val = (val << 8) | n
        return val

    table = []
    up = set()
    for cidr, metric, nh, iface in routes:
        ip_s, plen_s = cidr.split("/", 1)
        plen = int(plen_s)
        if not (0 <= plen <= 32):
            raise ValueError("bad prefix")
        mask = ((1 << 32) - 1) ^ ((1 << (32 - plen)) - 1) if plen > 0 else 0
        table.append((parse_ip(ip_s) & mask, mask, plen, metric, nh, iface))
        up.add(iface)
    out = []
    for kind, arg in events:
        if kind == "DOWN":
            up.discard(arg)
        elif kind == "UP":
            up.add(arg)
        elif kind == "LOOKUP":
            ip = parse_ip(arg)
            best = None
            for net, mask, plen, metric, nh, iface in table:
                if iface in up and (ip & mask) == net:
                    cand = (-plen, metric, nh)
                    if best is None or cand < best:
                        best = cand
            out.append(best[2] if best else "DROP")
        else:
            raise ValueError("bad event")
    return out
