def run_dark_pool(orders):
    book = []  # [seq, oid, trader, side, rem, price]
    out = []
    for seq, (oid, trader, side, qty, min_qty, price) in enumerate(orders):
        if side not in ("BUY", "SELL") or qty <= 0 or min_qty < 0:
            raise ValueError("bad order")
        cands = []
        for idx, entry in enumerate(book):
            if entry[4] <= 0 or entry[3] == side or entry[2] == trader:
                continue
            if (side == "BUY" and entry[5] <= price) or (side == "SELL" and entry[5] >= price):
                key = (entry[5], entry[0]) if side == "BUY" else (-entry[5], entry[0])
                cands.append((key, idx))
        cands.sort()
        if sum(book[idx][4] for _, idx in cands) < min_qty:
            book.append([seq, oid, trader, side, qty, price])
            out.append((oid, "REST", 0, qty))
            continue
        need = qty
        filled = 0
        for _, idx in cands:
            if need == 0:
                break
            take = min(need, book[idx][4])
            book[idx][4] -= take
            need -= take
            filled += take
        if need > 0:
            book.append([seq, oid, trader, side, need, price])
        out.append((oid, "FILL", filled, need))
    return out
