def run_slab_allocator(mem_size, ops):
    if mem_size < 0:
        raise ValueError("negative mem_size")
    blocks = [[0, mem_size, None]] if mem_size > 0 else []
    used_ids = set()
    out = []
    for op, bid, sz in ops:
        if op == "MALLOC":
            if sz <= 0 or bid in used_ids:
                raise ValueError("bad malloc")
            asz = ((sz + 7) // 8) * 8
            placed = -1
            for i, (st, ln, own) in enumerate(blocks):
                if own is None and ln >= asz:
                    placed = st
                    used_ids.add(bid)
                    if ln == asz:
                        blocks[i][2] = bid
                    else:
                        blocks[i:i + 1] = [[st, asz, bid], [st + asz, ln - asz, None]]
                    break
            out.append("OOM" if placed == -1 else f"@{placed}")
        elif op == "FREE":
            if bid not in used_ids:
                out.append("ERR")
                continue
            used_ids.remove(bid)
            for b in blocks:
                if b[2] == bid:
                    b[2] = None
                    break
            merged = []
            for b in blocks:
                if merged and merged[-1][2] is None and b[2] is None:
                    merged[-1][1] += b[1]
                else:
                    merged.append(b)
            blocks = merged
            out.append("OK")
        elif op == "MAXFREE":
            out.append(str(max((b[1] for b in blocks if b[2] is None), default=0)))
        else:
            raise ValueError("bad op")
    return out
