def three_way_line_merge(base, ours, theirs):
    def align_side(side):
        m, n = len(base), len(side)
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                if base[i] == side[j]:
                    dp[i][j] = 1 + dp[i + 1][j + 1]
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])
        ins = [[] for _ in range(m + 1)]
        kept = [False] * m
        i = j = bi = si = 0
        while i < m and j < n:
            if base[i] == side[j]:
                ins[bi].extend(side[si:j])
                kept[i] = True
                bi = i + 1
                si = j + 1
                i += 1
                j += 1
            elif dp[i + 1][j] >= dp[i][j + 1]:
                i += 1
            else:
                j += 1
        ins[bi].extend(side[si:])
        return ins, kept

    o_ins, o_kept = align_side(ours)
    t_ins, t_kept = align_side(theirs)
    out = []
    for k in range(len(base) + 1):
        oi, ti = o_ins[k], t_ins[k]
        if oi == ti or not ti:
            out.extend(oi)
        elif not oi:
            out.extend(ti)
        else:
            out.append("<<<<<<< OURS")
            out.extend(oi)
            out.append("=======")
            out.extend(ti)
            out.append(">>>>>>> THEIRS")
        if k < len(base) and o_kept[k] and t_kept[k]:
            out.append(base[k])
    return out
