def compute_tiered_taxes(brackets, surcharge_threshold, surcharge_bps, incomes):
    if surcharge_threshold < 0 or surcharge_bps < 0:
        raise ValueError("bad surcharge")
    prev_cap = 0
    for idx, (cap, bps) in enumerate(brackets):
        if bps < 0:
            raise ValueError("negative bps")
        if cap is None:
            if idx != len(brackets) - 1:
                raise ValueError("open bracket must be last")
        elif cap <= prev_cap:
            raise ValueError("non-increasing bracket cap")
        else:
            prev_cap = cap
    out = []
    for inc in incomes:
        if inc < 0:
            raise ValueError("negative income")
        lo = 0
        acc = 0
        for cap, bps in brackets:
            hi = inc if cap is None else min(inc, cap)
            if hi > lo:
                acc += (hi - lo) * bps
                lo = hi
        base_tax = acc // 10000
        sur = (max(0, inc - surcharge_threshold) * surcharge_bps) // 10000
        out.append(base_tax + sur)
    return out
