"""IPv4 CIDR parsing and prefix matching."""


def ip_to_int(ip_str):
    a, b, c, d = (int(p) for p in ip_str.split("."))
    return (a << 24) | (b << 16) | (c << 8) | d


def parse_cidr(cidr_str):
    ip_s, plen_s = cidr_str.split("/", 1)
    plen = int(plen_s)
    mask = ((1 << 32) - 1) << (32 - plen)
    return (ip_to_int(ip_s) & mask, mask, plen)

