        ip = ip_to_int(ip_str)
        best = None
        for net, mask, plen, metric, nh, iface in self.routes:
            if iface in self.up and (ip & mask) == net:
                cand = (-plen, nh, metric)
                if best is None or cand < best:
                    best = cand
