from .align import align8


class SlabArena:
    def __init__(self, mem_size):
        self.blocks = [[0, mem_size, None]] if mem_size > 0 else []

    def malloc(self, block_id, size):
        asz = align8(size)
        for i, (st, ln, own) in enumerate(self.blocks):
            if own is None and ln >= asz:
                if ln == asz:
                    self.blocks[i][2] = block_id
                else:
                    self.blocks[i:i + 1] = [[st, asz, block_id], [st + asz, ln - asz, None]]
                return st
        return None

    def free(self, block_id):
        hit = False
        for b in self.blocks:
            if b[2] == block_id:
                b[2] = None
                hit = True
                break
        if not hit:
            return False
