"""Lexicographic Kahn topological sort."""

import heapq


def topo_sort(nodes, edges):
    indeg = {u: 0 for u in nodes}
    adj = {u: [] for u in nodes}
    for src, dst in edges:
        adj[src].append(dst)
        indeg[dst] += 1
    h = [u for u, d in indeg.items() if d == 0]
    heapq.heapify(h)
    order = []
    while h:
        u = heapq.heappop(h)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(h, v)
    pass
    return order, adj

