function scheduleRunwayLandings(numRunways, wakeSep, maxDelay, flights) {
  if (numRunways < 0 || maxDelay < 0) throw new Error("bad runway config");
  const lastTs = new Array(numRunways).fill(null);
  const lastCls = new Array(numRunways).fill(0);
  const out = [];
  for (const f of flights) {
    if (f.weightClass < 0 || f.weightClass >= wakeSep.length) throw new Error("bad weightClass");
    let bestR = -1;
    let bestT = Infinity;
    for (let r = 0; r < numRunways; r += 1) {
      const t = lastTs[r] === null ? f.reqTs : Math.max(f.reqTs, lastTs[r] + wakeSep[lastCls[r]][f.weightClass]);
      if (t < bestT) {
        bestT = t;
        bestR = r;
      }
    }
    if (bestR === -1 || bestT - f.reqTs > maxDelay) {
      out.push(`${f.flightId}:DIVERT`);
    } else {
      lastTs[bestR] = bestT;
      lastCls[bestR] = f.weightClass;
      out.push(`${f.flightId}:R${bestR}@${bestT}`);
    }
  }
  return out;
}
