function placeConsistentReplicas(nodes, ops) {
  const ring = [];
  const rackOf = new Map();
  const up = new Set();
  for (const n of nodes) {
    if (rackOf.has(n.nodeId)) throw new Error("duplicate node");
    rackOf.set(n.nodeId, n.rackId);
    up.add(n.nodeId);
    for (const tok of n.tokens) ring.push([tok, n.nodeId]);
  }
  ring.sort((a, b) => (a[0] !== b[0] ? a[0] - b[0] : a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));
  const out = [];
  for (const op of ops) {
    if (op.op === "DOWN") up.delete(op.nodeId);
    else if (op.op === "UP") up.add(op.nodeId);
    else if (op.op === "PLACE") {
      if (op.rf < 0) throw new Error("bad rf");
      if (ring.length === 0 || op.rf === 0) {
        out.push([]);
        continue;
      }
      let lo = 0, hi = ring.length;
      while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (ring[mid][0] < op.keyHash) lo = mid + 1;
        else hi = mid;
