      const start = lo % ring.length;
      const chosen = [];
      const usedN = new Set();
      const usedR = new Set();
      for (let step = 0; step < ring.length && chosen.length < op.rf; step += 1) {
        const nid = ring[(start + step) % ring.length][1];
        const rid = rackOf.get(nid);
        if (up.has(nid) && !usedN.has(nid) && !usedR.has(rid)) {
          chosen.push(nid);
          usedN.add(nid);
          usedR.add(rid);
        }
      }
      for (let step = 0; step < ring.length && chosen.length < op.rf; step += 1) {
        const nid = ring[(start + step) % ring.length][1];
        if (up.has(nid) && !usedN.has(nid)) {
          chosen.push(nid);
          usedN.add(nid);
        }
      }
      out.push(chosen);
    } else {
      throw new Error("unknown op");
    }
  }
  return out;
}
