function simulateSlabAllocator(memSize, ops) {
  if (memSize < 0) throw new Error("negative memSize");
  let blocks = memSize > 0 ? [{ start: 0, len: memSize, owner: null }] : [];
  const active = new Set();
  const out = [];
  for (const op of ops) {
    if (op.op === "MALLOC") {
      if (op.size <= 0 || active.has(op.blockId)) throw new Error("bad malloc");
      const asz = Math.ceil(op.size / 8) * 8;
      let placed = -1;
      for (let i = 0; i < blocks.length; i += 1) {
        const b = blocks[i];
        if (b.owner === null && b.len >= asz) {
          placed = b.start;
          active.add(op.blockId);
          if (b.len === asz) {
            b.owner = op.blockId;
          } else {
            blocks.splice(i, 1, { start: b.start, len: asz, owner: op.blockId }, { start: b.start + asz, len: b.len - asz, owner: null });
          }
          break;
        }
      }
      out.push(placed === -1 ? "OOM" : `@${placed}`);
    } else if (op.op === "FREE") {
      if (!active.has(op.blockId)) {
        out.push("ERR");
        continue;
      }
      active.delete(op.blockId);
      for (const b of blocks) {
        if (b.owner === op.blockId) {
          b.owner = null;
          break;
        }
      }
      const merged = [];
      for (const b of blocks) {
        if (merged.length > 0 && merged[merged.length - 1].owner === null && b.owner === null) {
          merged[merged.length - 1].len += b.len;
        } else {
          merged.push(b);
        }
      }
      blocks = merged;
      out.push("OK");
    } else if (op.op === "MAXFREE") {
      let mx = 0;
      for (const b of blocks) {
        if (b.owner === null && b.len > mx) mx = b.len;
      }
      out.push(String(mx));
    } else {
      throw new Error("unknown op");
    }
  }
  return out;
}
