function simulateErAdmissions(icuBeds, wardBeds, arrivals) {
  if (icuBeds < 0 || wardBeds < 0) throw new Error("bad bed counts");
  const arrs = arrivals.map((p, seq) => {
    if (p.stayLen <= 0 || p.acuity < 1 || p.acuity > 5) throw new Error("bad patient");
    return { ...p, seq };
  });
  arrs.sort((a, b) => (a.arrivalTs !== b.arrivalTs ? a.arrivalTs - b.arrivalTs : a.seq - b.seq));
  let icuFree = icuBeds;
  let wardFree = wardBeds;
  const busy = []; // { freeTs, bed }
  let waiting = [];
  const out = [];
  let ai = 0;
  while (ai < arrs.length || busy.length > 0) {
    const nextArr = ai < arrs.length ? arrs[ai].arrivalTs : Infinity;
    let nextFree = Infinity;
    for (const b of busy) if (b.freeTs < nextFree) nextFree = b.freeTs;
    const now = Math.min(nextArr, nextFree);
    for (let i = busy.length - 1; i >= 0; i -= 1) {
      if (busy[i].freeTs === now) {
        if (busy[i].bed === "ICU") icuFree += 1;
        else wardFree += 1;
        busy.splice(i, 1);
      }
    }
    while (ai < arrs.length && arrs[ai].arrivalTs === now) {
      waiting.push(arrs[ai]);
      ai += 1;
    }
    waiting.sort((a, b) =>
      a.acuity !== b.acuity ? a.acuity - b.acuity : a.arrivalTs !== b.arrivalTs ? a.arrivalTs - b.arrivalTs : a.seq - b.seq
    );
    const rem = [];
    for (const p of waiting) {
      if (p.needIcu) {
        if (icuFree > 0) {
          icuFree -= 1;
          busy.push({ freeTs: now + p.stayLen, bed: "ICU" });
          out.push(`${p.patientId}:ICU@${now}`);
        } else {
          rem.push(p);
        }
      } else if (wardFree > 0) {
        wardFree -= 1;
        busy.push({ freeTs: now + p.stayLen, bed: "WARD" });
        out.push(`${p.patientId}:WARD@${now}`);
      } else if (p.acuity <= 2 && icuFree > 0) {
        icuFree -= 1;
        busy.push({ freeTs: now + p.stayLen, bed: "ICU" });
        out.push(`${p.patientId}:ICU@${now}`);
      } else {
        rem.push(p);
      }
    }
    waiting = rem;
  }
  return out;
}
