function computeTieredTaxes(brackets, surchargeThreshold, surchargeBps, incomes) {
  if (surchargeThreshold < 0 || surchargeBps < 0) throw new Error("bad surcharge");
  let prevCap = 0;
  for (let i = 0; i < brackets.length; i += 1) {
    const { cap, bps } = brackets[i];
    if (bps < 0) throw new Error("negative bps");
    if (cap === null) {
      if (i !== brackets.length - 1) throw new Error("open bracket must be last");
    } else if (cap <= prevCap) {
      throw new Error("non-increasing cap");
    } else {
      prevCap = cap;
    }
  }
  return incomes.map((inc) => {
    if (inc < 0) throw new Error("negative income");
    let lo = 0;
    let acc = 0;
    for (const { cap, bps } of brackets) {
      const hi = cap === null ? inc : Math.min(inc, cap);
      if (hi > lo) {
        acc += (hi - lo) * bps;
        lo = hi;
      }
    }
    const baseTax = Math.floor(acc / 10000);
    const sur = Math.floor((Math.max(0, inc - surchargeThreshold) * surchargeBps) / 10000);
    return baseTax + sur;
  });
}
