  reqTs: number;
  weightClass: number;
}

function scheduleRunwayArrivals(
  numRunways: number,
  wakeSep: number[][],
  maxDelay: number,
  flights: FlightReq[],
): string[] {
  if (numRunways < 0 || maxDelay < 0) throw new Error("bad config");
  const lastTs: Array<number | null> = new Array(numRunways).fill(null);
  const lastCls: number[] = new Array(numRunways).fill(0);
  const out: string[] = [];
  for (const f of flights) {
    if (f.weightClass < 0 || f.weightClass >= wakeSep.length) throw new Error("bad weightClass");
    let bestR = -1;
    let bestT = Infinity;
    for (let r = 0; r < numRunways; r += 1) {
      const prevT = lastTs[r];
      const t = prevT === null ? f.reqTs : Math.max(f.reqTs, prevT + wakeSep[lastCls[r]][f.weightClass]);
      if (t < bestT) {
        bestT = t;
        bestR = r;
      }
    }
    if (bestR === -1 || bestT - f.reqTs > maxDelay) {
      out.push(`${f.flightId}:DIVERT`);
    } else {
      lastTs[bestR] = bestT;
      lastCls[bestR] = f.weightClass;
      out.push(`${f.flightId}:R${bestR}@${bestT}`);
    }
  }
  return out;
}
