interface CidrRoute {
  cidr: string;
  metric: number;
  nextHop: string;
  iface: string;
}
type NetEvent = { op: "DOWN" | "UP" | "LOOKUP"; arg: string };

function lookupCidrRoutes(routes: CidrRoute[], events: NetEvent[]): string[] {
  const parseIp = (s: string): number => {
    const parts = s.split(".");
    if (parts.length !== 4) throw new Error("bad ip");
    let v = 0;
    for (const p of parts) {
      const n = Number(p);
      if (!Number.isInteger(n) || n < 0 || n > 255) throw new Error("bad octet");
      v = ((v << 8) | n) >>> 0;
    }
    return v;
  };
  const table = routes.map((r) => {
    const [ipS, plenS] = r.cidr.split("/");
    const plen = Number(plenS);
    if (!Number.isInteger(plen) || plen < 0 || plen > 32) throw new Error("bad prefix");
    const mask = plen === 0 ? 0 : ((0xffffffff << (32 - plen)) >>> 0);
    return { net: (parseIp(ipS) & mask) >>> 0, mask, plen, metric: r.metric, nh: r.nextHop, iface: r.iface };
  });
  const up = new Set<string>(routes.map((r) => r.iface));
  const out: string[] = [];
  for (const ev of events) {
    if (ev.op === "DOWN") up.delete(ev.arg);
    else if (ev.op === "UP") up.add(ev.arg);
    else {
      const ip = parseIp(ev.arg);
      let best: (typeof table)[number] | null = null;
      for (const r of table) {
        if (!up.has(r.iface)) continue;
        if (((ip & r.mask) >>> 0) === r.net) {
          if (
            !best ||
            r.plen > best.plen ||
            (r.plen === best.plen && (r.metric < best.metric || (r.metric === best.metric && r.nh < best.nh)))
          ) {
            best = r;
          }
        }
      }
      out.push(best ? best.nh : "DROP");
    }
  }
  return out;
}
