interface RingNodeSpec {
  nodeId: string;
  rackId: string;
  tokens: number[];
}
type RingOp =
  | { op: "DOWN" | "UP"; nodeId: string }
  | { op: "PLACE"; keyHash: number; rf: number };

function allocateRackReplicas(nodes: RingNodeSpec[], ops: RingOp[]): string[][] {
  const ring: Array<[number, string]> = [];
  const rackOf = new Map<string, string>();
  const up = new Set<string>();
  for (const n of nodes) {
    if (rackOf.has(n.nodeId)) throw new Error("duplicate node");
    rackOf.set(n.nodeId, n.rackId);
    up.add(n.nodeId);
    for (const t of n.tokens) ring.push([t, n.nodeId]);
  }
  ring.sort((a, b) => (a[0] !== b[0] ? a[0] - b[0] : a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));
  const out: string[][] = [];
  for (const item of ops) {
    if (item.op === "DOWN") up.delete(item.nodeId);
    else if (item.op === "UP") up.add(item.nodeId);
    else {
      if (item.rf < 0) throw new Error("negative rf");
      if (ring.length === 0 || item.rf === 0) {
        out.push([]);
        continue;
      }
      let lo = 0, hi = ring.length;
      while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (ring[mid][0] < item.keyHash) lo = mid + 1;
        else hi = mid;
      }
      const start = lo % ring.length;
      const chosen: string[] = [];
      const usedN = new Set<string>();
      const usedR = new Set<string>();
      for (let step = 0; step < ring.length && chosen.length < item.rf; step += 1) {
        const nid = ring[(start + step) % ring.length][1];
        const rid = rackOf.get(nid)!;
        if (up.has(nid) && !usedN.has(nid) && !usedR.has(rid)) {
          chosen.push(nid);
          usedN.add(nid);
          usedR.add(rid);
        }
      }
      for (let step = 0; step < ring.length && chosen.length < item.rf; step += 1) {
        const nid = ring[(start + step) % ring.length][1];
        if (up.has(nid) && !usedN.has(nid)) {
          chosen.push(nid);
          usedN.add(nid);
        }
      }
      out.push(chosen);
    }
  }
  return out;
}
