```typescript
interface DarkOrder {
  orderId: string;
  trader: string;
  side: "BUY" | "SELL";
  qty: number;
  minQty: number;
  limitPrice: number;
}
interface DarkExec {
  orderId: string;
  action: "FILL" | "REST";
  filled: number;
  remaining: number;
}

function executeDarkPool(orders: DarkOrder[]): DarkExec[] {
  const book: Array<{ seq: number; oid: string; trader: string; side: "BUY" | "SELL"; rem: number; price: number }> = [];
  const out: DarkExec[] = [];
  for (let seq = 0; seq < orders.length; seq += 1) {
    const o = orders[seq];
    if (o.qty <= 0 || o.minQty < 0) throw new Error("bad order");
    const cands: number[] = [];
    for (let i = 0; i < book.length; i += 1) {
      const b = book[i];
      if (b.rem <= 0 || b.side === o.side || b.trader === o.trader) continue;
      if ((o.side === "BUY" && b.price <= o.limitPrice) || (o.side === "SELL" && b.price >= o.limitPrice)) {
        cands.push(i);
      }
    }
    cands.sort((ia, ib) => {
      const a = book[ia], b = book[ib];
      if (a.price !== b.price) return o.side === "BUY" ? a.price - b.price : b.price - a.price;
      return a.seq - b.seq;
    });
    let avail = 0;
    for (const i of cands) avail += book[i].rem;
    if (avail < o.minQty) {
      book.push({ seq, oid: o.orderId, trader: o.trader, side: o.side, rem: o.qty, price: o.limitPrice });
      out.push({ orderId: o.orderId, action: "REST", filled: 0, remaining: o.qty });
      continue;
    }
    let need = o.qty;
    let filled = 0;
    for (const i of cands) {
      if (need === 0) break;
      const take = Math.min(need, book[i].rem);
      book[i].rem -= take;
      need -= take;
      filled += take;
    }
    if (need > 0) {
      book.push({ seq, oid: o.orderId, trader: o.trader, side: o.side, rem: need, price: o.limitPrice });
    }
    out.push({ orderId: o.orderId, action: "FILL", filled, remaining: need });
  }
  return out;
}
