function mergeThreeWayLines(base: string[], ours: string[], theirs: string[]): string[] {
  const align = (side: string[]) => {
    const m = base.length, n = side.length;
    const dp: number[][] = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
    for (let i = m - 1; i >= 0; i -= 1) {
      for (let j = n - 1; j >= 0; j -= 1) {
        dp[i][j] = base[i] === side[j] ? 1 + dp[i + 1][j + 1] : Math.max(dp[i + 1][j], dp[i][j + 1]);
      }
    }
    const ins: string[][] = Array.from({ length: m + 1 }, () => []);
    const kept: boolean[] = new Array(m).fill(false);
    let i = 0, j = 0, bi = 0, si = 0;
    while (i < m && j < n) {
      if (base[i] === side[j]) {
        for (let p = si; p < j; p += 1) ins[bi].push(side[p]);
        kept[i] = true;
        bi = i + 1;
        si = j + 1;
        i += 1;
        j += 1;
      } else if (dp[i + 1][j] >= dp[i][j + 1]) {
        i += 1;
      } else {
        j += 1;
      }
    }
    for (let p = si; p < n; p += 1) ins[bi].push(side[p]);
    return { ins, kept };
  };
  const o = align(ours);
  const t = align(theirs);
  const out: string[] = [];
  const sameArr = (a: string[], b: string[]) => a.length === b.length && a.every((v, idx) => v === b[idx]);
  for (let k = 0; k <= base.length; k += 1) {
    const oi = o.ins[k], ti = t.ins[k];
    if (sameArr(oi, ti) || ti.length === 0) out.push(...oi);
    else if (oi.length === 0) out.push(...ti);
    else out.push("<<<<<<< OURS", ...oi, "=======", ...ti, ">>>>>>> THEIRS");
    if (k < base.length && o.kept[k] && t.kept[k]) out.push(base[k]);
  }
  return out;
}
