function runLeaseManager(ops) {
  let prevTs = -Infinity;
  let nextToken = 1;
  const leases = new Map();
  const highestFence = new Map();
  const store = new Map();
  const out = [];

  for (const op of ops) {
    if (typeof op.ts !== "number" || op.ts < prevTs) {
      throw new Error("non-monotonic timestamp");
    }
    prevTs = op.ts;
    if (op.op === "ACQUIRE") {
      if (op.ttl <= 0) throw new Error("bad ttl");
      const cur = leases.get(op.key);
      if (cur && cur.expiresAt > op.ts) {
        out.push("BUSY");
      } else {
        const tok = nextToken++;
        leases.set(op.key, { owner: op.owner, token: tok, expiresAt: op.ts + op.ttl });
        out.push(`GRANT:${tok}`);
      }
    } else if (op.op === "RENEW") {
      if (op.ttl <= 0) throw new Error("bad ttl");
      const cur = leases.get(op.key);
      if (cur && cur.expiresAt > op.ts && cur.owner === op.owner && cur.token === op.token) {
        cur.expiresAt = op.ts + op.ttl;
        out.push("RENEWED");
      } else {
        out.push("STALE");
      }
    } else if (op.op === "RELEASE") {
      const cur = leases.get(op.key);
      if (cur && cur.expiresAt > op.ts && cur.owner === op.owner && cur.token === op.token) {
        leases.delete(op.key);
        out.push("RELEASED");
      } else {
        out.push("STALE");
      }
    } else if (op.op === "WRITE") {
      const high = highestFence.get(op.key) ?? 0;
      if (op.token < high || op.token <= 0) {
        out.push("FENCED");
      } else {
        highestFence.set(op.key, op.token);
        store.set(op.key, op.value);
        out.push(`OK:${op.value}`);
      }
    } else if (op.op === "INSPECT") {
      const cur = leases.get(op.key);
      if (!cur || cur.expiresAt <= op.ts) {
        out.push(`FREE:${store.get(op.key) ?? ""}`);
      } else {
        out.push(`${cur.owner}@${cur.token}:${cur.expiresAt}`);
      }
    } else {
      throw new Error("unknown op");
    }
  }
  return out;
}
