function processMultipartUpload(totalSize, partSize, events) {
  if (totalSize < 0 || partSize <= 0) throw new Error("bad upload config");
  const parts = new Map();
  const out = [];
  for (const ev of events) {
    if (ev.op === "UPLOAD") {
      if (
        !Number.isInteger(ev.partNum) ||
        ev.partNum < 1 ||
        ev.offset < 0 ||
        ev.len <= 0 ||
        ev.offset + ev.len > totalSize ||
        !ev.etag
      ) {
        throw new Error("bad upload part");
      }
      parts.set(ev.partNum, { offset: ev.offset, len: ev.len, etag: ev.etag });
      out.push(`PART:${ev.partNum}:${ev.len}`);
    } else if (ev.op === "ABORT") {
      out.push(parts.delete(ev.partNum) ? "ABORTED" : "MISSING");
    } else if (ev.op === "COMPLETE") {
      const m = ev.manifest;
      let err = null;
      let prevNum = 0;
      const intervals = [];
      for (let i = 0; i < m.length; i += 1) {
        const entry = m[i];
        if (entry.partNum <= prevNum) { err = "ERR:ORDER"; break; }
        prevNum = entry.partNum;
        const p = parts.get(entry.partNum);
        if (!p || p.etag !== entry.etag) { err = "ERR:ETAG"; break; }
        const isLast = i === m.length - 1;
        if ((!isLast && p.len !== partSize) || (isLast && p.len > partSize)) {
          err = "ERR:SIZE";
          break;
        }
        intervals.push([p.offset, p.offset + p.len]);
      }
      if (!err) {
        intervals.sort((a, b) => a[0] - b[0]);
        let cursor = 0;
        for (const [s, e] of intervals) {
          if (s !== cursor) { err = "ERR:COVERAGE"; break; }
          cursor = e;
        }
        if (!err && cursor !== totalSize) err = "ERR:COVERAGE";
      }
      out.push(err ?? `COMMIT:${m.length}:${totalSize}`);
    } else {
      throw new Error("unknown op");
    }
  }
  return out;
}
