    while (i < tok.length) {
      if (tok[i] === "#" || tok[i] === ".") {
        const kind = tok[i++];
        const start = i;
        while (i < tok.length && tok[i] !== "#" && tok[i] !== ".") i += 1;
        const name = tok.slice(start, i);
        if (kind === "#") id = name;
        else classes.push(name);
      } else {
        const start = i;
        while (i < tok.length && tok[i] !== "#" && tok[i] !== ".") i += 1;
        tag = tok.slice(start, i);
      }
    }
    return { tag, id, classes };
  };

  const matchCompound = (comp, node) => {
    if (comp.tag && comp.tag !== "*" && comp.tag !== node.tag) return false;
    if (comp.id && comp.id !== node.id) return false;
    for (const c of comp.classes) {
      if (!node.classes.includes(c)) return false;
    }
    return true;
  };

  const parseSelector = (sel) => {
    const tokens = sel.trim().replace(/\s*>\s*/g, " > ").split(/\s+/);
    const parts = [];
    let spec = [0, 0, 0];
    let nextComb = null;
    for (const tk of tokens) {
      if (tk === ">") {
        nextComb = ">";
      } else {
        const comp = parseCompound(tk);
        if (comp.id) spec[0] += 1;
        spec[1] += comp.classes.length;
        if (comp.tag && comp.tag !== "*") spec[2] += 1;
        parts.push({ comb: nextComb, comp });
        nextComb = " ";
