    if (ptr === "") return [];
    if (!ptr.startsWith("/")) throw new Error("bad pointer");
    return ptr.slice(1).split("/").map((s) => s.replace(/~1/g, "/").replace(/~0/g, "~"));
  };
  const resolveParent = (root, segs) => {
    let cur = root;
    for (let i = 0; i < segs.length - 1; i += 1) {
      const k = segs[i];
