        if (!/^(0|[1-9]\d*)$/.test(k) || Number(k) >= cur.length) throw new Error("bad index");
        cur = cur[Number(k)];
      } else if (cur && typeof cur === "object" && Object.prototype.hasOwnProperty.call(cur, k)) {
        cur = cur[k];
      } else {
        throw new Error("missing parent");
      }
    }
    return [cur, segs[segs.length - 1]];
  };
  const getVal = (root, ptr) => {
    const segs = parsePtr(ptr);
    let cur = root;
    for (const k of segs) {
      if (Array.isArray(cur)) {
        if (!/^(0|[1-9]\d*)$/.test(k) || Number(k) >= cur.length) throw new Error("bad get index");
        cur = cur[Number(k)];
      } else if (cur && typeof cur === "object" && Object.prototype.hasOwnProperty.call(cur, k)) {
        cur = cur[k];
      } else {
        throw new Error("missing path");
      }
    }
    return cur;
  };
  const addAt = (root, ptr, val) => {
    const segs = parsePtr(ptr);
    if (segs.length === 0) return clone(val);
    const [parent, key] = resolveParent(root, segs);
    if (Array.isArray(parent)) {
      if (key === "-") parent.push(clone(val));
      else {
        if (!/^(0|[1-9]\d*)$/.test(key) || Number(key) > parent.length) throw new Error("bad add idx");
        parent.splice(Number(key), 0, clone(val));
