function billSubscriptions(periodStart, periodEnd, plans, taxBps, events) {
  if (periodEnd <= periodStart || taxBps < 0) throw new Error("bad billing period");
  const periodLen = periodEnd - periodStart;
  let activePlan = null;
  let cursor = periodStart;
  let subtotal = 0;
  let credit = 0;

  const sorted = [...events].sort((a, b) => a.ts - b.ts);
  const chargeSlice = (until) => {
    const hi = Math.min(until, periodEnd);
    if (activePlan !== null && hi > cursor) {
      const rate = plans[activePlan];
      if (rate === undefined || rate < 0) throw new Error("unknown plan");
      subtotal += Math.floor(((hi - cursor) * rate) / periodLen);
    }
    if (hi > cursor) cursor = hi;
  };

  for (const ev of sorted) {
    if (ev.ts < periodStart || ev.ts > periodEnd) throw new Error("event out of period");
    if (ev.type === "CREDIT") {
      if (ev.amount < 0) throw new Error("negative credit");
      credit += ev.amount;
    } else if (ev.type === "START") {
      chargeSlice(ev.ts);
      if (!(ev.planId in plans)) throw new Error("missing plan");
      activePlan = ev.planId;
    } else if (ev.type === "CHANGE") {
      chargeSlice(ev.ts);
      if (activePlan === null) throw new Error("change without active plan");
      if (!(ev.planId in plans)) throw new Error("missing plan");
      activePlan = ev.planId;
    } else if (ev.type === "CANCEL") {
      chargeSlice(ev.ts);
      activePlan = null;
    } else {
      throw new Error("unknown billing event");
    }
  }
  chargeSlice(periodEnd);

  const creditApplied = Math.min(subtotal, credit);
  const taxable = subtotal - creditApplied;
  const tax = Math.floor((taxable * taxBps + 5000) / 10000);
  return {
    subtotal,
    creditApplied,
    tax,
    total: taxable + tax,
    remainingCredit: credit - creditApplied,
  };
}
