function simulateMvcc(ops) {
  let nextTs = 1;
  const committed = new Map(); // key -> Array<{ ts, val }>
  const txns = new Map();
  const out = [];

  const readSnapshot = (key, startTs) => {
    const hist = committed.get(key);
    if (!hist) return null;
    for (let i = hist.length - 1; i >= 0; i -= 1) {
      if (hist[i].ts <= startTs) return hist[i].val;
    }
    return null;
  };

  for (const op of ops) {
    if (op.op === "BEGIN") {
      if (txns.has(op.tx)) throw new Error("duplicate tx");
      const st = nextTs++;
      txns.set(op.tx, { startTs: st, writes: new Map(), status: "ACTIVE" });
      out.push(`BEGIN:${st}`);
    } else if (op.op === "READ") {
      const t = txns.get(op.tx);
      if (!t || t.status !== "ACTIVE") throw new Error("inactive tx");
      const val = t.writes.has(op.key) ? t.writes.get(op.key) : readSnapshot(op.key, t.startTs);
      out.push(val === null ? "NULL" : String(val));
    } else if (op.op === "WRITE") {
      const t = txns.get(op.tx);
      if (!t || t.status !== "ACTIVE") throw new Error("inactive tx");
      t.writes.set(op.key, op.value);
      out.push("WROTE");
    } else if (op.op === "ABORT") {
      const t = txns.get(op.tx);
      if (!t || t.status !== "ACTIVE") throw new Error("inactive tx");
      t.status = "ABORTED";
      out.push("ABORTED");
    } else if (op.op === "COMMIT") {
      const t = txns.get(op.tx);
      if (!t || t.status !== "ACTIVE") throw new Error("inactive tx");
      let conflict = false;
      for (const k of t.writes.keys()) {
        const hist = committed.get(k);
        if (hist && hist[hist.length - 1].ts > t.startTs) {
          conflict = true;
          break;
        }
      }
      if (conflict) {
        t.status = "ABORTED";
        out.push("CONFLICT");
      } else {
        const cts = nextTs++;
        for (const [k, v] of t.writes.entries()) {
          if (!committed.has(k)) committed.set(k, []);
          committed.get(k).push({ ts: cts, val: v });
        }
        t.status = "COMMITTED";
        out.push(`COMMIT:${cts}`);
      }
    } else {
      throw new Error("unknown op");
    }
  }
  return out;
}
