function reassembleIpPackets(maxBytes, ttl, fragments) {
  if (maxBytes < 0 || ttl < 0) throw new Error("bad buffer config");
  const pkts = new Map();
  let usedBytes = 0;
  const out = [];

  const evictExpired = (now) => {
    for (const [pid, st] of [...pkts.entries()]) {
      if (now - st.firstTs > ttl) {
        usedBytes -= st.bytes.size;
        pkts.delete(pid);
      }
    }
  };

  for (const frag of fragments) {
    if (frag.offset < 0 || frag.ts < 0) throw new Error("bad fragment");
    evictExpired(frag.ts);
    let st = pkts.get(frag.pktId);
    if (!st) {
      st = { firstTs: frag.ts, bytes: new Map(), totalLen: null };
      pkts.set(frag.pktId, st);
    }
    let added = 0;
    for (let i = 0; i < frag.data.length; i += 1) {
      const pos = frag.offset + i;
      if (!st.bytes.has(pos)) added += 1;
    }
    if (usedBytes + added > maxBytes) {
      const order = [...pkts.entries()]
        .filter(([pid]) => pid !== frag.pktId)
        .sort((a, b) => a[1].firstTs - b[1].firstTs);
      for (const [pid, ost] of order) {
        if (usedBytes + added <= maxBytes) break;
        usedBytes -= ost.bytes.size;
        pkts.delete(pid);
      }
    }
    if (usedBytes + added > maxBytes) {
      if (st.bytes.size === 0) pkts.delete(frag.pktId);
      continue;
    }
    for (let i = 0; i < frag.data.length; i += 1) {
      const pos = frag.offset + i;
      if (!st.bytes.has(pos)) {
        st.bytes.set(pos, frag.data[i]);
        usedBytes += 1;
      }
    }
    if (!frag.mf) st.totalLen = frag.offset + frag.data.length;
    if (st.totalLen !== null && st.bytes.size === st.totalLen) {
      let ok = true;
      const chars = new Array(st.totalLen);
      for (let i = 0; i < st.totalLen; i += 1) {
        if (!st.bytes.has(i)) { ok = false; break; }
        chars[i] = st.bytes.get(i);
      }
      if (ok) {
        usedBytes -= st.bytes.size;
        pkts.delete(frag.pktId);
        out.push(`${frag.pktId}:${chars.join("")}`);
      }
    }
  }
  return out;
}
