```typescript
interface LogEntry {
  term: number;
  index: number;
}

interface PeerState {
  id: string;
  matchIndex: number;
  nextIndex: number;
}

interface AppendAck {
  peerId: string;
  success: boolean;
  matchIndex: number;
}

function advanceRaftCommit(
  currentTerm: number,
  commitIndex: number,
  log: LogEntry[],
  peers: PeerState[],
  acks: AppendAck[],
): { commitIndex: number; peers: PeerState[] } {
  if (currentTerm < 0 || commitIndex < 0) throw new Error("bad raft state");
  const termAt = new Map<number, number>();
  let prevIdx = 0;
  for (const e of log) {
    if (e.index !== prevIdx + 1) throw new Error("non-contiguous log");
    termAt.set(e.index, e.term);
    prevIdx = e.index;
  }
  const peerMap = new Map<string, PeerState>();
  for (const p of peers) {
    peerMap.set(p.id, { ...p });
  }
  for (const ack of acks) {
    const p = peerMap.get(ack.peerId);
    if (!p) throw new Error("unknown peer");
    if (ack.success) {
      if (ack.matchIndex > prevIdx) throw new Error("ack past leader log");
      p.matchIndex = Math.max(p.matchIndex, ack.matchIndex);
      p.nextIndex = p.matchIndex + 1;
    } else {
      p.nextIndex = Math.max(1, Math.min(p.nextIndex - 1, ack.matchIndex + 1));
    }
  }
  const updated = [...peerMap.values()];
  const totalNodes = updated.length + 1;
  const quorum = Math.floor(totalNodes / 2) + 1;
  let nextCommit = commitIndex;
  for (let n = prevIdx; n > commitIndex; n -= 1) {
    if (termAt.get(n) !== currentTerm) continue;
    let count = 1;
    for (const p of updated) {
      if (p.matchIndex >= n) count += 1;
    }
    if (count >= quorum) {
      nextCommit = n;
      break;
    }
  }
  return { commitIndex: nextCommit, peers: updated };
}
