interface QosClass {
  id: string;
  rate: number;
  burst: number;
  priority: number;
}

type QosEvent =
  | { op: "TICK"; dt: number }
  | { op: "SEND"; classId: string; bytes: number };

function shapeTrafficQos(
  rootRate: number,
  rootBurst: number,
  classes: QosClass[],
  events: QosEvent[],
): string[] {
  if (rootRate < 0 || rootBurst < 0) throw new Error("bad root");
  let rootTokens = rootBurst;
  const clsMap = new Map<string, { rate: number; burst: number; priority: number; tokens: number }>();
  for (const c of classes) {
    if (c.rate < 0 || c.burst < 0 || clsMap.has(c.id)) throw new Error("bad class");
    clsMap.set(c.id, { rate: c.rate, burst: c.burst, priority: c.priority, tokens: c.burst });
  }
  const out: string[] = [];
  for (const ev of events) {
    if (ev.op === "TICK") {
      if (ev.dt < 0) throw new Error("negative dt");
      rootTokens = Math.min(rootBurst, rootTokens + ev.dt * rootRate);
      const ordered = [...clsMap.values()].sort((a, b) => a.priority - b.priority);
      for (const c of ordered) {
        c.tokens = Math.min(c.burst, c.tokens + ev.dt * c.rate);
      }
    } else {
      if (ev.bytes <= 0) throw new Error("bad packet bytes");
      const c = clsMap.get(ev.classId);
      if (!c) throw new Error("unknown class");
      if (c.tokens >= ev.bytes) {
        c.tokens -= ev.bytes;
        out.push(`PASS:${ev.classId}`);
      } else if (c.tokens + rootTokens >= ev.bytes) {
        const borrow = ev.bytes - c.tokens;
        c.tokens = 0;
        rootTokens -= borrow;
        out.push(`BORROW:${ev.classId}:${borrow}`);
      } else {
        out.push(`DROP:${ev.classId}`);
      }
    }
  }
  return out;
}
