    if (b.kind === "prim" && b.name === "unknown") return true;
    if (a.kind === "union") return a.members.every((m) => check(m, b));
    if (b.kind === "union") return b.members.some((m) => check(a, m));
    if (a.kind === "prim" && b.kind === "prim") return a.name === b.name;
    if (a.kind === "record" && b.kind === "record") {
      for (const [k, bf] of Object.entries(b.fields)) {
        const af = a.fields[k];
        if (!af) return false;
        if (!bf.readonly && af.readonly) return false;
        if (!check(af.type, bf.type)) return false;
        if (!bf.readonly && !check(bf.type, af.type)) return false;
      }
      return true;
    }
    if (a.kind === "fn" && b.kind === "fn") {
      if (a.params.length > b.params.length) return false;
      for (let i = 0; i < a.params.length; i += 1) {
        if (!check(b.params[i], a.params[i])) return false;
      }
      return check(a.ret, b.ret);
    }
    return false;
  };
  return check(sub, sup);
}
