interface WalRecord {
  seq: number;
  kind: "PUT" | "DEL" | "CKPT";
  key?: string;
  value?: string;
  lsn?: number;
}

function recoverAndCompactWal(
  segments: WalRecord[][],
): { snapshot: Record<string, string>; liveSeqs: number[]; truncatedCorrupt: number } {
  let expectedSeq = 1;
  let truncatedCorrupt = 0;
  const active = new Map<string, { seq: number; value: string }>();

  for (const seg of segments) {
    for (let i = 0; i < seg.length; i += 1) {
      const rec = seg[i];
      if (rec.seq !== expectedSeq) {
        truncatedCorrupt += seg.length - i;
        return buildOut(active, truncatedCorrupt);
      }
      expectedSeq += 1;
      if (rec.kind === "PUT") {
        if (rec.key === undefined || rec.value === undefined) throw new Error("bad PUT");
        active.set(rec.key, { seq: rec.seq, value: rec.value });
      } else if (rec.kind === "DEL") {
        if (rec.key === undefined) throw new Error("bad DEL");
        active.delete(rec.key);
      } else if (rec.kind === "CKPT") {
        if (rec.lsn === undefined || rec.lsn < 0) throw new Error("bad CKPT");
      } else {
        throw new Error("unknown WAL kind");
      }
    }
  }
  return buildOut(active, truncatedCorrupt);

  function buildOut(
    map: Map<string, { seq: number; value: string }>,
    dropped: number,
  ): { snapshot: Record<string, string>; liveSeqs: number[]; truncatedCorrupt: number } {
    const snapshot: Record<string, string> = {};
    const liveSeqs: number[] = [];
    for (const k of [...map.keys()].sort()) {
      const entry = map.get(k)!;
      snapshot[k] = entry.value;
      liveSeqs.push(entry.seq);
    }
    liveSeqs.sort((a, b) => a - b);
    return { snapshot, liveSeqs, truncatedCorrupt: dropped };
  }
}
