```typescript
interface EvRequest {
  evId: string;
  arrivalSlot: number;
  departSlot: number;
  kwhNeeded: number;
}

interface DepotSchedule {
  totalCost: number;
  unmetKwh: number;
  perEvDelivered: Record<string, number>;
}

function scheduleDepotCharging(
  numChargers: number,
  slotCapacityKwh: number,
  slotPrices: number[],
  requests: EvRequest[],
): DepotSchedule {
  if (numChargers < 0 || slotCapacityKwh <= 0) throw new Error("bad depot config");
  for (const p of slotPrices) if (p < 0) throw new Error("negative price");
  const T = slotPrices.length;
  const rem = new Map<string, number>();
  const delivered = new Map<string, number>();
  const evs = requests.map((r) => {
    if (r.arrivalSlot < 0 || r.departSlot > T || r.departSlot < r.arrivalSlot || r.kwhNeeded < 0) {
      throw new Error("bad ev request");
    }
    if (rem.has(r.evId)) throw new Error("duplicate evId");
    rem.set(r.evId, r.kwhNeeded);
    delivered.set(r.evId, 0);
    return r;
  });

  const slotsByPrice = Array.from({ length: T }, (_, s) => s).sort((a, b) =>
    slotPrices[a] !== slotPrices[b] ? slotPrices[a] - slotPrices[b] : a - b
  );
  const slotLoad = new Array(T).fill(0);
  const slotEvs: Array<Set<string>> = Array.from({ length: T }, () => new Set<string>());

  const sortedEvs = [...evs].sort((a, b) =>
    a.departSlot !== b.departSlot
      ? a.departSlot - b.departSlot
      : a.arrivalSlot !== b.arrivalSlot
      ? a.arrivalSlot - b.arrivalSlot
      : a.evId < b.evId ? -1 : 1
  );

  let totalCost = 0;
  for (const ev of sortedEvs) {
    let need = ev.kwhNeeded;
    for (const s of slotsByPrice) {
      if (need === 0) break;
      if (s < ev.arrivalSlot || s >= ev.departSlot) continue;
      if (slotEvs[s].size >= numChargers) continue;
      const room = slotCapacityKwh - slotLoad[s];
      if (room <= 0) continue;
      const take = Math.min(need, room);
      slotLoad[s] += take;
      slotEvs[s].add(ev.evId);
      need -= take;
      totalCost += take * slotPrices[s];
      delivered.set(ev.evId, delivered.get(ev.evId)! + take);
    }
    rem.set(ev.evId, need);
  }

  let unmetKwh = 0;
  const perEvDelivered: Record<string, number> = {};
  for (const k of [...delivered.keys()].sort()) {
    perEvDelivered[k] = delivered.get(k)!;
    unmetKwh += rem.get(k)!;
  }
  return { totalCost, unmetKwh, perEvDelivered };
}
