interface CanaryConfig {
  initialPct: number;
  stepPct: number;
  maxPct: number;
  windowSize: number;
  maxErrorBps: number;
  cooldownTicks: number;
}

type CanaryEvent =
  | { op: "REQ"; tick: number; ok: boolean }
  | { op: "PROMOTE"; tick: number }
  | { op: "ROUTE"; key: number };

function runCanaryGate(cfg: CanaryConfig, events: CanaryEvent[]): string[] {
  if (
    cfg.initialPct < 0 ||
    cfg.maxPct > 100 ||
    cfg.initialPct > cfg.maxPct ||
    cfg.stepPct < 1 ||
    cfg.windowSize < 1 ||
    cfg.maxErrorBps < 0 ||
    cfg.cooldownTicks < 1
  ) {
    throw new Error("bad canary config");
  }
  let pct = cfg.initialPct;
  let trippedUntil = -Infinity;
  const ring: boolean[] = [];
  const out: string[] = [];

  for (const ev of events) {
    if (ev.op === "REQ") {
      ring.push(ev.ok);
      if (ring.length > cfg.windowSize) ring.shift();
      if (ring.length === cfg.windowSize) {
        let errs = 0;
        for (const ok of ring) if (!ok) errs += 1;
        const bps = Math.floor((errs * 10000) / ring.length);
        if (bps > cfg.maxErrorBps) {
          pct = 0;
          trippedUntil = ev.tick + cfg.cooldownTicks;
          ring.length = 0;
          out.push(`ROLLBACK@${ev.tick}`);
          continue;
        }
      }
      out.push(`OK:${pct}`);
    } else if (ev.op === "PROMOTE") {
      if (ev.tick < trippedUntil) {
        out.push(`FROZEN:${pct}`);
      } else {
        pct = Math.min(cfg.maxPct, pct === 0 ? cfg.initialPct : pct + cfg.stepPct);
        out.push(`PCT:${pct}`);
      }
    } else {
      const bucket = ((ev.key % 100) + 100) % 100;
      out.push(bucket < pct ? "CANARY" : "STABLE");
    }
  }
  return out;
}
