interface JobDef {
  jobId: string;
  minuteMask: number[];
  hourMask: number[];
  concurrency: "ALLOW" | "FORBID" | "REPLACE";
  durationMin: number;
}

function planJobTriggers(
  jobs: JobDef[],
  startMin: number,
  endMin: number,
): string[] {
  if (startMin < 0 || endMin < startMin) throw new Error("bad window");
  const minuteSets = new Map<string, Set<number>>();
  const hourSets = new Map<string, Set<number>>();
  for (const j of jobs) {
    if (j.durationMin < 1 || minuteSets.has(j.jobId)) throw new Error("bad job def");
    for (const m of j.minuteMask) if (m < 0 || m > 59) throw new Error("bad minute");
    for (const h of j.hourMask) if (h < 0 || h > 23) throw new Error("bad hour");
    minuteSets.set(j.jobId, new Set(j.minuteMask));
    hourSets.set(j.jobId, new Set(j.hourMask));
  }
  const sortedJobs = [...jobs].sort((a, b) => (a.jobId < b.jobId ? -1 : 1));
  const runningUntil = new Map<string, number[]>();
  for (const j of sortedJobs) runningUntil.set(j.jobId, []);

  const out: string[] = [];
  for (let t = startMin; t <= endMin; t += 1) {
    const mm = t % 60;
    const hh = Math.floor(t / 60) % 24;
    for (const j of sortedJobs) {
      const active = runningUntil.get(j.jobId)!.filter((endT) => endT > t);
      runningUntil.set(j.jobId, active);
      if (!minuteSets.get(j.jobId)!.has(mm) || !hourSets.get(j.jobId)!.has(hh)) continue;
      if (active.length === 0 || j.concurrency === "ALLOW") {
        active.push(t + j.durationMin);
        out.push(`RUN:${j.jobId}@${t}`);
      } else if (j.concurrency === "FORBID") {
        out.push(`SKIP:${j.jobId}@${t}`);
      } else {
        runningUntil.set(j.jobId, [t + j.durationMin]);
        out.push(`REPLACE:${j.jobId}@${t}`);
      }
    }
  }
  return out;
}
