type CellInput = number | string; // e.g. 5 or "=A1+B2" or "=SUM(A1:A3)"

function evaluateTypedGrid(
  cells: Record<string, CellInput>,
): Record<string, number | "ERR"> {
  const parseRef = (ref: string): [number, number] => {
    const m = /^([A-Z]+)(\d+)$/.exec(ref);
    if (!m) throw new Error("bad cell ref");
    let col = 0;
    for (const ch of m[1]) col = col * 26 + (ch.charCodeAt(0) - 64);
    const row = Number(m[2]);
    return [col, row];
  };
  const toRef = (col: number, row: number): string => {
    let c = col;
    let s = "";
    while (c > 0) {
      const r = (c - 1) % 26;
      s = String.fromCharCode(65 + r) + s;
      c = Math.floor((c - 1) / 26);
    }
    return `${s}${row}`;
  };

  const state = new Map<string, 0 | 1 | 2>(); // 0=unvisited, 1=visiting, 2=done
  const cache = new Map<string, number | "ERR">();

  const evalCell = (id: string): number | "ERR" => {
    const st = state.get(id) ?? 0;
    if (st === 1) return "ERR";
    if (st === 2) return cache.get(id)!;
    if (!(id in cells)) return 0;
    state.set(id, 1);
    const raw = cells[id];
    let res: number | "ERR";
    if (typeof raw === "number") {
      res = raw;
    } else if (!raw.startsWith("=")) {
      res = "ERR";
    } else {
      const expr = raw.slice(1).replace(/\s+/g, "");
      if (expr.startsWith("SUM(") && expr.endsWith(")")) {
        const inner = expr.slice(4, -1);
        const [a, b] = inner.split(":");
        const [c1, r1] = parseRef(a);
        const [c2, r2] = parseRef(b);
        let acc = 0;
        let failed = false;
        for (let c = Math.min(c1, c2); c <= Math.max(c1, c2) && !failed; c += 1) {
          for (let r = Math.min(r1, r2); r <= Math.max(r1, r2); r += 1) {
            const v = evalCell(toRef(c, r));
            if (v === "ERR") { failed = true; break; }
            acc += v;
          }
        }
        res = failed ? "ERR" : acc;
      } else {
        const terms = expr.split(/(?=[+-])/);
        let acc = 0;
        let failed = false;
        for (const tk of terms) {
          if (!tk) continue;
          const sign = tk.startsWith("-") ? -1 : 1;
          const body = tk.startsWith("+") || tk.startsWith("-") ? tk.slice(1) : tk;
          if (/^\d+$/.test(body)) {
            acc += sign * Number(body);
          } else if (/^[A-Z]+\d+$/.test(body)) {
            const v = evalCell(body);
            if (v === "ERR") { failed = true; break; }
            acc += sign * v;
          } else {
            failed = true;
            break;
          }
        }
        res = failed ? "ERR" : acc;
      }
    }
    state.set(id, 2);
    cache.set(id, res);
    return res;
  };

  const out: Record<string, number | "ERR"> = {};
  for (const k of Object.keys(cells).sort()) {
    out[k] = evalCell(k);
  }
  return out;
}
