std::vector<int> simulateHpa(
    int minReplicas, int maxReplicas, long long targetUtil,
    int scaleUpStep, int scaleDownStep,
    int upWindow, int downWindow,
    int upCooldown, int downCooldown,
    const std::vector<long long>& loads) {
    int replicas = minReplicas;
    std::vector<int> hist;
    hist.reserve(loads.size());
    std::vector<int> out;
    out.reserve(loads.size());
    int lastUp = -1000000000;
    int lastDown = -1000000000;
    for (int t = 0; t < (int)loads.size(); ++t) {
        long long rawLL = (1LL * replicas * loads[t] + targetUtil - 1) / targetUtil;
        int raw = (int)std::clamp<long long>(rawLL, minReplicas, maxReplicas);
        hist.push_back(raw);
        int su = hist[t];
        for (int i = std::max(0, t - upWindow + 1); i <= t; ++i) su = std::min(su, hist[i]);
        int sd = hist[t];
        for (int i = std::max(0, t - downWindow + 1); i <= t; ++i) sd = std::max(sd, hist[i]);
        if (su > replicas && t - lastUp >= upCooldown) {
            replicas = std::min(su, replicas + scaleUpStep);
            lastUp = t;
        } else if (sd < replicas && t - lastDown >= downCooldown) {
            replicas = std::max(sd, replicas - scaleDownStep);
            lastDown = t;
        }
        out.push_back(replicas);
    }
    return out;
}
