std::vector<int> advanceRaftLog(
    int currentTerm,
    int commitIndex,
    const std::vector<std::pair<int, int>>& log,
    const std::vector<std::tuple<std::string, int, int>>& peers,
    const std::vector<std::tuple<std::string, bool, int>>& acks) {
    std::unordered_map<int, int> termAt;
    int lastIdx = 0;
    for (const auto& [t, idx] : log) {
        termAt[idx] = t;
        lastIdx = idx;
    }
    std::unordered_map<std::string, size_t> pos;
    std::vector<int> matchIdx(peers.size()), nextIdx(peers.size());
    for (size_t i = 0; i < peers.size(); ++i) {
        pos[std::get<0>(peers[i])] = i;
        matchIdx[i] = std::get<1>(peers[i]);
        nextIdx[i] = std::get<2>(peers[i]);
    }
    for (const auto& [pid, ok, m] : acks) {
        size_t i = pos.at(pid);
        if (ok) {
            matchIdx[i] = std::max(matchIdx[i], m);
            nextIdx[i] = matchIdx[i] + 1;
        } else {
            nextIdx[i] = std::max(1, std::min(nextIdx[i] - 1, m + 1));
        }
    }
    int quorum = ((int)peers.size() + 1) / 2 + 1;
    int nextCommit = commitIndex;
    for (int n = lastIdx; n > commitIndex; --n) {
        auto it = termAt.find(n);
        if (it == termAt.end() || it->second != currentTerm) continue;
        int cnt = 1;
        for (int m : matchIdx) if (m >= n) ++cnt;
        if (cnt >= quorum) {
            nextCommit = n;
            break;
        }
    }
    std::vector<int> res;
    res.reserve(1 + 2 * peers.size());
    res.push_back(nextCommit);
    for (int m : matchIdx) res.push_back(m);
    for (int nx : nextIdx) res.push_back(nx);
    return res;
}
