std::vector<std::string> runLeaseService(
    const std::vector<std::tuple<std::string, long long, std::string, std::string, long long, std::string>>& ops) {
    struct Lease { std::string owner; long long token; long long exp; };
    std::unordered_map<std::string, Lease> leases;
    std::unordered_map<std::string, long long> highFence;
    std::unordered_map<std::string, std::string> store;
    long long nextToken = 1;
    std::vector<std::string> out;
    for (const auto& [op, ts, key, owner, argNum, argStr] : ops) {
        if (op == "ACQUIRE") {
            auto it = leases.find(key);
            if (it != leases.end() && it->second.exp > ts) {
                out.push_back("BUSY");
            } else {
                long long tok = nextToken++;
                leases[key] = {owner, tok, ts + argNum};
                out.push_back("GRANT:" + std::to_string(tok));
            }
        } else if (op == "RENEW") {
            auto it = leases.find(key);
            if (it != leases.end() && it->second.exp > ts && it->second.owner == owner && it->second.token == argNum) {
                it->second.exp = ts + std::stoll(argStr);
                out.push_back("RENEWED");
            } else {
                out.push_back("STALE");
            }
        } else if (op == "RELEASE") {
            auto it = leases.find(key);
            if (it != leases.end() && it->second.exp > ts && it->second.owner == owner && it->second.token == argNum) {
                leases.erase(it);
                out.push_back("RELEASED");
            } else {
                out.push_back("STALE");
            }
        } else if (op == "WRITE") {
            long long hi = highFence.count(key) ? highFence[key] : 0;
            if (argNum <= 0 || argNum < hi) {
                out.push_back("FENCED");
            } else {
                highFence[key] = argNum;
                store[key] = argStr;
                out.push_back("OK:" + argStr);
            }
        } else if (op == "INSPECT") {
            auto it = leases.find(key);
            if (it == leases.end() || it->second.exp <= ts) {
                out.push_back("FREE:" + (store.count(key) ? store[key] : ""));
            } else {
                out.push_back(it->second.owner + "@" + std::to_string(it->second.token) + ":" + std::to_string(it->second.exp));
            }
        }
    }
    return out;
}
