std::vector<std::string> runMvcc(
    const std::vector<std::tuple<std::string, std::string, std::string, int>>& ops) {
    struct Tx { long long startTs; std::unordered_map<std::string, int> writes; };
    std::unordered_map<std::string, std::vector<std::pair<long long, int>>> committed;
    std::unordered_map<std::string, Tx> txns;
    long long nextTs = 1;
    std::vector<std::string> out;
    for (const auto& [op, tx, key, val] : ops) {
        if (op == "BEGIN") {
            long long st = nextTs++;
            txns[tx] = {st, {}};
            out.push_back("BEGIN:" + std::to_string(st));
        } else if (op == "READ") {
            auto& t = txns.at(tx);
            if (t.writes.count(key)) {
                out.push_back(std::to_string(t.writes[key]));
            } else {
                auto it = committed.find(key);
                if (it == committed.end()) {
                    out.push_back("NULL");
                } else {
                    const auto& hist = it->second;
                    bool found = false;
                    for (int i = (int)hist.size() - 1; i >= 0; --i) {
                        if (hist[i].first <= t.startTs) {
                            out.push_back(std::to_string(hist[i].second));
                            found = true;
                            break;
                        }
                    }
                    if (!found) out.push_back("NULL");
                }
            }
        } else if (op == "WRITE") {
            txns.at(tx).writes[key] = val;
            out.push_back("WROTE");
        } else if (op == "ABORT") {
            txns.erase(tx);
            out.push_back("ABORTED");
        } else if (op == "COMMIT") {
            auto& t = txns.at(tx);
            bool conflict = false;
            for (const auto& [k, _] : t.writes) {
                auto it = committed.find(k);
                if (it != committed.end() && !it->second.empty() && it->second.back().first > t.startTs) {
                    conflict = true;
                    break;
                }
            }
            if (conflict) {
                txns.erase(tx);
                out.push_back("CONFLICT");
            } else {
                long long cts = nextTs++;
                for (const auto& [k, v] : t.writes) committed[k].push_back({cts, v});
                txns.erase(tx);
                out.push_back("COMMIT:" + std::to_string(cts));
            }
        }
    }
    return out;
}
