std::vector<long long> scheduleEvDepot(
    int numChargers,
    long long slotCapKwh,
    const std::vector<long long>& prices,
    const std::vector<std::tuple<std::string, int, int, long long>>& requests) {
    int T = (int)prices.size();
    std::vector<int> slots(T);
    std::iota(slots.begin(), slots.end(), 0);
    std::sort(slots.begin(), slots.end(), [&](int a, int b) {
        return prices[a] != prices[b] ? prices[a] < prices[b] : a < b;
    });
    std::vector<long long> load(T, 0);
    std::vector<int> cnt(T, 0);
    auto reqs = requests;
    std::sort(reqs.begin(), reqs.end(), [](const auto& a, const auto& b) {
        if (std::get<2>(a) != std::get<2>(b)) return std::get<2>(a) < std::get<2>(b);
        if (std::get<1>(a) != std::get<1>(b)) return std::get<1>(a) < std::get<1>(b);
        return std::get<0>(a) < std::get<0>(b);
    });
    long long totalCost = 0, unmet = 0;
    for (const auto& [eid, arr, dep, kwh] : reqs) {
        long long rem = kwh;
        for (int s : slots) {
            if (rem == 0) break;
            if (s < arr || s >= dep || cnt[s] >= numChargers || load[s] >= slotCapKwh) continue;
            long long take = std::min(rem, slotCapKwh - load[s]);
            load[s] += take;
            cnt[s] += 1;
            rem -= take;
            totalCost += take * prices[s];
        }
        unmet += rem;
    }
    return {totalCost, unmet};
}
