std::vector<std::string> shapeQosTraffic(
    long long rootRate,
    long long rootBurst,
    const std::vector<std::tuple<std::string, long long, long long>>& classes,
    const std::vector<std::tuple<std::string, std::string, long long>>& events) {
    struct Cls { long long rate; long long burst; long long tok; };
    std::unordered_map<std::string, Cls> cmap;
    for (const auto& [cid, rate, burst] : classes) cmap[cid] = {rate, burst, burst};
    long long rtok = rootBurst;
    std::vector<std::string> out;
    for (const auto& [op, cid, num] : events) {
        if (op == "TICK") {
            rtok = std::min(rootBurst, rtok + num * rootRate);
            for (auto& [_, c] : cmap) c.tok = std::min(c.burst, c.tok + num * c.rate);
        } else {
            auto& c = cmap.at(cid);
            if (c.tok >= num) {
                c.tok -= num;
                out.push_back("PASS:" + cid);
            } else if (c.tok + rtok >= num) {
                long long borrow = num - c.tok;
                c.tok = 0;
                rtok -= borrow;
                out.push_back("BORROW:" + cid + ":" + std::to_string(borrow));
            } else {
                out.push_back("DROP:" + cid);
            }
        }
    }
    return out;
}
