std::vector<std::string> reassembleIpFragments(
    int maxBytes,
    long long ttl,
    const std::vector<std::tuple<std::string, long long, int, std::string, bool>>& frags) {
    struct Pkt { long long firstTs; std::map<int, char> bytes; int totalLen = -1; };
    std::unordered_map<std::string, Pkt> pkts;
    int used = 0;
    std::vector<std::string> out;
    for (const auto& [pid, ts, off, data, mf] : frags) {
        for (auto it = pkts.begin(); it != pkts.end(); ) {
            if (ts - it->second.firstTs > ttl) {
                used -= (int)it->second.bytes.size();
                it = pkts.erase(it);
            } else {
                ++it;
            }
        }
        auto [itP, inserted] = pkts.try_emplace(pid, Pkt{ts, {}, -1});
        auto& st = itP->second;
        int added = 0;
        for (int i = 0; i < (int)data.size(); ++i) {
            if (!st.bytes.count(off + i)) ++added;
        }
        if (used + added > maxBytes) {
            std::vector<std::pair<long long, std::string>> order;
            for (const auto& [opid, ost] : pkts) {
                if (opid != pid) order.push_back({ost.firstTs, opid});
            }
            std::sort(order.begin(), order.end());
            for (const auto& [_, opid] : order) {
                if (used + added <= maxBytes) break;
                used -= (int)pkts[opid].bytes.size();
                pkts.erase(opid);
            }
        }
        if (used + added > maxBytes) {
            if (st.bytes.empty()) pkts.erase(pid);
            continue;
        }
        for (int i = 0; i < (int)data.size(); ++i) {
            if (!st.bytes.count(off + i)) {
                st.bytes[off + i] = data[i];
                ++used;
            }
        }
        if (!mf) st.totalLen = off + (int)data.size();
        if (st.totalLen != -1 && (int)st.bytes.size() == st.totalLen) {
            std::string payload;
            payload.reserve(st.totalLen);
            for (int i = 0; i < st.totalLen; ++i) payload += st.bytes[i];
            used -= (int)st.bytes.size();
            pkts.erase(pid);
            out.push_back(pid + ":" + payload);
        }
    }
    return out;
}
