```cpp
std::vector<std::string> runCanaryGate(
    int initialPct, int stepPct, int maxPct,
    int windowSize, int maxErrorBps, int cooldownTicks,
    const std::vector<std::tuple<std::string, int, bool>>& events) {
    int pct = initialPct;
    long long trippedUntil = -1000000000LL;
    std::deque<bool> ring;
    std::vector<std::string> out;
    for (const auto& [op, arg, ok] : events) {
        if (op == "REQ") {
            ring.push_back(ok);
            if ((int)ring.size() > windowSize) ring.pop_front();
            if ((int)ring.size() == windowSize) {
                int errs = 0;
                for (bool v : ring) if (!v) ++errs;
                int bps = (errs * 10000) / windowSize;
                if (bps > maxErrorBps) {
                    pct = 0;
                    trippedUntil = (long long)arg + cooldownTicks;
                    ring.clear();
                    out.push_back("ROLLBACK@" + std::to_string(arg));
                    continue;
                }
            }
            out.push_back("OK:" + std::to_string(pct));
        } else if (op == "PROMOTE") {
            if (arg < trippedUntil) {
                out.push_back("FROZEN:" + std::to_string(pct));
            } else {
                pct = std::min(maxPct, pct == 0 ? initialPct : pct + stepPct);
                out.push_back("PCT:" + std::to_string(pct));
            }
        } else {
            int b = ((arg % 100) + 100) % 100;
            out.push_back(b < pct ? "CANARY" : "STABLE");
        }
    }
    return out;
}
