def run_lease_manager(ops):
    prev_ts = None
    next_token = 1
    leases = {}
    high_fence = {}
    store = {}
    out = []
    for item in ops:
        op, ts = item[0], item[1]
        if prev_ts is not None and ts < prev_ts:
            raise ValueError("non-monotonic ts")
        prev_ts = ts
        if op == "ACQUIRE":
            _, _, key, owner, ttl = item
            if ttl <= 0:
                raise ValueError("bad ttl")
            cur = leases.get(key)
            if cur is not None and cur[2] > ts:
                out.append("BUSY")
            else:
                tok = next_token
                next_token += 1
                leases[key] = [owner, tok, ts + ttl]
                out.append(f"GRANT:{tok}")
        elif op == "RENEW":
            _, _, key, owner, tok, ttl = item
            if ttl <= 0:
                raise ValueError("bad ttl")
            cur = leases.get(key)
            if cur is not None and cur[2] > ts and cur[0] == owner and cur[1] == tok:
                cur[2] = ts + ttl
                out.append("RENEWED")
            else:
                out.append("STALE")
        elif op == "RELEASE":
            _, _, key, owner, tok = item
            cur = leases.get(key)
            if cur is not None and cur[2] > ts and cur[0] == owner and cur[1] == tok:
                del leases[key]
                out.append("RELEASED")
            else:
                out.append("STALE")
        elif op == "WRITE":
            _, _, key, tok, val = item
            if tok <= 0 or tok < high_fence.get(key, 0):
                out.append("FENCED")
            else:
                high_fence[key] = tok
                store[key] = val
                out.append(f"OK:{val}")
        elif op == "INSPECT":
            _, _, key = item
            cur = leases.get(key)
            if cur is None or cur[2] <= ts:
                out.append(f"FREE:{store.get(key, '')}")
            else:
                out.append(f"{cur[0]}@{cur[1]}:{cur[2]}")
        else:
            raise ValueError("unknown op")
    return out
