def process_multipart_upload(total_size, part_size, events):
    if total_size < 0 or part_size <= 0:
        raise ValueError("bad upload config")
    parts = {}
    out = []
    for ev in events:
        op = ev[0]
        if op == "UPLOAD":
            _, pnum, off, length, etag = ev
            if not isinstance(pnum, int) or isinstance(pnum, bool) or pnum < 1 or off < 0 or length <= 0 or off + length > total_size or not etag:
                raise ValueError("bad part")
            parts[pnum] = (off, length, etag)
            out.append(f"PART:{pnum}:{length}")
        elif op == "ABORT":
            _, pnum = ev
            out.append("ABORTED" if parts.pop(pnum, None) is not None else "MISSING")
        elif op == "COMPLETE":
            _, manifest = ev
            err = None
            prev_num = 0
            intervals = []
            for idx, (pnum, etag) in enumerate(manifest):
                if pnum <= prev_num:
                    err = "ERR:ORDER"
                    break
                prev_num = pnum
                p = parts.get(pnum)
                if p is None or p[2] != etag:
                    err = "ERR:ETAG"
                    break
                is_last = idx == len(manifest) - 1
                if (not is_last and p[1] != part_size) or (is_last and p[1] > part_size):
                    err = "ERR:SIZE"
                    break
                intervals.append((p[0], p[0] + p[1]))
            if err is None:
                intervals.sort()
                cursor = 0
                for s, e in intervals:
                    if s != cursor:
                        err = "ERR:COVERAGE"
                        break
                    cursor = e
                if err is None and cursor != total_size:
                    err = "ERR:COVERAGE"
            out.append(err if err is not None else f"COMMIT:{len(manifest)}:{total_size}")
        else:
            raise ValueError("unknown op")
    return out
