def advance_raft_commit(current_term, commit_index, log, peers, acks):
    if current_term < 0 or commit_index < 0:
        raise ValueError("bad raft state")
    term_at = {}
    prev_idx = 0
    for term, idx in log:
        if idx != prev_idx + 1:
            raise ValueError("non-contiguous log")
        term_at[idx] = term
        prev_idx = idx
    pm = {pid: [m, n] for pid, m, n in peers}
    order = [pid for pid, _, _ in peers]
    for pid, ok, midx in acks:
        if pid not in pm:
            raise ValueError("unknown peer")
        if ok:
            if midx > prev_idx:
                raise ValueError("ack past leader log")
            pm[pid][0] = max(pm[pid][0], midx)
            pm[pid][1] = pm[pid][0] + 1
        else:
            pm[pid][1] = max(1, min(pm[pid][1] - 1, midx + 1))
    quorum = (len(peers) + 1) // 2 + 1
    next_commit = commit_index
    for n in range(prev_idx, commit_index, -1):
        if term_at.get(n) != current_term:
            continue
        cnt = 1 + sum(1 for pid in order if pm[pid][0] >= n)
        if cnt >= quorum:
            next_commit = n
            break
    return next_commit, [(pid, pm[pid][0], pm[pid][1]) for pid in order]
