def simulate_mvcc(ops):
    next_ts = 1
    committed = {}
    txns = {}
    out = []
    for item in ops:
        op = item[0]
        if op == "BEGIN":
            _, tx = item
            if tx in txns:
                raise ValueError("duplicate tx")
            st = next_ts
            next_ts += 1
            txns[tx] = [st, {}, "ACTIVE"]
            out.append(f"BEGIN:{st}")
        elif op == "READ":
            _, tx, key = item
            t = txns.get(tx)
            if t is None or t[2] != "ACTIVE":
                raise ValueError("inactive tx")
            if key in t[1]:
                val = t[1][key]
            else:
                val = None
                for cts, cv in reversed(committed.get(key, [])):
                    if cts <= t[0]:
                        val = cv
                        break
            out.append("NULL" if val is None else str(val))
        elif op == "WRITE":
            _, tx, key, val = item
            t = txns.get(tx)
            if t is None or t[2] != "ACTIVE":
                raise ValueError("inactive tx")
            t[1][key] = val
            out.append("WROTE")
        elif op == "ABORT":
            _, tx = item
            t = txns.get(tx)
            if t is None or t[2] != "ACTIVE":
                raise ValueError("inactive tx")
            t[2] = "ABORTED"
            out.append("ABORTED")
        elif op == "COMMIT":
            _, tx = item
            t = txns.get(tx)
            if t is None or t[2] != "ACTIVE":
                raise ValueError("inactive tx")
            conflict = any(committed.get(k) and committed[k][-1][0] > t[0] for k in t[1])
            if conflict:
                t[2] = "ABORTED"
                out.append("CONFLICT")
            else:
                cts = next_ts
                next_ts += 1
                for k, v in t[1].items():
                    committed.setdefault(k, []).append((cts, v))
                t[2] = "COMMITTED"
                out.append(f"COMMIT:{cts}")
        else:
            raise ValueError("unknown op")
    return out
