def schedule_depot_charging(num_chargers, slot_cap_kwh, slot_prices, requests):
    if num_chargers < 0 or slot_cap_kwh <= 0 or any(p < 0 for p in slot_prices):
        raise ValueError("bad depot config")
    t_len = len(slot_prices)
    seen = set()
    delivered = {}
    for ev_id, arr, dep, kwh in requests:
        if arr < 0 or dep > t_len or dep < arr or kwh < 0 or ev_id in seen:
            raise ValueError("bad request")
        seen.add(ev_id)
        delivered[ev_id] = 0
    slots = sorted(range(t_len), key=lambda s: (slot_prices[s], s))
    load = [0] * t_len
    cnt = [0] * t_len
    total_cost = 0
    unmet = 0
    for ev_id, arr, dep, kwh in sorted(requests, key=lambda r: (r[2], r[1], r[0])):
        need = kwh
        for s in slots:
            if need == 0:
                break
            if s < arr or s >= dep or cnt[s] >= num_chargers or load[s] >= slot_cap_kwh:
                continue
            take = min(need, slot_cap_kwh - load[s])
            load[s] += take
            cnt[s] += 1
            need -= take
            total_cost += take * slot_prices[s]
            delivered[ev_id] += take
        unmet += need
    return total_cost, unmet, dict(sorted(delivered.items()))
