def reassemble_ip_packets(max_bytes, ttl, fragments):
    if max_bytes < 0 or ttl < 0:
        raise ValueError("bad buffer config")
    pkts = {}
    used = 0
    out = []
    for pkt_id, ts, offset, data, mf in fragments:
        if offset < 0 or ts < 0:
            raise ValueError("bad fragment")
        for pid in [k for k, st in pkts.items() if ts - st[0] > ttl]:
            used -= len(pkts[pid][1])
            del pkts[pid]
        st = pkts.setdefault(pkt_id, [ts, {}, None])
        added = sum(1 for i in range(len(data)) if (offset + i) not in st[1])
        if used + added > max_bytes:
            others = sorted(((k, v) for k, v in pkts.items() if k != pkt_id), key=lambda kv: kv[1][0])
            for opid, ost in others:
                if used + added <= max_bytes:
                    break
                used -= len(ost[1])
                del pkts[opid]
        if used + added > max_bytes:
            if not st[1]:
                del pkts[pkt_id]
            continue
        for i, ch in enumerate(data):
            if (offset + i) not in st[1]:
                st[1][offset + i] = ch
                used += 1
        if not mf:
            st[2] = offset + len(data)
        if st[2] is not None and len(st[1]) == st[2]:
            payload = "".join(st[1][i] for i in range(st[2]))
            used -= len(st[1])
            del pkts[pkt_id]
            out.append(f"{pkt_id}:{payload}")
    return out
