"""Lease manager with monotonic fencing tokens."""


class LeaseRegistry:
    def __init__(self):
        self.next_token = 1
        self.leases = {}

    def is_active(self, key, now):
        cur = self.leases.get(key)
        return cur is not None and cur["expires_at"] >= now

    def acquire(self, key, owner, now, ttl):
        if self.is_active(key, now):
            return None
        tok = self.next_token
        self.next_token += 1
        self.leases[key] = {"owner": owner, "token": tok, "expires_at": now + ttl}
        return tok

    def renew(self, key, owner, token, now, ttl):
        if not self.is_active(key, now):
            return False
        cur = self.leases[key]
        if cur["owner"] != owner or cur["token"] != token:
            return False
        cur["expires_at"] = now + ttl
        return True

