from .leases import LeaseRegistry


class FencedKV:
    def __init__(self):
        self.registry = LeaseRegistry()
        self.high_token = {}
        self.data = {}

    def write(self, key, token, value):
        if token <= 0 or token <= self.high_token.get(key, 0):
            return False
        self.high_token[key] = token
        self.data[key] = value
        return True

    def read(self, key):
        return self.data.get(key)

