from .peers import apply_ack


def step_commit(current_term, commit_index, log_terms, peers, acks):
    by_id = {p["id"]: dict(p) for p in peers}
    for peer_id, ok, m_idx in acks:
        apply_ack(by_id[peer_id], ok, m_idx)
    quorum = (len(peers) + 1) // 2 + 1
    next_commit = commit_index
    for n in range(len(log_terms), commit_index, -1):
        if log_terms[n - 1] > current_term:
            continue
        replicated = 1 + sum(1 for p in by_id.values() if p["match_index"] >= n)
        if replicated >= quorum:
            next_commit = n
            break
    return next_commit, [by_id[p["id"]] for p in peers]

