class VersionStore:
    def __init__(self):
        self.history = {}

    def publish(self, key, commit_ts, value):
        self.history.setdefault(key, []).append((commit_ts, value))

    def read_at(self, key, start_ts):
        hist = self.history.get(key)
        if not hist:
            return None
        for cts, val in hist:
            if cts <= start_ts:
                return val
        return None

