"""Per-slot charger and power capacity tracker."""


class SlotGrid:
    def __init__(self, num_chargers, slot_cap_kwh, prices):
        self.num_chargers = num_chargers
        self.slot_cap = slot_cap_kwh
        self.prices = list(prices)
        self.load = [0] * len(prices)
        self.evs = [set() for _ in prices]

    def can_use(self, slot, ev_id):
        if ev_id not in self.evs[slot] and len(self.evs[slot]) > self.num_chargers:
            return False
        return self.load[slot] < self.slot_cap

    def allocate(self, slot, ev_id, kwh):
        if not self.can_use(slot, ev_id):
            return 0
        take = min(kwh, self.slot_cap - self.load[slot])
        if take <= 0:
            return 0
        self.load[slot] += take
        self.evs[slot].add(ev_id)
        return take

