"""Packet fragment byte buffer with memory budget."""


class PacketBuffer:
    def __init__(self, max_bytes):
        self.max_bytes = max_bytes
        self.used_bytes = 0
        self.entries = {}

    def ensure(self, pkt_id, ts):
        if pkt_id not in self.entries:
            self.entries[pkt_id] = {"first_ts": ts, "bytes": {}, "total_len": None}
        return self.entries[pkt_id]

    def drop(self, pkt_id):
        st = self.entries.pop(pkt_id, None)
        if st is not None:
            self.used_bytes -= len(st["bytes"])

    def write_fragment(self, pkt_id, ts, offset, data, mf):
        st = self.ensure(pkt_id, ts)
        added = sum(1 for i in range(len(data)) if (offset + i) not in st["bytes"])
        if self.used_bytes + added > self.max_bytes:
            others = sorted(((k, v) for k, v in self.entries.items() if k != pkt_id), key=lambda kv: kv[1]["first_ts"])
            for opid, _ in others:
                if self.used_bytes + added <= self.max_bytes:
                    break
                self.drop(opid)
        if self.used_bytes + added > self.max_bytes:
            if not st["bytes"]:
                self.entries.pop(pkt_id, None)
            return False
        for i, ch in enumerate(data):
            pos = offset + i
            st["bytes"][pos] = ch
            self.used_bytes += 1
        if not mf:
            st["total_len"] = offset + len(data)
        return True

