from .buffer import PacketBuffer


class Reassembler:
    def __init__(self, max_bytes, ttl):
        self.ttl = ttl
        self.buf = PacketBuffer(max_bytes)

    def feed(self, pkt_id, ts, offset, data, mf):
        for k in [pid for pid, st in self.buf.entries.items() if ts - st["first_ts"] >= self.ttl]:
            self.buf.drop(k)
        if not self.buf.write_fragment(pkt_id, ts, offset, data, mf):
            return None
        st = self.buf.entries[pkt_id]
        if st["total_len"] is not None and len(st["bytes"]) == st["total_len"]:
            payload = "".join(st["bytes"][i] for i in range(st["total_len"]))
            self.buf.entries.pop(pkt_id, None)
            return f"{pkt_id}:{payload}"
        return None

