from collections import deque


class ErrorWindow:
    def __init__(self, window_size, max_error_bps):
        self.window_size = window_size
        self.max_error_bps = max_error_bps
        self.ring = deque()

    def record(self, ok):
        self.ring.append(ok)
        if len(self.ring) > self.window_size:
            self.ring.popleft()
        if len(self.ring) < self.window_size:
            return False
        errs = sum(1 for v in self.ring if not v)
        return (errs * 10000) // self.window_size >= self.max_error_bps

    def reset(self):
        self.ring.clear()

