function runQosShaper(rootRate, rootBurst, classes, events) {
  if (rootRate < 0 || rootBurst < 0) throw new Error("bad root");
  let rootTokens = rootBurst;
  const cmap = new Map();
  for (const c of classes) {
    if (c.rate < 0 || c.burst < 0 || cmap.has(c.id)) throw new Error("bad class");
    cmap.set(c.id, { rate: c.rate, burst: c.burst, tokens: c.burst });
  }
  const out = [];
  for (const ev of events) {
    if (ev.op === "TICK") {
      if (ev.dt < 0) throw new Error("negative dt");
      rootTokens = Math.min(rootBurst, rootTokens + ev.dt * rootRate);
      for (const c of cmap.values()) {
        c.tokens = Math.min(c.burst, c.tokens + ev.dt * c.rate);
      }
    } else if (ev.op === "SEND") {
      if (ev.bytes <= 0) throw new Error("bad bytes");
      const c = cmap.get(ev.classId);
      if (!c) throw new Error("unknown class");
      if (c.tokens >= ev.bytes) {
        c.tokens -= ev.bytes;
        out.push(`PASS:${ev.classId}`);
      } else if (c.tokens + rootTokens >= ev.bytes) {
        const bor = ev.bytes - c.tokens;
        c.tokens = 0;
        rootTokens -= bor;
        out.push(`BORROW:${ev.classId}:${bor}`);
      } else {
        out.push(`DROP:${ev.classId}`);
      }
    } else {
      throw new Error("unknown op");
    }
  }
  return out;
}
