function scheduleCronJobs(jobs, startMin, endMin) {
  if (startMin < 0 || endMin < startMin) throw new Error("bad window");
  const mSets = new Map();
  const hSets = new Map();
  for (const j of jobs) {
    if (j.durationMin < 1 || mSets.has(j.jobId)) throw new Error("bad job");
    for (const m of j.minuteMask) if (m < 0 || m > 59) throw new Error("bad minute");
    for (const h of j.hourMask) if (h < 0 || h > 23) throw new Error("bad hour");
    mSets.set(j.jobId, new Set(j.minuteMask));
    hSets.set(j.jobId, new Set(j.hourMask));
  }
  const ordered = [...jobs].sort((a, b) => (a.jobId < b.jobId ? -1 : 1));
  const running = new Map();
  for (const j of ordered) running.set(j.jobId, []);
  const out = [];
  for (let t = startMin; t <= endMin; t += 1) {
    const mm = t % 60;
    const hh = Math.floor(t / 60) % 24;
    for (const j of ordered) {
      const act = running.get(j.jobId).filter((e) => e > t);
      running.set(j.jobId, act);
      if (!mSets.get(j.jobId).has(mm) || !hSets.get(j.jobId).has(hh)) continue;
      if (act.length === 0 || j.concurrency === "ALLOW") {
        act.push(t + j.durationMin);
        out.push(`RUN:${j.jobId}@${t}`);
      } else if (j.concurrency === "FORBID") {
        out.push(`SKIP:${j.jobId}@${t}`);
      } else if (j.concurrency === "REPLACE") {
        running.set(j.jobId, [t + j.durationMin]);
        out.push(`REPLACE:${j.jobId}@${t}`);
      } else {
        throw new Error("bad concurrency");
      }
    }
  }
  return out;
}
