function simulateOrder4BTree(ops) {
  const newNode = (leaf) => ({ leaf, keys: [], children: [] });
  let root = newNode(true);

  const splitChild = (parent, idx) => {
    const child = parent.children[idx];
    const right = newNode(child.leaf);
    const midKey = child.keys[1];
    right.keys = child.keys.slice(2);
    child.keys = child.keys.slice(0, 1);
    if (!child.leaf) {
      right.children = child.children.slice(2);
      child.children = child.children.slice(0, 2);
    }
    parent.keys.splice(idx, 0, midKey);
    parent.children.splice(idx + 1, 0, right);
  };

  const insertNonFull = (node, k) => {
    let i = node.keys.length - 1;
    if (node.leaf) {
      while (i >= 0 && node.keys[i] > k) i -= 1;
      if (i >= 0 && node.keys[i] === k) return false;
      node.keys.splice(i + 1, 0, k);
      return true;
    }
    while (i >= 0 && node.keys[i] > k) i -= 1;
    if (i >= 0 && node.keys[i] === k) return false;
    let cIdx = i + 1;
    if (node.children[cIdx].keys.length === 3) {
      if (node.children[cIdx].keys.includes(k)) return false;
      splitChild(node, cIdx);
      if (k === node.keys[cIdx]) return false;
      if (k > node.keys[cIdx]) cIdx += 1;
    }
    return insertNonFull(node.children[cIdx], k);
  };

  const contains = (node, k) => {
    let i = 0;
    while (i < node.keys.length && k > node.keys[i]) i += 1;
    if (i < node.keys.length && node.keys[i] === k) return true;
    if (node.leaf) return false;
    return contains(node.children[i], k);
  };

  const height = (node) => (node.leaf ? 1 : 1 + height(node.children[0]));

  const out = [];
  for (const op of ops) {
    if (op.op === "PUT") {
      if (contains(root, op.key)) {
        out.push("DUP");
        continue;
      }
      if (root.keys.length === 3) {
        const s = newNode(false);
        s.children.push(root);
        splitChild(s, 0);
        root = s;
      }
      insertNonFull(root, op.key);
      out.push(`OK:H${height(root)}`);
    } else if (op.op === "GET") {
      out.push(contains(root, op.key) ? "HIT" : "MISS");
    } else if (op.op === "RANGE") {
      const acc = [];
      const walk = (n) => {
        for (let i = 0; i < n.keys.length; i += 1) {
          if (!n.leaf) walk(n.children[i]);
          if (n.keys[i] >= op.lo && n.keys[i] <= op.hi) acc.push(n.keys[i]);
