function resolvePackageDeps(catalog, roots) {
  const pkgNames = Object.keys(catalog).sort();
  const versionsOf = (pkg) => catalog[pkg] || [];
  const chosen = new Map();

  const checkAllConstraints = () => {
    for (const [pkg, ver] of chosen.entries()) {
      const entry = versionsOf(pkg).find((v) => v.ver === ver);
      if (!entry) return false;
      for (const [dep, req] of Object.entries(entry.deps)) {
        if (chosen.has(dep)) {
          const dv = chosen.get(dep);
          if (dv < req.min || dv > req.max) return false;
        }
      }
    }
    return true;
  };

  const pending = () => {
    const reqs = new Map();
    for (const [pkg, bounds] of Object.entries(roots)) {
      reqs.set(pkg, { min: bounds.min, max: bounds.max });
    }
    for (const [pkg, ver] of chosen.entries()) {
      const entry = versionsOf(pkg).find((v) => v.ver === ver);
      for (const [dep, b] of Object.entries(entry.deps)) {
        const cur = reqs.get(dep);
        if (!cur) reqs.set(dep, { min: b.min, max: b.max });
        else reqs.set(dep, { min: Math.max(cur.min, b.min), max: Math.min(cur.max, b.max) });
      }
    }
    for (const [dep, b] of reqs.entries()) {
      if (b.min > b.max) return { conflict: true, nextPkg: null, bounds: null };
      if (!chosen.has(dep)) return { conflict: false, nextPkg: dep, bounds: b };
      const v = chosen.get(dep);
      if (v < b.min || v > b.max) return { conflict: true, nextPkg: null, bounds: null };
    }
    return { conflict: false, nextPkg: null, bounds: null };
  };

  const solve = () => {
    if (!checkAllConstraints()) return false;
    const p = pending();
    if (p.conflict) return false;
    if (p.nextPkg === null) return true;
    const cands = versionsOf(p.nextPkg)
      .filter((e) => e.ver >= p.bounds.min && e.ver <= p.bounds.max)
      .sort((a, b) => b.ver - a.ver);
    for (const c of cands) {
      chosen.set(p.nextPkg, c.ver);
      if (solve()) return true;
