    return items.length === 1 ? items[0] : { kind: "seq", items };
  };
  const parseQuant = () => {
    const atom = parseAtom();
    if (pos < pattern.length && (pattern[pos] === "*" || pattern[pos] === "+" || pattern[pos] === "?")) {
      const q = pattern[pos++];
      return { kind: "quant", q, node: atom };
    }
    return atom;
  };
  const parseAtom = () => {
    if (pos >= pattern.length) throw new Error("unexpected end");
    const ch = pattern[pos++];
    if (ch === "(") {
      const inner = parseExpr();
      if (pattern[pos++] !== ")") throw new Error("missing )");
      return inner;
