function computeSlaDeadline(startMin, slaMinutes, workStartMin, workEndMin, holidays) {
  if (
    startMin < 0 ||
    slaMinutes < 0 ||
    workStartMin < 0 ||
    workEndMin > 1440 ||
    workStartMin >= workEndMin
  ) {
    throw new Error("bad SLA config");
  }
  const holidaySet = new Set(holidays);
  const isWorkDay = (day) => {
    const dow = day % 7; // day 0 = Mon..4=Fri, 5=Sat, 6=Sun
    return dow < 5 && !holidaySet.has(day);
  };
  let curDay = Math.floor(startMin / 1440);
  let curTod = startMin % 1440;
  let rem = slaMinutes;
  while (true) {
    if (!isWorkDay(curDay) || curTod >= workEndMin) {
      curDay += 1;
      curTod = workStartMin;
      continue;
    }
    if (curTod < workStartMin) curTod = workStartMin;
    if (rem === 0) return curDay * 1440 + curTod;
    const avail = workEndMin - curTod;
    if (rem <= avail) return curDay * 1440 + curTod + rem;
    rem -= avail;
    curDay += 1;
    curTod = workStartMin;
  }
}
