type TxOp =
  | { op: "BEGIN"; tx: string; ts: number }
  | { op: "READ"; tx: string; key: string }
  | { op: "WRITE"; tx: string; key: string; value: number }
  | { op: "COMMIT"; tx: string; ts: number }
  | { op: "ABORT"; tx: string };

function runMvccLedger(ops: TxOp[]): string[] {
  interface Version { ts: number; val: number | null }
  interface TxState { startTs: number; writes: Map<string, number>; closed: boolean }

  const store = new Map<string, Version[]>();
  const txs = new Map<string, TxState>();
  const out: string[] = [];

  const visibleValue = (key: string, snapTs: number): number | null => {
    const vers = store.get(key);
    if (!vers) return null;
    for (let i = vers.length - 1; i >= 0; i -= 1) {
      if (vers[i].ts <= snapTs) return vers[i].val;
    }
    return null;
  };

  for (const ev of ops) {
    if (ev.op === "BEGIN") {
      if (txs.has(ev.tx) || ev.ts < 0) throw new Error("bad BEGIN");
      txs.set(ev.tx, { startTs: ev.ts, writes: new Map(), closed: false });
      out.push(`BEGIN:${ev.tx}@${ev.ts}`);
    } else if (ev.op === "READ") {
      const st = txs.get(ev.tx);
      if (!st || st.closed) throw new Error("tx not active");
      if (st.writes.has(ev.key)) {
        out.push(`VAL:${st.writes.get(ev.key)}`);
      } else {
        const v = visibleValue(ev.key, st.startTs);
        out.push(v === null ? "NULL" : `VAL:${v}`);
      }
    } else if (ev.op === "WRITE") {
      const st = txs.get(ev.tx);
      if (!st || st.closed) throw new Error("tx not active");
      st.writes.set(ev.key, ev.value);
      out.push(`STAGE:${ev.tx}:${ev.key}`);
    } else if (ev.op === "ABORT") {
      const st = txs.get(ev.tx);
      if (!st || st.closed) throw new Error("tx not active");
      st.closed = true;
      out.push(`ABORT:${ev.tx}`);
    } else if (ev.op === "COMMIT") {
      const st = txs.get(ev.tx);
      if (!st || st.closed || ev.ts <= st.startTs) throw new Error("bad COMMIT");
      let conflict = false;
      for (const key of st.writes.keys()) {
        const vers = store.get(key);
        if (vers && vers.length > 0 && vers[vers.length - 1].ts > st.startTs) {
          conflict = true;
          break;
        }
      }
      st.closed = true;
      if (conflict) {
        out.push(`CONFLICT:${ev.tx}`);
      } else {
        for (const [k, v] of st.writes.entries()) {
          if (!store.has(k)) store.set(k, []);
          store.get(k)!.push({ ts: ev.ts, val: v });
        }
        out.push(`COMMIT:${ev.tx}@${ev.ts}`);
      }
    } else {
      throw new Error("unknown op");
    }
  }
  return out;
}
