type RingOp =
  | { op: "ADD_NODE"; nodeId: string; weight: number }
  | { op: "REMOVE_NODE"; nodeId: string }
  | { op: "PUT"; key: string }
  | { op: "LOOKUP"; key: string; replicas: number };

function simulateConsistentHashRing(ops: RingOp[]): Array<string | string[]> {
  const fnv1a = (str: string): number => {
    let h = 2166136261;
    for (let i = 0; i < str.length; i += 1) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 16777619) >>> 0;
    }
    return h >>> 0;
  };

  interface VNode { hash: number; nodeId: string; vnode: string }
  let ring: VNode[] = [];
  const nodes = new Set<string>();

  const rebuild = () => {
    ring.sort((a, b) => (a.hash !== b.hash ? a.hash - b.hash : a.vnode < b.vnode ? -1 : a.vnode > b.vnode ? 1 : 0));
  };

  const upperBound = (h: number): number => {
    let lo = 0, hi = ring.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (ring[mid].hash < h) lo = mid + 1;
      else hi = mid;
    }
    return lo === ring.length ? 0 : lo;
  };

  const out: Array<string | string[]> = [];
  for (const op of ops) {
    if (op.op === "ADD_NODE") {
      if (op.weight < 1 || nodes.has(op.nodeId)) throw new Error("bad ADD_NODE");
      nodes.add(op.nodeId);
      for (let i = 0; i < op.weight; i += 1) {
        const vn = `${op.nodeId}#${i}`;
        ring.push({ hash: fnv1a(vn), nodeId: op.nodeId, vnode: vn });
      }
      rebuild();
    } else if (op.op === "REMOVE_NODE") {
      if (!nodes.has(op.nodeId)) throw new Error("unknown node");
      nodes.delete(op.nodeId);
      ring = ring.filter((v) => v.nodeId !== op.nodeId);
    } else if (op.op === "PUT") {
      if (ring.length === 0) {
        out.push("EMPTY");
      } else {
        const idx = upperBound(fnv1a(op.key));
        out.push(ring[idx].nodeId);
      }
    } else if (op.op === "LOOKUP") {
      if (op.replicas < 1) throw new Error("bad replicas");
      if (ring.length === 0) {
        out.push([]);
      } else {
        const start = upperBound(fnv1a(op.key));
        const picked: string[] = [];
        const seen = new Set<string>();
        for (let step = 0; step < ring.length && picked.length < op.replicas; step += 1) {
          const nid = ring[(start + step) % ring.length].nodeId;
          if (!seen.has(nid)) {
            seen.add(nid);
            picked.push(nid);
          }
        }
        out.push(picked);
      }
    } else {
      throw new Error("unknown op");
    }
  }
  return out;
}
