type CoordinatorOp =
  | { op: "PREPARE"; tx: string; participants: string[]; votes: Record<string, "YES" | "NO"> }
  | { op: "CRASH"; tx: string }
  | { op: "RECOVER"; tx: string }
  | { op: "ACK"; tx: string; participant: string };

function runTwoPhaseCommit(ops: CoordinatorOp[]): string[] {
  interface TxRec {
    phase: "INIT" | "COMMITTED" | "ABORTED";
    participants: string[];
    acked: Set<string>;
    crashed: boolean;
  }
  const txs = new Map<string, TxRec>();
  const out: string[] = [];

  for (const op of ops) {
    if (op.op === "PREPARE") {
      if (txs.has(op.tx) || op.participants.length === 0) throw new Error("bad PREPARE");
      const allYes = op.participants.every((p) => op.votes[p] === "YES");
      const phase = allYes ? "COMMITTED" : "ABORTED";
      txs.set(op.tx, { phase, participants: [...op.participants], acked: new Set(), crashed: false });
      out.push(`${phase === "COMMITTED" ? "DECIDE_COMMIT" : "DECIDE_ABORT"}:${op.tx}`);
    } else if (op.op === "CRASH") {
      const t = txs.get(op.tx);
      if (!t) throw new Error("unknown tx");
      t.crashed = true;
      out.push(`CRASHED:${op.tx}`);
    } else if (op.op === "RECOVER") {
      const t = txs.get(op.tx);
      if (!t) throw new Error("unknown tx");
      t.crashed = false;
      const pending = t.participants.filter((p) => !t.acked.has(p)).sort();
      out.push(`REPLAY:${op.tx}:${t.phase}:${pending.join(",")}`);
    } else if (op.op === "ACK") {
      const t = txs.get(op.tx);
      if (!t || t.crashed || !t.participants.includes(op.participant)) throw new Error("bad ACK");
      t.acked.add(op.participant);
      if (t.acked.size === t.participants.length) {
        out.push(`DONE:${op.tx}:${t.phase}`);
      } else {
        out.push(`ACKED:${op.tx}:${op.participant}`);
      }
    } else {
      throw new Error("unknown op");
    }
  }
  return out;
}
