interface CronJobSpec {
  jobId: string;
  minuteMask: number[];
  hourMask: number[];
  concurrency: "ALLOW" | "FORBID" | "REPLACE";
  durationMin: number;
}

function planCronExecution(jobs: CronJobSpec[], startMin: number, endMin: number): string[] {
  if (startMin < 0 || endMin < startMin) throw new Error("bad window");
  const mMap = new Map<string, Set<number>>();
  const hMap = new Map<string, Set<number>>();
  for (const j of jobs) {
    if (j.durationMin < 1 || mMap.has(j.jobId)) throw new Error("bad job");
    for (const m of j.minuteMask) if (m < 0 || m > 59) throw new Error("bad min");
    for (const h of j.hourMask) if (h < 0 || h > 23) throw new Error("bad hour");
    mMap.set(j.jobId, new Set(j.minuteMask));
    hMap.set(j.jobId, new Set(j.hourMask));
  }
  const ordered = [...jobs].sort((a, b) => (a.jobId < b.jobId ? -1 : 1));
  const active = new Map<string, number[]>();
  for (const j of ordered) active.set(j.jobId, []);
  const out: string[] = [];
  for (let t = startMin; t <= endMin; t += 1) {
    const mm = t % 60;
    const hh = Math.floor(t / 60) % 24;
    for (const j of ordered) {
      const rem = active.get(j.jobId)!.filter((endT) => endT > t);
      active.set(j.jobId, rem);
      if (!mMap.get(j.jobId)!.has(mm) || !hMap.get(j.jobId)!.has(hh)) continue;
      if (rem.length === 0 || j.concurrency === "ALLOW") {
        rem.push(t + j.durationMin);
        out.push(`RUN:${j.jobId}@${t}`);
      } else if (j.concurrency === "FORBID") {
        out.push(`SKIP:${j.jobId}@${t}`);
      } else if (j.concurrency === "REPLACE") {
        active.set(j.jobId, [t + j.durationMin]);
        out.push(`REPLACE:${j.jobId}@${t}`);
      } else {
        throw new Error("bad concurrency");
      }
    }
  }
  return out;
}
