interface PkgVer {
  ver: number;
  deps: Record<string, { min: number; max: number }>;
}

function solvePkgVersions(
  catalog: Record<string, PkgVer[]>,
  roots: Record<string, { min: number; max: number }>,
): Record<string, number> | null {
  const versionsOf = (p: string): PkgVer[] => catalog[p] || [];
  const chosen = new Map<string, number>();

  const consistent = (): boolean => {
    for (const [pkg, ver] of chosen.entries()) {
      const entry = versionsOf(pkg).find((v) => v.ver === ver);
      if (!entry) return false;
      for (const [dep, req] of Object.entries(entry.deps)) {
        if (chosen.has(dep)) {
          const dv = chosen.get(dep)!;
          if (dv < req.min || dv > req.max) return false;
        }
      }
    }
    return true;
  };

  const nextUnresolved = (): { conflict: boolean; pkg: string | null; min: number; max: number } => {
    const reqs = new Map<string, { min: number; max: number }>();
    for (const [p, b] of Object.entries(roots)) reqs.set(p, { min: b.min, max: b.max });
    for (const [p, ver] of chosen.entries()) {
      const entry = versionsOf(p).find((v) => v.ver === ver)!;
      for (const [dep, b] of Object.entries(entry.deps)) {
        const cur = reqs.get(dep);
        if (!cur) reqs.set(dep, { min: b.min, max: b.max });
        else reqs.set(dep, { min: Math.max(cur.min, b.min), max: Math.min(cur.max, b.max) });
      }
    }
    for (const [dep, b] of reqs.entries()) {
      if (b.min > b.max) return { conflict: true, pkg: null, min: 0, max: 0 };
      if (!chosen.has(dep)) return { conflict: false, pkg: dep, min: b.min, max: b.max };
      const v = chosen.get(dep)!;
      if (v < b.min || v > b.max) return { conflict: true, pkg: null, min: 0, max: 0 };
    }
    return { conflict: false, pkg: null, min: 0, max: 0 };
  };

  const dfs = (): boolean => {
    if (!consistent()) return false;
    const nxt = nextUnresolved();
    if (nxt.conflict) return false;
    if (nxt.pkg === null) return true;
    const cands = versionsOf(nxt.pkg)
      .filter((e) => e.ver >= nxt.min && e.ver <= nxt.max)
      .sort((a, b) => b.ver - a.ver);
    for (const c of cands) {
      chosen.set(nxt.pkg, c.ver);
      if (dfs()) return true;
      chosen.delete(nxt.pkg);
    }
    return false;
  };

  if (!dfs()) return null;
  const out: Record<string, number> = {};
  for (const k of [...chosen.keys()].sort()) out[k] = chosen.get(k)!;
  return out;
}
