type PatchOp =
  | { op: "REMOVE"; key: string }
  | { op: "INSERT"; key: string; before: string | null }
  | { op: "MOVE"; key: string; before: string | null };

function reconcileKeyedList(prevKeys: string[], nextKeys: string[]): PatchOp[] {
  const nextPos = new Map<string, number>();
  for (let i = 0; i < nextKeys.length; i += 1) {
    if (nextPos.has(nextKeys[i])) throw new Error("duplicate next key");
    nextPos.set(nextKeys[i], i);
  }
  const prevSet = new Set(prevKeys);
  if (prevSet.size !== prevKeys.length) throw new Error("duplicate prev key");

  const ops: PatchOp[] = [];
  const surviving: Array<{ key: string; target: number }> = [];
  for (const k of prevKeys) {
    if (!nextPos.has(k)) ops.push({ op: "REMOVE", key: k });
    else surviving.push({ key: k, target: nextPos.get(k)! });
  }

  const n = surviving.length;
  const tails: number[] = [];
  const tailIdx: number[] = [];
  const parent = new Array<number>(n).fill(-1);
  for (let i = 0; i < n; i += 1) {
    const val = surviving[i].target;
    let lo = 0, hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < val) lo = mid + 1;
      else hi = mid;
    }
    tails[lo] = val;
    tailIdx[lo] = i;
    if (lo > 0) parent[i] = tailIdx[lo - 1];
  }
  const anchorKeys = new Set<string>();
  if (n > 0) {
    let cur = tailIdx[tails.length - 1];
    while (cur !== -1) {
      anchorKeys.add(surviving[cur].key);
      cur = parent[cur];
    }
  }

  for (let i = nextKeys.length - 1; i >= 0; i -= 1) {
    const k = nextKeys[i];
    const before = i + 1 < nextKeys.length ? nextKeys[i + 1] : null;
    if (!prevSet.has(k)) ops.push({ op: "INSERT", key: k, before });
    else if (!anchorKeys.has(k)) ops.push({ op: "MOVE", key: k, before });
  }
  return ops;
}
