interface CausalMsg {
  sender: string;
  id: string;
  vc: Record<string, number>;
}

function deliverCausalMessages(nodes: string[], messages: CausalMsg[]): string[] {
  const nodeSet = new Set(nodes);
  const clock: Record<string, number> = {};
  for (const n of nodes) clock[n] = 0;

  for (const m of messages) {
    if (!nodeSet.has(m.sender)) throw new Error("unknown sender");
    for (const n of nodes) {
      if (typeof m.vc[n] !== "number" || m.vc[n] < 0) throw new Error("bad vector clock");
    }
  }

  const remaining = [...messages];
  const out: string[] = [];

  const isEligible = (m: CausalMsg): boolean => {
    if (m.vc[m.sender] !== clock[m.sender] + 1) return false;
    for (const n of nodes) {
      if (n !== m.sender && m.vc[n] > clock[n]) return false;
    }
    return true;
  };

  while (remaining.length > 0) {
    let bestIdx = -1;
    for (let i = 0; i < remaining.length; i += 1) {
      if (!isEligible(remaining[i])) continue;
      if (bestIdx === -1) {
        bestIdx = i;
      } else {
        const a = remaining[i];
        const b = remaining[bestIdx];
        if (a.sender < b.sender || (a.sender === b.sender && a.id < b.id)) {
          bestIdx = i;
        }
      }
    }
    if (bestIdx === -1) break;
    const [picked] = remaining.splice(bestIdx, 1);
    clock[picked.sender] += 1;
    out.push(`DELIVER:${picked.sender}:${picked.id}`);
  }

  remaining.sort((a, b) => (a.sender !== b.sender ? (a.sender < b.sender ? -1 : 1) : a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  for (const m of remaining) out.push(`STUCK:${m.sender}:${m.id}`);
  return out;
}
