interface CssRule {
  selector: string;
  declarations: Record<string, string>;
  important?: boolean;
}

function resolveCssCascade(rules: CssRule[], elementClasses: string[]): Record<string, string> {
  const clsSet = new Set(elementClasses);
  const winners = new Map<string, { imp: number; ids: number; cls: number; tags: number; idx: number; val: string }>();

  const parseSelector = (sel: string): { match: boolean; ids: number; cls: number; tags: number } => {
    if (!sel || /\s/.test(sel)) throw new Error("bad selector");
    let pos = 0;
    let tagOk = true;
    let ids = 0, cls = 0, tags = 0;
    if (sel[0] === "*") {
      pos = 1;
    } else if (/^[a-z]/.test(sel[0])) {
      let end = pos;
      while (end < sel.length && /[a-z0-9_-]/i.test(sel[end])) end += 1;
      const tag = sel.slice(pos, end);
      if (tag !== "div") tagOk = false;
      tags += 1;
      pos = end;
    }
    let idOk = true;
    let clsOk = true;
    while (pos < sel.length) {
      const ch = sel[pos];
      if (ch !== "#" && ch !== ".") throw new Error("bad token in selector");
      pos += 1;
      const start = pos;
      while (pos < sel.length && sel[pos] !== "#" && sel[pos] !== ".") pos += 1;
      if (pos === start) throw new Error("empty identifier");
      const name = sel.slice(start, pos);
      if (ch === "#") {
        ids += 1;
        if (name !== "main") idOk = false;
      } else {
        cls += 1;
        if (!clsSet.has(name)) clsOk = false;
      }
    }
    return { match: tagOk && idOk && clsOk, ids, cls, tags };
  };

  const beats = (
    a: { imp: number; ids: number; cls: number; tags: number; idx: number },
    b: { imp: number; ids: number; cls: number; tags: number; idx: number },
  ): boolean => {
    if (a.imp !== b.imp) return a.imp > b.imp;
    if (a.ids !== b.ids) return a.ids > b.ids;
    if (a.cls !== b.cls) return a.cls > b.cls;
    if (a.tags !== b.tags) return a.tags > b.tags;
    return a.idx > b.idx;
  };

  for (let i = 0; i < rules.length; i += 1) {
    const r = rules[i];
    const spec = parseSelector(r.selector);
    if (!spec.match) continue;
    const imp = r.important ? 1 : 0;
    for (const [prop, val] of Object.entries(r.declarations)) {
      const cand = { imp, ids: spec.ids, cls: spec.cls, tags: spec.tags, idx: i, val };
      const cur = winners.get(prop);
      if (!cur || beats(cand, cur)) winners.set(prop, cand);
    }
  }

  const out: Record<string, string> = {};
  for (const k of [...winners.keys()].sort()) out[k] = winners.get(k)!.val;
  return out;
}
