std::vector<std::string> runBuddyPool(
    int orderMax,
    const std::vector<std::tuple<std::string, int, int>>& ops) {
    if (orderMax < 1 || orderMax > 20) throw std::invalid_argument("bad orderMax");
    std::vector<std::set<int>> freeLists(orderMax + 1);
    freeLists[orderMax].insert(0);
    std::map<int, std::pair<int, int>> live;
    std::vector<std::string> out;
    for (const auto& [op, id, sz] : ops) {
        if (op == "ALLOC") {
            if (sz <= 0 || live.count(id)) throw std::invalid_argument("bad alloc");
            int need = 0;
            while ((1 << need) < sz) ++need;
            int k = need;
            while (k <= orderMax && freeLists[k].empty()) ++k;
            if (k > orderMax) {
                out.push_back("OOM:" + std::to_string(id));
                continue;
            }
            int addr = *freeLists[k].begin();
            freeLists[k].erase(freeLists[k].begin());
            while (k > need) {
                --k;
                freeLists[k].insert(addr + (1 << k));
            }
            live[id] = {addr, need};
            out.push_back("ALLOC:" + std::to_string(id) + "@" + std::to_string(addr) + ":" + std::to_string(1 << need));
        } else if (op == "FREE") {
            auto it = live.find(id);
            if (it == live.end()) throw std::invalid_argument("unknown block");
            auto [addr, order] = it->second;
            live.erase(it);
            while (order < orderMax) {
                int buddy = addr ^ (1 << order);
                auto bit = freeLists[order].find(buddy);
                if (bit == freeLists[order].end()) break;
                freeLists[order].erase(bit);
                addr = std::min(addr, buddy);
                ++order;
            }
            freeLists[order].insert(addr);
            out.push_back("FREE:" + std::to_string(id) + ":" + std::to_string(order));
        } else {
            throw std::invalid_argument("unknown op");
        }
    }
    return out;
}
