std::vector<int> advanceRaftCommitCpp(
    int currentTerm,
    int commitIndex,
    const std::vector<std::pair<int, int>>& log,
    const std::vector<std::tuple<int, int, int>>& peers,
    const std::vector<std::tuple<int, bool, int>>& acks) {
    if (currentTerm < 0 || commitIndex < 0) throw std::invalid_argument("bad raft state");
    std::map<int, int> termAt;
    int prevIdx = 0;
    for (auto [t, idx] : log) {
        if (idx != prevIdx + 1) throw std::invalid_argument("non-contiguous log");
        termAt[idx] = t;
        prevIdx = idx;
    }
    struct PState { int id; int matchIdx; int nextIdx; };
    std::vector<PState> ps;
    std::map<int, size_t> pos;
    for (auto [pid, mi, ni] : peers) {
        pos[pid] = ps.size();
        ps.push_back({pid, mi, ni});
    }
    for (auto [pid, ok, mi] : acks) {
        auto it = pos.find(pid);
        if (it == pos.end()) throw std::invalid_argument("unknown peer");
        auto& p = ps[it->second];
        if (ok) {
            if (mi > prevIdx) throw std::invalid_argument("ack past log");
            p.matchIdx = std::max(p.matchIdx, mi);
            p.nextIdx = p.matchIdx + 1;
        } else {
            p.nextIdx = std::max(1, std::min(p.nextIdx - 1, mi + 1));
        }
    }
    int quorum = ((int)ps.size() + 1) / 2 + 1;
    int nextCommit = commitIndex;
    for (int n = prevIdx; n > commitIndex; --n) {
        if (termAt[n] != currentTerm) continue;
        int cnt = 1;
        for (const auto& p : ps) if (p.matchIdx >= n) ++cnt;
        if (cnt >= quorum) { nextCommit = n; break; }
    }
    std::vector<int> out = {nextCommit};
    for (const auto& p : ps) {
        out.push_back(p.matchIdx);
        out.push_back(p.nextIdx);
    }
    return out;
}
