std::vector<std::string> runBTreeOrder4(const std::vector<std::tuple<std::string, int, int>>& ops) {
    struct Node {
        bool leaf = true;
        std::vector<int> keys;
        std::vector<Node*> ch;
        ~Node() { for (auto* p : ch) delete p; }
    };
    Node* root = new Node();
    auto split = [](Node* parent, int idx) {
        Node* child = parent->ch[idx];
        Node* right = new Node();
        right->leaf = child->leaf;
        int mid = child->keys[1];
        right->keys = {child->keys[2]};
        child->keys.resize(1);
        if (!child->leaf) {
            right->ch = {child->ch[2], child->ch[3]};
            child->ch.resize(2);
        }
        parent->keys.insert(parent->keys.begin() + idx, mid);
        parent->ch.insert(parent->ch.begin() + idx + 1, right);
    };
    auto contains = [](auto& self, Node* n, int k) -> bool {
        size_t i = 0;
        while (i < n->keys.size() && k > n->keys[i]) ++i;
        if (i < n->keys.size() && n->keys[i] == k) return true;
        return n->leaf ? false : self(self, n->ch[i], k);
    };
    auto insertNonFull = [&](auto& self, Node* n, int k) -> void {
        int i = (int)n->keys.size() - 1;
        if (n->leaf) {
            while (i >= 0 && n->keys[i] > k) --i;
            n->keys.insert(n->keys.begin() + i + 1, k);
            return;
        }
        while (i >= 0 && n->keys[i] > k) --i;
        int ci = i + 1;
        if (n->ch[ci]->keys.size() == 3) {
            split(n, ci);
            if (k > n->keys[ci]) ++ci;
        }
        self(self, n->ch[ci], k);
    };
    auto height = [](auto& self, Node* n) -> int {
        return n->leaf ? 1 : 1 + self(self, n->ch[0]);
    };
    std::vector<std::string> out;
    for (const auto& [op, a, b] : ops) {
        if (op == "PUT") {
            if (contains(contains, root, a)) {
                out.push_back("DUP");
                continue;
            }
            if (root->keys.size() == 3) {
                Node* s = new Node();
                s->leaf = false;
                s->ch.push_back(root);
                split(s, 0);
                root = s;
            }
            insertNonFull(insertNonFull, root, a);
            out.push_back("OK:H" + std::to_string(height(height, root)));
        } else if (op == "GET") {
            out.push_back(contains(contains, root, a) ? "HIT" : "MISS");
        } else if (op == "RANGE") {
            std::string acc;
            auto walk = [&](auto& self, Node* n) -> void {
                for (size_t i = 0; i < n->keys.size(); ++i) {
                    if (!n->leaf) self(self, n->ch[i]);
                    if (n->keys[i] >= a && n->keys[i] <= b) {
                        if (!acc.empty()) acc += ',';
                        acc += std::to_string(n->keys[i]);
                    }
                }
                if (!n->leaf) self(self, n->ch[n->keys.size()]);
            };
            walk(walk, root);
            out.push_back(acc);
        } else {
            delete root;
            throw std::invalid_argument("unknown op");
        }
    }
    delete root;
    return out;
}
