std::vector<std::string> shapeQosTraffic(
    long long rootRate, long long rootBurst,
    const std::vector<std::tuple<std::string, long long, long long>>& classes,
    const std::vector<std::tuple<std::string, std::string, long long>>& events) {
    if (rootRate < 0 || rootBurst < 0) throw std::invalid_argument("bad root");
    long long rootTokens = rootBurst;
    struct Cls { long long rate, burst, tokens; };
    std::map<std::string, Cls> cmap;
    for (const auto& [cid, r, b] : classes) {
        if (r < 0 || b < 0 || cmap.count(cid)) throw std::invalid_argument("bad class");
        cmap[cid] = {r, b, b};
    }
    std::vector<std::string> out;
    for (const auto& [op, cid, val] : events) {
        if (op == "TICK") {
            if (val < 0) throw std::invalid_argument("negative dt");
            rootTokens = std::min(rootBurst, rootTokens + val * rootRate);
            for (auto& [_, c] : cmap) c.tokens = std::min(c.burst, c.tokens + val * c.rate);
        } else if (op == "SEND") {
            if (val <= 0) throw std::invalid_argument("bad bytes");
            auto it = cmap.find(cid);
            if (it == cmap.end()) throw std::invalid_argument("unknown class");
            auto& c = it->second;
            if (c.tokens >= val) {
                c.tokens -= val;
                out.push_back("PASS:" + cid);
            } else if (c.tokens + rootTokens >= val) {
                long long bor = val - c.tokens;
                c.tokens = 0;
                rootTokens -= bor;
                out.push_back("BORROW:" + cid + ":" + std::to_string(bor));
            } else {
                out.push_back("DROP:" + cid);
            }
        } else {
            throw std::invalid_argument("unknown op");
        }
    }
    return out;
}
