long long computeSlaFinish(
    long long startMin, long long slaMinutes,
    int workStartMin, int workEndMin,
    const std::vector<long long>& holidays) {
    if (startMin < 0 || slaMinutes < 0 || workStartMin < 0 || workEndMin > 1440 || workStartMin >= workEndMin) {
        throw std::invalid_argument("bad SLA config");
    }
    std::unordered_set<long long> hset(holidays.begin(), holidays.end());
    auto isWorkDay = [&](long long d) {
        return (d % 7) < 5 && !hset.count(d);
    };
    long long curDay = startMin / 1440;
    int curTod = (int)(startMin % 1440);
    long long rem = slaMinutes;
    while (true) {
        if (!isWorkDay(curDay) || curTod >= workEndMin) {
            ++curDay;
            curTod = workStartMin;
            continue;
        }
        if (curTod < workStartMin) curTod = workStartMin;
        if (rem == 0) return curDay * 1440 + curTod;
        long long avail = workEndMin - curTod;
        if (rem <= avail) return curDay * 1440 + curTod + rem;
        rem -= avail;
        ++curDay;
        curTod = workStartMin;
    }
}
