                    atom = self(self);
                    if (pos >= pattern.size() || pattern[pos++] != ')') throw std::invalid_argument("missing )");
                } else if (c == '|' || c == '*' || c == '+' || c == '?' || c == ')') {
                    throw std::invalid_argument("bad syntax");
                } else {
                    atom = Node{0, c, 0, {}};
