            std::set<size_t> cur = idx;
            for (const auto& k : n.kids) {
                cur = self(self, k, cur);
                if (cur.empty()) break;
            }
            return cur;
        }
        if (n.kind == 2) {
            std::set<size_t> nxt;
            for (const auto& b : n.kids) for (size_t i : self(self, b, idx)) nxt.insert(i);
            return nxt;
        }
        if (n.q == '?') {
            std::set<size_t> nxt = idx;
            for (size_t i : self(self, n.kids[0], idx)) nxt.insert(i);
            return nxt;
        }
        std::set<size_t> res;
        std::set<size_t> frontier = (n.q == '*') ? idx : self(self, n.kids[0], idx);
        res.insert(frontier.begin(), frontier.end());
        while (!frontier.empty()) {
            std::set<size_t> nxt;
            for (size_t i : self(self, n.kids[0], frontier)) {
                if (!res.count(i)) { res.insert(i); nxt.insert(i); }
            }
            frontier = std::move(nxt);
        }
        return res;
    };
    return step(step, ast, {0}).count(text.size()) > 0;
}
