std::vector<std::string> deliverVectorClockMsgs(
    const std::vector<std::string>& nodes,
    const std::vector<std::tuple<std::string, std::string, std::vector<int>>>& msgs) {
    std::map<std::string, size_t> nodeIdx;
    for (size_t i = 0; i < nodes.size(); ++i) nodeIdx[nodes[i]] = i;
    for (const auto& [snd, id, vc] : msgs) {
        if (!nodeIdx.count(snd) || vc.size() != nodes.size()) throw std::invalid_argument("bad msg");
        for (int v : vc) if (v < 0) throw std::invalid_argument("neg vc");
    }
    std::vector<int> clock(nodes.size(), 0);
    std::vector<bool> used(msgs.size(), false);
    std::vector<std::string> out;
    auto eligible = [&](size_t idx) {
        const auto& [snd, id, vc] = msgs[idx];
        size_t s = nodeIdx[snd];
        if (vc[s] != clock[s] + 1) return false;
        for (size_t k = 0; k < nodes.size(); ++k) if (k != s && vc[k] > clock[k]) return false;
        return true;
    };
    while (true) {
        int best = -1;
        for (size_t i = 0; i < msgs.size(); ++i) {
            if (used[i] || !eligible(i)) continue;
            if (best == -1) best = (int)i;
            else {
                const auto& a = msgs[i];
                const auto& b = msgs[best];
                if (std::tie(std::get<0>(a), std::get<1>(a)) < std::tie(std::get<0>(b), std::get<1>(b))) best = (int)i;
            }
        }
        if (best == -1) break;
        used[best] = true;
        const auto& [snd, id, vc] = msgs[best];
        clock[nodeIdx[snd]] += 1;
        out.push_back("DELIVER:" + snd + ":" + id);
    }
    std::vector<std::pair<std::string, std::string>> stuck;
    for (size_t i = 0; i < msgs.size(); ++i) {
        if (!used[i]) stuck.push_back({std::get<0>(msgs[i]), std::get<1>(msgs[i])});
    }
    std::sort(stuck.begin(), stuck.end());
    for (const auto& [snd, id] : stuck) out.push_back("STUCK:" + snd + ":" + id);
    return out;
}
