std::vector<std::string> runMvccTransactions(
    const std::vector<std::tuple<std::string, std::string, std::string, long long>>& ops) {
    struct Ver { long long ts; long long val; };
    struct Tx { long long startTs; std::map<std::string, long long> writes; bool closed = false; };
    std::map<std::string, std::vector<Ver>> store;
    std::map<std::string, Tx> txs;
    std::vector<std::string> out;
    for (const auto& [op, tx, key, val] : ops) {
        if (op == "BEGIN") {
            if (txs.count(tx) || val < 0) throw std::invalid_argument("bad BEGIN");
            txs[tx] = {val, {}, false};
            out.push_back("BEGIN:" + tx + "@" + std::to_string(val));
        } else if (op == "READ") {
            auto it = txs.find(tx);
            if (it == txs.end() || it->second.closed) throw std::invalid_argument("inactive tx");
            auto wit = it->second.writes.find(key);
            if (wit != it->second.writes.end()) {
                out.push_back("VAL:" + std::to_string(wit->second));
            } else {
                const auto& vers = store[key];
                bool found = false;
                long long v = 0;
                for (auto rit = vers.rbegin(); rit != vers.rend(); ++rit) {
                    if (rit->ts <= it->second.startTs) { found = true; v = rit->val; break; }
                }
                out.push_back(found ? "VAL:" + std::to_string(v) : "NULL");
            }
        } else if (op == "WRITE") {
            auto it = txs.find(tx);
            if (it == txs.end() || it->second.closed) throw std::invalid_argument("inactive tx");
            it->second.writes[key] = val;
            out.push_back("STAGE:" + tx + ":" + key);
        } else if (op == "ABORT") {
            auto it = txs.find(tx);
            if (it == txs.end() || it->second.closed) throw std::invalid_argument("inactive tx");
            it->second.closed = true;
            out.push_back("ABORT:" + tx);
        } else if (op == "COMMIT") {
            auto it = txs.find(tx);
            if (it == txs.end() || it->second.closed || val <= it->second.startTs) throw std::invalid_argument("bad COMMIT");
            bool conflict = false;
            for (const auto& [k, _] : it->second.writes) {
                const auto& vers = store[k];
                if (!vers.empty() && vers.back().ts > it->second.startTs) { conflict = true; break; }
            }
            it->second.closed = true;
            if (conflict) {
                out.push_back("CONFLICT:" + tx);
            } else {
                for (const auto& [k, wv] : it->second.writes) store[k].push_back({val, wv});
                out.push_back("COMMIT:" + tx + "@" + std::to_string(val));
            }
        } else {
            throw std::invalid_argument("unknown op");
        }
    }
    return out;
}
