long long minPaddingCost(const std::vector<int>& recordSizes, int maxChunkLen, long long chunkOverhead) {
    if (maxChunkLen < 1 || chunkOverhead < 0) throw std::invalid_argument("bad params");
    int n = (int)recordSizes.size();
    std::vector<long long> pref(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        if (recordSizes[i] < 0) throw std::invalid_argument("neg size");
        pref[i + 1] = pref[i] + recordSizes[i];
    }
    const long long INF = (1LL << 60);
    std::vector<long long> dp(n + 1, INF);
    dp[0] = 0;
    for (int i = 1; i <= n; ++i) {
        int mx = 0;
        for (int j = i; j >= 1 && i - j + 1 <= maxChunkLen; --j) {
            mx = std::max(mx, recordSizes[j - 1]);
            long long len = i - j + 1;
            long long pad = 1LL * mx * len - (pref[i] - pref[j - 1]);
            dp[i] = std::min(dp[i], dp[j - 1] + chunkOverhead + pad);
        }
    }
    return dp[n];
}
