std::vector<long long> computeDagSlack(
    int n,
    const std::vector<long long>& dur,
    const std::vector<std::pair<int, int>>& edges) {
    if (n < 0 || (int)dur.size() != n) throw std::invalid_argument("bad args");
    for (long long d : dur) if (d < 0) throw std::invalid_argument("neg dur");
    std::vector<std::vector<int>> adj(n), rev(n);
    std::vector<int> indeg(n, 0);
    for (auto [u, v] : edges) {
        if (u < 0 || u >= n || v < 0 || v >= n) throw std::invalid_argument("bad edge");
        adj[u].push_back(v);
        rev[v].push_back(u);
        indeg[v]++;
    }
    std::queue<int> q;
    for (int i = 0; i < n; ++i) if (indeg[i] == 0) q.push(i);
    std::vector<int> topo;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        topo.push_back(u);
        for (int v : adj[u]) if (--indeg[v] == 0) q.push(v);
    }
    if ((int)topo.size() != n) throw std::invalid_argument("cycle in dag");
    std::vector<long long> es(n, 0), ef(n, 0);
    long long makespan = 0;
    for (int u : topo) {
        for (int p : rev[u]) es[u] = std::max(es[u], ef[p]);
        ef[u] = es[u] + dur[u];
        makespan = std::max(makespan, ef[u]);
    }
    std::vector<long long> lf(n, makespan), ls(n, 0), slack(n, 0);
    for (int i = n - 1; i >= 0; --i) {
        int u = topo[i];
        for (int v : adj[u]) lf[u] = std::min(lf[u], ls[v]);
        ls[u] = lf[u] - dur[u];
        slack[u] = ls[u] - es[u];
    }
    return slack;
}
