def simulate_buddy_allocator(order_max, ops):
    if not isinstance(order_max, int) or order_max < 1 or order_max > 20:
        raise ValueError("bad order_max")
    free_lists = [set() for _ in range(order_max + 1)]
    free_lists[order_max].add(0)
    live = {}
    out = []
    for op in ops:
        kind = op[0]
        if kind == "ALLOC":
            _, bid, sz = op
            if sz <= 0 or bid in live:
                raise ValueError("bad alloc")
            need = 0
            while (1 << need) < sz:
                need += 1
            k = need
            while k <= order_max and not free_lists[k]:
                k += 1
            if k > order_max:
                out.append(f"OOM:{bid}")
                continue
            addr = min(free_lists[k])
            free_lists[k].remove(addr)
            while k > need:
                k -= 1
                free_lists[k].add(addr + (1 << k))
            live[bid] = (addr, need)
            out.append(f"ALLOC:{bid}@{addr}:{1 << need}")
        elif kind == "FREE":
            _, bid = op
            if bid not in live:
                raise ValueError("unknown block")
            addr, order = live.pop(bid)
            while order < order_max:
                buddy = addr ^ (1 << order)
                if buddy not in free_lists[order]:
                    break
                free_lists[order].remove(buddy)
                addr = min(addr, buddy)
                order += 1
            free_lists[order].add(addr)
            out.append(f"FREE:{bid}:{order}")
        else:
            raise ValueError("unknown op")
    return out
