def advance_raft_commit(current_term, commit_index, log, peers, acks):
    if current_term < 0 or commit_index < 0:
        raise ValueError("negative raft state")
    term_at = {}
    prev_idx = 0
    for entry in log:
        if entry["index"] != prev_idx + 1:
            raise ValueError("non-contiguous log")
        term_at[entry["index"]] = entry["term"]
        prev_idx = entry["index"]
    peer_map = {}
    order = []
    for p in peers:
        pid = p["id"]
        if pid in peer_map:
            raise ValueError("duplicate peer")
        peer_map[pid] = dict(p)
        order.append(pid)
    for ack in acks:
        pid = ack["peer"]
        if pid not in peer_map:
            raise ValueError("unknown peer")
        p = peer_map[pid]
        if ack["success"]:
            if ack["match_index"] > prev_idx:
                raise ValueError("ack past leader log")
            p["match_index"] = max(p["match_index"], ack["match_index"])
            p["next_index"] = p["match_index"] + 1
        else:
            p["next_index"] = max(1, min(p["next_index"] - 1, ack["match_index"] + 1))
    updated = [peer_map[pid] for pid in order]
    quorum = (len(updated) + 1) // 2 + 1
    next_commit = commit_index
    for n in range(prev_idx, commit_index, -1):
        if term_at[n] != current_term:
            continue
        cnt = 1 + sum(1 for p in updated if p["match_index"] >= n)
        if cnt >= quorum:
            next_commit = n
            break
    return {"commit_index": next_commit, "peers": updated}
