def simulate_order4_btree(ops):
    class Node:
        def __init__(self, leaf=True):
            self.leaf = leaf
            self.keys = []
            self.ch = []

    root = Node(True)

    def split_child(parent, idx):
        child = parent.ch[idx]
        right = Node(child.leaf)
        mid = child.keys[1]
        right.keys = child.keys[2:]
        child.keys = child.keys[:1]
        if not child.leaf:
            right.ch = child.ch[2:]
            child.ch = child.ch[:2]
        parent.keys.insert(idx, mid)
        parent.ch.insert(idx + 1, right)

    def contains(node, k):
        i = 0
        while i < len(node.keys) and k > node.keys[i]:
            i += 1
        if i < len(node.keys) and node.keys[i] == k:
            return True
        return False if node.leaf else contains(node.ch[i], k)

    def insert_nonfull(node, k):
        i = len(node.keys) - 1
        if node.leaf:
            while i >= 0 and node.keys[i] > k:
                i -= 1
            node.keys.insert(i + 1, k)
            return
