            i -= 1
        ci = i + 1
        if len(node.ch[ci].keys) == 3:
            split_child(node, ci)
            if k > node.keys[ci]:
                ci += 1
        insert_nonfull(node.ch[ci], k)

    def height(node):
        return 1 if node.leaf else 1 + height(node.ch[0])

    out = []
    for op in ops:
        kind = op[0]
        if kind == "PUT":
            k = op[1]
            if contains(root, k):
                out.append("DUP")
                continue
            if len(root.keys) == 3:
                s = Node(False)
                s.ch.append(root)
                split_child(s, 0)
                root = s
            insert_nonfull(root, k)
            out.append(f"OK:H{height(root)}")
        elif kind == "GET":
            out.append("HIT" if contains(root, op[1]) else "MISS")
        elif kind == "RANGE":
            _, lo, hi = op
            acc = []
            def walk(n):
                for idx, kv in enumerate(n.keys):
                    if not n.leaf:
                        walk(n.ch[idx])
