def shape_qos_traffic(root_rate, root_burst, classes, events):
    if root_rate < 0 or root_burst < 0:
        raise ValueError("bad root")
    root_tokens = root_burst
    cmap = {}
    for c in classes:
        if c["rate"] < 0 or c["burst"] < 0 or c["id"] in cmap:
            raise ValueError("bad class")
        cmap[c["id"]] = {"rate": c["rate"], "burst": c["burst"], "tokens": c["burst"]}
    out = []
    for ev in events:
        if ev[0] == "TICK":
            dt = ev[1]
            if dt < 0:
                raise ValueError("negative dt")
            root_tokens = min(root_burst, root_tokens + dt * root_rate)
            for st in cmap.values():
                st["tokens"] = min(st["burst"], st["tokens"] + dt * st["rate"])
        elif ev[0] == "SEND":
            _, cid, b = ev
            if b <= 0 or cid not in cmap:
                raise ValueError("bad send")
            st = cmap[cid]
            if st["tokens"] >= b:
                st["tokens"] -= b
                out.append(f"PASS:{cid}")
            elif st["tokens"] + root_tokens >= b:
                bor = b - st["tokens"]
                st["tokens"] = 0
                root_tokens -= bor
                out.append(f"BORROW:{cid}:{bor}")
            else:
                out.append(f"DROP:{cid}")
        else:
            raise ValueError("unknown op")
    return out
