def match_mini_regex(pattern, text):
    pos = 0

    def parse_expr():
        branches = [parse_seq()]
        while pos < len(pattern) and pattern[pos] == "|":
            _advance()
            branches.append(parse_seq())
        return branches[0] if len(branches) == 1 else ("alt", branches)

    def _advance():
        nonlocal pos
        pos += 1

    def parse_seq():
        items = []
        while pos < len(pattern) and pattern[pos] not in "|)":
            items.append(parse_quant())
        return items[0] if len(items) == 1 else ("seq", items)

    def parse_quant():
        atom = parse_atom()
        if pos < len(pattern) and pattern[pos] in "*+?":
            q = pattern[pos]
            _advance()
            return ("quant", q, atom)
        return atom

    def parse_atom():
        if pos >= len(pattern):
            raise ValueError("unexpected end")
        ch = pattern[pos]
        _advance()
        if ch == "(":
            inner = parse_expr()
            if pos >= len(pattern) or pattern[pos] != ")":
                raise ValueError("missing )")
            _advance()
            return inner
        if ch in "|*+?)":
            raise ValueError("bad syntax")
        return ("lit", ch)

    ast = parse_expr()
    if pos != len(pattern):
        raise ValueError("trailing )")

    def match_from(node, idx_set):
        kind = node[0]
        if kind == "lit":
            ch = node[1]
            return {i + 1 for i in idx_set if i < len(text) and (ch == "." or ch == text[i])}
        if kind == "seq":
            cur = idx_set
            for item in node[1]:
                cur = match_from(item, cur)
                if not cur:
                    break
            return cur
        if kind == "alt":
            nxt = set()
            for br in node[1]:
                nxt |= match_from(br, idx_set)
            return nxt
        q, sub = node[1], node[2]
        if q == "?":
            return set(idx_set) | match_from(sub, idx_set)
        res = set()
        frontier = set(idx_set) if q == "*" else match_from(sub, idx_set)
        res |= frontier
        while frontier:
            nxt = match_from(sub, frontier) - res
            res |= nxt
            frontier = nxt
        return res

    return len(text) in match_from(ast, {0})
