```python
def deliver_vector_clock_msgs(nodes, messages):
    node_set = set(nodes)
    clock = {n: 0 for n in nodes}
    for m in messages:
        if m["sender"] not in node_set:
            raise ValueError("unknown sender")
        vc = m["vc"]
        for n in nodes:
            if n not in vc or vc[n] < 0:
                raise ValueError("bad vc")
    remaining = list(messages)
    out = []

    def eligible(m):
        s = m["sender"]
        vc = m["vc"]
        if vc[s] != clock[s] + 1:
            return False
        return all(vc[n] <= clock[n] for n in nodes if n != s)

    while remaining:
        cands = [(i, m) for i, m in enumerate(remaining) if eligible(m)]
        if not cands:
            break
        best_i, picked = min(cands, key=lambda im: (im[1]["sender"], im[1]["id"]))
        remaining.pop(best_i)
        clock[picked["sender"]] += 1
        out.append(f"DELIVER:{picked['sender']}:{picked['id']}")

    remaining.sort(key=lambda m: (m["sender"], m["id"]))
    for m in remaining:
        out.append(f"STUCK:{m['sender']}:{m['id']}")
    return out
