def run_mvcc_ledger(ops):
    store = {}
    txs = {}
    out = []

    def visible(key, snap_ts):
        for ts, val in reversed(store.get(key, [])):
            if ts <= snap_ts:
                return val
        return None

    for ev in ops:
        op = ev[0]
        if op == "BEGIN":
            _, tx, ts = ev
            if tx in txs or ts < 0:
                raise ValueError("bad BEGIN")
            txs[tx] = {"start": ts, "writes": {}, "closed": False}
            out.append(f"BEGIN:{tx}@{ts}")
        elif op == "READ":
            _, tx, key = ev
            st = txs.get(tx)
            if not st or st["closed"]:
                raise ValueError("inactive tx")
            if key in st["writes"]:
                out.append(f"VAL:{st['writes'][key]}")
            else:
                v = visible(key, st["start"])
                out.append("NULL" if v is None else f"VAL:{v}")
        elif op == "WRITE":
            _, tx, key, val = ev
            st = txs.get(tx)
            if not st or st["closed"]:
                raise ValueError("inactive tx")
            st["writes"][key] = val
            out.append(f"STAGE:{tx}:{key}")
        elif op == "ABORT":
            _, tx = ev
            st = txs.get(tx)
            if not st or st["closed"]:
                raise ValueError("inactive tx")
            st["closed"] = True
            out.append(f"ABORT:{tx}")
        elif op == "COMMIT":
            _, tx, ts = ev
            st = txs.get(tx)
            if not st or st["closed"] or ts <= st["start"]:
                raise ValueError("bad COMMIT")
            conflict = any(store.get(k) and store[k][-1][0] > st["start"] for k in st["writes"])
            st["closed"] = True
            if conflict:
                out.append(f"CONFLICT:{tx}")
            else:
                for k, v in st["writes"].items():
                    store.setdefault(k, []).append((ts, v))
                out.append(f"COMMIT:{tx}@{ts}")
        else:
            raise ValueError("unknown op")
    return out
