def min_chunk_padding_cost(record_sizes, max_chunk_len, chunk_overhead):
    if max_chunk_len < 1 or chunk_overhead < 0:
        raise ValueError("bad params")
    n = len(record_sizes)
    pref = [0] * (n + 1)
    for i, s in enumerate(record_sizes):
        if s < 0:
            raise ValueError("negative size")
        pref[i + 1] = pref[i] + s
    inf = 10**18
    dp = [inf] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        mx = 0
        start = max(1, i - max_chunk_len + 1)
        for j in range(i, start - 1, -1):
            if record_sizes[j - 1] > mx:
                mx = record_sizes[j - 1]
            pad = mx * (i - j + 1) - (pref[i] - pref[j - 1])
            cand = dp[j - 1] + chunk_overhead + pad
            if cand < dp[i]:
                dp[i] = cand
    return dp[n]
