def compute_dag_slack(n, dur, edges):
    from collections import deque
    if n < 0 or len(dur) != n or any(d < 0 for d in dur):
        raise ValueError("bad dag args")
    adj = [[] for _ in range(n)]
    rev = [[] for _ in range(n)]
    indeg = [0] * n
    for u, v in edges:
        if not (0 <= u < n and 0 <= v < n):
            raise ValueError("bad edge")
        adj[u].append(v)
        rev[v].append(u)
        indeg[v] += 1
    q = deque(i for i in range(n) if indeg[i] == 0)
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    if len(topo) != n:
        raise ValueError("cycle detected")
    es = [0] * n
    ef = [0] * n
    for u in topo:
        if rev[u]:
            es[u] = max(ef[p] for p in rev[u])
        ef[u] = es[u] + dur[u]
    makespan = max(ef) if n else 0
    lf = [makespan] * n
    ls = [0] * n
    for u in reversed(topo):
        if adj[u]:
            lf[u] = min(ls[v] for v in adj[u])
        ls[u] = lf[u] - dur[u]
    return [ls[i] - es[i] for i in range(n)]
