def diff_keyed_lists(prev_keys, next_keys):
    next_pos = {}
    for i, k in enumerate(next_keys):
        if k in next_pos:
            raise ValueError("duplicate next key")
        next_pos[k] = i
    prev_set = set(prev_keys)
    if len(prev_set) != len(prev_keys):
        raise ValueError("duplicate prev key")

    ops = []
    surviving = []
    for k in prev_keys:
        if k not in next_pos:
            ops.append({"op": "REMOVE", "key": k})
        else:
            surviving.append((k, next_pos[k]))

    import bisect
    n = len(surviving)
    tails = []
    tail_idx = []
    parent = [-1] * n
    for i, (_, val) in enumerate(surviving):
        lo = bisect.bisect_left(tails, val)
        if lo == len(tails):
            tails.append(val)
            tail_idx.append(i)
        else:
            tails[lo] = val
            tail_idx[lo] = i
        if lo > 0:
            parent[i] = tail_idx[lo - 1]
    anchors = set()
    if n > 0:
        cur = tail_idx[-1]
        while cur != -1:
            anchors.add(surviving[cur][0])
            cur = parent[cur]

    for i in range(len(next_keys) - 1, -1, -1):
        k = next_keys[i]
        before = next_keys[i + 1] if i + 1 < len(next_keys) else None
        if k not in prev_set:
            ops.append({"op": "INSERT", "key": k, "before": before})
        elif k not in anchors:
            ops.append({"op": "MOVE", "key": k, "before": before})
    return ops
