def simulate_two_phase_commit(ops):
    txs = {}
    out = []
    for ev in ops:
        kind = ev[0]
        if kind == "PREPARE":
            _, tx, participants, votes = ev
            if tx in txs or not participants:
                raise ValueError("bad PREPARE")
            phase = "COMMITTED" if all(votes.get(p) == "YES" for p in participants) else "ABORTED"
            txs[tx] = {"phase": phase, "parts": list(participants), "acked": set(), "crashed": False}
            out.append(f"{'DECIDE_COMMIT' if phase == 'COMMITTED' else 'DECIDE_ABORT'}:{tx}")
        elif kind == "CRASH":
            _, tx = ev
            if tx not in txs:
                raise ValueError("unknown tx")
            txs[tx]["crashed"] = True
            out.append(f"CRASHED:{tx}")
        elif kind == "RECOVER":
            _, tx = ev
            if tx not in txs:
                raise ValueError("unknown tx")
            t = txs[tx]
            t["crashed"] = False
            pending = sorted(p for p in t["parts"] if p not in t["acked"])
            out.append(f"REPLAY:{tx}:{t['phase']}:{','.join(pending)}")
        elif kind == "ACK":
            _, tx, p = ev
            t = txs.get(tx)
            if not t or t["crashed"] or p not in t["parts"]:
                raise ValueError("bad ACK")
            t["acked"].add(p)
            if len(t["acked"]) == len(t["parts"]):
                out.append(f"DONE:{tx}:{t['phase']}")
            else:
                out.append(f"ACKED:{tx}:{p}")
        else:
            raise ValueError("unknown op")
    return out
