import sys

lines = sys.stdin.read().splitlines()
if lines:
    q = int(lines[0])
    out = []
    for k in range(1, 1 + q):
        pat, text = lines[k].split("\t", 1) if "\t" in lines[k] else (lines[k], "")
        pos = 0
        def parse_expr():
            branches = [parse_seq()]
            while pos < len(pat) and pat[pos] == "|":
                adv()
                branches.append(parse_seq())
            return branches[0] if len(branches) == 1 else ("alt", branches)
        def adv():
            global pos
            pos += 1
        def parse_seq():
            items = []
            while pos < len(pat) and pat[pos] not in "|)":
                items.append(parse_quant())
            return items[0] if len(items) == 1 else ("seq", items)
        def parse_quant():
            atom = parse_atom()
            if pos < len(pat) and pat[pos] in "*+?":
                qch = pat[pos]; adv()
                return ("quant", qch, atom)
            return atom
        def parse_atom():
            ch = pat[pos]; adv()
            if ch == "(":
                inner = parse_expr()
                adv()
                return inner
            return ("lit", ch)
        ast = parse_expr()
        def step(node, idxs):
            kind = node[0]
            if kind == "lit":
                ch = node[1]
                return {i + 1 for i in idxs if i < len(text) and (ch == "." or ch == text[i])}
            if kind == "seq":
                cur = idxs
                for it in node[1]:
                    cur = step(it, cur)
                    if not cur: break
                return cur
            if kind == "alt":
                nxt = set()
                for br in node[1]: nxt |= step(br, idxs)
                return nxt
            qch, sub = node[1], node[2]
            if qch == "?": return set(idxs) | step(sub, idxs)
            res = set()
            fr = set(idxs) if qch == "*" else step(sub, idxs)
            res |= fr
            while fr:
                nxt = step(sub, fr) - res
                res |= nxt
                fr = nxt
            return res
        out.append("YES" if len(text) in step(ast, {0}) else "NO")
    sys.stdout.write("\n".join(out) + "\n")
