import sys

lines = [l.split() for l in sys.stdin.read().splitlines() if l.strip()]
if lines:
    n = int(lines[0][0])
    class Node:
        __slots__ = ("leaf", "keys", "ch")
        def __init__(self, leaf=True):
            self.leaf = leaf; self.keys = []; self.ch = []
    root = Node(True)
    def split(p, idx):
        c = p.ch[idx]; r = Node(c.leaf)
        mid = c.keys[1]; r.keys = c.keys[2:]; c.keys = c.keys[:1]
        if not c.leaf:
            r.ch = c.ch[2:]; c.ch = c.ch[:2]
        p.keys.insert(idx, mid); p.ch.insert(idx + 1, r)
    def has(node, k):
        while True:
            i = 0
            while i < len(node.keys) and k > node.keys[i]: i += 1
            if i < len(node.keys) and node.keys[i] == k: return True
            if node.leaf: return False
            node = node.ch[i]
    def ins(node, k):
        while not node.leaf:
            i = len(node.keys) - 1
            while i >= 0 and node.keys[i] > k: i -= 1
            ci = i + 1
            if len(node.ch[ci].keys) == 3:
                split(node, ci)
                if k > node.keys[ci]: ci += 1
            node = node.ch[ci]
        i = len(node.keys) - 1
        while i >= 0 and node.keys[i] > k: i -= 1
        node.keys.insert(i + 1, k)
    def ht(node):
        h = 1
        while not node.leaf: h += 1; node = node.ch[0]
        return h
    out = []
    for l in lines[1:1 + n]:
        op = l[0]
        if op == "PUT":
            k = int(l[1])
            if has(root, k):
                out.append("DUP")
                continue
            if len(root.keys) == 3:
                s = Node(False); s.ch.append(root); split(s, 0); root = s
            ins(root, k)
            out.append(f"OK:H{ht(root)}")
        elif op == "GET":
            out.append("HIT" if has(root, int(l[1])) else "MISS")
        else:
            lo, hi = int(l[1]), int(l[2])
            acc = []
            def walk(nd):
                for idx, kv in enumerate(nd.keys):
                    if not nd.leaf and kv >= lo: walk(nd.ch[idx])
                    if lo <= kv <= hi: acc.append(str(kv))
                if not nd.leaf and (not nd.keys or nd.keys[-1] <= hi): walk(nd.ch[len(nd.keys)])
            # Safe full range pruning:
            acc = []
            def walk_rng(nd):
                for idx, kv in enumerate(nd.keys):
                    if not nd.leaf and lo < kv: walk_rng(nd.ch[idx])
                    if lo <= kv <= hi: acc.append(str(kv))
                if not nd.leaf and hi > nd.keys[-1]: walk_rng(nd.ch[len(nd.keys)])
            if root.keys or not root.leaf:
                walk_rng(root)
            out.append(",".join(acc) if acc else "EMPTY")
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))
