import sys
from bisect import bisect_left

lines = [l.split() for l in sys.stdin.read().splitlines() if l.strip()]
if lines:
    def fnv1a(s):
        h = 2166136261
        for ch in s:
            h ^= ord(ch)
            h = (h * 16777619) & 0xFFFFFFFF
        return h

    n = int(lines[0][0])
    ring = []
    hashes = []
    out = []
    for l in lines[1:1 + n]:
        op = l[0]
        if op == "ADD":
            nid, w = l[1], int(l[2])
            for i in range(w):
                vn = f"{nid}#{i}"
                ring.append((fnv1a(vn), vn, nid))
            ring.sort()
            hashes = [x[0] for x in ring]
        elif op == "REM":
            nid = l[1]
            ring = [x for x in ring if x[2] != nid]
            hashes = [x[0] for x in ring]
        elif op == "PUT":
            if not ring:
                out.append("EMPTY")
            else:
                idx = bisect_left(hashes, fnv1a(l[1]))
                if idx == len(ring):
                    idx = 0
                out.append(ring[idx][2])
        else:
            key, reps = l[1], int(l[2])
            if not ring:
                out.append("EMPTY")
            else:
                start = bisect_left(hashes, fnv1a(key))
                if start == len(ring):
                    start = 0
                picked, seen = [], set()
                for step in range(len(ring)):
                    nid = ring[(start + step) % len(ring)][2]
                    if nid not in seen:
                        seen.add(nid)
                        picked.append(nid)
                        if len(picked) == reps:
                            break
                out.append(",".join(picked))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))
