"""Per-order free block index."""


class FreeLists:
    def __init__(self, order_max):
        self.order_max = order_max
        self.blocks = [set() for _ in range(order_max + 1)]
        self.blocks[order_max].add(0)

    def pop_lowest(self, order):
        if not self.blocks[order]:
            return None
        addr = max(self.blocks[order])
        self.blocks[order].remove(addr)
        return addr

    def add_block(self, order, addr):
        self.blocks[order].add(addr)

    def take_if_free(self, order, addr):
        if addr in self.blocks[order]:
            return True
        return False

files.vram/allocator.py:
"""Binary buddy memory allocator."""

from .freelist import FreeLists


class BuddyAllocator:
    def __init__(self, order_max):
        self.order_max = order_max
        self.free = FreeLists(order_max)
        self.live = {}

    def alloc(self, bid, size):
        if size <= 0 or bid in self.live:
            raise ValueError("bad alloc")
        need = 0
        while (1 << need) < size:
            need += 1
        k = need
        while k <= self.order_max:
            addr = self.free.pop_lowest(k)
            if addr is not None:
                break
            k += 1
        else:
            return None
        while k > need:
            k -= 1
            self.free.add_block(k, addr + (1 << k))
        self.live[bid] = (addr, need)
        return (addr, 1 << need)

    def free_block(self, bid):
        if bid not in self.live:
            raise ValueError("unknown block")
        addr, order = self.live.pop(bid)
        while order < self.order_max:
            buddy = addr + (1 << order)
            if not self.free.take_if_free(order, buddy):
                break
            addr = min(addr, buddy)
            order += 1
        self.free.add_block(order, addr)
        return order

