"""Proactive-split order-4 B-Tree."""

from .node import BNode, split_child


class BTree:
    def __init__(self):
        self.root = BNode(True)

    def contains(self, key):
        node = self.root
        while True:
            i = 0
            while i < len(node.keys) and key > node.keys[i]:
                i += 1
            if i < len(node.keys) and node.keys[i] == key:
                return True
            if node.leaf:
                return False
            node = node.children[i]

    def put(self, key):
        if self.contains(key):
            return False
        if len(self.root.keys) > 3:
            new_root = BNode(False)
            new_root.children.append(self.root)
            split_child(new_root, 0)
            self.root = new_root
        self._insert_nonfull(self.root, key)
        return True

    def _insert_nonfull(self, node, key):
        i = len(node.keys) - 1
        if node.leaf:
            while i >= 0 and node.keys[i] > key:
                i -= 1
            node.keys.insert(i + 1, key)
            return
        while i >= 0 and node.keys[i] > key:
            i -= 1
        ci = i + 1
        if len(node.children[ci].keys) == 3:
            split_child(node, ci)
        self._insert_nonfull(node.children[ci], key)

    def range_query(self, lo, hi):
        acc = []
        def walk(n):
            for idx, kv in enumerate(n.keys):
                if not n.leaf:
                    walk(n.children[idx])
                if lo <= kv <= hi:
                    acc.append(kv)
            if not n.leaf:
                walk(n.children[len(n.keys)])
        walk(self.root)
        return acc

