"""Hierarchical two-level QoS shaper."""

from .bucket import TokenBucket


class QosShaper:
    def __init__(self, root_rate, root_burst, classes):
        self.root = TokenBucket(root_rate, root_burst)
        self.classes = {c["id"]: TokenBucket(c["rate"], c["burst"]) for c in classes}

    def tick(self, dt):
        self.root.refill(dt)
        for b in self.classes.values():
            b.refill(dt)

    def send(self, class_id, num_bytes):
        cls = self.classes[class_id]
        if cls.tokens >= num_bytes:
            cls.tokens -= num_bytes
            return f"PASS:{class_id}"
        if cls.tokens + self.root.tokens >= num_bytes:
            borrow = num_bytes
            cls.tokens -= num_bytes
            self.root.tokens -= borrow
            return f"BORROW:{class_id}:{borrow}"
        return f"DROP:{class_id}"

