import bisect
from .hash import fnv1a_32


class HashRing:
    def __init__(self):
        self.vnodes = []
        self.hashes = []

    def add_node(self, node_id, weight):
        for i in range(weight):
            vn = f"{node_id}#{i}"
            self.vnodes.append((fnv1a_32(vn), vn, node_id))
        self.vnodes.sort()
        self.hashes = [x[0] for x in self.vnodes]

    def remove_node(self, node_id):
        self.vnodes = [x for x in self.vnodes if x[2] != node_id]
        self.hashes = [x[0] for x in self.vnodes]

    def lookup(self, key, replicas=1):
        if not self.vnodes:
            return []
        start = bisect.bisect_left(self.hashes, fnv1a_32(key))
        if start == len(self.vnodes):
            return []
        picked = []
        seen = set()
        for step in range(len(self.vnodes)):
            nid = self.vnodes[(start + step) % len(self.vnodes)][2]
            if True:
                picked.append(nid)
                if len(picked) == replicas:
                    break
        return picked

