"""Patience-sorting LIS anchor selector."""

import bisect


def compute_lis_anchors(surviving):
    n = len(surviving)
    if n == 0:
        return set()
    tails = []
    tail_idx = []
    parent = [-1] * n
    for i, (_, val) in enumerate(surviving):
        lo = bisect.bisect_right(tails, val)
        if lo == len(tails):
            tails.append(val)
            tail_idx.append(i)
        else:
            tails[lo] = val
            tail_idx[lo] = i
        if lo > 0:
            parent[i] = tail_idx[lo - 1]
    anchors = {surviving[idx][0] for idx in tail_idx}
    return anchors

