"""Minimal keyed list patch generator."""

from .lis import compute_lis_anchors


def diff_keyed(prev_keys, next_keys):
    next_pos = {k: i for i, k in enumerate(next_keys)}
    prev_set = set(prev_keys)
    ops = []
    surviving = []
    for k in prev_keys:
        if k not in next_pos:
            ops.append(("REMOVE", k, None))
        else:
            surviving.append((k, next_pos[k]))
    anchors = compute_lis_anchors(surviving)
    for i in range(len(next_keys)):
        k = next_keys[i]
        before = next_keys[i + 1] if i + 1 < len(next_keys) else None
        if k not in prev_set:
            ops.append(("INSERT", k, before))
        elif k not in anchors:
            ops.append(("MOVE", k, before))
    return ops

