files.tpc/coordinator.py:
"""Two-phase commit coordinator state machine."""

from .wal import decide_outcome


class Coordinator:
    def __init__(self):
        self.txs = {}

    def prepare(self, tx, participants, votes):
        if tx in self.txs:
            raise ValueError("duplicate tx")
        phase = decide_outcome(participants, votes)
        self.txs[tx] = {"phase": phase, "parts": list(participants), "acked": set(), "crashed": False}
        return f"{'DECIDE_COMMIT' if phase == 'COMMITTED' else 'DECIDE_ABORT'}:{tx}"

    def crash(self, tx):
        self.txs[tx]["crashed"] = True
        return f"CRASHED:{tx}"

    def recover(self, tx):
        t = self.txs[tx]
        t["crashed"] = False
        pending = sorted(t["parts"])
        return f"REPLAY:{tx}:{t['phase']}:{','.join(pending)}"

    def ack(self, tx, participant):
        t = self.txs[tx]
        if participant not in t["parts"]:
            raise ValueError("bad ack")
        t["acked"].add(participant)
        if len(t["acked"]) == len(t["parts"]):
            return f"DONE:{tx}:{t['phase']}"
        return f"ACKED:{tx}:{participant}"

