"""Forward pass for earliest start/finish."""


def forward_pass(n, dur, rev, topo):
    es = [0] * n
    ef = [0] * n
    for u in topo:
        if rev[u]:
            es[u] = min(ef[p] for p in rev[u])
        ef[u] = es[u] + dur[u]
    return es, ef

