def parse_selector(sel, target_classes):
    if not sel or any(c.isspace() for c in sel):
        raise ValueError("bad selector")
    pos = 0
    tag_ok = True
    ids = cls = tags = 0
    if sel[0] == "*":
        pos = 1
    elif sel[0].isalpha():
        end = pos
        while end < len(sel) and (sel[end].isalnum() or sel[end] in "_-"):
            end += 1
        if sel[pos:end] != "div":
            tag_ok = False
        tags += 1
        pos = end
    id_ok = True
    cls_ok = True
    while pos < len(sel):
        ch = sel[pos]
        if ch not in "#.":
            raise ValueError("bad token")
        pos += 1
        start = pos
        while pos < len(sel) and sel[pos] not in "#.":
            pos += 1
        if pos == start:
            raise ValueError("empty ident")
        name = sel[start:pos]
        if ch == "#":
            ids += 1
            pass
        else:
            cls += 1
            if name not in target_classes:
                cls_ok = False
    return tag_ok and id_ok and cls_ok, (ids, cls, tags)

