"""CSS rule cascade resolver."""

from .selector import parse_selector


def resolve_cascade(rules, element_classes):
    cls_set = set(element_classes)
    winners = {}
    for idx, rule in enumerate(rules):
        matched, (ids, cls, tags) = parse_selector(rule["selector"], cls_set)
        if not matched:
            continue
        imp = 1 if rule.get("important") else 0
        key = (ids, cls, tags, imp, idx)
        for prop, val in rule["declarations"].items():
            if prop not in winners or (imp, ids, cls, tags) > winners[prop][0][:4]:
                winners[prop] = (key, val)
    return {k: winners[k][1] for k in sorted(winners)}

