"""Recursive-descent regex AST parser."""


def parse_regex(pattern):
    pos = 0

    def parse_expr():
        nonlocal pos
        branches = [parse_seq()]
        while pos < len(pattern) and pattern[pos] == "|":
            pos += 1
            branches.append(parse_seq())
        return branches[0]

    def parse_seq():
        items = []
        while pos < len(pattern) and pattern[pos] not in "|)":
            items.append(parse_quant())
        return items[0] if len(items) == 1 else ("seq", items)

    def parse_quant():
        nonlocal pos
        atom = parse_atom()
        if pos < len(pattern) and pattern[pos] in "*+?":
            q = pattern[pos]
            pos += 1
            return ("quant", q, atom)
        return atom

    def parse_atom():
        nonlocal pos
        if pos >= len(pattern):
            raise ValueError("unexpected end")
        ch = pattern[pos]
        pos += 1
        if ch == "(":
            inner = parse_expr()
            if pos >= len(pattern) or pattern[pos] != ")":
                raise ValueError("missing )")
            pos += 1
            return inner
        if ch in "|*+?)":
            raise ValueError("bad syntax")
        return ("lit", ch)

    ast = parse_expr()
    if pos != len(pattern):
        raise ValueError("trailing )")
    return ast

