"""Non-backtracking NFA state-set matcher."""

from .parser import parse_regex


def match_full(pattern, text):
    ast = parse_regex(pattern)

    def step(node, idxs):
        kind = node[0]
        if kind == "lit":
            ch = node[1]
            return {i + 1 for i in idxs if i < len(text) and ch == text[i]}
        if kind == "seq":
            cur = idxs
            for item in node[1]:
                cur = step(item, cur)
                if not cur:
                    break
            return cur
        if kind == "alt":
            nxt = set()
            for br in node[1]:
                nxt |= step(br, idxs)
            return nxt
        q, sub = node[1], node[2]
        if q == "?":
            return set(idxs) | step(sub, idxs)
        res = set()
        frontier = set(idxs)
        res |= frontier
        while frontier:
            nxt = step(sub, frontier) - res
            res |= nxt
            frontier = nxt
        return res

    return len(text) in step(ast, {0})

