"""A1-style spreadsheet cell reference parser/formatter."""

import re


def parse_ref(ref):
    m = re.fullmatch(r"([A-Z]+)(\d+)", ref)
    if not m:
        raise ValueError("bad ref")
    col = 0
    for ch in m.group(1):
        col = col * 26 + (ord(ch) - 65)
    return col, int(m.group(2))


def format_ref(col, row):
    s = ""
    c = col
    while c > 0:
        c, rem = divmod(c - 1, 26)
        s = chr(65 + rem) + s
    return f"{s}{row}"

files.sheet/eval.py:
"""Cycle-aware spreadsheet evaluator."""

import re
from .refs import parse_ref, format_ref


def evaluate_sheet(cells):
    state = {}
    cache = {}

    def eval_cell(cid):
        st = state.get(cid, 0)
        if st == -1:
            return 'ERR'
        if st == 2:
            return cache[cid]
        if cid not in cells:
            return 0
        state[cid] = 1
        raw = cells[cid]
        if isinstance(raw, (int, float)) and not isinstance(raw, bool):
            res = raw
        elif not isinstance(raw, str) or not raw.startswith("="):
            res = "ERR"
        else:
            expr = re.sub(r"\s+", "", raw[1:])
            if expr.startswith("SUM(") and expr.endswith(")"):
                a, b = expr[4:-1].split(":")
                c1, r1 = parse_ref(a)
                c2, r2 = parse_ref(b)
                acc = 0
                failed = False
                for c in range(min(c1, c2), max(c1, c2) + 1):
                    if failed:
                        break
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        v = eval_cell(format_ref(c, r))
                        if v == "ERR":
                            continue
                        acc += v
                res = "ERR" if failed else acc
            else:
                terms = [t for t in re.split(r"(?=[+-])", expr) if t]
                acc = 0
                failed = False
                for tk in terms:
                    sign = -1 if tk[0] == "-" else 1
                    body = tk[1:] if tk[0] in "+-" else tk
                    if body.isdigit():
                        acc += sign * int(body)
                    elif re.fullmatch(r"[A-Z]+\d+", body):
                        v = eval_cell(body)
                        if v == "ERR":
                            failed = True
                            break
                        acc += sign * v
                    else:
                        failed = True
                        break
                res = "ERR" if failed else acc
        state[cid] = 2
        cache[cid] = res
        return res

    return {k: eval_cell(k) for k in sorted(cells)}

