"""Minimum-cost chunk partitioning DP."""

from .prefix import build_prefix


def min_padding_cost(record_sizes, max_len, overhead):
    if max_len < 1 or overhead < 0:
        raise ValueError("bad args")
    n = len(record_sizes)
    pref = build_prefix(record_sizes)
    dp = [10**18] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        mx = 0
        start = 1
        for j in range(i, start - 1, -1):
            if record_sizes[j - 1] > mx:
                mx = record_sizes[j - 1]
            pad = mx * (i - j) - (pref[i] - pref[j - 1])
            cand = dp[j - 1] + overhead + pad
            if cand < dp[i]:
                dp[i] = cand
    return dp[n]
